# ========== S14f part 2 - merged from test_s14f_p2_clauses.py ==========

# ══════════════════════════════════════════════════════════════════════════
# S14E-23 and S14E-28 — what a clause does, and who pays whom
# ══════════════════════════════════════════════════════════════════════════
# Pre-Deploy S14f part 2 (October 25, 2026; `docs/BUG_FIXES.md` §S14E,
# DD-B re-measure, October 24, 2026).
#
# S14E-23 (diplomacy-first #1): "An Open Borders letter never says what open
# borders does." Reproduced on the shipped 1805 board: Saxony's friendly_gift
# at relation < 0 is rewritten to an `open_borders` letter with a `gold_lump`
# sweetener (`ai_diplomacy._build_proposal_terms`); the letter's clause lines
# read ['Proposal: Open Borders Agreement', 'Clause: Open borders',
# 'Offer: Gold payment - 90'] - the clause repeats the head and names no
# effect, the header is the bare "Open Borders Agreement" (the "(free military
# passage)" summary lived on the OUTGOING road only), and the movement rule and
# the trade the state yields (`OPEN_MOVEMENT_STATES`, `trade_for_state`) are
# named on no surface.
# The fix: `display_names.clause_effect_words` builds the effect from those
# constants ("each side's armies may cross the other's provinces; up to +100
# gold a turn in trade") and `_proposal_term_lines` appends it to the clause
# line - one change that reaches the popup, the letter-book's Terms row, the
# dialogue text and the player's own draft; the payload carries
# `proposal_type_summary` and the incoming popup's "Proposes:" line prints it.
#
# S14E-28 (the sea #2): "A court's letter says 'Offer: Gold payment - 82'
# without who pays whom, and the signing never mentions the sum." Reproduced on
# the same board: the line read "Offer: Gold payment - 90" (the AI's own drafts
# say "France offers N gold (lump sum)" - the same word in the opposite
# direction), and accepting the letter answered "You have accepted Saxony's
# proposal. Treaty signed: Peace -> Open Borders with Saxony." - 90 gold had
# moved into the treasury and nothing said so.
# The fix: `_proposal_term_lines(terms, viewer=, proposer=, target=, name_of=)`
# reads the letter's chair ("Saxony pays you 90 gold at the signing" / "You pay
# Saxony 100 gold a turn for as long as the treaty stands" / "Prussia cedes
# Hanover to you"); `_ratify_player_events` stamps `receipt_lines` from what
# `_ratify_one_time_clauses` APPLIED (`display_names.treaty_receipt_lines`) and
# both accept handlers (and the player-proposed return) append it.

_R23_SCENARIO = (Path(__file__).resolve().parents[1] / "godot-client" / "project-sovereign"
                 / "assets" / "maps" / "europe_1805.json")
_R23_POPUP_GD = (Path(__file__).resolve().parents[1] / "godot-client" / "project-sovereign"
                 / "scripts" / "incoming_proposal_popup.gd")


def _r23_quiet():
    return contextlib.redirect_stdout(io.StringIO())


@pytest.fixture(scope="module")
def _r23_boot():
    from backend.models.world_state import WorldState
    with _r23_quiet():
        return WorldState.from_scenario(str(_R23_SCENARIO))


@pytest.fixture
def _r23_w(_r23_boot):
    """The shipped board, Saxony cool to France (relation -10) and flush."""
    from backend.models.world_state import WorldState
    with _r23_quiet():
        w = WorldState.from_dict(json.loads(json.dumps(_r23_boot.to_dict(), default=str)))
    w.nation_relations[w._make_diplo_key("Saxony", "France")] = -10
    w.nation_gold["Saxony"] = 900
    return w


def _r23_gift_terms(w, nation="Saxony"):
    """The friendly_gift letter's terms as the AI builds them: at relation < 0
    an open_borders proposal with a gold_lump sweetener."""
    from backend.game_logic.ai_diplomacy import _build_proposal_terms
    return _build_proposal_terms(nation, "friendly_gift", 0, w)


def _r23_letter(w, terms, nation="Saxony", label="friendly_gift"):
    from backend.game_logic.ai_diplomacy import build_ai_proposal_dialogue
    with _r23_quiet():
        return build_ai_proposal_dialogue({
            "source": nation, "terms": terms, "proposal_type": label,
            "talleyrand_assessment": "", "decision_reason": "friendly"}, w)


def _r23_accept(w, dialogue):
    from backend.commands.executor import CommandExecutor
    w.dialogue_manager.push(dialogue)
    with _r23_quiet():
        return CommandExecutor()._diplomatic._handle_accept_ai_proposal(dialogue, w)


def _r23_trade() -> int:
    from backend.game_logic.diplomacy import trade_for_state
    return int(trade_for_state("OPEN_BORDERS"))


class TestS14E23:
    """⟨SF step=pre-deploy S14f part 2 · S14E-23 · pillar=diplomacy⟩ An open
    borders letter says what open borders does. Reproduced: see the module
    header - the clause line was the bare "Clause: Open borders"."""

    def test_the_gift_letter_is_an_open_borders_letter_on_the_shipped_board(self, _r23_w):
        terms = _r23_gift_terms(_r23_w)
        assert terms["type"] == "open_borders" and terms["clauses"] == ["open_borders"]
        assert terms["sweeteners"] == [{"type": "gold_lump", "value": 90}]

    def test_the_clause_line_names_the_movement_rule_and_the_trade(self, _r23_w):
        from backend.display_names import build_proposal_popup_clauses
        lines = build_proposal_popup_clauses(_r23_gift_terms(_r23_w))
        clause = next(line for line in lines if line.startswith("Clause: Open borders"))
        assert "each side's armies may cross the other's provinces" in clause, clause
        assert f"+{_r23_trade()} gold a turn in trade" in clause, clause
        assert clause != "Clause: Open borders"          # the reproduction: the bare line

    def test_the_figures_come_from_the_constants_not_the_prose(self, _r23_w, monkeypatch):
        """Change the table and the sentence follows - nothing is hard-coded."""
        from backend.display_names import clause_effect_words
        from backend.game_logic import diplomacy as D
        monkeypatch.setitem(D.TRADE_INCOME, "OPEN_BORDERS", 130)
        assert "+130 gold a turn in trade" in clause_effect_words("open_borders", "open_borders")
        # EA-3's rule rides `trade_for_state`: a zero yields no trade claim at all
        monkeypatch.setitem(D.TRADE_INCOME, "OPEN_BORDERS", 0)
        said = clause_effect_words("open_borders", "open_borders")
        assert "gold a turn" not in said and "cross the other's provinces" in said
        # and the movement rule is the set `can_enter_territory` reads
        monkeypatch.setattr(D, "OPEN_MOVEMENT_STATES", frozenset({"ALLIANCE"}))
        monkeypatch.setitem(D.TRADE_INCOME, "OPEN_BORDERS", 100)
        said = clause_effect_words("open_borders", "open_borders")
        assert "cross" not in said and "+100 gold a turn in trade" in said

    def test_a_pact_letter_makes_no_trade_claim_its_own_state_sets(self):
        """The clause rides a pact or an alliance inside a state that sets its
        own trade (150 / 200): the line says the crossing, never a figure that
        the treaty would then contradict."""
        from backend.display_names import build_proposal_popup_clauses
        for ptype in ("non_aggression", "defensive_alliance", "alliance", "NON_AGGRESSION"):
            lines = build_proposal_popup_clauses(
                {"type": ptype, "clauses": ["open_borders"], "sweeteners": [], "demands": []})
            clause = next(line for line in lines if line.startswith("Clause: Open borders"))
            assert "cross the other's provinces" in clause, (ptype, clause)
            assert "gold a turn" not in clause, (ptype, clause)

    def test_the_incoming_payload_carries_the_summary_and_the_bare_name(self, _r23_w):
        from backend.game_logic.mailbox_payloads import build_pending_envoy_popup_from_terms
        terms = _r23_gift_terms(_r23_w)
        with _r23_quiet():
            popup = build_pending_envoy_popup_from_terms(
                _r23_w, nation="Saxony", terms=terms, label_type="friendly_gift")
        assert popup["proposal_type_display"] == "Open Borders Agreement"      # unchanged
        # S14E-X169 FLIPPED: the header also names the break price (was the bare summary)
        assert popup["proposal_type_summary"].startswith(
            "Open Borders Agreement (free military passage) - breaking it costs 1 DP")
        assert any("cross the other's provinces" in line for line in popup["clauses"])

    def test_the_summary_is_kept_off_the_letters_that_have_their_own_explanation(self, _r23_w):
        from backend.game_logic.mailbox_payloads import _incoming_type_summary
        # S14E-X169 FLIPPED: the open-borders header also names the break price
        # (its trade rides the clause line); was the bare summary
        assert _incoming_type_summary({"type": "open_borders"}).startswith(
            "Open Borders Agreement (free military passage) - breaking it costs 1 DP, -30 relation")
        # S14E-X95 FLIPPED: a pact letter's header also says what its state
        # yields and what breaking it costs (was the bare summary)
        assert _incoming_type_summary({"type": "non_aggression"}).startswith(
            "Non-Aggression Pact (agree not to attack) - up to +")
        # a counter reads "In response to your <bare name> proposal"
        assert _incoming_type_summary({"type": "open_borders"}, is_counter_offer=True) == ""
        # a dictated peace's title carries its tier; peace-class letters carry a war preview
        assert _incoming_type_summary({"type": "peace"}, label_type="harsh_peace") == ""
        for ptype in ("peace", "armistice", "armistice_losing", "armistice_stalemate"):
            assert _incoming_type_summary({"type": ptype}) == ""
        # a type the table gives no summary of keeps the bare name
        assert _incoming_type_summary({"type": "vassalage"}) == ""
        assert _incoming_type_summary({}) == ""

    def test_the_letter_book_row_reaches_the_effect(self, _r23_w):
        """`envoy_digest._digest_row` projects the payload's own clauses - the
        change in `display_names` is the whole change."""
        from backend.game_logic.envoy_digest import _digest_row
        letter = _r23_letter(_r23_w, _r23_gift_terms(_r23_w))
        row = _digest_row(letter, _r23_w, is_active=True)
        text = " · ".join(row["clauses"])
        assert "each side's armies may cross the other's provinces" in text
        assert "Saxony pays you 90 gold at the signing" in text

    def test_the_popup_header_prints_the_summary(self):
        gd = _R23_POPUP_GD.read_text(encoding="utf-8")
        assert 'data.get("proposal_type_summary", "")' in gd
        line = next(ln for ln in gd.splitlines() if "[b]Proposes:[/b]" in ln)
        assert "type_summary if type_summary != \"\" else type_display" in line, line

    def test_the_dialogue_text_and_the_players_own_draft_say_it_too(self):
        """The sibling surfaces of the same clause (S14E-X93): the typed
        terminal's dialogue text and the confirm popup of the player's draft."""
        from backend.display_names import format_proposal_summary, format_terms_for_display
        terms = {"type": "open_borders", "proposer_nation": "Saxony", "target_nation": "France",
                 "clauses": ["open_borders"], "sweeteners": [], "demands": []}
        assert any("cross the other's provinces" in ln
                   for ln in format_proposal_summary(terms).splitlines() if "Open borders" in ln)
        draft = format_terms_for_display(
            {"type": "open_borders", "clauses": ["open_borders"], "sweeteners": [], "demands": []},
            "open_borders", "Saxony")
        line = next(ln for ln in draft if ln.startswith("Open borders included"))
        assert "cross the other's provinces" in line and "gold a turn in trade" in line

    def test_the_struck_clause_line_and_other_clauses_are_untouched(self):
        """Sweep guard: only the open_borders clause gains an effect; every
        other clause keeps its line, and a struck clause keeps its words."""
        from backend.display_names import (
            CLAUSE_TYPE_DISPLAY, clause_effect_words, counter_struck_lines)
        explained = [k for k in CLAUSE_TYPE_DISPLAY if clause_effect_words(k)]
        # S14E-X94 FLIPPED: the protection pledge names its effect too (was
        # open_borders alone)
        assert explained == ["open_borders", "protection_promised"], explained
        assert counter_struck_lines(
            {"type": "alliance", "clauses": ["open_borders"]}, {"type": "alliance"}) == [
            "Struck clause: Open borders"]


# ──────────────────────────────────────────────────────────────────────────
# S14E-28 — who pays whom, and the receipt
# ──────────────────────────────────────────────────────────────────────────

def _r28_terms(*, sweeteners=(), demands=(), clauses=(), ptype="open_borders",
               proposer="Saxony", target="France"):
    return {"type": ptype, "proposer_nation": proposer, "target_nation": target,
            "sweeteners": list(sweeteners), "demands": list(demands), "clauses": list(clauses)}


def _r28_lines(terms, **reader):
    from backend.display_names import _proposal_term_lines
    return _proposal_term_lines(terms, viewer="France", **reader)


def _r28_sum(text: str) -> int:
    """The gold figures a receipt names ("... 90 gold ...") - the first number
    before the word gold."""
    return int(re.search(r"([\d,]+) gold", text).group(1).replace(",", ""))


class TestS14E28:
    """⟨SF step=pre-deploy S14f part 2 · S14E-28 · pillar=diplomacy⟩ A court's
    gold says who pays whom and when, and the signing says what was applied.
    Reproduced: see the module header - "Offer: Gold payment - 90" and a
    confirmation that never mentioned the 90 gold."""

    # ── the words ────────────────────────────────────────────────────────

    def test_the_gift_letter_says_the_court_pays_you_at_the_signing(self, _r23_w):
        letter = _r23_letter(_r23_w, _r23_gift_terms(_r23_w))
        clauses = letter["popup_payload"]["clauses"]
        assert "Saxony pays you 90 gold at the signing" in clauses, clauses
        assert not any("Gold payment" in c for c in clauses), clauses    # the reproduction's line

    def test_a_demand_says_you_pay(self):
        terms = _r28_terms(demands=[{"type": "gold_lump", "value": 2400}])
        assert _r28_lines(terms) == ["You pay Saxony 2,400 gold at the signing"]

    def test_the_per_turn_variants_name_the_stream_and_its_term(self):
        sweet = _r28_terms(sweeteners=[{"type": "gold_per_turn", "value": 40, "turns": 5}])
        assert _r28_lines(sweet) == ["Saxony pays you 40 gold a turn for 5 turns"]
        open_ended = _r28_terms(demands=[{"type": "gold_per_turn", "value": 100}])
        assert _r28_lines(open_ended) == [
            "You pay Saxony 100 gold a turn for as long as the treaty stands"]
        one = _r28_terms(demands=[{"type": "gold_per_turn", "value": 30, "turns": 1}])
        assert _r28_lines(one) == ["You pay Saxony 30 gold a turn for 1 turn"]

    def test_a_province_says_who_cedes_it_to_whom(self):
        terms = _r28_terms(
            demands=[{"type": "territory_cede", "value": 1, "regions": ["Hanover"]}],
            sweeteners=[{"type": "territory_cede", "value": 1, "regions": ["Saxony"]}],
            proposer="Prussia")
        assert _r28_lines(terms) == ["You cede Hanover to Prussia", "Prussia cedes Saxony to you"]

    def test_the_court_is_named_with_its_article_and_by_its_formed_name(self):
        terms = _r28_terms(sweeteners=[{"type": "gold_lump", "value": 50}],
                           demands=[{"type": "gold_lump", "value": 20}], proposer="Ottoman")
        assert _r28_lines(terms) == [
            "You pay the Ottoman Empire 20 gold at the signing",
            "The Ottoman Empire pays you 50 gold at the signing"]
        named = _r28_lines(terms, name_of=lambda n: "Sublime Porte" if n == "Ottoman" else n)
        assert named[1] == "Sublime Porte pays you 50 gold at the signing"

    def test_the_letters_own_proposer_wins_over_the_callers(self):
        """A counter keeps the player as proposer: the same sweetener is then
        what YOU pay. The ratifier reads `proposer_nation` the same way."""
        terms = _r28_terms(sweeteners=[{"type": "gold_lump", "value": 60}],
                           proposer="France", target="Saxony")
        assert _r28_lines(terms, proposer="Saxony", target="France") == [
            "You pay Saxony 60 gold at the signing"]
        # no proposer/target on the terms: the caller's chair stands in
        bare = {"type": "open_borders", "sweeteners": [{"type": "gold_lump", "value": 60}]}
        assert _r28_lines(bare, proposer="Saxony", target="France") == [
            "Saxony pays you 60 gold at the signing"]

    def test_no_viewer_and_a_term_it_does_not_read_keep_their_old_lines(self):
        """Every pre-existing caller stays valid: without a viewer the lines are
        what they always were; only gold and soil terms are re-worded."""
        from backend.display_names import _proposal_term_lines
        terms = _r28_terms(sweeteners=[{"type": "gold_lump", "value": 90}],
                           demands=[{"type": "ap_per_turn", "value": 1}])
        assert _proposal_term_lines(terms) == [
            "Demand: Action point concession - 1 for as long as the treaty stands",
            "Offer: Gold payment - 90"]
        assert _r28_lines(terms)[0].startswith("Demand: Action point concession")
        # an empty or zero sum is never "pays you 0 gold"
        zero = _r28_terms(sweeteners=[{"type": "gold_lump", "value": 0}])
        assert _r28_lines(zero) == ["Offer: Gold payment - 0"]

    def test_the_struck_lines_of_a_counter_keep_their_words(self):
        """S14D-X13's struck lines are a diff of the draft, not a letter's terms."""
        from backend.display_names import counter_offer_clause_lines
        original = _r28_terms(sweeteners=[{"type": "gold_lump", "value": 50}], proposer="France",
                              target="Saxony", ptype="alliance")
        counter = _r28_terms(ptype="alliance", proposer="France", target="Saxony")
        assert counter_offer_clause_lines(original, counter, viewer="France") == [
            "Proposal: Full Alliance", "Struck offer: Gold payment - 50"]
        kept = counter_offer_clause_lines(original, original, viewer="France")
        assert kept == ["You pay Saxony 50 gold at the signing"]

    # ── the sweep: the other letters that carry a sum ───────────────────

    def test_sell_neutrality_says_the_court_pays_you(self, _r23_w):
        from backend.game_logic.ai_diplomacy import _build_proposal_terms
        from backend.game_logic.settlement_helpers import ensure_war_instance_for_pair
        w = _r23_w
        with _r23_quiet():
            ensure_war_instance_for_pair(w, "Prussia", "Austria", entry_path="r28_test")
        key = w._make_diplo_key("Prussia", "Austria")
        w.diplomatic_states[key] = "WAR"
        w.invalidate_bloc_members_cache()
        w.nation_gold["Prussia"] = 2000
        terms = _build_proposal_terms("Prussia", "sell_neutrality", 0, w)
        assert terms["compact"] == "sell_neutrality"
        sum_ = terms["sweeteners"][0]["value"]
        letter = _r23_letter(w, terms, nation="Prussia", label="sell_neutrality")
        clauses = letter["popup_payload"]["clauses"]
        assert f"Prussia pays you {sum_:,} gold at the signing" in clauses, clauses
        assert any(c.startswith("Clause: ") and "France stays OUT" in c for c in clauses)
        assert not any("Gold payment" in c for c in clauses)

    def test_design_purchase_names_the_province_and_the_price_each_way(self, _r23_w):
        """The builder's shape (`ai_diplomacy._build_proposal_terms`'s
        `design_purchase` arm): the court demands the province, pays the sum."""
        terms = _r28_terms(
            ptype="open_borders", proposer="Prussia", clauses=["open_borders"],
            demands=[{"type": "territory_cede", "value": 1, "regions": ["Hanover"]}],
            sweeteners=[{"type": "gold_lump", "value": 2400}])
        letter = _r23_letter(_r23_w, terms, nation="Prussia", label="design_purchase")
        clauses = letter["popup_payload"]["clauses"]
        assert "You cede Hanover to Prussia" in clauses, clauses
        assert "Prussia pays you 2,400 gold at the signing" in clauses, clauses

    def test_the_friendly_gift_row_in_the_letter_book_says_it(self, _r23_w):
        from backend.game_logic.envoy_digest import _digest_row
        row = _digest_row(_r23_letter(_r23_w, _r23_gift_terms(_r23_w)), _r23_w, is_active=False)
        assert row["proposal_type"] == "friendly_gift"
        assert "Saxony pays you 90 gold at the signing" in row["clauses"]

    # ── the receipt: shown == applied ───────────────────────────────────

    def test_accepting_the_gift_answers_with_the_receipt_and_the_treasury_agrees(self, _r23_w):
        w = _r23_w
        letter = _r23_letter(w, _r23_gift_terms(w))
        france, saxony = w.nation_gold["France"], w.nation_gold["Saxony"]
        result = _r23_accept(w, letter)
        assert result["success"] is True, result
        msg = result["message"]
        assert msg.startswith("You have accepted Saxony's proposal. Treaty signed: Peace")
        assert msg.endswith("Saxony paid 90 gold into the treasury."), msg
        # shown == applied: the treasury moved by exactly the receipt's sum
        paid = _r28_sum(msg.split("with Saxony.")[-1])
        assert w.nation_gold["France"] - france == paid == 90
        assert saxony - w.nation_gold["Saxony"] == paid
        # the ratifier's own result carries the lines the handlers append
        assert w.get_diplomatic_state("Saxony", "France") == "OPEN_BORDERS"

    def test_a_lump_the_purse_could_not_meet_is_receipted_at_what_was_applied(self, _r23_w):
        """The ratifier pays `min(amount, available)`: the letter was written
        when Saxony was flush; by the signing it is not. The receipt says so."""
        w = _r23_w
        letter = _r23_letter(w, _r23_gift_terms(w))
        w.nation_gold["Saxony"] = 35
        france = w.nation_gold["France"]
        result = _r23_accept(w, letter)
        msg = result["message"]
        assert "Saxony could pay only 35 of the 90 gold promised" in msg, msg
        assert w.nation_gold["France"] - france == 35
        assert w.nation_gold["Saxony"] == 0

    def test_a_lump_the_court_could_not_pay_at_all_says_none(self, _r23_w):
        w = _r23_w
        letter = _r23_letter(w, _r23_gift_terms(w))
        w.nation_gold["Saxony"] = 0
        france = w.nation_gold["France"]
        msg = _r23_accept(w, letter)["message"]
        assert "Saxony paid none of the 90 gold promised" in msg, msg
        assert w.nation_gold["France"] == france

    def test_a_sum_you_pay_is_receipted_from_the_treasury(self, _r23_w):
        w = _r23_w
        terms = _r28_terms(demands=[{"type": "gold_lump", "value": 50}], clauses=["open_borders"])
        letter = _r23_letter(w, terms, label="friendly_gift")
        w.nation_gold["France"] = 400
        saxony = w.nation_gold["Saxony"]
        msg = _r23_accept(w, letter)["message"]
        assert msg.endswith("You paid Saxony 50 gold from the treasury."), msg
        assert w.nation_gold["France"] == 350 and w.nation_gold["Saxony"] - saxony == 50

    def test_a_province_that_moved_is_receipted(self, _r23_w):
        w = _r23_w
        w.regions["Hanover"].controller = "France"
        w.nation_gold["Prussia"] = 5000
        terms = _r28_terms(
            ptype="open_borders", proposer="Prussia", clauses=["open_borders"],
            demands=[{"type": "territory_cede", "value": 1, "regions": ["Hanover"]}],
            sweeteners=[{"type": "gold_lump", "value": 2400}])
        w.nation_relations[w._make_diplo_key("Prussia", "France")] = 10
        letter = _r23_letter(w, terms, nation="Prussia", label="design_purchase")
        france = w.nation_gold["France"]
        result = _r23_accept(w, letter)
        assert result["success"] is True, result
        msg = result["message"]
        assert "Prussia paid 2,400 gold into the treasury." in msg, msg
        assert "You ceded Hanover to Prussia." in msg, msg
        assert w.regions["Hanover"].controller == "Prussia"
        assert w.nation_gold["France"] - france == 2400

    def test_a_treaty_that_applies_nothing_gets_no_receipt(self, _r23_w):
        w = _r23_w
        terms = _r28_terms(clauses=["open_borders"])
        msg = _r23_accept(w, _r23_letter(w, terms))["message"]
        assert msg == "You have accepted Saxony's proposal. Treaty signed: Peace → Open Borders with Saxony."

    def test_the_counter_road_appends_the_receipt_too(self, _r23_w):
        from backend.commands.diplomatic_executor import DiplomaticExecutor
        w = _r23_w
        counter = _r28_terms(sweeteners=[{"type": "gold_lump", "value": 70}], clauses=["open_borders"])
        dialogue = {
            "type": "counter_offer", "target_nation": "Saxony",
            "context": {"source_nation": "Saxony", "counter_terms": counter,
                        "original_proposal": {"type": "open_borders"}},
        }
        w.dialogue_manager.replace(dialogue)
        france = w.nation_gold["France"]
        with _r23_quiet():
            result = DiplomaticExecutor(None)._process_dialogue_choice(
                "accept_counter_offer", {}, dialogue, w)
        assert result["success"] is True, result
        assert result["message"].endswith("Saxony paid 70 gold into the treasury."), result["message"]
        assert w.nation_gold["France"] - france == 70

    def test_a_peace_keeps_its_own_summary_and_no_second_receipt(self):
        """A peace's ratified-terms summary is its receipt (§11 of the BPH
        spec): `treaty_receipt_text` stays silent beside it."""
        from backend.display_names import treaty_receipt_text
        assert treaty_receipt_text({"receipt_lines": ["Saxony paid 90 gold into the treasury."],
                                    "peace_ratification_summary": {"war_outcome": "stalemate"}}) == ""
        assert treaty_receipt_text(None) == "" and treaty_receipt_text({}) == ""
        assert treaty_receipt_text({"receipt_lines": ["A.", "B."]}) == "A. B."

    def test_the_player_proposed_road_receipts_the_acceptance(self, _r23_w, monkeypatch):
        """The player's own proposal accepted in transit: the popup and the
        treaty event carry what was applied (here, France paying)."""
        w = _r23_w
        w.nation_gold["France"] = 500
        w.current_turn = 4
        w.proposal_in_transit = {
            "turn_sent": 3, "target": "Saxony",
            "proposal": _r28_terms(sweeteners=[{"type": "gold_lump", "value": 80}],
                                   clauses=["open_borders"], proposer="France", target="Saxony"),
        }
        monkeypatch.setattr(
            "backend.game_logic.diplomacy.calculate_acceptance",
            lambda proposal, world, *a, **k: {"score": 90, "outcome": "ACCEPT", "components": {},
                                              "feedback": ""})
        with _r23_quiet():
            events = w._process_proposal_in_transit()
        popup = w.proposal_result_popup
        assert popup and popup["outcome"] == "ACCEPT", popup
        assert popup["message"].endswith("You paid Saxony 80 gold from the treasury."), popup["message"]
        signed = next(e for e in events if e.get("type") == "diplomatic_treaty_signed")
        assert signed["message"].endswith("You paid Saxony 80 gold from the treasury.")
        assert w.nation_gold["France"] == 420

    def test_the_receipt_names_a_cession_the_bilateral_arm_could_not_carry(self):
        from backend.display_names import treaty_receipt_lines
        lines = treaty_receipt_lines([], [], "France",
                                     dropped=["Hanover not carried - Prussia no longer holds it"])
        assert lines == ["Not carried: Hanover not carried - Prussia no longer holds it."]

    def test_a_third_partys_clause_is_not_the_players_receipt(self):
        from backend.display_names import treaty_receipt_lines
        gold = [{"type": "gold_lump", "from": "Austria", "to": "Prussia", "amount": 40}]
        assert treaty_receipt_lines(gold, gold, "France") == []


