# S14E-21
# ──────────────────────────────────────────────────────────────────────────

class TestS14E21:
    """Esc's ladder had a silent rung. The replay took one Esc when settled
    and TWO while the cinematic played (`battle_diorama.gd`'s
    `_unhandled_input` read Esc and Enter/Space as ONE "advance" arm — skip
    when playing, close when settled); on close the command line takes focus
    (`_return_control_to_player`), its own Esc runs DDB-54's ladder, finds
    nothing and silently `release_focus()`s, and the NEXT Esc, unfocused,
    opens the pause menu: four pause menus by accident in the record
    (#69, #263, #388, #444).

    Reproduced (by source, on the shipped client): the ui_cancel arm of the
    diorama's `_unhandled_input` was the SAME arm as ui_accept, ending in
    `if _final: _on_close_pressed() else: _skip_to_final()` — two presses
    while the cinematic plays; and `main.tscn`'s placeholder stayed "Type
    command..." whether the line held focus or not, so the release rung
    showed nothing.

    The fix: Esc closes the replay in ONE press at any moment (Space/Enter and
    the click still skip, then close); the placeholder reads "Esc: menu ·
    click to type" while the open command line is unfocused (an empty line
    shows its placeholder; a disabled line keeps the default — it cannot be
    typed into). DDB-54's ladder (`_escape_closes_topmost`) is untouched and
    its pin stands (tests/test_ddb_s13b_the_client.py::TestDDB54)."""

    def test_esc_closes_the_replay_in_one_press_while_the_cinematic_plays(self):
        body = _r21_func(_r21_src("scripts/battle_diorama.gd"), "_unhandled_input")
        cancel = body.index('is_action_pressed("ui_cancel")')
        accept = body.index('is_action_pressed("ui_accept")')
        assert cancel < accept, "Esc has its own arm, before Space/Enter's"
        esc_arm = body[cancel:accept]
        assert "_on_close_pressed()" in esc_arm
        assert "_skip_to_final()" not in esc_arm, "Esc never merely skips"
        assert "_final" not in esc_arm, "Esc closes whether or not the cinematic is settled"

    def test_esc_and_enter_are_no_longer_one_arm(self):
        body = _r21_func(_r21_src("scripts/battle_diorama.gd"), "_unhandled_input")
        joined = re.search(r'is_action_pressed\("ui_cancel"\)\s*\\?\s*or\s+event\.is_action_pressed\("ui_accept"\)', body)
        assert joined is None, "the old shared arm (skip-when-playing, close-when-settled) is gone"

    def test_space_enter_and_the_click_still_skip_then_close(self):
        src = _r21_src("scripts/battle_diorama.gd")
        body = _r21_func(src, "_unhandled_input")
        accept_arm = body[body.index('is_action_pressed("ui_accept")'):]
        assert "if _final:" in accept_arm and "_on_close_pressed()" in accept_arm
        assert "_skip_to_final()" in accept_arm, "Space still skips the cinematic"
        click = _r21_func(src, "_on_root_input")
        assert "InputEventMouseButton" in click and "_skip_to_final()" in click and "not _final" in click, \
            "the click still skips"

    def test_closing_mid_cinematic_kills_the_sequence_first(self):
        """Esc can now close while the tween plays: the close must kill it
        (no tween bookkeeping left ticking over a hidden tableau) and still
        emit `dismissed` — the one tail that hands the command line back."""
        body = _r21_func(_r21_src("scripts/battle_diorama.gd"), "_on_close_pressed")
        assert body.index("_kill_sequence()") < body.index("hide()") < body.index("dismissed.emit()")

    def test_the_input_is_still_consumed_so_the_pause_menu_cannot_open_beneath(self):
        body = _r21_func(_r21_src("scripts/battle_diorama.gd"), "_unhandled_input")
        cancel = body.index('is_action_pressed("ui_cancel")')
        accept = body.index('is_action_pressed("ui_accept")')
        assert "set_input_as_handled()" in body[cancel:accept]

    def test_the_released_line_says_how_to_get_back(self):
        src = _r21_src()
        assert 'const COMMAND_PLACEHOLDER_RELEASED := "Esc: menu · click to type"' in src
        assert 'const COMMAND_PLACEHOLDER_FOCUSED := "Type command..."' in src
        body = _r21_func(src, "_refresh_command_placeholder")
        assert "command_input.editable" in body and "command_input.has_focus()" in body
        assert "COMMAND_PLACEHOLDER_RELEASED" in body and "COMMAND_PLACEHOLDER_FOCUSED" in body

    def test_the_placeholder_follows_focus_released_and_regained(self):
        src = _r21_src()
        ready = _r21_func(src, "_ready")
        assert "command_input.focus_exited.connect(_refresh_command_placeholder)" in ready
        assert "command_input.focus_entered.connect(_refresh_command_placeholder)" in ready
        assert "_refresh_command_placeholder()" in ready, "set once at wiring (the line starts unfocused)"

    def test_the_placeholder_follows_the_input_gate(self):
        """A line the gate has closed cannot be typed into: it must not claim
        "click to type" — set_input_enabled refreshes AFTER it has taken (or
        refused) focus."""
        body = _r21_func(_r21_src(), "set_input_enabled")
        assert "_refresh_command_placeholder()" in body
        assert body.rindex("_refresh_command_placeholder()") > body.index("command_input.grab_focus()")

    def test_the_scene_default_stays_the_focused_text(self):
        tscn = _r21_src("scenes/main.tscn")
        assert 'placeholder_text = "Type command..."' in tscn

    def test_the_ladder_closes_a_standing_tableau_for_a_line_that_kept_focus(self):
        """A DISABLED line keeps focus under the tableau, and its Esc runs
        the ladder — which would find nothing and silently release (one dead
        press, then the skip, then the close). The ladder's FIRST rung is the
        tableau, so the line's Esc answers like the tableau's own."""
        ladder = _r21_func(_r21_src(), "_escape_closes_topmost")
        rung = ladder.index("battle_diorama.visible")
        assert "battle_diorama._on_close_pressed()" in ladder[rung:rung + 200]
        assert rung < ladder.index("diplomacy_wizard.visible"), "the tableau is the topmost thing"
        assert "return true" in ladder[rung:ladder.index("diplomacy_wizard.visible")]
        assert "battle_diorama and battle_diorama.visible" in ladder, "null-safe: not every harness has one"

    def test_ddb54s_ladder_is_untouched(self):
        """The ruled ladder stands: the line's Esc runs the clear/close
        ladder and releases focus only when nothing is open."""
        src = _r21_src()
        gui = _r21_func(src, "_on_command_input_gui_input")
        assert "_escape_closes_topmost()" in gui and "command_input.release_focus()" in gui
        ladder = _r21_func(src, "_escape_closes_topmost")
        assert "top_bar.close_all_screens()" in ladder and "diplomacy_wizard._close_wizard()" in ladder


