class TestS14E29:
    """The header's Gold line was not refreshed after a letter answered from
    the Envoys panel. `/mailbox/respond` returns the whole base envelope (the
    new treasury, `gold_projected_net`, the action counters, the rail), but
    `_on_mailbox_row_action_result` called only `_update_diplomatic_top_bar`;
    the Gold label, the Actions / Admin counters, the manpower line, the map
    and the notification bar are written by `_sync_response_hud` alone,
    reached from `_on_command_result` and the world swap — the letter-book
    was the one api_client road that bypassed it (its docstring avoids the
    MODAL route table; the HUD sync is not the route table). The header read
    244 while the Admiralty read 326.

    Reproduced (by source): `_sync_response_hud` was not called in
    `_on_mailbox_row_action_result`, only `_update_diplomatic_top_bar`.

    The fix: `_sync_response_hud(response)` replaces the lone top-bar call,
    BEFORE the panel re-fetch (it carries the top-bar sync itself)."""

    def test_the_letter_book_answer_syncs_the_hud(self):
        body = _r29_func(_r29_src(), "_on_mailbox_row_action_result")
        assert "_sync_response_hud(response)" in body

    def test_the_sync_runs_before_the_panel_refetch(self):
        body = _r29_func(_r29_src(), "_on_mailbox_row_action_result")
        assert body.index("_sync_response_hud(response)") < body.index("api_client.get_mailbox(")

    def test_the_sync_reaches_every_outcome_not_only_the_success_arm(self):
        """The old top-bar call was unconditional; the sync keeps that reach
        (a refusal still carries a fresh envelope) and sits above both
        failure arms."""
        body = _r29_func(_r29_src(), "_on_mailbox_row_action_result")
        sync = body.index("_sync_response_hud(response)")
        assert sync < body.index('if not response.get("success", false):')
        assert sync < body.index('response.get("activation_blocked", false)')

    def test_the_top_bar_is_not_synced_twice(self):
        """`_sync_response_hud` already ends in `_update_diplomatic_top_bar`;
        the handler repeating it is the duplication
        tests/test_popup_routing_registry.py forbids on the command road."""
        body = _r29_func(_r29_src(), "_on_mailbox_row_action_result")
        assert "_update_diplomatic_top_bar(" not in body
        assert "_update_diplomatic_top_bar(response)" in _r29_func(_r29_src(), "_sync_response_hud")

    def test_the_modal_route_table_is_still_not_run(self):
        """The handler's reason for being isolated stands: nothing here may
        route a popup UNDER the open panel."""
        body = _r29_func(_r29_src(), "_on_mailbox_row_action_result")
        assert "_on_command_result(" not in body
        assert "_route_response_ui(" not in body

    def test_the_tutor_still_hears_the_answer(self):
        body = _r29_func(_r29_src(), "_on_mailbox_row_action_result")
        assert "tutorial_overlay.observe(response)" in body

    def test_sync_applies_the_treasury_the_counters_and_the_rail(self):
        """What the sync reads off the response is what the handler now
        gets: gold, the projected net, the action summary, the manpower pools,
        the map and the rail."""
        sync = _r29_func(_r29_src(), "_sync_response_hud")
        for needle in ("gold_projected_net", "response.game_state.gold",
                       "_update_status(response.action_summary)",
                       "_apply_manpower(response.game_state.manpower_pools)",
                       "_update_map_from_game_state(response.game_state)",
                       "notification_bar.update_notifications(response.notifications)"):
            assert needle in sync, needle

    def test_the_backend_envelope_carries_what_the_sync_reads(self, _r29_rig):
        """An Accept answered from the letter-book returns the treasury as
        APPLIED (shown == applied), the projected net, the counters and the
        rail — everything `_sync_response_hud` reads."""
        from backend.game_logic.envoy_digest import build_envoy_digest
        M, world, dialogue = _r29_rig
        assert build_envoy_digest(world)["count"] == 1
        world.gold = 244
        result = M.respond_to_mailbox_item(
            M.MailboxRespondRequest(mailbox_id=dialogue["mailbox_id"], choice="accept"))
        assert result["success"] is True
        assert result["game_state"]["gold"] == int(world.gold), "the treasury as applied"
        assert isinstance(result["game_state"]["gold"], int)
        assert isinstance(result["gold_projected_net"], int)
        assert "action_summary" in result and "notifications" in result
        assert "manpower_pools" in result["game_state"]
        assert "map_data" in result["game_state"]

    def test_a_refusal_carries_the_same_envelope(self, _r29_rig):
        M, world, _dialogue = _r29_rig
        result = M.respond_to_mailbox_item(M.MailboxRespondRequest(mailbox_id=9999, choice="accept"))
        assert result["success"] is False
        assert result["game_state"]["gold"] == int(world.gold)
        assert isinstance(result["gold_projected_net"], int)


