def _r30_src(name: str = "main.gd") -> str:
    return (_R30_CLIENT / "scripts" / name).read_text(encoding="utf-8")


def _r30_func(src: str, name: str) -> str:
    start = src.index(f"func {name}(")
    end = src.find("\nfunc ", start + 1)
    return src[start:end if end != -1 else len(src)]


@pytest.fixture(scope="module")
def _r30_boot():
    from backend.models.world_state import WorldState
    with contextlib.redirect_stdout(io.StringIO()):
        return WorldState.from_scenario(str(_R30_SCENARIO))


@pytest.fixture
def _r30_world(_r30_boot):
    from backend.models.world_state import WorldState
    return WorldState.from_dict(json.loads(json.dumps(_r30_boot.to_dict(), default=str)))


def _r30_row(dispatch: dict, name: str) -> dict:
    return next(r for r in dispatch["marshals"] if r["name"] == name)


def _r30_halt_massena(world):
    """The sea road's turn: Massena marching home to Milan halted at Tyrol by
    Archduke John — his order frozen on a pending contact interrupt."""
    from backend.models.marshal import StrategicOrder
    massena = world.get_marshal("Massena")
    massena.location = "Tyrol"
    massena.strategic_order = StrategicOrder(
        command_type="MOVE_TO", target="Milan", target_type="region",
        started_turn=1, original_command="Massena, march to Milan", path=["Milan"])
    assert massena.in_strategic_mode   # a property of the order
    massena.pending_interrupt = {
        "interrupt_type": "contact", "marshal": "Massena", "enemy": "ArchdukeJohn",
        "location": "Tyrol", "options": ["attack", "go_around", "hold_position", "cancel_order"]}
    return massena


def _r30_continue_as_ordered(massena):
    """`/strategic_response` "Continue as Ordered": the question is answered
    and the marshal marches on — to Milan."""
    massena.pending_interrupt = None
    massena.location = "Milan"


class TestS14E30:
    """The Morning Dispatch was shown AFTER the first-step interrupt was
    answered, so it contradicted the answer it was built before. The dispatch
    is built inside `_execute_end_turn` after the advance has raised the
    marshal's interrupt, so his row reads "HALTED at Tyrol — awaiting your
    word"; the client stashed it (`pending_dispatch_data`) and raised the
    interrupt first (`_on_strategic_report_dismissed`); `/strategic_response`
    ran "Continue as Ordered" (Massena to Milan) and returned no new dispatch;
    only then `_process_next_interrupt` → `_show_pending_dispatch()` printed
    the pre-answer snapshot under "Massena arrives at Milan". And
    `last_morning_dispatch` is frozen at turn start by design
    (`_readable_dispatch` re-derived only `unmet_marshals`), so the R re-read
    said HALTED for the whole turn.

    Reproduced (shipped 1805 board): Massena halted at Tyrol on a contact
    interrupt, the boot dispatch stored ("HALTED at Tyrol"), the interrupt
    answered and the man at Milan — `_readable_dispatch(world)` still read
    "HALTED at Tyrol — Archduke John bars the way" with `location` Tyrol.
    On the client side `_show_pending_dispatch()` stood AFTER the
    `_show_interrupt_popup(first_interrupt)` early return in
    `_on_strategic_report_dismissed`.

    The fix: (1) the client shows the stashed dispatch BEFORE the first
    interrupt's popup — the briefing says halted, the question follows, the
    answer follows, in truth order; (2) `_readable_dispatch` re-derives
    MARSHAL STATUS on read, onto a COPY, as it does `unmet_marshals`."""

    # ---- the client order -------------------------------------------------

    def test_the_dispatch_is_shown_before_the_first_interrupt_is_raised(self):
        body = _r30_func(_r30_src(), "_on_strategic_report_dismissed")
        raise_at = body.index("_show_interrupt_popup(first_interrupt)")
        # The call sits inside the same `if not interrupt_queue.is_empty():`
        # block, between the pop and the raise.
        block = body[body.index("if not interrupt_queue.is_empty():"):raise_at]
        assert "_show_pending_dispatch()" in block
        assert block.index("var first_interrupt = interrupt_queue.pop_front()") <             block.index("_show_pending_dispatch()")

    def test_the_interrupt_early_return_still_follows_the_raise(self):
        body = _r30_func(_r30_src(), "_on_strategic_report_dismissed")
        raise_at = body.index("_show_interrupt_popup(first_interrupt)")
        assert body[raise_at:].lstrip().split("\n")[1].strip().startswith("return"), \
            "the input stays closed until the question is answered"

    def test_the_tail_still_shows_the_dispatch_for_the_no_interrupt_road(self):
        """A turn with no question: the dispatch is still the last thing
        printed before the player has control (the existing tail)."""
        body = _r30_func(_r30_src(), "_on_strategic_report_dismissed")
        assert body.count("_show_pending_dispatch()") >= 2
        assert body.rindex("_show_pending_dispatch()") < body.rindex("_return_control_to_player()")

    def test_the_shown_dispatch_is_consumed_so_the_answer_cannot_reprint_it(self):
        body = _r30_func(_r30_src(), "_show_pending_dispatch")
        assert body.index("_display_morning_dispatch(pending_dispatch_data)") < \
            body.index("pending_dispatch_data = null")

    def test_the_post_answer_tail_keeps_its_call_and_its_comment_is_true(self):
        """`_process_next_interrupt` keeps its `_show_pending_dispatch()` (the
        safety net for any road that reaches it with a dispatch unshown —
        it is a no-op after the new first call consumed it), and its comment
        no longer says the dispatch waits for the answers."""
        body = _r30_func(_r30_src(), "_process_next_interrupt")
        assert "_show_pending_dispatch()" in body
        assert "S14E-30" in body
        assert "BEFORE the first interrupt" in body
        assert "no-op" in body

    # ---- the backend: MARSHAL STATUS re-derived on read ---------------------

    def test_the_stored_dispatch_says_halted(self, _r30_world):
        """Control: the briefing built while the question stands is right to
        say HALTED (that is why it is now shown before the question)."""
        from backend.game_logic import dispatch as D
        world = _r30_world
        _r30_halt_massena(world)
        with contextlib.redirect_stdout(io.StringIO()):
            D.build_morning_dispatch(world, boot=True)
        row = _r30_row(world.last_morning_dispatch, "Massena")
        assert row["status"] == "awaiting_decision"
        assert "HALTED at Tyrol" in row["status_note"]

    def test_the_reread_shows_the_marshal_where_he_now_stands(self, _r30_world):
        import backend.main as M
        from backend.game_logic import dispatch as D
        world = _r30_world
        massena = _r30_halt_massena(world)
        with contextlib.redirect_stdout(io.StringIO()):
            D.build_morning_dispatch(world, boot=True)
        _r30_continue_as_ordered(massena)
        row = _r30_row(M._readable_dispatch(world), "Massena")
        assert row["location"] == "Milan"
        assert "HALTED" not in row["status_note"]
        assert row["status"] == "arrived" and "Milan" in row["status_note"]

    def test_the_read_never_mutates_the_stored_dispatch(self, _r30_world):
        import backend.main as M
        from backend.game_logic import dispatch as D
        world = _r30_world
        massena = _r30_halt_massena(world)
        with contextlib.redirect_stdout(io.StringIO()):
            D.build_morning_dispatch(world, boot=True)
        stored_before = json.dumps(world.last_morning_dispatch, sort_keys=True, default=str)
        stored_rows = world.last_morning_dispatch["marshals"]
        _r30_continue_as_ordered(massena)
        got = M._readable_dispatch(world)
        assert got is not world.last_morning_dispatch
        assert got["marshals"] is not stored_rows, "a fresh list, not the store's"
        assert json.dumps(world.last_morning_dispatch, sort_keys=True, default=str) == stored_before
        assert "HALTED at Tyrol" in _r30_row(world.last_morning_dispatch, "Massena")["status_note"]

    def test_the_whole_dispatch_is_still_not_rebuilt_on_a_read(self):
        """UX23-R4's trap stands: a read re-derives PURE halves only (it must
        never call the consuming builder)."""
        src = (Path(__file__).resolve().parents[1] / "backend" / "main.py").read_text(encoding="utf-8")
        body = src[src.index("def _readable_dispatch("):]
        body = body[:body.index("\ndef ")]
        assert "build_morning_dispatch(" not in body
        assert "_build_marshal_status(" in body
        assert "dispatch = dict(dispatch)" in body

    def test_the_other_sections_are_the_stored_ones(self, _r30_world):
        """Only MARSHAL STATUS and unmet marshals are live on a read; the
        headline, the intelligence and the note stay the morning's."""
        import backend.main as M
        from backend.game_logic import dispatch as D
        world = _r30_world
        _r30_halt_massena(world)
        with contextlib.redirect_stdout(io.StringIO()):
            D.build_morning_dispatch(world, boot=True)
        stored = world.last_morning_dispatch
        got = M._readable_dispatch(world)
        for key in ("turn", "intelligence", "turn_events", "berthier_note"):
            assert got.get(key) == stored.get(key), key

    def test_an_unmoved_roster_reads_the_same_rows(self, _r30_world):
        """No drift on a quiet board: re-deriving with nothing changed gives
        the stored rows back (so `/new_game` and `/load` show what the boot
        briefing built)."""
        import backend.main as M
        from backend.game_logic import dispatch as D
        world = _r30_world
        with contextlib.redirect_stdout(io.StringIO()):
            D.build_morning_dispatch(world, boot=True)
        assert M._readable_dispatch(world)["marshals"] == world.last_morning_dispatch["marshals"]

    def test_the_empty_store_still_reads_empty(self, _r30_world):
        import backend.main as M
        _r30_world.last_morning_dispatch = {}
        assert M._readable_dispatch(_r30_world) == {}

