# S14E-16
# ══════════════════════════════════════════════════════════════════════════

class TestS14E16:
    """S14E-16 — "how do I get to Vienna" is a BOARD question misfiled as
    grammar.

    Reproduced (the shipped 1805 board, the real endpoint, the keyless
    parser): "how do I get to Vienna" opened "how do I", so the grammar
    regex took it, the desk's `reach` kind (only "can <marshal> reach …")
    never saw it, and the help executor's `section_for` (no get / go / travel
    / reach word in its table) returned None — the reply was the WHOLE
    22,573-character manual, "COMMAND REFERENCE" at its head, for a four-line
    window. ("how do I march to Vienna" already printed its one section.)

    The fix: a marshal-less `route` board kind ("how do I get / go / travel
    to / reach <province>", "the way / road / route to <province>") answered
    through `nearest_lawful_marcher` and `_answer_reach_by_the_march` — a
    marshal and a road, and the order that takes it; and the movement verbs
    in the `help_topics` table so a place the board does not know still gets
    ONE section, never the whole manual.
    """

    ROUTE_LINES = (
        "how do I get to Vienna",
        "how do I get to Vienna?",
        "how do we get to Vienna?",
        "how can I go to Vienna?",
        "how would I travel to Vienna?",
        "how do I reach Vienna?",
        "what is the way to Vienna?",
        "what's the road to Vienna?",
        "which way to Vienna?",
        "the road to Vienna?",
        "the way to Vienna?",
    )

    def test_the_sighting_no_longer_dumps_the_manual(self, _r16_client):
        reply = _r16_say(_r16_client, "how do I get to Vienna")
        text = str(reply.get("message") or "")
        assert "COMMAND REFERENCE" not in text
        assert len(text) < 800, len(text)
        assert reply.get("success") is True

    @pytest.mark.parametrize("line", ROUTE_LINES)
    def test_every_route_phrasing_is_classified_as_the_route_kind(self, line, _r16_world):
        from backend.ai.question_desk import classify_board_question
        question = classify_board_question(
            line, marshals=list(_r16_world.get_player_marshals() and
                                [m.name for m in _r16_world.get_player_marshals()]),
            enemies=[], regions=list(_r16_world.regions), nations=[])
        assert question is not None and question["kind"] == "route", (line, question)
        assert question["place"] == "Vienna"

    @pytest.mark.parametrize("line", ROUTE_LINES[:8])
    def test_the_answer_names_a_marshal_and_a_road(self, line, _r16_client, _r16_world):
        from backend.commands.strategic import nearest_lawful_marcher
        marshal, road, refusal = nearest_lawful_marcher(_r16_world, "Vienna")
        assert marshal is not None and road, refusal
        reply = _r16_say(_r16_client, line)
        text = str(reply.get("message") or "")
        assert reply.get("success") is True, (line, text[:200])
        assert "COMMAND REFERENCE" not in text
        assert marshal.name in text, text
        assert " -> ".join([marshal.location] + list(road)) in text, text
        # the order that takes the road is quoted, and the game can read it
        order = f"{marshal.name}, march to Vienna"
        assert f"'{order}'" in text, text

    def test_the_quoted_order_is_the_one_the_answer_describes(self, _r16_client, _r16_world):
        """Shown == applied: send the quoted order; the marshal marches and
        the turns the answer quoted are the march's own clock."""
        from backend.commands.strategic import march_turns, nearest_lawful_marcher
        marshal, road, _r = nearest_lawful_marcher(_r16_world, "Vienna")
        text = str(_r16_say(_r16_client, "how do I get to Vienna?").get("message") or "")
        turns = march_turns(len(road), getattr(marshal, "movement_range", 1))
        assert (f"in {turns} turn" in text) if turns else ("this very turn" in text), text
        reply = _r16_say(_r16_client, f"{marshal.name}, march to Vienna")
        assert reply.get("success") is True, reply.get("message")

    def test_an_unknown_place_still_gets_one_section_not_the_manual(self, _r16_client):
        text = str(_r16_say(_r16_client, "how do I get to Narnia?").get("message") or "")
        assert text.startswith("STRATEGIC COMMANDS"), text[:80]
        assert "COMMAND REFERENCE" not in text
        assert len(text) < 3000, len(text)

    def test_section_for_reads_the_movement_verbs(self):
        from backend.ai.help_topics import section_for
        assert section_for("how do I get to Vienna") is not None
        for line in ("how do I get to Vienna", "how do I go to Vienna",
                     "how do I travel", "how do I travel to Vienna",
                     "how do I reach Vienna", "how do I get there",
                     "what is the way to Vienna", "the road to Vienna",
                     "how do I find the route to Vienna"):
            assert section_for(line) == "STRATEGIC COMMANDS", line

    def test_the_movement_words_do_not_steal_the_neighbouring_sections(self):
        from backend.ai.help_topics import section_for
        assert section_for("how do I get more gold") == "ECONOMY"
        assert section_for("how do I get peace with Austria") == "DIPLOMACY"
        assert section_for("how do I go to war with Austria") != "STRATEGIC COMMANDS"
        assert section_for("how do I reach a peace") == "DIPLOMACY"
        assert section_for("how do I get ships") == "THE ADMIRALTY"
        assert section_for("how do I sing") is None

    @pytest.mark.parametrize("line", (
        "how do I get to Narnia", "how do I go to Narnia", "how do I travel",
        "how do I reach Narnia", "how can I get there",
    ))
    def test_the_help_fallback_never_returns_the_whole_manual(self, line, _r16_world):
        from backend.commands.meta_executor import MetaExecutor
        with _r16_quiet():
            reply = MetaExecutor(None)._execute_help({"raw_command": line},
                                                     {"world": _r16_world})
        assert "COMMAND REFERENCE" not in reply["message"], line
        assert reply.get("help_section") == "STRATEGIC COMMANDS", line

    def test_a_grammar_question_about_another_verb_keeps_its_section(self, _r16_client):
        text = str(_r16_say(_r16_client, "how do I build ships?").get("message") or "")
        assert text.startswith("THE ADMIRALTY")
        text = str(_r16_say(_r16_client, "how do I sing?").get("message") or "")
        # S14E-D17: flipped - no section named: the SECTION INDEX answers, the
        # manual stays one bare `help` away.
        assert "COMMAND REFERENCE" not in text and text.startswith("Which part, Sire?"), text[:80]

    def test_a_place_nobody_can_march_to_is_refused_in_the_marches_own_words(
            self, _r16_client, _r16_world):
        # every corps of ours already stands there: nobody has a road to take
        for m in _r16_world.get_player_marshals():
            m.location = "Vienna"
        text = str(_r16_say(_r16_client, "how do I get to Vienna?").get("message") or "")
        assert "COMMAND REFERENCE" not in text
        assert "already" in text and "Vienna" in text, text

    def test_a_named_origin_is_honoured_or_said_not_to_be_ours(self, _r16_client, _r16_world):
        """Nothing the question names is dropped: "from Franconia" is the
        corps standing there; a place that is no province of the board's is
        said, and the answer is reckoned from the nearest corps."""
        text = str(_r16_say(_r16_client, "how do I get to Vienna from Franconia?")
                   .get("message") or "")
        assert "from Franconia" in text and "Bernadotte" in text, text
        text = str(_r16_say(_r16_client, "how do I get to Vienna from Narnia?")
                   .get("message") or "")
        assert "no province called Narnia" in text, text
        assert "COMMAND REFERENCE" not in text


