# S14E-32
# ══════════════════════════════════════════════════════════════════════════

# The verbs a quoted order may name -> (the action it parses to, the strategic
# type the parse carries or None). A NEW quoted verb is a failure until it is
# put here with the action it must read as.
_R32_READS_AS = {
    "recruit": ("recruit", None), "hold": ("hold", None), "cancel": ("cancel", None),
    "unfortify": ("unfortify", None), "retreat": ("retreat", None),
    "defend": ("defend", None), "scout": ("scout", None),
    "charge": ("charge", None), "attack": ("attack", None), "move": ("move", None),
    "march": ("move", "MOVE_TO"), "support": ("move", "SUPPORT"),
    "pursue": ("attack", "PURSUE"),
}
# What fills a placeholder in the tail of a quoted order, by verb.
_R32_OBJECT = {"attack": "Mack", "charge": "Mack", "pursue": "Mack",
               "support": "Davout", "recruit": "infantry"}
_R32_ROOTS = ("backend", "backend/commands", "backend/ai", "backend/game_logic",
              "backend/models")
# Not messages to the player: the LLM prompt's few-shot examples, and the
# legacy `CommandParser.get_help` demo block (called only from its own
# `__main__`). The command reference's body (a string over 2,000 characters)
# is CX-3's census (`tests/test_cx3_the_predictor.py`).
_R32_SKIP = ("backend/ai/prompt_builder.py", "backend/commands/parser.py")
_R32_LONGEST_MESSAGE = 2000
# 'Ney, recruit' and "Ney, recruit infantry" -- the game quotes in both.
_R32_QUOTED = re.compile(
    r"""(['"])((?:\x00|[A-Z][a-z]+(?: [A-Z][a-z]+)?)), ([a-z]+)((?: [^'"\n]*)?)\1""")


def _r32_harvest():
    """Every `'<Name>, <order verb> ...'` sentence the game's own message
    strings quote (docstrings and comments excluded), as
    {(file, line, head, verb, tail)}. A placeholder is \\x00."""
    import ast
    from backend.ai.routed_order_words import ROUTED_ORDER_WORDS
    root = Path(__file__).resolve().parents[1]
    found = set()
    for folder in _R32_ROOTS:
        for path in sorted((root / folder).glob("*.py")):
            if f"{folder}/{path.name}" in _R32_SKIP:
                continue
            tree = ast.parse(path.read_text(encoding="utf-8"))
            docstrings = set()
            for node in ast.walk(tree):
                body = getattr(node, "body", None)
                if (isinstance(node, (ast.Module, ast.FunctionDef, ast.AsyncFunctionDef,
                                      ast.ClassDef)) and body
                        and isinstance(body[0], ast.Expr)
                        and isinstance(getattr(body[0], "value", None), ast.Constant)):
                    docstrings.add(id(body[0].value))
            for node in ast.walk(tree):
                if isinstance(node, ast.JoinedStr):
                    text = "".join(str(v.value) if isinstance(v, ast.Constant) else "\x00"
                                   for v in node.values)
                elif (isinstance(node, ast.Constant) and isinstance(node.value, str)
                      and id(node) not in docstrings):
                    text = node.value
                else:
                    continue
                if len(text) > _R32_LONGEST_MESSAGE:
                    continue
                for m in _R32_QUOTED.finditer(text):
                    head, verb, tail = m.group(2), m.group(3), m.group(4)
                    if verb in ROUTED_ORDER_WORDS and head != "Sire":
                        found.add((f"{folder}/{path.name}", node.lineno, head, verb, tail))
    return found


def _r32_sentence(head: str, verb: str, tail: str) -> str:
    return (f"{'Ney' if head == chr(0) else head}, {verb}"
            + tail.replace("\x00", _R32_OBJECT.get(verb, "Swabia")))


@pytest.fixture(scope="module")
def _r32_board():
    from backend.ai.parser_eval import build_llm_game_state, build_world
    from backend.commands.parser import CommandParser
    with _r16_quiet():
        world = build_world("1805")
        return world, build_llm_game_state(world), CommandParser(use_real_llm=False)


def _r32_parse(board, text: str) -> dict:
    world, state, parser = board
    with _r16_quiet():
        return parser.parse(text, state, world=world)


class TestS14E32:
    """S14E-32 -- "Murat, cancel" is not understood though the game prints
    "'Ney, cancel' recalls him".

    Reproduced (the keyless parser on the 1805 board): "Murat, cancel" /
    "Murat, stop" / "Murat, abort" -> success False, "Unknown action"
    ("I cannot determine the order. Perhaps 'Murat, attack Moore' ...") while
    "Murat, halt" parsed -- the cancel keywords held "cancel " with its
    trailing space and ", halt" without, and the exact-match arm read only the
    bare verb with no address. The PURSUE-upgrade acceptance
    (`strategic_executor.py`) prints the very sentence `'Ney, cancel' recalls
    him.`; CX-3's census covered the help body and the completer, not the
    executors' messages.

    The fix: `_BARE_CANCEL_TAIL_RE` -- `<one to three words>, cancel|stop|
    abort|halt` is the cancel order; and the census below extended to every
    quoted `'X, verb'` order in the game's message strings.
    """

    @pytest.mark.parametrize("verb", ("cancel", "stop", "abort", "halt"))
    def test_the_bare_tail_after_the_address_is_the_cancel_order(self, verb, _r32_board):
        for line in (f"Murat, {verb}", f"murat, {verb}", f"Murat, {verb}.",
                     f"Marshal Murat, {verb}", f"Murat,{verb}"):
            result = _r32_parse(_r32_board, line)
            command = result.get("command") or {}
            assert result.get("success") is True, (line, result.get("message"))
            assert command.get("action") == "cancel" and command.get("marshal") == "Murat", line

    def test_the_sentence_the_game_prints_runs(self, _r16_client, _r16_world):
        reply = _r16_say(_r16_client, "Murat, cancel")
        assert reply.get("success") is True, reply.get("message")
        assert "Murat" in str(reply.get("message") or "")
        assert "cannot determine" not in str(reply.get("message") or "")

    def test_the_tail_is_the_whole_line_not_a_suffix(self, _r32_board):
        """"Ney, attack Mack, stop" is an attack with an aside; a name the
        roster lacks is still refused by name."""
        attack = (_r32_parse(_r32_board, "Ney, attack Mack, stop").get("command") or {})
        assert attack.get("action") == "attack"
        ghost = _r32_parse(_r32_board, "Zorglub, cancel")
        assert ghost.get("success") is False and "Zorglub" in str(
            ghost.get("error") or ghost.get("message"))

    def test_the_census_reads_the_quoted_orders_of_the_executors(self):
        found = _r32_harvest()
        files = {f for f, *_ in found}
        assert len(found) > 40, len(found)
        for needed in ("backend/commands/economy_executor.py",
                       "backend/commands/movement_executor.py",
                       "backend/commands/strategic_executor.py"):
            assert needed in files, needed
        verbs = {v for _f, _l, _h, v, _t in found}
        assert {"cancel", "recruit", "hold"} <= verbs, verbs

    def test_every_quoted_order_parses_to_the_action_it_names(self, _r32_board):
        failures, unmapped = [], set()
        for path, line, head, verb, tail in sorted(_r32_harvest()):
            if "[" in tail:          # a template ("[enemy name]"), not a sentence
                continue
            if verb not in _R32_READS_AS:
                unmapped.add(verb)
                continue
            sentence = _r32_sentence(head, verb, tail)
            result = _r32_parse(_r32_board, sentence)
            command = result.get("command") or {}
            action, strategic = _R32_READS_AS[verb]
            if verb == "march" and tail.endswith(" then attack"):
                # S14E-X72: the manual's own two-orders-in-one line ("march to X
                # then attack") reads as the attack carried by the march.
                action = "attack"
            read_as = (command.get("action"), result.get("strategic_type"))
            if not result.get("success") or command.get("action") != action or (
                    strategic and result.get("strategic_type") != strategic):
                failures.append((f"{path}:{line}", sentence, read_as))
        assert not unmapped, ("a quoted verb with no recorded reading", unmapped)
        assert not failures, failures

    def test_the_census_is_sensitive_to_the_defect(self, _r32_board, monkeypatch):
        """Mutation arm: with the bare-tail reader dead the census's own
        sentence ('Ney, cancel', quoted at strategic_executor) fails."""
        found = sorted((p, l, h, v, t) for p, l, h, v, t in _r32_harvest() if v == "cancel")
        assert found, "the census must see the quoted cancel"
        sentence = _r32_sentence(*found[0][2:])
        assert (_r32_parse(_r32_board, sentence).get("command") or {}).get("action") == "cancel"
        import backend.ai.llm_client as llm
        monkeypatch.setattr(llm, "_BARE_CANCEL_TAIL_RE", re.compile(r"(?!x)x"))
        broken = _r32_parse(_r32_board, sentence)
        assert (broken.get("command") or {}).get("action") != "cancel"


