# S14E-33
# ══════════════════════════════════════════════════════════════════════════

def _r33_open_seas(world) -> None:
    """The shipped boot has France under Britain's blockade (the yards' rate
    is 1); a guard posture on the British fleet opens the rate to 2."""
    from backend.game_logic import naval
    for nation, rec in naval.get_fleets(world).items():
        if nation != naval.META_KEY and nation != world.player_nation:
            rec["posture"] = "guard"
    assert naval.build_rate(world, world.player_nation) == 2


def _r33_state(world) -> dict:
    from backend.game_logic import naval
    rec = naval.get_fleet(world, world.player_nation)
    return {"ships": int(rec["ships"]), "built": int(rec.get("built_this_turn", 0) or 0),
            "gold": int(world.nation_gold[world.player_nation]),
            "admin": int(world.admin_actions_remaining)}


class TestS14E33:
    """S14E-33 -- "lay down two ships" lays one keel and never says the two
    was dropped.

    Reproduced (the shipped 1805 board, the real endpoint): "lay down two
    ships" parsed `build_fleet` with no count, `_execute_build_fleet` laid
    exactly ONE keel (45 -> 46 sail, 400g) and the reply -- "A keel is laid
    ... 1 more keel possible this turn" -- never said the number had been
    ignored; the same on "build 2 ships", "lay down three keels".

    The fix: the parser reads a count (`naval_executor.ship_count_in`, a
    `count` field on the command, one keel when none is named); the executor
    lays min(N, the yards' rate this turn, what the treasury holds, the
    administrative actions that remain -- a keel is an order's worth of each,
    as it always was) and the reply says how many and why not more. The AI's
    build rung carries no count and is untouched.
    """

    @pytest.mark.parametrize("line", (
        "lay down two ships", "build 2 ships", "lay down 2 ships",
        "build two ships of the line", "lay down both ships",
        "lay down a pair of ships", "lay down a couple of ships",
        "lay down two more ships", "lay down 2 keels"))
    def test_the_parser_reads_the_count(self, line, _r32_board):
        command = _r32_parse(_r32_board, line).get("command") or {}
        assert command.get("action") == "build_fleet", (line, command)
        assert command.get("count") == 2, (line, command)

    @pytest.mark.parametrize("line", (
        "lay down a ship", "build ships", "build a ship", "lay down one ship",
        "lay down a ship of the line", "build the fleet",
        "build ships for 800 gold"))
    def test_no_count_named_is_no_count_field_and_one_keel(self, line, _r32_board):
        command = _r32_parse(_r32_board, line).get("command") or {}
        assert command.get("action") == "build_fleet", (line, command)
        assert not command.get("count") or command.get("count") == 1, (line, command)

    def test_the_count_reader(self):
        from backend.commands.naval_executor import ship_count_in
        assert ship_count_in("lay down two ships") == 2
        assert ship_count_in("Build 3 keels") == 3
        assert ship_count_in("lay down a pair of ships") == 2
        assert ship_count_in("lay down 10 ships") == 10
        assert ship_count_in("lay down a ship") is None
        assert ship_count_in("lay down one ship") == 1
        assert ship_count_in("lay down no ships") is None
        assert ship_count_in("lay down 0 ships") is None
        assert ship_count_in("") is None and ship_count_in(None) is None
        # a number that is not the ships' ("for 800 gold", "in 2 turns")
        assert ship_count_in("build ships for 800 gold") is None
        assert ship_count_in("build ships in 2 turns") is None

    def test_a_keel_noun_reaches_the_fleet_not_the_economy(self, _r32_board):
        command = _r32_parse(_r32_board, "build three keels").get("command") or {}
        assert command.get("action") == "build_fleet" and command.get("count") == 3

    def test_two_ships_are_two_keels_and_the_reply_says_so(self, _r16_client, _r16_world):
        from backend.game_logic import naval
        _r33_open_seas(_r16_world)
        before = _r33_state(_r16_world)
        reply = _r16_say(_r16_client, "lay down two ships")
        after = _r33_state(_r16_world)
        text = str(reply.get("message") or "")
        assert reply.get("success") is True, text
        assert after["ships"] == before["ships"] + 2, (before, after)
        assert after["built"] == before["built"] + 2
        assert before["gold"] - after["gold"] == 2 * naval.SHIP_COST
        # shown == applied: the reply's own numbers
        assert text.startswith("Two keels are laid"), text
        assert f"{2 * naval.SHIP_COST}g" in text and "2 administrative actions" in text, text
        assert f"stands at {after['ships']} sail" in text, text
        assert "Only" not in text

    def test_each_keel_is_an_orders_worth_of_administration(self, _r16_client, _r16_world):
        """Two keels in one line cost what two lines cost: 2 admin actions."""
        _r33_open_seas(_r16_world)
        before = _r33_state(_r16_world)
        reply = _r16_say(_r16_client, "lay down two ships")
        after = _r33_state(_r16_world)
        assert before["admin"] - after["admin"] == 2, (before, after)
        # and the receipt says it: the pool's fall is the reply's own number
        assert "2 administrative actions" in str(reply.get("message") or "")
        assert reply["action_summary"]["admin_actions_remaining"] == after["admin"] == 0

    def test_a_count_beyond_the_yards_is_laid_to_the_rate_and_said(self, _r16_client, _r16_world):
        _r33_open_seas(_r16_world)
        before = _r33_state(_r16_world)
        reply = _r16_say(_r16_client, "lay down three keels")
        after = _r33_state(_r16_world)
        text = str(reply.get("message") or "")
        assert after["ships"] == before["ships"] + 2, (before, after)
        assert text.startswith("Only 2 of the 3 laid"), text
        assert "the yards allow 2 this turn" in text, text

    def test_the_blockaded_yards_lay_one_and_say_the_sightings_figure(
            self, _r16_client, _r16_world):
        """The shipped boot: France is blockaded, the rate is 1 -- the
        sighting's own board.  "Only 1 laid -- the yards allow 1 this turn"."""
        from backend.game_logic import naval
        assert naval.build_rate(_r16_world, "France") == 1
        before = _r33_state(_r16_world)
        reply = _r16_say(_r16_client, "lay down two ships")
        after = _r33_state(_r16_world)
        text = str(reply.get("message") or "")
        assert after["ships"] == before["ships"] + 1 and after["built"] == 1
        assert before["admin"] - after["admin"] == 1
        assert text.startswith("Only 1 of the 2 laid"), text
        assert "the yards allow 1 this turn" in text, text
        assert "no more keels possible this turn" in text.lower() or "0 more keels" in text

    def test_the_second_order_of_a_turn_is_told_how_many_more_the_yards_allow(
            self, _r16_client, _r16_world):
        _r33_open_seas(_r16_world)
        _r16_say(_r16_client, "lay down a ship")
        before = _r33_state(_r16_world)
        reply = _r16_say(_r16_client, "lay down two ships")
        after = _r33_state(_r16_world)
        text = str(reply.get("message") or "")
        assert after["ships"] == before["ships"] + 1
        assert text.startswith("Only 1 of the 2 laid"), text
        assert "the yards allow 1 more this turn" in text, text

    def test_a_thin_treasury_is_the_reason_when_it_binds(self, _r16_client, _r16_world):
        _r33_open_seas(_r16_world)
        _r16_world.nation_gold["France"] = 500
        before = _r33_state(_r16_world)
        reply = _r16_say(_r16_client, "lay down two ships")
        after = _r33_state(_r16_world)
        text = str(reply.get("message") or "")
        assert after["ships"] == before["ships"] + 1 and before["gold"] - after["gold"] == 400
        assert text.startswith("Only 1 of the 2 laid"), text
        assert "treasury holds 500g" in text, text

    def test_the_last_administrative_action_is_the_reason_when_it_binds(
            self, _r16_client, _r16_world):
        _r33_open_seas(_r16_world)
        _r16_world.admin_actions_remaining = 1
        before = _r33_state(_r16_world)
        reply = _r16_say(_r16_client, "lay down two ships")
        after = _r33_state(_r16_world)
        text = str(reply.get("message") or "")
        assert after["ships"] == before["ships"] + 1 and after["admin"] == 0
        assert text.startswith("Only 1 of the 2 laid"), text
        assert "1 administrative action remains" in text, text

    def test_no_count_is_one_keel_and_the_sentence_as_it_was(self, _r16_client, _r16_world):
        from backend.game_logic import naval
        _r33_open_seas(_r16_world)
        before = _r33_state(_r16_world)
        reply = _r16_say(_r16_client, "lay down a ship")
        after = _r33_state(_r16_world)
        text = str(reply.get("message") or "")
        assert after["ships"] == before["ships"] + 1 and after["admin"] == before["admin"] - 1
        assert text.startswith("A keel is laid at "), text
        assert f"({naval.SHIP_COST}g)" in text and "1 more keel possible this turn." in text, text
        assert "Only" not in text

    def test_the_ai_build_rung_carries_no_count_and_lays_one(self, _r16_world):
        """GR5: the AI's order is `find_ai_build_fleet`'s dict -- no count --
        and even a count handed to an AI actor is not read."""
        from backend.commands.executor import CommandExecutor
        from backend.game_logic import naval
        order = naval.find_ai_build_fleet(_r16_world, "Spain", 5000)
        assert order is not None and "count" not in order
        gs = {"world": _r16_world}
        before = int(naval.get_fleet(_r16_world, "Spain")["ships"])
        with _r16_quiet():
            result = CommandExecutor()._naval._execute_build_fleet(
                dict(order, count=2, raw_input="lay down two ships"), gs)
        assert result["success"] is True
        assert int(naval.get_fleet(_r16_world, "Spain")["ships"]) == before + 1
        assert "Only" not in result["message"] and result["message"].startswith("A keel is laid")


