class TestS14EX69:
    """S14E-X69 -- the route question's siblings (S14E-16's sweep).

    Reproduced (the real endpoint, the shipped 1805 board): "can I get to
    Vienna", "can we reach Vienna?", "is Vienna reachable?", "who can get to
    Vienna", "which marshal can reach Vienna" and "how can Ney get to Vienna"
    all drew the shrug ("I cannot answer that from the dispatches, Sire") --
    the marshal-less road and the named corps asked in other words -- and
    "how do I get Ney to Vienna" (once the route kind took the line) would
    have answered for the NEAREST corps, not the Ney it names.

    The fix: the same `route` kind reads can / who / which-marshal / is-X-
    reachable; the named corps's "how can Ney get to ..." and "how do I get
    Ney to ..." are the `reach` kind's; the route's place must be the WHOLE
    phrase (never a province found inside a longer one).
    """

    NEAREST = (
        "can I get to Vienna", "can we reach Vienna?", "could we get to Vienna?",
        "is Vienna reachable?", "who can get to Vienna", "which marshal can reach Vienna",
        "which corps could reach Vienna?",
    )

    @pytest.mark.parametrize("line", NEAREST)
    def test_the_marshal_less_question_is_answered_by_the_nearest_corps(
            self, line, _r16_client, _r16_world):
        from backend.commands.strategic import nearest_lawful_marcher
        marshal, road, _refusal = nearest_lawful_marcher(_r16_world, "Vienna")
        text = str(_r16_say(_r16_client, line).get("message") or "")
        assert marshal.name in text and " -> ".join([marshal.location] + list(road)) in text, (line, text)
        assert "cannot answer" not in text and "COMMAND REFERENCE" not in text

    @pytest.mark.parametrize("line", (
        "how can Ney get to Vienna", "how do I get Ney to Vienna",
        "how would Ney reach Vienna?", "how do we get Ney into Vienna?"))
    def test_the_named_corps_is_the_one_answered_for(self, line, _r16_client, _r16_world):
        text = str(_r16_say(_r16_client, line).get("message") or "")
        assert "Ney can reach Vienna from" in text, (line, text)

    def test_a_province_inside_a_longer_phrase_is_not_a_road(self, _r16_world):
        from backend.ai.question_desk import classify_board_question
        regions = list(_r16_world.regions)
        marshals = [m.name for m in _r16_world.get_player_marshals()]
        for line in ("how do I get a marshal to Vienna", "how do I get Zorglub to Vienna",
                     "how do I get the army to Vienna"):
            question = classify_board_question(line, marshals=marshals, enemies=[],
                                               regions=regions, nations=[])
            assert question is None or question["kind"] != "route", (line, question)

    def test_the_grammar_questions_that_are_not_routes_keep_their_sections(self, _r16_client):
        text = str(_r16_say(_r16_client, "how do I build ships?").get("message") or "")
        assert text.startswith("THE ADMIRALTY")
        text = str(_r16_say(_r16_client, "how do I sing?").get("message") or "")
        # S14E-D17: flipped - the SECTION INDEX, not the manual.
        assert "COMMAND REFERENCE" not in text and text.startswith("Which part, Sire?")


class TestS14EX70:
    """S14E-X70 -- the verbs a first-time player asks the manual with
    (S14E-16's sweep): the whole 22,573-character manual, for a four-line
    window, answered "how do I move my army", "how do I capture Vienna",
    "how do I beat Austria", "how do I raise an army", "how do I see my
    marshals", "how do I end the turn" and "how do I march an army to
    Vienna" -- the `help_topics` table held none of these verbs. Each now
    names its ONE section.
    """

    ROWS = (
        ("how do I move my army", "MILITARY COMMANDS"),
        ("how do I capture Vienna", "MILITARY COMMANDS"),
        ("how do I conquer Austria", "MILITARY COMMANDS"),
        ("how do I beat Austria", "MILITARY COMMANDS"),
        ("how do I raise an army", "MILITARY COMMANDS"),
        ("how do I see my marshals", "YOUR MARSHALS"),
        ("how do I end the turn", "FREE ACTIONS"),
        ("how do I march an army to Vienna", "STRATEGIC COMMANDS"),
        ("how do I get Ney to Zorglubia", "STRATEGIC COMMANDS"),
    )

    @pytest.mark.parametrize("line,heading", ROWS)
    def test_the_verb_names_its_section(self, line, heading):
        from backend.ai.help_topics import section_for
        assert section_for(line) == heading, line

    @pytest.mark.parametrize("line,heading", ROWS)
    def test_the_reply_is_that_section_and_not_the_manual(self, line, heading, _r16_client):
        text = str(_r16_say(_r16_client, line).get("message") or "")
        if line == "how do I capture Vienna":
            # S14E-X72: a province in hand is the desk's own one-paragraph answer
            # (the march-and-attack); the section stays the fallback for a place
            # the board does not know (`section_for` is pinned above).
            assert text.startswith("To take Vienna, Sire"), text[:80]
            assert "COMMAND REFERENCE" not in text and len(text) < 900
            return
        assert text.startswith(heading), (line, text[:80])
        assert "COMMAND REFERENCE" not in text and len(text) < 4500, len(text)

    def test_the_older_nouns_still_win_their_own_sections(self):
        from backend.ai.help_topics import section_for
        assert section_for("how do I raise taxes") == "ECONOMY"
        assert section_for("how do I raise a fleet") == "THE ADMIRALTY"
        assert section_for("how do I move the fleet") == "THE ADMIRALTY"
        assert section_for("how do I win a battle?") == "MILITARY COMMANDS"
        assert section_for("how do I win?") == "THE CONGRESS OF PARIS"
        assert section_for("how do I make peace with Austria?") == "DIPLOMACY"
        assert section_for("how do I sing") is None

    def test_help_end_turn_asks_for_the_section_and_ends_nothing(self, _r16_client, _r16_world):
        turn = int(_r16_world.current_turn)
        text = str(_r16_say(_r16_client, "help end turn").get("message") or "")
        assert text.startswith("FREE ACTIONS"), text[:80]
        assert int(_r16_world.current_turn) == turn

# ========== S14f part 2 - merged from test_s14f_p2_firstattack.py ==========

_r24_ROOT = Path(__file__).resolve().parent.parent
_r24_SCRIPTS = _r24_ROOT / "godot-client" / "project-sovereign" / "scripts"
_r24_SCENARIO = (_r24_ROOT / "godot-client" / "project-sovereign" / "assets" / "maps"
                 / "europe_1805.json")


def _r24_quiet():
    return contextlib.redirect_stdout(io.StringIO())


def _r24_src(name: str = "main.gd") -> str:
    return (_r24_SCRIPTS / name).read_text(encoding="utf-8")


def _r24_func(src: str, name: str) -> str:
    """A GDScript function's body: from its header to the next top-level one."""
    start = src.index(f"func {name}(")
    end = src.find("\nfunc ", start + 1)
    return src[start:end if end != -1 else len(src)]


@pytest.fixture(scope="module")
def _r24_boot():
    from backend.models.world_state import WorldState
    with _r24_quiet():
        return WorldState.from_scenario(str(_r24_SCENARIO))


@pytest.fixture
def _r24_world(_r24_boot):
    """The shipped 1805 board, a private copy per test."""
    from backend.models.world_state import WorldState
    return WorldState.from_dict(json.loads(json.dumps(_r24_boot.to_dict(), default=str)))


@contextlib.contextmanager
def _r24_served(world):
    """Swap the three module globals together and restore them."""
    import backend.main as M
    from backend.commands.parser import CommandParser
    from fastapi.testclient import TestClient
    saved = (M.game_state["world"], M.world, M.parser)
    M.game_state["world"] = world
    M.world = world
    M.parser = CommandParser(use_real_llm=False)
    try:
        with contextlib.redirect_stdout(io.StringIO()):
            yield TestClient(M.app)
    finally:
        M.game_state["world"], M.world, M.parser = saved


def _r24_join_names(line: str) -> set:
    """The corps a muster line names as answering the guns."""
    head = line.split(" would answer the guns", 1)[0].replace("Berthier adds: ", "")
    return {n.strip() for n in re.split(r",| and ", head) if n.strip()}


# ══════════════════════════════════════════════════════════════════════════
# S14E-24 — the first typed attack, and the free preview
# ══════════════════════════════════════════════════════════════════════════

class TestS14E24:
    """Reproduced: on the shipped 1805 board the boot dispatch's TODAY list
    offered "Ney, attack Mack" with no word of the free preview (`today` held
    orders / orders_header / doors / cabinet / doctrine / designs and nothing
    else); `order_quotes.attack_quote(world, Ney, Mack)` carried the command,
    AP and objection chance and no muster (`note` and every rider ""); the
    boot help listed `"Ney, attack Mack"` with no `what if` beside it. The
    muster gate arms only on an unfavourable band (DDB-D2 / R2), so the first
    typed attack — favourable, 106,545 against 52,000 — fired at once and
    pulled four corps and the Emperor into Swabia unannounced.

    Fix: the boot help and the TODAY list name 'what if Ney attacks Mack' (a
    new `today.orders_hint`, present only when an attack is listed); the map
    attack card's quote carries Berthier's one-line muster (`quote.muster`),
    the contact ask's own sentence. Typed orders stay unpaused."""

    # ── the boot help ─────────────────────────────────────────────────────
    def test_the_boot_help_names_the_free_preview_beside_the_first_attack(self):
        body = _r24_func(_r24_src(), "_print_boot_help")
        first = body.index('\\"Ney, attack Mack\\"')
        preview = body.index('\\"what if Ney attacks Mack\\"')
        assert first < preview < first + 400, "the preview sits beside the attack"
        assert "who marches with him" in body[preview:preview + 200]
        assert "free" in body[preview:preview + 120]

    def test_the_boot_help_preview_executes_and_costs_nothing(self, _r24_world):
        w = _r24_world
        before = (int(w.actions_remaining), int(w.admin_actions_remaining))
        with _r24_served(w) as client:
            reply = client.post("/command", json={"command": "what if Ney attacks Mack"}).json()
        assert reply["success"] is True, reply.get("message")
        assert "MUSTER" in reply["message"] and "WILL JOIN" in reply["message"]
        assert (int(w.actions_remaining), int(w.admin_actions_remaining)) == before

    # ── the TODAY list ────────────────────────────────────────────────────
    def test_the_today_list_names_the_preview_beside_the_attack(self, _r24_world):
        from backend.game_logic.dispatch import _build_first_morning_doors
        today = _build_first_morning_doors(_r24_world, "France")
        assert today["orders"][0] == "Ney, attack Mack"
        assert today["orders_hint"] == (
            "Ask 'what if Ney attacks Mack' first — it names who marches with "
            "Ney, and costs nothing.")

    def test_the_hint_rides_the_boot_dispatch_and_the_question_it_names_is_askable(self, _r24_world):
        from backend.game_logic.dispatch import build_morning_dispatch
        w = _r24_world
        with _r24_quiet():
            dispatch = build_morning_dispatch(w, boot=True)
        hint = dispatch["today"]["orders_hint"]
        question = re.search(r"'([^']+)'", hint).group(1)
        assert question == "what if Ney attacks Mack"
        with _r24_served(w) as client:
            reply = client.post("/command", json={"command": question}).json()
        assert reply["success"] is True and "MUSTER" in reply["message"], reply.get("message")

    def test_a_board_with_no_attack_listed_carries_no_hint(self, _r24_world, monkeypatch):
        import backend.ai.counsel as counsel
        from backend.game_logic.dispatch import _build_first_morning_doors
        monkeypatch.setattr(counsel, "what_can_i_do",
                            lambda *a, **k: ["Davout, march to Lorraine", "Ney, fortify"])
        today = _build_first_morning_doors(_r24_world, "France")
        assert "orders_hint" not in today
        assert set(today) == {"orders", "orders_header", "doors", "cabinet",
                              "doctrine", "designs"}

    def test_the_hint_reads_the_first_attack_among_the_lines(self):
        from backend.game_logic.dispatch import attack_preview_hint
        assert attack_preview_hint([]) == ""
        assert attack_preview_hint(["Davout, march to Lorraine"]) == ""
        assert attack_preview_hint(["Davout, march to Lorraine", "Murat, attack ArchdukeJohn",
                                    "Ney, attack Mack"]) == (
            "Ask 'what if Murat attacks ArchdukeJohn' first — it names who marches "
            "with Murat, and costs nothing.")

    def test_the_header_and_the_choice_lever_are_untouched(self):
        from backend.game_logic import dispatch
        assert dispatch.TODAY_ORDERS_HEADER.startswith("Orders the board will take at once")
        assert dispatch.THE_TODAY_LIST_IS_A_CHOICE is True

    def test_both_screens_print_the_hint_under_the_orders(self):
        for name, anchor in (("main.gd", "_display_morning_dispatch"),
                             ("dispatch_view.gd", None)):
            src = _r24_src(name)
            body = _r24_func(src, anchor) if anchor else src
            assert 'today.get("orders_hint", "")' in body, name
            assert (body.index("for order in today_orders:")
                    < body.index('today.get("orders_hint", "")')
                    < body.index('today.get("doors", "")')), name

    # ── the map attack card ───────────────────────────────────────────────
    def test_the_attack_quote_carries_berthiers_one_line_muster(self, _r24_world):
        from backend.commands.order_quotes import attack_quote
        w = _r24_world
        ney, mack = w.get_marshal("Ney"), w.get_marshal("Mack")
        q = attack_quote(w, ney, mack)
        assert q["ok"] and q["kind"] == "attack"
        line = q["muster"]
        assert line.startswith("Berthier adds: "), line
        assert "\n" not in line
        assert _r24_join_names(line) == {"Davout", "Lannes", "Murat", "Napoleon"}
        assert "against Mack (large force)" in line
        assert "the balance of force looks favorable" in line

    def test_the_line_is_the_previews_own_joiners_figure_and_band(self, _r24_world):
        """Shown == priced: the names are the preview rows that will march (and
        bring something), the figure its committed strength, the band its
        band — read off the very preview the what-if prints."""
        from backend.commands.executor import CommandExecutor
        from backend.commands.order_quotes import attack_quote
        w = _r24_world
        ney, mack = w.get_marshal("Ney"), w.get_marshal("Mack")
        with _r24_quiet():
            pv = CommandExecutor()._combat._build_muster_preview(
                ney, mack, w, {"world": w}, with_spread=False)
        line = attack_quote(w, ney, mack)["muster"]
        marching = {r["marshal"] for r in pv["rows"]
                    if r["will_join"] and not r.get("cannot_arrive")
                    and "NOTHING" not in r.get("withholds", "")}
        assert _r24_join_names(line) == marching
        assert f"{pv['attacker']['committed_strength']:,} with the muster committed" in line
        assert f"looks {pv['odds_band']}" in line

    def test_the_line_is_fog_legal(self, _r24_world):
        from backend.commands.order_quotes import attack_quote
        from backend.models.intel import FULL
        w = _r24_world
        ney, mack = w.get_marshal("Ney"), w.get_marshal("Mack")
        assert w.intel["Swabia"].visibility != FULL
        line = attack_quote(w, ney, mack)["muster"]
        assert "(large force)" in line
        assert f"{int(mack.strength):,}" not in line, "Mack's true strength is not printed"
        # With Swabia seen in full the same sentence prints the exact figure.
        w.intel["Swabia"].visibility = FULL
        assert f"({int(mack.strength):,} men" in attack_quote(w, ney, mack)["muster"] \
            or f"({int(mack.strength):,}" in attack_quote(w, ney, mack)["muster"]

    def test_a_corps_with_no_one_in_reach_says_so(self, _r24_world):
        from backend.commands.order_quotes import attack_quote
        w = _r24_world
        ney, mack = w.get_marshal("Ney"), w.get_marshal("Mack")
        for m in w.marshals.values():
            if m.nation == "France" and m.name != "Ney":
                m.location = "Normandy"
        line = attack_quote(w, ney, mack)["muster"]
        assert "no other corps stands within reach" in line, line
        assert "Ney 24,000 against Mack (large force)" in line

    def test_a_refused_or_distant_attack_has_no_muster(self, _r24_world):
        from backend.commands.order_quotes import attack_quote
        w = _r24_world
        ney, mack = w.get_marshal("Ney"), w.get_marshal("Mack")
        w.actions_remaining = 0
        refused = attack_quote(w, ney, mack)
        assert refused["ok"] is False and refused["muster"] == ""
        # A foe beyond Ney's reach is a march-and-attack card: the muster is
        # read where the corps arrives, not on the road.
        w.actions_remaining = 4
        far = attack_quote(w, w.get_marshal("Soult"), w.get_marshal("ArchdukeJohn"))
        # (S14E-X81 flipped the old `== ""`: the card now SAYS when it is read.)
        assert far["kind"] == "march_attack" and far["ok"]
        assert far["muster"] == f"On arrival Berthier will read the muster at {far['dest']}."

    def test_the_muster_belongs_to_the_players_corps_only(self, _r24_world):
        from backend.commands.order_quotes import _muster_line
        w = _r24_world
        assert _muster_line(w, w.get_marshal("Mack"), w.get_marshal("Ney")) == ""

    def test_the_quote_is_a_pure_read(self, _r24_world):
        import random
        from backend.commands.order_quotes import attack_quote
        w = _r24_world
        ney, mack = w.get_marshal("Ney"), w.get_marshal("Mack")
        dump = lambda: json.dumps(w.to_dict(), default=str, sort_keys=True)   # noqa: E731
        before, dice, hint = dump(), random.getstate(), w.muster_hint_shown
        assert attack_quote(w, ney, mack)["muster"]
        assert dump() == before
        assert random.getstate() == dice
        assert w.muster_hint_shown == hint

    def test_the_endpoint_and_the_provinces_rows_carry_it(self, _r24_world):
        from backend.commands.order_quotes import attack_quote, march_quotes_for_region
        w = _r24_world
        ney, mack = w.get_marshal("Ney"), w.get_marshal("Mack")
        want = attack_quote(w, ney, mack)["muster"]
        with _r24_served(w) as client:
            got = client.get("/march_quotes", params={"marshal": "Ney", "enemy": "Mack"}).json()
        assert got["success"] and got["quote"]["muster"] == want
        rows = march_quotes_for_region(w, "Swabia")["attack"][0]["quotes"]
        by = {q["marshal"]: q for q in rows}
        assert by["Ney"]["muster"] == want
        # (S14E-X81: a march & attack row carries "On arrival ... will read the
        # muster at <dest>", no real line; every other kind still carries none.)
        assert all(q["muster"] == "" for q in rows
                   if q["kind"] not in ("attack", "march_attack"))
        assert all(q["muster"] == f"On arrival Berthier will read the muster at {q['dest']}."
                   for q in rows if q["kind"] == "march_attack" and q["ok"])

    def test_the_card_prints_the_muster_under_the_objection_line(self):
        terms = _r24_func(_r24_src("order_confirm_card.gd"), "_terms")
        assert 'q.get("muster", "")' in terms
        assert (terms.index('q.get("objection", "none")')
                < terms.index('q.get("muster", "")')
                < terms.index('q.get("contact", "")'))

    def test_typed_orders_stay_unpaused(self, _r24_world):
        """The ruling DDB-D2 / R2 holds on its terms: a favourable attack fires
        at once; the preview is a question, never a gate."""
        from backend.commands.combat_executor import player_muster_gate_arms
        from backend.commands.order_quotes import attack_quote
        w = _r24_world
        ney = w.get_marshal("Ney")
        assert "favorable" in attack_quote(w, ney, w.get_marshal("Mack"))["muster"]
        assert player_muster_gate_arms(ney, "favorable") is False
        # and the quote is the only new surface: the executor's own source is
        # untouched by the muster line (it reads `_contact_muster_note`).
        src = (_r24_ROOT / "backend" / "commands" / "order_quotes.py").read_text(encoding="utf-8")
        assert "_contact_muster_note" in src


# ══════════════════════════════════════════════════════════════════════════
# S14E-X31 — IN PERIL at the End Turn click
# ══════════════════════════════════════════════════════════════════════════

def _rx31_board(ours=17000, foe=52000, morale=90, together=True, corps=("Ney",),
                enemy="Wellington"):
    """The fixture world: the named French corps stand at Belgium at `ours`
    men and `morale`; the enemy (Wellington, Britain) stands at Belgium with
    `foe` (`together`) or at adjacent Waterloo."""
    from backend.models.world_state import WorldState
    w = WorldState(player_nation="France")
    for name in corps:
        m = w.marshals[name]
        m.location, m.strength, m.morale = "Belgium", ours, morale
    f = w.marshals[enemy]
    f.location, f.strength = ("Belgium" if together else "Waterloo"), foe
    w.calculate_visibility()
    return w


def _rx31_peril(w):
    from backend.game_logic.dispatch import end_turn_peril_warning
    return end_turn_peril_warning(w, w.player_nation)


def _rx31_army(w):
    from backend.game_logic.dispatch import end_turn_army_warning
    return end_turn_army_warning(w, w.player_nation)


_rx31_SENTENCE = ("Ney's corps (17,000) stands in peril — an enemy force of ~52,000 "
                  "shares the field (Belgium).")


class TestS14EX31:
    """Reproduced: the fixture world with Ney (17,000, morale 90) at Belgium
    and Wellington (52,000, 3.06x) at the same province — `_derive_danger`
    printed "IN PERIL — an enemy force of ~52,000 shares the field (Belgium)."
    at dawn, and at the click `end_turn_army_warning` was None (the morale
    pairing only): a full-morale corps beside a 3x army ended the turn with no
    gate line. Beside = the dawn line's own reading, the shared province.

    Fix: `dispatch.end_turn_peril_warning` — the second clause, read through
    the same scan (`_known_enemy_force_at`) and the same ratio
    (`PERIL_RATIO`) as `_derive_danger`; a second response field
    (`end_turn_peril_warning`); the client's one gate and its one latch
    (`_army_warned`) show it before the morale line's question."""

    # ── the reproduction ──────────────────────────────────────────────────
    def test_the_dawn_line_says_in_peril_and_the_morale_gate_line_is_silent(self):
        from backend.game_logic.dispatch import _derive_danger
        w = _rx31_board()
        assert _derive_danger(w.marshals["Ney"], w, "France", {}) == (
            "IN PERIL — an enemy force of ~52,000 shares the field (Belgium).")
        assert _rx31_army(w) is None                  # the gate line that was missing

    # ── the clause ────────────────────────────────────────────────────────
    def test_a_full_morale_corps_beside_a_3x_enemy_yields_the_clause(self):
        assert _rx31_peril(_rx31_board()) == _rx31_SENTENCE

    def test_the_ratio_is_the_dawn_lines_and_flips_with_it(self, monkeypatch):
        from backend.game_logic import dispatch
        # 1.5 x 17,000 = 25,500: at the ratio, in peril; a man under it, not.
        for foe, expect in ((25500, True), (25499, False), (52000, True), (20000, False)):
            w = _rx31_board(foe=foe)
            dawn = "IN PERIL" in dispatch._derive_danger(w.marshals["Ney"], w, "France", {})
            assert dawn is expect
            assert (_rx31_peril(w) is not None) is expect, foe
        assert dispatch.PERIL_RATIO == 1.5
        w = _rx31_board()
        monkeypatch.setattr(dispatch, "PERIL_RATIO", 4)
        assert _rx31_peril(w) is None
        assert "IN PERIL" not in dispatch._derive_danger(w.marshals["Ney"], w, "France", {})

    def test_no_second_literal_ratio_in_the_dawn_derivation(self):
        src = (_r24_ROOT / "backend" / "game_logic" / "dispatch.py").read_text(encoding="utf-8")
        body = src[src.index("def _derive_danger("):src.index("_ROUT_CLAUSES = (")]
        assert "PERIL_RATIO * marshal.strength" in body
        assert "1.5 * marshal.strength" not in body
        assert src.count("PERIL_RATIO = 1.5") == 1

    def test_a_calm_board_yields_null(self):
        assert _rx31_peril(_rx31_board(foe=20000)) is None
        assert _rx31_peril(_rx31_board(together=False)) is None   # beside: the morale line's reading

    def test_an_army_in_the_next_province_is_not_in_peril_at_the_click(self):
        """Co-located only, as the dawn line is. A ratio against every
        neighbour would gate the shipped board's first turn: Ney (24,000)
        stands beside Mack (~55,000) at Rhineland / Swabia."""
        from backend.models.world_state import WorldState
        with _r24_quiet():
            w = WorldState.from_scenario(str(_r24_SCENARIO))
        assert _rx31_peril(w) is None

    def test_a_fogged_province_is_not_read_and_a_partial_one_prints_the_band(self):
        from backend.models.intel import PARTIAL, UNKNOWN
        w = _rx31_board()
        w.intel["Belgium"].visibility = UNKNOWN
        assert _rx31_peril(w) is None
        w.intel["Belgium"].visibility = PARTIAL
        w.intel["Belgium"].known_marshals = [
            {"name": "Wellington", "nation": "Britain", "band": "large force"}]
        line = _rx31_peril(w)
        assert "~55,000" in line and "52,000" not in line, line

    def test_a_court_we_are_at_peace_with_is_no_peril(self):
        w = _rx31_board(foe=20000)
        charles = w.marshals["ArchdukeCharles"]
        charles.location, charles.strength = "Belgium", 90000
        w.calculate_visibility()
        assert not w.is_at_war("France", "Austria")
        assert _rx31_peril(w) is None

    def test_several_corps_on_the_field_are_counted_and_the_heaviest_field_is_named(self):
        w = _rx31_board(corps=("Ney", "Davout"))
        assert _rx31_peril(w) == ("2 corps stand in peril — an enemy force of ~52,000 "
                                  "shares the field (Belgium).")
        # One of them is strong enough to stand: only the weak one is named.
        w.marshals["Davout"].strength = 40000
        assert _rx31_peril(w).startswith("Ney's corps (17,000) stands in peril")
        # A second field, lighter: the heavier enemy force leads …
        grouchy = w.marshals["Grouchy"]
        grouchy.location, grouchy.strength = "Rhineland", 10000
        w.calculate_visibility()
        assert "Belgium" in _rx31_peril(w) and "~52,000" in _rx31_peril(w)
        # … and when the heavy one no longer threatens, the other field is named.
        w.marshals["Wellington"].strength = 20000
        w.calculate_visibility()
        line = _rx31_peril(w)
        assert line.startswith("Grouchy's corps (10,000) stands in peril"), line
        assert "(Rhineland)" in line

    def test_a_captured_or_destroyed_corps_is_not_a_standing_corps(self):
        w = _rx31_board(corps=("Ney", "Davout"))
        w.marshals["Ney"].captured_by = "Britain"
        assert _rx31_peril(w).startswith("Davout's corps (17,000) stands in peril")
        w.marshals["Davout"].strength = 0
        assert _rx31_peril(w) is None

    def test_only_the_players_nation_is_warned(self):
        from backend.game_logic.dispatch import end_turn_peril_warning
        w = _rx31_board()
        assert end_turn_peril_warning(w, "Britain") is None

    def test_the_builder_is_a_pure_read_that_never_scans_enemies_or_regions(self):
        w = _rx31_board()

        def _boom(*_a, **_k):
            raise AssertionError("scanned beyond the player's roster and one intel lookup")
        w.get_visible_enemies = _boom
        w.get_enemies_of_nation = _boom
        real_regions = w.regions
        w.regions = SimpleNamespace(values=_boom, items=_boom, keys=_boom,
                                    __iter__=_boom, get=real_regions.get)
        dump = lambda: json.dumps({"turn": w.current_turn, "marshals": {   # noqa: E731
            n: [m.location, int(m.strength), int(m.morale)] for n, m in w.marshals.items()}},
            sort_keys=True)
        before = dump()
        assert _rx31_peril(w) == _rx31_SENTENCE
        assert dump() == before

    # ── the morale clause is untouched ────────────────────────────────────
    def test_the_morale_pairing_is_byte_identical_and_the_two_clauses_are_independent(self):
        w = _rx31_board(morale=30, foe=20000)
        w.marshals["Gneisenau"].location = "Berlin"      # the only army beside Ney is Wellington
        w.calculate_visibility()
        assert _rx31_army(w) == ("Ney's corps stands below 40% morale beside Wellington "
                                 "(20,000, Belgium) — end the turn anyway?")
        assert _rx31_peril(w) is None
        w.marshals["Wellington"].strength = 52000
        w.calculate_visibility()
        assert _rx31_army(w).startswith("Ney's corps stands below 40% morale beside Wellington")
        assert _rx31_peril(w) == _rx31_SENTENCE      # both, on one field: two clauses

    def test_the_morale_constant_stays_the_one_constant(self):
        from backend.game_logic import dispatch
        assert dispatch.MORALE_FAILING_BELOW == 40
        src = (_r24_ROOT / "backend" / "game_logic" / "dispatch.py").read_text(encoding="utf-8")
        assert src.count("MORALE_FAILING_BELOW = 40") == 1

    # ── the passthrough ───────────────────────────────────────────────────
    def test_the_clause_rides_a_command_response_and_a_post_handler(self):
        w = _rx31_board()
        with _r24_served(w) as client:
            a = client.post("/command", json={"command": "status"}).json()
            b = client.post("/cancel_order", json={"marshal": ""}).json()
        for r in (a, b):
            assert r["end_turn_peril_warning"] == _rx31_SENTENCE, sorted(r)
            assert r["end_turn_army_warning"] is None

    def test_a_calm_board_sends_null_not_a_missing_key(self):
        w = _rx31_board(foe=20000)
        with _r24_served(w) as client:
            r = client.post("/command", json={"command": "status"}).json()
        assert "end_turn_peril_warning" in r and r["end_turn_peril_warning"] is None

    def test_the_end_turn_response_carries_the_new_days_reading(self):
        w = _rx31_board()
        with _r24_served(w) as client:
            r = client.post("/command", json={"command": "end turn"}).json()
        assert r.get("turn_ended"), r.get("message")
        assert r["end_turn_peril_warning"] == _rx31_peril(w)

    def test_the_base_builder_sends_a_string(self):
        import backend.main as M
        w = _rx31_board()
        with _r24_quiet():
            r = M.build_base_response(w)
        assert isinstance(r["end_turn_peril_warning"], str)

    # ── the client's one gate and one latch, by source ───────────────────
    def test_the_client_reads_the_field_and_re_arms_when_it_changes(self):
        src = _r24_src()
        assert 'var end_turn_peril_warning: String = ""' in src
        sync = _r24_func(src, "_sync_response_hud")
        assert 'response.get("end_turn_peril_warning")' in sync
        assert "if _peril != end_turn_peril_warning:\n\t\t\t_army_warned = false" in sync
        # the army line's own re-arm stands beside it, byte for byte
        assert "if _army != end_turn_army_warning:\n\t\t\t_army_warned = false" in sync

    def test_the_gate_stops_once_on_either_clause_under_the_one_latch(self):
        src = _r24_src()
        stands = _r24_func(src, "_army_warning_stands")
        assert 'end_turn_army_warning != "" and not _army_warned' in stands
        assert 'end_turn_peril_warning != "" and not _army_warned' in stands
        gate = _r24_func(src, "_execute_end_turn")
        # DDB-13's treasury clause stands byte-for-byte, the army gate follows it.
        assert ("if _current_lapsing_count > 0 or not _current_decision_names.is_empty() "
                "or (_treasury_goes_negative() and not _treasury_warned):") in gate
        assert gate.index("_treasury_goes_negative()") < gate.index("_army_warning_stands()")
        assert src.count("var _army_warned: bool = false") == 1, "ONE latch for both clauses"
        assert "_peril_warned" not in src
        send = _r24_func(src, "_send_end_turn")
        assert "_army_warned = false" in send

    def test_the_card_prints_the_peril_clause_before_the_morale_question(self):
        card = _r24_func(_r24_src(), "_show_lapse_confirmation")
        assert "parts.append(end_turn_peril_warning)" in card
        assert (card.index("_treasury_warned = true")
                < card.index("parts.append(end_turn_peril_warning)")
                < card.index("parts.append(end_turn_army_warning)")), \
            "the morale line's question still closes the card"
        peril = card[card.index('if end_turn_peril_warning != "":'):
                     card.index("parts.append(end_turn_peril_warning)")]
        assert "_army_warned = true" in peril, "the one latch is set by this clause too"

    def test_the_closing_instruction_names_the_peril_as_a_stopper(self):
        """A treasury in deficit is the SOLE stopper only when neither army
        clause is up (S14E-X29's rule, widened to the second clause)."""
        card = _r24_func(_r24_src(), "_show_lapse_confirmation")
        tail = card[card.index("elif not _current_decision_names.is_empty():"):]
        deficit = tail[:tail.index("to end the turn in deficit")]
        assert ('_treasury_goes_negative() and end_turn_army_warning == "" '
                'and end_turn_peril_warning == ""') in deficit
        assert "to end the turn anyway" in tail


