class TestS14EX78:
    """Sweep find: the clause and the dawn line read ONE scan — a second
    reader of 'what enemy force the player's intel shows in a province' would
    drift from it. `_known_enemy_force_at` is that scan; the dawn line and the
    gate both call it (and it is the only place a known marshal's strength or
    band is summed for IN PERIL)."""

    def test_the_dawn_line_and_the_gate_share_the_one_scan(self):
        src = (_r24_ROOT / "backend" / "game_logic" / "dispatch.py").read_text(encoding="utf-8")
        assert src.count("def _known_enemy_force_at(") == 1
        dawn = src[src.index("def _derive_danger("):src.index("def end_turn_army_warning(")]
        gate = src[src.index("def end_turn_peril_warning("):src.index("_ROUT_CLAUSES = (")]
        assert "_known_enemy_force_at(world, player_nation, marshal.location)" in dawn
        assert "_known_enemy_force_at(world, nation, m.location)" in gate
        assert "known_marshals" not in gate and "known_marshals" not in dawn

    def test_the_scan_agrees_with_the_intel_it_reads(self):
        from backend.game_logic.dispatch import _known_enemy_force_at
        w = _rx31_board()
        assert _known_enemy_force_at(w, "France", "Belgium") == 52000
        assert _known_enemy_force_at(w, "France", "Nowhere") == 0
        assert _known_enemy_force_at(w, "France", "Waterloo") == 0

