# S14E-18
# ══════════════════════════════════════════════════════════════════════════
# S14E-18 (S14f part 2, Oct 25, 2026) — "Not Now" shuts the Cabinet for the
# turn and nothing says so at the click.

class TestS14E18:
    """Reproduced (before the fix): the dismiss echo in
    `main.gd::_on_incoming_proposal_choice` read "Setting aside Prussia's
    proposal. Click the envoy badge to revisit." — no word of the lock; the
    Not Now button carried no tooltip; the Cabinet button looked live until
    clicked, and the wizard's locked notice named the envoy but not the rule;
    the haggle's echo printed "Responding to Prussia's proposal: countered"
    BEFORE the backend answered (`choice_display["counter"]`) and the dry run
    then found no counter. The fix: the lock said at the click, in Not Now's
    tooltip, on the locked Cabinet button and in the wizard's notice (one
    sentence, `Utils.cabinet_shut_line`); the haggle's echo reworded to what
    was done ("asked Talleyrand to haggle"), true whatever he finds."""

    def test_one_sentence_is_the_lock(self):
        utils = _r18_src("utils.gd")
        body = _r18_func(utils, "cabinet_shut_line")
        assert f'return "{_R18_SHUT}"' in body
        # a call to arms stands to its answer-by turn: the sentence names it
        assert "turn %d ends." in body

    def test_the_echo_says_the_lock_at_the_click(self):
        main = _r18_src("main.gd")
        body = _r18_func(main, "_on_incoming_proposal_choice")
        dismiss = body[body.index('if choice == "dismiss":'):body.index("# LV-3 (row EP F2)")]
        assert "Setting aside %s's proposal — %s Click the envoy badge to revisit." in dismiss
        assert "Utils.cabinet_shut_line(" in dismiss
        # a moment letter has no court and never locks the wizard (EVENTS_SPEC
        # §3.4 seam 9): its echo is untouched
        moment = dismiss[dismiss.index("if is_moment:"):dismiss.index("else:")]
        assert "cabinet_shut_line" not in moment
        # composed the way the client composes it, the player reads the brief's sentence
        said = ("Setting aside %s's proposal — %s Click the envoy badge to revisit."
                % ("Prussia", _R18_SHUT))
        assert said.startswith("Setting aside Prussia's proposal — the Cabinet stays shut "
                               "until it is answered or the turn ends.")

    def test_the_echo_names_the_court_the_way_the_answer_echo_does(self):
        body = _r18_func(_r18_src("main.gd"), "_on_incoming_proposal_choice")
        dismiss = body[body.index('if choice == "dismiss":'):body.index("# LV-3 (row EP F2)")]
        assert 'data.get("from_nation_display"' in dismiss

    def test_not_now_carries_the_same_sentence_in_its_tooltip(self):
        popup = _r18_src("incoming_proposal_popup.gd")
        show = _r18_func(popup, "show_proposal")
        arm = show[show.index("S14E-18 (S14f part 2): a set-aside letter still stands"):
                   show.index("# Button labels adapt to context")]
        assert "Utils.cabinet_shut_line(_lock_by_turn)" in arm
        assert 'dismiss_btn.tooltip_text = "Set this letter aside — " + ' in arm
        # the moment letter locks nothing: its tooltip does not claim a lock
        moment_arm = arm[arm.index("if is_moment:"):arm.index("else:")]
        assert "cabinet_shut_line" not in moment_arm
        # a call to arms stands to its answer-by turn, and says so
        assert 'int(data.get("answer_by_turn", 0)) if is_call_to_arms else 0' in arm

    def test_the_locked_cabinet_button_says_so(self):
        main = _r18_src("main.gd")
        assert "func _set_cabinet_locked(" in main
        body = _r18_func(main, "_set_cabinet_locked")
        assert "diplomacy_button.tooltip_text" in body
        # flipped for S14E-X92 (S14f part 2, W1): the sentence takes the call to
        # arms' answer-by turn (`until`, 0 = the generic sentence)
        assert "Utils.cabinet_shut_line(until)" in body
        # the tooltip the .tscn authored comes back when the lock lifts
        assert "_cabinet_tooltip_default" in body
        # fed by the backend's one flag, on the hand-copied diplomatic fields
        upd = _r18_func(main, "_update_diplomatic_top_bar")
        # flipped for S14E-X92 (W1): the flag travels with `cabinet_locked_until`
        assert ('_set_cabinet_locked(bool(response.get("cabinet_locked", false)), '
                'int(response.get("cabinet_locked_until", 0)))') in upd

    def test_the_wizards_locked_notice_states_the_rule(self):
        wiz = _r18_src("diplomacy_wizard.gd")
        body = _r18_func(wiz, "_add_dialogue_gate_notice")
        assert "An unanswered envoy awaits your reply" in body
        # flipped for S14E-X92 (W1): the notice names the call to arms' turn
        assert "Utils.cabinet_shut_line(locked_until)" in body
        assert "Open Envoys" in wiz

    def test_the_haggle_echo_is_true_whatever_he_finds(self, _r18_world):
        """`choice_display` is the word the echo prints BEFORE the backend
        answers; "countered" was false whenever the dry run found nothing."""
        from backend.game_logic.mailbox_payloads import build_pending_envoy_popup_from_terms
        terms = _r18_terms("Austria", demands=[{"type": "gold_lump", "value": 300}])
        with _r18_quiet():
            popup = build_pending_envoy_popup_from_terms(
                _r18_world, nation="Austria", terms=terms, assessment="", acceptance=None,
                decision_reason="")
        assert popup["choice_display"]["counter"] == "asked Talleyrand to haggle"
        assert popup["choice_display"]["counter"] != "countered"
        # the answered words stand
        assert popup["choice_display"]["accept"] == "accepted"
        assert popup["choice_display"]["reject"] == "declined"
        # and the client prints them in "Responding to %s's proposal: %s"
        assert "Responding to %s's proposal: %s" in _r18_func(
            _r18_src("main.gd"), "_on_incoming_proposal_choice")

    def test_the_backend_flag_is_the_cabinets_own_gate(self, _r18_client):
        c, w = _r18_client
        assert _r18_post(c, "/command", {"command": "status"}).get("cabinet_locked") is False
        _r18_deliver(w, "Austria", _r18_terms("Austria", demands=[{"type": "gold_lump", "value": 300}]))
        after = _r18_post(c, "/command", {"command": "status"})
        assert after.get("cabinet_locked") is True
        # one flag, one gate: the wizard's nation list locks on the same read
        listing = _r18_get(c, "/diplomatic_preview")
        assert listing["dialogue_pending"] is True


