# S14E-20
# ══════════════════════════════════════════════════════════════════════════
# S14E-20 (S14f part 2, Oct 25, 2026) — the haggle is stamped from its dry run.

class TestS14E20:
    """Reproduced (before the fix), on the shipped 1805 board: Austria's peace
    that asks 300 gold — `generate_counter_offer(…, dry_run=True)` is None —
    arrived with the Counter option carrying NO `enabled` and NO `reason`, so
    the popup showed "Let Talleyrand haggle (1 DP)" live; the click ran the
    handler, which answered "Talleyrand finds no counter Austria could take —
    the offer stands." and never said the point was kept. Across the matrix of
    shipped-board letters (a court x an offer class) the dry run is None for
    most great courts: the live button was a lie in the common case.

    The fix (`treaty.counter_verdict` / `stamp_counter_option`, read by
    `stamp_letter` at every seam `refresh_letter_verdict` reaches): the Counter
    option carries `enabled` / `reason` from the dry run, greyed with the
    reason; HIDDEN for a courtesy or a peace on the held line when the dry run
    finds nothing (nothing in the letter to strike — Rule 9, no dead control);
    the result line ends "— no point spent"."""

    _AUSTRIA = {"type": "peace", "proposer_nation": "Austria", "target_nation": "France",
                "demands": [{"type": "gold_lump", "value": 300}], "sweeteners": [], "clauses": []}
    _SPAIN = {"type": "peace", "proposer_nation": "Spain", "target_nation": "France",
              "demands": [{"type": "gold_lump", "value": 3000}], "sweeteners": [], "clauses": []}

    def test_a_dry_run_none_is_greyed_with_the_reason(self, _r18_client):
        _c, w = _r18_client
        letter = _r18_deliver(w, "Austria", dict(self._AUSTRIA))
        counter = _r18_counter_option(letter)
        assert counter["enabled"] is False
        assert counter["reason"] == "Austria has nothing to trade at this price."
        assert not counter.get("hidden")
        # the popup's options mirror carries the stamp the popup reads
        row = _r18_popup_counter(letter["popup_payload"])
        assert row["enabled"] is False
        assert row["reason"] == "Austria has nothing to trade at this price."

    def test_a_counter_the_court_can_make_stays_live(self, _r18_client):
        _c, w = _r18_client
        w.nation_dp["Spain"] = 5
        letter = _r18_deliver(w, "Spain", dict(self._SPAIN))
        counter = _r18_counter_option(letter)
        assert counter["enabled"] is True
        assert counter["reason"] == ""
        assert not counter.get("hidden")

    def test_a_court_that_cannot_pay_for_its_counter_is_greyed(self, _r18_client):
        _c, w = _r18_client
        w.nation_dp["Spain"] = 0
        letter = _r18_deliver(w, "Spain", dict(self._SPAIN))
        counter = _r18_counter_option(letter)
        assert counter["enabled"] is False
        assert counter["reason"] == "Spain has nothing to trade at this price."

    def test_a_courtesy_with_nothing_to_strike_hides_the_haggle(self, _r18_client):
        _c, w = _r18_client
        letter = _r18_deliver(
            w, "Prussia",
            _r18_terms("Prussia", "open_borders", clauses=["open_borders"]), "open_borders")
        assert letter, "the letter must reach the desk"
        counter = _r18_counter_option(letter)
        assert counter["enabled"] is False
        assert counter["hidden"] is True
        assert _r18_popup_counter(letter["popup_payload"])["hidden"] is True

    def test_a_peace_on_the_held_line_hides_the_haggle(self, _r18_client):
        _c, w = _r18_client
        letter = _r18_deliver(w, "Austria", _r18_terms("Austria", "peace"))
        counter = _r18_counter_option(letter)
        assert counter["enabled"] is False
        assert counter["hidden"] is True

    def test_a_demand_in_the_letter_is_never_hidden_only_greyed(self, _r18_client):
        """The hidden class is the letter with nothing to strike; a letter that
        asks something keeps its (greyed) control and says why."""
        _c, w = _r18_client
        letter = _r18_deliver(w, "Austria", dict(self._AUSTRIA))
        assert not _r18_counter_option(letter).get("hidden")

    def test_the_press_costs_nothing_when_the_button_was_grey(self, _r18_client):
        c, w = _r18_client
        letter = _r18_deliver(w, "Austria", dict(self._AUSTRIA))
        dp = w.diplomatic_points
        out = _r18_post(c, "/respond_to_diplomatic_dialogue",
                        {"choice": "counter_ai_proposal", "dialogue_id": letter["dialogue_id"]})
        assert out["success"] is False
        assert out["message"].endswith("— no point spent.")
        assert out["message"] == ("Talleyrand finds no counter Austria could take; "
                                  "the offer stands — no point spent.")
        assert w.diplomatic_points == dp

    def test_every_read_seam_restamps_from_the_live_board(self, _r18_client):
        """Not baked at issue: the court's purse changes between reads."""
        c, w = _r18_client
        w.nation_dp["Spain"] = 0
        letter = _r18_deliver(w, "Spain", dict(self._SPAIN))
        assert _r18_counter_option(letter)["enabled"] is False
        # the poll (`/pending_envoy`) reads it grey ...
        polled = _r18_get(c, "/pending_envoy")
        assert _r18_popup_counter(polled["incoming_proposal"])["enabled"] is False
        # ... Spain recovers a point, and the very next read opens it
        w.nation_dp["Spain"] = 5
        polled = _r18_get(c, "/pending_envoy")
        assert _r18_popup_counter(polled["incoming_proposal"])["enabled"] is True
        assert _r18_popup_counter(polled["incoming_proposal"])["reason"] == ""
        # the mailbox activation is the third seam
        mailbox_id = letter["mailbox_id"]
        w.nation_dp["Spain"] = 0
        activated = _r18_post(c, "/mailbox/activate", {"mailbox_id": mailbox_id})
        assert _r18_popup_counter(activated["incoming_proposal"])["enabled"] is False

    def test_shown_is_applied_across_the_matrix(self, _r18_boot):
        """For every court x offer class of the matrix: the stamp says the
        click spends a point exactly when the handler spends one."""
        from backend.commands.executor import CommandExecutor
        from backend.models.world_state import WorldState
        from backend.game_logic.treaty import refresh_letter_verdict
        from backend.game_logic.ai_diplomacy import (
            _build_proposal_terms, build_ai_proposal_dialogue, _make_proposal)
        seen = {"live": 0, "grey": 0, "hidden": 0}
        for court in ("Prussia", "Austria", "Spain", "Bavaria", "Denmark", "Russia"):
            for ptype in ("friendly_gift", "open_borders", "non_aggression", "opportunistic",
                          "peace", "armistice_losing"):
                w = WorldState.from_dict(json.loads(json.dumps(_r18_boot.to_dict(), default=str)))
                w.diplomatic_points = 5
                with _r18_quiet():
                    terms = _build_proposal_terms(court, ptype, 30, w)
                    dialogue = build_ai_proposal_dialogue(
                        _make_proposal(court, ptype, 5, terms, w), w)
                    refresh_letter_verdict(w, dialogue)
                counter = _r18_counter_option(dialogue)
                dp = w.diplomatic_points
                with _r18_quiet():
                    result = CommandExecutor()._diplomatic._handle_counter_ai_proposal(dialogue, w)
                spent = dp - w.diplomatic_points
                if counter["enabled"] is False:
                    # greyed or hidden: the press (a stale popup, a typed answer)
                    # still costs nothing and says so
                    seen["hidden" if counter.get("hidden") else "grey"] += 1
                    assert spent == 0, (court, ptype, "a grey button must cost nothing")
                    assert result["message"].endswith("— no point spent."), result["message"]
                else:
                    assert not counter.get("hidden")
                    seen["live"] += 1
                    assert spent == 1, (court, ptype, "a live button costs the point it names")
        assert seen["live"] > 0 and seen["grey"] > 0 and seen["hidden"] > 0, seen

    def test_the_stamp_is_side_effect_free(self, _r18_client):
        """The dry run changes no world state and spends no DP."""
        _c, w = _r18_client
        letter = _r18_deliver(w, "Austria", dict(self._AUSTRIA))
        from backend.game_logic.treaty import refresh_letter_verdict
        dp = w.diplomatic_points
        nation_dp = dict(w.nation_dp)
        gold = dict(w.nation_gold)
        before = json.dumps(w.to_dict(), default=str, sort_keys=True)
        for _ in range(3):
            refresh_letter_verdict(w, letter)
        after = json.dumps(w.to_dict(), default=str, sort_keys=True)
        assert w.diplomatic_points == dp
        assert dict(w.nation_dp) == nation_dp
        assert dict(w.nation_gold) == gold
        assert before == after

    def test_a_player_without_a_point_sees_why(self, _r18_client):
        _c, w = _r18_client
        w.nation_dp["Spain"] = 5
        w.diplomatic_points = 0
        letter = _r18_deliver(w, "Spain", dict(self._SPAIN))
        counter = _r18_counter_option(letter)
        assert counter["enabled"] is False
        assert counter["reason"] == "A haggle costs 1 DP, and none is left."

    def test_the_popup_reads_the_stamp_as_it_reads_the_accept(self):
        popup = _r18_src("incoming_proposal_popup.gd")
        show = _r18_func(popup, "show_proposal")
        assert '"counter_ai_proposal"' in show
        assert 'counter_enabled = bool(opt.get("enabled", true))' in show
        assert 'counter_hidden = bool(opt.get("hidden", false))' in show
        assert "counter_btn.disabled" in show and "not counter_enabled" in show
        assert "and not counter_hidden" in show
        # the reason is on the tooltip AND above the fold, like the accept's
        assert "counter_btn.tooltip_text = counter_reason" in show
        assert "Haggle unavailable: " in show
        # the DDB-4 caption stands
        assert 'counter_btn.text = "Let Talleyrand haggle (1 DP)"' in show

    def test_the_mirror_carries_the_hidden_key(self):
        from backend.game_logic import treaty
        dialogue = {"options": [{"label": "x", "action": "counter_ai_proposal",
                                 "enabled": False, "reason": "r", "hidden": True}]}
        payload: dict = {}
        treaty._mirror_options(dialogue, payload)
        assert payload["options"][0]["hidden"] is True
        assert payload["options"][0]["enabled"] is False

    def test_a_counter_offer_letter_carries_no_haggle(self, _r18_client):
        """A counter-offer is answered, not countered again (the popup hides the
        button); the stamp touches only letters that carry the option."""
        c, w = _r18_client
        w.nation_dp["Spain"] = 5
        letter = _r18_deliver(w, "Spain", dict(self._SPAIN))
        out = _r18_post(c, "/respond_to_diplomatic_dialogue",
                        {"choice": "counter_ai_proposal", "dialogue_id": letter["dialogue_id"]})
        assert out["success"] is True
        current = w.pending_diplomatic_dialogue
        assert current["type"] == "counter_offer"
        assert all(o["action"] != "counter_ai_proposal" for o in current["options"])


