# S14E-27
# ══════════════════════════════════════════════════════════════════════════
# S14E-27 (S14f part 2, Oct 25, 2026) — the Envoys panel says what a row is.

class TestS14E27:
    """Reproduced (before the fix): `GET /mailbox` rows for a great court's
    letter carried only `summary_text` ("Incoming proposal: Open Borders",
    cut at 72 characters) — no terms, no reason it opens in full; the panel's
    "Open ▸" was a `Label` with `MOUSE_FILTER_IGNORE` (UXR3-63 added the word,
    the cursor and the tooltip; the word was still not the press); the subtitle
    never said which rows answer in place.

    The fix: the row carries `terms_lines` (the popup's own `clauses`) and one
    `reason` line for a row that does not answer in place
    (`envoy_digest.mailbox_row_terms` / `mailbox_row_reason`, the IGR-F module
    that owns the boundary — the boundary itself UNTOUCHED); the panel draws
    "Open ▸" as a flat Button on the same `item_selected` path, a Terms line
    and the reason line; the subtitle names the in-place rows."""

    def test_a_great_courts_row_carries_its_terms_and_the_reason(self, _r18_client):
        c, w = _r18_client
        letter = _r18_deliver(
            w, "Prussia",
            _r18_terms("Prussia", "open_borders", clauses=["open_borders"]), "open_borders")
        assert letter
        book = _r18_get(c, "/mailbox")
        row = next(i for i in book["items"] if i["source_nation"] == "Prussia")
        assert row["terms_lines"] == list(letter["popup_payload"]["clauses"])
        assert row["terms_lines"], "the letter has terms to show"
        assert row["reason"] == ("A great court's letter is answered in full "
                                 "— open to accept, haggle or refuse.")
        # the IGR-F boundary stands: a great court's letter is no letter-book row
        assert not (book["envoy_digest"] or {}).get("items")

    def test_a_routine_small_court_row_answers_in_place_and_needs_no_reason(self, _r18_client):
        c, w = _r18_client
        letter = _r18_deliver(w, "Saxony", _r18_terms("Saxony", "open_borders",
                                                       clauses=["open_borders"]), "open_borders")
        assert letter
        book = _r18_get(c, "/mailbox")
        row = next(i for i in book["items"] if i["source_nation"] == "Saxony")
        digest_rows = (book["envoy_digest"] or {}).get("items") or []
        assert any(d["mailbox_id"] == row["mailbox_id"] for d in digest_rows)
        assert row["reason"] == ""

    def test_a_lesser_courts_treaty_opens_in_full(self, _r18_client):
        """The routine allowlist is the boundary: a lesser court's PEACE is not
        a letter-book row, and its row says why."""
        c, w = _r18_client
        letter = _r18_deliver(w, "Saxony", _r18_terms("Saxony", "peace"))
        assert letter
        book = _r18_get(c, "/mailbox")
        row = next(i for i in book["items"] if i["source_nation"] == "Saxony")
        assert row["reason"] == ("A treaty is answered in full "
                                 "— open to accept, haggle or refuse.")

    def test_the_reason_for_every_other_kind_of_row(self, _r18_world):
        from backend.game_logic.envoy_digest import mailbox_row_reason
        w = _r18_world

        def row(dtype, **ctx):
            return {"type": dtype, "target_nation": ctx.pop("nation", "Prussia"),
                    "context": ctx}

        assert mailbox_row_reason(row("incoming_proposal", proposal_type="client_petition",
                                      source_nation="Prussia"), w) == (
            "A client's petition is granted or refused in full — open to decide.")
        assert mailbox_row_reason(row("incoming_proposal", proposal_type="call_to_arms",
                                      source_nation="Prussia"), w) == (
            "An ally's call to arms is joined or refused in full — open to answer.")
        assert mailbox_row_reason(row("incoming_proposal", proposal_type="moment_letter",
                                      source_nation="Prussia"), w) == (
            "A moment of history is answered in full — open the letter to choose.")
        assert mailbox_row_reason(row("incoming_ultimatum", source_nation="Prussia"), w) == (
            "An ultimatum is yielded to or defied in full — open to answer.")
        assert mailbox_row_reason(row("counter_offer", source_nation="Prussia"), w) == (
            "A counter-offer is accepted or rejected in full — open to read the revised terms.")
        assert mailbox_row_reason({"type": "incoming_settlement_offer"}, w) == (
            "A settlement offer is answered in full — open to review its terms.")
        assert mailbox_row_reason({"type": "ally_settlement_petition"}, w) == (
            "An ally's petition is answered in full — open to read it and reply.")

    def test_the_boundary_is_untouched(self, _r18_world):
        """`is_routine_small_court` still keeps a great court's courtesy and a
        lesser court's peace out of the letter-book."""
        from backend.game_logic.envoy_digest import is_routine_small_court
        w = _r18_world
        great = {"type": "incoming_proposal", "target_nation": "Prussia",
                 "context": {"proposal_type": "open_borders", "source_nation": "Prussia"}}
        small = {"type": "incoming_proposal", "target_nation": "Bavaria",
                 "context": {"proposal_type": "open_borders", "source_nation": "Bavaria"}}
        small_peace = {"type": "incoming_proposal", "target_nation": "Bavaria",
                       "context": {"proposal_type": "peace", "source_nation": "Bavaria"}}
        assert not is_routine_small_court(great, w)
        assert is_routine_small_court(small, w)
        assert not is_routine_small_court(small_peace, w)

    def test_a_row_without_terms_carries_an_empty_list_not_a_missing_key(self):
        from backend.models.dialogue_manager import DialogueManager
        dm = DialogueManager()
        dm.push({"type": "incoming_proposal", "target_nation": "Prussia",
                 "turn_created": 3, "context": {"source_nation": "Prussia",
                                                "proposal": {"type": "open_borders"}}})
        row = dm.get_mailbox_items()[0]
        assert row["terms_lines"] == []
        assert row["reason"] == ""   # no world, no tier: the panel's own rows say nothing

    def test_open_is_a_real_flat_button_on_the_same_path(self):
        panel = _r18_src("mailbox_panel.gd")
        build = _r18_func(panel, "_build_item_row")
        assert "var open_btn = Button.new()" in build
        assert 'open_btn.text = "Open ▸"' in build
        assert "open_btn.flat = true" in build
        assert "open_btn.pressed.connect(_open_row.bind(panel))" in build
        # the Label that was not a press is gone
        assert "open_label" not in build
        # one path: the button and the whole row both go through `_open_row`,
        # which emits `item_selected` — the row stays clickable
        assert "_open_row(panel)" in _r18_func(panel, "_on_row_gui_input")
        opener = _r18_func(panel, "_open_row")
        assert "item_selected.emit(" in opener and "hide()" in opener
        # the tooltip of the row stands (UXR3-63)
        assert 'panel.tooltip_text = "Open this letter"' in build
        assert "panel.mouse_default_cursor_shape = Control.CURSOR_POINTING_HAND" in build

    def test_the_row_draws_the_terms_line_and_the_reason_line(self):
        panel = _r18_src("mailbox_panel.gd")
        build = _r18_func(panel, "_build_item_row")
        assert 'item.get("terms_lines"' in build
        assert 'item.get("reason"' in build
        helper = _r18_func(panel, "_terms_line_label")
        assert '"Terms: " + " · ".join(' in helper
        # a letter-book row keeps its own Terms line (from the digest), once
        assert build.count("_terms_line_label(") == 2

    def test_the_subtitle_says_which_rows_answer_in_place(self):
        panel = _r18_src("mailbox_panel.gd")
        sub = re.search(r'const DEFAULT_SUBTITLE = "([^"]+)"', panel).group(1)
        assert "Routine letters from the lesser courts answer in place" in sub
        assert "every other letter opens in full" in sub
        # the lapse promise (R159) is kept
        assert "it lapses" in sub


# ══════════════════════════════════════════════════════════════════════════
# S14E-X90 (the sweep of S14E-20)
# ══════════════════════════════════════════════════════════════════════════
# S14E-X90 (S14f part 2, Oct 25, 2026) — a "counter" that is the letter itself.

class TestS14EX90:
    """Reproduced (before the fix), on the shipped board: Bavaria's peace
    (an ally, the court's reading 61 against a bar of 50) — `generate_counter_offer(
    …, dry_run=True)` returns the proposal UNCHANGED ("already acceptable, no
    need to counter"), the Counter option stayed live, and the press charged
    1 DP to re-present the identical terms as a "COUNTER-OFFER". The sweep of
    S14E-20's class (a haggle control live where the click can only waste the
    point): `treaty.counter_is_constructible` is now the ONE question the stamp
    and the handler both ask — an unchanged hand-back is no counter."""

    def test_an_unchanged_hand_back_is_no_counter(self, _r18_client):
        from backend.game_logic.ai_diplomacy import generate_counter_offer
        c, w = _r18_client
        terms = _r18_terms("Bavaria", "peace")
        premise = generate_counter_offer(terms, w, dry_run=True)
        assert premise == terms, "the premise: the dry run hands the proposal back"
        letter = _r18_deliver(w, "Bavaria", dict(terms))
        counter = _r18_counter_option(letter)
        assert counter["enabled"] is False
        assert counter["reason"] == ("Bavaria's terms already stand "
                                     "— Talleyrand finds nothing to haggle over.")
        assert counter["hidden"] is True   # a letter that asks nothing: nothing to strike
        dp = w.diplomatic_points
        out = _r18_post(c, "/respond_to_diplomatic_dialogue",
                        {"choice": "counter_ai_proposal", "dialogue_id": letter["dialogue_id"]})
        assert out["success"] is False
        assert out["message"].endswith("— no point spent.")
        assert w.diplomatic_points == dp
        assert (w.pending_diplomatic_dialogue or {}).get("dialogue_id") == letter["dialogue_id"]

# ========== S14f part 2 - merged from test_s14f_p2_mission.py ==========

_R34_SCENARIO = (Path(__file__).resolve().parents[1] / "godot-client" / "project-sovereign"
            / "assets" / "maps" / "europe_1805.json")
ROOT = Path(__file__).resolve().parents[1]


@contextlib.contextmanager
def _r34_quiet():
    with contextlib.redirect_stdout(io.StringIO()):
        yield


@pytest.fixture(scope="module")
def _r34_boot():
    from backend.models.world_state import WorldState
    with _r34_quiet():
        return WorldState.from_scenario(str(_R34_SCENARIO))


@pytest.fixture
def _r34_w(_r34_boot):
    from backend.models.world_state import WorldState
    with _r34_quiet():
        return WorldState.from_dict(json.loads(json.dumps(_r34_boot.to_dict(), default=str)))


@pytest.fixture(autouse=True)
def _r34_no_blowback(monkeypatch):
    """COURT_NATION's 20% blowback is a die; every pin here is about the books."""
    from backend.game_logic import diplomatic_dialogue as DD
    monkeypatch.setitem(DD.MISSION_EFFECTS["COURT_NATION"], "undermine_chance", 0.0)


def _r34_copy(w):
    from backend.models.world_state import WorldState
    with _r34_quiet():
        return WorldState.from_dict(json.loads(json.dumps(w.to_dict(), default=str)))


def _r34_rel(w, a, b):
    return int(w.nation_relations.get(w._make_diplo_key(a, b), 0) or 0)


def _r34_set_rel(w, a, b, value):
    w.nation_relations[w._make_diplo_key(a, b)] = int(value)


def _r34_set_state(w, a, b, state):
    w.diplomatic_states[w._make_diplo_key(a, b)] = state
    w.invalidate_bloc_members_cache()


def _r34_begin(w, mission_type, target, ally=None, dp=10):
    """Drive the REAL `start_mission` dialogue arm (the executor writes the dict)."""
    from backend.commands.executor import CommandExecutor
    from backend.game_logic.diplomatic_dialogue import MISSION_DP_COSTS
    terms = {"mission_type": mission_type, "target_nation": target}
    if ally:
        terms["target_ally"] = ally
    w.dialogue_manager.replace({
        "type": "mission", "target_nation": target, "talleyrand_text": "Very well, Sire.",
        "options": [
            {"label": "Begin mission", "description": "Start.", "action": "start_mission",
             "terms": terms},
            {"label": "Dismiss", "description": "Cancel.", "action": "dismiss"},
        ],
        "context": {"dp_cost_per_turn": int(MISSION_DP_COSTS[mission_type])},
        "turn_created": int(w.current_turn), "blocking": False,
    })
    w.diplomatic_points = max(int(w.diplomatic_points), dp)
    with _r34_quiet():
        out = CommandExecutor()._diplomatic.handle_diplomatic_dialogue_response(1, {"world": w})
    assert out.get("success"), out
    return w.active_diplomatic_mission


def _r34_tick(w, dp=10):
    """One whole diplomatic tick (`process_diplomacy_turn`), DP topped up."""
    from backend.game_logic import diplomacy as D
    w.diplomatic_points = dp
    with _r34_quiet():
        return D.process_diplomacy_turn(w)


def _r34_truce(w, relation=-60):
    """France and Austria under a truce (the sighting's Austria)."""
    _r34_set_state(w, "France", "Austria", "ARMISTICE")
    _r34_set_rel(w, "France", "Austria", relation)
    w.armistice_turns[w._make_diplo_key("France", "Austria")] = 1


def _r34_rows(w, court):
    from backend.game_logic import diplomacy as D
    w.diplomatic_points = max(int(w.diplomatic_points), 10)
    with _r34_quiet():
        return {a["action"]: a for a in D.get_available_diplomatic_actions(w, court)}


class TestS14E34:
    """Improve Relations sent under a truce ran on after the peace it was sent
    to win.

    Reproduced: on the shipped board, France-Austria under a truce at -60, the
    real `start_mission` arm for Improve Relations, then the pair at PEACE and
    four `process_diplomacy_turn` ticks: the mission stayed LIVE (`completed`
    absent), billed 1 DP on each of the four ticks (turns_active 1 -> 4), carried
    the relation -60 -> -24 with no word, and `mission_gate` refused the next
    mission with "Mission already active" naming no court.
    """

    def test_the_executor_records_the_state_a_truce_mission_began_in(self, _r34_w):
        w = _r34_w
        _r34_truce(w)
        mission = _r34_begin(w, "IMPROVE_RELATIONS", "Austria")
        assert mission["started_state"] == "ARMISTICE"

    def test_a_mission_begun_at_war_records_war(self, _r34_w):
        w = _r34_w
        assert w.get_diplomatic_state("France", "Austria") == "WAR"
        mission = _r34_begin(w, "IMPROVE_RELATIONS", "Austria")
        assert mission["started_state"] == "WAR"

    def test_a_mission_begun_at_peace_records_no_state(self, _r34_w):
        w = _r34_w
        _r34_set_state(w, "France", "Prussia", "PEACE")
        mission = _r34_begin(w, "IMPROVE_RELATIONS", "Prussia")
        assert "started_state" not in mission, mission

    def test_the_tick_that_finds_the_peace_ends_the_mission_and_bills_nothing(self, _r34_w):
        w = _r34_w
        _r34_truce(w)
        _r34_begin(w, "IMPROVE_RELATIONS", "Austria")
        _r34_set_state(w, "France", "Austria", "PEACE")
        events = _r34_tick(w)
        mission = w.active_diplomatic_mission
        assert mission["completed"] is True and mission["end_reason"] == "peace"
        assert mission["turns_active"] == 0, "the tick that finds the peace bills no DP"
        (done,) = [e for e in events if e.get("type") == "diplomatic_mission_completed"]
        assert done["reason"] == "peace"
        assert "Austria and France are at peace — Talleyrand is home" in done["message"]
        # the DP stops: three more ticks charge nothing and the mission stays done
        for _ in range(3):
            _r34_tick(w)
        assert w.active_diplomatic_mission["turns_active"] == 0

    def test_the_end_is_told_on_the_rail_the_log_and_the_dispatch(self, _r34_w):
        from backend.game_logic.dispatch import _build_diplomatic_events_section
        w = _r34_w
        _r34_truce(w)
        _r34_begin(w, "IMPROVE_RELATIONS", "Austria")
        _r34_set_state(w, "France", "Austria", "PEACE")
        w.pending_dispatch_events = []
        _r34_tick(w)
        # the rail: ONE row, the ending beat
        rows = [n for n in w.notifications.get_pending() if n.get("type") == "diplomatic_mission"]
        assert len(rows) == 1 and "Austria and France are at peace — Talleyrand is home" in rows[0]["message"], rows
        assert rows[0]["details"]["beat"] == "completed"
        # the campaign log
        ended = [e for e in w.event_log if e.get("type") == "diplomatic_mission_ended"]
        assert ended and ended[-1]["reason"] == "peace"
        from backend.campaign_log import format_event_oneliner
        line = format_event_oneliner(ended[-1])
        assert "the peace was signed" in line, line
        # the dispatch: a MEDIUM line naming both courts
        with _r34_quiet():
            events = _build_diplomatic_events_section(w, "France")
        (beat,) = [e for e in events if e["type"] == "diplomatic_mission_completed"]
        assert beat["priority"] == "MEDIUM"
        assert "Austria and France are at peace — Talleyrand is home" in beat["text"], beat

    def test_the_desk_is_free_for_the_next_mission(self, _r34_w):
        from backend.game_logic import diplomacy as D
        w = _r34_w
        _r34_truce(w)
        _r34_begin(w, "IMPROVE_RELATIONS", "Austria")
        assert D.mission_gate(w, "IMPROVE_RELATIONS") == (False, "Mission already active")
        _r34_set_state(w, "France", "Austria", "PEACE")
        _r34_tick(w)
        assert D.mission_gate(w, "IMPROVE_RELATIONS") == (True, "")
        assert w.talleyrand_state == "IDLE"

    def test_a_truce_that_ripens_ends_the_mission_on_that_tick(self, _r34_w):
        from backend.game_logic import diplomacy as D
        w = _r34_w
        _r34_truce(w, relation=-55)
        key = w._make_diplo_key("France", "Austria")
        _r34_begin(w, "IMPROVE_RELATIONS", "Austria")
        w.armistice_turns[key] = int(D.ARMISTICE_DURATION) - 1      # the expiring tick
        _r34_tick(w)
        assert w.get_diplomatic_state("France", "Austria") == "PEACE", "the truce ripened"
        mission = w.active_diplomatic_mission
        assert mission["completed"] is True and mission["end_reason"] == "peace", mission

    def test_a_truce_that_has_not_ripened_leaves_the_mission_at_work(self, _r34_w):
        w = _r34_w
        _r34_truce(w, relation=-55)
        _r34_begin(w, "IMPROVE_RELATIONS", "Austria")
        for _ in range(2):
            _r34_tick(w)
        mission = w.active_diplomatic_mission
        assert not mission.get("completed") and mission["turns_active"] == 2, mission

    def test_a_mission_begun_at_peace_is_untouched_by_the_tick(self, _r34_w):
        w = _r34_w
        _r34_set_state(w, "France", "Prussia", "PEACE")
        _r34_set_rel(w, "France", "Prussia", 10)
        _r34_begin(w, "IMPROVE_RELATIONS", "Prussia")
        for _ in range(3):
            _r34_tick(w)
        mission = w.active_diplomatic_mission
        assert not mission.get("completed") and mission["turns_active"] == 3, mission
        assert "end_reason" not in mission

    def test_courting_keeps_the_favour_past_the_peace(self, _r34_w):
        """COURT_NATION is not of the class: the Court's Favour is paid in
        treaties AFTER the peace and holds only while he stays (IQ-4)."""
        w = _r34_w
        _r34_truce(w)
        mission = _r34_begin(w, "COURT_NATION", "Austria")
        assert mission["started_state"] == "ARMISTICE"
        _r34_set_state(w, "France", "Austria", "PEACE")
        _r34_tick(w)
        assert not w.active_diplomatic_mission.get("completed")

    def test_an_old_save_without_the_key_runs_as_it_did(self, _r34_w):
        w = _r34_w
        _r34_truce(w)
        mission = _r34_begin(w, "IMPROVE_RELATIONS", "Austria")
        mission.pop("started_state")
        _r34_set_state(w, "France", "Austria", "PEACE")
        _r34_tick(w)
        assert not w.active_diplomatic_mission.get("completed")

    def test_the_new_keys_survive_a_save(self, _r34_w):
        w = _r34_w
        _r34_truce(w)
        _r34_begin(w, "IMPROVE_RELATIONS", "Austria")
        saved = _r34_copy(w)
        assert saved.active_diplomatic_mission["started_state"] == "ARMISTICE"
        _r34_set_state(saved, "France", "Austria", "PEACE")
        _r34_tick(saved)
        again = _r34_copy(saved)
        assert again.active_diplomatic_mission["end_reason"] == "peace"
        assert again.active_diplomatic_mission["completed"] is True

    def test_the_shut_row_names_the_court_the_slot_is_at(self, _r34_w):
        w = _r34_w
        _r34_set_state(w, "France", "Prussia", "PEACE")
        _r34_begin(w, "IMPROVE_RELATIONS", "Prussia")
        rows = _r34_rows(w, "Austria")
        row = rows["mission_gather_intel"]
        assert row["available"] is False
        assert row["disabled_reason_display"] == "Talleyrand is at Prussia's court — F1 → Prussia → Cancel"
        assert row["disabled_reason"] == "Mission already active", "the machine reason stays"

    def test_the_busy_words_stand_in_the_client_tooltip_chain(self):
        src = (ROOT / "godot-client" / "project-sovereign" / "scripts" / "diplomacy_wizard.gd").read_text(encoding="utf-8")
        assert 'action.get("disabled_reason_display", action.get("error_display", action.get("disabled_reason", "")))' in src

    def test_the_dispatch_progress_line_carries_the_dp_bill(self, _r34_w):
        from backend.game_logic.dispatch import _build_diplomatic_events_section
        w = _r34_w
        _r34_set_state(w, "France", "Prussia", "PEACE")
        _r34_set_rel(w, "France", "Prussia", 10)
        _r34_begin(w, "IMPROVE_RELATIONS", "Prussia")
        w.pending_dispatch_events = []
        _r34_tick(w)
        _r34_tick(w)
        with _r34_quiet():
            events = _build_diplomatic_events_section(w, "France")
        lines = [e for e in events if e["type"] == "diplomatic_mission_progress"]
        assert lines, events
        text = lines[-1]["text"]
        assert text.startswith("Talleyrand's efforts in Prussia continue. Relations now at "), text
        assert text.endswith("1 DP a turn, 2 so far."), text

    def test_the_undermining_line_carries_its_bill_too(self, _r34_w):
        from backend.game_logic.dispatch import _build_diplomatic_events_section
        w = _r34_w
        _r34_begin(w, "UNDERMINE_ALLIANCE", "Austria", ally="Britain")
        w.pending_dispatch_events = []
        _r34_tick(w)
        _r34_tick(w)
        with _r34_quiet():
            events = _build_diplomatic_events_section(w, "France")
        lines = [e for e in events if e["type"] == "diplomatic_mission_undermine_progress"]
        assert lines and lines[-1]["text"].endswith("2 DP a turn, 4 so far."), lines

    def test_a_queued_line_from_before_the_bill_renders_as_it_did(self):
        from backend.game_logic.dispatch import _format_dispatch_event_text
        text = _format_dispatch_event_text(
            "diplomatic_mission_progress", {"nation": "Prussia", "value": 12})
        assert text == "Talleyrand's efforts in Prussia continue. Relations now at 12."

    def test_the_last_mission_line_says_the_peace_not_the_ceiling(self, _r34_w):
        from backend.game_logic.ledger import build_cabinet
        w = _r34_w
        _r34_truce(w)
        _r34_begin(w, "IMPROVE_RELATIONS", "Austria")
        _r34_set_state(w, "France", "Austria", "PEACE")
        _r34_tick(w)
        cabinet = build_cabinet(w)
        assert cabinet["live"] is False
        assert cabinet["last"]["reason_phrase"] == "the peace was signed", cabinet

    def test_the_projection_says_it_ends_at_the_peace(self, _r34_w):
        from backend.game_logic.diplomatic_dialogue import mission_status
        w = _r34_w
        _r34_truce(w)
        _r34_begin(w, "IMPROVE_RELATIONS", "Austria")
        status = mission_status(w)
        assert status["remaining_kind"] == "peace"
        assert "peace is signed" in status["remaining_note"], status["remaining_note"]
        assert "no end in sight" not in status["remaining_note"]


# ══════════════════════════════════════════════════════════════════════════
# S14E-X37 — the writes that drag the pair are booked (before X36 reads them)
# ══════════════════════════════════════════════════════════════════════════

def _rx37_stage(w, mission_type, target, ally=None):
    """The dict the executor's `start_mission` arm writes, books open."""
    mission = {
        "type": mission_type, "target": target, "turns_active": 0, "paused": False,
        "paused_turns": 0, "started_turn": int(w.current_turn),
        "initial_relation": _r34_rel(w, w.player_nation, target),
        "earned": 0, "shocks": [], "paused_errand": 0, "paused_starved": 0,
    }
    if ally:
        mission["target_ally"] = ally
        mission["initial_pair_relation"] = _r34_rel(w, target, ally)
    w.active_diplomatic_mission = mission
    w.talleyrand_state = "ON_MISSION"
    return mission


def _rx37_both(w, stage, run):
    """The books never move the board: run the SAME write on a world with the
    mission and one without; return (mission world, bare world)."""
    bare = _r34_copy(w)
    with_mission = _r34_copy(w)
    stage(with_mission)
    with _r34_quiet():
        run(with_mission)
        run(bare)
    return with_mission, bare


def _rx37_shocks(w):
    return list(w.active_diplomatic_mission["shocks"])


class TestS14EX37:
    """Reproduced: on the shipped board a Reassure Ally on Spain under a forced
    alliance (-10 a turn), an Improve Relations on Prussia through an
    ultimatum, an Undermine on two coalition members through the coalition's
    +10 / -15 / -2, a settlement's shut-out and a vassal's break all moved the
    mission's pair and left `shocks` EMPTY (the books held only the three
    part-1 sites: a declaration, a downgrade, a treaty break)."""

    def test_the_forced_alliance_drift_is_booked(self, _r34_w):
        from backend.game_logic import diplomacy as D
        w = _r34_w
        w.alliance_origins[w._make_diplo_key("France", "Spain")] = "forced"
        mission_world, bare = _rx37_both(
            w, lambda x: _rx37_stage(x, "REASSURE_ALLY", "Spain"),
            D._process_forced_alliance_drift)
        assert mission_world.nation_relations == bare.nation_relations, "the board is untouched"
        (shock,) = _rx37_shocks(mission_world)
        assert (shock["kind"], shock["delta"]) == ("forced_alliance_drift", -10)
        from backend.game_logic.diplomatic_dialogue import mission_shock_cause
        assert mission_shock_cause(shock) == "the forced alliance's drift"

    def test_a_standing_write_folds_into_one_entry(self, _r34_w):
        from backend.game_logic import diplomacy as D
        w = _r34_w
        w.alliance_origins[w._make_diplo_key("France", "Spain")] = "forced"
        _rx37_stage(w, "REASSURE_ALLY", "Spain")
        for _ in range(3):
            D._process_forced_alliance_drift(w)
        (shock,) = _rx37_shocks(w)
        assert shock["delta"] == -30, shock

    def test_the_ultimatum_penalty_and_its_rejection_are_booked(self, _r34_w):
        from backend.commands.executor import CommandExecutor
        w = _r34_w
        _r34_set_state(w, "France", "Prussia", "PEACE")
        _r34_set_rel(w, "France", "Prussia", 10)
        for m in w.marshals.values():
            if m.nation == "Prussia":
                m.strength = min(int(m.strength), 3000)

        def deliver(x):
            demands = [{"type": "gold_lump", "value": 5000}]
            x.dialogue_manager.replace({
                "type": "ultimatum_confirm", "target_nation": "Prussia",
                "turn_created": int(x.current_turn), "prompt": "Deliver?",
                "options": [{"label": "Deliver Ultimatum", "action": "execute_ultimatum",
                             "terms": {"demands": demands, "sweeteners": [], "clauses": [],
                                       "type": "ultimatum_demand"}}],
                "terms": {"demands": demands, "sweeteners": [], "clauses": [], "type": "ultimatum_demand"},
                "context": {}})
            x.diplomatic_points = 10
            out = CommandExecutor()._diplomatic.handle_diplomatic_dialogue_response(1, {"world": x})
            assert out.get("success"), out
        mission_world, bare = _rx37_both(
            w, lambda x: _rx37_stage(x, "IMPROVE_RELATIONS", "Prussia"), deliver)
        assert mission_world.nation_relations == bare.nation_relations, "the board is untouched"
        shocks = _rx37_shocks(mission_world)
        kinds = [s["kind"] for s in shocks]
        assert "ultimatum" in kinds, shocks
        total = sum(s["delta"] for s in shocks)
        assert total == _r34_rel(mission_world, "France", "Prussia") - 10, (shocks, total)
        from backend.game_logic.diplomatic_dialogue import mission_shock_cause
        by_kind = {s["kind"]: mission_shock_cause(s) for s in shocks}
        assert by_kind["ultimatum"] == "our ultimatum to Prussia"
        if "ultimatum_rejection" in by_kind:
            assert by_kind["ultimatum_rejection"] == "Prussia's rejection of our ultimatum"

    def test_an_ultimatum_that_splashes_a_bystander_is_booked_on_that_pair(self, _r34_w):
        """The splash writes France-Spain when Spain is allied to the target."""
        from backend.commands.executor import CommandExecutor
        w = _r34_w
        _r34_set_state(w, "France", "Bavaria", "PEACE")
        _r34_set_rel(w, "France", "Bavaria", 10)
        _r34_set_state(w, "Bavaria", "Spain", "ALLIANCE")
        _rx37_stage(w, "REASSURE_ALLY", "Spain")
        before = _r34_rel(w, "France", "Spain")
        demands = [{"type": "gold_lump", "value": 5000}]
        w.dialogue_manager.replace({
            "type": "ultimatum_confirm", "target_nation": "Bavaria",
            "turn_created": int(w.current_turn), "prompt": "Deliver?",
            "options": [{"label": "Deliver Ultimatum", "action": "execute_ultimatum",
                         "terms": {"demands": demands, "sweeteners": [], "clauses": [],
                                   "type": "ultimatum_demand"}}],
            "terms": {"demands": demands, "sweeteners": [], "clauses": [], "type": "ultimatum_demand"},
            "context": {}})
        w.diplomatic_points = 10
        with _r34_quiet():
            CommandExecutor()._diplomatic.handle_diplomatic_dialogue_response(1, {"world": w})
        landed = _r34_rel(w, "France", "Spain") - before
        assert landed < 0, "the splash hit the pair"
        shocks = _rx37_shocks(w)
        assert [(s["kind"], s["delta"]) for s in shocks] == [("ultimatum", landed)], shocks

    def test_the_coalitions_leave_join_and_friction_are_booked(self, _r34_w):
        from backend.game_logic import coalition as C
        w = _r34_w
        # friction: -2 a turn between members (an Undermine on two of them)
        mw, bare = _rx37_both(w, lambda x: _rx37_stage(x, "UNDERMINE_ALLIANCE", "Austria", "Britain"),
                              C.process_coalition_turn)
        assert mw.nation_relations == bare.nation_relations
        (shock,) = _rx37_shocks(mw)
        assert (shock["kind"], shock["delta"]) == ("coalition_friction", -2)
        # leaving: -15 with the remaining members
        mw, bare = _rx37_both(w, lambda x: _rx37_stage(x, "UNDERMINE_ALLIANCE", "Russia", "Britain"),
                              lambda x: C.remove_coalition_member("Russia", x))
        assert mw.nation_relations == bare.nation_relations
        (shock,) = _rx37_shocks(mw)
        assert (shock["kind"], shock["delta"], shock["by"], shock["on"]) == (
            "coalition_leave", -15, "Russia", "Britain")
        from backend.game_logic.diplomatic_dialogue import mission_shock_cause
