    def test_the_cap_folds_the_oldest_so_no_shock_is_lost(self, _r34_w):
        from backend.game_logic.diplomatic_dialogue import (
            MISSION_SHOCK_CAP, mission_shock_cause, modify_relation_booked)
        w = _r34_w
        _rx37_stage(w, "IMPROVE_RELATIONS", "Prussia")
        _r34_set_rel(w, "France", "Prussia", 0)
        for i in range(MISSION_SHOCK_CAP + 4):
            modify_relation_booked(w, "France", "Prussia", -1, "ultimatum", "France", f"Prussia{i}")
        shocks = _rx37_shocks(w)
        assert len(shocks) == MISSION_SHOCK_CAP
        assert sum(s["delta"] for s in shocks) == -(MISSION_SHOCK_CAP + 4), "nothing dropped"
        assert shocks[0]["kind"] == "earlier" and shocks[0]["delta"] == -5
        assert mission_shock_cause(shocks[0]) == "earlier events"


