def _rx36_run(w):
    """The part-1 sighting on the shipped board: two funded turns at 20 (each
    +8 and the court's -1 drift), then Prussia declares war on Hanover (-15)."""
    from backend.game_logic import diplomacy as D
    _r34_set_state(w, "France", "Prussia", "PEACE")
    _r34_set_rel(w, "France", "Prussia", 20)
    _rx37_stage(w, "IMPROVE_RELATIONS", "Prussia")
    for _ in range(2):
        w.diplomatic_points = 10
        with _r34_quiet():
            D._process_mission_dp(w)
            D._process_mission_effects(w)
            D._process_relation_decay(w)
    with _r34_quiet():
        res = D.declare_war(w, "Prussia", "Hanover")
    assert res["success"], res


class TestS14EX36:
    """Reproduced: the part-1 sighting reads "+16 earned, -15 from Prussia's
    declaration on Hanover" beside a headline of -1 — the parts sum to +1; the
    court's own -2 (two ticks of decay) is nowhere on the line."""

    def test_the_line_gains_a_derived_drift_term(self, _r34_w):
        from backend.game_logic.diplomatic_dialogue import mission_status
        w = _r34_w
        _rx36_run(w)
        status = mission_status(w)
        assert status["ledger_line"] == (
            "+16 earned, -15 from Prussia's declaration on Hanover, drift -2"), status["ledger_line"]

    def test_the_parts_sum_to_the_headline(self, _r34_w):
        from backend.game_logic.diplomatic_dialogue import mission_status
        w = _r34_w
        _rx36_run(w)
        status = mission_status(w)
        line = status["ledger_line"]
        # every signed figure the line prints (+16, -15, drift -2) ...
        printed = [int(x) for x in re.findall(r"(?:^|, )([+-]\d+)(?= earned| from)", line)]
        drift = int(re.search(r"drift ([+-]\d+)", line).group(1))
        # ... sums to the headline the Cabinet row prints
        assert sum(printed) + drift == status["relation_delta"], (line, printed, drift)
        assert status["earned"] + status["shock_total"] + drift == status["relation_delta"]

    def test_a_quiet_mission_still_says_nothing(self, _r34_w):
        from backend.game_logic import diplomacy as D
        from backend.game_logic.diplomatic_dialogue import mission_status
        w = _r34_w
        _r34_set_state(w, "France", "Prussia", "PEACE")
        _r34_set_rel(w, "France", "Prussia", 20)
        _rx37_stage(w, "IMPROVE_RELATIONS", "Prussia")
        for _ in range(2):
            w.diplomatic_points = 10
            with _r34_quiet():
                D._process_mission_dp(w)
                D._process_mission_effects(w)
                D._process_relation_decay(w)
        assert mission_status(w)["ledger_line"] == "", "the drift alone does not make a quiet line speak"

    def test_a_record_without_books_claims_no_drift(self):
        from backend.game_logic.diplomatic_dialogue import mission_drift, mission_ledger_line
        old = {"type": "IMPROVE_RELATIONS", "target": "Prussia", "initial_relation": 10, "turns_active": 3,
               "shocks": [{"turn": 1, "delta": -5, "kind": "war_declaration", "by": "Prussia", "on": "Hanover"}]}
        assert mission_drift(old, 0) == 0
        assert "drift" not in mission_ledger_line(old, "France", current=0)

    def test_without_the_world_the_line_reads_as_it_did(self, _r34_w):
        from backend.game_logic.diplomatic_dialogue import mission_ledger_line
        w = _r34_w
        _rx36_run(w)
        assert mission_ledger_line(w.active_diplomatic_mission, "France") == (
            "+16 earned, -15 from Prussia's declaration on Hanover")

    def test_every_reader_prints_the_one_line_with_the_drift(self, _r34_w):
        from backend.game_logic import diplomatic_dialogue as DD
        from backend.game_logic import ledger as L
        w = _r34_w
        _rx36_run(w)
        line = DD.mission_status(w)["ledger_line"]
        assert "drift -2" in line
        assert line in _r34_rows(w, "Prussia")["cancel_mission"]["effect_text"]
        assert L.build_cabinet(w)["ledger_line"] == line
        DD.restate_mission_notice(w)
        (row,) = [n for n in w.notifications.get_pending() if n.get("type") == "diplomatic_mission"]
        assert line in row["message"], row["message"]

    def test_the_dispatch_line_and_the_end_beat_carry_it(self, _r34_w):
        from backend.game_logic import diplomatic_dialogue as DD
        from backend.game_logic.dispatch import _build_diplomatic_events_section
        w = _r34_w
        _rx36_run(w)
        w.pending_dispatch_events = [
            {"type": "diplomatic_mission_progress",
             "template_vars": {"nation": "Prussia", "value": 99},
             "fog_rule": "player_mission", "queued_turn": int(w.current_turn)}]
        with _r34_quiet():
            events = _build_diplomatic_events_section(w, "France")
        (line,) = [e for e in events if e["type"] == "diplomatic_mission_progress"]
        assert "drift -2" in line["text"], line
        DD.record_mission_end(w, dict(w.active_diplomatic_mission), "recalled")
        ended = [e for e in w.event_log if e.get("type") == "diplomatic_mission_ended"]
        assert "drift -2" in ended[-1]["ledger_line"], ended[-1]

    def test_an_undermining_reads_the_pair_not_france(self, _r34_w):
        from backend.game_logic import diplomacy as D
        from backend.game_logic.diplomatic_dialogue import mission_status
        from backend.game_logic.diplomatic_dialogue import modify_relation_booked
        w = _r34_w
        _rx37_stage(w, "UNDERMINE_ALLIANCE", "Austria", "Britain")
        before = _r34_rel(w, "Austria", "Britain")
        w.diplomatic_points = 10
        with _r34_quiet():
            D._process_mission_dp(w)
            D._process_mission_effects(w)
        earned = int(w.active_diplomatic_mission["earned"])
        assert earned < 0, "his work lowers the pair"
        # a hand on the pair the books do not know ...
        w.modify_nation_relation("Austria", "Britain", -4)
        # ... and one they do, which makes the line speak
        modify_relation_booked(w, "Austria", "Britain", -1, "coalition_leader")
        status = mission_status(w)
        assert status["current_relation"] - before == earned - 4 - 1
        assert status["ledger_line"] == (
            f"{earned:+d} from him, -1 from the coalition's change of leader, drift -4"), status["ledger_line"]


