# ══════════════════════════════════════════════════════════════════════════
# S14E-D11 (the ruling) / S14E-X68 (its defect half) - the mean, exact
# ══════════════════════════════════════════════════════════════════════════
# Cause: the header's "expect about N" is `committed_strength`: each joiner's
# share priced under ONE coordination stamp (`_priced_coordination` with every
# corps that can arrive present) times his own arrival odds. The resolver
# stamps the bonus on the corps that ARRIVE, so a day with fewer arrivals
# carries a smaller bonus and the one-stamp mean sat above the true expectation
# - on the 1805 boot, Davout on Mack printed 109,122 against an exact 107,570
# (1.4%). The floor and the bad day were already exact (S14E-12).
#
# Fix (ruled "re-seat it, on the series arms"): `_muster_outcome_set` - the one
# enumeration (2^N, each outcome under its own `_priced_coordination`) the
# floor, the bad day AND NOW THE MEAN are read from - and the SEAM
# `CombatExecutor._muster_mean_exact(outcome_set)`, the probability-weighted
# mean (None -> today's one-stamp mean: the AI's lead, nobody uncertain, more
# uncertain corps than `MUSTER_SPREAD_MAX_UNCERTAIN`, or the S14E-12 lever
# down). `_build_muster_preview` and `muster_odds` (the gate) both read it, so
# the screen, the band, the CA9 gate and the objection's totals agree.

_RD11_SCENARIO = _R17_SCENARIO


def _rd11_quiet():
    return contextlib.redirect_stdout(io.StringIO())


def _rd11_combat():
    from backend.commands.executor import CommandExecutor
    with _rd11_quiet():
        return CommandExecutor()._combat


@pytest.fixture(scope="module")
def _rd11_boot():
    from backend.models.world_state import WorldState
    with _rd11_quiet():
        return WorldState.from_scenario(str(_RD11_SCENARIO))


@pytest.fixture
def _rd11_mack(_rd11_boot):
    """The 1805 boot, Mack at 52,000 (so the muster reads Davout's campaign
    the way the sighting did)."""
    from backend.models.world_state import WorldState
    w = WorldState.from_dict(json.loads(json.dumps(_rd11_boot.to_dict(), default=str)))
    w.get_marshal("Mack").strength = 52000
    w.calculate_visibility()
    return w


def _rd11_muster(w, lead, foe, ex=None) -> dict:
    ex = ex or _rd11_combat()
    with _rd11_quiet():
        return ex._build_muster_preview(w.get_marshal(lead), w.get_marshal(foe),
                                        w, {"world": w})


def _rd11_old_seam(monkeypatch) -> None:
    """The orchestrator's arm: the one-stamp mean back, by swapping the seam."""
    from backend.commands.combat_executor import CombatExecutor
    monkeypatch.setattr(CombatExecutor, "_muster_mean_exact",
                        lambda self, outcome_set: None)


def _rd11_exact_by_hand(w, lead_name, foe_name, ex) -> float:
    """The exact expectation of the lead's committed strength, enumerated here
    from the per-corps arrival odds - the subsets of the corps that can arrive,
    each priced under its own coordination - without the code under test's
    outcome set."""
    lead, foe = w.get_marshal(lead_name), w.get_marshal(foe_name)
    battle = foe.location
    region = w.get_region(battle)
    joiners = [m for m in w.marshals.values()
               if m.nation == lead.nation and m.name != lead.name and m.strength > 0
               and (m.location == battle or m.location in set(region.adjacent_regions))
               and ex._muster_reason(m, lead, battle, lead.nation, w)[0]]
    foes, _ = ex._defender_muster(foe, w)
    foes = ex._reachable_joiners(foe, foes, w, battle, active=True)
    odds = {m.name: ex._expected_arrival_weight(lead, m, w, battle) for m in joiners}
    live = [m for m in joiners if odds[m.name] > 0.0]
    mean = 0.0
    for mask in range(1 << len(live)):
        team, p = [], 1.0
        for i, m in enumerate(live):
            if mask >> i & 1:
                team.append(m)
                p *= odds[m.name]
            else:
                p *= 1.0 - odds[m.name]
        if p <= 0.0:
            continue
        with ex._priced_coordination(lead, team, foe, foes, w, battle):
            mean += p * ex._committed_reinforcement_strength(lead, team, w)
    return mean


class TestS14ED11:
    """Reproduced (the shipped 1805 board, Davout on Mack at 52,000, before the
    fix): the header printed "expect about 109,122 with the corps likely to
    arrive, up to 115,003 if all march; certain 26,000; a bad day (1 in 10)
    93,730" - the exact per-outcome expectation of the same arithmetic was
    107,570."""

    def test_the_header_prints_the_exact_expectation(self, _rd11_mack):
        w, ex = _rd11_mack, _rd11_combat()
        exact = _rd11_exact_by_hand(w, "Davout", "Mack", ex)
        pv = _rd11_muster(w, "Davout", "Mack", ex)
        lead = w.get_marshal("Davout")
        assert pv["attacker"]["committed_strength"] == int(lead.strength + exact)
        text = ex._format_muster_lines(pv)
        assert f"expect about {int(lead.strength + exact):,} with the corps likely" in text, text

    def test_it_sits_below_the_one_stamp_mean_it_replaces(self, _rd11_mack, monkeypatch):
        w, ex = _rd11_mack, _rd11_combat()
        new = _rd11_muster(w, "Davout", "Mack", ex)["attacker"]["committed_strength"]
        _rd11_old_seam(monkeypatch)
        old = _rd11_muster(w, "Davout", "Mack", ex)["attacker"]["committed_strength"]
        assert new < old                                       # the over-statement, gone
        assert 0.005 < (old - new) / old < 0.03                # about 1.4% on the boot

    def test_the_floor_the_mean_and_the_ceiling_are_ordered(self, _rd11_mack):
        pv = _rd11_muster(_rd11_mack, "Davout", "Mack")
        att = pv["attacker"]
        assert att["floor_strength"] <= att["bad_day_strength"] < att["committed_strength"]
        assert att["committed_strength"] < att["ceiling_strength"]

    def test_the_gate_reads_the_screens_mean(self, _rd11_mack):
        """`muster_odds` (the CA9 / glory gate) and the preview (the screen):
        one figure, one band, one ratio."""
        w, ex = _rd11_mack, _rd11_combat()
        pv = _rd11_muster(w, "Davout", "Mack", ex)
        with _rd11_quiet():
            odds = ex.muster_odds(w.get_marshal("Davout"), w.get_marshal("Mack"), w)
        lead = w.get_marshal("Davout")
        assert int(lead.strength + odds["committed_attacker"]) == pv["attacker"]["committed_strength"]
        assert odds["band"] == pv["odds_band"]

    def test_the_band_reads_the_re_seated_figure(self, _rd11_mack, monkeypatch):
        """The ratio the band reads moves with the mean (smaller, never larger)."""
        w, ex = _rd11_mack, _rd11_combat()
        lead, foe = w.get_marshal("Davout"), w.get_marshal("Mack")
        with _rd11_quiet():
            new = ex.muster_odds(lead, foe, w)
        _rd11_old_seam(monkeypatch)
        with _rd11_quiet():
            old = ex.muster_odds(lead, foe, w)
        assert new["committed_attacker"] < old["committed_attacker"]
        assert new["ratio"] < old["ratio"]
        assert new["committed_defender"] == old["committed_defender"]   # his side untouched

    def test_the_objections_totals_are_the_screens_figures(self, _rd11_mack):
        from backend.commands.objection_v2 import muster_expected_totals
        w = _rd11_mack
        pv = _rd11_muster(w, "Davout", "Mack")
        with _rd11_quiet():
            totals = muster_expected_totals(w.get_marshal("Davout"), w.get_marshal("Mack"), w)
        assert totals == (pv["attacker"]["committed_strength"],
                          pv["target"]["committed_strength"])

    def test_the_state_is_restored(self, _rd11_mack):
        """The enumeration prices hypotheticals and leaves nobody stamped or moved."""
        w = _rd11_mack
        keep = lambda: {n: (m.location, getattr(m, "total_coordination_attack_bonus", None),  # noqa: E731
                            getattr(m, "sovereign_presence", None))
                        for n, m in w.marshals.items()}
        before = keep()
        _rd11_muster(w, "Davout", "Mack")
        assert keep() == before


# - a small board whose corps differ in type and distance (the stamp differs by
# outcome), the resolver's own stamping as the independent measure ------------

def _rd11_board(extra=0, co_located=False, drop=()):
    """Alpha (cautious infantry) on Foe at Belgium; Bravo and Charlie
    (infantry) and Delta (cavalry) a march away, each uncertain."""
    from tests.conftest import MarshalFactory, WorldFactory
    lead = MarshalFactory.infantry(name="Alpha", location="Belgium",
                                   strength=20000, personality="cautious")
    bravo = MarshalFactory.infantry(name="Bravo", location="Paris",
                                    strength=18000, personality="aggressive")
    charlie = MarshalFactory.infantry(name="Charlie", location="Normandy",
                                      strength=15000, personality="aggressive")
    delta = MarshalFactory.cavalry(name="Delta", location="Waterloo",
                                   strength=9000, personality="aggressive")
    foe = MarshalFactory.enemy(name="Foe", location="Belgium", nation="Austria",
                               strength=40000, personality="cautious")
    ms = [lead, bravo, charlie, delta, foe]
    if co_located:
        ms.append(MarshalFactory.infantry(name="Echo", location="Belgium",
                                          strength=6000, personality="aggressive"))
    for i in range(extra):
        ms.append(MarshalFactory.infantry(
            name=f"Extra{i}", location=("Paris", "Normandy", "Rhineland")[i % 3],
            strength=5000 + 500 * i, personality="aggressive"))
    w = WorldFactory.with_marshals(ms)
    key = "|".join(sorted(["France", "Austria"]))
    w.diplomatic_states[key] = "WAR"
    w.war_start_turns[key] = w.current_turn
    w.marshals["Bravo"].skills["logistics"] = 5
    w.marshals["Charlie"].skills["logistics"] = 3
    w.marshals["Delta"].skills["logistics"] = 3
    for i in range(extra):
        w.marshals[f"Extra{i}"].skills["logistics"] = 3
    w.get_region("Normandy").terrain = "plains"
    w.get_region("Waterloo").terrain = "plains"
    for name in drop:
        del w.marshals[name]
    w.calculate_visibility()
    return w


def _rd11_applied(arrivals, **board) -> float:
    """What the RESOLVER masses when exactly `arrivals` come: relocate them to
    the field, stamp the coordination the way `_attack_reinforce_and_coordinate`
    does (excluding the arrived names, read on the field), sum the committed term."""
    ex = _rd11_combat()
    w = _rd11_board(**board)
    lead = w.marshals["Alpha"]
    team = [w.marshals[n] for n in arrivals]
    for m in team:
        m.location = "Belgium"
    ex._calculate_coordination_context(
        lead, w, exclude_from_adjacent=set(arrivals), field="Belgium")
    return float(ex._committed_reinforcement_strength(lead, team, w))


def _rd11_applied_mean(names, **board) -> float:
    """The exact expectation of the applied committed strength: every subset of
    `names`, at its probability, valued by the resolver's own stamping."""
    ex = _rd11_combat()
    w = _rd11_board(**board)
    lead = w.marshals["Alpha"]
    odds = {n: ex._expected_arrival_weight(lead, w.marshals[n], w, "Belgium") for n in names}
    mean = 0.0
    for mask in range(1 << len(names)):
        arrivals, p = [], 1.0
        for i, n in enumerate(names):
            if mask >> i & 1:
                arrivals.append(n)
                p *= odds[n]
            else:
                p *= 1.0 - odds[n]
        mean += p * _rd11_applied(tuple(arrivals), **board)
    return mean


def _rd11_alpha(w, ex=None) -> dict:
    return _rd11_muster(w, "Alpha", "Foe", ex)


class TestS14ED11Applied:
    """Shown == applied: the printed mean is the probability-weighted mean of
    what the resolver would mass in each outcome."""

    def test_the_mean_is_the_resolvers_own_expectation(self):
        ex = _rd11_combat()
        pv = _rd11_alpha(_rd11_board(), ex)
        mean = _rd11_applied_mean(("Bravo", "Charlie", "Delta"))
        assert pv["attacker"]["committed_strength"] == int(20000 + mean)

    def test_the_one_stamp_mean_the_seam_falls_back_to_is_the_old_arithmetic(self, monkeypatch):
        """The seam swapped for None is PT-A2's mean: the per-corps odds times
        the per-corps share under the stamp of them all - what the orchestrator's
        series arm restores."""
        ex = _rd11_combat()
        _rd11_old_seam(monkeypatch)
        w = _rd11_board()
        pv = _rd11_alpha(w, ex)
        lead = w.marshals["Alpha"]
        team = [w.marshals[n] for n in ("Bravo", "Charlie", "Delta")]
        with ex._priced_coordination(lead, team, w.marshals["Foe"], [], w, "Belgium"):
            expect = sum(
                ex._expected_arrival_weight(lead, m, w, "Belgium")
                * ex._committed_share(lead, m, ex._pair_contribution_scale(lead, m))
                for m in team)
        assert pv["attacker"]["committed_strength"] == int(lead.strength + expect)
        exact = _rd11_applied_mean(("Bravo", "Charlie", "Delta"))
        assert int(lead.strength + exact) < pv["attacker"]["committed_strength"]

    def test_six_uncertain_corps_are_still_exact(self):
        """Exactly the cap: the whole outcome set is enumerated (64 outcomes)."""
        ex = _rd11_combat()
        names = ("Bravo", "Charlie", "Delta", "Extra0", "Extra1", "Extra2")
        pv = _rd11_alpha(_rd11_board(extra=3), ex)
        mean = _rd11_applied_mean(names, extra=3)
        assert pv["attacker"]["committed_strength"] == int(20000 + mean)

    def test_beyond_the_cap_the_one_stamp_mean_stands(self, monkeypatch):
        """Seven uncertain corps: the set is a truncation (the rest taken as not
        arriving), so the mean must not be read from it - the printed figure is
        the one-stamp mean, exactly as the seam's fallback computes it."""
        ex = _rd11_combat()
        up = _rd11_alpha(_rd11_board(extra=4), ex)
        _rd11_old_seam(monkeypatch)
        down = _rd11_alpha(_rd11_board(extra=4), ex)
        assert up["attacker"]["committed_strength"] == down["attacker"]["committed_strength"]
        assert "bad_day_strength" not in up["attacker"]          # withheld, as S14E-12
        assert "floor_strength" in up["attacker"]

    def test_no_uncertain_corps_means_the_stamp_is_already_exact(self, monkeypatch):
        """Only a corps on the field: one outcome; nothing to re-seat."""
        ex = _rd11_combat()
        alone = dict(co_located=True, drop=("Bravo", "Charlie", "Delta"))
        up = _rd11_alpha(_rd11_board(**alone), ex)
        _rd11_old_seam(monkeypatch)
        down = _rd11_alpha(_rd11_board(**alone), ex)
        assert up["attacker"]["committed_strength"] == down["attacker"]["committed_strength"]
        assert up["attacker"]["committed_strength"] == int(20000 + _rd11_applied(("Echo",), **alone))

    def test_the_ceiling_the_floor_and_the_band_words_are_the_same_lines(self):
        ex = _rd11_combat()
        pv = _rd11_alpha(_rd11_board(), ex)
        att = pv["attacker"]
        assert att["floor_strength"] == int(20000 + _rd11_applied(()))
        assert att["ceiling_strength"] == int(20000 + _rd11_applied(("Bravo", "Charlie", "Delta")))
        assert att["floor_strength"] < att["committed_strength"] < att["ceiling_strength"]
        text = ex._format_muster_lines(pv)
        assert f"expect about {att['committed_strength']:,}" in text
        assert f"up to {att['ceiling_strength']:,} if all march" in text

    def test_the_lever_down_is_the_pre_s14e_12_mean(self, monkeypatch):
        """`A_CORPS_THAT_CANNOT_ARRIVE_IS_NOT_PRESENT` down keeps the one-stamp
        mean (the pre-S14E-12 muster stamps a corps that cannot arrive)."""
        import backend.commands.combat_executor as CE
        ex = _rd11_combat()
        up = _rd11_alpha(_rd11_board(), ex)
        monkeypatch.setattr(CE, "A_CORPS_THAT_CANNOT_ARRIVE_IS_NOT_PRESENT", False)
        down = _rd11_alpha(_rd11_board(), ex)
        assert up["attacker"]["committed_strength"] < down["attacker"]["committed_strength"]


class TestS14ED11TheAIsReads:
    """Golden Rule 5: the re-seat was the player's lead's. (S14E-X215, S14f p3:
    the nation gate is lifted - the AI's `muster_odds`, the jealousy P3.9
    rung, reads the exact mean through the same seam; the two AI pins below
    were flipped, and the seam's down value is still the one-stamp mean.)"""

    def _austrian(self):
        from tests.conftest import MarshalFactory, WorldFactory
        lead = MarshalFactory.enemy(name="Karl", location="Belgium", nation="Austria",
                                    strength=20000, personality="cautious")
        j = MarshalFactory.enemy(name="Jodl", location="Paris", nation="Austria",
                                 strength=18000, personality="aggressive")
        k = MarshalFactory.enemy(name="Kurt", location="Normandy", nation="Austria",
                                 strength=15000, personality="aggressive")
        z = MarshalFactory.enemy(name="Zeta", location="Waterloo", nation="Austria",
                                 strength=9000, personality="aggressive")
        z.cavalry = True
        fr = MarshalFactory.infantry(name="Foe", location="Belgium", strength=30000)
        w = WorldFactory.with_marshals([lead, j, k, z, fr])
        key = "|".join(sorted(["France", "Austria"]))
        w.diplomatic_states[key] = "WAR"
        w.war_start_turns[key] = w.current_turn
        for m in (j, k, z):
            m.skills["logistics"] = 4
        w.get_region("Waterloo").terrain = "plains"
        w.get_region("Normandy").terrain = "plains"
        w.calculate_visibility()
        return w

    def test_an_ais_outcome_set_is_none(self):
        # S14E-X215 (S14f p3): FLIPPED - D11's player-only nation gate is
        # lifted; an AI lead has an outcome set (the seam below is still the
        # one switch). The nothing-to-read cases stay None.
        ex = _rd11_combat()
        w = self._austrian()
        lead, foe = w.marshals["Karl"], w.marshals["Foe"]
        joiners = [w.marshals[n] for n in ("Jodl", "Kurt", "Zeta")]
        assert ex._muster_outcome_set(lead, joiners, foe, [], w, "Belgium") is not None
        assert ex._muster_outcome_set(lead, [], foe, [], w, "Belgium") is None
        assert ex._muster_mean_exact(None) is None

    def test_an_ais_muster_odds_do_not_move_with_the_seam(self, monkeypatch):
        # S14E-X215 (S14f p3): FLIPPED - the AI's lead reads D11's seam like
        # the player's: the exact mean is smaller than the one-stamp mean it
        # replaces, and the seam swapped for None restores that one-stamp
        # mean for the AI too.
        ex = _rd11_combat()
        w = self._austrian()
        with _rd11_quiet():
            up = ex.muster_odds(w.marshals["Karl"], w.marshals["Foe"], w)
        assert up["committed_attacker"] > 0
        _rd11_old_seam(monkeypatch)
        w = self._austrian()
        with _rd11_quiet():
            down = ex.muster_odds(w.marshals["Karl"], w.marshals["Foe"], w)
        assert up["committed_attacker"] < down["committed_attacker"]
        assert up["ratio"] < down["ratio"]

    def test_the_defenders_muster_is_untouched(self, monkeypatch):
        """The defender's term (`_defender_muster`, also read by the AI's
        `_muster_price`) does not move with the ATTACKER's seam. (S14E-D12,
        S14f p3: flipped in its words - the defender's term is now itself
        re-seated, on its OWN seam `_defender_mean_exact`; this pin keeps
        the two seams independent.)"""
        ex = _rd11_combat()
        w = _rd11_board()
        before = ex._defender_muster(w.marshals["Foe"], w)
        _rd11_old_seam(monkeypatch)
        assert ex._defender_muster(w.marshals["Foe"], w) == before


class TestS14EX68:
    """The defect half of D11. Reproduced: the boot's Davout-on-Mack header
    printed 109,122 beside an exact 107,570 (1.4% above) - the one-stamp mean
    kept by S14E-12 (PT-A2). The header is now the exact figure; the old one is
    the seam's fallback."""

    def test_the_boot_header_is_not_the_one_stamp_figure(self, _rd11_mack, monkeypatch):
        w, ex = _rd11_mack, _rd11_combat()
        text = ex._format_muster_lines(_rd11_muster(w, "Davout", "Mack", ex))
        shown = int(re.search(r"expect about ([\d,]+)", text).group(1).replace(",", ""))
        _rd11_old_seam(monkeypatch)
        old = int(_rd11_muster(w, "Davout", "Mack", ex)["attacker"]["committed_strength"])
        assert shown < old
        assert shown == int(w.get_marshal("Davout").strength
                            + _rd11_exact_by_hand(w, "Davout", "Mack", ex))

    def test_the_what_if_and_the_attack_print_the_same_mean(self, _rd11_mack):
        from backend.ai.question_desk import _answer_what_if
        w, ex = _rd11_mack, _rd11_combat()
        pv = _rd11_muster(w, "Davout", "Mack", ex)
        with _rd11_quiet():
            answer = _answer_what_if(w, "France", "Mack", "Davout")
        m = re.search(r"expect about ([\d,]+)", answer)
        assert m and int(m.group(1).replace(",", "")) == pv["attacker"]["committed_strength"]


class TestS14EX75:
    """Sweep sibling of S14E-17 (the jealousy autonomous attack's refusal
    beat): "the odds held him - 1 to 2 against Archduke John's position at
    Tyrol" quotes the ratio the muster's band reads, the defender's unscouted
    muster folded in, with nothing to say so. Reproduced on the boot (Murat
    eyeing a 60,000-man John at Tyrol, Charles at Carniola unscouted): the
    beat ended "...his orders are unchanged." Fixed: the same gap-naming line
    follows it when the held reading weighs a force the player has not
    scouted."""

    def _held(self, w):
        from backend.commands.executor import CommandExecutor
        from backend.models.marshal import StrategicOrder
        import backend.game_logic.jealousy as J
        murat = w.get_marshal("Murat")
        john = w.get_marshal("ArchdukeJohn")
        murat.location = "Munich"
        murat.jealous_of = "Ney"
        murat.jealousy_turns_remaining = 4
        murat.jealousy_autonomous_warned = True
        john.location = "Tyrol"
        john.strength = 60000
        john.fortified = True
        john.defense_bonus = 0.12
        w.get_marshal("ArchdukeCharles").location = "Carniola"
        w.get_marshal("Mack").location = "Bohemia"
        for name in ("Ney", "Davout", "Lannes"):
            w.get_marshal(name).location = "Munich"
        w.calculate_visibility()
        murat.strategic_order = StrategicOrder(
            command_type="MOVE_TO", target="Vienna", target_type="region",
            started_turn=w.current_turn, original_command="move to Vienna")
        with _r17_quiet():
            ex = CommandExecutor()
            J.process_autonomous_attacks(w, ex, {"world": w})
        events = [e for e in getattr(w, "_pending_jealousy_turn_events", [])
                  if e["type"] == "jealousy_autonomous_refused" and e.get("held_by_odds")]
        assert events, "the odds should have held him"
        return events[-1]["message"]

    def test_the_beat_names_the_gap_after_the_odds(self, _r17_w):
        message = self._held(_r17_w)
        assert "the odds held him — 1 to " in message
        assert message.endswith(f"his orders are unchanged. {_R17_LINE}"), message

    def test_a_scouted_muster_leaves_the_beat_as_it_was(self, _r17_w):
        from backend.models.intel import PARTIAL
        _r17_w.get_region_intel("Carniola").visibility = PARTIAL
        message = self._held(_r17_w)
        assert "have not scouted" not in message
        assert message.endswith("his orders are unchanged."), message

# ========== S14f part 2 - merged from test_s14f_p2_offer.py ==========

# ══════════════════════════════════════════════════════════════════════════
# S14f part 2 — the table's offer row opens at the counsel's sum
# ══════════════════════════════════════════════════════════════════════════
# S14E-D7 (the ruling, YES October 25, 2026) and its defect half S14E-X34
# (DD-B re-measure, diplomacy-first #6, `docs/BUG_FIXES.md` §S14E).
#
# The counsel's lever (S14E-8) says "A payment of 875 gold to Britain would
# carry the table with her alone. At the table: Open Settlement with Britain
# alone, then Offer gold to Britain, 875 or more (the + and - on its line
# move it by 100)." The table's offer row opened at its default (300), six
# presses of + from the sum the counsel quoted — and the Cabinet carried NO
# control for "Open Settlement with Britain alone" at all while the lever was
# said (the counsel stamps the alone coverage only on the road that CARRIES,
# and a lever is said only where the alone table does not): the lever named a
# road with no row.
#
# Fix: ONE Cabinet row for the lever's road (`cabinet_rows.lever_table_actions`,
# read from the counsel's own `table_alone` dry run) carries `gold_offer` —
# the very `gold_to_carry` the sentence quotes — beside `counsel_coverage`; the
# wizard forwards it (`diplomacy_wizard._structured_payload_for_action`), the
# request model carries it (`CommandRequest.gold_offer`), main copies it into
# the parsed command, and the open-settlement arm stages it the way `bond_bid`
# stages the bid (`cabinet_rows.lever_offer_opening_terms` over
# `bond.bid_opening_terms`, funded or not at all). A table opened any other way
# keeps its default.

_RD7_ROOT = Path(__file__).resolve().parents[1]
_RD7_SCENARIO = (_RD7_ROOT / "godot-client" / "project-sovereign" / "assets"
                 / "maps" / "europe_1805.json")
_RD7_WIZARD = (_RD7_ROOT / "godot-client" / "project-sovereign" / "scripts"
               / "diplomacy_wizard.gd")


@pytest.fixture(scope="module")
def _rd7_boot():
    from backend.models.world_state import WorldState
    with contextlib.redirect_stdout(io.StringIO()):
        return WorldState.from_scenario(str(_RD7_SCENARIO))


@pytest.fixture
def _rd7_world(_rd7_boot):
    """The Third Coalition board at 20 / 20 / 20 — the board on which the
    counsel's lever is said — with a treasury that can fund it."""
    from backend.models.world_state import WorldState
    w = WorldState.from_dict(json.loads(json.dumps(_rd7_boot.to_dict(), default=str)))
    w.diplomatic_points = 30
    w.nation_gold["France"] = 3000
    for other in ("Britain", "Austria", "Russia"):
        key = w._make_diplo_key("France", other)
        w.war_scores[key] = 20 if key.split("|")[0] == "France" else -20
    return w


@pytest.fixture
def _rd7_client(monkeypatch, _rd7_world):
    import backend.main as M
    from backend.commands.parser import CommandParser
    from fastapi.testclient import TestClient
    for key in ("SOVEREIGN_SCENARIO", "SOVEREIGN_MAP", "SOVEREIGN_SMOKE_START"):
        monkeypatch.delenv(key, raising=False)
    monkeypatch.setenv("LLM_MODE", "mock")
    monkeypatch.setattr(M, "world", _rd7_world)
    monkeypatch.setitem(M.game_state, "world", _rd7_world)
    monkeypatch.setattr(M, "parser", CommandParser(use_real_llm=False))
    return TestClient(M.app), _rd7_world


def _rd7_quiet(fn, *args, **kwargs):
    with contextlib.redirect_stdout(io.StringIO()):
        return fn(*args, **kwargs)


def _rd7_post(client, body: dict) -> dict:
    with contextlib.redirect_stdout(io.StringIO()):
        return client.post("/command", json=body).json()


def _rd7_preview(w, court: str = "Britain") -> dict:
    from backend.game_logic.diplomacy import get_diplomatic_preview
    return _rd7_quiet(get_diplomatic_preview, w, court)


def _rd7_alone_road(preview: dict) -> dict:
    return next(r for r in preview["counsel_roads"] if r["road"] == "table_alone")


def _rd7_lever_rows(preview: dict, court: str = "Britain") -> list:
    return [a for a in preview["actions"]
            if a.get("action") == "open_settlement"
            and list(a.get("counsel_coverage") or []) == [court]]


def _rd7_wizard_body(row: dict, nation: str = "Britain") -> dict:
    """What `diplomacy_wizard._structured_payload_for_action("open_settlement")`
    sends for this Cabinet row (pinned against the GDScript source below)."""
    body = {"command": f"propose common peace with {nation}",
            "action": "propose_common_peace", "target_nation": nation}
    if row.get("war_id"):
        body["war_id"] = str(row["war_id"])
    if row.get("counsel_coverage"):
        body["counsel_coverage"] = list(row["counsel_coverage"])
    gold = int(float(row.get("gold_offer", 0) or 0))
    if gold > 0:
        body["gold_offer"] = gold
    return body


def _rd7_court_card(dialogue: dict, court: str = "Britain") -> dict:
    return next(r for r in dialogue["per_court_acceptance"] if r["nation"] == court)


def _rd7_offers(card: dict) -> list:
    return [s for s in card.get("demand_suggestions", [])
            if s.get("group") == "offer" and s.get("clause_type") == "gold_indemnity"]


def _rd7_gold_terms(dialogue: dict) -> list:
    return [t for t in dialogue["settlement_terms"] if t.get("type") == "gold_indemnity"]


class TestS14ED7:
    """Reproduced (before the fix, on the shipped 1805 board at 20 / 20 / 20,
    France holding 3,000 gold): the Britain page's counsel line quotes "A
    payment of 875 gold to Britain would carry the table with her alone" and
    the Cabinet carries NO row for the court alone (the single
    `open_settlement` row reads "the whole table: Britain, Austria and
    Russia"); the alone table opened by hand (`counsel_coverage: ["Britain"]`)
    stages `[peace]` and its offer row reads "Offer 300 gold to Britain" —
    575 gold, six presses of +, short of the sum the sentence quotes."""

    # ── the lever has a row ──────────────────────────────────────────────

    def test_the_lever_names_a_road_and_the_cabinet_carries_it(self, _rd7_world):
        from backend.game_logic import counsel as CS
        w = _rd7_world
        preview = _rd7_preview(w)
        alone = _rd7_alone_road(preview)
        gold = int(alone["gold_to_carry"])
        assert gold > 0 and not alone["carries"], alone
        reading = _rd7_quiet(CS.read_counsel, w, "Britain")
        assert "At the table: Open Settlement with Britain alone" in CS._lever_sentence(reading)
        rows = _rd7_lever_rows(preview)
        assert len(rows) == 1, [a["display_name"] for a in preview["actions"]
                                if a["action"] == "open_settlement"]
        row = rows[0]
        assert row["display_name"].startswith("Open Settlement with Britain alone"), row["display_name"]
        assert row["available"] and row["war_id"] == alone["war_id"]
        assert row["addresses"] == ["Britain"]

    def test_the_row_carries_the_sum_the_sentence_quotes(self, _rd7_world):
        """Shown == applied, the first half: the figure on the row is the
        lever sentence's own (`counsel._lever_sentence`), as an integer."""
        from backend.game_logic import counsel as CS
        w = _rd7_world
        reading = _rd7_quiet(CS.read_counsel, w, "Britain")
        gold = int(next(r for r in reading["roads"] if r["road"] == "table_alone")["gold_to_carry"])
        sentence = CS._lever_sentence(reading)
        assert f"{gold} or more" in sentence
        row = _rd7_lever_rows(_rd7_preview(w))[0]
        assert row["gold_offer"] == gold and isinstance(row["gold_offer"], int)
        assert f"{gold} gold" in row["effect_text"], row["effect_text"]

    def test_the_whole_table_row_is_still_the_first_and_unchanged(self, _rd7_world):
        """The lever row joins the page; the whole-table row stays first, with
        no staged sum and no coverage stamp."""
        preview = _rd7_preview(_rd7_world)
        tables = [a for a in preview["actions"] if a["action"] == "open_settlement"]
        assert len(tables) == 2
        whole = tables[0]
        assert "counsel_coverage" not in whole and "gold_offer" not in whole
        assert whole["display_name"].startswith("Open Settlement")
        assert "whole table" in whole["display_name"]
        assert tables[1] is not whole and tables[1]["gold_offer"] > 0

    # ── the table opens at the sum ───────────────────────────────────────

    def test_the_table_opens_staged_at_the_quoted_sum_and_carries(self, _rd7_client):
        """The whole chain through the real endpoint: the row's payload (as the
        wizard sends it) opens the table with the offer staged at the quoted
        sum — the staged term, the line the player reads and the figure that
        carries Britain are ONE number."""
        client, w = _rd7_client
        row = _rd7_lever_rows(_rd7_preview(w))[0]
        gold = int(row["gold_offer"])
        opened = _rd7_post(client, _rd7_wizard_body(row))
        dialogue = opened["diplomatic_dialogue"]
        assert dialogue["type"] == "settlement_confirm", opened.get("message")
        terms = _rd7_gold_terms(dialogue)
        assert len(terms) == 1, dialogue["settlement_terms"]
        assert (terms[0]["from"], terms[0]["to"], int(terms[0]["amount"])) == ("France", "Britain", gold)
        card = _rd7_court_card(dialogue)
        line = next(l for l in card["current_demands"] if l["clause_type"] == "gold_indemnity")
        assert line["line_display"] == f"France pays {gold} gold"
        assert int(line["magnitude"]["amount"]) == gold
        # the lever said it would carry: the table does
        assert int(card["total"]) >= int(card["threshold"]), (card["total"], card["threshold"])
        assert dialogue["covered_enemy_participants"] == ["Britain"]

    def test_the_staged_offer_is_the_players_own_line(self, _rd7_client):
        """The click authored it, as the Offer row's press does: the dial
        sweep protects a line the player authored and the line says so."""
        client, w = _rd7_client
        row = _rd7_lever_rows(_rd7_preview(w))[0]
        dialogue = _rd7_post(client, _rd7_wizard_body(row))["diplomatic_dialogue"]
        assert _rd7_gold_terms(dialogue)[0].get("authored_by") == "player"

    def test_the_plus_and_minus_step_the_staged_line_by_the_lever_stride(self, _rd7_client):
        """The sentence's "(the + and - on its line move it by 100)" is true of
        the staged line: the table's magnitude verb (what the line's + and -
        fire, absolute values a stride apart) moves the opened sum by exactly
        `SETTLEMENT_DIAL_GOLD_STEP`."""
        from backend.game_logic.settlement_actions import handle_settlement_dialogue_action
        from backend.game_logic.settlement_baseline import SETTLEMENT_DIAL_GOLD_STEP
        client, w = _rd7_client
        row = _rd7_lever_rows(_rd7_preview(w))[0]
        gold = int(row["gold_offer"])
        dialogue = _rd7_post(client, _rd7_wizard_body(row))["diplomatic_dialogue"]
        index = next(i for i, t in enumerate(dialogue["settlement_terms"])
                     if t.get("type") == "gold_indemnity")
        step = int(SETTLEMENT_DIAL_GOLD_STEP)
        assert step == 100
        for amount in (gold - step, gold + step, gold):
            result = _rd7_quiet(
                handle_settlement_dialogue_action, w, action="settlement_demand_set_magnitude",
                dialogue=w.dialogue_manager.peek(),
                action_params={"clause_index": index, "expected_type": "gold_indemnity",
                               "amount": amount})
            assert result["success"], result.get("message")
            assert [int(t["amount"]) for t in _rd7_gold_terms(result["diplomatic_dialogue"])] == [amount]

    # ── a table opened any other way is unchanged ────────────────────────

    def test_the_alone_table_opened_without_the_key_keeps_its_default(self, _rd7_client):
        from backend.game_logic.settlement_baseline import CONCESSION_BASELINE_GOLD_FLOOR
        client, w = _rd7_client
        row = _rd7_lever_rows(_rd7_preview(w))[0]
        body = _rd7_wizard_body(row)
        body.pop("gold_offer")
        dialogue = _rd7_post(client, body)["diplomatic_dialogue"]
        assert dialogue["settlement_terms"] == [{"type": "peace"}], dialogue["settlement_terms"]
        offers = _rd7_offers(_rd7_court_card(dialogue))
        assert offers and offers[0]["label"] == \
            f"Offer {int(CONCESSION_BASELINE_GOLD_FLOOR)} gold to Britain"

    def test_the_whole_table_row_opens_exactly_as_before(self, _rd7_client):
        client, w = _rd7_client
        preview = _rd7_preview(w)
        whole = next(a for a in preview["actions"] if a["action"] == "open_settlement")
        body = _rd7_wizard_body(whole)
        assert "gold_offer" not in body and "counsel_coverage" not in body
        dialogue = _rd7_post(client, body)["diplomatic_dialogue"]
        assert _rd7_gold_terms(dialogue) == []
        assert sorted(dialogue["covered_enemy_participants"]) == ["Austria", "Britain", "Russia"]

    def test_reopening_the_lever_does_not_stack_a_second_payment(self, _rd7_client):
        client, w = _rd7_client
        row = _rd7_lever_rows(_rd7_preview(w))[0]
        first = _rd7_post(client, _rd7_wizard_body(row))["diplomatic_dialogue"]
        staged = _rd7_gold_terms(first)
        assert len(staged) == 1
        again = _rd7_post(client, _rd7_wizard_body(row))["diplomatic_dialogue"]
        assert _rd7_gold_terms(again) == staged

    def test_the_click_after_a_back_out_still_stages_the_payment(self, _rd7_client):
        """Reproduced: open the whole table, Back Out, click the lever - the
        war's draft is restored (`draft_restored_from_scope`) and the lever's
        payment was never staged, so the row said "opens with 875 gold
        staged" and the table opened without it. The restored draft keeps its
        lines and takes the payment as its one gold line to the court."""
        client, w = _rd7_client
        preview = _rd7_preview(w)
        whole = next(a for a in preview["actions"] if a["action"] == "open_settlement")
        row = _rd7_lever_rows(preview)[0]
        gold = int(row["gold_offer"])
        first = _rd7_post(client, _rd7_wizard_body(whole))["diplomatic_dialogue"]
        with contextlib.redirect_stdout(io.StringIO()):
            backed = client.post("/respond_to_diplomatic_dialogue", json={
                "choice": "suspend_settlement_editor",
                "dialogue_id": first["dialogue_id"]}).json()
        assert backed["success"], backed.get("message")
        opened = _rd7_post(client, _rd7_wizard_body(row))
        assert opened.get("draft_restored_from_scope") is True, "the board must restore a draft"
        dialogue = opened["diplomatic_dialogue"]
        terms = _rd7_gold_terms(dialogue)
        assert [(t["from"], t["to"], int(t["amount"])) for t in terms] == [("France", "Britain", gold)]
        assert {"type": "peace"} in dialogue["settlement_terms"]
        assert dialogue["covered_enemy_participants"] == ["Britain"]

    def test_a_player_drafted_gold_line_to_the_court_yields_to_the_payment(self, _rd7_client):
        """One France-to-Britain gold line: the lever's click replaces the sum
        the player had set (they are clicking the row that states the sum) and
        keeps every other line of the draft."""
        from backend.game_logic.cabinet_rows import lever_offer_opening_terms
        client, w = _rd7_client
        row = _rd7_lever_rows(_rd7_preview(w))[0]
        gold = int(row["gold_offer"])
        held = [{"type": "peace"},
                {"type": "gold_indemnity", "from": "France", "to": "Britain", "amount": 200,
                 "authored_by": "player"},
                {"type": "gold_indemnity", "from": "France", "to": "Austria", "amount": 150}]
        terms = lever_offer_opening_terms(
            w, war_id=row["war_id"], payer="France", court="Britain", amount=gold,
            covered=["Britain"], base_terms=held)
        assert terms[:2] == [{"type": "peace"}, held[2]]
        assert terms[2] == {"type": "gold_indemnity", "from": "France", "to": "Britain",
                            "amount": gold, "authored_by": "player"}
        assert len(terms) == 3

    # ── the treasury ─────────────────────────────────────────────────────

    def test_the_offer_the_treasury_cannot_fund_is_neither_staged_nor_promised(self, _rd7_client):
        """800 gold in the chest (the shipped opening) against the quoted sum:
        the row says what the lever costs and what the treasury can fund and
        carries no `gold_offer`; a request that names the sum anyway opens the
        table at its default — never an overdrawn line."""
        client, w = _rd7_client
        gold = int(_rd7_alone_road(_rd7_preview(w))["gold_to_carry"])
        w.nation_gold["France"] = gold - 75
        preview = _rd7_preview(w)
        row = _rd7_lever_rows(preview)[0]
        assert "gold_offer" not in row
        assert str(gold) in row["effect_text"] and str(gold - 75) in row["effect_text"], row["effect_text"]
        body = _rd7_wizard_body(row)
        body["gold_offer"] = gold      # a stale or hand-made request
        dialogue = _rd7_post(client, body)["diplomatic_dialogue"]
        assert _rd7_gold_terms(dialogue) == []

    def test_the_funding_test_is_the_validators_budget(self, _rd7_world):
        from backend.game_logic.cabinet_rows import lever_offer_opening_terms
        from backend.game_logic.settlement_validation import compute_gold_payer_budgets
        w = _rd7_world
        budget = int(compute_gold_payer_budgets(w, [], ["France"])["France"])
        war_id = _rd7_alone_road(_rd7_preview(w))["war_id"]

        def _open(amount, base=None):
            return lever_offer_opening_terms(w, war_id=war_id, payer="France", court="Britain",
                                             amount=amount, covered=["Britain"], base_terms=base)
        ok = _open(budget)
        assert ok and ok[-1]["amount"] == budget
        assert _open(budget + 1) is None
        # the draft's other gold lines draw on the same chest
        other = [{"type": "peace"},
                 {"type": "gold_indemnity", "from": "France", "to": "Austria", "amount": 500}]
        assert _open(budget - 500, other) is not None
        assert _open(budget - 499, other) is None

    # ── the row's other shapes (pure) ────────────────────────────────────

    def test_a_table_that_is_only_the_court_stamps_the_row_it_has(self):
        """Where the court IS the whole table there is no second row to add:
        the one `open_settlement` row carries the sum in place."""
        from backend.game_logic.cabinet_rows import lever_table_actions
        w = SimpleNamespace(player_nation="France", nation_gold={"France": 5000},
                            recurring_settlement_payments=[], regions={})
        table = {"action": "open_settlement", "display_name": "Open Settlement — with Britain",
                 "available": True, "war_id": "war_1", "addresses": ["Britain"], "dp_cost": 0}
        roads = [{"road": "table_alone", "available": True, "carries": False,
                  "label": "Open Settlement with Britain alone", "gold_to_carry": 600,
                  "war_id": "war_1"}]
        out = lever_table_actions(w, "France", "Britain", [dict(table)], roads)
        assert len(out) == 1 and out[0]["gold_offer"] == 600
        assert out[0]["counsel_coverage"] == ["Britain"]

    def test_no_lever_no_row(self):
        from backend.game_logic.cabinet_rows import lever_table_actions
        w = SimpleNamespace(player_nation="France", nation_gold={"France": 5000},
                            recurring_settlement_payments=[], regions={})
        table = {"action": "open_settlement", "display_name": "Open Settlement — the whole table",
                 "available": True, "war_id": "war_1", "addresses": ["Britain", "Austria"]}
        for roads in ([], [{"road": "table_alone", "available": True, "carries": True,
                            "gold_to_carry": 0}],
                      [{"road": "table_alone", "available": True, "carries": False,
                        "gold_to_carry": None}],
                      [{"road": "table_alone", "available": False, "carries": False,
                        "gold_to_carry": 600}]):
            assert lever_table_actions(w, "France", "Britain", [dict(table)], roads) == [dict(table)], roads
        shut = dict(table, available=False)
        roads = [{"road": "table_alone", "available": True, "carries": False,
                  "gold_to_carry": 600, "label": "Open Settlement with Britain alone"}]
        assert lever_table_actions(w, "France", "Britain", [shut], roads) == [shut]
        # a page with no table row at all (a truce's) gets none made for it
        other = [{"action": "propose_peace", "available": True}]
        assert lever_table_actions(w, "France", "Britain", list(other), roads) == other

    def test_only_the_wizards_page_gains_the_row(self, _rd7_world):
        """Golden Rule 5: the row is the PREVIEW's (the player's Cabinet page);
        the action list every other reader takes (`get_available_diplomatic_
        actions`) keeps its one table row - nothing of the AI's moves."""
        from backend.game_logic import diplomacy as D
        w = _rd7_world
        tables = [a for a in _rd7_quiet(D.get_available_diplomatic_actions, w, "Britain")
                  if a["action"] == "open_settlement"]
        assert len(tables) == 1 and "gold_offer" not in tables[0]
        assert len(_rd7_lever_rows(_rd7_preview(w))) == 1

    # ── the wire ─────────────────────────────────────────────────────────

    def test_the_request_model_and_main_carry_the_key(self):
        import backend.main as M
        assert "gold_offer" in M.CommandRequest.model_fields
        src = (_RD7_ROOT / "backend" / "main.py").read_text(encoding="utf-8")
        assert 'ctx.parsed["command"]["gold_offer"] = int(ctx.request.gold_offer)' in src

    def test_the_wizard_forwards_the_key_on_the_open_settlement_arm(self):
        src = _RD7_WIZARD.read_text(encoding="utf-8")
        start = src.index("func _structured_payload_for_action")
        end = src.index("\n\tif action_id == \"propose_white_peace\":", start)
        arm = src[start:end]
        assert 'var offer_gold = int(float(action_payload.get("gold_offer", 0)))' in arm
        assert 'data["gold_offer"] = offer_gold' in arm
        # tests/test_settlement_ui_slice_f_source.py: the helper's body never
        # says the word the emit signal is named for - not in a comment either
        addition = arm[arm.index("# S14E-D7"):]
        assert re.search(r"\bcommand\b", addition) is None
        # the Python mirror in `_rd7_wizard_body` is the GDScript arm: same keys
        assert 'data["counsel_coverage"] = coverage' in arm
        assert arm.index('data["counsel_coverage"] = coverage') < arm.index('data["gold_offer"] = offer_gold')


class TestS14EX34:
    """S14E-X34 — "reaching 875 takes about six presses of +": the defect half
    of D7. Reproduced: the alone table opened from the counsel's road stages
    `[peace]`, its offer row reads "Offer 300 gold to Britain", and the
    distance to the quoted sum is `(gold_to_carry - 300) / 100` presses."""

    def test_the_presses_the_defect_cost_are_gone(self, _rd7_client):
        from backend.game_logic.settlement_baseline import (
            CONCESSION_BASELINE_GOLD_FLOOR, SETTLEMENT_DIAL_GOLD_STEP,
        )
        client, w = _rd7_client
        preview = _rd7_preview(w)
        gold = int(_rd7_alone_road(preview)["gold_to_carry"])
        presses_before = -(-(gold - int(CONCESSION_BASELINE_GOLD_FLOOR)) // int(SETTLEMENT_DIAL_GOLD_STEP))
        assert presses_before >= 1, "the board must make the old default short of the sum"
        row = _rd7_lever_rows(preview)[0]
        dialogue = _rd7_post(client, _rd7_wizard_body(row))["diplomatic_dialogue"]
        staged = int(_rd7_gold_terms(dialogue)[0]["amount"])
        presses_after = -(-(gold - staged) // int(SETTLEMENT_DIAL_GOLD_STEP))
        assert presses_after == 0

    def test_the_lever_sentence_is_unchanged(self, _rd7_world):
        """S14E-8's words stand: the road, the control and the stride."""
        from backend.game_logic import counsel as CS
        reading = _rd7_quiet(CS.read_counsel, _rd7_world, "Britain")
        gold = int(next(r for r in reading["roads"] if r["road"] == "table_alone")["gold_to_carry"])
        lever = CS._lever_sentence(reading)
        assert lever.startswith(f"A payment of {gold} gold to Britain would carry the table with her alone. ")
        assert "At the table: Open Settlement with Britain alone, then Offer gold to Britain" in lever
        assert f"{gold} or more" in lever and "move it by 100" in lever

    def test_the_rows_name_is_the_roads_name_the_sentence_prints(self, _rd7_world):
        preview = _rd7_preview(_rd7_world)
        label = _rd7_alone_road(preview)["label"]
        assert label == "Open Settlement with Britain alone"
        assert _rd7_lever_rows(preview)[0]["display_name"].startswith(label)

# ========== S14f part 2 - merged from test_s14f_p2_preview.py ==========

# Pre-Deploy S14f part 2 — the peace preview's figures and words (S14E-19,
# S14E-25, the ruling S14E-D6 with its defect half S14E-X32, S14E-X6). One
# class per row; helper names carry the row's prefix (`_r19_`, `_r25_`,
# `_rd6_`, `_rx6_`); sweep letter G.


# ══════════════════════════════════════════════════════════════════════════
# row19 — "Adjust terms" on a peace France is dictating
# ══════════════════════════════════════════════════════════════════════════
# S14E-19 (P3). Conquest #5 (turn 4, action 97): the peace preview's
# "Adjust terms" (`adjust_terms`, the legacy concession wizard) opened the
# territory branch when `war_score < 0 or relation < -50` — Austria|France
# boots at -80, so a France at +84 read "Shall we discuss concessions, Sire?"
# and was asked for its own provinces to cede. Reproduced on the shipped 1805
# board (France +84 against Austria, relation -80): the click answered a
# `terms_guidance` step whose text was "Shall we discuss concessions, Sire?";
# on a bilateral fixture at +40 (relation -30) it answered "I suggest offering
# 120 gold per turn." — a winner paying the loser.
#
# The fix (`diplomatic_templates.adjust_terms_road`, read by BOTH the confirm's
# option stamp and the executor's arm): the direction comes from the WAR SCORE
# alone (the `relation < -50` arm is gone). A France that is behind keeps the
# concessions wizard; at peace the wizard is the sweetener road (gold / AP); a
# France that is NOT behind in a war is on the DEMANDS road — the table
# (`propose_common_peace`, covering the court alone: the counsel's own "Open
# Settlement with Austria alone"), where the guided Add demand lives. Where no
# table exists (a one-on-one war; a truce; a court that is not the side's
# leader) the button arrives DISABLED with its reason, and a forged click is
# refused with the same words. The ultimatum wizard is NOT the road: an
# ultimatum is refused in a war ("Use a peace proposal with harsh demands
# instead") and its confirm delivers an instrument the war forbids.

_R19_ROOT = Path(__file__).resolve().parents[1]
_R19_SCENARIO = (_R19_ROOT / "godot-client" / "project-sovereign" / "assets"
                 / "maps" / "europe_1805.json")


def _r19_quiet():
    return contextlib.redirect_stdout(io.StringIO())


@pytest.fixture(scope="module")
def _r19_boot():
    from backend.models.world_state import WorldState
    with _r19_quiet():
        return WorldState.from_scenario(str(_R19_SCENARIO))


@pytest.fixture
def _r19_world(_r19_boot):
    from backend.models.world_state import WorldState
    w = WorldState.from_dict(json.loads(json.dumps(_r19_boot.to_dict(), default=str)))
    w.diplomatic_points = 30
    return w


@pytest.fixture
def _r19_client(monkeypatch, _r19_world):
    """The in-process HTTP idiom on the shipped board: `M.world`,
    `M.game_state["world"]` and the mock parser swapped together."""
    import backend.main as M
    from backend.commands.parser import CommandParser
    from fastapi.testclient import TestClient
    for key in ("SOVEREIGN_SCENARIO", "SOVEREIGN_MAP", "SOVEREIGN_SMOKE_START"):
        monkeypatch.delenv(key, raising=False)
    monkeypatch.setenv("LLM_MODE", "mock")
    monkeypatch.setattr(M, "world", _r19_world)
    monkeypatch.setitem(M.game_state, "world", _r19_world)
    monkeypatch.setattr(M, "parser", CommandParser(use_real_llm=False))
    return TestClient(M.app), _r19_world


def _r19_post(client, path: str, body: dict) -> dict:
    with _r19_quiet():
        return client.post(path, json=body).json()


def _r19_set(w, nation_a: str, nation_b: str, a_view: int) -> None:
    """Store the pair's war score from `nation_a`'s chair."""
    key = w._make_diplo_key(nation_a, nation_b)
    w.war_scores[key] = a_view if key.split("|")[0] == nation_a else -a_view


def _r19_open(client, command: str) -> dict:
    out = _r19_post(client, "/command", {"command": command})
    dialogue = out["diplomatic_dialogue"]
    assert dialogue["type"] == "proposal_confirm", dialogue.get("type")
    return dialogue


def _r19_click(client, dialogue: dict, choice: str) -> dict:
    return _r19_post(client, "/respond_to_diplomatic_dialogue",
                     {"choice": choice, "dialogue_id": dialogue["dialogue_id"]})


def _r19_option(dialogue: dict, action: str) -> dict:
    return next(o for o in dialogue["options"] if o["action"] == action)


def _r19_bilateral(state: str = "WAR", score: int = 40, relation: int = -30):
    """The legacy fixture world: France and Austria alone — no war instance,
    so no table; the pair IS the side."""
    from backend.models.world_state import WorldState
    w = WorldState()
    key = w._make_diplo_key("France", "Austria")
    w.nation_relations[key] = relation
    w.diplomatic_states[key] = state
    if state == "WAR":
        w.war_scores[key] = score if key.split("|")[0] == "France" else -score
    return w


def _r19_confirm(w, proposal_type: str = "peace") -> dict:
    """The confirm popup's dialogue for `proposal_type` to Austria, as the
    typed road builds it."""
    from backend.game_logic.diplomatic_dialogue import (
        classify_diplomatic_intent, generate_dialogue,
    )
    data = {"target_nation": "Austria", "proposal_type": proposal_type,
            "raw_text": f"propose {proposal_type} to Austria", "tone": "propose",
            "has_diplomatic_keywords": True, "clauses": []}
    intent = classify_diplomatic_intent(data, w)
    assert intent == "proposal_confirm"
    with _r19_quiet():
        return generate_dialogue(intent, data, w)


def _r19_click_index(w, dialogue: dict, action: str) -> dict:
    """Answer the live dialogue by option index, as the client does."""
    from backend.commands.executor import CommandExecutor
    w.dialogue_manager.replace(dialogue)
    actions = [o["action"] for o in dialogue["options"]]
    with _r19_quiet():
        return CommandExecutor().handle_diplomatic_dialogue_response(
            actions.index(action) + 1, {"world": w})


class TestS14E19:
    # ── reproduction ─────────────────────────────────────────────────────

    def test_the_board_is_the_one_the_row_names(self, _r19_world):
        """Guard the guard: a war, relation at -80, France far ahead."""
        from backend.game_logic.diplomacy import get_war_score_for
        w = _r19_world
        _r19_set(w, "France", "Austria", 84)
        key = w._make_diplo_key("France", "Austria")
        assert w.get_diplomatic_state("France", "Austria") == "WAR"
        assert w.nation_relations[key] == -80
        assert get_war_score_for(w, "France", "Austria") == 84

    def test_a_winning_france_is_not_asked_to_cede(self, _r19_client):
        client, w = _r19_client
        _r19_set(w, "France", "Austria", 84)
        dialogue = _r19_open(client, "Talleyrand, propose peace to Austria")
        out = _r19_click(client, dialogue, "adjust_terms")
        step = out["diplomatic_dialogue"]
        assert "concessions" not in str(step.get("talleyrand_text", "")).lower(), (
            "a France at +84 was asked for its own provinces: "
            f"{step.get('talleyrand_text')!r}")
        assert step["type"] == "settlement_confirm", step["type"]

    def test_the_demands_road_is_the_table_over_the_court_alone(self, _r19_client):
        client, w = _r19_client
        _r19_set(w, "France", "Austria", 84)
        dialogue = _r19_open(client, "Talleyrand, propose peace to Austria")
        step = _r19_click(client, dialogue, "adjust_terms")["diplomatic_dialogue"]
        assert step["covered_enemy_participants"] == ["Austria"]
        assert step["war_id"] == "war_1"
        # the table is the desk; the peace preview it replaced is not left behind
        assert w.dialogue_manager.peek()["type"] == "settlement_confirm"
        assert not [d for d in w.dialogue_manager.iter_queue()
                    if d.get("type") == "proposal_confirm"]

    def test_the_bilateral_fixture_no_longer_pays_the_loser(self):
        """The fixture's reproduction: +40 at relation -30 read 'I suggest
        offering 120 gold per turn' — France paying the court it is beating."""
        w = _r19_bilateral("WAR", 40, -30)
        out = _r19_click_index(w, _r19_confirm(w), "adjust_terms")
        assert "offering" not in str(out.get("message", "")).lower()
        assert "concessions" not in str(out.get("message", "")).lower()

    # ── the direction is the war score's, alone ──────────────────────────

    @pytest.mark.parametrize("relation", [-80, -10, 30])
    def test_a_losing_france_keeps_the_concessions_road(self, relation):
        w = _r19_bilateral("WAR", -20, relation)
        out = _r19_click_index(w, _r19_confirm(w), "adjust_terms")
        step = out["diplomatic_dialogue"]
        assert step["type"] == "terms_guidance"
        assert "concessions" in step["talleyrand_text"].lower()
        assert {o["action"] for o in step["options"]} >= {"territory_yes", "territory_no_gold"}

    def test_the_losing_road_on_the_shipped_board_is_unmoved(self, _r19_client):
        client, w = _r19_client
        _r19_set(w, "France", "Austria", -30)
        dialogue = _r19_open(client, "Talleyrand, propose peace to Austria")
        step = _r19_click(client, dialogue, "adjust_terms")["diplomatic_dialogue"]
        assert step["type"] == "terms_guidance"
        assert "concessions" in step["talleyrand_text"].lower()

    @pytest.mark.parametrize("relation", [-80, -55, -10, 40])
    def test_relation_does_not_pick_the_road_at_war(self, relation):
        from backend.game_logic.diplomatic_templates import adjust_terms_road
        ahead = adjust_terms_road(_r19_bilateral("WAR", 40, relation), "France", "Austria", "peace")
        behind = adjust_terms_road(_r19_bilateral("WAR", -20, relation), "France", "Austria", "peace")
        assert ahead["road"] == "demands"
        assert behind["road"] == "concessions"

    @pytest.mark.parametrize("relation", [-80, -55, -10, 40])
    def test_at_peace_the_wizard_is_the_sweetener_road_whatever_the_relation(self, relation):
        """FALSIFIABLE: the old `relation < -50` arm opened 'concessions' for
        an alliance asked of a cold court at peace."""
        w = _r19_bilateral("PEACE", 0, relation)
        out = _r19_click_index(w, _r19_confirm(w, "alliance"), "adjust_terms")
        step = out["diplomatic_dialogue"]
        assert "concessions" not in step["talleyrand_text"].lower(), step["talleyrand_text"]
        assert "gold" in step["talleyrand_text"].lower()

    # ── where no demands road exists the button is disabled, with its reason

    def test_a_one_on_one_war_disables_the_button_with_its_reason(self):
        w = _r19_bilateral("WAR", 40, -30)
        dialogue = _r19_confirm(w)
        button = _r19_option(dialogue, "adjust_terms")
        assert button.get("available") is False and button.get("enabled") is False
        reason = str(button.get("disabled_reason_display") or "")
        assert reason and "table" in reason.lower(), reason
        assert button["unavailable_reason"] == reason
        # the other roads stand
