# ══════════════════════════════════════════════════════════════════════════
# rowD6 / X32 — the pair for the words, the side for the gold
# ══════════════════════════════════════════════════════════════════════════
# S14E-D6 (the ruling, built as recommended) with its defect half S14E-X32.
# On the France-Britain -2 / France-Austria +60 board, Britain's confirm said
# "They have little choice but to accept — and I have asked nothing of them
# beyond the peace itself, Sire" beside an estimate of REJECT (-8 of 50):
# `generate_suggested_terms` stage 4 picked the commentary tag
# (`dominant_terms` / `no_demands_winning` / `desperate_terms`) from the SIDE
# sum (+58 here) while the figure beside the words — and `get_game_bucket`, and
# the option descriptions — read the court's PAIR (-2).
#
# The fix: stage 4 picks the tag from the court's PAIR score
# (`get_war_score_for`, the figure the estimate beside it is judged on); the
# drafted gold keeps pricing the WHOLE war (CA8-D2's one number for stages 1-3
# and the prisoner easing stays). A bilateral war is byte-identical (pair ==
# side).

def _rd6_board(w, britain: int, austria: int, russia: int = 0):
    """The Third Coalition board with chosen pair scores (France's chair)."""
    _r19_set(w, "France", "Britain", britain)
    _r19_set(w, "France", "Austria", austria)
    _r19_set(w, "France", "Russia", russia)
    return w


def _rd6_words(terms: dict) -> str:
    """The commentary's own first paragraph (a situational flavour line may follow)."""
    return str(terms["talleyrand_commentary"]).split("\n\n")[0]


def _rd6_draft(w, court: str, proposal_type: str = "peace") -> dict:
    from backend.game_logic.diplomatic_templates import generate_suggested_terms
    with _r19_quiet():
        return generate_suggested_terms(court, proposal_type, w, deterministic=True)


class TestS14ED6:
    def test_the_board_splits_the_pair_from_the_side(self, _r19_world):
        """Guard the guard: Britain's pair is behind, the side sum is far ahead."""
        from backend.game_logic import diplomacy as D
        w = _rd6_board(_r19_world, -2, 60)
        assert D.get_war_score_for(w, "France", "Britain") == -2
        assert D.get_side_war_score_for(w, "France", "Britain") == 58

    def test_the_tag_follows_the_pairs_sign(self, _r19_world):
        from backend.game_logic.diplomatic_templates import _get_smart_commentary
        w = _rd6_board(_r19_world, -2, 60)
        britain = _rd6_words(_rd6_draft(w, "Britain"))
        assert "little choice" not in britain, britain
        # a level pair is not dominant: the bucket's word (a pair read) speaks
        assert britain == _get_smart_commentary("Britain", "neutral_deal"), britain
        # Austria's pair is +60: her draft keeps the dominant voice
        austria = _rd6_words(_rd6_draft(w, "Austria"))
        assert austria == _get_smart_commentary("Austria", "no_demands_winning"), austria

    def test_the_words_never_promise_what_the_figure_beside_them_refuses(self, _r19_client):
        """X32's pin over the wire: a confirm that says the court has no
        choice but to accept carries an estimate that accepts."""
        client, w = _r19_client
        _rd6_board(w, -2, 60)
        for court in ("Britain", "Austria"):
            dialogue = _r19_open(client, f"Talleyrand, propose peace to {court}")
            said_no_choice = "little choice but to accept" in str(dialogue["talleyrand_commentary"])
            if said_no_choice:
                assert dialogue["acceptance_outcome"] == "ACCEPT", (
                    court, dialogue["acceptance_estimate"], dialogue["acceptance_outcome"])
            _r19_click(client, dialogue, "reconsider")
        # and the case the row names: Britain's estimate refuses
        britain = _r19_open(client, "Talleyrand, propose peace to Britain")
        assert britain["acceptance_outcome"] != "ACCEPT"
        assert "little choice but to accept" not in britain["talleyrand_commentary"]

    @pytest.mark.parametrize("britain,austria,tag", [
        (-40, 60, "desperate_terms"),     # side +20: the old read said neutral
        (45, -20, "dominant_terms"),      # side +25: the old read said neutral
    ])
    def test_the_pair_picks_the_tag_the_side_would_not(self, _r19_world, britain, austria, tag):
        from backend.game_logic.diplomatic_templates import _get_smart_commentary
        w = _rd6_board(_r19_world, britain, austria)
        words = _rd6_words(_rd6_draft(w, "Britain"))
        expected = {_get_smart_commentary("Britain", t) for t in
                    (tag, "no_demands_winning" if tag == "dominant_terms" else tag)}
        assert words in expected, (words, tag)

    def test_the_gold_still_prices_the_whole_war(self, _r19_world):
        """CA8-D2 kept: stage 1's demand is the SIDE's figure — both courts of
        one war are priced by the same war number, whatever each pair reads."""
        from backend.game_logic.diplomatic_templates import _build_base_terms
        w = _rd6_board(_r19_world, -2, 60)
        with _r19_quiet():
            britain = _build_base_terms("Britain", "peace", w, deterministic=True)
            austria = _build_base_terms("Austria", "peace", w, deterministic=True)
        assert britain["demands"], "the guard: the side's +58 prices a demand"
        assert britain["demands"] == austria["demands"]

    @pytest.mark.parametrize("pair,tags", [
        (45, ("dominant_terms", "no_demands_winning")),
        (10, ("neutral_deal",)),
    ])
    def test_a_board_where_the_pair_is_the_side_is_unmoved(self, _r19_world, pair, tags):
        """FALSIFIABLE NEGATIVE: with the other enemy courts level, the pair
        IS the side, so the tag is the tag the side sum picked."""
        from backend.game_logic import diplomacy as D
        from backend.game_logic.diplomatic_templates import _get_smart_commentary
        w = _rd6_board(_r19_world, pair, 0, 0)
        assert D.get_side_war_score_for(w, "France", "Britain") == pair
        allowed = {_get_smart_commentary("Britain", t) for t in tags}
        assert _rd6_words(_rd6_draft(w, "Britain")) in allowed


