# ══════════════════════════════════════════════════════════════════════════
# rowX6 — floats on the wire under the confirm's war-context snapshot
# ══════════════════════════════════════════════════════════════════════════
# S14E-X6 (P3, found by S14E-3's float scan). `war_context_snapshot/harshness`
# (`round(harshness, 2)`) and `commitment_conflicts[*]/detail/bloc_share`
# (`round(share, 2)`) left the backend as floats; Golden Rule 2 says Godot
# takes none. The client reads neither: `harshness_label` is what
# `proposal_confirm_popup.gd` / `incoming_proposal_popup.gd` print, and a
# conflict is read by its `display` and `severity` — so nothing is kept as a
# float on purpose. Both are whole percents now (`harshness`: 35 = 0.35). The
# sibling the scan found beside them, the enriched dialogue's own top-level
# `harshness`, goes the same way; the letters' snapshot (`mailbox_payloads`)
# and the Cabinet's preview snapshots come out of the same builder.

def _rx6_floats(obj, path: str = ""):
    if isinstance(obj, float):
        yield path, obj
    elif isinstance(obj, dict):
        for key, value in obj.items():
            yield from _rx6_floats(value, f"{path}/{key}")
    elif isinstance(obj, (list, tuple)):
        for index, value in enumerate(obj):
            yield from _rx6_floats(value, f"{path}[{index}]")


class TestS14EX6:
    @pytest.mark.parametrize("command", [
        "Talleyrand, propose peace to Austria",
        "Talleyrand, propose armistice to Austria",
        "Talleyrand, propose peace to Britain",
        "Talleyrand, propose armistice to Britain",
    ])
    def test_no_float_under_the_confirms_snapshot_on_the_wire(self, _r19_client, command):
        client, w = _r19_client
        dialogue = _r19_open(client, command)
        assert list(_rx6_floats(dialogue["war_context_snapshot"])) == []

    def test_the_bloc_opposition_conflict_is_on_the_board_the_scan_reads(self, _r19_client):
        """Guard the guard: the snapshot carries the conflict whose detail held
        the second float, so the scan above is not vacuously green."""
        client, w = _r19_client
        dialogue = _r19_open(client, "Talleyrand, propose peace to Austria")
        kinds = {c.get("conflict_type")
                 for c in dialogue["war_context_snapshot"]["commitment_conflicts"]}
        assert "bloc_opposition" in kinds

    def test_the_two_figures_are_whole_percents(self, _r19_client):
        client, w = _r19_client
        dialogue = _r19_open(client, "Talleyrand, propose peace to Austria")
        snapshot = dialogue["war_context_snapshot"]
        assert isinstance(snapshot["harshness"], int) and 0 <= snapshot["harshness"] <= 100
        conflict = next(c for c in snapshot["commitment_conflicts"]
                        if c.get("conflict_type") == "bloc_opposition")
        share = conflict["detail"]["bloc_share"]
        assert isinstance(share, int) and 30 <= share <= 100

    def test_the_figure_is_the_old_one_in_percent(self, _r19_world):
        """A harsh draft reads its burden: the percent is 100x the old float."""
        from backend.game_logic.diplomacy import build_war_context_snapshot
        from backend.game_logic.diplomatic_templates import calculate_treaty_harshness
        w = _r19_world
        terms = {"type": "peace", "proposal_type": "peace", "proposer_nation": "France",
                 "target_nation": "Austria", "sweeteners": [],
                 "demands": [{"type": "gold_per_turn", "value": 400}], "clauses": []}
        with _r19_quiet():
            snapshot = build_war_context_snapshot(w, "France", "Austria", "peace", terms=terms)
        expected = calculate_treaty_harshness({**terms, "clauses": []})
        assert snapshot["harshness"] == int(round(expected * 100))
        assert snapshot["harshness"] > 0, "the guard: the demand is a burden"

    def test_the_dialogues_own_harshness_is_a_whole_percent_too(self, _r19_client):
        client, w = _r19_client
        dialogue = _r19_open(client, "Talleyrand, propose peace to Austria")
        assert isinstance(dialogue["harshness"], int)
        assert dialogue["harshness"] == dialogue["war_context_snapshot"]["harshness"]

    def test_the_cabinets_preview_snapshots_carry_no_float(self, _r19_world):
        from backend.game_logic import diplomacy as D
        with _r19_quiet():
            preview = D.get_diplomatic_preview(_r19_world, "Austria")
        assert preview["war_context_snapshots"]
        assert list(_rx6_floats(preview["war_context_snapshots"])) == []

    def test_the_letters_snapshot_carries_no_float(self, _r19_world):
        from backend.game_logic import mailbox_payloads as MP
        w = _r19_world
        with _r19_quiet():
            payload = MP.build_pending_envoy_popup_from_terms(
                w, nation="Austria",
                terms={"type": "peace", "sweeteners": [],
                       "demands": [{"type": "gold_lump", "value": 405}]},
                assessment="", is_counter_offer=False)
        assert payload["war_context_snapshot"]["harshness"] > 0
        assert list(_rx6_floats(payload["war_context_snapshot"])) == []
        assert isinstance(payload["harshness"], int)

    def test_the_client_reads_neither_figure(self):
        """The record that nothing is a float on purpose: the popups name the
        LABEL, never the number."""
        base = _R19_ROOT / "godot-client" / "project-sovereign" / "scripts"
        for script in ("proposal_confirm_popup.gd", "incoming_proposal_popup.gd"):
            src = (base / script).read_text(encoding="utf-8")
            assert not re.search(r'get\("harshness"[,)]', src), script
            assert "bloc_share" not in src, script


