# S14E-22 — a typed march's long or foreign detour asks first
# ══════════════════════════════════════════════════════════════════════════

_R22_ROOT = Path(__file__).resolve().parents[1]
_R22_SCENARIO = (_R22_ROOT / "godot-client" / "project-sovereign"
                  / "assets" / "maps" / "europe_1805.json")

def _r22_quiet():
    return contextlib.redirect_stdout(io.StringIO())


@pytest.fixture(scope="module")
def _r22_boot():
    from backend.models.world_state import WorldState
    with _r22_quiet():
        return WorldState.from_scenario(str(_R22_SCENARIO))


def _r22_world(boot):
    from backend.models.world_state import WorldState
    return WorldState.from_dict(json.loads(json.dumps(boot.to_dict(), default=str)))


def _r22_set(w, a: str, b: str, state: str) -> None:
    from backend.game_logic.diplomacy import set_diplomatic_state
    with _r22_quiet():
        set_diplomatic_state(w, a, b, state, "test")


def _r22_make_board(boot):
    """The conquest run's board (DD-B, turn 19, action 424): France holds
    Berlin, Moravia and Vienna; Bohemia and Dresden are Austrian under the
    truce; Prussia has opened her borders; Soult (literal, one province a
    turn) stands in Berlin. The direct road is Berlin -> Dresden -> Vienna
    (two provinces); the lawful one is Brandenburg -> Posen -> Silesia ->
    Podolia -> Moravia -> Vienna (six)."""
    w = _r22_world(boot)
    for name, owner in (("Berlin", "France"), ("Moravia", "France"), ("Vienna", "France"),
                        ("Dresden", "Austria"), ("Bohemia", "Austria")):
        w.regions[name].controller = owner
    _r22_set(w, "France", "Austria", "ARMISTICE")
    _r22_set(w, "France", "Prussia", "OPEN_BORDERS")
    soult = w.get_marshal("Soult")
    assert soult.personality == "literal" and soult.movement_range == 1
    soult.location = "Berlin"
    with _r22_quiet():
        w.calculate_visibility()
    return w


@pytest.fixture
def _r22_board(_r22_boot):
    return _r22_make_board(_r22_boot)


@contextlib.contextmanager
def _r22_client(w):
    """The player's road: /command on a swapped world (three globals, restored)."""
    import backend.main as M
    from backend.commands.parser import CommandParser
    from fastapi.testclient import TestClient
    saved = (M.game_state["world"], M.world, M.parser)
    M.game_state["world"] = w
    M.world = w
    M.parser = CommandParser(use_real_llm=False)
    try:
        yield TestClient(M.app)
    finally:
        M.game_state["world"], M.world, M.parser = saved


def _r22_say(client, text: str) -> dict:
    with _r22_quiet():
        return client.post("/command", json={"command": text}).json()


class TestS14E22:
    """S14E-22 — a typed `march to` commits a six-province detour through
    foreign courts and prints the road only afterwards.

    Reproduced: on the conquest run's board (the `_r22_board` fixture) "Soult,
    march to Vienna" was accepted at once — 1 AP spent, the order standing, the
    first step walked to Brandenburg — and the reply printed "Route: Berlin ->
    Brandenburg -> Posen -> Silesia -> Podolia -> Moravia -> Vienna" only
    afterwards; nothing said the direct road through Dresden is shut by the
    truce or that the lawful road is three times as long.

    The fix: a typed PLAYER `march to` whose direct road is closed asks, at no
    cost, on the free-ask channel (the pursuit ask's), when the lawful road is
    at least twice the direct or crosses soil of a court that is neither ours,
    an ally, a vassal nor an enemy — `strategic.march_detour_reading` is the
    one reader, the order's ask and the march quote's `detour` rider print the
    same sentence."""

    def test_the_typed_march_asks_before_it_commits(self, _r22_board):
        w = _r22_board
        soult = w.get_marshal("Soult")
        ap = int(w.actions_remaining)
        with _r22_client(w) as client:
            out = _r22_say(client, "Soult, march to Vienna")
        assert out.get("state") == "awaiting_clarification", out.get("message")
        assert out.get("clarification_kind") == "march_detour_ask"
        assert out.get("free_action") is True
        # nothing walked, nothing spent, no order standing
        assert soult.location == "Berlin"
        assert soult.strategic_order is None
        assert int(w.actions_remaining) == ap
        assert (out.get("action_info") or {}).get("cost", 0) == 0
        msg = out["message"]
        assert "The direct road to Vienna via Dresden is closed by the truce with Austria" in msg
        assert msg == ("The direct road to Vienna via Dresden is closed by the truce with "
                       "Austria; the lawful road is 6 provinces, 6 turns, through Prussia "
                       "and Russia — march, or cancel?")

    def test_march_issues_the_order_as_today(self, _r22_board):
        w = _r22_board
        soult = w.get_marshal("Soult")
        ap = int(w.actions_remaining)
        with _r22_client(w) as client:
            ask = _r22_say(client, "Soult, march to Vienna")
            assert ask.get("clarification_kind") == "march_detour_ask"
            out = _r22_say(client, "march")
        assert out.get("success") is True, out.get("message")
        assert out.get("state") != "awaiting_clarification"
        assert "Route: Brandenburg → Posen → Silesia → Podolia → Moravia → Vienna" in out["message"]
        assert soult.strategic_order is not None
        assert soult.strategic_order.command_type == "MOVE_TO"
        assert soult.strategic_order.target == "Vienna"
        assert int(w.actions_remaining) == ap - 1          # the literal's 1 AP, once
        assert soult.location == "Brandenburg"

    def test_cancel_spends_nothing(self, _r22_board):
        w = _r22_board
        soult = w.get_marshal("Soult")
        ap = int(w.actions_remaining)
        with _r22_client(w) as client:
            _r22_say(client, "Soult, march to Vienna")
            out = _r22_say(client, "cancel")
        assert out.get("success") is True
        assert "withdrawn" in out["message"]
        assert soult.location == "Berlin" and soult.strategic_order is None
        assert int(w.actions_remaining) == ap

    # ── the ask's boundaries ─────────────────────────────────────────────

    def test_the_options_reissue_the_players_own_words_confirmed(self, _r22_board):
        w = _r22_board
        with _r22_client(w) as client:
            out = _r22_say(client, "Soult, march to Vienna")
        opt = out["options"][0]
        assert opt["command"] == "Soult, march to Vienna"
        assert opt["flags"] == {"_march_confirmed": True}
        assert opt["label"] == "March (1 AP)"
        assert out["marshal"] == "Berthier" and out["interpreted_target"] == "Vienna"

    def test_the_ask_comes_before_the_square_breaks_and_before_any_objection(self, _r22_board):
        w = _r22_board
        davout = w.get_marshal("Davout")           # cautious: 2 AP, may object
        davout.location = "Berlin"
        davout.square_formation = True
        ap = int(w.actions_remaining)
        with _r22_client(w) as client:
            out = _r22_say(client, "Davout, march to Vienna")
        assert out.get("clarification_kind") == "march_detour_ask", out.get("message")
        assert davout.square_formation is True       # stage 7 never ran
        assert davout.strategic_order is None and int(w.actions_remaining) == ap
        assert not out.get("pending_objection") and w.pending_strategic_objection is None

    def test_a_short_sidestep_through_allied_soil_does_not_ask(self, _r22_board):
        """Bohemia ours, Dresden shut: Berlin -> Franconia (Bavaria, our ally)
        -> Bohemia -> Vienna is 3 against 2 and never leaves our own and allied
        soil — nothing to ask about."""
        w = _r22_board
        w.regions["Bohemia"].controller = "France"
        soult = w.get_marshal("Soult")
        with _r22_client(w) as client:
            out = _r22_say(client, "Soult, march to Vienna")
        assert out.get("state") != "awaiting_clarification", out.get("message")
        assert soult.strategic_order is not None and soult.strategic_order.target == "Vienna"

    def test_a_sidestep_over_a_third_courts_soil_asks_and_names_the_court(self, _r22_board):
        w = _r22_board
        w.regions["Bohemia"].controller = "France"
        w.regions["Franconia"].controller = "Prussia"       # an open-borders court's soil
        soult = w.get_marshal("Soult")
        with _r22_client(w) as client:
            out = _r22_say(client, "Soult, march to Vienna")
        assert out.get("clarification_kind") == "march_detour_ask", out.get("message")
        assert out["message"] == ("The direct road to Vienna via Dresden is closed by the truce "
                                  "with Austria; the lawful road is 3 provinces, 3 turns, "
                                  "through Prussia — march, or cancel?")
        assert soult.strategic_order is None

    def test_an_open_direct_road_never_asks(self, _r22_boot):
        """The shipped board: Lorraine -> Vienna runs lawful soil all the way
        (an ally's, then the enemy's) — the typed march is taken as today."""
        w = _r22_world(_r22_boot)
        soult = w.get_marshal("Soult")
        with _r22_client(w) as client:
            out = _r22_say(client, "Soult, march to Vienna")
        assert out.get("state") != "awaiting_clarification", out.get("message")
        assert soult.strategic_order is not None

    @pytest.mark.parametrize("command_extra,parsed_extra", [
        pytest.param({}, {}, id="no_typed_line"),
        pytest.param({"_army_order": True}, {"raw_input": "the army, march to Vienna"}, id="army_order"),
        pytest.param({"objection_response": "proceed"}, {"raw_input": "Soult, march to Vienna"},
                     id="objection_answered"),
        pytest.param({"_objection_answered": True}, {"raw_input": "Soult, march to Vienna"},
                     id="objection_preferred"),
        pytest.param({"_march_confirmed": True}, {"raw_input": "Soult, march to Vienna"},
                     id="the_answered_ask"),
        pytest.param({}, {"raw_input": "Soult, march to Vienna", "delegation_inferred": True},
                     id="delegation_inferred"),
    ])
    def test_orders_that_are_not_the_players_typed_line_keep_today(self, _r22_boot,
                                                                   command_extra, parsed_extra):
        """The Staff's army order, a delegation-inferred order, an order
        answered through an objection, the answered ask itself and a command
        with no typed words all keep today's road (Golden Rule 5; the row's
        scope)."""
        from backend.commands.executor import CommandExecutor
        w = _r22_make_board(_r22_boot)
        command = {"marshal": "Soult", "action": "move", "target": "Vienna", **command_extra}
        parsed = {"command": command, "is_strategic": True, "strategic_type": "MOVE_TO",
                  **parsed_extra}
        with _r22_quiet():
            out = CommandExecutor().execute(parsed, {"world": w})
        assert out.get("state") != "awaiting_clarification", out.get("message")
        assert w.get_marshal("Soult").strategic_order is not None

    def test_the_ais_side_and_a_standing_orders_replots_never_read_the_ask(self, _r22_board):
        """Golden Rule 5: the reading is the player's corps only, and the ask
        has one caller — the typed issuance's road stage. The per-turn
        processor re-plots through `march_road` and never asks."""
        from backend.commands import strategic as S
        w = _r22_board
        road, refusal, _kind = S.march_road(w, w.get_marshal("Soult"), "Vienna", "MOVE_TO")
        assert refusal is None and S.march_detour_reading(w, w.get_marshal("Soult"), "Vienna", road)
        ai = w.get_marshal("Mack")
        assert ai.nation != w.player_nation
        assert S.march_detour_reading(w, ai, "Vienna", road) is None
        text = (_R22_ROOT / "backend" / "commands" / "strategic_executor.py").read_text(encoding="utf-8")
        assert text.count("march_detour_ask(") == 2          # the definition and the road stage
        ai_src = (_R22_ROOT / "backend" / "ai" / "enemy_ai.py").read_text(encoding="utf-8")
        assert "march_detour" not in ai_src

    def test_the_quote_says_what_the_ask_says(self, _r22_board):
        """The march quote's `detour` rider is the ask's sentence (one reader,
        `march_detour_reading`): the card the player reads before sending and
        the question the typed order asks cannot disagree."""
        from backend.commands.order_quotes import march_quote
        w = _r22_board
        soult = w.get_marshal("Soult")
        q = march_quote(w, soult, "Vienna")
        assert q["ok"] and q["turns"] == 6 and len(q["road"]) == 6
        with _r22_client(w) as client:
            ask = _r22_say(client, "Soult, march to Vienna")
        assert q["detour"] and ask["message"] == q["detour"].rstrip(".") + " — march, or cancel?"
        # ... and an open road quotes no detour
        other = march_quote(w, w.get_marshal("Davout"), "Franconia")
        assert other["detour"] == ""

    def test_a_road_that_arrives_today_says_so(self):
        from backend.commands.strategic import march_detour_sentence
        line = march_detour_sentence("Vienna", {
            "via": "Dresden", "closed_by": "Saxony", "state": "PEACE", "direct": 1,
            "lawful": 2, "turns": 0, "courts": ["Prussia"], "foreign": ["Prussia"]})
        assert line == ("The direct road to Vienna via Dresden is closed — Saxony keeps its "
                        "frontier shut; the lawful road is 2 provinces, he arrives this turn, "
                        "through Prussia.")


