class TestS14ED5:
    """The design half (built as recommended): SLICE THE HARSHNESS PENALTY,
    KEEP THE BURDEN AND THE ALIGNMENT WHOLE-TABLE.

    Reproduced on the shipped board (the Beira package: the shared peace and
    Portugal's cession of Beira, Austria + Portugal + Russia covered): before
    the ruling Austria and Russia each carried `term_harshness_penalty` -9 for
    Portugal's cession and totalled -57; Portugal -54. After: Austria and
    Russia -48 (the -9 gone), Portugal -54 unchanged."""

    _BEIRA = _RD5_WHITE + [_rd5_demand()]

    def test_a_reproduction_the_whole_package_costs_austria_nine_for_portugals_cession(
            self, _rd5_board, monkeypatch):
        """THE REPRODUCTION (the ruling down = the whole package, as shipped before)."""
        _rd5_harshness_down(monkeypatch)
        rows, _ = _rd5_table(_rd5_board, self._BEIRA)
        for court in ("Austria", "Russia"):
            assert _rd5_comp(rows[court], "term_harshness_penalty") == -9, court
            assert rows[court]["total"] == -57, court
        assert _rd5_comp(rows["Portugal"], "term_harshness_penalty") == -9
        assert rows["Portugal"]["total"] == -54

    def test_b_after_the_ruling_each_court_reads_its_own_slice(self, _rd5_board):
        rows, _ = _rd5_table(_rd5_board, self._BEIRA)
        for court in ("Austria", "Russia"):
            assert _rd5_comp(rows[court], "term_harshness_penalty") == 0, court   # Portugal's price, not hers
            assert rows[court]["total"] == -48, court
        assert _rd5_comp(rows["Portugal"], "term_harshness_penalty") == -9      # her own cession
        assert rows["Portugal"]["total"] == -54

    def test_c_the_burden_and_the_alignment_keep_the_whole_table(self, _rd5_board, monkeypatch):
        """Principle 5: Talleyrand reasons across the table. The same two
        components read the same -15 / -15 with the ruling up or down."""
        up = {c: _rd5_scorer(_rd5_board, self._BEIRA, c)["components"] for c in ("Austria", "Russia")}
        _rd5_harshness_down(monkeypatch)
        down = {c: _rd5_scorer(_rd5_board, self._BEIRA, c)["components"] for c in ("Austria", "Russia")}
        for court in ("Austria", "Russia"):
            assert up[court]["burdened_participant_penalty"] == down[court]["burdened_participant_penalty"] == -15
            assert up[court]["war_objective_alignment"] == down[court]["war_objective_alignment"] == -15

    def test_d_the_numbers_move_by_the_harshness_alone(self, _rd5_board, monkeypatch):
        after = {c: _rd5_scorer(_rd5_board, self._BEIRA, c) for c in _RD5_COURTS}
        _rd5_harshness_down(monkeypatch)
        before = {c: _rd5_scorer(_rd5_board, self._BEIRA, c) for c in _RD5_COURTS}
        for court in ("Austria", "Russia"):
            assert after[court]["score"] - before[court]["score"] == 9, court
            moved = {k for k in after[court]["components"]
                     if after[court]["components"][k] != before[court]["components"][k]}
            assert moved == {"term_harshness_penalty"}, (court, moved)
        assert after["Portugal"]["components"] == before["Portugal"]["components"]

    def test_e_a_slice_never_costs_a_court_more_than_the_whole_package(self, _rd5_board, monkeypatch):
        packages = [
            self._BEIRA,
            _RD5_WHITE + [_rd5_demand("Beira"), _rd5_demand("Lisbon"),
                          {"type": "gold_indemnity", "from": "Austria", "to": "France", "amount": 300}],
            _RD5_WHITE + [{"type": "gold_indemnity", "from": "France", "to": "Russia", "amount": 100}],
        ]
        for terms in packages:
            after = {c: _rd5_scorer(_rd5_board, terms, c)["components"]["term_harshness_penalty"]
                     for c in _RD5_COURTS}
            with monkeypatch.context() as m:
                _rd5_harshness_down(m)
                before = {c: _rd5_scorer(_rd5_board, terms, c)["components"]["term_harshness_penalty"]
                          for c in _RD5_COURTS}
            for court in _RD5_COURTS:
                assert after[court] >= before[court], (court, terms)       # penalties are <= 0

    def test_f_a_one_court_table_is_unchanged(self, _rd5_board, monkeypatch):
        """With one covered court the slice is the package (or the package's
        other clauses all name her): the same scores as before the ruling."""
        terms = _RD5_WHITE + [{"type": "gold_indemnity", "from": "Austria", "to": "France", "amount": 300}]
        after = _rd5_scorer(_rd5_board, terms, "Austria", covered=["Austria"])
        _rd5_harshness_down(monkeypatch)
        before = _rd5_scorer(_rd5_board, terms, "Austria", covered=["Austria"])
        assert after["components"] == before["components"] and after["score"] == before["score"]

    def test_g_the_seam_is_looked_up_late_and_its_old_behaviour_is_the_whole_package(
            self, _rd5_board, monkeypatch):
        """`harshness_terms_for(package, court)` is THE series seam: the
        scorer looks it up at call time; swapping it for `list(package)`
        restores the pre-ruling scores exactly (the arms' lever)."""
        from backend.game_logic import settlement_scoring as SC
        seen = []
        real = SC.harshness_terms_for

        def spy(package, court):
            seen.append(court)
            return real(package, court)
        monkeypatch.setattr(SC, "harshness_terms_for", spy)
        _rd5_scorer(_rd5_board, self._BEIRA, "Austria")
        assert seen == ["Austria"]
        assert [t["type"] for t in real(self._BEIRA, "Austria")] == ["peace"]
        assert [t["type"] for t in real(self._BEIRA, "Portugal")] == ["peace", "territory_cede"]
        assert real(self._BEIRA, "") == self._BEIRA                            # no court: the whole package

    def test_h_the_debug_says_which_slice_was_read(self, _rd5_board):
        debug = _rd5_scorer(_rd5_board, self._BEIRA, "Austria")["component_debug"]["term_harshness_penalty"]
        assert debug["court"] == "Austria"
        assert (debug["package_clause_count"], debug["slice_clause_count"]) == (2, 1)
        assert debug["raw_total_harshness"] == 0.0 and debug["score"] == 0
        own = _rd5_scorer(_rd5_board, self._BEIRA, "Portugal")["component_debug"]["term_harshness_penalty"]
        assert (own["court"], own["slice_clause_count"]) == ("Portugal", 2) and own["score"] == -9

    def test_i_an_injected_package_figure_stands_when_the_slice_is_the_package(self, _rd5_board):
        """The aggregator memoizes the package's raw harshness once for every
        court; a court whose slice IS the package keeps reading the memo, a
        court with a smaller slice reads its own (never the memo)."""
        terms = _RD5_WHITE + [{"type": "gold_indemnity", "from": "Austria", "to": "France", "amount": 300}]
        whole = _rd5_scorer(_rd5_board, terms, "Austria", covered=["Austria"], raw_total_harshness=1.5)
        assert whole["components"]["term_harshness_penalty"] == -45
        sliced = _rd5_scorer(_rd5_board, self._BEIRA, "Austria", raw_total_harshness=1.5)
        assert sliced["components"]["term_harshness_penalty"] == 0

    def test_k_the_two_series_seams_are_independent(self, _rd5_board, monkeypatch):
        """D2's seam (`court_slice_of_package`, the legitimacy tier) and D5's
        (`harshness_terms_for`, the harshness penalty) hold their rulings down
        separately: the arms attribute each on its own."""
        from backend.game_logic import settlement_scoring as SC
        base = _rd5_scorer(_rd5_board, self._BEIRA, "Austria")["components"]
        with monkeypatch.context() as m:
            m.setattr(SC, "court_slice_of_package", lambda package, court: SC._iter_terms(package))
            d2_down = _rd5_scorer(_rd5_board, self._BEIRA, "Austria")["components"]
        assert d2_down["settlement_tier_legitimacy"] == -20 and base["settlement_tier_legitimacy"] == -10
        assert d2_down["term_harshness_penalty"] == base["term_harshness_penalty"] == 0
        with monkeypatch.context() as m:
            _rd5_harshness_down(m)
            d5_down = _rd5_scorer(_rd5_board, self._BEIRA, "Austria")["components"]
        assert d5_down["term_harshness_penalty"] == -9
        assert d5_down["settlement_tier_legitimacy"] == base["settlement_tier_legitimacy"] == -10

    def test_j_the_table_lessons_board_russia_moves_austria_and_the_chip_do_not(self):
        """The Table lesson (`tutorial_table_1805.json`, the probe's board):
        Austria still reads 56 of 50 "Will sign" (her slice holds the cession
        and the gold - the -14 is hers), the chip's 68 is a bilateral figure
        the scorer does not touch, and Russia's -39 (D2) becomes -25: her -14
        was Austria's price. The top blocker stays the war-objective alignment
        (-15, whole-table by design)."""
        from backend.models.world_state import WorldState
        with _rd5_quiet():
            w = WorldState.from_scenario(str(_RD5_TABLE_BOARD))
        terms = [{"type": "peace"},
                 {"type": "territory_cede", "from": "Austria", "to": "France", "region": "Carniola"},
                 {"type": "gold_indemnity", "from": "Austria", "to": "France", "amount": 200}]
        rows, _ = _rd5_table(w, terms, covered=["Austria", "Russia"])
        assert rows["Austria"]["total"] == 56 and rows["Austria"]["band"] == "accept"
        assert _rd5_comp(rows["Austria"], "term_harshness_penalty") == -14
        assert rows["Russia"]["total"] == -25
        assert _rd5_comp(rows["Russia"], "term_harshness_penalty") == 0
        assert _rd5_comp(rows["Russia"], "war_objective_alignment") == -15
        assert rows["Russia"]["top_blocker_component"] == "war_objective_alignment"


class TestS14EX24:
    """The defect half: three other components read the WHOLE package for
    every court. Reproduced as D5's: Austria's `term_harshness_penalty` -9
    for Portugal's cession on the Beira board. The harshness read is S14E-6's
    class and now follows the legitimacy tier; the burden and the alignment
    are deliberately whole-table (principle 5) and say so."""

    def test_a_the_harshness_penalty_no_longer_charges_austria_for_portugals_cession(self, _rd5_board):
        austria = _rd5_scorer(_rd5_board, _RD5_WHITE + [_rd5_demand()], "Austria")
        assert austria["components"]["term_harshness_penalty"] == 0
        assert austria["component_debug"]["settlement_tier_legitimacy"]["slice_clause_count"] == 1
        assert austria["component_debug"]["term_harshness_penalty"]["slice_clause_count"] == 1

    def test_b_the_burden_still_names_the_demand_on_portugal_as_austrias_top_blocker(self, _rd5_board):
        """Austria's new top blocker for a demand on Portugal is the BURDEN -
        the whole-table read, kept on purpose."""
        rows, _ = _rd5_table(_rd5_board, _RD5_WHITE + [_rd5_demand()])
        assert _rd5_comp(rows["Austria"], "burdened_participant_penalty") == -15
        assert _rd5_comp(rows["Austria"], "term_harshness_penalty") == 0

    def test_c_the_alignment_still_reads_russias_war_aim_against_the_whole_table(self, _rd5_board):
        rows, _ = _rd5_table(_rd5_board, _RD5_WHITE + [_rd5_demand()])
        assert _rd5_comp(rows["Russia"], "war_objective_alignment") == -15

    def test_d_the_scorer_names_the_three_reads_in_one_place(self):
        """The two whole-table reads are passed `settlement_terms` unsliced;
        the harshness read goes through the one seam."""
        from backend.game_logic import settlement_scoring as SC
        import inspect
        src = inspect.getsource(SC.calculate_common_peace_acceptance)
        assert "harshness_terms_for(settlement_terms, accepting_leader)" in src
        burden = src[src.index("calculate_burdened_participant_penalty("):]
        assert "settlement_terms=settlement_terms" in burden[:600]
        align = src[src.index("calculate_war_objective_alignment("):]
        assert "settlement_terms=settlement_terms" in align[:600]


# ═══════════════════════════════════════════════════════════════════════════
# S14E-D8 / S14E-X50 — the proposer's pass reaches only the allies the table resolves
# ═══════════════════════════════════════════════════════════════════════════

_RD8_SPAIN_FIGHTS = "Spain fights on alone against Britain — the table does not touch her war."


def _rd8_quiet():
    return contextlib.redirect_stdout(io.StringIO())


@pytest.fixture(scope="module")
def _rd8_boot():
    from backend.models.world_state import WorldState
    with _rd8_quiet():
        return WorldState.from_scenario(str(_RD5_SCENARIO))


@pytest.fixture
def _rd8_w(_rd8_boot):
    from backend.models.world_state import WorldState
    return WorldState.from_dict(json.loads(json.dumps(_rd8_boot.to_dict(), default=str)))


def _rd8_fight(w, **points):
    """Give nations battle contribution in war_1 (the material the
    reactions read): `_rd8_fight(w, France=200, Spain=200)`."""
    from backend.game_logic.war_contribution import open_episode
    for nation, pts in points.items():
        episode = open_episode(w, "war_1", nation, joined_turn=0, war_sequence=1)
        episode["battle"] = pts
        episode["total"] = pts


def _rd8_rel(w, a, b):
    return int(w.nation_relations.get(w._make_diplo_key(a, b), 0) or 0)


def _rd8_table(w, terms, covered, white_peace=False):
    """Preview, stage and ratify a table over `covered` (the scorer patched to
    carry, as the ratification tests do). Returns (preview, dialogue, result)."""
    import unittest.mock as mock
    from backend.game_logic import settlement_ratify as SR
    from backend.game_logic import settlement_scoring as SS
    from backend.game_logic.settlement_staging import build_settlement_preview, stage_settlement_confirm
    from tests.test_common_peace_c2_ratification import _acceptance_always_passes
    covered = list(covered)
    with _rd8_quiet():
        preview = build_settlement_preview(
            w, war_id="war_1", covered_enemy_participants=covered,
            settlement_terms=list(terms))["settlement_preview"]
    with mock.patch.object(SS, "calculate_common_peace_acceptance", _acceptance_always_passes):
        with _rd8_quiet():
            staged = stage_settlement_confirm(
                w, war_id="war_1", settlement_terms=([] if white_peace else list(terms)),
                covered_enemy_participants=covered, white_peace=white_peace)
        assert staged["success"], staged
        dialogue = w.pending_diplomatic_dialogue
        with _rd8_quiet():
            out = SR.ratify_settlement_confirm(w, dialogue)
    assert out["success"], out
    return preview, dialogue, out


def _rd8_applied(out, kind):
    return {r["ally"]: r for r in out["settlement_reactions"]["proposer_side_reactions"] if r["kind"] == kind}


def _rd8_resolves_down(monkeypatch):
    """The ruling DOWN - the series seam: every ally is reached, as shipped."""
    from backend.game_logic import settlement_reactions as R
    monkeypatch.setattr(R, "table_resolves_ally", lambda world, war_id, ally, terms, covered: True)


def _rd8_plan(w, ally, covered, terms=None, reading=None):
    from backend.game_logic.settlement_reactions import proposer_ally_plan
    return proposer_ally_plan(w, war_id="war_1", proposer_side="attackers", ally=ally,
                              settlement_terms=list(terms or _RD5_WHITE), covered=covered,
                              reading=reading)


class TestS14ED8:
    """The design half (built as recommended): the proposer-side pass REACHES
    ONLY THE ALLIES WHOSE PAIR THE TABLE RESOLVES; the rest are priced as
    "fights on alone" - no relation hit, no grievance, a line in the forecast
    and the review. ONE gate in `proposer_ally_plan`, behind ONE seam
    (`table_resolves_ally`)."""

    def test_a_who_the_table_resolves_is_who_the_ratifier_closes(self, _rd8_w):
        from backend.game_logic.settlement_reactions import table_resolves_ally
        w = _rd8_w
        terms = _RD5_WHITE
        austria_alone = {a: table_resolves_ally(w, "war_1", a, terms, ["Austria"])
                         for a in ("Bavaria", "KingdomOfItaly", "Spain", "Holland")}
        assert austria_alone == {"Bavaria": True, "KingdomOfItaly": True, "Spain": False, "Holland": False}
        britain_alone = {a: table_resolves_ally(w, "war_1", a, terms, ["Britain"])
                         for a in ("Bavaria", "KingdomOfItaly", "Spain", "Holland")}
        assert britain_alone == {"Bavaria": False, "KingdomOfItaly": False, "Spain": True, "Holland": True}
        whole = {a: table_resolves_ally(w, "war_1", a, terms, ["Austria", "Britain", "Russia"])
                 for a in ("Bavaria", "KingdomOfItaly", "Spain", "Holland")}
        assert all(whole.values())

    def test_b_the_plan_for_an_ally_the_table_does_not_touch_is_fights_on_with_no_price(self, _rd8_w):
        w = _rd8_w
        _rd8_fight(w, France=200, Spain=200)
        plan = _rd8_plan(w, "Spain", ["Austria"])
        assert plan["kind"] == "fights_on"
        assert plan["relation_delta"] == 0 and plan["grievance_flag_added"] is False
        assert plan["fights_on_against"] == ["Britain"]
        # the same ally on a table that DOES end her war: the shut-out, as shipped
        reached = _rd8_plan(w, "Spain", ["Britain"])
        assert reached["kind"] == "shut_out" and reached["relation_delta"] == -18

    def test_c_the_words_say_it_before_the_click(self, _rd8_w):
        from backend.game_logic.settlement_reactions import fights_on_words
        w = _rd8_w
        _rd8_fight(w, France=200, Spain=200)
        assert fights_on_words(w, _rd8_plan(w, "Spain", ["Austria"])) == _RD8_SPAIN_FIGHTS
        two = dict(_rd8_plan(w, "Spain", ["Austria"]), fights_on_against=["Britain", "Russia"])
        assert fights_on_words(w, two) == (
            "Spain fights on alone against Britain and Russia — the table does not touch her war.")
        idle = dict(_rd8_plan(w, "Spain", ["Austria"]), fights_on_against=[])
        assert fights_on_words(w, idle) == "Spain has no war the table touches — nothing changes between us."

    def test_d_the_reading_carries_the_gate_only_when_the_table_is_named(self, _rd8_w):
        """The bilateral road (`separate_peace_words`: carried allies are
        resolved by construction) and every caller with no coverage in hand
        read the ally as before."""
        from backend.game_logic.settlement_reactions import proposer_ally_reading
        w = _rd8_w
        _rd8_fight(w, France=200, Spain=200)
        bare = proposer_ally_reading(w, war_id="war_1", proposer_side="attackers", ally="Spain",
                                     settlement_terms=_RD5_WHITE)
        assert "table_resolves" not in bare
        covered = proposer_ally_reading(w, war_id="war_1", proposer_side="attackers", ally="Spain",
                                        settlement_terms=_RD5_WHITE, covered=["Austria"])
        assert covered["table_resolves"] is False and covered["fights_on_against"] == ["Britain"]
        # no coverage -> the old plan (the bilateral road's plan)
        from backend.game_logic.settlement_reactions import proposer_ally_plan
        assert proposer_ally_plan(w, war_id="war_1", proposer_side="attackers", ally="Spain",
                                  settlement_terms=_RD5_WHITE)["kind"] == "shut_out"

    def test_e_the_seam_is_looked_up_late_and_true_restores_the_old_pass(self, _rd8_w, monkeypatch):
        from backend.game_logic import settlement_reactions as R
        w = _rd8_w
        _rd8_fight(w, France=200, Spain=200)
        seen = []
        real = R.table_resolves_ally

        def spy(world, war_id, ally, terms, covered):
            seen.append((war_id, ally, tuple(covered)))
            return real(world, war_id, ally, terms, covered)
        monkeypatch.setattr(R, "table_resolves_ally", spy)
        assert _rd8_plan(w, "Spain", ["Austria"])["kind"] == "fights_on"
        assert seen == [("war_1", "Spain", ("Austria",))]
        _rd8_resolves_down(monkeypatch)
        down = _rd8_plan(w, "Spain", ["Austria"])
        assert down["kind"] == "shut_out" and down["relation_delta"] == -18

    def test_f_an_ally_the_instrument_names_is_thanked_whether_or_not_her_pair_is_resolved(self, _rd8_w):
        """The gate is for the shut-out arm: an ally NAMED in the instrument
        takes what it names (Spain, at war with Britain, named for Tyrol on an
        Austria-alone table)."""
        w = _rd8_w
        _rd8_fight(w, France=200, Spain=200)
        tyrol = _RD5_WHITE + [{"type": "territory_cede", "from": "Austria", "to": "Spain", "region": "Tyrol"}]
        plan = _rd8_plan(w, "Spain", ["Austria"], terms=tyrol)
        assert plan["kind"] == "rewarded" and plan["awarded_regions"] == ["Tyrol"]

    def test_g_an_ally_made_to_pay_keeps_her_price(self, _rd8_w):
        """PC-R7 (ii): a province of the ally pays the compensation - the
        instrument touches her whatever the pairs, so she is not 'untouched'."""
        w = _rd8_w
        paid = _RD5_WHITE + [{"type": "territory_compensate", "from": "Spain", "to": "Austria", "region": "Aragon"}]
        plan = _rd8_plan(w, "Spain", ["Austria"], terms=paid)
        assert plan["kind"] == "shut_out" and plan["severity"] == "paid_for_the_peace"

    def test_h_a_minor_with_standing_is_not_shut_out_of_a_peace_that_never_touched_her_war(self, _rd8_w):
        w = _rd8_w
        _rd8_fight(w, France=200, Holland=10)
        assert _rd8_plan(w, "Holland", ["Austria"])["kind"] == "fights_on"
        assert _rd8_plan(w, "Holland", ["Britain"])["kind"] == "shut_out"
        assert _rd8_plan(w, "Holland", ["Britain"])["relation_delta"] == -7

    def test_i_an_ally_with_no_standing_is_still_none_not_fights_on(self, _rd8_w):
        """Nobody has fought on the boot: Spec 14.4 stands (no standing, no
        reaction) - the new kind does not list the unlisted."""
        w = _rd8_w
        for ally in ("Spain", "Holland", "Bavaria", "KingdomOfItaly"):
            assert _rd8_plan(w, ally, ["Austria"])["kind"] == "none", ally

    def test_j_two_enemies_one_covered_is_resolved_not_fights_on(self, _rd8_w):
        """An ally the table ends ONE war of is reached (F81's teeth are for the
        ally whose war we ended for nothing): Spain at war with Austria too."""
        w = _rd8_w
        _rd8_fight(w, France=200, Spain=200)
        inst = w.war_instances["war_1"]
        pair = w._make_diplo_key("Austria", "Spain")
        inst["active_diplo_keys"].append(pair)
        inst.setdefault("diplo_key_meta", {})[pair] = {
            "attacker": "Spain", "defender": "Austria", "joined_turn": 1,
            "pair_status": "war", "resolved_turn": None, "entry_path": "scenario_start"}
        plan = _rd8_plan(w, "Spain", ["Austria"])
        assert plan["kind"] == "shut_out" and plan["relation_delta"] == -18

    def test_k_the_ai_roads_never_reach_the_gate(self, _rd8_w):
        """BASELINE_SERIES guard: the gate lives in `proposer_ally_reading(
        covered=...)`, passed only by the player's ratifier and the player's
        staging; the AI's settlement code never imports it."""
        for name in ("ai_diplomacy.py", "settlement_third_party.py", "agendas.py"):
            path = _RD5_REPO / "backend" / "game_logic" / name
            if path.is_file():
                src = path.read_text(encoding="utf-8")
                assert "table_resolves_ally" not in src and "fights_on" not in src, name


class TestS14EX50:
    """The defect half. Reproduced on the shipped board: an Austria-alone
    white peace with Spain (200 points, at war with Britain, which the table
    does not touch), Holland (10) and Bavaria (200, at war with Austria) in
    the war: the ratifier shut out Spain at -18 with a grievance and Holland
    at -7 - and the forecast said so. After the ruling Spain and Holland
    fight on alone (no relation hit, no flag, no record) and Bavaria, whose
    war the table ends, is shut out as before."""

    def test_a_reproduction_the_ratifier_shut_spain_out_of_a_peace_that_never_touched_her_war(
            self, _rd8_w, monkeypatch):
        from backend.game_logic.diplomacy import _get_grievance_flags
        _rd8_resolves_down(monkeypatch)
        w = _rd8_w
        _rd8_fight(w, France=200, Spain=200, Bavaria=200, Holland=10)
        before = {n: _rd8_rel(w, "France", n) for n in ("Spain", "Holland", "Bavaria")}
        _preview, _d, out = _rd8_table(w, _RD5_WHITE, ["Austria"], white_peace=True)
        shut = _rd8_applied(out, "ally_shut_out")
        assert set(shut) == {"Spain", "Holland", "Bavaria"}
        assert (shut["Spain"]["relation_delta"], shut["Spain"]["grievance_flag_added"]) == (-18, True)
        assert _rd8_rel(w, "France", "Spain") == before["Spain"] - 18
        assert [f["grievance_type"] for f in _get_grievance_flags(w, "France", "Spain")] == ["settlement_shut_out"]

    def test_b_after_the_ruling_spain_and_holland_fight_on_and_bavaria_is_shut_out(self, _rd8_w):
        from backend.game_logic.diplomacy import _get_grievance_flags
        w = _rd8_w
        _rd8_fight(w, France=200, Spain=200, Bavaria=200, Holland=10)
        before = {n: _rd8_rel(w, "France", n) for n in ("Spain", "Holland", "Bavaria", "KingdomOfItaly")}
        preview, _d, out = _rd8_table(w, _RD5_WHITE, ["Austria"], white_peace=True)
        shut = _rd8_applied(out, "ally_shut_out")
        assert set(shut) == {"Bavaria"}, "the ally whose war the table ends is still shut out"
        assert (shut["Bavaria"]["relation_delta"], shut["Bavaria"]["grievance_flag_added"]) == (-18, True)
        assert _rd8_rel(w, "France", "Spain") == before["Spain"]
        assert _rd8_rel(w, "France", "Holland") == before["Holland"]
        assert _get_grievance_flags(w, "France", "Spain") == []
        assert _get_grievance_flags(w, "France", "Holland") == []
        # nothing written for the allies it does not reach: no record of any kind
        kinds = {(r["kind"], r.get("ally")) for r in out["settlement_reactions"]["proposer_side_reactions"]}
        assert kinds == {("ally_shut_out", "Bavaria")}
        standing = {r["nation"]: r for r in preview["ally_standing_forecast"]}
        assert standing["Spain"]["display"] == _RD8_SPAIN_FIGHTS
        assert standing["Holland"]["display"] == (
            "Holland fights on alone against Britain — the table does not touch her war.")

    def test_c_shown_equals_applied(self, _rd8_w):
        """The forecast lists exactly the allies the ratifier punishes (the
        shut-outs, at the figures it applies) and says 'fights on' for exactly
        the allies it leaves alone."""
        w = _rd8_w
        _rd8_fight(w, France=200, Spain=200, Bavaria=200, Holland=10)
        preview, dialogue, out = _rd8_table(w, _RD5_WHITE, ["Austria"], white_peace=True)
        forecast = {r["nation"]: r for r in preview["shut_out_forecast"]}
        applied = _rd8_applied(out, "ally_shut_out")
        assert set(forecast) == set(applied) == {"Bavaria"}
        for nation, row in forecast.items():
            assert (applied[nation]["relation_delta"], applied[nation]["grievance_flag_added"],
                    applied[nation]["severity"]) == (
                row["relation_delta"], row["grievance_flag_added"], row["severity"]), nation
        fights = {r["nation"] for r in preview["ally_standing_forecast"] if r["kind"] == "fights_on"}
        assert fights == {"Spain", "Holland"} and fights.isdisjoint(applied)

    def test_d_the_line_is_in_the_review_and_on_the_staged_dialogue_before_the_click(self, _rd8_w):
        w = _rd8_w
        _rd8_fight(w, France=200, Spain=200, Bavaria=200)
        preview, dialogue, _out = _rd8_table(w, _RD5_WHITE, ["Austria"], white_peace=True)
        review = preview["review_sections"]
        assert [r["nation"] for r in review["ally_standing_preview"]] == ["Spain"]
        assert review["ally_standing_preview"][0]["display"] == _RD8_SPAIN_FIGHTS
        assert review["ally_standing_preview"][0]["relation_delta"] == 0
        # not among the allies left out, not among the third-party reactions to be paid
        assert {r["nation"] for r in review["shut_out_allies_preview"]} == {"Bavaria"}
        assert not any(r["nation"] == "Spain" for r in review["third_party_reaction_preview"])
        # the staged dialogue carries it at the top level (the client's footer reads it)
        assert [r["display"] for r in dialogue["ally_standing_forecast"]] == [_RD8_SPAIN_FIGHTS]
        assert all(isinstance(r["relation_delta"], int) and isinstance(r["material_points"], int)
                   and isinstance(r["material_share_pct"], int) for r in dialogue["ally_standing_forecast"])

    def test_e_the_whole_war_table_reaches_every_ally_as_before(self, _rd8_w):
        """Austria + Britain + Russia covered: every ally's pair is resolved -
        the three-pair table's forecast and ratification are the shipped ones
        (Spain -18 and a grievance, Holland -7)."""
        w = _rd8_w
        _rd8_fight(w, France=200, Spain=200, Holland=10)
        preview, _d, out = _rd8_table(w, _RD5_WHITE, ["Austria", "Britain", "Russia"], white_peace=True)
        assert {r["nation"] for r in preview["shut_out_forecast"]} == {"Spain", "Holland"}
        assert preview["ally_standing_forecast"] == []
        shut = _rd8_applied(out, "ally_shut_out")
        assert (shut["Spain"]["relation_delta"], shut["Holland"]["relation_delta"]) == (-18, -7)

    def test_f_a_britain_table_reaches_spain_and_leaves_bavaria_to_fight_on(self, _rd8_w):
        w = _rd8_w
