# S14E-X51 — the named ally's gratitude, said before the click
# ═══════════════════════════════════════════════════════════════════════════

_RX51_TYROL = _RD5_WHITE + [{"type": "territory_cede", "from": "Austria", "to": "Bavaria", "region": "Tyrol"}]


class TestS14EX51:
    """Reproduced on the shipped board: an Austria-alone table that cedes
    Tyrol to Bavaria (at war with Austria, 200 points): the ratifier wrote
    +10 relation and the `they_chose_us` record, the forecast listed nobody
    and the table's `rewarded` stamp carried no number. After: the forecast
    lists Bavaria, "Bavaria takes Tyrol by it and thanks us (+10 relation).",
    the figure the ratifier writes."""

    def test_a_reproduction_the_forecast_listed_only_shut_outs(self, _rd8_w):
        from backend.game_logic.settlement_reactions import forecast_proposer_side_reactions
        w = _rd8_w
        _rd8_fight(w, France=200, Bavaria=200)
        rows = forecast_proposer_side_reactions(w, war_id="war_1", proposer_side="attackers",
                                                settlement_terms=_RX51_TYROL,
                                                covered_enemy_participants=["Austria"])
        assert rows == [], "the shut-out forecast (the shipped default) has never listed the thanked"

    def test_b_the_forecast_states_the_thanks_with_its_figure(self, _rd8_w):
        from backend.game_logic.settlement_reactions import forecast_proposer_side_reactions
        w = _rd8_w
        _rd8_fight(w, France=200, Bavaria=200)
        rows = forecast_proposer_side_reactions(
            w, war_id="war_1", proposer_side="attackers", settlement_terms=_RX51_TYROL,
            covered_enemy_participants=["Austria"], kinds=("rewarded",))
        assert [r["nation"] for r in rows] == ["Bavaria"]
        assert rows[0]["kind"] == "rewarded" and rows[0]["relation_delta"] == 10
        assert rows[0]["display"] == "Bavaria takes Tyrol by it and thanks us (+10 relation)."
        assert rows[0]["awarded_regions"] == ["Tyrol"]

    def test_c_shown_equals_applied_the_seat_and_the_consult(self, _rd8_w):
        """The ratifier's gratitude write is the forecast's figure: a seat
        (+10) and a consult (+5), the relation and the `they_chose_us` record."""
        from backend.game_logic.settlement_reactions import get_settlement_memories
        for points, figure in ((200, 10), (0, 5)):
            from backend.models.world_state import WorldState
            w = WorldState.from_dict(json.loads(json.dumps(_rd8_w.to_dict(), default=str)))
            _rd8_fight(w, France=200, Bavaria=points) if points else _rd8_fight(w, France=200)
            before = _rd8_rel(w, "France", "Bavaria")
            preview, _d, out = _rd8_table(w, _RX51_TYROL, ["Austria"])
            shown = {r["nation"]: r for r in preview["ally_standing_forecast"] if r["kind"] == "rewarded"}
            applied = _rd8_applied(out, "ally_rewarded")
            assert set(shown) == set(applied) == {"Bavaria"}
            assert shown["Bavaria"]["relation_delta"] == applied["Bavaria"]["relation_delta"] == figure
            assert shown["Bavaria"]["awarded_regions"] == applied["Bavaria"]["awarded_regions"] == ["Tyrol"]
            assert _rd8_rel(w, "France", "Bavaria") == before + figure
            assert get_settlement_memories(w, actor="France", subject="Bavaria", memory_type="they_chose_us")
            assert f"(+{figure} relation)" in shown["Bavaria"]["display"]

    def test_d_one_footer_line_in_the_review_the_dialogue_and_the_client(self, _rd8_w):
        w = _rd8_w
        _rd8_fight(w, France=200, Bavaria=200)
        preview, dialogue, _out = _rd8_table(w, _RX51_TYROL, ["Austria"])
        line = "Bavaria takes Tyrol by it and thanks us (+10 relation)."
        review = {r["nation"]: r for r in preview["review_sections"]["ally_standing_preview"]}
        assert review["Bavaria"]["display"] == line and review["Bavaria"]["relation_delta"] == 10
        assert review["Bavaria"]["kind"] == "rewarded"
        assert line in [r["display"] for r in dialogue["ally_standing_forecast"]]
        # a thanked ally is not 'left out'
        assert preview["shut_out_forecast"] == []
        assert "Bavaria" not in {r["nation"] for r in preview["review_sections"]["shut_out_allies_preview"]}
        popup = (_RD5_REPO / "godot-client" / "project-sovereign" / "scripts"
                 / "proposal_confirm_popup.gd").read_text(encoding="utf-8")
        assert 'data.get("ally_standing_forecast", [])' in popup and "[b]The allies[/b]" in popup
        assert popup.index("Left out of the peace") < popup.index("[b]The allies[/b]")

    def test_e_an_ally_named_with_no_province_is_thanked_for_her_share(self, _rd8_w):
        from backend.game_logic.settlement_reactions import rewarded_words
        w = _rd8_w
        _rd8_fight(w, France=200, Bavaria=200)
        plan = {"ally": "Bavaria", "kind": "rewarded", "relation_delta": 5, "awarded_regions": []}
        assert rewarded_words(w, plan) == "Bavaria takes her share by it and thanks us (+5 relation)."

    def test_f_the_plan_carries_the_figure_from_the_one_source(self, _rd8_w):
        """`gratitude_delta` is `_reward_named_ally`'s own source: the plan's
        number cannot drift from the write."""
        from backend.game_logic import settlement_reactions as R
        assert R.gratitude_delta("seat") == R.RELATION_GRATITUDE_SEAT == 10
        assert R.gratitude_delta("consult") == R.RELATION_GRATITUDE_CONSULT == 5
        w = _rd8_w
        _rd8_fight(w, France=200, Bavaria=200)
        plan = _rd8_plan(w, "Bavaria", ["Austria"], terms=_RX51_TYROL)
        assert plan["kind"] == "rewarded" and plan["relation_delta"] == R.gratitude_delta(plan["standing_level"])

    def test_g_the_default_forecast_and_the_whole_table_are_unchanged(self, _rd8_w):
        """No `kinds`: the shipped call returns shut-outs alone (TestS14E10)."""
        from backend.game_logic.settlement_reactions import forecast_proposer_side_reactions
        w = _rd8_w
        _rd8_fight(w, France=200, Spain=200, Holland=10)
        rows = forecast_proposer_side_reactions(w, war_id="war_1", proposer_side="attackers",
                                                settlement_terms=_RD5_WHITE)
        assert {r["nation"] for r in rows} == {"Spain", "Holland"}
        assert all(r["kind"] == "shut_out" for r in rows)


class TestS14EX115:
    """Sibling found by the X51 sweep: `_is_named_beneficiary` read only the
    plural `regions` of a clause, so the table's canonical cession (a singular
    `region`, PC-X32's class) named nothing - the `they_chose_us` record and
    every sentence built from it said "her share". Reproduced: a table that
    cedes Tyrol to Bavaria recorded `awarded_regions == []`."""

    def test_a_the_singular_region_is_named(self):
        from backend.game_logic.settlement_reactions import _is_named_beneficiary
        assert _is_named_beneficiary(
            [{"type": "territory_cede", "from": "Austria", "to": "Bavaria", "region": "Tyrol"}],
            "Bavaria") == (True, ["Tyrol"])
        assert _is_named_beneficiary(
            [{"type": "territory_cede", "from": "Austria", "to": "Bavaria", "regions": ["Tyrol", "Salzburg"]}],
            "Bavaria") == (True, ["Tyrol", "Salzburg"])
        assert _is_named_beneficiary(
            [{"type": "territory_cede", "from": "Austria", "to": "Bavaria", "regions": ["Tyrol"], "region": "Tyrol"}],
            "Bavaria") == (True, ["Tyrol"])
        assert _is_named_beneficiary(
            [{"type": "territory_cede", "from": "Austria", "to": "Bavaria", "region": "Tyrol"}],
            "Spain") == (False, [])

    def test_b_the_ratified_record_names_the_province(self, _rd8_w):
        from backend.game_logic.settlement_reactions import get_settlement_memories
        w = _rd8_w
        _rd8_fight(w, France=200, Bavaria=200)
        _preview, _d, _out = _rd8_table(w, _RX51_TYROL, ["Austria"])
        mem = get_settlement_memories(w, actor="France", subject="Bavaria", memory_type="they_chose_us")
        assert mem and mem[0]["payload"]["awarded_regions"] == ["Tyrol"]


