# S14E-X25 — ONE clause-to-court predicate
# ═══════════════════════════════════════════════════════════════════════════

_RX25_LIBERATION = {"type": "liberation", "vassal_nation": "Saxony", "lord_nation": "Prussia",
                    "liberator": "Austria"}
_RX25_TRANSFER = {"type": "vassal_transfer", "from": "Prussia", "to": "France", "vassal": "Hanover"}


class TestS14EX25:
    """Three clause-to-court predicates existed. Reproduced (the pre-ruling
    predicates, read off HEAD): for a `liberation` clause
    `settlement_validation._clause_touches_court` (`from`/`to` only) and
    `settlement_actions.clause_names_court` (twelve generic keys no canonical
    clause carries) answered False for EVERY court - its lord, its liberator,
    its freed vassal - and `_clause_touches_court` missed a
    `vassal_transfer`'s `vassal`. Both now read `settlement_scoring.
    clause_parties`, the slice's own predicate."""

    def test_a_both_predicates_are_the_scorers(self):
        from backend.game_logic.settlement_actions import clause_names_court
        from backend.game_logic.settlement_scoring import clause_parties
        from backend.game_logic.settlement_validation import _clause_touches_court
        clauses = [
            _RX25_LIBERATION, _RX25_TRANSFER, {"type": "peace"},
            {"type": "territory_cede", "from": "Portugal", "to": "France", "region": "Beira"},
            {"type": "gold_indemnity", "from": "France", "to": "Austria", "amount": 200},
            {"type": "forced_alliance", "from": "Russia", "to": "France"},
        ]
        nations = ["Austria", "France", "Hanover", "Portugal", "Prussia", "Russia", "Saxony", "Spain"]
        for clause in clauses:
            for court in nations:
                expected = court in clause_parties(clause)
                assert clause_names_court(clause, court) is expected, (clause["type"], court)
                assert _clause_touches_court(clause, court) is (expected and clause["type"] != "peace"), \
                    (clause["type"], court)

    def test_b_a_liberation_touches_its_lord_its_liberator_and_its_freed_vassal(self):
        from backend.game_logic.settlement_actions import clause_names_court
        from backend.game_logic.settlement_validation import _clause_touches_court
        for court in ("Prussia", "Austria", "Saxony"):
            assert _clause_touches_court(_RX25_LIBERATION, court) is True, court
            assert clause_names_court(_RX25_LIBERATION, court) is True, court
        assert _clause_touches_court(_RX25_LIBERATION, "France") is False
        assert clause_names_court(_RX25_LIBERATION, "France") is False

    def test_c_a_vassal_transfer_touches_the_lord_the_taker_and_the_vassal(self):
        from backend.game_logic.settlement_actions import clause_names_court
        from backend.game_logic.settlement_validation import _clause_touches_court
        for court in ("Prussia", "France", "Hanover"):
            assert _clause_touches_court(_RX25_TRANSFER, court) is True, court
            assert clause_names_court(_RX25_TRANSFER, court) is True, court

    def test_d_the_shared_peace_names_nobody_and_a_blank_court_nobody(self):
        from backend.game_logic.settlement_actions import clause_names_court
        from backend.game_logic.settlement_validation import _clause_touches_court
        assert clause_names_court({"type": "peace"}, "Austria") is False
        assert _clause_touches_court({"type": "peace"}, "Austria") is False
        assert clause_names_court(_RX25_LIBERATION, "") is False
        assert clause_names_court("not a clause", "Austria") is False
        assert _clause_touches_court(None, "Austria") is False

    def test_e_the_cover_drop_strikes_the_dependency_clauses_of_the_dropped_court(self):
        """The dial survives the drop (SF-DIP-1): dropping Prussia strikes the
        liberation of its vassal and the transfer of Hanover; dropping the
        LIBERATOR strikes the liberation (it did not before)."""
        from backend.game_logic.settlement_actions import _terms_after_cover_edit
        dialogue = {"settlement_terms": [
            {"type": "peace"}, dict(_RX25_LIBERATION), dict(_RX25_TRANSFER),
            {"type": "gold_indemnity", "from": "Russia", "to": "France", "amount": 100}]}
        terms, message = _terms_after_cover_edit(
            dialogue, action="settlement_cover_drop", nation="Prussia", baseline_terms=[],
            new_covered=["Russia"])
        assert [t["type"] for t in terms] == ["peace", "gold_indemnity"]
        assert "2 clauses naming it struck" in message
        terms, _ = _terms_after_cover_edit(
            dialogue, action="settlement_cover_drop", nation="Austria", baseline_terms=[],
            new_covered=["Prussia", "Russia"])
        assert [t["type"] for t in terms] == ["peace", "vassal_transfer", "gold_indemnity"]

    def test_f_the_cover_add_brings_the_baselines_dependency_clauses_for_the_added_court(self):
        from backend.game_logic.settlement_actions import _terms_after_cover_edit
        dialogue = {"settlement_terms": [{"type": "peace"}]}
        terms, message = _terms_after_cover_edit(
            dialogue, action="settlement_cover_add", nation="Prussia",
            baseline_terms=[dict(_RX25_LIBERATION), {"type": "gold_indemnity", "from": "Russia", "to": "France",
                                                     "amount": 100}],
            new_covered=["Prussia"])
        assert [t["type"] for t in terms] == ["peace", "liberation"]
        assert "1 baseline clause authored" in message

    def test_g_the_baselines_degrade_pass_strikes_a_dependency_clause_it_could_not_validate(
            self, _rd8_w, monkeypatch):
        """`_degrade_generated_baseline_to_valid` degrades the LAST covered
        court that still holds material clauses - a liberation held by no
        court (both predicates false) was unreachable, the package stayed
        invalid."""
        from backend.game_logic import settlement_baseline as SB
        monkeypatch.setattr(
            SB, "validate_settlement_terms",
            lambda terms, **kw: {"valid": not any(t.get("type") == "liberation" for t in terms)})
        entry = {"terms": [dict(_RX25_LIBERATION)]}
        out = SB._degrade_generated_baseline_to_valid(
            _rd8_w, war_instance=_rd8_w.war_instances["war_1"], proposer_side="attackers",
            covered=["Prussia"], combined_terms=[{"type": "peace"}, dict(_RX25_LIBERATION)],
            per_court_baseline={"Prussia": entry})
        assert [t["type"] for t in out] == ["peace"]
        assert entry["terms"] == [] and entry["degraded_to_peace_floor"] is True

    def test_h_the_twelve_generic_keys_are_gone(self):
        src = (_RD5_REPO / "backend" / "game_logic" / "settlement_actions.py").read_text(encoding="utf-8")
        assert "_CLAUSE_COURT_KEYS" not in src
        assert "court in clause_parties(clause)" in src
        validation = (_RD5_REPO / "backend" / "game_logic" / "settlement_validation.py").read_text(encoding="utf-8")
        assert "court in clause_parties(clause)" in validation

