_W1_ROOT = Path(__file__).resolve().parent.parent
_W1_SCRIPTS = _W1_ROOT / "godot-client" / "project-sovereign" / "scripts"
_W1_SCENARIO = (_W1_ROOT / "godot-client" / "project-sovereign" / "assets" / "maps"
                / "europe_1805.json")


def _w1_quiet():
    return contextlib.redirect_stdout(io.StringIO())


def _w1_src(name: str = "main.gd") -> str:
    return (_W1_SCRIPTS / name).read_text(encoding="utf-8")


def _w1_func(src: str, name: str) -> str:
    """A GDScript function's body: from its header to the next top-level one."""
    start = src.index(f"func {name}(")
    ends = [e for e in (src.find("\nfunc ", start + 1), src.find("\nstatic func ", start + 1))
            if e != -1]
    return src[start:min(ends) if ends else len(src)]


