def _w1_halt_massena_under_strain(world):
    """The sea road's turn on the shipped board: Massena and Soult stand over
    Tyrol's capacity (two turns of supply attrition), Massena on his way to
    Milan halted at Tyrol by Archduke John -- his order frozen on a contact
    interrupt. The boot briefing then leads with the supply_strain headline."""
    from backend.models.marshal import StrategicOrder
    massena, soult = world.get_marshal("Massena"), world.get_marshal("Soult")
    for m in (massena, soult):
        m.location = "Tyrol"
    turn = int(world.current_turn)
    for t in (turn - 1, turn):
        for m in (massena, soult):
            world.event_log.append({"type": "supply_attrition", "nation": "France",
                                    "region": "Tyrol", "turn": t, "losses": 800,
                                    "marshal": m.name})
    massena.strategic_order = StrategicOrder(
        command_type="MOVE_TO", target="Milan", target_type="region",
        started_turn=1, original_command="Massena, march to Milan", path=["Milan"])
    massena.pending_interrupt = {
        "interrupt_type": "contact", "marshal": "Massena", "enemy": "ArchdukeJohn",
        "location": "Tyrol", "options": ["attack", "go_around", "hold_position", "cancel_order"]}
    return massena


def _w1_continue_as_ordered(massena):
    massena.pending_interrupt = None
    massena.location = "Milan"


def _w1_boot_dispatch(world):
    from backend.game_logic import dispatch as D
    with _w1_quiet():
        return D.build_morning_dispatch(world, boot=True)


class TestS14EX122:
    """Reproduced (shipped 1805 board): Massena and Soult over Tyrol's supply
    cap, Massena halted there on a contact interrupt -- the boot briefing led
    "Soult and Massena stand 72,000 men at Tyrol, which feeds 20,000". The
    interrupt answered ("Continue as Ordered": Massena to Milan),
    `_readable_dispatch` (S14E-30) re-derived the MARSHAL STATUS rows but kept
    the morning's frozen `headline` and `berthier_note`, so the R screen
    printed a headline about Tyrol over a roster showing Milan.

    Why not re-derive the headline: `_build_headline` / `_select_headline` are
    not a pure read of the board. The exact-repeat demotion reads
    `world.last_morning_dispatch` (on a re-read the stored headline is its own
    "yesterday" and the pick would demote itself to the next candidate), the
    streak / escalation ladder reads `headline_lead_memory`, and the note's
    lead class rides the same memory.

    The fix: the COPY `_readable_dispatch` returns carries `stale_headline:
    True` when a corps' location or status differs from the morning's stored
    row, and both dispatch screens caption the headline and note "as of this
    morning" (`Utils.DISPATCH_AS_OF_THE_MORNING`)."""

    def test_the_headline_names_tyrol_after_the_corps_has_left(self, _w1_world):
        import backend.main as M
        massena = _w1_halt_massena_under_strain(_w1_world)
        dispatch = _w1_boot_dispatch(_w1_world)
        assert dispatch["headline"]["class"] == "supply_strain"
        assert "Massena" in dispatch["headline"]["text"] and "Tyrol" in dispatch["headline"]["text"]
        _w1_continue_as_ordered(massena)
        got = M._readable_dispatch(_w1_world)
        row = next(r for r in got["marshals"] if r["name"] == "Massena")
        assert row["location"] == "Milan"
        # the morning's words stand (they are the morning's) -- and say so
        assert got["headline"] == dispatch["headline"]
        assert got["berthier_note"] == dispatch["berthier_note"]
        assert got["stale_headline"] is True

    def test_the_stored_dispatch_is_never_touched(self, _w1_world):
        import backend.main as M
        massena = _w1_halt_massena_under_strain(_w1_world)
        _w1_boot_dispatch(_w1_world)
        before = json.dumps(_w1_world.last_morning_dispatch, sort_keys=True, default=str)
        _w1_continue_as_ordered(massena)
        M._readable_dispatch(_w1_world)
        assert json.dumps(_w1_world.last_morning_dispatch, sort_keys=True, default=str) == before
        assert "stale_headline" not in _w1_world.last_morning_dispatch

    def test_an_unmoved_board_carries_no_flag(self, _w1_world):
        import backend.main as M
        _w1_halt_massena_under_strain(_w1_world)
        _w1_boot_dispatch(_w1_world)
        assert "stale_headline" not in M._readable_dispatch(_w1_world)

    def test_a_strength_only_change_is_not_a_move(self, _w1_world):
        """The flag is the headline's subject moving (where a corps stands,
        what it is doing), not every casualty."""
        import backend.main as M
        _w1_halt_massena_under_strain(_w1_world)
        _w1_boot_dispatch(_w1_world)
        _w1_world.get_marshal("Ney").strength -= 100
        assert "stale_headline" not in M._readable_dispatch(_w1_world)

    def test_any_corps_that_marches_flags_the_headline(self, _w1_world):
        import backend.main as M
        _w1_boot_dispatch(_w1_world)
        _w1_world.get_marshal("Ney").location = "Swabia"
        assert M._readable_dispatch(_w1_world)["stale_headline"] is True

    def test_the_reader_stays_pure(self):
        """UX23-R4's trap stands: no consuming builder on a read."""
        src = (_W1_ROOT / "backend" / "main.py").read_text(encoding="utf-8")
        body = src[src.index("def _readable_dispatch("):]
        body = body[:body.index("\ndef ")]
        assert "build_morning_dispatch(" not in body and "_build_headline(" not in body
        assert "dispatch = dict(dispatch)" in body

    def test_the_empty_store_still_reads_empty(self, _w1_world):
        import backend.main as M
        _w1_world.last_morning_dispatch = {}
        assert M._readable_dispatch(_w1_world) == {}

    def test_both_screens_caption_the_stale_headline(self):
        utils = _w1_src("utils.gd")
        assert "const DISPATCH_AS_OF_THE_MORNING" in utils
        caption = utils[utils.index("const DISPATCH_AS_OF_THE_MORNING"):].split("\n", 1)[0]
        assert "as of this morning" in caption
        for name, fn in (("dispatch_view.gd", None), ("main.gd", "_display_morning_dispatch")):
            src = _w1_src(name)
            body = _w1_func(src, fn) if fn else src
            assert 'data.get("stale_headline", false)' in body, name
            assert "Utils.DISPATCH_AS_OF_THE_MORNING" in body, name
            # between the headline block and SITUATION
            assert (body.index('headline.get("sub_beats", [])')
                    < body.index('data.get("stale_headline", false)')
                    < body.index(']SITUATION[/color]')), name


