class TestS14EX123:
    """Reproduced (by source): the command line's `KEY_ESCAPE` arm always ran
    its ladder and ended in `command_input.accept_event()`. A line the gate has
    closed (`set_input_enabled(false)`: a modal is up, a reply pending) keeps
    focus -- nothing releases it -- so its gui_input saw Esc FIRST and consumed
    it, and no modal's own Esc hatch (`enemy_phase_dialog`,
    `strategic_report_popup`, `popup_base`, `mailbox_panel`) ever saw the key.

    The fix: when `not command_input.editable` the arm returns at once,
    WITHOUT `accept_event()`, so Esc travels on to the popup's own handler, as
    it does for an unfocused line.

    NOT verified without the engine: the premise (a disabled line keeps focus
    under a modal, and the modal's hatch then runs ahead of main's
    `_unhandled_input`) is the orchestrator's Mode C walk."""

    def _arm(self) -> str:
        body = _w1_func(_w1_src(), "_on_command_input_gui_input")
        return body[body.index("elif event.keycode == KEY_ESCAPE:"):]

    def test_a_disabled_line_returns_before_the_ladder_and_before_it_consumes(self):
        arm = self._arm()
        guard = arm.index("if not command_input.editable:")
        assert arm[guard:].split("\n", 2)[1].strip() == "return"
        assert guard < arm.index("_clear_suggestions()")
        assert guard < arm.index("_escape_closes_topmost()")
        assert guard < arm.index("command_input.accept_event()")
        assert "accept_event" not in arm[:arm.index("if not _suggestions.is_empty():")], \
            "nothing consumes the key on the disabled path"

    def test_the_open_line_keeps_the_ruled_ladder(self):
        """CX-3 / CC-3 / DDB-54: the list, then the selection, then the
        topmost thing, then the release -- and the key consumed."""
        arm = self._arm()
        rungs = ("_clear_suggestions()", "_clear_order_selection()",
                 "_escape_closes_topmost()", "command_input.release_focus()",
                 "command_input.accept_event()")
        positions = [arm.index(r) for r in rungs]
        assert positions == sorted(positions)

    def test_the_guard_reads_the_editable_flag_the_gate_writes(self):
        body = _w1_func(_w1_src(), "set_input_enabled")
        assert "command_input.editable = enabled" in body


