@contextlib.contextmanager
def _w1_served(world):
    """Swap the three module globals together and restore them."""
    import backend.main as M
    from backend.commands.parser import CommandParser
    from fastapi.testclient import TestClient
    saved = (M.game_state["world"], M.world, M.parser)
    M.game_state["world"] = world
    M.world = world
    M.parser = CommandParser(use_real_llm=False)
    try:
        with _w1_quiet():
            yield TestClient(M.app)
    finally:
        M.game_state["world"], M.world, M.parser = saved


def _w1_letter(world, court: str = "Austria"):
    """A routine court's letter (a current-turn offer: the Cabinet locks) --
    Austria's peace that asks 300 gold, on the shipped board."""
    from backend.game_logic.ai_diplomacy import _make_proposal, deliver_ai_proposal
    terms = {"type": "peace", "proposer_nation": court, "target_nation": "France",
             "demands": [{"type": "gold_lump", "value": 300}], "sweeteners": [], "clauses": []}
    with _w1_quiet():
        return deliver_ai_proposal(_make_proposal(court, "peace", 5, terms, world), world)


def _w1_call(world, ally: str = "Spain", target: str = "Britain"):
    from backend.game_logic import call_to_arms
    with _w1_quiet():
        return call_to_arms.post_call(world, ally=ally, target=target, callee="France", war_id="w1")


def _w1_base(world) -> dict:
    import backend.main as M
    with _w1_quiet():
        return M.build_base_response(world, success=True, message="x")


class TestS14EX91:
    """Reproduced: `/diplomatic_preview` carried `dialogue_pending: true` for a
    hard-stop or local-planning dialogue and no word of WHICH, so the wizard's
    zero-envoy notice said only "Resolve the active diplomatic dialogue before
    starting a new action." -- an instruction with no object.

    The fix: both preview payloads carry `dialogue_pending_name` (the active
    dialogue through `display_names.dialogue_display_name`; "" for a letter,
    which the Envoys arm names itself), and the notice prints "Resolve the
    active dialogue first -- <name> ..." (number-neutral: the display strings
    include plural noun phrases such as "the terms you are drafting")."""

    def _push(self, world, dtype: str):
        world.dialogue_manager.push({"type": dtype, "blocking": False})

    def test_the_nations_payload_names_the_dialogue(self, _w1_world):
        self._push(_w1_world, "terms_guidance")
        with _w1_served(_w1_world) as client:
            reply = client.get("/diplomatic_preview").json()
        assert reply["dialogue_pending"] is True
        assert reply["dialogue_pending_name"] == "the terms you are drafting"

    def test_the_court_payload_names_it_too(self, _w1_world):
        self._push(_w1_world, "advisory")
        with _w1_served(_w1_world) as client:
            reply = client.get("/diplomatic_preview", params={"nation": "Austria"}).json()
        assert reply["success"] is True and reply["dialogue_pending"] is True
        assert reply["dialogue_pending_name"] == "Talleyrand's counsel"

    def test_a_hard_stop_is_named_the_same_way(self, _w1_world):
        self._push(_w1_world, "war_purpose_selection")
        with _w1_served(_w1_world) as client:
            reply = client.get("/diplomatic_preview").json()
        assert reply["dialogue_pending_name"] == "a war purpose yet to be declared"

    def test_nothing_pending_names_nothing(self, _w1_world):
        with _w1_served(_w1_world) as client:
            reply = client.get("/diplomatic_preview").json()
            court = client.get("/diplomatic_preview", params={"nation": "Austria"}).json()
        assert reply["dialogue_pending"] is False and reply["dialogue_pending_name"] == ""
        assert court["dialogue_pending_name"] == ""

    def test_a_letter_is_not_named_by_a_raw_key(self, _w1_world):
        """The offers arm is the envoy count's; the name stays empty rather
        than title-casing `incoming_proposal` at the player."""
        _w1_letter(_w1_world)
        with _w1_served(_w1_world) as client:
            reply = client.get("/diplomatic_preview").json()
        assert reply["dialogue_pending"] is True and reply["pending_envoy_count"] >= 1
        assert reply["dialogue_pending_name"] == ""

    def test_every_gating_type_has_a_display_name(self):
        """The notice never falls to the raw-key fallback for a type that can
        gate the wizard."""
        from backend.display_names import DIALOGUE_TYPE_DISPLAY
        from backend.models.dialogue_manager import DialogueManager as DM
        for dtype in sorted(DM.HARD_STOP_TYPES | DM.LOCAL_PLANNING_TYPES):
            assert dtype in DIALOGUE_TYPE_DISPLAY, dtype

    def test_the_wizard_prints_the_name_in_the_sentence(self):
        wiz = _w1_src("diplomacy_wizard.gd")
        body = _w1_func(wiz, "_add_dialogue_gate_notice")
        assert "Resolve the active dialogue first — " in body
        assert "awaiting your answer" in body
        assert "Resolve the active diplomatic dialogue before starting a new action." not in body
        # the name rides the payload to both renders
        for render in ("_render_nations", "_render_preview"):
            assert 'data.get("dialogue_pending_name", "")' in _w1_func(wiz, render), render

    def test_an_unnamed_dialogue_still_reads_as_a_sentence(self):
        body = _w1_func(_w1_src("diplomacy_wizard.gd"), "_add_dialogue_gate_notice")
        assert 'if dialogue_name != "":' in body
        assert "Resolve the active dialogue first." in body


class TestS14EX92:
    """Reproduced: `Utils.cabinet_shut_line()` says "or the turn ends" -- exact
    for a letter's first (only) turn, but an ally's call to arms stands to its
    answer-by turn (`keeps_open`: two turns), so on its first turn the Cabinet
    button's tooltip and the wizard's notice promised a release a turn early.
    The Not Now echo and tooltip already passed `answer_by_turn`.

    The fix: the base payload (`build_base_response`, `/test`) and both
    `/diplomatic_preview` payloads carry `cabinet_locked_until` (int; the
    latest answer-by turn of a standing call to arms while it is still ahead,
    else 0) beside `cabinet_locked`, and `_set_cabinet_locked` and the wizard's
    notice thread it into `Utils.cabinet_shut_line`."""

    def test_a_call_to_arms_names_its_answer_by_turn(self, _w1_world):
        assert _w1_call(_w1_world) is not None
        reply = _w1_base(_w1_world)
        assert reply["cabinet_locked"] is True
        assert reply["cabinet_locked_until"] == int(_w1_world.current_turn) + 2
        assert isinstance(reply["cabinet_locked_until"], int)

    def test_a_routine_letter_lifts_with_the_turn(self, _w1_world):
        _w1_letter(_w1_world)
        reply = _w1_base(_w1_world)
        assert reply["cabinet_locked"] is True and reply["cabinet_locked_until"] == 0

    def test_no_letter_no_lock_no_turn(self, _w1_world):
        reply = _w1_base(_w1_world)
        assert reply["cabinet_locked"] is False and reply["cabinet_locked_until"] == 0

    def test_on_the_answer_by_turn_the_generic_sentence_is_exact(self, _w1_world):
        """The call lapses at the end of its answer-by turn: "the turn ends" is
        true again, and the figure falls away."""
        _w1_call(_w1_world)
        _w1_world.current_turn = int(_w1_world.current_turn) + 2
        reply = _w1_base(_w1_world)
        assert reply["cabinet_locked"] is True and reply["cabinet_locked_until"] == 0

    def test_the_latest_call_wins(self, _w1_world):
        _w1_call(_w1_world, "Spain", "Britain")
        first = _w1_base(_w1_world)["cabinet_locked_until"]
        _w1_world.current_turn = int(_w1_world.current_turn) + 1
        _w1_call(_w1_world, "Bavaria", "Britain")
        later = _w1_base(_w1_world)["cabinet_locked_until"]
        assert later >= first and later == int(_w1_world.current_turn) + 2

    def test_a_call_among_letters_still_names_the_turn(self, _w1_world):
        _w1_letter(_w1_world)
        _w1_call(_w1_world)
        assert _w1_base(_w1_world)["cabinet_locked_until"] == int(_w1_world.current_turn) + 2

    def test_the_connection_test_and_both_previews_carry_it(self, _w1_world):
        _w1_call(_w1_world)
        want = int(_w1_world.current_turn) + 2
        with _w1_served(_w1_world) as client:
            hello = client.get("/test").json()
            nations = client.get("/diplomatic_preview").json()
            court = client.get("/diplomatic_preview", params={"nation": "Austria"}).json()
        assert hello["cabinet_locked_until"] == want
        assert nations["cabinet_locked_until"] == want and court["cabinet_locked_until"] == want

    def test_a_moment_letter_locks_nothing(self, _w1_world):
        """EVENTS_SPEC section 3.4 seam 9 stands: the figure follows the flag."""
        reply = _w1_base(_w1_world)
        assert reply["cabinet_locked"] is False and reply["cabinet_locked_until"] == 0

    def test_the_button_tooltip_threads_the_turn(self):
        src = _w1_src()
        body = _w1_func(src, "_set_cabinet_locked")
        assert "until" in body and "Utils.cabinet_shut_line(until)" in body
        upd = _w1_func(src, "_update_diplomatic_top_bar")
        assert ('_set_cabinet_locked(bool(response.get("cabinet_locked", false)), '
                'int(response.get("cabinet_locked_until", 0)))') in upd

    def test_the_wizard_notice_threads_the_turn(self):
        wiz = _w1_src("diplomacy_wizard.gd")
        body = _w1_func(wiz, "_add_dialogue_gate_notice")
        assert "Utils.cabinet_shut_line(locked_until)" in body
        for render in ("_render_nations", "_render_preview"):
            assert 'int(data.get("cabinet_locked_until", 0))' in _w1_func(wiz, render), render

    def test_the_sentence_itself_is_unchanged(self):
        """`cabinet_shut_line(0)` is the generic sentence the letters' pins
        read; a positive turn names it."""
        body = _w1_func(_w1_src("utils.gd"), "cabinet_shut_line")
        assert "the Cabinet stays shut until it is answered or the turn ends." in body
        assert "turn %d ends." in body


# ======================================================================
# S14E-X79 -- the province panel's attack chips and the muster
# ======================================================================

class TestS14EX79:
    """Reproduced (by source, and on the shipped board): the map attack card
    shows Berthier's one-line muster (`quote.muster`, S14E-24), but the province
    panel's two attack surfaces did not -- `_quote_rows` (the ATTACK <enemy>
    rows) printed `_quote_notes` without it, and the older Attack chips in a
    marshal's own row (corps and enemy in the SAME province) sent at once with
    no quote at all (`march_quotes_for_region` quoted only the corps standing
    AWAY).

    The fix: `_quote_notes` prints a short tail of `q.muster` for kind
    `attack`; each attack row of `march_quotes_for_region` carries `here` --
    the same `attack_quote` for the corps already standing in the province --
    and the marshal row prints its muster tail under the chip."""

    def _board(self, world):
        ney = world.get_marshal("Ney")
        ney.location = "Swabia"
        world._build_marshal_index()
        world.calculate_visibility()
        return ney, world.get_marshal("Mack")

    def test_the_attack_rows_quote_the_corps_standing_here(self, _w1_world):
        from backend.commands.order_quotes import attack_quote, march_quotes_for_region
        ney, mack = self._board(_w1_world)
        with _w1_quiet():
            payload = march_quotes_for_region(_w1_world, "Swabia")
        row = next(r for r in payload["attack"] if r["enemy"] == "Mack")
        here = {q["marshal"]: q for q in row["here"]}
        assert "Ney" in here and here["Ney"]["ok"] and here["Ney"]["kind"] == "attack"
        assert here["Ney"]["muster"].startswith("Berthier adds: ")
        with _w1_quiet():
            assert here["Ney"]["muster"] == attack_quote(_w1_world, ney, mack)["muster"]

    def test_the_away_quotes_are_unchanged(self, _w1_world):
        from backend.commands.order_quotes import march_quotes_for_region
        self._board(_w1_world)
        with _w1_quiet():
            payload = march_quotes_for_region(_w1_world, "Swabia")
        row = next(r for r in payload["attack"] if r["enemy"] == "Mack")
        assert all(q["marshal"] != "Ney" for q in row["quotes"])
        assert {"enemy", "enemy_shown", "quotes", "here"} == set(row)

    def test_a_province_with_nobody_of_ours_has_an_empty_here(self, _w1_world):
        from backend.commands.order_quotes import march_quotes_for_region
        _w1_world.calculate_visibility()
        with _w1_quiet():
            payload = march_quotes_for_region(_w1_world, "Swabia")
        for row in payload["attack"]:
            assert row["here"] == []

    def test_the_quote_rows_print_the_muster_for_an_attack(self):
        body = _w1_func(_w1_src("region_panel.gd"), "_quote_notes")
        assert 'str(q.get("kind", "")) == "attack"' in body
        assert 'q.get("muster", "")' in body
        assert "_muster_tail(" in body
        assert body.index('q.get("muster", "")') < body.index('"he may object"')

    def test_the_tail_is_short_and_keeps_the_band(self):
        body = _w1_func(_w1_src("region_panel.gd"), "_muster_tail")
        assert '"Berthier adds: "' in body
        assert '" — "' in body
        assert "parts.size() > 2" in body

    def test_the_older_chips_print_the_muster_under_the_row(self):
        src = _w1_src("region_panel.gd")
        row = _w1_func(src, "_format_marshal_row")
        assert "_here_attack_muster(m_name, enemy)" in row
        assert "muster_lines" in row
        # the chip's own expression is the census's pinned text -- untouched
        assert '"do:" + m_name + ", attack " + enemy_shown' in row
        lookup = _w1_func(src, "_here_attack_muster")
        assert "_quotes_region != _region" in lookup
        assert 'row.get("here", [])' in lookup

    def test_a_dimmed_attack_chip_prints_no_muster(self):
        row = _w1_func(_w1_src("region_panel.gd"), "_format_marshal_row")
        chip = row[row.index('if attack_why == "":'):row.index("if not fortified and fortify_why")]
        assert chip.index("_here_attack_muster(") < chip.index("else:")

