# ══════════════════════════════════════════════════════════════════════════
# S14E-X141 -- "recruit two infantry for Davout" raises ONE levy and never says so
# ══════════════════════════════════════════════════════════════════════════

_W10_SAID = "one levy per order"


class TestS14EX141:
    """S14E-X141 -- a count in a recruit order is silently dropped (S14E-33's
    class: "lay down TWO ships" laid one keel and said nothing; XA3 did the
    same for buildings).

    Reproduced (the shipped 1805 board, the real endpoint): "recruit two
    infantry for Davout" -> "Davout recruits 3,000 infantry at Rhineland
    (field levy ...) - Cost: 741 gold" -- ONE levy and not a word that the two
    was ignored; the same on "recruit 2 infantry" (where PF-7 said "your 2 is
    noted", as if two MEN had been asked), "recruit three levies" and
    "recruit a pair of infantry".

    The fix: `naval_executor.recruit_count_in` is the one count reader's third
    noun set (infantry, cavalry, artillery, levy / levies, regiments,
    battalions, squadrons, batteries, corps ...); a count of 2-10 before a unit
    noun is said not to be read ("; one levy per order -- the two is not
    read"), and PF-7's "your N is noted" no longer misreads that small figure
    as an amount of men.  A figure over ten ("recruit 5000 infantry") is an
    AMOUNT and reads as before.  The levy itself, the price and the AI's
    recruiting (`_acting_nation`) are untouched.
    """

    def test_the_sighting_says_the_two_is_not_read(self, _w10_client, _w10_world):
        w = _w10_world
        davout = w.get_marshal("Davout")
        gold, men, pool = int(w.nation_gold["France"]), int(davout.strength), int(w.manpower_pools["France"]["infantry"])
        reply = _w10_say(_w10_client, "recruit two infantry for Davout")
        text = str(reply.get("message") or "")
        assert reply.get("success") is True, text
        assert "Davout recruits 3,000 infantry" in text, text
        assert f"{_W10_SAID} — the two is not read" in text, text
        # shown == applied: ONE levy, ONE price
        quoted = int(re.search(r"Cost: (\d+) gold", text).group(1))
        assert gold - int(w.nation_gold["France"]) == quoted
        assert int(davout.strength) - men == 3000
        assert pool - int(w.manpower_pools["France"]["infantry"]) == 3000

    @pytest.mark.parametrize("line,word", (
        ("recruit 2 infantry for Davout", "two"),
        ("recruit three levies for Davout", "three"),
        ("recruit a pair of infantry for Davout", "two"),
        ("recruit a couple of infantry for Davout", "two"),
        ("recruit two more infantry for Davout", "two"),
        ("Davout, recruit two infantry corps", "two"),
        ("recruit 4 regiments for Davout", "four"),
        ("recruit 10 infantry for Davout", "ten"),
    ))
    def test_every_count_phrasing_is_named(self, line, word, _w10_client):
        text = str(_w10_say(_w10_client, line).get("message") or "")
        assert "recruits 3,000 infantry" in text, (line, text)
        assert f"{_W10_SAID} — the {word} is not read" in text, (line, text)
        assert "is noted" not in text, (line, text)      # a count is not an amount

    def test_the_cavalry_noun_is_read_too(self, _w10_client, _w10_world):
        _w10_world.nation_gold["France"] = 5000
        text = str(_w10_say(_w10_client, "recruit two cavalry for Murat").get("message") or "")
        assert "Murat recruits" in text and f"{_W10_SAID} — the two is not read" in text, text

    @pytest.mark.parametrize("line", (
        "recruit infantry for Davout", "recruit for Davout", "Davout, recruit",
        "recruit one infantry for Davout", "recruit 1 infantry for Davout",
        "recruit an infantry corps for Davout", "recruit a levy for Davout"))
    def test_no_count_or_a_count_of_one_is_unchanged(self, line, _w10_client):
        text = str(_w10_say(_w10_client, line).get("message") or "")
        assert "recruits 3,000 infantry" in text, (line, text)
        assert "not read" not in text, (line, text)
        assert "is noted" not in text, (line, text)

    @pytest.mark.parametrize("line,figure", (
        ("recruit 5000 infantry for Davout", "5,000"),
        ("recruit 3000 men for Davout", "3,000"),
        ("recruit 100 infantry for Davout", "100"),
        ("recruit 20000 infantry for Davout", "20,000"),
        ("recruit 5k infantry for Davout", "5,000"),
        ("recruit 12 infantry for Davout", "12")))
    def test_an_amount_is_still_noted_by_pf7_and_is_no_count(self, line, figure, _w10_client):
        text = str(_w10_say(_w10_client, line).get("message") or "")
        assert "recruits 3,000 infantry" in text, (line, text)
        assert f"your {figure} is noted" in text, (line, text)
        assert "not read" not in text, (line, text)

    def test_two_thousand_is_an_amount_not_a_count(self, _w10_client):
        text = str(_w10_say(_w10_client, "recruit two thousand infantry for Davout")
                   .get("message") or "")
        assert "recruits 3,000 infantry" in text, text
        assert "not read" not in text, text

    def test_the_levy_is_what_a_bare_order_raises(self, _w10_boot):
        """Pin the recruit itself unchanged: the count phrase changes the
        reply, never the levy (men, morale, pool, gold)."""
        from fastapi.testclient import TestClient
        from backend.commands.parser import CommandParser
        from backend.models.world_state import WorldState
        import backend.main as main_module
        seen = []
        for line in ("recruit infantry for Davout", "recruit two infantry for Davout"):
            w = WorldState.from_dict(json.loads(json.dumps(_w10_boot.to_dict(), default=str)))
            old = (main_module.world, main_module.game_state, main_module.parser)
            main_module.world, main_module.game_state = w, {"world": w}
            main_module.parser = CommandParser(use_real_llm=False)
            try:
                reply = _w10_say(TestClient(main_module.app), line)
            finally:
                main_module.world, main_module.game_state, main_module.parser = old
            d = w.get_marshal("Davout")
            seen.append((reply.get("success"), int(d.strength), int(d.morale),
                         int(w.nation_gold["France"]), int(w.manpower_pools["France"]["infantry"]),
                         int(w.actions_remaining), int(w.admin_actions_remaining)))
        assert seen[0] == seen[1], seen

    def test_the_reader(self):
        from backend.commands.naval_executor import recruit_count_in
        assert recruit_count_in("recruit two infantry for Davout") == 2
        assert recruit_count_in("recruit 3 levies") == 3
        assert recruit_count_in("recruit a pair of cavalry") == 2
        assert recruit_count_in("recruit one infantry") == 1
        assert recruit_count_in("recruit ten infantry") == 10
        assert recruit_count_in("recruit 5000 infantry") is None
        assert recruit_count_in("recruit 3,000 infantry") is None
        assert recruit_count_in("recruit eleven infantry") is None
        assert recruit_count_in("recruit 11 infantry") is None
        assert recruit_count_in("recruit two thousand infantry") is None
        assert recruit_count_in("recruit 500 men") is None
        assert recruit_count_in("recruit infantry in 2 turns") is None
        assert recruit_count_in("recruit infantry for 700 gold") is None
        assert recruit_count_in("") is None and recruit_count_in(None) is None
        # the nouns do not cross: ships and buildings keep their own readers
        from backend.commands.naval_executor import building_count_in, ship_count_in
        assert ship_count_in("recruit two infantry") is None
        assert building_count_in("recruit two infantry") is None
        assert recruit_count_in("lay down two ships") is None
        assert recruit_count_in("build two depots in Paris") is None
        assert ship_count_in("lay down two ships") == 2 and building_count_in("build 3 depots") == 3

    def test_the_ai_recruits_are_untouched(self, _w10_world):
        """An AI levy carries `_acting_nation`: whatever a stray `raw_command`
        holds, its reply is byte-identical."""
        from backend.commands.executor import CommandExecutor
        w = _w10_world
        with _w10_quiet():
            ex = CommandExecutor()
        w.nation_gold["France"] = 5000
        cmd = {"marshal": "Davout", "_acting_nation": "France",
               "raw_command": "recruit two infantry for Davout"}
        result = ex._economy._execute_recruit(cmd, {"world": w}, raw_text="recruit two infantry for Davout")
        assert result.get("success") is True, result
        assert "not read" not in str(result.get("message") or ""), result
        assert "is noted" not in str(result.get("message") or ""), result

    def test_the_build_reply_is_untouched(self, _w10_client):
        """The sibling XA3's clause keeps its own reader and sentence."""
        text = str(_w10_say(_w10_client, "build two depots in Paris").get("message") or "")
        assert "one building at a time per province — the two is not read" in text, text
        assert _W10_SAID not in text, text


# ══════════════════════════════════════════════════════════════════════════
# S14E-X143 -- "everyone stop" / "stop everyone" / "Ney and Davout stop"
# ══════════════════════════════════════════════════════════════════════════

def _w10_three_orders(client, world) -> list:
    """Ney, Davout and Lannes each on a standing march (two actions apiece);
    the pool is refilled to nine, and the turn moved on so that a recall is a
    mid-march one (-3 trust each, the ordinary cancel's price)."""
    world.actions_remaining = 9
    for line in ("Ney, march to Orleanais", "Davout, march to Nivernais",
                 "Lannes, march to Orleanais"):
        reply = _w10_say(client, line)
        assert reply.get("success") is True, (line, reply.get("message"))
    held = [m.name for m in world.get_player_marshals() if m.strategic_order is not None]
    assert held == ["Ney", "Davout", "Lannes"], held
    world.current_turn += 1
    world.actions_remaining = 9
    return held


class TestS14EX143:
    """S14E-X143 -- the cancel for the whole army: "everyone stop", "stop
    everyone", "all marshals stop" and "Ney and Davout stop" parse Unknown
    while "everyone attack Mack", the comma forms and "everyone halt" work.

    Reproduced (the keyless parser on the 1805 board): "everyone stop" /
    "stop everyone" / "all marshals stop" / "everyone cancel" / "everybody
    abort" / "Ney and Davout stop" -> success False, "Unknown action:
    unknown".  And the forms that DID parse ("everyone, stop", "everyone
    halt") read as a cancel with no name, which the executor ran on the FIRST
    corps holding an order only: with Ney, Davout and Lannes on the road,
    "everyone, stop" recalled Ney (1 action) and answered "Ney halts his march
    and awaits new orders" -- two thirds of the army marching on.

    The fix: (1) `group_orders.is_collective_cancel` -- the army road's own
    words (`_COLLECTIVE_WHO`, built from the head regex's alternation) with
    one of cancel / stop / abort / halt in either order -- read by the mock
    parser (`llm_client._group_cancel_phrase`); (2) the collective road
    (`group_orders._collective_cancel`) recalls EVERY standing order, each as
    the ordinary `cancel` (its own price and trust), the reply opening with the
    sum against the pool and naming every corps; fewer than two orders ride the
    ordinary road as before; (3) `parser._split_second_name` lets the comma go
    when the order is the bare recall ("Ney and Davout stop" -- the second man
    rides the relay, as "Ney and Davout, stop" does).
    """

    @pytest.mark.parametrize("line", (
        "everyone stop", "Everyone stop.", "everybody stop", "all marshals stop", "all stop",
        "all of you stop", "stop everyone", "stop everybody", "stop all marshals",
        "everyone cancel", "everyone abort", "everyone halt", "cancel everyone",
        "abort all", "halt all marshals", "everyone, stop", "all marshals, stop",
        "everyone stop now", "please stop everyone", "the army stop", "stop the army",
        "the army, stop", "cancel all orders", "cancel all marches", "stop all orders",
        "cancel everyone's orders", "everyone, cancel your orders", "everyone cancel your marches",
        "belay everyone", "everyone belay"))
    def test_the_collective_recall_parses_to_the_cancel_with_no_name(self, line, _w10_board):
        result = _w10_parse(_w10_board, line)
        command = result.get("command") or {}
        assert result.get("success") is True, (line, result.get("message") or result.get("error"))
        assert command.get("action") == "cancel" and not command.get("marshal"), (line, command)

    @pytest.mark.parametrize("line", (
        "Ney and Davout stop", "ney and davout stop", "Ney & Davout abort", "Ney, Davout stop",
        "Ney and Davout cancel", "Ney and Davout halt", "Ney, Davout and Soult stop",
        "Marshal Ney and Marshal Davout stop"))
    def test_a_list_of_marshals_before_the_bare_recall_is_the_relay_address(self, line, _w10_board):
        result = _w10_parse(_w10_board, line)
        command = result.get("command") or {}
        assert result.get("success") is True, (line, result.get("message") or result.get("error"))
        assert command.get("action") == "cancel" and command.get("marshal") == "Ney", (line, command)
        assert result.get("dropped_sequel_kind") == "second_name", (line, result)
        assert result.get("second_marshal") == "Davout", (line, result)
        assert re.match(r"^Davout, (cancel|stop|abort|halt)$", result.get("dropped_sequel") or ""), result

    def test_the_comma_form_and_the_comma_less_form_are_one_address(self, _w10_board):
        with_comma = _w10_parse(_w10_board, "Ney and Davout, stop")
        without = _w10_parse(_w10_board, "Ney and Davout stop")
        for key in ("dropped_sequel", "second_marshal", "second_marshal_lead",
                    "second_marshal_others", "warning"):
            assert with_comma.get(key) == without.get(key), (key, with_comma, without)

    @pytest.mark.parametrize("line", (
        "Ney stop", "stop Ney", "stop", "cancel", "halt", "stop the war", "stop Mack",
        "stop Zorglub", "stop the war with Britain", "Ney, stop attacking", "everyone stop attacking",
        "stop everyone's pay", "Murat please stop"))
    def test_nothing_else_became_the_collective_recall(self, line, _w10_board):
        from backend.commands.group_orders import is_collective_cancel
        assert not is_collective_cancel(line), line
        result = _w10_parse(_w10_board, line)
        command = result.get("command") or {}
        if command.get("action") == "cancel":
            # the older readings: a named marshal, or the bare verb with no address
            assert command.get("marshal") or line in ("stop", "cancel", "halt") or "attacking" in line, (line, command)

    def test_the_other_collective_orders_are_untouched(self, _w10_board):
        for line, action in (("everyone attack Mack", "attack"), ("everyone fortify", "fortify"),
                             ("all marshals hold", "hold"), ("everyone retreat", "retreat")):
            command = _w10_parse(_w10_board, line).get("command") or {}
            assert command.get("action") == action and not command.get("marshal"), (line, command)

    def test_the_older_pins_flip_for_the_army_words(self, _w10_board):
        """S14E-X73 / XN1 pinned "the army stop" / "stop the army" as NOT the
        cancel (a marshal of ours must head the verb).  The army is the
        collective address the army road already reads ("the army marches on
        Swabia"), and "halt the army" / "the army, stop" were already the
        cancel: they are now the collective recall, in every word order."""
        for line in ("the army stop", "stop the army"):
            command = _w10_parse(_w10_board, line).get("command") or {}
            assert command.get("action") == "cancel" and not command.get("marshal"), (line, command)

    # ── the executor: shown == applied ────────────────────────────────────

    def test_everyone_stop_recalls_every_standing_order_and_says_so(self, _w10_client, _w10_world):
        from backend.commands.strategic_executor import cancel_trust_change
        w = _w10_world
        held = _w10_three_orders(_w10_client, w)
        expected_trust = {n: w.get_marshal(n).trust.value
                          + cancel_trust_change(w.get_marshal(n).strategic_order, w.current_turn)
                          for n in held}
        assert set(expected_trust.values()) != {w.get_marshal(n).trust.value for n in held}   # (-3 each)
        reply = _w10_say(_w10_client, "everyone stop")
        text = str(reply.get("message") or "")
        assert reply.get("success") is True, text
        # the sum against the pool, then every corps by name
        assert text.startswith("Every standing order is recalled, corps by corps — 3 corps, 3 actions for the 9 in hand."), text
        for name in held:
            assert f"{name}: {name} halts his march and awaits new orders." in text, (name, text)
        # applied == shown: three actions, every order gone, the ordinary trust each
        assert 9 - int(w.actions_remaining) == 3
        assert int((reply.get("action_info") or {}).get("cost")) == 3, reply.get("action_info")
        assert [m.name for m in w.get_player_marshals() if m.strategic_order is not None] == []
        assert {n: w.get_marshal(n).trust.value for n in held} == expected_trust

    @pytest.mark.parametrize("line", ("stop everyone", "all marshals halt", "everyone, stop",
                                      "the army cancel", "everybody abort", "cancel all orders",
                                      "belay everyone", "everyone, cancel your marches"))
    def test_every_word_order_recalls_the_whole_army(self, line, _w10_client, _w10_world):
        w = _w10_world
        _w10_three_orders(_w10_client, w)
        reply = _w10_say(_w10_client, line)
        assert reply.get("success") is True, (line, reply.get("message"))
        assert "3 corps, 3 actions" in str(reply.get("message") or ""), (line, reply.get("message"))
        assert [m.name for m in w.get_player_marshals() if m.strategic_order is not None] == [], line

    def test_the_pool_stops_the_recall_and_names_who_was_left(self, _w10_client, _w10_world):
        w = _w10_world
        _w10_three_orders(_w10_client, w)
        w.actions_remaining = 2
        reply = _w10_say(_w10_client, "everyone stop")
        text = str(reply.get("message") or "")
        assert reply.get("success") is True, text
        assert "3 corps, 3 actions for the 2 in hand." in text, text
        assert "Nothing left for Lannes today" in text, text
        assert "Ney: Ney halts" in text and "Davout: Davout halts" in text, text
        assert 2 - int(w.actions_remaining) == 2 and int(reply["action_info"]["cost"]) == 2
        left = [m.name for m in w.get_player_marshals() if m.strategic_order is not None]
        assert left == ["Lannes"], left

    def test_no_standing_order_is_the_ordinary_refusal_and_free(self, _w10_client, _w10_world):
        w = _w10_world
        before = int(w.actions_remaining)
        for line in ("everyone stop", "stop everyone"):
            reply = _w10_say(_w10_client, line)
            assert reply.get("success") is False
            assert str(reply.get("message") or "") == "No marshal has an active strategic order to cancel.", reply
        assert int(w.actions_remaining) == before

    def test_one_standing_order_is_exactly_the_ordinary_cancel(self, _w10_client, _w10_world):
        w = _w10_world
        w.actions_remaining = 9
        assert _w10_say(_w10_client, "Ney, march to Orleanais").get("success") is True
        w.current_turn += 1
        w.actions_remaining = 9
        reply = _w10_say(_w10_client, "everyone stop")
        assert reply.get("success") is True
        assert str(reply.get("message") or "") == "Ney halts his march and awaits new orders.", reply
        assert 9 - int(w.actions_remaining) == 1
        assert w.get_marshal("Ney").strategic_order is None

    def test_the_named_cancel_and_the_bare_verb_are_untouched(self, _w10_client, _w10_world):
        w = _w10_world
        _w10_three_orders(_w10_client, w)
        reply = _w10_say(_w10_client, "Davout, stop")
        assert str(reply.get("message") or "") == "Davout halts his march and awaits new orders.", reply
        assert [m.name for m in w.get_player_marshals() if m.strategic_order is not None] == ["Ney", "Lannes"]
        # the bare verb (no address) recalls the first, one action, as it always did
        reply = _w10_say(_w10_client, "stop")
        assert str(reply.get("message") or "") == "Ney halts his march and awaits new orders.", reply
        assert [m.name for m in w.get_player_marshals() if m.strategic_order is not None] == ["Lannes"]

    def test_the_list_address_recalls_the_first_and_relays_the_second(self, _w10_client, _w10_world):
        w = _w10_world
        _w10_three_orders(_w10_client, w)
        reply = _w10_say(_w10_client, "Ney and Davout stop")
        text = str(reply.get("message") or "")
        assert reply.get("success") is True, text
        assert "Ney halts his march and awaits new orders." in text, text
        assert "Davout" in text, text                      # the second man is HEARD (the relay's note)
        assert reply.get("dropped_sequel") == "Davout, stop", reply.get("dropped_sequel")
        assert w.get_marshal("Ney").strategic_order is None
        assert w.get_marshal("Davout").strategic_order is not None   # his own waits for the seal

    def test_the_golden_corpus_holds_the_rows(self):
        corpus = json.loads((Path(__file__).parent / "data" / "parser_golden_corpus.json")
                            .read_text(encoding="utf-8"))
        rows = {e["utterance"]: e for e in corpus["entries"]}
        for utterance in ("everyone stop", "stop everyone", "Ney and Davout stop"):
            assert utterance in rows, utterance
            assert rows[utterance]["expected"]["action"] == "cancel", utterance

    def test_the_routed_order_words_are_unmoved(self):
        """The addressee rule's verb set is generated from the router's
        branches (CX-R1): the new arm adds no verb the set lacks."""
        from backend.ai.routed_order_words import ROUTED_ORDER_WORDS
        assert {"cancel", "stop", "abort", "halt"} <= set(ROUTED_ORDER_WORDS)


# ══════════════════════════════════════════════════════════════════════════
# S14E-X144 -- a refusal that quotes a bare attack names no preview
# ══════════════════════════════════════════════════════════════════════════

_W10_HINT = ("Ask 'what if Ney attacks Mack' first — it names who marches with "
             "Ney, and costs nothing.")


class TestS14EX144:
    """S14E-X144 -- S14E-24 taught the TODAY list the free preview and XC3 five
    other counsel lists; the refusals and the shrug that QUOTE an attack to
    try did not.

    Reproduced (the shipped 1805 board, the real endpoint): "Ney, move to
    Swabia" -> "Cannot move into Swabia - enemy forces present! ... Try: 'Ney,
    attack Mack'" and no word of "what if Ney attacks Mack"; the same on the
    engaged march ("Try: 'Ney, attack Mack' or 'Ney, retreat'"), the attack
    elsewhere while engaged ("Attack Mack in Swabia first"), "attack the
    Austrians at Lorraine" ("Order 'Ney, attack Mack'."), and the shrug's
    "Perhaps: 'Ney, attack Mack'" / "Try: 'Ney, attack Bavaria'".

    The fix: `movement_executor.attack_preview_hint_for(who, foe)` (the very
    sentence the TODAY list carries, `dispatch.attack_preview_hint`) appended
    after each quoted attack; the shrug's twin is
    `llm_client._attack_preview_sentence`.  Byte-identical where no attack is
    quoted.
    """

    def test_a_move_into_an_enemy_names_the_preview(self, _w10_client):
        text = str(_w10_say(_w10_client, "Ney, move to Swabia").get("message") or "")
        assert "Try: 'Ney, attack Mack'." in text, text
        assert _W10_HINT in text, text
        assert text.index("Try: 'Ney, attack Mack'") < text.index(_W10_HINT)

    @pytest.mark.parametrize("line", ("Ney, march to Orleanais", "Ney, move to Orleanais",
                                      "Ney, attack ArchdukeJohn"))
    def test_an_engaged_march_names_the_preview(self, line, _w10_client, _w10_world):
        _w10_world.get_marshal("Ney").location = "Swabia"        # with Mack
        text = str(_w10_say(_w10_client, line).get("message") or "")
        assert "cannot begin a strategic march" in text, (line, text)
        assert "Try: 'Ney, attack Mack' or 'Ney, retreat'." in text, (line, text)
        assert _W10_HINT in text, (line, text)

    def test_an_attack_elsewhere_while_engaged_names_the_preview(self, _w10_client, _w10_world):
        w = _w10_world
        w.get_marshal("Ney").location = "Swabia"                  # with Mack
        w.get_marshal("ArchdukeJohn").location = "Munich"         # in range, elsewhere
        text = str(_w10_say(_w10_client, "Ney, attack ArchdukeJohn").get("message") or "")
        assert "Cannot attack elsewhere while engaged" in text, text
        assert "Attack Mack in Swabia first." in text, text
        # S14E-X178 flips this pin: the sentence before the hint ends "first.",
        # so the hint drops its own "first" (the joined sentence said it twice).
        assert _W10_HINT.replace("' first — ", "' — ") in text, text

    def test_a_named_court_with_no_force_in_sight_names_the_preview(self, _w10_client):
        text = str(_w10_say(_w10_client, "Ney, attack the Austrians at Lorraine").get("message") or "")
        assert "Order 'Ney, attack Mack'." in text, text
        assert _W10_HINT in text, text

    def test_no_attack_quoted_no_hint(self, _w10_client):
        """The refusal that quotes no attack is byte-identical."""
        text = str(_w10_say(_w10_client, "Ney, attack the Russians at Lorraine").get("message") or "")
        assert "Scout for them first, or name the corps you mean." in text, text
        assert "what if" not in text, text
        text = str(_w10_say(_w10_client, "Ney, attack Paris").get("message") or "")
        assert "cannot reach Paris" in text and "what if" not in text, text

    def test_the_nearest_enemy_branch_names_the_preview(self, _w10_world, monkeypatch):
        """`No enemy found at X. Nearest enemy is Y ...` -- reached with a
        defender the lookup missed; driven at the stage with the nearest foe
        three provinces off."""
        from backend.commands.executor import CommandExecutor
        w = _w10_world
        with _w10_quiet():
            ex = CommandExecutor()
        ney, charles = w.get_marshal("Ney"), w.get_marshal("ArchdukeCharles")
        monkeypatch.setattr(w, "find_nearest_enemy", lambda loc: (charles, 5))
        ctx = SimpleNamespace(
            marshal=ney, world=w, enemy_marshal=None, enemy_by_name=None, target="Carniola",
            resolved_target="Carniola", game_state={"world": w}, target_region=None,
            drill_cancelled_message="", is_counter_punch=False)
        result = ex._combat._attack_war_and_bombard_target(ctx)
        assert isinstance(result, dict) and result.get("success") is False, result
        assert "Nearest enemy is ArchdukeCharles" in result["message"], result
        # S14E-X178 flips the tail of this pin: "... or move closer first." is
        # followed by the hint WITHOUT its own "first".
        assert result["suggestion"] == (
            "Try: 'Attack ArchdukeCharles' or move closer first. "
            "Ask 'what if Ney attacks ArchdukeCharles' — it names who marches "
            "with Ney, and costs nothing."), result["suggestion"]

    @staticmethod
    def _w10_shrug_state(world):
        return {"world": world, "marshals": {m.name: {} for m in world.get_player_marshals()},
                "enemies": {"Mack": {}}}

    def test_the_recognised_marshal_shrug_names_it(self, _w10_world, monkeypatch):
        import random
        from backend.ai.llm_client import LLMClient
        monkeypatch.setattr(random, "choice", lambda seq: seq[0])      # the first template
        with _w10_quiet():
            client = LLMClient()
        text = client._berthier_mock_response(
            "flibbertigibbet", self._w10_shrug_state(_w10_world), {"recognized_marshal": "Ney"})
        assert "Perhaps: 'Ney, attack Mack' or 'Ney, move to Paris'?" in text, text
        assert text.index("Perhaps: 'Ney, attack Mack'") < text.index(_W10_HINT), text
        # the templates that quote no attack carry no hint
        monkeypatch.setattr(random, "choice", lambda seq: seq[1])
        assert "what if" not in client._berthier_mock_response(
            "flibbertigibbet", self._w10_shrug_state(_w10_world), {"recognized_marshal": "Ney"})

    def test_the_retreat_shrug_names_it(self, _w10_world):
        from backend.ai.llm_client import LLMClient
        with _w10_quiet():
            client = LLMClient()
        text = client._berthier_mock_response(
            "the Austrians retreat toward Vienna", self._w10_shrug_state(_w10_world),
            {"recognized_marshal": "Ney"})
        assert "to strike at a foe who falls back, 'Ney, attack Mack'." in text, text
        assert text.endswith(_W10_HINT + '"'), text

    def test_the_recognised_place_shrug_names_it(self, _w10_world, monkeypatch):
        import random
        import backend.ai.llm_client as llm
        monkeypatch.setattr(random, "choice", lambda seq: seq[0])
        monkeypatch.setattr(llm, "_place_suggestion", lambda gs, target: None)    # the cold template
        with _w10_quiet():
            client = llm.LLMClient()
        text = client._berthier_mock_response(
            "flibbertigibbet", self._w10_shrug_state(_w10_world), {"recognized_target": "Carniola"})
        assert "Try: 'Ney, attack Carniola' or 'Ney, move to Carniola'." in text, text
        assert text.endswith(
            "Ask 'what if Ney attacks Carniola' first — it names who marches with Ney, "
            "and costs nothing.\""), text

    def test_the_place_suggestion_names_it_only_for_a_hostile_province(self, _w10_world):
        from backend.ai.llm_client import _place_suggestion
        state = {"world": _w10_world}
        hostile = _place_suggestion(state, "Carniola")       # Austrian soil, at war
        assert "'Bernadotte, attack Carniola'." in hostile, hostile
        assert ("Ask 'what if Bernadotte attacks Carniola' first — it names who marches "
                "with Bernadotte, and costs nothing.") in hostile, hostile
        friendly = _place_suggestion(state, "Swabia")        # allied soil: no attack quoted
        assert "attack" not in friendly and "what if" not in friendly, friendly

    def test_the_cautious_delegation_note_names_it(self):
        from backend.commands.delegation import describe_cautious_delegation
        match = SimpleNamespace(marshal="Ney", target_display="Mack")
        text = describe_cautious_delegation(match, "scout")
        assert 'Say "Ney, attack Mack" to press the assault instead.' in text, text
        assert text.endswith(_W10_HINT), text

    def test_the_hint_is_the_one_sentence_the_today_list_carries(self):
        from backend.commands.movement_executor import attack_preview_hint_for
        from backend.game_logic.dispatch import attack_preview_hint
        assert attack_preview_hint_for("Ney", "Mack") == attack_preview_hint(["Ney, attack Mack"]) == _W10_HINT


