# The sweep's own finds (letter W)
# ══════════════════════════════════════════════════════════════════════════

class TestS14EX183:
    """S14E-X183 -- "repair two depots in Paris" repairs ONE and never says so
    (S14E-X71's class on the repair verb, found sweeping XN3).

    Reproduced (the shipped 1805 board, the real endpoint, a damaged depot and
    watchtower at Paris): "repair two depots in Paris" -> "Repaired Supply
    Depot in Paris (150 gold)" -- one repair, 150g, not a word of the two;
    the same on "repair 2 buildings" and "repair two watchtowers".

    The fix: the repair reply's three successes (a work, the watchtower, the
    war damage) end with `_unread_count_clause(..., "repair per order")` --
    the buildings' reader, XA3's sentence; nothing else changes.
    """

    @staticmethod
    def _w10_damaged_paris(world):
        paris = world.get_region("Paris")
        paris.war_damage = 0.5
        paris.buildings.append({"type": "supply_depot", "damaged": True})
        paris.watchtower = "damaged"
        return paris

    @pytest.mark.parametrize("line,word", (
        ("repair two depots in Paris", "two"), ("repair 2 buildings in Paris", "two"),
        ("repair three supply depots in Paris", "three"), ("repair a pair of depots in Paris", "two")))
    def test_a_repaired_work_says_the_count_is_not_read(self, line, word, _w10_client, _w10_world):
        self._w10_damaged_paris(_w10_world)
        gold = int(_w10_world.nation_gold["France"])
        text = str(_w10_say(_w10_client, line).get("message") or "")
        assert text.startswith("Repaired Supply Depot in Paris (150 gold)"), (line, text)
        assert text.endswith(f"; one repair per order — the {word} is not read"), (line, text)
        assert gold - int(_w10_world.nation_gold["France"]) == 150     # ONE repair, ONE price

    def test_the_watchtower_and_the_war_damage_say_it_too(self, _w10_client, _w10_world):
        self._w10_damaged_paris(_w10_world)
        text = str(_w10_say(_w10_client, "repair two watchtowers in Paris").get("message") or "")
        assert text.startswith("Watchtower repair started in Paris (2 turns, 150 gold)"), text
        assert text.endswith("; one repair per order — the two is not read"), text
        # 2 buildings, none damaged: the war damage is the repair
        paris = _w10_world.get_region("Paris")
        paris.buildings[:] = [b for b in paris.buildings if not b.get("damaged")]
        text = str(_w10_say(_w10_client, "repair 2 buildings in Paris").get("message") or "")
        assert text.startswith("War damage repaired in Paris (150 gold)"), text
        assert text.endswith("; one repair per order — the two is not read"), text

    @pytest.mark.parametrize("line", ("repair Paris", "repair the depot in Paris",
                                      "repair a depot in Paris", "repair the watchtower in Paris",
                                      "repair buildings in Paris"))
    def test_no_count_or_one_is_unchanged(self, line, _w10_client, _w10_world):
        self._w10_damaged_paris(_w10_world)
        text = str(_w10_say(_w10_client, line).get("message") or "")
        assert "repair" in text.lower() and "not read" not in text, (line, text)

    def test_the_ai_repair_is_untouched(self, _w10_world):
        from backend.commands.executor import CommandExecutor
        w = _w10_world
        self._w10_damaged_paris(w)
        with _w10_quiet():
            ex = CommandExecutor()
        cmd = {"target": "Paris", "building_type": "supply_depot", "_acting_nation": "France",
               "raw_command": "repair two depots in Paris"}
        result = ex._economy._execute_repair(cmd, {"world": w}, raw_text="repair two depots in Paris")
        assert result.get("success") is True and "not read" not in result["message"], result


class TestS14EX184:
    """S14E-X184 -- a count in a Marshalate order: "commission two marshals"
    asks for a candidate named "Two", and "recruit two marshals" raises 3,000
    infantry and spends 741 gold (found sweeping XN3's class).

    Reproduced (the keyless parser on the 1805 board): "commission two
    marshals" -> recruit_marshal with target "Two" ("No candidate named 'Two'
    awaits a commission."); "recruit two marshals" / "recruit new marshals" ->
    action `recruit` (a levy: the plural `marshals` missed the Marshalate's
    `\bmarshal\b`).

    The fix: a number or quantity word is no candidate's name (the placeholder
    list the parser already keeps), and "recruit <count/quantity> marshals" is
    the Marshalate's verb -- which asks WHOM, spending nothing.  "recruit
    marshals" (no count word) and every troop-recruit line read as before.
    """

    @pytest.mark.parametrize("line", ("commission two marshals", "commission three new marshals",
                                      "commission both marshals", "commission several marshals"))
    def test_a_count_is_no_candidates_name(self, line, _w10_board):
        result = _w10_parse(_w10_board, line)
        command = result.get("command") or {}
        assert command.get("action") == "recruit_marshal", (line, command)
        assert not command.get("target"), (line, command)

    def test_the_answer_asks_whom_and_spends_nothing(self, _w10_client, _w10_world):
        w = _w10_world
        gold, ap, admin = int(w.nation_gold["France"]), int(w.actions_remaining), int(w.admin_actions_remaining)
        for line in ("commission two marshals", "recruit two marshals", "recruit 3 marshals",
                     "recruit some new marshals"):
            reply = _w10_say(_w10_client, line)
            text = str(reply.get("message") or "")
            assert reply.get("success") is False, (line, text)
            assert text.startswith("Whom shall we raise to the marshalate, Sire? Candidates:"), (line, text)
        assert (int(w.nation_gold["France"]), int(w.actions_remaining),
                int(w.admin_actions_remaining)) == (gold, ap, admin)

    # S14E-X176 flips ("recruit marshals", "recruit", None): the bare plural is
    # the Marshalate's too (tests/test_s14f_p2_w15.py::TestS14EX176).
    @pytest.mark.parametrize("line,action,target", (
        ("recruit marshals", "recruit_marshal", None),
        ("recruit infantry for the marshals", "recruit", None),
        ("recruit two infantry for Davout", "recruit", None),
        ("recruit marshal Grouchy", "recruit_marshal", "Grouchy"),
        ("commission Grouchy", "recruit_marshal", "Grouchy"),
        ("recruit a marshal", "recruit_marshal", None)))
    def test_every_other_reading_is_unchanged(self, line, action, target, _w10_board):
        command = _w10_parse(_w10_board, line).get("command") or {}
        assert command.get("action") == action, (line, command)
        assert (command.get("target") or None) == target, (line, command)

# ========== S14f part 2 - merged from test_s14f_p2_w11.py ==========

_W11_ROOT = Path(__file__).resolve().parent.parent
_W11_SCRIPTS = _W11_ROOT / "godot-client" / "project-sovereign" / "scripts"
_W11_SCENARIO = (_W11_ROOT / "godot-client" / "project-sovereign" / "assets" / "maps"
                 / "europe_1805.json")


def _w11_quiet():
    return contextlib.redirect_stdout(io.StringIO())


def _w11_src(name: str = "main.gd") -> str:
    return (_W11_SCRIPTS / name).read_text(encoding="utf-8")


def _w11_func(src: str, name: str) -> str:
    """A GDScript function's body: from its header to the next top-level one."""
    start = src.index(f"func {name}(")
    ends = [e for e in (src.find("\nfunc ", start + 1), src.find("\nstatic func ", start + 1))
            if e != -1]
    return src[start:min(ends) if ends else len(src)]


@pytest.fixture(scope="module")
def _w11_boot():
    from backend.models.world_state import WorldState
    with _w11_quiet():
        return WorldState.from_scenario(str(_W11_SCENARIO))


@pytest.fixture
def _w11_world(_w11_boot):
    """The shipped 1805 board, a private copy per test."""
    from backend.models.world_state import WorldState
    return WorldState.from_dict(json.loads(json.dumps(_w11_boot.to_dict(), default=str)))


@contextlib.contextmanager
def _w11_served(world):
    """Swap the three module globals together and restore them."""
    import backend.main as M
    from backend.commands.parser import CommandParser
    from fastapi.testclient import TestClient
    saved = (M.game_state["world"], M.world, M.parser)
    M.game_state["world"] = world
    M.world = world
    M.parser = CommandParser(use_real_llm=False)
    try:
        with _w11_quiet():
            yield TestClient(M.app)
    finally:
        M.game_state["world"], M.world, M.parser = saved


def _w11_base(world) -> dict:
    import backend.main as M
    with _w11_quiet():
        return M.build_base_response(world, success=True, message="x")


_W11_GATE_KEYS = ("gold_projected_net", "end_turn_army_warning", "end_turn_peril_warning")


# ======================================================================
# S14E-X146 -- the /test road at boot
# ======================================================================

class TestS14EX146:
    """Reproduced (shipped board, and by source): `GET /test` -- the payload
    `main.gd::_on_connection_test` hand-copies status, gold and manpower out
    of -- carried none of `gold_projected_net`, `end_turn_army_warning` and
    `end_turn_peril_warning` (every POST envelope does, through
    `build_base_response`), so the boot header read "432" with no "(-N next
    turn)" and the End Turn gate's two lines were empty until the first
    response of the session.

    The fix: `/test` carries the three fields from the SAME builders the
    envelope uses (`_gold_projected_net`, `_end_turn_army_warning`,
    `_end_turn_peril_warning`) and the handler sets them the way
    `_sync_response_hud` does, in the same order, ahead of the first gold
    paint. It cannot call the sync itself: the sync's map update would run
    before the topology bootstrap."""

    def test_the_connection_test_carries_the_three_fields(self, _w11_world):
        with _w11_served(_w11_world) as client:
            hello = client.get("/test").json()
        for key in _W11_GATE_KEYS:
            assert key in hello, key
        assert isinstance(hello["gold_projected_net"], int)
        for key in ("end_turn_army_warning", "end_turn_peril_warning"):
            assert hello[key] is None or isinstance(hello[key], str), key

    def test_the_values_are_the_envelopes_own(self, _w11_world):
        """Shown == the envelope's: the same figure the first response would
        have written, on the shipped board."""
        with _w11_served(_w11_world) as client:
            hello = client.get("/test").json()
        base = _w11_base(_w11_world)
        for key in _W11_GATE_KEYS:
            assert hello[key] == base[key], key

    def test_a_standing_army_gate_line_rides_the_boot_payload(self, _w11_world):
        """A spent corps beside a seen enemy army: the gate's army sentence is
        on the connection test, and it is the envelope's sentence."""
        davout = _w11_world.get_marshal("Davout")
        davout.morale = 10
        _w11_world.calculate_visibility()
        base = _w11_base(_w11_world)
        assert isinstance(base["end_turn_army_warning"], str) and base["end_turn_army_warning"], \
            "the fixture must stand a real army line"
        with _w11_served(_w11_world) as client:
            hello = client.get("/test").json()
        assert hello["end_turn_army_warning"] == base["end_turn_army_warning"]

    def test_the_payload_reads_the_envelopes_builders(self, _w11_world, monkeypatch):
        """Not a copy of the logic: the three module builders, called by name."""
        import backend.main as M
        monkeypatch.setattr(M, "_gold_projected_net", lambda world: -486)
        monkeypatch.setattr(M, "_end_turn_army_warning", lambda world: "A spent corps.")
        monkeypatch.setattr(M, "_end_turn_peril_warning", lambda world: "A corps in peril.")
        with _w11_served(_w11_world) as client:
            hello = client.get("/test").json()
        assert hello["gold_projected_net"] == -486
        assert hello["end_turn_army_warning"] == "A spent corps."
        assert hello["end_turn_peril_warning"] == "A corps in peril."

    def test_the_handler_sets_the_three_fields_in_the_syncs_order(self):
        body = _w11_func(_w11_src(), "_on_connection_test")
        net = body.index('response.get("gold_projected_net") != null')
        army = body.index('response.has("end_turn_army_warning")')
        peril = body.index('response.has("end_turn_peril_warning")')
        assert net < army < peril
        for needle in ("gold_projected_net = _net", "_has_gold_projected_net = true",
                       "end_turn_army_warning = _army", "end_turn_peril_warning = _peril",
                       "_army_warned = false", "_treasury_warned = false"):
            assert needle in body, needle

    def test_the_net_is_set_before_the_first_gold_paint(self):
        """The header is painted by `_update_gold_display()` in the gold arm:
        the net must already be set, or the first paint still reads bare."""
        body = _w11_func(_w11_src(), "_on_connection_test")
        assert body.index("_has_gold_projected_net = true") < \
            body.index("gold = int(response.gold)")
        assert body.index("end_turn_peril_warning = _peril") < \
            body.index("gold = int(response.gold)")

    def test_the_handler_names_its_row_and_why_it_does_not_call_the_sync(self):
        body = _w11_func(_w11_src(), "_on_connection_test")
        assert "S14E-X146" in body
        assert "_sync_response_hud(" not in body.replace("`_sync_response_hud`", "")
        assert "topology" in body[body.index("S14E-X146"):]

    def test_the_sync_and_the_handler_agree_on_each_fields_rule(self):
        """The two copies drift together or not at all: the sync's three
        statements for the fields appear in the handler too."""
        src = _w11_src()
        sync = _w11_func(src, "_sync_response_hud")
        conn = _w11_func(src, "_on_connection_test")
        for line in ('var _net := int(response.get("gold_projected_net"))',
                     'var _army_raw = response.get("end_turn_army_warning")',
                     'var _peril_raw = response.get("end_turn_peril_warning")'):
            assert line in sync and line in conn, line

    def test_the_boot_road_is_still_one_of_the_stash_exceptions(self):
        """tests/test_b4b_the_one_tail.py's allowance stands: the connection
        test still stashes the ending itself and nothing else routes."""
        body = _w11_func(_w11_src(), "_on_connection_test")
        assert "_stash_ending(response)" in body
        assert body.index("_remember_game_state(response.game_state)") < \
            body.index("_print_boot_help()")


# ======================================================================
# S14E-X147 -- the counter-punch row's button and the muster
# ======================================================================

def _w11_earned(world, name: str = "Davout"):
    m = world.marshals[name]
    m.counter_punch_available = True
    m.counter_punch_turns = 1
    return m


def _w11_post(world, marshal):
    """The row as the combat seam posts it (its own reader, its own call)."""
    from backend.commands.executor import CommandExecutor
    with _w11_quiet():
        CommandExecutor()._combat._process_combat_notifications(
            {"counter_punch_earned": True}, world.marshals["Mack"], marshal, world)


def _w11_rows(world) -> list:
    from backend.notifications import COUNTER_PUNCH_EARNED
    return [n for n in world.notifications.get_pending()
            if n.get("type") == COUNTER_PUNCH_EARNED]


def _w11_read_rows(world) -> list:
    """The rail as `GET /notifications` / every response ships it."""
    import backend.main as M
    with _w11_quiet():
        notes = M._pending_notifications(world)
    from backend.notifications import COUNTER_PUNCH_EARNED
    return [n for n in notes if n.get("type") == COUNTER_PUNCH_EARNED]


@contextlib.contextmanager
def _w11_count_musters(monkeypatch):
    """Count every call of the muster line's one source, wherever it comes
    from (the cached reader's `_contact_muster_note`)."""
    from backend.commands.combat_executor import CombatExecutor
    calls = SimpleNamespace(n=0)
    real = CombatExecutor._contact_muster_note

    def counting(self, *args, **kwargs):
        calls.n += 1
        return real(self, *args, **kwargs)

    monkeypatch.setattr(CombatExecutor, "_contact_muster_note", counting)
    yield calls


class TestS14EX147:
    """Reproduced (shipped board): Davout (cautious) at Rhineland with Mack one
    hop off at Swabia, a counter-punch earned. The map attack card
    (`order_quotes.attack_quote`) carried "Berthier adds: ..." (S14E-24); the
    rail row's button -- `Davout, attack Mack`, "Strike Mack -- free" -- had
    `action_detail` "Mack stands within reach at Swabia. The strike costs no
    action and expires when this turn ends." and no muster at all, so the
    same strike was thrown blind from the rail and priced from the card.

    The fix: the row carries the one-line muster in its `action_detail` (the
    button's tooltip), built ONCE at row creation by `_contact_muster_note`
    through the cached `order_quotes._MUSTER_READER`, fog-banded as the card's.
    `restate_counter_punch_notices` (every rail read) never rebuilds it: it
    carries the stored line while the board it priced is unchanged, and lets
    it go -- the plain row -- once a corps has moved, never a stale figure."""

    def _board(self, world):
        davout = _w11_earned(world)
        world.calculate_visibility()
        return davout, world.marshals["Mack"]

    def test_the_row_carries_the_muster_when_created(self, _w11_world):
        davout, mack = self._board(_w11_world)
        _w11_post(_w11_world, davout)
        rows = _w11_rows(_w11_world)
        assert len(rows) == 1
        details = rows[0]["details"]
        assert details["action_command"] == "Davout, attack Mack"
        assert "Berthier adds: " in details["action_detail"], details["action_detail"]
        assert details["action_detail"].startswith(
            "Mack stands within reach at Swabia. The strike costs no action "
            "and expires when this turn ends.")

    def test_the_figure_is_the_attack_cards_own(self, _w11_world):
        """Shown == the card's: the very sentence `attack_quote` carries for
        the same pair."""
        from backend.commands.order_quotes import attack_quote
        davout, mack = self._board(_w11_world)
        card = attack_quote(_w11_world, davout, mack)["muster"]
        assert card.startswith("Berthier adds: "), card
        _w11_post(_w11_world, davout)
        detail = _w11_rows(_w11_world)[0]["details"]["action_detail"]
        assert detail.endswith(card), (detail, card)
        assert _w11_rows(_w11_world)[0]["details"]["muster"] == card

    def test_the_line_is_fog_banded_like_the_card(self, _w11_world):
        from backend.models.intel import FULL
        davout, mack = self._board(_w11_world)
        assert _w11_world.intel["Swabia"].visibility != FULL
        _w11_post(_w11_world, davout)
        detail = _w11_rows(_w11_world)[0]["details"]["action_detail"]
        assert f"{int(mack.strength):,}" not in detail, "Mack's true strength is not printed"
        assert "Mack (" in detail

    def test_the_first_response_after_creation_carries_it(self, _w11_world):
        """The creating response reads the rail through the restate: the line
        must survive the very first read, or the fix would never reach the
        player."""
        davout, _mack = self._board(_w11_world)
        _w11_post(_w11_world, davout)
        row = _w11_read_rows(_w11_world)[0]
        assert "Berthier adds: " in row["details"]["action_detail"]

    def test_a_restate_does_not_rebuild_it(self, _w11_world, monkeypatch):
        """Hot path: the rail is read on every response. After creation, a
        hundred reads call the muster's source zero times, the row keeps its
        id, and the line is the one created."""
        davout, _mack = self._board(_w11_world)
        _w11_post(_w11_world, davout)
        first = _w11_rows(_w11_world)[0]
        line = first["details"]["action_detail"]
        with _w11_count_musters(monkeypatch) as calls:
            for _ in range(100):
                row = _w11_read_rows(_w11_world)[0]
        assert calls.n == 0, "a restate rebuilt the muster"
        assert row["id"] == first["id"]
        assert row["details"]["action_detail"] == line

    def test_the_restate_function_itself_never_calls_the_reader(self):
        """By source: the muster is not requested anywhere in the restate."""
        import inspect
        from backend.game_logic import dispatch
        body = inspect.getsource(dispatch.restate_counter_punch_notices)
        assert "with_muster" not in body
        assert "_muster_line" not in body and "_contact_muster_note" not in body

    def test_the_creation_seam_is_the_only_caller_that_asks_for_it(self):
        import inspect
        from backend.commands import combat_executor
        from backend.game_logic import dispatch
        seam = inspect.getsource(combat_executor.CombatExecutor._process_combat_notifications)
        assert "counter_punch_notice(defender, world, with_muster=True)" in seam
        src = inspect.getsource(dispatch)
        assert src.count("with_muster=True") == 0, "no dispatch caller asks for it"

    def test_the_dispatch_note_and_a_plain_call_carry_no_muster(self, _w11_world):
        """The dawn dispatch's own use of the notice (no creation) is
        unchanged: default call, no muster line, no extra keys."""
        from backend.game_logic.dispatch import counter_punch_notice
        davout, _mack = self._board(_w11_world)
        note = counter_punch_notice(davout, _w11_world)
        assert "Berthier" not in note["details"]["action_detail"]
        assert "muster" not in note["details"]

    def test_a_moved_corps_lets_the_stale_line_go(self, _w11_world, monkeypatch):
        """The line prices the board it was built on. A corps that marches
        changes who would answer the guns: the restate drops the line (the
        button and its plain tooltip stay) without rebuilding anything."""
        davout, _mack = self._board(_w11_world)
        _w11_post(_w11_world, davout)
        assert "Berthier adds: " in _w11_rows(_w11_world)[0]["details"]["action_detail"]
        mover = next(m for m in _w11_world.get_player_marshals()
                     if m.name not in ("Davout", "Mack") and int(m.strength) > 0)
        mover.location = "Normandy" if mover.location != "Normandy" else "Brittany"
        _w11_world._build_marshal_index()
        with _w11_count_musters(monkeypatch) as calls:
            row = _w11_read_rows(_w11_world)[0]
        assert calls.n == 0
        assert row["details"]["action_command"] == "Davout, attack Mack"
        assert "Berthier" not in row["details"]["action_detail"]
        assert "muster" not in row["details"]

    def test_a_foe_who_changed_his_strength_lets_it_go(self, _w11_world):
        davout, mack = self._board(_w11_world)
        _w11_post(_w11_world, davout)
        mack.strength = int(mack.strength) - 5000
        row = _w11_read_rows(_w11_world)[0]
        assert "Berthier" not in row["details"]["action_detail"]

    def test_a_fortified_man_gets_neither_button_nor_muster(self, _w11_world):
        davout, _mack = self._board(_w11_world)
        davout.fortified = True
        _w11_post(_w11_world, davout)
        row = _w11_rows(_w11_world)[0]
        assert "action_command" not in row["details"]
        assert "action_detail" not in row["details"]
        assert "muster" not in row["details"]

    def test_no_foe_in_reach_means_no_muster_and_no_button(self, _w11_world):
        davout, mack = self._board(_w11_world)
        for enemy in _w11_world.get_visible_enemies("France"):
            if enemy.name != "Mack":
                enemy.location = "Vienna"
        mack.location = "Franconia"
        _w11_world.invalidate_active_nations_cache()
        _w11_post(_w11_world, davout)
        row = _w11_rows(_w11_world)[0]
        assert "action_command" not in row["details"] and "muster" not in row["details"]

    def test_the_stored_row_round_trips_through_a_save(self, _w11_world):
        """The line rides `details` (a plain dict of strings and ints): a save
        and a load keep it."""
        davout, _mack = self._board(_w11_world)
        _w11_post(_w11_world, davout)
        blob = json.loads(json.dumps(_w11_world.to_dict(), default=str))
        from backend.models.world_state import WorldState
        again = WorldState.from_dict(blob)
        details = _w11_rows(again)[0]["details"]
        assert "Berthier adds: " in details["action_detail"]
        assert isinstance(details["muster_stamp"], int)

    def test_the_button_still_sends_the_same_order(self, _w11_world):
        """Nothing about the order changed: same command, same label, still
        free."""
        davout, _mack = self._board(_w11_world)
        _w11_post(_w11_world, davout)
        details = _w11_rows(_w11_world)[0]["details"]
        assert details["action_command"] == "Davout, attack Mack"
        assert details["action_label"] == "Strike Mack — free"
        assert "costs no action" in details["action_detail"]

    def test_the_tooltip_is_the_field_the_rail_button_reads(self):
        """The client reads `action_detail` as the button's tooltip: no
        client change is needed for the line to show."""
        bar = _w11_src("notification_bar.gd")
        assert 'action_btn.tooltip_text = str(details.get("action_detail", ""))' in bar


# ======================================================================
# S14E-X154 -- the sweep of XP2: /test lacked the formed-nation overrides
# ======================================================================

class TestS14EX154:
    """Sibling found sweeping XP2's class (the `/test` payload against the
    envelope): the NA-6 identity overrides (`nation_display_overrides`,
    `nation_flag_overrides`) were stamped on every POST envelope and every
    hand-rolled GET that renders a nation name -- `/ledger`, `/dispatch`,
    `/campaign_log`, `/map_topology` and the rest (the census in
    tests/test_nation_agendas_formables.py) -- but not on `/test`, the first
    body a plain entry reads. `api_client._adopt_formation_overrides` takes
    them off any 200 body, so a plain entry into a campaign with a formed
    nation drew its first frame under the dead name.

    Reproduced (shipped board): the `/test` body had neither key.
    Fix: `/test` stamps them through `_attach_nation_identity_overrides`."""

    def test_the_connection_test_carries_both_override_maps(self, _w11_world):
        with _w11_served(_w11_world) as client:
            hello = client.get("/test").json()
        assert hello["nation_display_overrides"] == {}
        assert hello["nation_flag_overrides"] == {}

    def test_a_formed_nation_rides_the_boot_payload(self, _w11_world, monkeypatch):
        from backend.game_logic import formations
        monkeypatch.setattr(formations, "build_nation_display_overrides",
                            lambda world: {"KingdomOfItaly": "Italy"})
        monkeypatch.setattr(formations, "build_nation_flag_overrides",
                            lambda world: {"KingdomOfItaly": "Italy"})
        with _w11_served(_w11_world) as client:
            hello = client.get("/test").json()
        base = _w11_base(_w11_world)
        assert hello["nation_display_overrides"] == {"KingdomOfItaly": "Italy"}
        assert hello["nation_flag_overrides"] == base["nation_flag_overrides"]

    def test_the_client_chokepoint_adopts_them_off_any_body(self):
        body = _w11_func(_w11_src("api_client.gd"), "_adopt_formation_overrides")
        assert 'data.has("nation_display_overrides")' in body
        assert "Utils.set_formation_overrides(names, flags)" in body

# ========== S14f part 2 - merged from test_s14f_p2_w12.py ==========

# ══════════════════════════════════════════════════════════════════════════
# S14f part 2, third wave - the Congress's price quotes sums against a chest
# ══════════════════════════════════════════════════════════════════════════
# S14E-X148 (the Congress's price - `congress.price` - quotes "a 2,000g
# sweetener at the table" and "buy off X (1,200g)" with no word of the chest:
# the S14E-X127 / S14E-X126 class - a sum quoted against a treasury that cannot
# fund it). The Congress, the bond's price line and the counsel's lever now
# read ONE chest (`bond.bid_funds` = `cabinet_rows._lever_funds`) and say it
# in ONE idiom, " (the treasury holds N)".

_W12_SWEETENER = "a 2,000g sweetener at the table (+20)"
_W12_BUY_OFF = "buy off The Hanoverian Prize (1,200g) (+29)"
_W12_CHAIN = "buy off Redeem Italy then Primacy in Germany — one order each, 1,320g the first (+34)"
_W12_SHORT = " (the treasury holds 800)"


def _w12_quiet(fn, *args, **kwargs):
    with contextlib.redirect_stdout(io.StringIO()):
        return fn(*args, **kwargs)


def _w12_sitting(peace_with: str = ""):
    """The shipped 1805 board with the Congress sitting (the staging the
    Congress's own tests use), France holding the SHIPPED 800 gold, Hanover
    held (Prussia's design to buy off)."""
    from tests.test_congress_of_paris import _boot, _peace, _sit
    w = _boot()
    if peace_with:
        _peace(w, peace_with)
    _w12_quiet(_sit, w)
    w.nation_gold["France"] = 800
    w.regions["Hanover"].controller = "France"
    w.invalidate_active_nations_cache()
    return w


@pytest.fixture
def _w12_world():
    """Prussia at peace and short of the line: a sweetener, a buy-off, a
    treaty and the relations are all priced. France holds 800."""
    return _w12_sitting()


@pytest.fixture
def _w12_austria():
    """Austria at peace: the buy-off is a CHAIN of two designs ("one order
    each, 1,320g the first")."""
    return _w12_sitting("Austria")


def _w12_lever(w, key: str, court: str = "Prussia") -> dict:
    from backend.game_logic import congress
    pr = congress.price(w, court)
    return next(lv for lv in pr["levers"] if lv["key"] == key)


def _w12_funds(monkeypatch, amount: int) -> None:
    """Set the lever's chest (the settlement validator's budget) itself."""
    from backend.game_logic import cabinet_rows
    monkeypatch.setattr(cabinet_rows, "_lever_funds", lambda world, payer: amount)


# ══════════════════════════════════════════════════════════════════════════
# S14E-X148 - the Congress's price quotes a sum the chest cannot fund
# ══════════════════════════════════════════════════════════════════════════

class TestS14EX148:
    """Reproduced (before the fix, on the shipped 1805 board with the
    Congress sitting and France holding the shipped 800 gold):
    `congress.price(w, "Prussia")` reads "needs +73: a 2,000g sweetener at the
    table (+20) + buy off The Hanoverian Prize (1,200g) (+29) + ..." - two
    sums the chest cannot pay, with no word of the chest - and Austria's
    chained buy-off ("one order each, 1,320g the first") the same. The bond's
    price line (S14E-X127) and the counsel's lever (S14E-X126) on the same board
    already say "(the treasury holds 800)"."""

    # ── the sweetener ────────────────────────────────────────────────────

    def test_the_short_sweetener_names_the_chest(self, _w12_world):
        from backend.game_logic import bond as B
        w = _w12_world
        assert int(w.nation_gold["France"]) == 800
        assert B.bid_funds(w, "France") == 800
        lever = _w12_lever(w, "sweetener")
        assert int(lever["gold"]) == 2000
        assert lever["text"] == _W12_SWEETENER + _W12_SHORT

    def test_the_short_buy_off_names_the_chest(self, _w12_world):
        w = _w12_world
        lever = _w12_lever(w, "design")
        assert int(lever["gold"]) == 1200
        assert lever["text"] == _W12_BUY_OFF + _W12_SHORT

    def test_the_chained_buy_off_names_the_chest(self, _w12_austria):
        """A chain buys ONE design per order: the figure quoted is the first
        order's, and the chest is set against that figure."""
        w = _w12_austria
        lever = _w12_lever(w, "design", "Austria")
        assert int(lever["orders"]) == 2 and int(lever["gold"]) == 1320
        assert lever["text"] == _W12_CHAIN + _W12_SHORT

    def test_the_price_text_carries_each_levers_words(self, _w12_world):
        """`price.text` joins the bundle's levers by their `text`: the chest
        rides into the sentence every surface reads (the ledger, the
        dispatch's warning, Berthier's answer)."""
        from backend.game_logic import congress
        w = _w12_world
        pr = congress.price(w, "Prussia")
        assert _W12_SWEETENER + _W12_SHORT in pr["text"], pr["text"]
        assert _W12_BUY_OFF + _W12_SHORT in pr["text"], pr["text"]

    # ── the funded text is untouched ─────────────────────────────────────

    def test_the_funded_levers_are_byte_identical(self, _w12_world):
        from backend.game_logic import congress
        w = _w12_world
        w.nation_gold["France"] = 5000
        assert _w12_lever(w, "sweetener")["text"] == _W12_SWEETENER
        assert _w12_lever(w, "design")["text"] == _W12_BUY_OFF
        pr = congress.price(w, "Prussia")
        assert "treasury" not in pr["text"], pr["text"]
        assert f"needs +73: {_W12_SWEETENER} + {_W12_BUY_OFF} + " in pr["text"]

    def test_the_funded_chain_is_byte_identical(self, _w12_austria):
        w = _w12_austria
        w.nation_gold["France"] = 5000
        assert _w12_lever(w, "design", "Austria")["text"] == _W12_CHAIN

    # ── the boundary and the chest ───────────────────────────────────────

    def test_the_boundary_is_the_sum_itself(self, _w12_world, monkeypatch):
        w = _w12_world
        _w12_funds(monkeypatch, 2000)                 # exactly the sweetener: funded
        assert _w12_lever(w, "sweetener")["text"] == _W12_SWEETENER
        assert _w12_lever(w, "design")["text"] == _W12_BUY_OFF
        _w12_funds(monkeypatch, 1999)                 # a gold short: the sweetener names it
        assert _w12_lever(w, "sweetener")["text"] == _W12_SWEETENER + " (the treasury holds 1,999)"
        assert _w12_lever(w, "design")["text"] == _W12_BUY_OFF         # 1,200 is still funded
        _w12_funds(monkeypatch, 1199)                 # a gold short of the buy-off too
        assert _w12_lever(w, "design")["text"] == _W12_BUY_OFF + " (the treasury holds 1,199)"

    def test_the_chest_is_the_levers_chest_not_the_bare_treasury(self, _w12_world, monkeypatch):
        """Shown == applied: the figure is `bond.bid_funds` (the settlement
        validator's budget - the treasury less what is owed), the very chest
        the bond's price line and the counsel's lever quote."""
        w = _w12_world
        w.nation_gold["France"] = 5000
        _w12_funds(monkeypatch, 410)
        assert _w12_lever(w, "sweetener")["text"] == _W12_SWEETENER + " (the treasury holds 410)"
        assert _w12_lever(w, "design")["text"] == _W12_BUY_OFF + " (the treasury holds 410)"

    def test_a_large_chest_is_grouped_like_the_sum(self, _w12_world, monkeypatch):
        w = _w12_world
        _w12_funds(monkeypatch, 1999)
        assert _w12_lever(w, "sweetener")["text"].endswith(" (the treasury holds 1,999)")

    def test_an_empty_chest_is_named(self, _w12_world, monkeypatch):
        w = _w12_world
        _w12_funds(monkeypatch, 0)
        assert _w12_lever(w, "sweetener")["text"].endswith(" (the treasury holds 0)")

    # ── the lever's numbers are the applied ones ─────────────────────────

    def test_the_figures_in_the_text_are_the_applied_ones(self, _w12_world):
        """The idiom changes the sentence only: the lever's `gold` and
        `value` are what they were, and the sweetener, paid, charges that
        gold and moves the court by that value."""
        from backend.game_logic import congress
        w = _w12_world
        lever = _w12_lever(w, "sweetener")
        before = int(congress.recognition_score(w, "Prussia")["score"])
        w.nation_gold["France"] = 5000
        w.diplomatic_points = 6
        result = _w12_quiet(congress.pay_sweetener, w, "Prussia", int(lever["gold"]))
        assert result["success"], result
        assert int(w.nation_gold["France"]) == 5000 - int(lever["gold"])
        assert int(congress.recognition_score(w, "Prussia")["score"]) - before == int(lever["value"])
        assert f"{int(lever['gold']):,}g sweetener" in lever["text"]

    # ── the three sites, one board ───────────────────────────────────────

    def test_the_price_the_bond_and_the_counsel_agree_on_one_chest(self, monkeypatch):
        """XT1's bond line, XM3's lever sentence and XV1's Congress levers,
        read on ONE board (the Congress sitting, Britain's bond on Austria,
        the 20 / 20 / 20 war board), print the same chest - and print the
        same new one when the chest moves."""
        from backend.game_logic import bond as B
        from backend.game_logic import congress
        from backend.game_logic import counsel as CS
        w = _w12_sitting()
        w.nation_gold["Britain"] = 5000
        minted = _w12_quiet(B.mint_bond, w, payer="Britain", member="Austria", enemy="France")
        assert minted["success"], minted
        for other in ("Britain", "Austria", "Russia"):
            key = w._make_diplo_key("France", other)
            w.war_scores[key] = 20 if key.split("|")[0] == "France" else -20

        def _three():
            sweet = _w12_lever(w, "sweetener")["text"]
            bond_line = B.price_line(w, "Austria", "France")
            austria = congress.price(w, "Austria")["text"]
            lever = CS._lever_sentence(_w12_quiet(CS.read_counsel, w, "Britain"))
            return sweet, bond_line, austria, lever

        chest = B.bid_funds(w, "France")
        assert chest == 800
        sweet, bond_line, austria, lever = _three()
        note = f"the treasury holds {chest}"
        assert note in sweet, sweet
        assert note in bond_line, bond_line
        assert bond_line.rstrip(".") in austria, austria     # the Congress quotes the bond's line
        assert note in lever, lever
        # the same idiom: a parenthesis, ahead of the lever's own close
        assert sweet.endswith(f" ({note})")
        assert f"pays it ({note})" in bond_line

        _w12_funds(monkeypatch, 410)
        sweet, bond_line, austria, lever = _three()
        for text in (sweet, bond_line, austria, lever):
            assert "the treasury holds 410" in text, text
            assert "the treasury holds 800" not in text, text

    # ── the siblings keep their words ────────────────────────────────────

    def test_the_war_arm_and_the_at_war_court_are_untouched(self, _w12_world):
        """A court at war has no sweetener or buy-off lever; the war arm's
        words (win the war / take its capital / sign a peace) are unchanged."""
        from backend.game_logic import congress
        w = _w12_world
        pr = congress.price(w, "Russia")
        assert [lv["key"] for lv in pr["levers"]] == ["war", "capital", "peace"]
        assert "treasury" not in pr["text"]


# ══════════════════════════════════════════════════════════════════════════
# S14E-X156 - the bundle asks two sums the chest can each pay but not together
# ══════════════════════════════════════════════════════════════════════════

class TestS14EX156:
    """Reproduced (a sweep find of S14E-X148, on the shipped board with France
    holding 3,000): Prussia's price reads "needs +73: a 2,000g sweetener at
    the table (+20) + buy off The Hanoverian Prize (1,200g) (+29) + ..." - each
    lever is funded (so XV1 says nothing) and the bundle asks 3,200g of a
    3,000-gold chest, with no word of it."""

    _TOGETHER = " (together 3,200g; the treasury holds 3,000)"

    def test_the_unpayable_bundle_names_the_chest(self, _w12_world):
        from backend.game_logic import congress
        w = _w12_world
        w.nation_gold["France"] = 3000
        pr = congress.price(w, "Prussia")
        assert [lv["key"] for lv in pr["bundle"]][:2] == ["sweetener", "design"]
        # each lever is funded: neither carries its own note
        assert _w12_lever(w, "sweetener")["text"] == _W12_SWEETENER
        assert _w12_lever(w, "design")["text"] == _W12_BUY_OFF
        # the note rides after the LAST gold lever, once
        assert f"{_W12_SWEETENER} + {_W12_BUY_OFF}{self._TOGETHER} + " in pr["text"], pr["text"]
        assert pr["text"].count("treasury holds") == 1

    def test_the_figures_are_the_bundles_applied_ones(self, _w12_world):
        """The `together` figure is the sum the bundle's own levers cost."""
        from backend.game_logic import congress
        w = _w12_world
        w.nation_gold["France"] = 3000
        pr = congress.price(w, "Prussia")
        gold = sum(int(lv.get("gold") or 0) for lv in pr["bundle"]
                   if lv["key"] in ("sweetener", "design"))
        assert gold == 3200
        assert f"(together {gold:,}g;" in pr["text"]

    def test_a_chest_that_pays_the_bundle_is_byte_identical(self, _w12_world, monkeypatch):
        from backend.game_logic import congress
        w = _w12_world
        for chest in (3200, 5000):
            _w12_funds(monkeypatch, chest)
            pr = congress.price(w, "Prussia")
            assert "treasury" not in pr["text"], (chest, pr["text"])
            assert f"needs +73: {_W12_SWEETENER} + {_W12_BUY_OFF} + " in pr["text"]

    def test_the_boundary_is_one_gold_short(self, _w12_world, monkeypatch):
        from backend.game_logic import congress
        w = _w12_world
        _w12_funds(monkeypatch, 3199)
        pr = congress.price(w, "Prussia")
        assert f"{_W12_BUY_OFF} (together 3,200g; the treasury holds 3,199) + " in pr["text"]

    def test_a_lever_short_alone_keeps_only_its_own_note(self, _w12_world, monkeypatch):
        """Where a single lever is already short (XV1) the chest is named
        there; the bundle does not say it a second time."""
        from backend.game_logic import congress
        w = _w12_world
        _w12_funds(monkeypatch, 1500)
        pr = congress.price(w, "Prussia")
        assert f"{_W12_SWEETENER} (the treasury holds 1,500) + {_W12_BUY_OFF} + " in pr["text"], pr["text"]
        assert "together" not in pr["text"]

    def test_a_bundle_of_one_gold_lever_has_no_together(self, _w12_world, monkeypatch):
        """Near the line a sweetener alone flips the court: one sum, no
        `together`."""
        from backend.game_logic import congress
        w = _w12_world
        key = w._make_diplo_key("Prussia", "France")
        base = congress.recognition_score(w, "Prussia")["score"]
        w.nation_relations[key] = int(w.nation_relations.get(key, 0)) + (42 - base)
        _w12_funds(monkeypatch, 700)
        pr = congress.price(w, "Prussia")
        assert [lv["key"] for lv in pr["bundle"]] == ["sweetener"]
        assert pr["text"].endswith("a 800g sweetener at the table (+8) (the treasury holds 700)"), pr["text"]
        assert "together" not in pr["text"]

# ========== S14f part 2 - merged from test_s14f_p2_w13.py ==========

# ══════════════════════════════════════════════════════════════════════════
# S14f part 2, third wave - the chest the words quote is the chest the PAY reads
# ══════════════════════════════════════════════════════════════════════════
# S14E-X148 made the Congress's price levers name the lever chest
# (`bond.bid_funds` = the treasury LESS the recurring settlement payments owed)
# in " (the treasury holds N)". The two PLAYER purchases that price against it
# still read the raw `nation_gold`: the Congress sweetener (`sweetener_refusal`
# / `sweetener_quote` / `pay_sweetener`) and the buy-off verb
# (`_execute_buy_off_design` / `instruments.buyoff_quote` /
# `instruments.buy_off_refusal` / the wizard chip). S14E-X157 reads ONE chest
# in all of them; S14E-X158 drops the bare sum from the lever's control.

_W13_ROOT = Path(__file__).resolve().parents[1]
_W13_SCENARIO = (_W13_ROOT / "godot-client" / "project-sovereign" / "assets" / "maps"
                 / "europe_1805.json")
_W13_BACKEND = _W13_ROOT / "backend"

_W13_FREE = " free of its obligations"


def _w13_quiet(fn, *args, **kwargs):
    with contextlib.redirect_stdout(io.StringIO()):
        return fn(*args, **kwargs)


def _w13_owe(w, per_turn: int = 100, turns: int = 3, payer: str = "France",
             to: str = "Austria") -> int:
    """A ratified recurring settlement payment the payer still owes: the lever
    chest (`bond.bid_funds`) is the treasury less `per_turn * turns`."""
    w.recurring_settlement_payments.append({
        "payment_id": f"recurring_gold:{payer}:{to}:0:{len(w.recurring_settlement_payments)}",
        "from": payer, "to": to,
        "amount_per_turn": int(per_turn), "turns_remaining": int(turns),
        "total_turns": int(turns), "war_id": "", "war_label": "the settlement",
        "ratified_turn": 0,
    })
    return int(per_turn) * int(turns)


def _w13_sitting(raw: int = 1000, owed: int = 0):
    """The shipped 1805 board with the Congress sitting (the staging the
    Congress's own tests use), France holding `raw` gold, `owed` of it
    promised to a recurring settlement payment (100 a turn), Hanover held
    (Prussia's design to buy off)."""
    from tests.test_congress_of_paris import _boot, _sit
    w = _boot()
    _w13_quiet(_sit, w)
    w.nation_gold["France"] = raw
    w.regions["Hanover"].controller = "France"
    w.invalidate_active_nations_cache()
    if owed:
        assert owed % 100 == 0
        _w13_owe(w, 100, owed // 100)
    return w


@pytest.fixture(scope="module")
def _w13_boot():
    from backend.models.world_state import WorldState
    with contextlib.redirect_stdout(io.StringIO()):
        return WorldState.from_scenario(str(_W13_SCENARIO))


def _w13_board(boot, raw: int, owed: int = 0):
    """The shipped board (no Congress) for the buy-off verb: France holds
    `raw` gold and 5 DP, `owed` of the gold promised away."""
    from backend.models.world_state import WorldState
    w = WorldState.from_dict(json.loads(json.dumps(boot.to_dict(), default=str)))
    w.nation_gold["France"] = raw
    w.diplomatic_points = 5
    if owed:
        assert owed % 100 == 0
        _w13_owe(w, 100, owed // 100)
    return w


@contextlib.contextmanager
def _w13_client(w):
    """The player's road: /command on a swapped world (three globals, restored)."""
    import backend.main as M
    from backend.commands.parser import CommandParser
    from fastapi.testclient import TestClient
    saved = (M.game_state["world"], M.world, M.parser)
    M.game_state["world"] = w
    M.world = w
    M.parser = CommandParser(use_real_llm=False)
    try:
        yield TestClient(M.app)
    finally:
        M.game_state["world"], M.world, M.parser = saved


def _w13_say(client, text: str) -> dict:
    with contextlib.redirect_stdout(io.StringIO()):
        return client.post("/command", json={"command": text}).json()


def _w13_after(message: str) -> int:
    m = re.search(r"would hold ([\d,]+) after", message)
    assert m, message
    return int(m.group(1).replace(",", ""))


def _w13_lever(w, key: str, court: str = "Prussia") -> dict:
    from backend.game_logic import congress
    return next(lv for lv in congress.price(w, court)["levers"] if lv["key"] == key)


def _w13_src(*parts: str) -> str:
    return _W13_BACKEND.joinpath(*parts).read_text(encoding="utf-8")


# ══════════════════════════════════════════════════════════════════════════
# S14E-X157 - the chest the words quote is not the chest the pay reads
# ══════════════════════════════════════════════════════════════════════════

class TestS14EX157:
    """Reproduced (before the fix, on the shipped 1805 board with the Congress
    sitting, France holding 1,000 gold and 300 of it owed to a recurring
    settlement payment): the lever chest (`bond.bid_funds`) is 700 and
    `congress.price` says "a 2,000g sweetener at the table (+20) (the treasury
    holds 700)" - yet `sweetener_refusal(w, "Prussia", 1000)` is None,
    `sweetener_quote` reads "The treasury holds 1,000 gold and would hold 0
    after" and `pay_sweetener` lays the 1,000 (the recurring bill then finds an
    empty chest). The buy-off verb is the same: with 1,500 gold and 300 owed
    (a 1,200 chest), "buy off Sweden" (1,368) quotes "The treasury holds 1,500
    gold and would hold 132 after" and charges it, though the chest cannot pay
    it; `buy_off_refusal` and the wizard chip read the raw treasury too."""

    _REFUSAL = ("The treasury holds 700 gold free of its obligations — "
                "the sweetener is 1,000, 300 short.")

    # ── the Congress sweetener: the refusal ──────────────────────────────

    def test_the_lever_text_and_the_refusal_name_the_same_chest(self):
        from backend.game_logic import bond as B
        from backend.game_logic import congress
        w = _w13_sitting(raw=1000, owed=300)
        assert int(w.nation_gold["France"]) == 1000
        assert B.bid_funds(w, "France") == 700
        lever = _w13_lever(w, "sweetener")
        assert lever["text"].endswith("(the treasury holds 700)"), lever["text"]
        assert congress.sweetener_refusal(w, "Prussia", int(lever["gold"])) == (
            "The treasury holds 700 gold free of its obligations — "
            f"the sweetener is {int(lever['gold']):,}, {int(lever['gold']) - 700:,} short.")

    def test_a_sum_the_chest_cannot_fund_is_refused_with_the_figure(self):
        from backend.game_logic import congress
        w = _w13_sitting(raw=1000, owed=300)
        assert congress.sweetener_refusal(w, "Prussia", 1000) == self._REFUSAL

    def test_pay_sweetener_cannot_pay_what_the_gate_refuses(self):
        from backend.game_logic import congress
        w = _w13_sitting(raw=1000, owed=300)
        before = (dict(w.nation_gold), json.dumps(w.congress, sort_keys=True, default=str))
        result = _w13_quiet(congress.pay_sweetener, w, "Prussia", 1000)
        assert result["success"] is False
        assert result["message"] == self._REFUSAL
        assert (dict(w.nation_gold), json.dumps(w.congress, sort_keys=True, default=str)) == before

    def test_the_boundary_is_the_chest_itself(self):
        from backend.game_logic import congress
        w = _w13_sitting(raw=1000, owed=300)
        assert congress.sweetener_refusal(w, "Prussia", 700) is None
        assert congress.sweetener_refusal(w, "Prussia", 701) == (
            "The treasury holds 700 gold free of its obligations — "
            "the sweetener is 701, 1 short.")

    def test_a_raw_purse_below_the_sum_still_names_the_chest(self):
        """800 raw, 300 owed (500 free), 1,000 asked: the chest is the figure
        the player is shown, not the 800 in the coffers."""
        from backend.game_logic import congress
        w = _w13_sitting(raw=800, owed=300)
        assert congress.sweetener_refusal(w, "Prussia", 1000) == (
            "The treasury holds 500 gold free of its obligations — "
            "the sweetener is 1,000, 500 short.")

    # ── the Congress sweetener: the quote ────────────────────────────────

    def test_the_quote_reads_the_lever_chest_and_the_pay_leaves_it(self):
        """Shown == applied: the quote's "would hold N after" is the chest
        (`bond.bid_funds`) once the sweetener has been laid."""
        from backend.game_logic import bond as B
        from backend.game_logic import congress
        w = _w13_sitting(raw=5000, owed=300)
        text = congress.sweetener_quote(w, "Prussia", 1000)
        assert ("The treasury holds 4,700 gold free of its obligations and "
                "would hold 3,700 after;") in text, text
        promised = _w13_after(text)
        result = _w13_quiet(congress.pay_sweetener, w, "Prussia", 1000)
        assert result["success"] is True, result
        assert B.bid_funds(w, "France") == promised == 3700
        assert int(w.nation_gold["France"]) == 4000

    def test_nothing_owed_is_byte_identical(self):
        from backend.game_logic import congress
        w = _w13_sitting(raw=1000)
        assert congress.sweetener_refusal(w, "Prussia", 1000) is None
        assert congress.sweetener_refusal(w, "Prussia", 1500) == (
            "The treasury holds 1,000g — the sweetener asks 1,500g.")
        text = congress.sweetener_quote(w, "Prussia", 1000)
        assert ("The treasury holds 1,000 gold and would hold 0 after; "
                "the gold is kept whatever the court answers. Lay it? (yes / no)") in text
        assert "obligations" not in text

    def test_a_fully_owed_purse_is_an_empty_chest(self):
        from backend.game_logic import congress
        w = _w13_sitting(raw=1000, owed=1000)
        assert congress.sweetener_refusal(w, "Prussia", 500) == (
            "The treasury holds 0 gold free of its obligations — "
            "the sweetener is 500, 500 short.")

    # ── the Cabinet row and the player's road ────────────────────────────

    def test_the_cabinet_row_offers_only_the_sums_the_chest_pays(self):
        from backend.game_logic.cabinet_rows import recognition_actions
        w = _w13_sitting(raw=1000, owed=300)
        row = recognition_actions(w, "France", "Prussia")[0]
        assert [c["payload"]["amount"] for c in row["choices"]] == [500]
        w = _w13_sitting(raw=1000, owed=700)
        row = recognition_actions(w, "France", "Prussia")[0]
        assert row["choices"] == [] and row["available"] is False
        assert row["disabled_reason"] == (
            "The treasury holds 300 gold free of its obligations — "
            "the sweetener is 500, 200 short.")

    def test_the_command_refuses_a_sum_the_chest_cannot_pay_and_spends_nothing(self):
        w = _w13_sitting(raw=1000, owed=300)
        w.diplomatic_points = 5
        before = (dict(w.nation_gold), int(w.diplomatic_points))
        with _w13_client(w) as client:
            reply = _w13_say(client, "offer Prussia 1000 gold for recognition")
        assert reply["success"] is False
        assert self._REFUSAL in reply["message"], reply["message"]
        assert (dict(w.nation_gold), int(w.diplomatic_points)) == before

    def test_the_command_quotes_then_pays_the_quoted_chest(self):
        from backend.game_logic import bond as B
        w = _w13_sitting(raw=5000, owed=300)
        w.diplomatic_points = 5
        with _w13_client(w) as client:
            quote = _w13_say(client, "offer Prussia 1000 gold for recognition")
            assert quote.get("state") == "awaiting_clarification", quote.get("message")
            promised = _w13_after(quote["message"])
            assert "free of its obligations" in quote["message"]
            done = _w13_say(client, quote["options"][0]["command"])
        assert done["success"] is True, done["message"]
        assert B.bid_funds(w, "France") == promised == 3700

    # ── the buy-off verb ─────────────────────────────────────────────────

    def test_the_buy_off_quote_reads_the_lever_chest(self, _w13_boot):
        from backend.game_logic import bond as B
        from backend.game_logic.instruments import compute_buyoff_price
        w = _w13_board(_w13_boot, raw=2500, owed=300)
        price = compute_buyoff_price(w, "Sweden")
        assert price == 1368
        assert B.bid_funds(w, "France") == 2200
        with _w13_client(w) as client:
            quote = _w13_say(client, "buy off Sweden")
            text = quote["message"]
            assert quote.get("state") == "awaiting_clarification", text
            assert (f"The treasury holds 2,200 gold free of its obligations and "
                    f"would hold {2200 - price:,} after.") in text, text
            promised = _w13_after(text)
            done = _w13_say(client, quote["options"][0]["command"])
        assert done["success"] is True, done["message"]
        assert B.bid_funds(w, "France") == promised == 2200 - price

    def test_the_buy_off_a_chest_cannot_pay_is_refused_before_the_quote(self, _w13_boot):
        w = _w13_board(_w13_boot, raw=1500, owed=300)       # chest 1,200 < 1,368
        before = (dict(w.nation_gold), int(w.diplomatic_points))
        with _w13_client(w) as client:
            reply = _w13_say(client, "buy off Sweden")
        assert reply["success"] is False and not reply.get("options"), reply["message"]
        assert ("Their price is 1368 gold; the treasury holds 1200 gold free of "
                "its obligations.") in reply["message"], reply["message"]
        assert (dict(w.nation_gold), int(w.diplomatic_points)) == before

    def test_buy_off_nothing_owed_is_byte_identical(self, _w13_boot):
        w = _w13_board(_w13_boot, raw=1300)
        with _w13_client(w) as client:
            reply = _w13_say(client, "buy off Sweden")
        assert reply["success"] is False
        assert "Their price is 1368 gold; the treasury holds 1300. Talleyrand:" in reply["message"]
        assert "obligations" not in reply["message"]
        w = _w13_board(_w13_boot, raw=2500)
        with _w13_client(w) as client:
            text = _w13_say(client, "buy off Sweden")["message"]
        assert "The treasury holds 2,500 gold and would hold 1,132 after." in text
        assert "obligations" not in text

    def test_the_league_refusal_and_the_wizard_chip_read_the_same_chest(self, _w13_boot):
        from backend.game_logic.diplomacy import _instrument_actions
        from backend.game_logic.instruments import buy_off_refusal
        w = _w13_board(_w13_boot, raw=1500, owed=300)
        assert buy_off_refusal(w, "France", "Sweden") == (
            "the treasury holds 1,200 gold free of its obligations")
        chip = next(a for a in _instrument_actions(w, "France", "Sweden")
                    if a["action"] == "buy_off_design")
        assert chip["available"] is False
        assert chip["disabled_reason"] == (
            "Their price is 1368g — the treasury holds 1200g free of its obligations.")
        # the funded chest: the chip is open and the league row is silent
        w = _w13_board(_w13_boot, raw=2500, owed=300)
        assert buy_off_refusal(w, "France", "Sweden") == ""
        chip = next(a for a in _instrument_actions(w, "France", "Sweden")
                    if a["action"] == "buy_off_design")
        assert chip["available"] is True

    def test_the_league_refusal_and_the_chip_nothing_owed_are_byte_identical(self, _w13_boot):
        from backend.game_logic.diplomacy import _instrument_actions
        from backend.game_logic.instruments import buy_off_refusal
        w = _w13_board(_w13_boot, raw=1300)
        assert buy_off_refusal(w, "France", "Sweden") == "the treasury holds 1,300 gold"
        chip = next(a for a in _instrument_actions(w, "France", "Sweden")
                    if a["action"] == "buy_off_design")
        assert chip["disabled_reason"] == "Their price is 1368g — the treasury holds 1300g."

    # ── the AI's instruments are untouched (Golden Rule 5) ───────────────

    def test_only_the_players_verbs_read_the_lever_chest(self):
        """The AI's sponsorships and its allegiance bids do not read the lever
        chest. S14E-D19 / S14E-X190 (S14f p3): FLIPPED for the AI's buy-off -
        `war_council._run_ai_instrument_producers` now buys off on
        `_ai_buyoff_funds(world, target)` (`bond.bid_funds`: the holder's
        treasury less the recurring payments it owes), the one named seam; the
        raw `int(gold.get(target, 0)) >= price` read is gone."""
        for rel in (("game_logic", "ai_diplomacy.py"), ("ai", "enemy_ai.py")):
            src = _w13_src(*rel)
            assert "bid_funds" not in src and "spendable_chest" not in src, rel
        src = _w13_src("game_logic", "war_council.py")
        assert "int(gold.get(target, 0)) >= price" not in src
        assert "_ai_buyoff_funds(world, target) >= price" in src


