# S14E-X158 - the lever's control still quotes the bare sum
# ══════════════════════════════════════════════════════════════════════════

class TestS14EX158:
    """Reproduced (before the fix, on the shipped board with the Congress
    sitting): the sweetener lever's `control` read "F1 → Prussia → Offer Gold
    for Recognition (2,000g)" - the bare sum, under a price text that now
    names the chest ("a 2,000g sweetener at the table (+20) (the treasury
    holds 700)"). The ledger prints the control as "In the Cabinet: ..." beside
    the price; the price text carries the figure."""

    def test_the_control_names_the_row_not_the_sum(self):
        w = _w13_sitting(raw=1000, owed=300)
        lever = _w13_lever(w, "sweetener")
        assert int(lever["gold"]) == 2000
        # S14E-X158: the figure lives in the price text beside it
        assert lever["control"] == "F1 → Prussia → Offer Gold for Recognition"
        assert "2,000" not in lever["control"] and "g)" not in lever["control"]
        assert "a 2,000g sweetener at the table (+20)" in lever["text"]

    def test_the_control_is_the_same_funded_or_short(self):
        for raw in (800, 5000):
            w = _w13_sitting(raw=raw)
            assert _w13_lever(w, "sweetener")["control"] == (
                "F1 → Prussia → Offer Gold for Recognition")

    def test_the_buy_off_control_is_untouched(self):
        w = _w13_sitting(raw=1000)
        assert _w13_lever(w, "design")["control"] == "F1 → Prussia → Buy Off Their Design"


# ══════════════════════════════════════════════════════════════════════════
# S14E-X159 - the lever chest scanned every province for an income it multiplied by zero
# ══════════════════════════════════════════════════════════════════════════

class TestS14EX159:
    """Reproduced (a sweep find of S14E-X157, which reads the lever chest in
    the buy-off refusal that EVERY league row calls): `bond.bid_funds` ->
    `cabinet_rows._lever_funds` -> `compute_gold_payer_budgets(world, [],
    [payer])` called `_estimate_payer_net_income_per_turn` - a scan of every
    province (Golden Rule 8; `settlement_baseline._payer_net_income_estimate`
    says so) - for an income it then multiplied by the payer's longest
    recurring stream, which is 0 when no term is staged. One scan per chest
    read, so one per league row per build."""

    def test_a_chest_read_with_no_stream_scans_no_province(self, monkeypatch):
        from backend.game_logic import bond as B
        from backend.game_logic import settlement_validation as SV
        w = _w13_sitting(raw=1000, owed=300)
        calls = []
        real = SV._estimate_payer_net_income_per_turn
        monkeypatch.setattr(SV, "_estimate_payer_net_income_per_turn",
                            lambda world, payer: calls.append(payer) or real(world, payer))
        assert B.bid_funds(w, "France") == 700
        assert calls == []

    def test_a_staged_stream_still_reads_the_income(self, monkeypatch):
        """The estimate is still read where it is multiplied: a 4-turn
        `gold_per_turn` line counts four turns of the income as capacity."""
        from backend.game_logic import settlement_validation as SV
        w = _w13_sitting(raw=1000, owed=300)
        income = SV._estimate_payer_net_income_per_turn(w, "France")
        assert income > 0
        calls = []
        real = SV._estimate_payer_net_income_per_turn
        monkeypatch.setattr(SV, "_estimate_payer_net_income_per_turn",
                            lambda world, payer: calls.append(payer) or real(world, payer))
        terms = [{"type": "gold_per_turn", "from": "France", "to": "Austria",
                  "amount": 50, "turns": 4}]
        budgets = SV.compute_gold_payer_budgets(w, terms, ["France"])
        assert calls == ["France"]
        assert budgets["France"] == 1000 + income * 4 - 300

    def test_the_budgets_are_unchanged_for_every_payer_shape(self):
        """Lump-only, stream and extra-payer shapes: the same capacity the
        formula gave (gold + income * longest stream - owed), floored at 0."""
        from backend.game_logic import settlement_validation as SV
        w = _w13_sitting(raw=1000, owed=300)
        income = SV._estimate_payer_net_income_per_turn(w, "France")
        lump = [{"type": "gold_lump", "from": "France", "to": "Austria", "amount": 400}]
        assert SV.compute_gold_payer_budgets(w, lump)["France"] == 700
        assert SV.compute_gold_payer_budgets(w, [], ["France"])["France"] == 700
        w.nation_gold["France"] = 100
        assert SV.compute_gold_payer_budgets(w, [], ["France"])["France"] == 0
        w.nation_gold["France"] = 1000
        two = [{"type": "gold_per_turn", "from": "France", "to": "Austria", "amount": 10, "turns": 2},
               {"type": "gold_per_turn", "from": "France", "to": "Russia", "amount": 10, "turns": 5}]
        assert SV.compute_gold_payer_budgets(w, two)["France"] == 1000 + income * 5 - 300

