# ══════════════════════════════════════════════════════════════════════════
# S14f part 2, third wave - Golden Rule 2 on two more payloads: every number
# sent to Godot is an int, because Godot crashes on a float.
# ══════════════════════════════════════════════════════════════════════════
# The third-wave sweep had made whole percents of the confirm snapshot's
# `harshness` / `bloc_share`, the ledger's `hegemon_share`, `parse_confidence`
# and the muster's shares. Two payloads of the same family were still carrying
# floats on the wire:
#   - S14E-X161: the objection ("Ney, fortify", a strategic "Davout, pursue
#     Mack", the reprompt, the GET): `severity` (0.55 / 0.72, top-level AND under
#     `objection`), `trust_gain_modifier` (the anti-pushover damper, 1.0 / 0.5),
#     and the parse echoes' `confidence` (0.9 / 0.95) under `original_order` /
#     `original_command` / `parsed_command`.
#   - S14E-X162: the settlement table's `settlement_confirm` dialogue and the
#     response's `settlement_preview` carried twenty floats under
#     `acceptance.component_debug.*` and `acceptance.raw_total_harshness`.
# The MECHANIC is untouched in both: the executor's `objection` dict is
# `world.pending_objection` (the answer handlers read it back) and the staged
# dialogue's preview is what the tests and `tools/_table_board_probe.py` read.
# Only the WIRE COPY changes (`_wire_objection`, `_wire_dialogue`).

_W14_ROOT = Path(__file__).resolve().parents[1]
_W14_SCENARIO = (_W14_ROOT / "godot-client" / "project-sovereign" / "assets" / "maps"
                 / "europe_1805.json")
_W14_SCRIPTS = _W14_ROOT / "godot-client" / "project-sovereign" / "scripts"


def _w14_quiet(fn, *args, **kwargs):
    with contextlib.redirect_stdout(io.StringIO()):
        return fn(*args, **kwargs)


def _w14_floats(obj, path: str = ""):
    """Every float in a JSON-shaped value, with its path."""
    if isinstance(obj, float):
        yield path, obj
    elif isinstance(obj, dict):
        for key, value in obj.items():
            yield from _w14_floats(value, f"{path}/{key}")
    elif isinstance(obj, (list, tuple)):
        for index, value in enumerate(obj):
            yield from _w14_floats(value, f"{path}[{index}]")


@pytest.fixture(scope="module")
def _w14_boot():
    from backend.models.world_state import WorldState
    with contextlib.redirect_stdout(io.StringIO()):
        return WorldState.from_scenario(str(_W14_SCENARIO))


def _w14_world(boot):
    from backend.models.world_state import WorldState
    w = WorldState.from_dict(json.loads(json.dumps(boot.to_dict(), default=str)))
    w.diplomatic_points = 30
    return w


@contextlib.contextmanager
def _w14_client(w):
    """The in-process HTTP idiom on a swapped world (`M.world`,
    `M.game_state["world"]` and the mock parser together, restored)."""
    import backend.main as M
    from backend.commands.parser import CommandParser
    from fastapi.testclient import TestClient
    saved = (M.game_state["world"], M.world, M.parser)
    M.game_state["world"] = w
    M.world = w
    M.parser = CommandParser(use_real_llm=False)
    try:
        yield TestClient(M.app)
    finally:
        M.game_state["world"], M.world, M.parser = saved


@pytest.fixture
def _w14_board(monkeypatch, _w14_boot):
    for key in ("SOVEREIGN_SCENARIO", "SOVEREIGN_MAP", "SOVEREIGN_SMOKE_START"):
        monkeypatch.delenv(key, raising=False)
    monkeypatch.setenv("LLM_MODE", "mock")
    w = _w14_world(_w14_boot)
    with _w14_client(w) as client:
        yield client, w


def _w14_post(client, path: str, body: dict) -> dict:
    with contextlib.redirect_stdout(io.StringIO()):
        return client.post(path, json=body).json()


def _w14_get(client, path: str, **params) -> dict:
    with contextlib.redirect_stdout(io.StringIO()):
        return client.get(path, params=params or None).json()


def _w14_say(client, text: str) -> dict:
    return _w14_post(client, "/command", {"command": text})


def _w14_steady_roll():
    """The one roll in the objection's trigger (`objection_v2`'s boundary
    jitter) held at the middle, so the objection neither promotes nor demotes."""
    from unittest.mock import patch
    return patch("backend.commands.objection_v2.random.random", return_value=0.5)


def _w14_tactical(client, w) -> dict:
    """`Ney, fortify` on the shipped board: an aggressive marshal objects."""
    with _w14_steady_roll():
        out = _w14_say(client, "Ney, fortify")
    assert out.get("state") == "awaiting_player_choice", out.get("message")
    assert w.pending_objection, "the objection stands in the world"
    return out


def _w14_strategic(client, w) -> dict:
    """`Davout, pursue Mack` against a Mack the muster cannot carry (the
    ACH-F3 idiom): a strategic objection."""
    w.get_marshal("Mack").strength = 400000
    with _w14_steady_roll():
        out = _w14_say(client, "Davout, pursue Mack")
    assert out.get("pending_objection") is True, out.get("message")
    assert w.pending_strategic_objection
    return out


def _w14_pushover(w) -> None:
    w.authority_tracker.recent_responses = [
        {"choice": "trust", "turn": i} for i in range(5)]


# ══════════════════════════════════════════════════════════════════════════
# S14E-X161 - the objection payload
# ══════════════════════════════════════════════════════════════════════════

class TestS14EX161:
    """Reproduced on the shipped 1805 board at the real `POST /command`:
    `Ney, fortify` came back with `/objection/trust_gain_modifier` 1.0,
    `/objection/severity` 0.72, `/objection/original_order/confidence` 0.9 and
    the top-level `/severity` 0.72; `Davout, pursue Mack` with the same plus
    `/objection/original_command/confidence` 0.95 and
    `/objection/parsed_command/command/confidence` 0.95; `GET /pending_objection`
    with `/original_order/confidence` 0.9. The only reader in the client is the
    damper (`objection_dialog.gd` prints "trust rewards x0.50"); `severity`,
    `original_order`, `original_command` and `parsed_command` have no `.gd`
    reader at all."""

    # ── the wire is float-free ───────────────────────────────────────────

    def test_the_tactical_objection_is_float_free_on_the_wire(self, _w14_board):
        client, w = _w14_board
        out = _w14_tactical(client, w)
        assert list(_w14_floats(out)) == []

    def test_the_strategic_objection_is_float_free_on_the_wire(self, _w14_board):
        client, w = _w14_board
        out = _w14_strategic(client, w)
        assert list(_w14_floats(out)) == []

    def test_the_objection_the_scan_reads_is_on_the_board(self, _w14_board):
        """Guard the guard: the response carries the objection, the four
        figures' homes (the damper, the tone, the parse echo) and the
        executor's own float severity is IN the world - so a green scan is not
        a response that lost its objection."""
        client, w = _w14_board
        out = _w14_tactical(client, w)
        objection = out["objection"]
        assert objection["marshal"] == "Ney" and objection["concern_level"] in ("MODERATE", "STRONG", "EXTREME")
        assert "trust_gain_modifier" in objection and "original_order" in objection
        assert objection["original_order"]["action"] == "fortify"
        assert isinstance(w.pending_objection["severity"], float)

    def test_the_replies_to_every_answer_are_float_free(self, _w14_boot, monkeypatch):
        for choice in ("trust", "insist", "compromise"):
            monkeypatch.delenv("SOVEREIGN_SCENARIO", raising=False)
            w = _w14_world(_w14_boot)
            with _w14_client(w) as client:
                _w14_tactical(client, w)
                reply = _w14_post(client, "/respond_to_objection", {"choice": choice})
                assert reply.get("success") is True, (choice, reply.get("message"))
                assert list(_w14_floats(reply)) == [], choice

    def test_the_strategic_replies_are_float_free(self, _w14_boot, monkeypatch):
        for choice in ("trust", "insist", "compromise"):
            monkeypatch.delenv("SOVEREIGN_SCENARIO", raising=False)
            w = _w14_world(_w14_boot)
            with _w14_client(w) as client:
                _w14_strategic(client, w)
                reply = _w14_post(client, "/respond_to_objection", {"choice": choice})
                assert list(_w14_floats(reply)) == [], choice

    def test_the_reprompt_while_an_objection_waits_is_float_free(self, _w14_board):
        """The `objection=world.pending_objection` roads of `execute_command`
        hand the STORED dict to `build_base_response`: the wire copy is made
        there, never in the world."""
        client, w = _w14_board
        _w14_tactical(client, w)
        again = _w14_say(client, "reconsider")      # a dialogue word typed while it waits
        assert again.get("objection"), again.get("message")
        assert list(_w14_floats(again)) == []
        assert isinstance(w.pending_objection["severity"], float), "the stored dict is untouched"

    def test_the_get_is_float_free_and_keeps_its_int_severity(self, _w14_board):
        client, w = _w14_board
        _w14_tactical(client, w)
        got = _w14_get(client, "/pending_objection")
        assert got["has_pending"] is True
        assert list(_w14_floats(got)) == []
        assert isinstance(got["severity"], int) and 0 < got["severity"] <= 100
        assert got["original_order"]["action"] == "fortify"
        assert "confidence" not in got["original_order"]

    # ── what the wire carries instead ────────────────────────────────────

    def test_the_legacy_severity_is_off_the_wire_at_both_places(self, _w14_board):
        client, w = _w14_board
        out = _w14_tactical(client, w)
        assert "severity" not in out and "severity" not in out["objection"]
        # the words the client reads are all still there
        assert out["concern_level"] and out["tone"] and out["message"]

    def test_the_strategic_objection_drops_it_too(self, _w14_board):
        client, w = _w14_board
        out = _w14_strategic(client, w)
        assert "severity" not in out and "severity" not in out["objection"]
        assert out["objection"]["trust_gain_modifier"] == 100
        assert out["objection"]["options"], "the answers the client draws stand"

    def test_the_damper_is_a_whole_percent_on_the_wire(self, _w14_board):
        client, w = _w14_board
        out = _w14_tactical(client, w)
        modifier = out["objection"]["trust_gain_modifier"]
        assert isinstance(modifier, int) and not isinstance(modifier, bool)
        assert modifier == 100, "nothing is damped on a fresh board"

    def test_a_pushover_is_damped_to_fifty_on_the_wire_and_half_in_the_world(self, _w14_board):
        """shown == applied: the wire percent over 100 IS the multiplier the
        trust figure on the button was quoted under."""
        client, w = _w14_board
        _w14_pushover(w)
        out = _w14_tactical(client, w)
        wire = out["objection"]["trust_gain_modifier"]
        assert wire == 50 and isinstance(wire, int)
        stored = w.pending_objection
        assert stored["trust_gain_modifier"] == 0.5, "the executor's float is the mechanic's own"
        assert wire / 100 == stored["trust_gain_modifier"]
        from backend.commands.objection_v2 import ConcernLevel, TrustTier, calculate_trust_gain
        raw = calculate_trust_gain(ConcernLevel[stored["concern_level"]], TrustTier[stored["trust_tier"]])
        assert out["objection"]["trust_gain"] == int(raw * stored["trust_gain_modifier"])

    def test_the_parse_echoes_keep_their_words_and_lose_only_the_floats(self, _w14_board):
        client, w = _w14_board
        out = _w14_strategic(client, w)
        objection = out["objection"]
        assert objection["original_command"]["marshal"] == "Davout"
        assert objection["parsed_command"]["command"]["marshal"] == "Davout"
        assert "confidence" not in objection["original_command"]
        assert "confidence" not in objection["parsed_command"]["command"]
        stored = w.pending_strategic_objection
        assert isinstance(stored["original_command"]["confidence"], float), "the world keeps it"

    # ── the mechanic is untouched ────────────────────────────────────────

    def test_the_executors_result_dict_is_unchanged(self, _w14_board):
        """Pinned at the executor, not the wire: the result the executor hands
        `main.py` still holds the floats, and the wire response is a COPY - the
        stored `pending_objection` is the same dict before and after."""
        import backend.commands.executor as EX
        client, w = _w14_board
        seen = {}
        original = EX.CommandExecutor.execute

        def spy(self, command, game_state, *a, **k):
            result = original(self, command, game_state, *a, **k)
            if isinstance(result, dict) and result.get("objection"):
                seen["result"] = result
            return result

        with pytest.MonkeyPatch.context() as mp:
            mp.setattr(EX.CommandExecutor, "execute", spy)
            out = _w14_tactical(client, w)
        result = seen["result"]
        assert isinstance(result["objection"]["severity"], float)
        assert isinstance(result["objection"]["trust_gain_modifier"], float)
        assert isinstance(result["objection"]["original_order"]["confidence"], float)
        assert isinstance(result["severity"], float)
        assert result["objection"] is w.pending_objection, "the result IS the stored dict"
        assert out["objection"] is not w.pending_objection, "the wire carries a copy"
        assert isinstance(w.pending_objection["severity"], float)

    def test_the_answer_handler_still_reads_the_stored_dict(self, _w14_board):
        client, w = _w14_board
        _w14_pushover(w)
        _w14_tactical(client, w)
        stored_gain = w.pending_objection["trust_gain"]
        wire_gain = _w14_get(client, "/pending_objection")["choices"]
        assert wire_gain, "the objection stands for the answer"
        reply = _w14_post(client, "/respond_to_objection", {"choice": "trust"})
        assert reply.get("success") is True
        assert reply["trust_change"] == stored_gain, "the damped quote is what was paid"

    # ── the helper, alone ────────────────────────────────────────────────

    def test_the_helper_copies_and_never_mutates(self):
        import copy
        import backend.main as M
        objection = {"severity": 0.72, "trust_gain_modifier": 0.5, "trust_gain": 2,
                     "original_order": {"action": "fortify", "confidence": 0.9, "target": None},
                     "original_command": {"confidence": 0.95, "marshal": "Ney"},
                     "parsed_command": {"command": {"confidence": 0.95, "action": "move"}},
                     "options": [{"type": "preferred", "trust_change": 3}]}
        before = copy.deepcopy(objection)
        wire = M._objection_for_wire(objection)
        assert objection == before, "the input is never touched"
        assert list(_w14_floats(wire)) == []
        assert wire["trust_gain_modifier"] == 50 and "severity" not in wire
        assert wire["original_order"] == {"action": "fortify", "target": None}
        assert wire["options"] == [{"type": "preferred", "trust_change": 3}]
        assert M._objection_for_wire(wire) == wire, "idempotent"

    def test_the_helper_keeps_a_word_severity_and_tolerates_nothing(self):
        import backend.main as M
        assert M._objection_for_wire({"severity": "major"})["severity"] == "major"
        assert M._objection_for_wire(None) is None
        assert M._objection_for_wire({"original_order": None})["original_order"] is None
        assert M._without_floats(None) is None

    # ── the client half ──────────────────────────────────────────────────

    def test_the_dialog_divides_the_percent_back_to_the_multiplier(self):
        src = (_W14_SCRIPTS / "objection_dialog.gd").read_text(encoding="utf-8")
        assert 'var trust_mod = float(objection_data.get("trust_gain_modifier", 100)) / 100.0' in src
        assert 'response.get("trust_gain_modifier", 100)' in src
        assert 'response.get("trust_gain_modifier", 1.0)' not in src
        assert "if trust_mod < 1.0:" in src
        assert "trust rewards x%.2f" in src

    def test_no_script_reads_what_the_wire_dropped(self):
        """The record that dropping them loses nothing: no `.gd` reads an
        objection's `severity`, its parse echoes or its `confidence`."""
        for script in sorted(_W14_SCRIPTS.glob("*.gd")):
            src = script.read_text(encoding="utf-8")
            for key in ("original_order", "original_command", "parsed_command"):
                assert key not in src, (script.name, key)
        dialog = (_W14_SCRIPTS / "objection_dialog.gd").read_text(encoding="utf-8")
        assert '"severity"' not in dialog and '"confidence"' not in dialog
        main = (_W14_SCRIPTS / "main.gd").read_text(encoding="utf-8")
        body = main[main.index("func _show_objection_dialog"):]
        body = body[:body.index("\nfunc ", 10)]
        assert "severity" not in body


