# S14E-X162 - the settlement table
# ══════════════════════════════════════════════════════════════════════════

_W14_TABLE = "propose common peace with Austria"
_W14_DEBUG = ("component_debug", "raw_total_harshness")


def _w14_table(client, w) -> dict:
    out = _w14_say(client, _W14_TABLE)
    assert out["diplomatic_dialogue"]["type"] == "settlement_confirm", out.get("message")
    return out


class TestS14EX162:
    """Reproduced on the shipped 1805 board at the real `POST /command`:
    `propose common peace with Austria` staged the whole-war table and the
    response carried TWENTY floats - ten under `/diplomatic_dialogue/
    settlement_preview/acceptance/` and the same ten under the response's own
    `/settlement_preview/acceptance/` - `component_debug/*` (the ceilings,
    scales and shares the scorer computed) and `raw_total_harshness`. Every
    dial click and the Review answered with the ten again. No `.gd` reads
    `settlement_preview`, `component_debug` or `raw_total_harshness`."""

    # ── the wire is float-free ───────────────────────────────────────────

    def test_the_staged_tables_response_is_float_free(self, _w14_board):
        client, w = _w14_board
        out = _w14_table(client, w)
        assert list(_w14_floats(out)) == []
        assert list(_w14_floats(out["diplomatic_dialogue"])) == []

    def test_the_table_the_scan_reads_is_on_the_wire_with_its_acceptance(self, _w14_board):
        """Guard the guard: the preview rides both places and keeps the rest
        of its acceptance block - only the scorer's debug left."""
        client, w = _w14_board
        out = _w14_table(client, w)
        for body in (out["diplomatic_dialogue"]["settlement_preview"], out["settlement_preview"]):
            acceptance = body["acceptance"]
            assert {"score", "threshold", "verdict", "components", "top_components"} <= set(acceptance)
            for key in _W14_DEBUG:
                assert key not in acceptance, key
        assert out["diplomatic_dialogue"]["per_court_acceptance"], "the rows the client reads stand"

    def test_every_click_on_the_table_is_float_free(self, _w14_board):
        client, w = _w14_board
        dialogue = _w14_table(client, w)["diplomatic_dialogue"]
        for scope in ("Austria", "Britain", "Russia"):
            reply = _w14_post(client, "/respond_to_diplomatic_dialogue", {
                "choice": "settlement_dial_generous", "action_params": {"scope": scope},
                "dialogue_id": dialogue["dialogue_id"]})
            assert list(_w14_floats(reply)) == [], scope
            dialogue = reply.get("diplomatic_dialogue") or dialogue
        review = _w14_post(client, "/respond_to_diplomatic_dialogue", {
            "choice": "submit_settlement_for_review", "dialogue_id": dialogue["dialogue_id"]})
        assert review.get("diplomatic_dialogue"), review.get("message")
        assert list(_w14_floats(review)) == []

    # ── the in-process preview keeps its debug ───────────────────────────

    def test_the_stored_dialogue_still_carries_its_debug_after_the_wire(self, _w14_board):
        client, w = _w14_board
        _w14_table(client, w)
        stored = w.pending_diplomatic_dialogue
        acceptance = stored["settlement_preview"]["acceptance"]
        assert acceptance["component_debug"], "the debug stands in the world"
        assert isinstance(acceptance["raw_total_harshness"], float)
        assert any(True for _ in _w14_floats(acceptance["component_debug"]))

    def test_the_in_process_preview_builder_still_returns_the_debug(self, _w14_board):
        from backend.game_logic import settlement_staging as SS
        client, w = _w14_board
        with contextlib.redirect_stdout(io.StringIO()):
            pv = SS.build_settlement_preview(
                w, war_id="war_1", settlement_terms=[{"type": "peace"}],
                covered_enemy_participants=["Austria", "Britain", "Russia"],
                actor_nation="France", ignore_active_dialogue=True)
        assert pv["success"]
        acceptance = pv["settlement_preview"]["acceptance"]
        assert acceptance["component_debug"] and "raw_total_harshness" in acceptance
        assert len(list(_w14_floats(pv))) >= 10

    def test_the_wire_dialogue_is_a_copy_the_stored_one_is_not(self, _w14_board):
        client, w = _w14_board
        out = _w14_table(client, w)
        wire = out["diplomatic_dialogue"]
        stored = w.pending_diplomatic_dialogue
        assert wire is not stored
        assert "component_debug" not in wire["settlement_preview"]["acceptance"]
        assert "component_debug" in stored["settlement_preview"]["acceptance"]

    # ── the other roads the preview rides ────────────────────────────────

    def test_the_cabinets_settlement_preview_endpoints_are_float_free(self, _w14_board):
        client, w = _w14_board
        body = {"mode": "settlement", "war_id": "war_1", "settlement_terms": [{"type": "peace"}],
                "proposer_side": "attackers",
                "covered_enemy_participants": ["Austria", "Britain", "Russia"]}
        posted = _w14_post(client, "/diplomatic_preview", body)
        assert posted.get("success") is True, posted
        assert list(_w14_floats(posted)) == []
        assert "component_debug" not in posted["settlement_preview"]["acceptance"]
        assert posted["settlement_preview"]["acceptance"]["score"] is not None

    def test_the_helpers_copy_and_never_mutate(self):
        import copy
        import backend.main as M
        dialogue = {"type": "settlement_confirm", "settlement_preview": {
            "acceptance": {"score": 40, "raw_total_harshness": 0.2,
                           "component_debug": {"term_harshness_penalty": {"normalized": 0.1}}},
            "war_id": "war_1"}}
        before = copy.deepcopy(dialogue)
        wire = M._dialogue_settlement_for_wire(dialogue)
        assert dialogue == before
        assert list(_w14_floats(wire)) == []
        assert wire["settlement_preview"]["acceptance"] == {"score": 40}
        assert wire["settlement_preview"]["war_id"] == "war_1"
        clean = {"type": "x", "settlement_preview": {"acceptance": {"score": 1}}}
        assert M._dialogue_settlement_for_wire(clean) is clean, "a clean body is not re-copied"
        assert M._dialogue_settlement_for_wire({"type": "incoming_proposal"}) == {"type": "incoming_proposal"}
        assert M._dialogue_settlement_for_wire(None) is None
        assert M._settlement_response_for_wire({"success": False}) == {"success": False}

    def test_the_wire_step_is_the_dialogue_chokepoint_and_the_response_key(self):
        """Source pin: `_wire_dialogue` strips on every dialogue road and
        `_wire_result_dialogues` strips the top-level `settlement_preview`."""
        src = (_W14_ROOT / "backend" / "main.py").read_text(encoding="utf-8")
        wire = src[src.index("def _wire_dialogue("):]
        wire = wire[:wire.index("\ndef _wire_result_dialogues(")]
        assert "_dialogue_settlement_for_wire(first_open.with_line(active_world, dialogue))" in wire
        body = src[src.index("def _wire_result_dialogues("):]
        body = body[:body.index("\n\n\n")]
        assert '_settlement_preview_for_wire(result["settlement_preview"])' in body

    def test_no_script_reads_the_scorers_debug(self):
        for script in sorted(_W14_SCRIPTS.glob("*.gd")):
            src = script.read_text(encoding="utf-8")
            for key in ("component_debug", "raw_total_harshness", "settlement_preview"):
                assert key not in src, (script.name, key)


