def _w14_beat(w) -> dict:
    """The Balance of Europe beat, fired by the engine's own detector on the
    shipped board: the notice the rail carries for it."""
    from backend.game_logic import coalition
    w.hegemony_signal_high_water = 0
    w.hegemony_signal_hegemon = None
    with contextlib.redirect_stdout(io.StringIO()):
        fired = coalition._check_hegemony_band_crossing(w, "test")
    assert fired, "the shipped board's leading bloc crosses the first band"
    return next(n for n in w.notifications.get_pending()
                if (n.get("details") or {}).get("event_type") == "balance_of_europe_shifted")


class TestS14EX170:
    """Sweep find (the playtest driver's float scan over a 14-turn run on the
    shipped board, every response): the Balance of Europe beat's notice put
    `/notifications[]/details/share` (0.37 - the bloc's share as the engine
    holds it) on the wire of `/command`, `/respond_to_diplomatic_dialogue` and
    `/strategic_response`, beside the `share_pct` (37) it already carries. The
    rail reads `details` by name (`icon`, `event_type`, `review_target`,
    `action_command` ...), never a float."""

    def test_the_beats_notice_carries_the_float_in_the_world_and_the_percent_beside_it(self, _w14_board):
        client, w = _w14_board
        notice = _w14_beat(w)
        assert isinstance(notice["details"]["share"], float), "the engine's own figure stays"
        assert isinstance(notice["details"]["share_pct"], int)

    def test_the_rail_is_float_free_on_the_wire(self, _w14_board):
        client, w = _w14_board
        _w14_beat(w)
        got = _w14_get(client, "/notifications")
        beat = [n for n in got["notifications"]
                if (n.get("details") or {}).get("event_type") == "balance_of_europe_shifted"]
        assert beat, "the guard: the beat is on the rail the scan reads"
        assert list(_w14_floats(got)) == []
        assert "share" not in beat[0]["details"] and isinstance(beat[0]["details"]["share_pct"], int)
        assert beat[0]["details"]["review_target"], "the rail's own keys stand"

    def test_a_command_response_carries_the_same_rail_float_free(self, _w14_board):
        client, w = _w14_board
        _w14_beat(w)
        out = _w14_say(client, "status")
        assert out["notifications"], "the rail rides the response"
        assert list(_w14_floats(out["notifications"])) == []

    def test_the_stored_notice_is_untouched_by_the_wire(self, _w14_board):
        client, w = _w14_board
        notice = _w14_beat(w)
        _w14_get(client, "/notifications")
        _w14_say(client, "status")
        assert isinstance(notice["details"]["share"], float)
        assert any(n is notice for n in w.notifications.get_pending())

    def test_the_helper_copies_only_what_it_cleans(self):
        import copy
        import backend.main as M
        notice = {"id": "n1", "details": {"share": 0.37, "share_pct": 37,
                                          "bloc_members": [{"nation": "Spain", "weight": 0.5}]}}
        before = copy.deepcopy(notice)
        wire = M._notification_for_wire(notice)
        assert notice == before
        assert list(_w14_floats(wire)) == []
        assert wire["details"] == {"share_pct": 37, "bloc_members": [{"nation": "Spain"}]}
        clean = {"id": "n2", "details": {"icon": "scales"}}
        assert M._notification_for_wire(clean) is clean
        bare = {"id": "n3"}
        assert M._notification_for_wire(bare) is bare
        assert M._notification_for_wire(None) is None

    def test_no_script_reads_a_notices_share(self):
        for script in sorted(_W14_SCRIPTS.glob("*.gd")):
            src = script.read_text(encoding="utf-8")
            assert 'details.get("share"' not in src and 'details["share"]' not in src, script.name


