def _w14_stage_murat(w) -> None:
    """Murat eyeing a fortified 60,000-man John at Tyrol (the board of
    `tests/test_s14f_p2_muster.py::_held`): at the next autonomous-attack pass
    the odds hold him."""
    from backend.models.marshal import StrategicOrder
    murat = w.get_marshal("Murat")
    john = w.get_marshal("ArchdukeJohn")
    murat.location = "Munich"
    murat.jealous_of = "Ney"
    murat.jealousy_turns_remaining = 4
    murat.jealousy_autonomous_warned = True
    john.location = "Tyrol"
    john.strength = 60000
    john.fortified = True
    john.defense_bonus = 0.12
    w.get_marshal("ArchdukeCharles").location = "Carniola"
    w.get_marshal("Mack").location = "Bohemia"
    for name in ("Ney", "Davout", "Lannes"):
        w.get_marshal(name).location = "Munich"
    w.calculate_visibility()
    murat.strategic_order = StrategicOrder(
        command_type="MOVE_TO", target="Vienna", target_type="region",
        started_turn=w.current_turn, original_command="move to Vienna")


def _w14_held_by_the_odds(w) -> dict:
    """The glory beat that stands where he was, run by the engine's own pass;
    the engine's own event is returned."""
    from backend.commands.executor import CommandExecutor
    import backend.game_logic.jealousy as J
    _w14_stage_murat(w)
    with contextlib.redirect_stdout(io.StringIO()):
        J.process_autonomous_attacks(w, CommandExecutor(), {"world": w})
    held = [e for e in getattr(w, "_pending_jealousy_turn_events", [])
            if e["type"] == "jealousy_autonomous_refused" and e.get("held_by_odds")]
    assert held, "the odds should have held him"
    return held[-1]


class TestS14EX172:
    """Sweep find (the playtest driver's float scan, `cmd_feel` and
    `sf_nav1_conquest_road`): the End Turn response carried `/events[]/ratio`
    0.396 (and 0.692) and the same under `/tactical_events[]` - the
    `jealousy_autonomous_refused` event's `ratio` (`round(ratio, 3)`), a field
    no `.gd` reads (the beat's sentence says "1 to N" in words). The wire now
    drops a float-valued field of any event, on a copy."""

    def test_the_engines_event_carries_the_float_the_wire_drops(self, _w14_board):
        client, w = _w14_board
        event = _w14_held_by_the_odds(w)
        assert isinstance(event["ratio"], float), "the engine's own figure stays in the world"
        assert "the odds held him" in event["message"]

    def test_the_end_turn_events_leave_float_free(self, _w14_board):
        import backend.main as M
        client, w = _w14_board
        event = _w14_held_by_the_odds(w)
        with contextlib.redirect_stdout(io.StringIO()):
            response = M.build_base_response(w, success=True, message="Turn 2 begins",
                                             events=[event, {"type": "x", "text": "plain"}])
        assert list(_w14_floats(response["events"])) == []
        wire = response["events"][0]
        assert wire["held_by_odds"] is True and wire["message"] == event["message"]
        assert "ratio" not in wire
        assert response["events"][1] == {"type": "x", "text": "plain"}
        assert isinstance(event["ratio"], float), "the stored event is untouched"

    def test_the_tactical_events_attach_float_free(self, _w14_board):
        import backend.main as M
        client, w = _w14_board
        event = _w14_held_by_the_odds(w)
        response = {}
        M._include_command_tactical_events(
            response, {"tactical_events": [{**event, "nation": w.player_nation}]}, w)
        got = response.get("tactical_events")
        assert got and got[0]["held_by_odds"] is True, "the player's own beat passes the fog filter"
        assert list(_w14_floats(got)) == [] and "ratio" not in got[0]
        assert isinstance(event["ratio"], float), "the stored event is untouched"

    def test_the_real_end_turn_delivers_the_beat_without_its_ratio(self, _w14_board):
        """The whole /command envelope on the road the sweep found: the board
        staged, End Turn pressed, the engine's pass holds him by the odds."""
        client, w = _w14_board
        _w14_stage_murat(w)
        out = _w14_say(client, "end turn")
        beats = [e for key in ("events", "tactical_events") for e in (out.get(key) or [])
                 if isinstance(e, dict) and e.get("type") == "jealousy_autonomous_refused"]
        assert beats, out.get("message")
        assert all(e.get("held_by_odds") and "ratio" not in e for e in beats)
        assert list(_w14_floats(out)) == []

    def test_the_helper_copies_and_leaves_strings_alone(self):
        import backend.main as M
        events = [{"type": "a", "ratio": 0.4, "nested": {"p": 0.2, "q": 3}}, "a line", None]
        wire = M._events_for_wire(events)
        assert wire == [{"type": "a", "nested": {"q": 3}}, "a line", None]
        assert events[0]["ratio"] == 0.4, "the input is never touched"
        assert M._events_for_wire(None) is None


