# S14E-X173 - the campaign log's nested figures
# ══════════════════════════════════════════════════════════════════════════

class TestS14EX173:
    """Sweep find (the driver's float scan; a GET the screens poll): `GET
    /campaign_log` cast an event's TOP-level floats to int but let a NESTED one
    through - a ratified settlement's `participant_reactions[].material_share`
    (0.0864, 0.27, 0.025 ...), the ally's share of the war the record keeps.
    The log screen draws the `display` line and the tier, never a nested
    figure; the stored event keeps it (the dispatch and the table's history
    read it)."""

    def _summary(self, w):
        event = {"type": "settlement_summary", "turn": 3, "nation": w.player_nation,
                 "war_id": "war_1", "war_label": "the War", "proposer_leader": w.player_nation,
                 "accepting_leader": "Austria", "applied_clauses": [], "war_ended": True,
                 "participant_reactions": [
                     {"kind": "ally_shut_out", "ally": "Spain", "material_share": 0.0864,
                      "material_points": 3, "severity": 2},
                     {"kind": "rewarded", "ally": "Bavaria", "material_share_pct": 27}]}
        w.event_log.append(event)
        return event

    def test_the_log_is_float_free_and_keeps_its_reactions(self, _w14_board):
        client, w = _w14_board
        event = self._summary(w)
        log = _w14_get(client, "/campaign_log")
        rows = [e for t in log["turns"] for e in t["events"] if e["type"] == "settlement_summary"]
        assert rows, "the guard: the settlement event is on the log the scan reads"
        assert list(_w14_floats(log)) == []
        reactions = rows[0]["participant_reactions"]
        assert [r["ally"] for r in reactions] == ["Spain", "Bavaria"]
        assert "material_share" not in reactions[0] and reactions[0]["material_points"] == 3
        assert reactions[1]["material_share_pct"] == 27
        assert event["participant_reactions"][0]["material_share"] == 0.0864, "the record keeps it"

    def test_the_top_level_cast_is_unchanged(self, _w14_board):
        client, w = _w14_board
        w.event_log.append({"type": "battle", "turn": 2, "nation": w.player_nation, "ratio": 1.5,
                            "attacker": "Ney", "defender": "Mack", "region": "Swabia",
                            "attacker_nation": w.player_nation, "marshal": "Ney"})
        log = _w14_get(client, "/campaign_log")
        assert list(_w14_floats(log)) == []

