def _w15_with_davout_beside_mack(world):
    """Davout at Swabia with Mack and Ney far from him: the counsel's first
    attack is now Davout's, not the boot's Ney."""
    world.get_marshal("Davout").location = "Swabia"
    world.get_marshal("Ney").location = "Paris"
    return world


def _w15_no_live_attack(monkeypatch):
    """The counsel offers no attack today (only a march): `live_attack_example`
    is None, so a refusal keeps its static example."""
    import backend.ai.counsel as counsel
    monkeypatch.setattr(counsel, "military_counsel",
                        lambda world, nation, limit=4: ["Ney, march to Orleanais"])


_W15_HINT_NEY = ("Ask 'what if Ney attacks Mack' first — it names who marches with "
                 "Ney, and costs nothing.")
_W15_HINT_DAVOUT = ("Ask 'what if Davout attacks Mack' first — it names who marches "
                    "with Davout, and costs nothing.")


# ══════════════════════════════════════════════════════════════════════════
# S14E-X174 -- the comma between a list of marshals and the order
# ══════════════════════════════════════════════════════════════════════════

class TestS14EX174:
    """S14E-X174 -- the comma between a list of marshals and the order was
    mandatory, so "Ney and Davout fortify", "Ney and Davout attack Mack" and
    "Ney and Davout retreat" ran Ney's order and SILENTLY dropped Davout (no
    relay, no note) while the comma form relayed Davout's order.

    Reproduced (the keyless parser on the 1805 board): "Ney and Davout
    fortify" -> fortify, Ney, dropped_sequel None, second_marshal None; "Ney
    and Davout, fortify" -> the same order with dropped_sequel "Davout,
    fortify" and second_marshal "Davout".  The same for attack Mack
    ("Davout, support Ney") and retreat.

    The fix: `parser._split_second_name` lets the separator go when the rest of
    the line STARTS WITH a verb of the router's own set (`ROUTED_ORDER_WORDS`,
    read through `clause_guards.order_verb_re`) -- the bare recall the second
    wave let through (S14E-X143) is one of them.  Ney takes the order, Davout's
    rides the relay exactly as the comma form does.
    """

    @pytest.mark.parametrize("line,action,target,relayed", (
        ("Ney and Davout fortify", "fortify", None, "Davout, fortify"),
        ("Ney and Davout retreat", "retreat", None, "Davout, retreat"),
        ("Ney and Davout attack Mack", "attack", "Mack", "Davout, support Ney"),
        ("Ney and Davout drill", "drill", None, "Davout, drill"),
        ("Ney and Davout hold", "hold", "Rhineland", "Davout, hold"),       # hold names the corps' own province
        ("Ney and Davout scout Swabia", "scout", "Swabia", "Davout, scout Swabia"),
        ("Ney and Davout dig in", "fortify", None, "Davout, dig in"),
        ("Ney & Davout fortify", "fortify", None, "Davout, fortify"),
        ("ney and davout fortify", "fortify", None, "Davout, fortify"),
        ("Marshal Ney and Marshal Davout drill", "drill", None, "Davout, drill"),
        ("Ney and Davout stop", "cancel", None, "Davout, stop"),
        ("Ney and Davout cease", "cancel", None, "Davout, cease"),
        ("Ney, Davout and Soult fortify", "fortify", None, "Davout, fortify"),
        ("Ney and Davout fortify.", "fortify", None, "Davout, fortify."),
    ))
    def test_the_comma_less_list_is_the_relay_address(self, line, action, target, relayed, _w15_board):
        result = _w15_parse(_w15_board, line)
        command = result.get("command") or {}
        assert result.get("success") is True, (line, result.get("message") or result.get("error"))
        assert command.get("action") == action and command.get("marshal") == "Ney", (line, command)
        assert (command.get("target") or None) == target, (line, command)
        assert result.get("dropped_sequel_kind") == "second_name", (line, result)
        assert result.get("second_marshal") == "Davout", (line, result)
        assert result.get("dropped_sequel") == relayed, (line, result.get("dropped_sequel"))

    @pytest.mark.parametrize("with_comma,without", (
        ("Ney and Davout, fortify", "Ney and Davout fortify"),
        ("Ney and Davout, retreat", "Ney and Davout retreat"),
        ("Ney and Davout, attack Mack", "Ney and Davout attack Mack"),
        ("Ney, Davout and Soult, drill", "Ney, Davout and Soult drill"),
        ("Ney and Davout, stop", "Ney and Davout stop")))
    def test_the_comma_form_and_the_comma_less_form_are_one_address(self, with_comma, without, _w15_board):
        a, b = _w15_parse(_w15_board, with_comma), _w15_parse(_w15_board, without)
        assert (a.get("command") or {}).get("action") == (b.get("command") or {}).get("action")
        for key in ("dropped_sequel", "dropped_sequel_kind", "second_marshal",
                    "second_marshal_lead", "second_marshal_others", "warning"):
            assert a.get(key) == b.get(key), (key, a, b)

    def test_the_second_man_is_heard_on_the_endpoint(self, _w15_client, _w15_world):
        """Davout takes the fortify; Lannes's own order is on the line with
        its note -- not dropped in silence."""
        for line in ("Davout and Lannes fortify", "Davout and Lannes, fortify"):
            w = _w15_world
            w.get_marshal("Davout").fortified = False
            reply = _w15_say(_w15_client, line)
            assert reply.get("success") is True, (line, reply.get("message"))
            assert reply.get("relay_command") == "Lannes, fortify", (line, reply.get("relay_command"))
            assert "Lannes" in str(reply.get("relay_note") or ""), (line, reply)
            assert "You named Lannes beside Davout" in str(reply.get("message") or ""), (line, reply.get("message"))
            w.get_marshal("Davout").fortified = False
            w.get_marshal("Davout").stance = type(w.get_marshal("Davout").stance).NEUTRAL

    def test_the_splitter_itself(self, _w15_board):
        from backend.commands.parser import _split_second_name
        _world, state, _parser = _w15_board
        split = _split_second_name("Ney, Davout and Soult fortify", state)
        assert (split["first"], split["second"], split["others"], split["first_text"], split["order"]) == (
            "Ney", "Davout", ["Soult"], "Ney, fortify", "Davout, fortify")

    @pytest.mark.parametrize("line", (
        "Ney and Davout",                       # no order at all
        "Ney and Mack attack",                 # an enemy is never our second man
        "Ney and Ney fortify",                 # one man named twice is one man
        "Ney and Soult everyone attack",       # the collective rule's words
        "Ney and Davout are ready",            # no verb of the router's
        "Ney and Davout zorglub",              # not an order
        "Ney fortify",                         # one man
        "Ney and Davout's corps fortify"))     # a possessive is no list
    def test_nothing_that_is_no_list_and_order_is_split(self, line, _w15_board):
        from backend.commands.parser import _split_second_name
        _world, state, _parser = _w15_board
        assert _split_second_name(line, state) is None, line

    def test_the_verbs_are_the_routers_own(self):
        """The separator reads the generated set: every verb the router routes
        on may follow a list, and nothing the router does not know does."""
        from backend.ai.clause_guards import order_verb_re
        from backend.ai.routed_order_words import ROUTED_ORDER_WORDS
        regex = order_verb_re()
        for word in ("fortify", "attack", "retreat", "stop", "cancel", "halt", "drill", "hold", "scout"):
            assert word in ROUTED_ORDER_WORDS and regex.match(word + " now"), word
        assert not regex.match("zorglub now") and not regex.match("ney now")

    def test_the_golden_corpus_holds_the_rows(self):
        rows = _w15_corpus_rows()
        for utterance, action in (("Ney and Davout fortify", "fortify"), ("Ney and Davout attack Mack", "attack")):
            assert rows[utterance]["expected"]["action"] == action, utterance
            assert rows[utterance]["expected"]["dropped_sequel"], utterance


# ══════════════════════════════════════════════════════════════════════════
# S14E-X175 -- two static examples teach a bare attack
# ══════════════════════════════════════════════════════════════════════════

class TestS14EX175:
    """S14E-X175 -- the two static examples left over from XN7: "Whom shall I
    send, Sire ... 'Ney, attack Mack'" (`combat_executor.
    _resolve_auto_assign_attacker`) and the fleet-is-no-corps refusal quoting
    'Ney, attack Swabia' (`main.py`) taught a bare attack with no word of the
    free preview -- and a name that may not be the live one.

    Reproduced (the shipped 1805 board, the real endpoint): "the Guard, attack
    Mack" -> "... Name the marshal and the foe - 'Ney, attack Mack'." and
    nothing after it; "Send the fleet to attack Swabia." -> "... a province is
    attacked by a marshal - 'Ney, attack Swabia'." and nothing after it.

    The fix: `movement_executor.live_attack_example(world)` -- the counsel's
    own first attack (`ai.counsel.military_counsel`, the line `what can I do`
    opens with), None when none is lawful today -- is quoted and followed by
    `attack_preview_hint_for(who, foe)`; with no live pair the static example
    stays, with the hint.
    """

    def test_the_live_pair_is_the_counsels_first_attack(self, _w15_world):
        from backend.ai.counsel import what_can_i_do
        from backend.commands.movement_executor import live_attack_example
        assert live_attack_example(_w15_world) == ("Ney", "Mack")
        first = next(line for line in what_can_i_do(_w15_world, "France", limit=6) if ", attack " in line)
        assert first == "Ney, attack Mack"
        _w15_with_davout_beside_mack(_w15_world)
        assert live_attack_example(_w15_world) == ("Davout", "Mack")
        _w15_world.actions_remaining = 0            # nothing is lawful with no action left
        assert live_attack_example(_w15_world) is None
        assert live_attack_example(None) is None

    def test_the_whom_shall_i_send_answer_quotes_the_live_pair(self, _w15_client, _w15_world):
        _w15_with_davout_beside_mack(_w15_world)
        ap = int(_w15_world.actions_remaining)
        reply = _w15_say(_w15_client, "the Guard, attack Mack")
        text = str(reply.get("message") or "")
        assert reply.get("success") is False, text
        assert "Whom shall I send, Sire, and against whom?" in text, text
        assert "Name the marshal and the foe — 'Davout, attack Mack'. " + _W15_HINT_DAVOUT in text, text
        assert "'Ney, attack Mack'" not in text, text
        assert int(_w15_world.actions_remaining) == ap

    def test_the_whom_shall_i_send_answer_keeps_the_static_example_with_the_hint(
            self, _w15_client, _w15_world, monkeypatch):
        _w15_no_live_attack(monkeypatch)            # no live pair today
        text = str(_w15_say(_w15_client, "the Guard, attack Mack").get("message") or "")
        assert "Name the marshal and the foe — 'Ney, attack Mack'. " + _W15_HINT_NEY in text, text

    def test_the_fleet_refusal_quotes_the_live_pair(self, _w15_client, _w15_world):
        _w15_with_davout_beside_mack(_w15_world)
        ap = int(_w15_world.actions_remaining)
        text = str(_w15_say(_w15_client, "Send the fleet to attack Swabia.").get("message") or "")
        assert "The fleet is not a corps, Sire" in text and "I have relayed nothing" in text, text
        assert "a foe is attacked by a marshal — 'Davout, attack Mack'. " + _W15_HINT_DAVOUT in text, text
        assert "'Ney, attack Swabia'" not in text, text
        assert int(_w15_world.actions_remaining) == ap

    def test_the_fleet_refusal_keeps_the_static_example_with_the_hint(
            self, _w15_client, _w15_world, monkeypatch):
        _w15_no_live_attack(monkeypatch)
        text = str(_w15_say(_w15_client, "Send the fleet to attack Swabia.").get("message") or "")
        assert ("a province is attacked by a marshal — 'Ney, attack Swabia'. "
                "Ask 'what if Ney attacks Swabia' first — it names who marches with Ney, "
                "and costs nothing.") in text, text

    def test_the_quoted_live_order_is_one_the_board_takes(self, _w15_client, _w15_world):
        """shown == applied: the sentence quoted parses to the attack, and the
        preview it names answers (nothing is spent)."""
        _w15_with_davout_beside_mack(_w15_world)
        gold, ap = int(_w15_world.nation_gold["France"]), int(_w15_world.actions_remaining)
        reply = _w15_say(_w15_client, "what if Davout attacks Mack")        # the sentence the hint teaches
        assert reply.get("success") is True and "MUSTER — Davout" in str(reply.get("message") or ""), reply.get("message")
        assert (int(_w15_world.nation_gold["France"]), int(_w15_world.actions_remaining)) == (gold, ap)
        from backend.commands.parser import CommandParser
        from backend.ai.parser_eval import build_llm_game_state
        with _w15_quiet():
            parsed = CommandParser(use_real_llm=False).parse(
                "Davout, attack Mack", build_llm_game_state(_w15_world), world=_w15_world)
        assert (parsed.get("command") or {}).get("action") == "attack", parsed

    def test_no_static_attack_example_is_left_without_the_hint(self):
        """The sweep: every `'<Name>, attack <X>'` a refusal prints in the
        three command executors and main.py is followed by the hint's door."""
        root = Path(__file__).resolve().parents[1] / "backend"
        for name in ("main.py", "commands/combat_executor.py", "commands/movement_executor.py",
                     "commands/strategic_executor.py", "commands/delegation.py"):
            source = (root / name).read_text(encoding="utf-8")
            for found in re.finditer(r"'Ney, attack (?:Mack|Swabia)'", source):
                window = source[found.start(): found.start() + 700]
                assert "attack_preview_hint_for" in window or "_preview_hint" in window, (name, found.group(0))


# ══════════════════════════════════════════════════════════════════════════
# S14E-X176 -- "recruit marshals" raises a levy
# ══════════════════════════════════════════════════════════════════════════

class TestS14EX176:
    """S14E-X176 -- "recruit marshals" (plural, no count word) still raised a
    3,000-man LEVY (S14E-X184 pinned it as a levy on purpose and fixed only the
    counted forms).

    Reproduced (the keyless parser on the 1805 board): "recruit marshals" ->
    action `recruit` (the levy), "recruit good marshals" -> `recruit`; "recruit
    new marshals" -> `recruit_marshal`.

    The fix: `llm_client._PLURAL_MARSHALS_ARE_THE_MARSHALATE_RE` -- the verb,
    at most a count or an adjective, then the plural "marshals" (not a
    possessive) is the Marshalate's: it asks whom and spends nothing.
    "recruit infantry / men / levies" and "recruit infantry for the marshals"
    read as before.
    """

    @pytest.mark.parametrize("line", (
        "recruit marshals", "Recruit Marshals.", "recruit marshals please", "recruit good marshals",
        "recruit more marshals", "recruit new marshals", "recruit two marshals", "recruit some new marshals",
        "recruit able marshals", "Ney, recruit marshals"))
    def test_the_plural_is_the_marshalate_not_a_levy(self, line, _w15_board):
        command = _w15_parse(_w15_board, line).get("command") or {}
        assert command.get("action") == "recruit_marshal", (line, command)
        assert not command.get("target"), (line, command)

    @pytest.mark.parametrize("line", (
        "recruit infantry", "recruit men", "recruit levies", "recruit 3000 infantry", "recruit cavalry",
        "recruit infantry for the marshals", "recruit 3000 men for marshals", "recruit the marshals",
        "recruit marshals' regiments", "recruit two infantry for Davout", "recruit"))
    def test_every_troop_recruit_reads_as_before(self, line, _w15_board):
        command = _w15_parse(_w15_board, line).get("command") or {}
        assert command.get("action") == "recruit", (line, command)

    def test_the_answer_asks_whom_and_spends_nothing(self, _w15_client, _w15_world):
        w = _w15_world
        gold, ap, admin = int(w.nation_gold["France"]), int(w.actions_remaining), int(w.admin_actions_remaining)
        troops = sum(int(m.strength) for m in w.get_player_marshals())
        for line in ("recruit marshals", "recruit good marshals", "Ney, recruit marshals"):
            reply = _w15_say(_w15_client, line)
            text = str(reply.get("message") or "")
            assert reply.get("success") is False, (line, text)
            assert text.startswith("Whom shall we raise to the marshalate, Sire? Candidates:"), (line, text)
        assert (int(w.nation_gold["France"]), int(w.actions_remaining), int(w.admin_actions_remaining)) == (gold, ap, admin)
        assert sum(int(m.strength) for m in w.get_player_marshals()) == troops

    def test_the_golden_corpus_holds_the_row(self):
        assert _w15_corpus_rows()["recruit marshals"]["expected"]["action"] == "recruit_marshal"


# ══════════════════════════════════════════════════════════════════════════
# S14E-X177 -- "everyone stand down" / "cease" / "rest"
# ══════════════════════════════════════════════════════════════════════════

_W15_POINTER = ("To halt a corps where it stands: 'Ney, hold'; to recall every standing "
                "order: 'everyone stop'.")


def _w15_three_orders(client, world) -> list:
    """Ney, Davout and Lannes each on a standing march; the turn moved on so a
    recall is a mid-march one."""
    world.actions_remaining = 9
    for line in ("Ney, march to Orleanais", "Davout, march to Nivernais", "Lannes, march to Orleanais"):
        reply = _w15_say(client, line)
        assert reply.get("success") is True, (line, reply.get("message"))
    held = [m.name for m in world.get_player_marshals() if m.strategic_order is not None]
    assert held == ["Ney", "Davout", "Lannes"], held
    world.current_turn += 1
    world.actions_remaining = 9
    return held


class TestS14EX177:
    """S14E-X177 -- "everyone stand down" answered "Did you mean 'Davout'?
    ('down' not found)" (the stand-down keyword was removed as a stance, Fix 9,
    and the fuzzy matcher then took "down" for a name), and "everyone cease" /
    "everyone rest" parsed Unknown.

    Reproduced (the keyless parser on the 1805 board, the real endpoint):
    "everyone stand down" / "stand down" -> "I do not find 'down' in the order
    of battle, Sire. Did you mean Davout?"; "everyone cease" / "Ney cease" /
    "cease" / "everyone rest" / "Ney, rest" -> the unknown-order shrug.

    The fix: (1) "cease" joins cancel / stop / abort / halt on the collective
    road (`group_orders._CANCEL_VERBS`) and the single roads
    (`llm_client._BARE_CANCEL_TAIL_RE`, `_BARE_CANCEL_NO_COMMA_RE`, the bare
    verb); (2) "stand down" and "rest" -- bare, with the army's address, or
    "rest" after one of our marshals -- are no order the game carries:
    `llm_client._stand_down_or_rest` makes the chain's refusal
    `stand_down_is_no_order`, which `main.py` answers with the hold pointer
    (0 AP, nothing relayed).  "Ney, stand down" stays the NEUTRAL stance.
    """

    @pytest.mark.parametrize("line", (
        "everyone cease", "everybody cease", "all marshals cease", "cease everyone", "everyone, cease",
        "the army cease", "cease all orders", "everyone cease now", "please cease everyone"))
    def test_cease_is_the_collective_recall(self, line, _w15_board):
        from backend.commands.group_orders import is_collective_cancel
        assert is_collective_cancel(line), line
        result = _w15_parse(_w15_board, line)
        command = result.get("command") or {}
        assert result.get("success") is True, (line, result.get("message") or result.get("error"))
        assert command.get("action") == "cancel" and not command.get("marshal"), (line, command)

    @pytest.mark.parametrize("line", ("Ney cease", "Ney, cease", "cease Ney", "Marshal Ney cease", "ney cease.", "cease"))
    def test_cease_is_the_single_cancel(self, line, _w15_board):
        result = _w15_parse(_w15_board, line)
        command = result.get("command") or {}
        assert result.get("success") is True, (line, result.get("message") or result.get("error"))
        assert command.get("action") == "cancel", (line, command)
        if "ney" in line.lower():
            assert command.get("marshal") == "Ney", (line, command)

    @pytest.mark.parametrize("line", (
        "cease fire", "ceasefire", "cease hostilities with Austria", "Talleyrand, cease hostilities",
        "Ney, cease attacking Mack", "cease the war"))
    def test_nothing_else_became_a_cancel_or_changed(self, line, _w15_board):
        from backend.commands.group_orders import is_collective_cancel
        assert not is_collective_cancel(line), line
        command = _w15_parse(_w15_board, line).get("command") or {}
        assert command.get("action") != "cancel" or line.startswith("Ney, cease attacking"), (line, command)

    def test_everyone_cease_recalls_every_standing_order(self, _w15_client, _w15_world):
        w = _w15_world
        held = _w15_three_orders(_w15_client, w)
        reply = _w15_say(_w15_client, "everyone cease")
        text = str(reply.get("message") or "")
        assert reply.get("success") is True, text
        assert text.startswith("Every standing order is recalled, corps by corps — 3 corps, 3 actions for the 9 in hand."), text
        for name in held:
            assert f"{name}: {name} halts his march and awaits new orders." in text, (name, text)
        assert 9 - int(w.actions_remaining) == 3
        assert [m.name for m in w.get_player_marshals() if m.strategic_order is not None] == []

    def test_a_list_before_cease_rides_the_relay(self, _w15_board):
        result = _w15_parse(_w15_board, "Ney and Davout cease")
        assert (result.get("command") or {}).get("action") == "cancel"
        assert result.get("dropped_sequel") == "Davout, cease" and result.get("second_marshal") == "Davout"

    @pytest.mark.parametrize("line,word", (
        ("everyone stand down", "Stand down"), ("stand down", "Stand down"), ("Stand down.", "Stand down"),
        ("stand everyone down", "Stand down"), ("all marshals stand down", "Stand down"),
        ("everyone, stand down", "Stand down"), ("please stand down", "Stand down"), ("the army stand down", "Stand down"),
        ("everyone rest", "Rest"), ("rest", "Rest"), ("all marshals rest", "Rest"), ("Ney rest", "Rest"),
        ("Ney, rest", "Rest"), ("Marshal Ney, rest", "Rest"), ("the army rest", "Rest"), ("everyone, rest.", "Rest")))
    def test_stand_down_and_rest_answer_with_the_hold_pointer(self, line, word, _w15_client, _w15_world):
        w = _w15_world
        ap, gold = int(w.actions_remaining), int(w.nation_gold["France"])
        reply = _w15_say(_w15_client, line)
        text = str(reply.get("message") or "")
        assert reply.get("success") is False, (line, text)
        assert f"'{word}' is no order I know, Sire, and I have relayed nothing." in text, (line, text)
        assert _W15_POINTER in text, (line, text)
        assert "Did you mean" not in text and "do not find" not in text and "eludes me" not in text, (line, text)
        assert not reply.get("relay_command"), reply
        assert (int(w.actions_remaining), int(w.nation_gold["France"])) == (ap, gold)

    @pytest.mark.parametrize("line", ("Davout, rest", "Marshal Davout, rest", "General Davout rest"))
    def test_the_pointer_quotes_the_marshal_who_was_addressed(self, line, _w15_client):
        text = str(_w15_say(_w15_client, line).get("message") or "")
        assert "To halt a corps where it stands: 'Davout, hold'; to recall every standing order: 'everyone stop'." in text, text

    def test_the_two_orders_the_pointer_teaches_are_read(self, _w15_board):
        command = _w15_parse(_w15_board, "Ney, hold").get("command") or {}
        assert command.get("action") == "hold" and command.get("marshal") == "Ney", command
        command = _w15_parse(_w15_board, "everyone stop").get("command") or {}
        assert command.get("action") == "cancel" and not command.get("marshal"), command

    @pytest.mark.parametrize("line", (
        "Ney, stand down", "Ney stand down", "Marshal Ney, stand down",     # the NEUTRAL stance, as before
        "rest your men", "Ney, rest your men", "Ney, stay put",               # the wait, as before
        "stand fast", "Ney, hold", "the army rests", "Zorglub rest"))
    def test_the_older_readings_are_untouched(self, line, _w15_board):
        from backend.ai.llm_client import _stand_down_or_rest
        pairs = [("ney", "Ney"), ("davout", "Davout")]
        assert _stand_down_or_rest(line.lower(), pairs) is None, line
        result = _w15_parse(_w15_board, line)
        assert "no order I know" not in str(result), (line, result)

    def test_the_stance_order_still_changes_the_stance(self, _w15_board):
        command = _w15_parse(_w15_board, "Ney, stand down").get("command") or {}
        assert command.get("action") == "stance_change" and command.get("marshal") == "Ney", command

    def test_the_unit(self):
        from backend.ai.llm_client import _stand_down_or_rest
        pairs = [("ney", "Ney"), ("davout", "Davout")]
        assert _stand_down_or_rest("everyone stand down", pairs) == ("stand down", "Ney")
        assert _stand_down_or_rest("rest", pairs) == ("rest", "Ney")
        assert _stand_down_or_rest("davout, rest", pairs) == ("rest", "Davout")
        assert _stand_down_or_rest("ney, stand down", pairs) is None          # the stance order
        assert _stand_down_or_rest("zorglub rest", pairs) is None
        assert _stand_down_or_rest("rest your men", pairs) is None
        assert _stand_down_or_rest("", pairs) is None

    def test_the_routed_order_words_are_unmoved(self):
        """The addressee rule's verb set is generated from the router's
        branches (CX-R1): the new arms add no keyword the set lacks."""
        from backend.ai.routed_order_words import ROUTED_ORDER_WORDS
        from tools import gen_routed_order_words as GEN
        assert {"cease", "cancel", "stop", "abort", "halt"} <= set(ROUTED_ORDER_WORDS)
        assert set(ROUTED_ORDER_WORDS) == GEN.harvest()

    def test_the_golden_corpus_holds_the_rows(self):
        rows = _w15_corpus_rows()
        assert rows["everyone cease"]["expected"]["action"] == "cancel"
        assert rows["Ney, cease"]["expected"]["marshal"] == "Ney"
        assert rows["everyone stand down"]["expected"]["success"] is False


# ══════════════════════════════════════════════════════════════════════════
# S14E-X178 -- "first" said twice
# ══════════════════════════════════════════════════════════════════════════

class TestS14EX178:
    """S14E-X178 -- "Attack Mack in Swabia first. Ask 'what if Ney attacks
    Mack' first - ..." said "first" twice (the engaged-march refusal's
    suggestion plus the hint XN7 appended); so did "Try: 'Attack X' or move
    closer first. Ask 'what if ...' first - ...".

    Reproduced (the shipped 1805 board, the real endpoint, Ney with Mack at
    Swabia, John in range at Munich): "Ney, attack ArchdukeJohn" -> suggestion
    "Attack Mack in Swabia first. Ask 'what if Ney attacks Mack' first - it
    names who marches with Ney, and costs nothing." (two "first").

    The fix: `movement_executor.attack_preview_hint_for(who, foe, after=...)`
    drops the hint's own "first" when the sentence it follows already ends
    "first."; the two call sites in `combat_executor` pass the sentence.
    """

    def test_the_engaged_elsewhere_suggestion_says_first_once(self, _w15_client, _w15_world):
        w = _w15_world
        w.get_marshal("Ney").location = "Swabia"                  # with Mack
        w.get_marshal("ArchdukeJohn").location = "Munich"         # in range, elsewhere
        reply = _w15_say(_w15_client, "Ney, attack ArchdukeJohn")
        text = str(reply.get("message") or "")
        assert "Cannot attack elsewhere while engaged" in text, text
        joined = text.split("\n", 1)[1]
        assert joined == ("Attack Mack in Swabia first. Ask 'what if Ney attacks Mack' — "
                          "it names who marches with Ney, and costs nothing."), joined
        assert joined.count("first") == 1, joined

    def test_the_nearest_enemy_suggestion_says_first_once(self, _w15_world, monkeypatch):
        from backend.commands.executor import CommandExecutor
        w = _w15_world
        with _w15_quiet():
            ex = CommandExecutor()
        ney, charles = w.get_marshal("Ney"), w.get_marshal("ArchdukeCharles")
        monkeypatch.setattr(w, "find_nearest_enemy", lambda loc: (charles, 5))
        ctx = SimpleNamespace(
            marshal=ney, world=w, enemy_marshal=None, enemy_by_name=None, target="Carniola",
            resolved_target="Carniola", game_state={"world": w}, target_region=None,
            drill_cancelled_message="", is_counter_punch=False)
        result = ex._combat._attack_war_and_bombard_target(ctx)
        assert isinstance(result, dict) and result.get("success") is False, result
        assert result["suggestion"] == (
            "Try: 'Attack ArchdukeCharles' or move closer first. "
            "Ask 'what if Ney attacks ArchdukeCharles' — it names who marches "
            "with Ney, and costs nothing."), result["suggestion"]
        assert result["suggestion"].count("first") == 1

    def test_the_door_drops_its_first_only_after_a_first(self):
        from backend.commands.movement_executor import attack_preview_hint_for
        bare = attack_preview_hint_for("Ney", "Mack")
        assert bare == _W15_HINT_NEY
        assert attack_preview_hint_for("Ney", "Mack", after="Try: 'Ney, attack Mack'. ") == bare
        assert attack_preview_hint_for("Ney", "Mack", after="") == bare
        assert attack_preview_hint_for("Ney", "Mack", after="Attack Mack in Swabia first. ") == (
            "Ask 'what if Ney attacks Mack' — it names who marches with Ney, and costs nothing.")
        assert attack_preview_hint_for("Ney", "Mack", after="Move closer FIRST.") == (
            "Ask 'what if Ney attacks Mack' — it names who marches with Ney, and costs nothing.")
        assert attack_preview_hint_for("Ney", "Mack", after="Strike first or retreat. ") == bare   # not a "first."

    def test_no_other_refusal_says_first_twice(self, _w15_client, _w15_world):
        """The other XN7 sites (no "first." before the hint) keep the hint whole
        and carry exactly one "first"."""
        text = str(_w15_say(_w15_client, "Ney, move to Swabia").get("message") or "")
        assert _W15_HINT_NEY in text and text.count("first") == 1, text
        _w15_world.get_marshal("Ney").location = "Swabia"
        text = str(_w15_say(_w15_client, "Ney, march to Orleanais").get("message") or "")
        assert _W15_HINT_NEY in text, text
        assert text.split("\n", 1)[1].count("first") == 1, text      # the suggestion's own sentence


