# The sweep's own finds (letter W, third wave): S14E-X179 ... X181
# ══════════════════════════════════════════════════════════════════════════

class TestS14EX179:
    """S14E-X179 -- "raise two marshals" / "enlist new marshals" / "hire marshals"
    are X176's class on the other recruiting verbs: the first two raised a
    3,000-man levy, "hire marshals" / "hire a marshal" parsed Unknown.

    Reproduced (the keyless parser on the 1805 board): "raise two marshals" ->
    `recruit` (a levy); "enlist two marshals" -> `recruit`; "hire marshals" ->
    Unknown action; "hire a marshal" -> Unknown action.

    The fix: the same `_PLURAL_MARSHALS_ARE_THE_MARSHALATE_RE` reads raise /
    enlist / hire, and the singular "hire a marshal" joins the recruit arm
    (both behind the pension guard).
    """

    @pytest.mark.parametrize("line", (
        "raise two marshals", "raise new marshals", "raise marshals", "enlist two marshals",
        "hire marshals", "hire two marshals", "hire new marshals for the army", "hire a marshal",
        "hire a new marshal"))
    def test_the_other_verbs_reach_the_marshalate(self, line, _w15_board):
        command = _w15_parse(_w15_board, line).get("command") or {}
        assert command.get("action") == "recruit_marshal", (line, command)
        assert not command.get("target"), (line, command)

    @pytest.mark.parametrize("line,action", (
        ("raise 3000 infantry", "recruit"), ("raise a levy in Paris", "recruit"),
        ("enlist 3000 infantry", "recruit"), ("hire replacements", "purchase_levy"),
        ("raise the marshals pensions", "grant_pension"), ("raise marshals pensions", "grant_pension"),
        ("hire a marshal's pension", "grant_pension"), ("raise the marshals' morale", "recruit")))
    def test_nothing_else_moved(self, line, action, _w15_board):
        command = _w15_parse(_w15_board, line).get("command") or {}
        assert command.get("action") == action, (line, command)

    def test_the_answer_asks_whom_and_spends_nothing(self, _w15_client, _w15_world):
        w = _w15_world
        gold, ap, admin = int(w.nation_gold["France"]), int(w.actions_remaining), int(w.admin_actions_remaining)
        for line in ("raise two marshals", "enlist new marshals", "hire marshals", "hire a marshal"):
            text = str(_w15_say(_w15_client, line).get("message") or "")
            assert text.startswith("Whom shall we raise to the marshalate, Sire? Candidates:"), (line, text)
        assert (int(w.nation_gold["France"]), int(w.actions_remaining), int(w.admin_actions_remaining)) == (gold, ap, admin)

    def test_the_golden_corpus_holds_the_row(self):
        assert _w15_corpus_rows()["raise two marshals"]["expected"]["action"] == "recruit_marshal"


class TestS14EX180:
    """S14E-X180 -- X174's class with a filler between the list and the verb:
    "Ney and Davout will fortify", "... please fortify", "... both fortify",
    "... together attack Mack" ran Ney's order and dropped Davout in silence
    (the single address already drops the filler: "Ney will fortify").

    Reproduced (the keyless parser on the 1805 board): "Ney and Davout will
    fortify" -> fortify Ney, dropped_sequel None.

    The fix: the separator of `_split_second_name` may carry a run of
    please / kindly / now / both / together / will / shall / must / should
    before the verb; the filler is dropped from BOTH orders ("Ney, fortify" and
    "Davout, fortify").
    """

    @pytest.mark.parametrize("line,action,relayed", (
        ("Ney and Davout will fortify", "fortify", "Davout, fortify"),
        ("Ney and Davout please fortify", "fortify", "Davout, fortify"),
        ("Ney and Davout now fortify", "fortify", "Davout, fortify"),
        ("Ney and Davout must fortify", "fortify", "Davout, fortify"),
        ("Ney and Davout shall stop", "cancel", "Davout, stop"),
        ("Ney and Davout both fortify", "fortify", "Davout, fortify"),
        ("Ney and Davout should attack Mack", "attack", "Davout, support Ney"),
        ("Ney and Davout together attack Mack", "attack", "Davout, support Ney")))
    def test_a_filler_before_the_verb_is_dropped_and_the_second_man_heard(self, line, action, relayed, _w15_board):
        result = _w15_parse(_w15_board, line)
        command = result.get("command") or {}
        assert result.get("success") is True, (line, result.get("message") or result.get("error"))
        assert command.get("action") == action and command.get("marshal") == "Ney", (line, command)
        assert result.get("second_marshal") == "Davout", (line, result)
        assert result.get("dropped_sequel") == relayed, (line, result.get("dropped_sequel"))

    @pytest.mark.parametrize("line", ("Ney and Davout will", "Ney and Davout please", "Ney and Davout both",
                                      "Ney and Davout will zorglub"))
    def test_a_filler_with_no_verb_is_no_split(self, line, _w15_board):
        from backend.commands.parser import _split_second_name
        assert _split_second_name(line, _w15_board[1]) is None, line

    def test_the_golden_corpus_holds_the_row(self):
        assert _w15_corpus_rows()["Ney and Davout will fortify"]["expected"]["dropped_sequel"] == "Davout, fortify"


class TestS14EX181:
    """S14E-X181 -- "Ney, recruit marshals" / "Ney, recruit a marshal" took the
    ADDRESSEE for the candidate: "No candidate named 'Ney' awaits a
    commission." (found sweeping X176 -- the parser moved any extracted
    "marshal" of a recruit_marshal line into `target`, the very move that
    reads "recruit marshal Suchet").

    Reproduced (the real endpoint on the 1805 board): "Ney, recruit a
    marshal" -> "No candidate named 'Ney' awaits a commission."

    The fix: `parser._apply_fuzzy_matching` leaves the target empty when the
    extracted name is the line's own ADDRESS ("Ney," / "Marshal Ney:"); the
    executor then asks whom.
    """

    @pytest.mark.parametrize("line", ("Ney, recruit a marshal", "Ney, recruit marshals", "Marshal Ney, recruit two marshals",
                                      "Ney: commission a marshal", "Davout, hire marshals"))
    def test_the_addressee_is_no_candidate(self, line, _w15_client, _w15_world):
        w = _w15_world
        gold, ap, admin = int(w.nation_gold["France"]), int(w.actions_remaining), int(w.admin_actions_remaining)
        text = str(_w15_say(_w15_client, line).get("message") or "")
        assert text.startswith("Whom shall we raise to the marshalate, Sire? Candidates:"), (line, text)
        assert "No candidate named" not in text, (line, text)
        assert (int(w.nation_gold["France"]), int(w.actions_remaining), int(w.admin_actions_remaining)) == (gold, ap, admin)

    @pytest.mark.parametrize("line,candidate", (
        ("Ney, commission Grouchy", "Grouchy"), ("recruit marshal Grouchy", "Grouchy"),
        ("commission Grouchy", "Grouchy")))
    def test_a_named_candidate_still_reaches_the_executor(self, line, candidate, _w15_board):
        command = _w15_parse(_w15_board, line).get("command") or {}
        assert command.get("action") == "recruit_marshal" and command.get("target") == candidate, (line, command)

    def test_a_roster_man_named_as_the_candidate_is_still_refused_by_name(self, _w15_client):
        text = str(_w15_say(_w15_client, "commission Ney").get("message") or "")
        assert text.startswith("No candidate named 'Ney' awaits a commission."), text


class TestS14EX182:
    """S14E-X182 -- X177's class on the other words for the same thing: "stand
    easy", "at ease", "relax", "take a rest" (found sweeping X177) parsed to
    the unknown-order shrug, like "rest" did.

    Reproduced (the real endpoint on the 1805 board): "stand easy" / "at ease"
    / "relax" / "everyone relax" / "Ney, at ease" -> "Berthier peers at the
    dispatch with concern. 'I cannot make sense of this, Sire...'" (the
    generic shrug that offers 'Ney, attack Mack').

    The fix: the same `llm_client._stand_down_or_rest` reads them (bare, with
    the army's address, or after one of our marshals) and the chain refuses
    them with the hold pointer; "relax the siege" and "stand by" read as
    before.
    """

    @pytest.mark.parametrize("line,word", (
        ("stand easy", "Stand easy"), ("at ease", "At ease"), ("relax", "Relax"),
        ("everyone relax", "Relax"), ("everyone stand easy", "Stand easy"), ("all marshals, at ease", "At ease"),
        ("Ney, stand easy", "Stand easy"), ("Ney, relax", "Relax"), ("Davout at ease", "At ease"),
        ("everyone, take a rest", "Take a rest")))
    def test_the_other_words_for_rest_answer_with_the_hold_pointer(self, line, word, _w15_client, _w15_world):
        w = _w15_world
        ap = int(w.actions_remaining)
        reply = _w15_say(_w15_client, line)
        text = str(reply.get("message") or "")
        assert reply.get("success") is False, (line, text)
        assert f"'{word}' is no order I know, Sire, and I have relayed nothing." in text, (line, text)
        assert "'everyone stop'" in text and ", hold'" in text, (line, text)
        assert "eludes me" not in text and "cannot make sense" not in text, (line, text)
        assert int(w.actions_remaining) == ap

    @pytest.mark.parametrize("line", ("relax the siege", "stand by", "Ney, stand by", "stand fast", "Ney, stand down",
                                      "rest your men", "Zorglub relax"))
    def test_nothing_else_is_taken(self, line, _w15_board):
        from backend.ai.llm_client import _stand_down_or_rest
        assert _stand_down_or_rest(line.lower(), [("ney", "Ney"), ("davout", "Davout")]) is None, line

