_W16_SCENARIO = (Path(__file__).resolve().parents[1] / "godot-client" / "project-sovereign"
                 / "assets" / "maps" / "europe_1805.json")


def _w16_quiet():
    return contextlib.redirect_stdout(io.StringIO())


@pytest.fixture(scope="module")
def _w16_boot():
    from backend.models.world_state import WorldState
    with _w16_quiet():
        return WorldState.from_scenario(str(_W16_SCENARIO))


def _w16_fresh_world(boot):
    """The shipped 1805 board, a private copy."""
    from backend.models.world_state import WorldState
    return WorldState.from_dict(json.loads(json.dumps(boot.to_dict(), default=str)))


@pytest.fixture
def _w16_world(_w16_boot):
    return _w16_fresh_world(_w16_boot)


def _w16_use(world, monkeypatch):
    """The real endpoint on `world` (the keyless parser)."""
    from fastapi.testclient import TestClient
    from backend.commands.parser import CommandParser
    import backend.main as main_module
    monkeypatch.setattr(main_module, "world", world)
    monkeypatch.setattr(main_module, "game_state", {"world": world})
    monkeypatch.setattr(main_module, "parser", CommandParser(use_real_llm=False))
    return TestClient(main_module.app)


def _w16_say(client, text: str) -> dict:
    with _w16_quiet():
        return client.post("/command", json={"command": text}).json()


@pytest.fixture(scope="module")
def _w16_board():
    from backend.ai.parser_eval import build_llm_game_state, build_world
    from backend.commands.parser import CommandParser
    with _w16_quiet():
        world = build_world("1805")
        return world, build_llm_game_state(world), CommandParser(use_real_llm=False)


def _w16_parse(board, text: str) -> dict:
    world, state, parser = board
    with _w16_quiet():
        return parser.parse(text, state, world=world)


def _w16_corpus_rows() -> dict:
    corpus = json.loads((Path(__file__).parent / "data" / "parser_golden_corpus.json")
                        .read_text(encoding="utf-8"))
    return {e["utterance"]: e for e in corpus["entries"]}


# ══════════════════════════════════════════════════════════════════════════
# S14E-X192 -- "hire / recruit <Name> as a marshal"
# ══════════════════════════════════════════════════════════════════════════

class TestS14EX192:
    """S14E-X192 -- "hire Grouchy as a marshal" and "recruit Grouchy as a
    marshal" did not reach the Marshalate: the name stands BEFORE "as a
    marshal", farther than the 12-character windows (`\\brecruit\\b.{0,12}
    \\bmarshal`, the `\\bmarshal\\s+<name>` read of the `_rm` extraction) reach.

    Reproduced (the keyless parser on the 1805 board): "hire Grouchy as a
    marshal" -> no action at all (Berthier's "I cannot make sense of this");
    "recruit / raise / enlist Grouchy as a marshal" -> `recruit` (a LEVY: "No
    marshal is available to receive reinforcements"); "recruit Grouchy as
    marshal" -> `recruit_marshal` but with NO target (the executor asked whom,
    though the line named him).

    The fix: `llm_client._NAME_AS_A_MARSHAL_RE` -- the verb (recruit / raise /
    enlist / hire), the NAME, then "as (a) marshal" -- is read by the route
    (behind the pension guard) and by the `_rm` name extraction, so the line
    commissions the named candidate exactly as "commission Grouchy" does.
    "recruit infantry as a reserve", "recruit infantry as a marshal's escort"
    and every troop recruit read as before (a troop word is no candidate).
    """

    @pytest.mark.parametrize("line,candidate", (
        ("hire Grouchy as a marshal", "Grouchy"), ("recruit Grouchy as a marshal", "Grouchy"),
        ("raise Grouchy as a marshal", "Grouchy"), ("enlist Grouchy as a marshal", "Grouchy"),
        ("hire Grouchy as marshal", "Grouchy"), ("recruit Grouchy as marshal", "Grouchy"),
        ("Hire Suchet as a marshal.", "Suchet"), ("hire Oudinot as a new marshal", "Oudinot"),
        ("please recruit Mortier as our marshal", "Mortier"),
        ("hire marshal Grouchy as a marshal", "Grouchy"),
        ("Ney, hire Grouchy as a marshal", "Grouchy"), ("Marshal Ney, recruit Suchet as a marshal", "Suchet")))
    def test_the_named_man_reaches_the_marshalate(self, line, candidate, _w16_board):
        command = _w16_parse(_w16_board, line).get("command") or {}
        assert command.get("action") == "recruit_marshal", (line, command)
        assert command.get("target") == candidate, (line, command)
        assert not command.get("marshal"), (line, command)

    @pytest.mark.parametrize("line", ("hire someone as a marshal", "recruit him as a marshal",
                                      "recruit a man as marshal"))
    def test_a_placeholder_names_nobody_and_the_executor_asks_whom(self, line, _w16_board):
        command = _w16_parse(_w16_board, line).get("command") or {}
        assert command.get("action") == "recruit_marshal", (line, command)
        assert not command.get("target"), (line, command)

    @pytest.mark.parametrize("line,action", (
        ("recruit infantry as a reserve", "recruit"), ("recruit infantry", "recruit"),
        ("recruit 3000 infantry", "recruit"), ("recruit cavalry as a screen", "recruit"),
        ("recruit infantry as a marshal's escort", "recruit"),
        ("recruit infantry as marshal Ney's escort", "recruit"),
        ("recruit men as marshals", "recruit"), ("recruit Mortier as the marshals", "recruit"),
        ("recruit infantry because the marshal is weak", "recruit"),
        ("march to Ulm as the marshal is ready", "move"),
        ("hire replacements", "purchase_levy"), ("hire a marshal's pension", "grant_pension"),
        ("raise the marshals pensions", "grant_pension")))
    def test_every_troop_recruit_and_the_older_readings_are_unmoved(self, line, action, _w16_board):
        command = _w16_parse(_w16_board, line).get("command") or {}
        assert command.get("action") == action, (line, command)
        assert command.get("action") != "recruit_marshal" or not command.get("target"), (line, command)

    @pytest.mark.parametrize("line,candidate", (
        ("commission Grouchy", "Grouchy"), ("recruit marshal Grouchy", "Grouchy"),
        ("appoint Grouchy as marshal", "Grouchy"), ("Make Suchet a marshal", "Suchet"),
        ("give Oudinot a baton", "Oudinot")))
    def test_the_older_candidate_forms_still_name_him(self, line, candidate, _w16_board):
        command = _w16_parse(_w16_board, line).get("command") or {}
        assert command.get("action") == "recruit_marshal" and command.get("target") == candidate, (line, command)

    def test_the_unit(self):
        from backend.ai.llm_client import _NAME_AS_A_MARSHAL_RE as rx
        assert rx.search("hire grouchy as a marshal").group(1) == "grouchy"
        assert rx.search("recruit marshal grouchy as marshal.").group(1) == "grouchy"
        assert rx.search("recruit infantry as a marshal") is None            # a troop word is no candidate
        assert rx.search("recruit guards as a marshal's escort") is None     # a possessive is no title
        assert rx.search("recruit grouchy as marshals") is None              # the plural is X176's
        assert rx.search("commission grouchy as a marshal") is None          # commission has its own arm

    def test_the_line_commissions_him_exactly_as_commission_does(self, _w16_boot, monkeypatch):
        """Shown == applied: with the gold in hand, each phrasing leaves the
        same board (Grouchy in the order of battle, the same price paid)."""
        results = []
        for line in ("commission Grouchy", "hire Grouchy as a marshal", "recruit Grouchy as a marshal"):
            w = _w16_fresh_world(_w16_boot)
            w.nation_gold["France"] = 20000
            client = _w16_use(w, monkeypatch)
            gold, admin = int(w.nation_gold["France"]), int(w.admin_actions_remaining)
            reply = _w16_say(client, line)
            results.append((reply.get("success"), int(gold - w.nation_gold["France"]),
                            admin - int(w.admin_actions_remaining), "Grouchy" in w.marshals,
                            str(reply.get("message") or "")))
        reference = results[0]
        assert reference[0] is True and reference[3] is True, reference
        for line, got in zip(("hire", "recruit"), results[1:]):
            assert got == reference, (line, got, reference)

    def test_the_refusal_names_the_man_and_the_price_not_a_shrug(self, _w16_world, monkeypatch):
        """With too little gold the line is refused with the Marshalate's own
        sentence (the price), not the shrug or a levy's "no marshal to receive"."""
        client = _w16_use(_w16_world, monkeypatch)
        for line in ("hire Grouchy as a marshal", "recruit Grouchy as a marshal", "raise Grouchy as a marshal"):
            text = str(_w16_say(client, line).get("message") or "")
            assert text.startswith("Commissioning Grouchy costs"), (line, text)
            assert "cannot make sense" not in text and "reinforcements" not in text, (line, text)

    def test_a_placeholder_line_spends_nothing_and_asks_whom(self, _w16_world, monkeypatch):
        w = _w16_world
        client = _w16_use(w, monkeypatch)
        gold, ap, admin = int(w.nation_gold["France"]), int(w.actions_remaining), int(w.admin_actions_remaining)
        text = str(_w16_say(client, "hire someone as a marshal").get("message") or "")
        assert text.startswith("Whom shall we raise to the marshalate, Sire? Candidates:"), text
        assert (int(w.nation_gold["France"]), int(w.actions_remaining), int(w.admin_actions_remaining)) == (gold, ap, admin)

    def test_the_golden_corpus_holds_the_rows(self):
        rows = _w16_corpus_rows()
        for line in ("hire Grouchy as a marshal", "recruit Grouchy as a marshal"):
            expected = rows[line]["expected"]
            assert expected["action"] == "recruit_marshal" and expected["target"] == "Grouchy", (line, expected)

    def test_the_routed_order_words_are_unmoved(self):
        """The addressee rule's verb set is generated from the router's
        branches (CX-R1): the new arm adds no keyword the set lacks."""
        from backend.ai.routed_order_words import ROUTED_ORDER_WORDS
        from tools import gen_routed_order_words as GEN
        assert set(ROUTED_ORDER_WORDS) == GEN.harvest()


# ══════════════════════════════════════════════════════════════════════════
# S14E-X193 -- the keyed parse prompt's cancel keywords
# ══════════════════════════════════════════════════════════════════════════

def _w16_prompt(world, utterance="Ney, attack Mack") -> str:
    import backend.ai.prompt_builder as PB
    from backend.ai.parser_eval import build_llm_game_state
    gs = build_llm_game_state(world)
    name, personality = PB.addressed_marshal(utterance, gs)
    return PB.build_parse_prompt(utterance, gs, marshal_name=name, personality=personality)


def _w16_cancel_keywords(prompt: str) -> list:
    line = next(l for l in prompt.splitlines() if l.startswith("Cancel keywords:"))
    return re.findall(r'"([^"]+)"', line)


class TestS14EX193:
    """S14E-X193 -- the keyed-LLM parse prompt (`prompt_builder.build_parse_prompt`,
    the `## Cancel Command` section) listed "stand down" as a CANCEL keyword,
    which disagrees with the keyless parser (S14E-X177: "stand down" is no
    order -- a bare one answers with the hold pointer, "Ney, stand down" is the
    neutral stance -- while "cease" IS a cancel verb).

    Reproduced (the prompt built on the shipped 1805 board, before the fix):
    `Cancel keywords: "halt", "stop", "cancel", "abort", "stand down", "belay
    that"` -- "stand down" in, "cease" absent.  The same line was the manual
    test plan's 7C ("Test each: ... "stand down" ..."), which expects every
    keyword to work as a cancel.

    The fix: the list reads "halt", "stop", "cancel", "abort", "cease", "belay
    that" -- the keyless parser's own verbs.  The 16 parse cassettes of the
    IQ-9 gate are re-stamped keylessly (every parse prompt -5 characters, the
    responses untouched; `tests/data/l1_prompt_restamp.json` and the manifest
    with them).  `docs/MANUAL_TEST_PLAN.md` 7C says the same.
    """

    def test_the_cancel_keywords_are_the_keyless_parsers(self, _w16_world):
        keywords = _w16_cancel_keywords(_w16_prompt(_w16_world))
        assert keywords == ["halt", "stop", "cancel", "abort", "cease", "belay that"], keywords
        assert "stand down" not in keywords

    def test_no_prompt_section_teaches_stand_down_as_a_cancel(self, _w16_world):
        prompt = _w16_prompt(_w16_world)
        for line in prompt.splitlines():
            lowered = line.lower()
            if "stand down" in lowered:
                assert "cancel" not in lowered, line

    @pytest.mark.parametrize("keyword", ("halt", "stop", "cancel", "abort", "cease", "belay that"))
    def test_every_listed_keyword_is_a_cancel_on_the_keyless_road(self, keyword, _w16_board):
        """The prompt and the parser agree: each keyword the prompt teaches
        reads as `cancel` on the keyless road ("Ney, <keyword>")."""
        command = _w16_parse(_w16_board, f"Ney, {keyword}").get("command") or {}
        assert command.get("action") == "cancel" and command.get("marshal") == "Ney", (keyword, command)

    def test_stand_down_is_not_a_cancel_on_the_keyless_road(self, _w16_board):
        for line in ("stand down", "everyone stand down"):
            result = _w16_parse(_w16_board, line)
            assert (result.get("command") or {}).get("action") != "cancel", (line, result)
        command = _w16_parse(_w16_board, "Ney, stand down").get("command") or {}
        assert command.get("action") == "stance_change", command      # the neutral stance, as before

    def test_the_manual_test_plan_no_longer_lists_stand_down_as_a_cancel_verb(self):
        text = (Path(__file__).resolve().parents[1] / "docs" / "MANUAL_TEST_PLAN.md").read_text(encoding="utf-8")
        line = next(l for l in text.splitlines() if l.startswith('Test each: "halt"'))
        assert '"stand down"' not in line and '"cease"' in line, line
        assert "hold pointer" in text, "7C must say what 'stand down' answers with"

    def test_the_cassettes_carry_the_moved_prompt(self):
        """The re-stamp is exact: every parse cassette's recorded fingerprint
        is the live prompt (the IQ-9 drift gate), with the cancel line the only
        change (-5 characters: 'stand down' -> 'cease')."""
        import backend.ai.prompt_builder as PB
        source = Path(PB.__file__).read_text(encoding="utf-8")
        assert 'Cancel keywords: "halt", "stop", "cancel", "abort", "cease", "belay that"' in source
        assert "S14E-X193" in source


