_W17_MAIN = Path(__file__).resolve().parents[1] / "backend" / "main.py"


class TestS14EX194:
    """S14E-X194 (Golden Rule 2, the sweep of S14E-X172): a resumed column's
    events (`group_orders.attach`) joined the reply AFTER `build_base_response`
    had scrubbed the events of their floats, so the two popup roads that
    resume an army order (`/respond_to_objection`, `/strategic_response`)
    could carry an un-scrubbed event. Reproduced by source: the two
    `_group.attach(response, …)` sites were followed by no scrub."""

    def test_both_resume_sites_scrub_the_merged_events(self):
        src = _W17_MAIN.read_text(encoding="utf-8")
        sites = [m.start() for m in re.finditer(r"_group\.attach\(response, _group\.resume\(", src)]
        assert len(sites) == 2, sites
        for pos in sites:
            tail = src[pos:pos + 600]
            assert 'response["events"] = _events_for_wire(response.get("events"))' in tail, tail

    def test_the_scrub_drops_a_float_field_of_a_merged_event(self):
        from backend.main import _events_for_wire
        merged = [{"type": "x", "ratio": 0.396, "turn": 3}, {"type": "y", "men": 1200}]
        out = _events_for_wire(merged)
        assert out[0] == {"type": "x", "turn": 3} and out[1] == {"type": "y", "men": 1200}
        assert merged[0]["ratio"] == 0.396  # the stored list keeps its figure

