# ══════════════════════════════════════════════════════════════════════════
# S14E-X71 -- "build two depots in Paris" builds ONE and never says so
# ══════════════════════════════════════════════════════════════════════════

class TestS14EX71:
    """S14E-X71 -- a count in a build order is silently dropped (S14E-33's
    class: "lay down TWO ships" laid one keel and said nothing).

    Reproduced (the shipped 1805 board, the real endpoint): "build two depots
    in Paris" -> "Construction started: Supply Depot in Paris (2 turns, 300
    gold)" -- one depot, 300g, and not a word that the two was ignored; the
    same on "build 2 fortifications in Paris" and "build two watchtowers in
    Paris".

    The fix: `naval_executor.building_count_in` reads the count the way
    `ship_count_in` does (ONE reader, `named_count_in`, two noun sets); the
    build reply names a count above one as not read ("one building at a time
    per province -- the two is not read").  Nothing else changes: the build
    itself, the gold, and the AI's builds (a command with `_acting_nation`
    carries no typed line).
    """

    SAID = "one building at a time per province"

    def test_the_sighting_says_the_two_is_not_read(self, _w2_client, _w2_world):
        w = _w2_world
        gold = int(w.nation_gold["France"])
        reply = _w2_say(_w2_client, "build two depots in Paris")
        text = str(reply.get("message") or "")
        assert reply.get("success") is True, text
        assert "Construction started: Supply Depot in Paris" in text, text
        assert f"{self.SAID} — the two is not read" in text, text
        # shown == applied: ONE depot, ONE price
        assert gold - int(w.nation_gold["France"]) == 300
        assert w.get_region("Paris").building_under_construction["type"] == "supply_depot"

    @pytest.mark.parametrize("line,word", (
        ("build 2 depots in Paris", "two"),
        ("build three supply depots in Paris", "three"),
        ("build a pair of depots in Paris", "two"),
        ("build a couple of supply depots in Paris", "two"),
        ("build two more depots in Paris", "two"),
        ("build 4 depots in Paris", "four"),
        ("build 12 depots in Paris", "12"),
    ))
    def test_every_count_phrasing_is_named(self, line, word, _w2_client):
        text = str(_w2_say(_w2_client, line).get("message") or "")
        assert "Construction started" in text, (line, text)
        assert f"{self.SAID} — the {word} is not read" in text, (line, text)

    def test_the_other_buildings_are_read_the_same_way(self, _w2_client, _w2_world):
        text = str(_w2_say(_w2_client, "build 2 fortifications in Paris").get("message") or "")
        assert "Fortification in Paris" in text and "the two is not read" in text, text

    def test_a_watchtower_has_its_own_sentence(self, _w2_client):
        text = str(_w2_say(_w2_client, "build two watchtowers in Paris").get("message") or "")
        assert "Construction started: Watchtower in Paris" in text, text
        assert "one watchtower to a province — the two is not read" in text, text

    @pytest.mark.parametrize("line", (
        "build a depot in Paris", "build one depot in Paris", "build depot in Paris",
        "build a supply depot in Paris", "build a depot in Paris in 2 turns",
        "build a depot in Paris for 300 gold", "build a watchtower in Paris"))
    def test_no_count_or_a_count_of_one_is_unchanged(self, line, _w2_client):
        text = str(_w2_say(_w2_client, line).get("message") or "")
        assert text.startswith("Construction started"), (line, text)
        assert "not read" not in text, (line, text)
        assert text.count("(") == 1 and text.endswith("gold)"), text

    def test_the_second_depot_was_never_queued(self, _w2_client, _w2_world):
        _w2_say(_w2_client, "build two depots in Paris")
        again = _w2_say(_w2_client, "build a depot in Paris")
        assert again.get("success") is False
        assert "Already constructing" in str(again.get("message") or "")

    def test_the_reader_is_the_ship_readers_twin(self):
        from backend.commands.naval_executor import building_count_in, ship_count_in
        assert building_count_in("build two depots in Paris") == 2
        assert building_count_in("build 3 supply depots") == 3
        assert building_count_in("build a pair of forts") == 2
        assert building_count_in("build two training grounds") == 2
        assert building_count_in("build a depot") is None
        assert building_count_in("build one depot") == 1
        assert building_count_in("build 0 depots") is None
        assert building_count_in("build a depot in 2 turns") is None
        assert building_count_in("build a depot for 300 gold") is None
        assert building_count_in("") is None and building_count_in(None) is None
        # the ships' reader is untouched, and the two nouns do not cross
        assert ship_count_in("lay down two ships") == 2
        assert ship_count_in("build two depots in Paris") is None
        assert building_count_in("lay down two ships") is None

    def test_the_ai_builds_are_untouched(self, _w2_world):
        """An AI build carries `_acting_nation` and no typed line: whatever a
        stray `raw_command` holds, its reply is byte-identical."""
        from backend.commands.executor import CommandExecutor
        w = _w2_world
        with _w2_quiet():
            ex = CommandExecutor()
        cmd = {"target": "Vienna", "building_type": "supply_depot",
               "_acting_nation": "Austria", "raw_command": "build two depots in Vienna"}
        w.nation_gold["Austria"] = 5000
        result = ex._economy._execute_build(cmd, {"world": w}, raw_text="build two depots in Vienna")
        assert "not read" not in str(result.get("message") or ""), result


# ══════════════════════════════════════════════════════════════════════════
# S14E-X73 -- "Murat stop" (no comma) parses Unknown
# ══════════════════════════════════════════════════════════════════════════

class TestS14EX73:
    """S14E-X73 -- S14E-32's cancel tail needs its comma.

    Reproduced (the keyless parser on the 1805 board): "Murat cancel" /
    "Murat stop" / "Murat abort" -> success False, "Unknown action: unknown"
    (while "Murat halt" ran: the ` halt` keyword reads it, and "Murat, stop"
    ran: S14E-32's comma-tail arm).  The sentence is the same order.

    The fix: `llm_client._bare_cancel_without_comma` -- the whole line is a
    marshal of ours (any register the roster prints, an honorific allowed)
    and ONE of cancel / stop / abort / halt.  The comma-tail arm is not
    touched (its mutation pin still holds), "Ney attack Mack" and "the army
    stop" read as they did.
    """

    @pytest.mark.parametrize("verb", ("cancel", "stop", "abort", "halt"))
    def test_the_comma_is_optional_after_a_marshal(self, verb, _w2_board):
        for line in (f"Murat {verb}", f"murat {verb}", f"Murat {verb}.", f"Murat {verb.upper()}!",
                     f"Marshal Murat {verb}", f"general murat {verb}"):
            result = _w2_parse(_w2_board, line)
            command = result.get("command") or {}
            assert result.get("success") is True, (line, result.get("message"))
            assert command.get("action") == "cancel" and command.get("marshal") == "Murat", line

    def test_the_sentence_runs_through_the_endpoint(self, _w2_client):
        reply = _w2_say(_w2_client, "Murat stop")
        assert reply.get("success") is True, reply.get("message")
        assert "cannot determine" not in str(reply.get("message") or "")
        assert "Murat" in str(reply.get("message") or "")

    # S14E-X143 (the third wave) FLIPS "the army stop": the army is the
    # collective address the army road reads, and "the army stop" is now the
    # collective recall (pinned in tests/test_s14f_p2_w10.py::TestS14EX143).
    @pytest.mark.parametrize("line", (
        "Zorglub stop", "Ney Murat stop", "Murat please stop",
        "Mack stop"))
    def test_only_a_marshal_of_ours_heading_the_verb_is_the_cancel(self, line, _w2_board):
        result = _w2_parse(_w2_board, line)
        assert (result.get("command") or {}).get("action") != "cancel", (line, result)

    def test_orders_with_a_verb_are_untouched(self, _w2_board):
        for line, action in (("Ney attack Mack", "attack"), ("Ney, attack Mack stop", "attack"),
                             ("Murat, cancel", "cancel"), ("Murat, stop", "cancel"),
                             ("Ney stop attacking", "cancel")):
            command = _w2_parse(_w2_board, line).get("command") or {}
            assert command.get("action") == action, (line, command)

    def test_the_comma_arm_and_the_new_arm_do_not_overlap(self):
        import backend.ai.llm_client as llm
        roster = [("murat", "Murat"), ("ney", "Ney")]
        assert llm._bare_cancel_without_comma("murat stop", roster) is True
        assert llm._bare_cancel_without_comma("murat, stop", roster) is False
        assert llm._bare_cancel_without_comma("murat stop", []) is False
        assert llm._bare_cancel_without_comma("murat attack", roster) is False
        assert llm._bare_cancel_without_comma("", roster) is False

    def test_the_golden_corpus_holds_the_row(self):
        corpus = json.loads((Path(__file__).parent / "data" / "parser_golden_corpus.json")
                            .read_text(encoding="utf-8"))
        row = next(e for e in corpus["entries"] if e["utterance"] == "Murat stop")
        assert row["expected"]["action"] == "cancel" and row["expected"]["marshal"] == "Murat"


