# S14E-X80 -- the "what can I do" answers list the attack with no preview hint
# ══════════════════════════════════════════════════════════════════════════

_W2_HINT = ("Ask 'what if Ney attacks Mack' first — it names who marches with "
            "Ney, and costs nothing.")


class TestS14EX80:
    """S14E-X80 -- S14E-24 taught the TODAY list the free preview; five other
    surfaces that print the SAME counsel list (`what_can_i_do`) did not.

    Reproduced (the shipped 1805 board, the real endpoint): "what can I do"
    printed "Ney, attack Mack" among five orders and no word of "what if Ney
    attacks Mack"; the same on "who should I attack" (My counsel), a question
    the desk cannot take ("What I CAN do today"), the greeting ("This morning,
    'Ney, attack Mack' would be carried out at once") and "what is the goal"
    ("Today: ..."), and the shrug's "'Ney, attack Mack', perhaps?".

    The fix: each appends `dispatch.attack_preview_hint(lines)` -- the very
    sentence the TODAY list carries -- after its list; byte-identical when no
    attack line is listed.
    """

    def test_what_can_i_do_names_the_preview_under_the_list(self, _w2_client):
        text = str(_w2_say(_w2_client, "what can I do").get("message") or "")
        assert "Ney, attack Mack" in text, text
        assert _W2_HINT in text, text
        # under the list, above the Cabinet's door
        assert text.index("build supply depot") < text.index(_W2_HINT) < text.index("press F1"), text

    def test_the_counsel_answer_names_it_before_the_unordered_line(self, _w2_client):
        text = str(_w2_say(_w2_client, "who should I attack").get("message") or "")
        assert text.startswith("My counsel, Sire:"), text
        assert "attack" in text.split("\n")[1], text
        assert _W2_HINT in text, text
        assert text.index(_W2_HINT) < text.index("Nothing has been ordered."), text

    def test_the_unanswered_question_list_names_it(self, _w2_client):
        text = str(_w2_say(_w2_client, "should I paint the walls red").get("message") or "")
        assert "What I CAN do today:" in text, text
        assert _W2_HINT in text, text
        assert text.index("build supply depot") < text.index(_W2_HINT) < text.index("press F1"), text

    def test_the_greeting_names_it_beside_the_morning_attack(self, _w2_client):
        text = str(_w2_say(_w2_client, "hello").get("message") or "")
        assert "This morning, 'Ney, attack Mack' would be carried out at once." in text, text
        assert _W2_HINT in text, text

    def test_the_goal_answer_names_it_beside_today(self, _w2_client):
        text = str(_w2_say(_w2_client, "what is the goal of the game").get("message") or "")
        assert "Today: 'Ney, attack Mack'" in text, text
        assert _W2_HINT in text, text

    def test_the_shrug_names_it_when_it_offers_the_attack(self, _w2_world, monkeypatch):
        import random
        from backend.ai.llm_client import LLMClient
        import backend.ai.llm_client as llm
        monkeypatch.setattr(random, "choice", lambda seq: seq[0])
        with _w2_quiet():
            client = LLMClient()
        state = {"world": _w2_world,
                 "marshals": {m.name: {} for m in _w2_world.get_player_marshals()},
                 "enemies": {}}
        monkeypatch.setattr(llm, "_counsel_lines",
                            lambda gs: ["Ney, attack Mack", "Davout, march to Lorraine"])
        text = client._berthier_mock_response("flibbertigibbet", state, {})
        assert "'Ney, attack Mack', perhaps?" in text, text
        assert _W2_HINT in text, text

    def test_nothing_changes_when_no_attack_is_listed(self, _w2_world, monkeypatch):
        import backend.ai.counsel as counsel
        from backend.ai.question_desk import answer_board_question
        from backend.ai.first_contact import answer_first_contact
        from backend.commands.meta_executor import MetaExecutor
        lines = ["Davout, march to Lorraine", "Soult, fortify"]
        monkeypatch.setattr(counsel, "what_can_i_do", lambda *a, **k: list(lines))
        monkeypatch.setattr(counsel, "military_counsel", lambda *a, **k: list(lines))
        options = answer_board_question(_w2_world, {"kind": "options", "subject": "",
                                                    "subject_type": "board"})
        assert options == ("These orders would be carried out today, Sire:\n"
                           "  Davout, march to Lorraine\n  Soult, fortify\n"
                           "For any matter of state, press F1 for the Cabinet."), options
        from backend.ai.state_desk import _answer_counsel
        assert _answer_counsel(_w2_world) == (
            "My counsel, Sire:\n  Davout, march to Lorraine\n  Soult, fortify\n"
            "Nothing has been ordered.")
        hello = answer_first_contact("greeting", "hello", _w2_world)
        assert "what if" not in hello and "This morning, 'Davout, march to Lorraine'" in hello
        goal = answer_first_contact("goal", "what is the goal", _w2_world)
        assert "what if" not in goal
        with _w2_quiet():
            routed = MetaExecutor(SimpleNamespace())._route_unanswered_question(
                "should I paint the walls red", {"world": _w2_world})
        assert "what if" not in routed and "  Soult, fortify" in routed

    def test_the_hint_names_the_first_attack_among_the_lines(self, _w2_world, monkeypatch):
        import backend.ai.counsel as counsel
        from backend.ai.question_desk import answer_board_question
        monkeypatch.setattr(counsel, "what_can_i_do", lambda *a, **k: [
            "Davout, march to Lorraine", "Murat, attack ArchdukeJohn", "Ney, attack Mack"])
        text = answer_board_question(_w2_world, {"kind": "options", "subject": "",
                                                 "subject_type": "board"})
        assert "Ask 'what if Murat attacks ArchdukeJohn' first" in text, text
        assert text.count("Ask 'what if") == 1


# ══════════════════════════════════════════════════════════════════════════
# S14E-X81 -- the march & attack card has no muster line
# ══════════════════════════════════════════════════════════════════════════

class TestS14EX81:
    """S14E-X81 -- `order_quotes.march_quote(then_attack=)` (the "march &
    attack" card) carried `muster == ""`.

    Reproduced (the shipped board): `attack_quote(Soult, ArchdukeJohn)` -- a
    foe beyond Soult's reach -- is a `march_attack` card with ok True and an
    empty `muster`, where the plain attack card carries Berthier's real line.
    A real line read now would be the wrong field (the muster is read where
    the corps arrives), so the card says WHEN it is read: "On arrival Berthier
    will read the muster at <destination>."
    """

    def test_the_march_and_attack_card_says_when_the_muster_is_read(self, _w2_world):
        from backend.commands.order_quotes import attack_quote
        w = _w2_world
        far = attack_quote(w, w.get_marshal("Soult"), w.get_marshal("ArchdukeJohn"))
        assert far["kind"] == "march_attack" and far["ok"]
        assert far["muster"] == f"On arrival Berthier will read the muster at {far['dest']}."
        assert far["dest"] == w.get_marshal("ArchdukeJohn").location

    def test_the_plain_attack_card_keeps_the_real_line(self, _w2_world):
        from backend.commands.order_quotes import attack_quote
        w = _w2_world
        q = attack_quote(w, w.get_marshal("Ney"), w.get_marshal("Mack"))
        assert q["kind"] == "attack" and q["muster"].startswith("Berthier adds: ")
        assert "On arrival" not in q["muster"]

    def test_a_refused_march_and_attack_carries_no_line(self, _w2_world):
        from backend.commands.order_quotes import march_quote
        w = _w2_world
        w.actions_remaining = 0
        q = march_quote(w, w.get_marshal("Soult"), "Bohemia", then_attack="ArchdukeJohn")
        assert q["kind"] == "march_attack" and q["ok"] is False and q["muster"] == ""

    def test_a_plain_march_carries_no_line(self, _w2_world):
        from backend.commands.order_quotes import march_quote
        w = _w2_world
        q = march_quote(w, w.get_marshal("Soult"), "Lorraine")
        assert q["kind"] == "march" and q["muster"] == ""

    def test_the_line_names_no_odds_it_could_not_know(self, _w2_world):
        """Shown == priced: the line is a promise of WHEN, never a figure -- no
        men, no band, no corps named."""
        from backend.commands.order_quotes import attack_quote
        w = _w2_world
        far = attack_quote(w, w.get_marshal("Soult"), w.get_marshal("ArchdukeJohn"))
        assert not re.search(r"\d", far["muster"].replace(far["dest"], ""))
        assert "favorable" not in far["muster"] and "Berthier adds" not in far["muster"]

    def test_the_province_cards_carry_it(self, _w2_world):
        from backend.commands.order_quotes import march_quotes_for_region
        w = _w2_world
        john = w.get_marshal("ArchdukeJohn")
        rows = march_quotes_for_region(w, john.location)["attack"][0]["quotes"]
        march_rows = [q for q in rows if q["kind"] == "march_attack" and q["ok"]]
        assert march_rows, rows
        assert all(q["muster"] == f"On arrival Berthier will read the muster at {john.location}."
                   for q in march_rows)

    def test_the_card_renders_the_field_it_already_reads(self):
        """No client change: `order_confirm_card.gd` prints any `muster` it is
        handed under the objection line (S14E-24)."""
        src = (Path(__file__).resolve().parents[1] / "godot-client" / "project-sovereign"
               / "scripts" / "order_confirm_card.gd").read_text(encoding="utf-8")
        assert 'str(q.get("muster", ""))' in src


# ══════════════════════════════════════════════════════════════════════════
# S14E-X82 -- a CommandExecutor built per attack evaluation
# ══════════════════════════════════════════════════════════════════════════

def _w2_count_executor_builds(monkeypatch) -> list:
    from backend.commands.executor import CommandExecutor
    built: list = []
    original = CommandExecutor.__init__

    def counting(self, *a, **k):
        built.append(1)
        original(self, *a, **k)
    monkeypatch.setattr(CommandExecutor, "__init__", counting)
    return built


class TestS14EX82:
    """S14E-X82 -- `objection_v2.muster_expected_totals` (reached by
    `_tactical_objection`) built a `CommandExecutor()` per attack evaluation.

    Reproduced: two evaluations printed "Command Executor initialized" twice
    (it is the constructor's own banner -- the server log filled with it, one
    per quote, and each construction builds eleven sub-executors).

    The fix: a cached reader (`objection_v2._MUSTER_TOTALS_READER`, a dict
    keyed by the executor class -- the `order_quotes._MUSTER_READER` idiom,
    never a boolean lever); the totals are unchanged.
    """

    def test_two_evaluations_build_one_executor(self, _w2_world, monkeypatch):
        import backend.commands.objection_v2 as OV2
        OV2._MUSTER_TOTALS_READER.clear()
        built = _w2_count_executor_builds(monkeypatch)
        w = _w2_world
        ney, mack = w.get_marshal("Ney"), w.get_marshal("Mack")
        with _w2_quiet():
            first = OV2.muster_expected_totals(ney, mack, w)
            second = OV2.muster_expected_totals(ney, mack, w)
        assert first is not None and first == second
        assert len(built) == 1, built

    def test_the_banner_prints_once_not_per_evaluation(self, _w2_world):
        import backend.commands.objection_v2 as OV2
        OV2._MUSTER_TOTALS_READER.clear()
        w = _w2_world
        ney, mack = w.get_marshal("Ney"), w.get_marshal("Mack")
        sink = io.StringIO()
        with contextlib.redirect_stdout(sink):
            for _ in range(3):
                OV2.muster_expected_totals(ney, mack, w)
        assert sink.getvalue().count("Command Executor initialized") <= 1

    def test_the_tactical_objection_path_builds_none_once_warm(self, _w2_world, monkeypatch):
        """Reached by `_tactical_objection` (the player's attack quote): warm
        the reader, then five quotes build no executor."""
        from backend.commands.order_quotes import attack_quote
        w = _w2_world
        ney, mack = w.get_marshal("Ney"), w.get_marshal("Mack")
        with _w2_quiet():
            attack_quote(w, ney, mack)
        built = _w2_count_executor_builds(monkeypatch)
        with _w2_quiet():
            for _ in range(5):
                attack_quote(w, ney, mack)
        assert built == [], built

    def test_the_totals_are_the_previews_own(self, _w2_world):
        """Unchanged: (our committed, theirs) -- the very preview the what-if
        prints -- and a pure read (the hint latch is put back)."""
        import backend.commands.objection_v2 as OV2
        from backend.commands.executor import CommandExecutor
        w = _w2_world
        ney, mack = w.get_marshal("Ney"), w.get_marshal("Mack")
        with _w2_quiet():
            fresh = CommandExecutor()._combat._build_muster_preview(
                ney, mack, w, {"world": w}, with_spread=False)
        w.muster_hint_shown = False         # (the direct preview latched it; the read must not)
        with _w2_quiet():
            totals = OV2.muster_expected_totals(ney, mack, w)
        assert totals == (int(fresh["attacker"]["committed_strength"]),
                          int(fresh["target"]["committed_strength"]))
        assert w.muster_hint_shown is False

    def test_the_cache_is_keyed_by_the_class_and_is_no_lever(self):
        import backend.commands.objection_v2 as OV2
        assert isinstance(OV2._MUSTER_TOTALS_READER, dict)
        src = (Path(__file__).resolve().parents[1] / "backend" / "commands"
               / "objection_v2.py").read_text(encoding="utf-8")
        assert re.search(r"^_MUSTER_TOTALS_READER: dict = \{\}", src, re.MULTILINE)
        assert not re.search(r"^[A-Z_]*MUSTER[A-Z_]* = (True|False)", src, re.MULTILINE)
        # a swapped executor class does not inherit the old class's reader
        import backend.commands.executor as EX
        OV2._MUSTER_TOTALS_READER.clear()
        with _w2_quiet():
            first = OV2._muster_totals_reader()
        assert OV2._MUSTER_TOTALS_READER == {EX.CommandExecutor: first}
        assert OV2._muster_totals_reader() is first


# ══════════════════════════════════════════════════════════════════════════
# S14E-X72 -- "how do I find Mack / take Vienna / stop Ney" dumps the manual
# ══════════════════════════════════════════════════════════════════════════

def _w2_names(world) -> dict:
    """The rosters the live chain hands the desk."""
    from backend.ai.llm_client import _askable_enemy_names
    return {"marshals": [m.name for m in world.get_player_marshals()],
            "enemies": list(_askable_enemy_names({"world": world}) or []),
            "regions": list(world.regions),
            "nations": list(world.get_active_nations())}


class TestS14EX72:
    """S14E-X72 -- "how do I find Mack", "how do I take Vienna", "how do I stop
    Ney" opened "how do I", were filed as grammar, named no section the help
    table knew, and printed the WHOLE 22,573-character manual.

    Reproduced (the shipped 1805 board, the real endpoint, the keyless
    parser): each of the three returned success True with "COMMAND REFERENCE"
    at its head and 22,573 characters -- the first wave left the bare verbs
    "find", "take" and "stop" out of the help table because they would steal
    "find peace", "take a loan" and "stop the war".

    The fix anchors on the OBJECT, not the verb: three desk kinds
    (`how_find`, `how_take`, `how_stop` in `question_desk._WIDE_KINDS`) claim
    the line only when the thing after the verb RESOLVES -- a marshal, a
    province, a marshal of ours -- so a peace, a loan and a war are not
    theirs.  Each answers in a few lines: the scout (or the where-answer, for
    a man in sight), the march-and-attack with the free preview, the cancel.
    """

    def _w2_reply(self, client, line):
        reply = _w2_say(client, line)
        text = str(reply.get("message") or "")
        assert reply.get("success") is True, (line, text[:200])
        assert _W2_MANUAL not in text, (line, text[:120])
        assert len(text) < 900, (line, len(text))
        return text

    # ── find ──────────────────────────────────────────────────────────────
    @pytest.mark.parametrize("line", (
        "how do I find Mack", "how do I find Mack?", "how can I find Mack?",
        "how would we find Mack", "how do I locate Mack?", "how do I track down Mack?",
        "how do I hunt down Mack", "Berthier, how do I find Mack?"))
    def test_find_an_enemy_marshal_is_one_answer_naming_him(self, line, _w2_client):
        text = self._w2_reply(_w2_client, line)
        assert "Mack" in text, text
        assert "scout" in text.lower(), text

    def test_find_names_the_last_word_we_hold_fog_honestly(self, _w2_client, _w2_world):
        """The where-answer is the fog-honest one (`_answer_enemy`): nothing the
        player could not already ask 'where is Mack' and be told."""
        text = self._w2_reply(_w2_client, "how do I find Mack")
        where = str(_w2_say(_w2_client, "where is Mack").get("message") or "")
        assert where in text, (where, text)

    def test_find_a_man_in_sight_is_offered_the_closer_look_and_one_out_of_sight_the_search(
            self, _w2_client, _w2_world):
        from backend.models.intel import PARTIAL
        w = _w2_world
        mack = w.get_marshal("Mack")
        assert w.get_region_intel(mack.location).visibility_at_least(PARTIAL)
        in_sight = self._w2_reply(_w2_client, "how do I find Mack")
        assert "reported at Swabia" in in_sight, in_sight
        assert "To see more of him" in in_sight and ", scout Swabia'" in in_sight, in_sight
        # march him out of sight: a province the player has no eyes on
        dark = next(n for n in w.regions
                    if n != mack.location
                    and not w.get_region_intel(n).visibility_at_least(PARTIAL))
        mack.location = dark
        hidden = self._w2_reply(_w2_client, "how do I find Mack")
        assert "Mack" in hidden and "To look for him" in hidden, hidden
        assert dark not in hidden, hidden           # the real position is not leaked

    def test_find_one_of_ours_is_the_where_answer(self, _w2_client, _w2_world):
        text = self._w2_reply(_w2_client, "how do I find Ney")
        assert "Ney" in text and _w2_world.get_marshal("Ney").location in text, text

    # ── take ──────────────────────────────────────────────────────────────
    @pytest.mark.parametrize("line", (
        "how do I take Vienna", "how do I take Vienna?", "how can I take Vienna?",
        "how do we capture Vienna", "how do I conquer Vienna?", "how do I seize Vienna",
        "how would I storm Vienna"))
    def test_take_a_province_is_the_march_and_the_attack(self, line, _w2_client, _w2_world):
        from backend.commands.strategic import nearest_lawful_marcher
        marshal, _road, _refusal = nearest_lawful_marcher(_w2_world, "Vienna")
        text = self._w2_reply(_w2_client, line)
        assert f"'{marshal.name}, march to Vienna then attack'" in text, text
        assert f"'{marshal.name}, attack Vienna'" in text, text
        # the free preview, the very sentence the TODAY list carries
        assert f"Ask 'what if {marshal.name} attacks Vienna' first" in text, text

    def test_the_quoted_orders_are_orders_the_game_takes(self, _w2_client, _w2_world):
        from backend.commands.strategic import nearest_lawful_marcher
        marshal, _road, _refusal = nearest_lawful_marcher(_w2_world, "Vienna")
        self._w2_reply(_w2_client, "how do I take Vienna")
        preview = _w2_say(_w2_client, f"what if {marshal.name} attacks Vienna")
        assert preview.get("success") is True, preview.get("message")
        march = _w2_say(_w2_client, f"{marshal.name}, march to Vienna then attack")
        assert march.get("success") is True, march.get("message")

    def test_take_our_own_province_is_said_already_ours(self, _w2_client):
        text = self._w2_reply(_w2_client, "how do I take Paris")
        assert text == "Paris is already ours, Sire."

    def test_take_a_province_of_a_court_at_peace_is_the_cabinets(self, _w2_client, _w2_world):
        w = _w2_world
        peace = next(r for r in w.regions.values()
                     if r.controller not in (None, "", w.player_nation)
                     and not w.is_at_war(w.player_nation, r.controller))
        text = self._w2_reply(_w2_client, f"how do I take {peace.name}")
        assert "at peace" in text and "press F1" in text, text
        assert "march to" not in text, text

    # ── stop ──────────────────────────────────────────────────────────────
    @pytest.mark.parametrize("line", (
        "how do I stop Ney", "how do I stop Ney?", "how can I halt Ney?",
        "how do I cancel Ney's march", "how do I abort Ney's order",
        "how would we call off Ney"))
    def test_stop_a_marshal_is_the_cancel_line(self, line, _w2_client):
        text = self._w2_reply(_w2_client, line)
        assert "'Ney, cancel'" in text, text

    def test_stop_a_marshal_under_a_standing_order_names_the_order(self, _w2_client, _w2_world):
        _w2_say(_w2_client, "Ney, march to Lorraine")
        assert _w2_world.get_marshal("Ney").strategic_order is not None
        text = self._w2_reply(_w2_client, "how do I stop Ney")
        assert "standing order to march to Lorraine" in text, text
        assert "'Ney, cancel' recalls him (1 AP)" in text, text
        # shown == applied: the sentence it quotes runs, and ends the order
        cancel = _w2_say(_w2_client, "Ney, cancel")
        assert cancel.get("success") is True, cancel.get("message")
        assert _w2_world.get_marshal("Ney").strategic_order is None

    def test_stop_a_marshal_with_no_order_says_there_is_nothing_to_recall(self, _w2_client):
        text = self._w2_reply(_w2_client, "how do I stop Ney")
        assert "no standing march or hold" in text and "'Ney, cancel'" in text, text

    # ── the lines the verbs must not steal ────────────────────────────────
    def test_find_peace_keeps_its_section(self, _w2_client):
        reply = _w2_say(_w2_client, "how do I find peace")
        text = str(reply.get("message") or "")
        assert text.startswith("DIPLOMACY - THE CABINET IS THE DOOR"), text[:80]
        assert _W2_MANUAL not in text and len(text) < 5000

    def test_take_a_loan_is_not_the_takers(self, _w2_client, _w2_world):
        from backend.ai.question_desk import classify_board_question
        assert classify_board_question("how do I take a loan", **_w2_names(_w2_world)) is None
        # S14E-D17 / S14E-X142: flipped - its answer was the whole reference
        # (reported, not claimed); it is the SECTION INDEX now.
        text = str(_w2_say(_w2_client, "how do I take a loan").get("message") or "")
        assert _W2_MANUAL not in text and text.startswith("Which part, Sire?")
        assert "march to" not in text

    def test_stop_the_war_keeps_its_answer(self, _w2_client, _w2_world):
        from backend.ai.question_desk import classify_board_question
        assert classify_board_question("how do I stop the war", **_w2_names(_w2_world)) is None
        text = str(_w2_say(_w2_client, "how do I stop the war").get("message") or "")
        assert text.startswith("An astute question, Sire."), text[:80]

    @pytest.mark.parametrize("line", (
        "how do I find peace", "how do I find the way", "how do I take a loan",
        "how do I take command", "how do I stop the war", "how do I stop the enemy",
        "how do I take Zorglub", "how do I find Zorglub", "how do I stop Zorglub",
        "how do I stop Mack", "how do I take Mack"))
    def test_an_object_that_is_not_a_province_or_a_marshal_is_not_claimed(
            self, line, _w2_world):
        from backend.ai.question_desk import classify_board_question
        found = classify_board_question(line, **_w2_names(_w2_world))
        assert found is None or found["kind"] not in ("how_take", "how_find", "how_stop"), found

    def test_the_classified_kinds_name_their_subject(self, _w2_world):
        from backend.ai.question_desk import classify_board_question
        names = _w2_names(_w2_world)
        take = classify_board_question("how do I take Vienna", **names)
        assert (take["kind"], take["subject"], take["subject_type"]) == (
            "how_take", "Vienna", "region")
        find = classify_board_question("how do I find Mack", **names)
        assert (find["kind"], find["subject"], find["subject_type"]) == (
            "how_find", "Mack", "enemy")
        stop = classify_board_question("how do I stop Ney", **names)
        assert (stop["kind"], stop["subject"], stop["subject_type"]) == (
            "how_stop", "Ney", "marshal")

    def test_the_older_kinds_keep_their_phrasings(self, _w2_world):
        from backend.ai.question_desk import classify_board_question, classify_question
        names = _w2_names(_w2_world)
        assert classify_board_question("how do I get to Vienna", **names)["kind"] == "route"
        assert classify_board_question("can Ney reach Vienna", **names)["kind"] == "reach"
        assert classify_board_question("what if Ney attacks Mack", **names)["kind"] in (
            "what_if", "what_if_named")
        assert classify_question("where is Mack", marshals=names["marshals"],
                                 enemies=names["enemies"], regions=names["regions"])["kind"] == "where"

    def test_a_pure_read_costs_nothing(self, _w2_client, _w2_world):
        w = _w2_world
        before = (int(w.actions_remaining), int(w.admin_actions_remaining), w.current_turn)
        for line in ("how do I find Mack", "how do I take Vienna", "how do I stop Ney"):
            self._w2_reply(_w2_client, line)
        assert (int(w.actions_remaining), int(w.admin_actions_remaining), w.current_turn) == before


