class TestS14EX139:
    """S14E-X139 -- "stop Ney" / "abort Ney" (the verb FIRST) parse Unknown.

    Found sweeping S14E-X73's class: the manual teaches "cancel Ney" and
    "halt Ney" and both run; "stop Ney" and "abort Ney" -- the commonest way a
    player says it, and the very sentence S14E-X72's "how do I stop Ney" answer
    teaches the cancel for -- answered "Unknown action: unknown".

    Reproduced (the keyless parser on the 1805 board): "stop Ney" ->
    success False; "abort Ney" -> success False.

    The fix: the same `_bare_cancel_without_comma` reads the verb-first order
    when the WHOLE rest of the line is a marshal of ours.
    """

    @pytest.mark.parametrize("line", ("stop Ney", "abort Ney", "Stop Ney.", "stop Marshal Ney",
                                      "cancel Ney", "halt Ney", "stop ney"))
    def test_the_verb_first_order_is_the_cancel(self, line, _w2_board):
        result = _w2_parse(_w2_board, line)
        command = result.get("command") or {}
        assert result.get("success") is True, (line, result.get("message"))
        assert command.get("action") == "cancel" and command.get("marshal") == "Ney", line

    # S14E-X143 (the third wave) FLIPS "stop the army": the collective recall
    # (tests/test_s14f_p2_w10.py::TestS14EX143).
    @pytest.mark.parametrize("line", ("stop Zorglub", "stop Mack",
                                      "stop the war", "abort the plan"))
    def test_only_a_marshal_of_ours_after_the_verb_is_the_cancel(self, line, _w2_board):
        command = _w2_parse(_w2_board, line).get("command") or {}
        assert command.get("action") != "cancel", (line, command)

    def test_the_older_readings_of_stop_are_kept(self, _w2_board):
        for line, action in (("stop Davout's pension", "revoke_pension"),
                             ("Ney, stop attacking", "cancel"), ("stop", "cancel")):
            command = _w2_parse(_w2_board, line).get("command") or {}
            assert command.get("action") == action, (line, command)

    def test_the_sentence_the_stop_answer_teaches_runs(self, _w2_client):
        text = str(_w2_say(_w2_client, "how do I stop Ney").get("message") or "")
        assert "'Ney, cancel'" in text
        assert _w2_say(_w2_client, "stop Ney").get("success") is True


class TestS14EX140:
    """S14E-X140 -- the desk's what-if answers built a whole `CommandExecutor`
    (eleven sub-executors and the banner) per answer -- S14E-X82's class.

    Found sweeping XC5: `question_desk._answer_what_if`, `_muster_lines` and
    the province what-if each did `CommandExecutor()._combat`.  Reproduced:
    three "what if Ney attacks Mack" questions printed the banner three times.

    The fix: `question_desk._combat_reader()` -- the very cached reader the
    objection path uses -- so a warm desk builds none; the answers are
    byte-identical.
    """

    def test_the_what_if_builds_no_executor_once_warm(self, _w2_world, monkeypatch):
        from backend.ai.question_desk import answer_board_question
        question = {"kind": "what_if", "subject": "Mack", "subject_type": "enemy"}
        with _w2_quiet():
            first = answer_board_question(_w2_world, question)
        built = _w2_count_executor_builds(monkeypatch)
        _w2_world.muster_hint_shown = False     # (the once-per-campaign hint latch is world state)
        with _w2_quiet():
            second = answer_board_question(_w2_world, question)
            third = answer_board_question(_w2_world, dict(question, marshal="Ney"))
        assert built == [], built
        assert first == second and "MUSTER" in first and third

    def test_the_answer_is_what_a_fresh_executor_prints(self, _w2_world):
        from backend.ai.question_desk import _muster_lines
        from backend.commands.executor import CommandExecutor
        w = _w2_world
        ney, mack = w.get_marshal("Ney"), w.get_marshal("Mack")
        with _w2_quiet():
            cached = _muster_lines(w, ney, mack)
            w.muster_hint_shown = False
            fresh_combat = CommandExecutor()._combat
            preview = fresh_combat._build_muster_preview(ney, mack, w, {"world": w})
            fresh = fresh_combat._format_muster_lines(preview)
        assert cached == fresh

    def test_no_desk_site_but_the_armistice_probe_builds_an_executor(self):
        src = (Path(__file__).resolve().parents[1] / "backend" / "ai"
               / "question_desk.py").read_text(encoding="utf-8")
        assert src.count("CommandExecutor()") == 1
        assert "CommandExecutor()._make_diplomatic_error" in src

