_W3_ROOT = Path(__file__).resolve().parents[1]
_W3_SCENARIO = (_W3_ROOT / "godot-client" / "project-sovereign" / "assets" / "maps"
                / "europe_1805.json")
_W3_SCRIPTS = _W3_ROOT / "godot-client" / "project-sovereign" / "scripts"


def _w3_quiet():
    return contextlib.redirect_stdout(io.StringIO())


def _w3_src(rel: str) -> str:
    return (_W3_ROOT / rel).read_text(encoding="utf-8")


@pytest.fixture(scope="module")
def _w3_boot():
    from backend.models.world_state import WorldState
    with _w3_quiet():
        return WorldState.from_scenario(str(_W3_SCENARIO))


@pytest.fixture
def _w3_w(_w3_boot):
    """The shipped board, a fresh copy per test."""
    from backend.models.world_state import WorldState
    with _w3_quiet():
        return WorldState.from_dict(json.loads(json.dumps(_w3_boot.to_dict(), default=str)))


def _w3_floats(obj, path: str = ""):
    if isinstance(obj, float):
        yield path, obj
    elif isinstance(obj, dict):
        for key, value in obj.items():
            yield from _w3_floats(value, f"{path}/{key}")
    elif isinstance(obj, (list, tuple)):
        for index, value in enumerate(obj):
            yield from _w3_floats(value, f"{path}[{index}]")


def _w3_fight(w, **points):
    """Give nations battle contribution in war_1 (the material the reactions
    read): `_w3_fight(w, France=200, Bavaria=200)`."""
    from backend.game_logic.war_contribution import open_episode
    for nation, pts in points.items():
        episode = open_episode(w, "war_1", nation, joined_turn=0, war_sequence=1)
        episode["battle"] = pts
        episode["total"] = pts


def _w3_rel(w, a, b) -> int:
    return int(w.nation_relations.get(w._make_diplo_key(a, b), 0) or 0)


def _w3_set_state(w, a, b, state):
    w.diplomatic_states[w._make_diplo_key(a, b)] = state
    w.invalidate_bloc_members_cache()


@contextlib.contextmanager
def _w3_client(w):
    """The player's road: /command on a swapped world (three globals, restored)."""
    import backend.main as M
    from backend.commands.parser import CommandParser
    from fastapi.testclient import TestClient
    saved = (M.game_state["world"], M.world, M.parser)
    M.game_state["world"] = w
    M.world = w
    M.parser = CommandParser(use_real_llm=False)
    try:
        yield TestClient(M.app)
    finally:
        M.game_state["world"], M.world, M.parser = saved


def _w3_say(client, text: str) -> dict:
    with contextlib.redirect_stdout(io.StringIO()):
        return client.post("/command", json={"command": text}).json()


def _w3_is_quote(reply: dict) -> bool:
    return (reply.get("state") == "awaiting_clarification"
            and reply.get("type") == "clarification"
            and bool(reply.get("options")))


def _w3_after(message: str) -> int:
    m = re.search(r"would hold ([\d,]+) after", message)
    assert m, message
    return int(m.group(1).replace(",", ""))


