# S14E-X94 - the Saxony protection pledge names its effect
# ══════════════════════════════════════════════════════════════════════════

class TestS14EX94:
    """Reproduced on the shipped board: Saxony's non-aggression / alliance
    letters carry the `protection_promised` clause (`ai_diplomacy` line "Saxony
    always offers protection clause") and the popup line read the bare
    "Clause: Protection guarantee" - on every surface (the letter, the dialogue
    text, the player's draft, the ledger) naming no effect. The code gives it
    exactly one: the acceptance formula's special-desire arm
    (`diplomacy.SPECIAL_BONUSES`) adds +10 to Saxony's court when the clause is
    in a letter put TO her; no ratifier writes it and it binds no army."""

    def test_a_the_saxon_letter_says_the_pledge_is_a_word_only(self, _w3_w):
        from backend.game_logic.ai_diplomacy import _build_proposal_terms, build_ai_proposal_dialogue
        terms = _build_proposal_terms("Saxony", "non_aggression", 0, _w3_w)
        assert "protection_promised" in terms["clauses"], terms
        with _w3_quiet():
            letter = build_ai_proposal_dialogue({
                "source": "Saxony", "terms": terms, "proposal_type": "non_aggression",
                "talleyrand_assessment": "", "decision_reason": "friendly"}, _w3_w)
        line = next(c for c in letter["popup_payload"]["clauses"]
                    if c.startswith("Clause: Protection guarantee"))
        assert line != "Clause: Protection guarantee"          # the reproduction: the bare line
        assert line == ("Clause: Protection guarantee - Saxony pledges her protection; "
                        "a word only: it binds no army and weighs with no court"), line

    def test_b_put_to_saxony_the_figure_is_the_acceptance_bonus(self, _w3_w):
        """Shown == applied: the sentence's +10 is the component the scorer adds."""
        from backend.display_names import build_proposal_popup_clauses
        from backend.game_logic.diplomacy import SPECIAL_BONUSES, calculate_acceptance
        proposal = {"type": "alliance", "proposer_nation": "France", "target_nation": "Saxony",
                    "sweeteners": [], "demands": [], "clauses": ["protection_promised"]}
        lines = build_proposal_popup_clauses(proposal, viewer="France", proposer="France",
                                             target="Saxony")
        pledge = next(ln for ln in lines if ln.startswith("Clause: Protection guarantee"))
        figure = SPECIAL_BONUSES["Saxony"]["protection_promised"]
        assert pledge == ("Clause: Protection guarantee - You pledge your protection; "
                          f"it weighs +{figure} with Saxony's court and binds no army"), pledge
        with_clause = calculate_acceptance(proposal, _w3_w)["components"]["special_desire_bonus"]
        without = calculate_acceptance(dict(proposal, clauses=[]), _w3_w)["components"]["special_desire_bonus"]
        assert (with_clause, without) == (figure, 0)

    def test_c_the_figure_follows_the_table_not_the_prose(self, monkeypatch):
        from backend.display_names import clause_effect_words
        from backend.game_logic import diplomacy as D
        monkeypatch.setitem(D.SPECIAL_BONUSES["Saxony"], "protection_promised", 14)
        assert "+14 with Saxony's court" in clause_effect_words(
            "protection_promised", "alliance", proposer="France", target="Saxony")
        # no court holds the desire: no figure is claimed
        said = clause_effect_words("protection_promised", "alliance", proposer="France",
                                   target="Prussia")
        assert "+" not in said and "weighs with no court" in said

    def test_d_it_binds_no_army(self, _w3_w):
        """The ratifier mints no guarantee and moves no corps for the clause."""
        w = _w3_w
        before = json.dumps(w.diplomatic_guarantees, sort_keys=True, default=str)
        corps = {n: m.location for n, m in w.marshals.items()}
        with _w3_quiet():
            w._ratify_treaty({"type": "non_aggression", "proposer_nation": "Saxony",
                              "target_nation": "France", "sweeteners": [], "demands": [],
                              "clauses": ["protection_promised"]})
        assert json.dumps(w.diplomatic_guarantees, sort_keys=True, default=str) == before
        assert {n: m.location for n, m in w.marshals.items()} == corps

    def test_e_the_draft_the_dialogue_and_the_ledger_say_it_too(self, _w3_w):
        from backend.display_names import format_proposal_summary, format_terms_for_display
        from backend.game_logic.diplomatic_ledger import build_diplomatic_ledger
        draft = format_terms_for_display(
            {"type": "alliance", "proposer_nation": "France", "clauses": ["protection_promised"],
             "sweeteners": [], "demands": []}, "alliance", "Saxony")
        line = next(ln for ln in draft if ln.startswith("Protection guarantee"))
        assert line == ("Protection guarantee - France pledges her protection; it weighs +10 "
                        "with Saxony's court and binds no army"), line
        text = format_proposal_summary(
            {"type": "non_aggression", "proposer_nation": "Saxony", "target_nation": "France",
             "clauses": ["protection_promised"], "sweeteners": [], "demands": []})
        assert "Saxony pledges her protection; a word only" in text, text
        w = _w3_w
        key = w._make_diplo_key("France", "Saxony")
        w.active_treaties[key] = {
            "type": "alliance", "nations": ["France", "Saxony"], "turn_signed": 0,
            "clauses": [{"type": "protection_promised", "amount": 1, "from": "France", "to": "Saxony"}]}
        with _w3_quiet():
            treaties = build_diplomatic_ledger(w)["treaties"]
        row = next(t for t in treaties if {t["nation_a"], t["nation_b"]} == {"France", "Saxony"})
        assert row["clauses"] == ["Military protection (France -> Saxony) - a pledge only; it binds no army"]

    def test_f_the_other_clauses_keep_their_lines(self):
        from backend.display_names import CLAUSE_TYPE_DISPLAY, clause_effect_words
        explained = [k for k in CLAUSE_TYPE_DISPLAY if clause_effect_words(k)]
        assert explained == ["open_borders", "protection_promised"], explained


# ══════════════════════════════════════════════════════════════════════════
# S14E-X95 - the pact letters say what their state yields and what breaking costs
# ══════════════════════════════════════════════════════════════════════════

_W3_BREAK_RE = re.compile(
    r"up to \+(\d+) gold a turn in trade; breaking it costs (\d+) DP, -(\d+) relation with "
    r"the other signer and -(\d+) with every other court")


class TestS14EX95:
    """Reproduced: `build_pending_envoy_popup_from_terms` for a non-aggression,
    defensive-alliance or alliance letter carried `proposal_type_summary` =
    the bare table text ("Non-Aggression Pact (agree not to attack)") and no
    line of the trade the state yields or the price of breaking it - the
    player signed a treaty that pays 150 or 200 a turn and costs 1 DP and
    -30 / -40 relation to leave, none of it said."""

    def _letter(self, w, ptype):
        from backend.game_logic.mailbox_payloads import build_pending_envoy_popup_from_terms
        with _w3_quiet():
            return build_pending_envoy_popup_from_terms(
                w, nation="Saxony", terms={"type": ptype, "sweeteners": [], "demands": [],
                                           "clauses": []}, label_type=ptype)

    @pytest.mark.parametrize("ptype,state", [("non_aggression", "NON_AGGRESSION"),
                                              ("defensive_alliance", "DEFENSIVE_ALLIANCE"),
                                              ("alliance", "ALLIANCE")])
    def test_a_the_letter_names_the_trade_and_the_break(self, _w3_w, ptype, state):
        from backend.display_names import proposal_summary_display_name
        from backend.game_logic.diplomacy import (
            TREATY_BREAK_DP_COST, TREATY_BREAK_RELATION_ALL, trade_for_state,
            treaty_break_partner_penalty)
        summary = self._letter(_w3_w, ptype)["proposal_type_summary"]
        head = proposal_summary_display_name(ptype)
        assert summary.startswith(head + " - "), summary
        got = _W3_BREAK_RE.search(summary)
        assert got, summary
        assert tuple(int(x) for x in got.groups()) == (
            trade_for_state(state), TREATY_BREAK_DP_COST,
            treaty_break_partner_penalty(ptype), TREATY_BREAK_RELATION_ALL)

    @pytest.mark.parametrize("ptype,state,partner", [("non_aggression", "NON_AGGRESSION", 30),
                                                      ("defensive_alliance", "DEFENSIVE_ALLIANCE", 40),
                                                      ("alliance", "ALLIANCE", 40)])
    def test_b_shown_equals_applied_the_break_writes_the_quoted_price(self, _w3_w, ptype, state, partner):
        from backend.game_logic.diplomacy import break_treaty
        w = _w3_w
        summary = self._letter(w, ptype)["proposal_type_summary"]
        dp_said, partner_said, others_said = (int(x) for x in _W3_BREAK_RE.search(summary).groups()[1:])
        assert partner_said == partner
        key = w._make_diplo_key("France", "Saxony")
        _w3_set_state(w, "France", "Saxony", state)
        w.active_treaties[key] = {"type": ptype, "nations": ["France", "Saxony"],
                                  "clauses": [], "turn_signed": 0}
        w.diplomatic_points = 5
        before_partner = _w3_rel(w, "France", "Saxony")
        before_other = _w3_rel(w, "France", "Prussia")
        with _w3_quiet():
            out = break_treaty(key, "France", w)
        assert out["success"], out
        assert 5 - w.diplomatic_points == dp_said
        assert before_partner - _w3_rel(w, "France", "Saxony") == partner_said
        assert before_other - _w3_rel(w, "France", "Prussia") == others_said

    def test_c_the_peace_the_truce_the_counter_and_open_borders_are_unchanged(self):
        from backend.game_logic.mailbox_payloads import _incoming_type_summary
        for ptype in ("peace", "armistice", "armistice_losing", "armistice_winning"):
            assert _incoming_type_summary({"type": ptype}) == ""
        assert _incoming_type_summary({"type": "alliance"}, is_counter_offer=True) == ""
        assert _incoming_type_summary({"type": "peace"}, label_type="harsh_peace") == ""
        # open borders: the break price alone (S14E-X169) - its trade rides the clause line
        assert _incoming_type_summary({"type": "open_borders"}) == (
            "Open Borders Agreement (free military passage) - breaking it costs 1 DP, "
            "-30 relation with the other signer and -10 with every other court")

    def test_d_the_figures_follow_the_constants(self, monkeypatch):
        from backend.display_names import treaty_state_effect_words
        from backend.game_logic import diplomacy as D
        monkeypatch.setitem(D.TRADE_INCOME, "ALLIANCE", 260)
        monkeypatch.setattr(D, "TREATY_BREAK_RELATION_ALL", 14)
        said = treaty_state_effect_words("alliance")
        assert "up to +260 gold a turn" in said and "-14 with every other court" in said
        monkeypatch.setitem(D.TRADE_INCOME, "NON_AGGRESSION", 0)      # EA-3's rule: no trade claim at 0
        assert "gold a turn" not in treaty_state_effect_words("non_aggression")

    def test_e_the_players_own_draft_says_it_too(self):
        """The XF3 sweep (S14E-X165): the outgoing pact draft is the same class."""
        from backend.display_names import format_terms_for_display
        lines = format_terms_for_display({"type": "non_aggression", "clauses": [], "sweeteners": [],
                                          "demands": []}, "non_aggression", "Saxony")
        assert _W3_BREAK_RE.search(lines[0]), lines[0]
        peace = format_terms_for_display({"type": "peace", "clauses": [], "sweeteners": [],
                                          "demands": []}, "peace", "Saxony")
        assert peace[0] == "Peace Treaty (end state of war)"


# ══════════════════════════════════════════════════════════════════════════
# S14E-X116 - the bilateral road thanks the ally it names
