_W3_TYROL = [{"type": "territory_cede", "from": "Austria", "to": "Bavaria", "region": "Tyrol"}]


class TestS14EX116:
    """Reproduced on the shipped board with Bavaria a seat at the war (200
    points): `separate_peace_words(w, "France", "Austria", <Tyrol to Bavaria>)`
    read "Bavaria's war with Austria ends in this instrument; she is named for
    Tyrol." - while the table's review says "Bavaria takes Tyrol by it and
    thanks us (+10 relation)." and the bilateral ratifier writes that +10."""

    def test_a_the_sentence_carries_the_figure(self, _w3_w):
        from backend.game_logic import diplomacy as D
        w = _w3_w
        _w3_fight(w, France=200, Bavaria=200)
        words = D.separate_peace_words(w, "France", "Austria", _W3_TYROL)
        assert words["display"] == ("Bavaria's war with Austria ends in this instrument; "
                                    "she is named for Tyrol and thanks us (+10 relation).")
        assert words["thanks"] == {"Bavaria": 10} and words["shut_out"] == {}

    def test_b_shown_equals_applied(self, _w3_w):
        """The ratifier's gratitude write is the sentence's figure, and it is the
        table's own `gratitude_delta`."""
        from backend.game_logic import diplomacy as D
        from backend.game_logic.settlement_reactions import gratitude_delta
        w = _w3_w
        _w3_fight(w, France=200, Bavaria=200)
        shown = D.separate_peace_words(w, "France", "Austria", _W3_TYROL)["thanks"]["Bavaria"]
        before = _w3_rel(w, "France", "Bavaria")
        with _w3_quiet():
            w._ratify_treaty({
                "type": "peace", "proposer_nation": "France", "target_nation": "Austria",
                "sweeteners": [], "clauses": [],
                "demands": [{"type": "territory_cede", "regions": ["Tyrol"],
                             "from_nation": "Austria", "to_nation": "Bavaria"}]})
        assert w.regions["Tyrol"].controller == "Bavaria"
        assert _w3_rel(w, "France", "Bavaria") - before == shown == gratitude_delta("seat")

    def test_c_a_consult_is_thanked_for_less(self, _w3_w):
        from backend.game_logic import diplomacy as D
        w = _w3_w
        _w3_fight(w, France=200)                      # Bavaria at the war with no battle points
        words = D.separate_peace_words(w, "France", "Austria", _W3_TYROL)
        assert words["display"].endswith("she is named for Tyrol and thanks us (+5 relation).")

    def test_d_an_ally_named_for_nothing_and_a_no_standing_ally_say_no_thanks(self, _w3_w):
        from backend.game_logic import diplomacy as D
        w = _w3_w
        _w3_fight(w, France=200, Bavaria=200)
