# S14E-X114 - the Propose-Peace road's bond line names its control
# ══════════════════════════════════════════════════════════════════════════

class TestS14EX114:
    """Reproduced: with the league's bond on Austria the counsel's `table_alone`
    road ends "... 1,000 gold to her pays it (F1 → Austria → Outbid Britain's
    Bond)." (S14E-X33) while the `send_peace` road's bond line ended at the sum
    - the same price, the control unnamed."""

    def _bonded(self, w):
        from backend.game_logic import bond as B
        w.nation_gold["Britain"] = 5000
        with _w3_quiet():
            minted = B.mint_bond(w, payer="Britain", member="Austria", enemy="France")
        assert minted["success"], minted

    def test_a_the_bilateral_line_names_the_row_that_stages_it(self, _w3_w):
        from backend.game_logic import counsel as K
        w = _w3_w
        self._bonded(w)
        with _w3_quiet():
            road = K._bilateral_road(w, "France", "Austria", "peace", "send_peace")
        line = road["bond_line"]
        assert line.startswith("Britain's bond costs her"), line
        assert line.endswith("(F1 → Austria → Outbid Britain's Bond)."), line
        assert line in road["trade"]

    def test_b_it_is_the_table_roads_own_path(self, _w3_w):
        from backend.game_logic import counsel as K
        w = _w3_w
        self._bonded(w)
        with _w3_quiet():
            table = K._table_road(w, "France", "Austria", alone=True)
            bilateral = K._bilateral_road(w, "France", "Austria", "peace", "send_peace")
        assert table["bond_line"].endswith("(F1 → Austria → Outbid Britain's Bond).")
        assert bilateral["bond_line"].split(" (F1")[1] == table["bond_line"].split(" (F1")[1]

    def test_c_where_the_table_cannot_be_named_the_court_page_is(self, _w3_w, monkeypatch):
        from backend.game_logic import counsel as K
        w = _w3_w
        self._bonded(w)
        monkeypatch.setattr(K, "_outbid_path", lambda *a, **k: "")
        with _w3_quiet():
            road = K._bilateral_road(w, "France", "Austria", "peace", "send_peace")
        assert road["bond_line"].endswith("(F1 → Austria).")

    def test_d_no_bond_no_line(self, _w3_w):
        from backend.game_logic import counsel as K
        with _w3_quiet():
            road = K._bilateral_road(_w3_w, "France", "Austria", "peace", "send_peace")
        assert road["bond_line"] == "" and "(F1" not in road["trade"]

    def test_e_the_shared_war_is_one_or_none(self, _w3_w):
        from backend.game_logic import counsel as K
        w = _w3_w
        assert K._shared_war_id(w, "France", "Austria") == "war_1"
        assert K._shared_war_id(w, "France", "Prussia") == ""       # no war between them


