# S14E-X99 - the dialogue context's war score is the live one
# ══════════════════════════════════════════════════════════════════════════

class TestS14EX99:
    """Reproduced: the stored end-turn score (Austria|France raw 30, France
    sees -30) rode `context["war_score"]` of `generate_dialogue` and of
    `generate_feasibility_dialogue` while the preview's own read is the live
    `calculate_war_score` (-5 with Berry held by Austria): the context
    contradicted the popup it travelled with."""

    def _world(self, w):
        key = w._make_diplo_key("France", "Austria")
        w.war_scores[key] = 30 if key.split("|")[0] == "Austria" else -30
        w.regions["Berry"].controller = "Austria"
        return w

    def test_a_the_stored_and_the_live_score_differ_on_this_board(self, _w3_w):
        from backend.game_logic.diplomacy import get_war_score_for, live_war_score_for
        w = self._world(_w3_w)
        assert get_war_score_for(w, "France", "Austria") == -30
        assert live_war_score_for(w, "France", "Austria") != -30

    def test_b_the_dialogue_context_is_live(self, _w3_w):
        from backend.game_logic.diplomacy import build_war_context_snapshot, live_war_score_for
        from backend.game_logic.diplomatic_dialogue import generate_dialogue
        w = self._world(_w3_w)
        live = live_war_score_for(w, "France", "Austria")
        with _w3_quiet():
            dialogue = generate_dialogue(
                "greeting", {"action": "propose_peace", "target_nation": "Austria"}, w)
            snapshot = build_war_context_snapshot(w, "France", "Austria", "peace")
        assert dialogue["context"]["war_score"] == live == snapshot["war_score"]

    def test_c_the_feasibility_context_is_live(self, _w3_w):
        from backend.game_logic.diplomacy import live_war_score_for
        from backend.game_logic.diplomatic_dialogue import generate_feasibility_dialogue
        w = self._world(_w3_w)
        with _w3_quiet():
            dialogue = generate_feasibility_dialogue(
                {"target_nation": "Austria", "proposal_type": "peace"}, w)
        assert dialogue["context"]["war_score"] == live_war_score_for(w, "France", "Austria")

    def test_d_the_context_is_a_whole_number(self, _w3_w):
        from backend.game_logic.diplomatic_dialogue import generate_dialogue
        w = self._world(_w3_w)
        with _w3_quiet():
            dialogue = generate_dialogue(
                "greeting", {"action": "propose_peace", "target_nation": "Austria"}, w)
        assert isinstance(dialogue["context"]["war_score"], int)


# ══════════════════════════════════════════════════════════════════════════
# S14E-X100 - no unread float on the wire (Golden Rule 2)
# ══════════════════════════════════════════════════════════════════════════

class TestS14EX100:
    """Reproduced on the shipped board: every response carried ten floats under
    `active_wars/wars[0]/contribution_share[i]/(material_share|support_share)`
    (0..1, read as a percent by one client line), `parse_confidence` rode a
    float on a live parse, and the Diplomatic Ledger's payload carried four:
    each treaty row's `harshness` (read by nothing) and the Balance of Europe /
    the France mirror's `hegemon_share` (read as `float * 100`). All whole
    percents now; the two client readers are adjusted in the same change."""

    def test_a_a_base_response_carries_no_float(self, _w3_w):
        import backend.main as M
        w = _w3_w
        _w3_fight(w, France=300, Bavaria=100)
        saved = M.world
        M.world = w
        try:
            with _w3_quiet():
                response = M.build_base_response(w, True, "x")
        finally:
            M.world = saved
        assert list(_w3_floats(response)) == []
        rows = response["active_wars"]["wars"][0]["contribution_share"]
        by_nation = {r["nation"]: r for r in rows}
        assert (by_nation["France"]["material_share_pct"], by_nation["Bavaria"]["material_share_pct"]) == (75, 25)
        assert all(isinstance(r["material_share_pct"], int) and isinstance(r["support_share_pct"], int)
                   for r in rows)
        assert not any("material_share" in r or "support_share" in r for r in rows)

    def test_b_the_shares_are_the_old_ones_in_percent(self, _w3_w):
        from backend.game_logic.settlement_presentation import build_contribution_share_rows
        from backend.game_logic.war_contribution import compute_standing_inputs
        w = _w3_w
        _w3_fight(w, France=300, Bavaria=100)
        rows = build_contribution_share_rows(w, "war_1")["rows"]
        for row in rows:
            inputs = compute_standing_inputs(w, "war_1", row["nation"], side=row["side"])
            assert row["material_share_pct"] == int(round(float(inputs["material_share"]) * 100))
            assert row["support_share_pct"] == int(round(float(inputs.get("support_share", 0.0)) * 100))
        # the order is the floats' order, not the percents' (a tie keeps the alphabet)
        assert [r["nation"] for r in rows][:2] == ["France", "Bavaria"]

    def test_c_the_standing_line_reads_the_percent(self):
        gd = _w3_src("godot-client/project-sovereign/scripts/utils.gd")
        assert 'float(row.get("material_share_pct", 0))' in gd
        assert 'row.get("material_share"' not in gd
        assert "* 100.0" not in gd.split("static func standing_lines", 1)[1].split("\nstatic func", 1)[0]

    def test_d_the_review_rows_carry_percents_too(self):
        from backend.game_logic.settlement_presentation import _enrich_ally_row
        row = _enrich_ally_row({"nation": "Saxony", "standing": "seat",
                                "material_share": 0.305, "support_share": 0.1})
        assert row["material_share_pct"] == 30 and row["support_share_pct"] == 10
        assert "material_share" not in row and "support_share" not in row
        assert "30% material share" in row["standing_phrase"]
        again = _enrich_ally_row(row)                    # idempotent on a built row
        assert again["material_share_pct"] == 30

    def test_e_parse_confidence_is_a_whole_percent(self):
        import backend.main as M
        M._PARSE_PROVENANCE.set(("anthropic", 0.62))
        try:
            response = M.build_base_response(M.world, True, "x")
        finally:
            M._PARSE_PROVENANCE.set(None)
        assert response["parse_confidence"] == 62 and isinstance(response["parse_confidence"], int)
        assert response["parse_mode"] == "anthropic"
        assert list(_w3_floats({"c": response["parse_confidence"]})) == []

    def test_f_an_unscored_parse_stays_none(self):
        import backend.main as M
        M._PARSE_PROVENANCE.set(("mock", None))
        try:
            response = M.build_base_response(M.world, True, "x")
        finally:
            M._PARSE_PROVENANCE.set(None)
        assert response["parse_confidence"] is None

    def test_g_a_real_parse_rides_an_int(self, _w3_w):
        w = _w3_w
        with _w3_client(w) as client:
            reply = _w3_say(client, "status")
        assert isinstance(reply.get("parse_confidence"), (int, type(None)))
        assert not isinstance(reply.get("parse_confidence"), float)

    def test_h_the_digest_keeps_its_mark(self):
        import tools.playtest_driver as pdriver
        from tests.test_fa_slice15b_the_instrument_sees_2026_09_06 import _Recorder
        rec = _Recorder()
        pdriver.Digest.command(rec, "Ney, attack Mack", {
            "success": True, "message": "ok", "parse_mode": "anthropic", "parse_confidence": 62})
