    def test_k_a_treaty_rows_harshness_is_a_whole_percent(self, _w3_w):
        from backend.game_logic.diplomatic_ledger import build_diplomatic_ledger
        from backend.game_logic.diplomatic_templates import get_treaty_harshness_for_consumer
        w = _w3_w
        key = w._make_diplo_key("France", "Prussia")
        treaty = {"type": "peace", "nations": ["France", "Prussia"], "turn_signed": 0,
                  "harshness": 0.37,
                  "clauses": [{"type": "gold_per_turn", "amount": 900, "from": "Prussia", "to": "France"},
                              {"type": "territory_cede", "amount": 1, "regions": ["Hanover"],
                               "from": "Prussia", "to": "France"}]}
