# ========== S14f part 2 - merged from test_s14f_p2_w4.py ==========

_W4_SCENARIO = (Path(__file__).resolve().parents[1] / "godot-client" / "project-sovereign"
            / "assets" / "maps" / "europe_1805.json")
_W4_ROOT = Path(__file__).resolve().parents[1]


@contextlib.contextmanager
def _w4_quiet():
    with contextlib.redirect_stdout(io.StringIO()):
        yield


@pytest.fixture(scope="module")
def _w4_boot():
    from backend.models.world_state import WorldState
    with _w4_quiet():
        return WorldState.from_scenario(str(_W4_SCENARIO))


@pytest.fixture
def _w4_w(_w4_boot):
    return _w4_copy(_w4_boot)


def _w4_copy(w):
    from backend.models.world_state import WorldState
    with _w4_quiet():
        return WorldState.from_dict(json.loads(json.dumps(w.to_dict(), default=str)))


def _w4_rel(w, a, b):
    return int(w.nation_relations.get(w._make_diplo_key(a, b), 0) or 0)


def _w4_set_rel(w, a, b, value):
    w.nation_relations[w._make_diplo_key(a, b)] = int(value)


def _w4_set_state(w, a, b, state):
    w.diplomatic_states[w._make_diplo_key(a, b)] = state
    w.invalidate_bloc_members_cache()


def _w4_stage(w, mission_type, target, ally=None):
    """The dict the executor's `start_mission` arm writes, books open."""
    mission = {
        "type": mission_type, "target": target, "turns_active": 0, "paused": False,
        "paused_turns": 0, "started_turn": int(w.current_turn),
        "initial_relation": _w4_rel(w, w.player_nation, target),
        "earned": 0, "shocks": [], "paused_errand": 0, "paused_starved": 0,
    }
    if ally:
        mission["target_ally"] = ally
        mission["initial_pair_relation"] = _w4_rel(w, target, ally)
    w.active_diplomatic_mission = mission
    w.talleyrand_state = "ON_MISSION"
    return mission


def _w4_both(w, stage, run):
    """The books never move the board: run the SAME write on a world with the
    mission and one without; return (mission world, bare world)."""
    bare = _w4_copy(w)
    with_mission = _w4_copy(w)
    stage(with_mission)
    with _w4_quiet():
        run(with_mission)
        run(bare)
    assert with_mission.nation_relations == bare.nation_relations, "the books moved the board"
    return with_mission, bare


def _w4_shocks(w):
    return list(w.active_diplomatic_mission["shocks"])


def _w4_cause(shock):
    from backend.game_logic.diplomatic_dialogue import mission_shock_cause
    return mission_shock_cause(shock)


# ══════════════════════════════════════════════════════════════════════════
# S14E-X112 — the writes the first sweep left unbooked
# ══════════════════════════════════════════════════════════════════════════

def _w4_direct_calls():
    """Every `*.modify_nation_relation(...)` call in backend/, as
    {(file name, enclosing function)}, read off the syntax tree."""
    import ast
    found = set()
    for path in (_W4_ROOT / "backend").rglob("*.py"):
        if "__pycache__" in path.parts:
            continue
        text = path.read_text(encoding="utf-8")
        if "modify_nation_relation(" not in text:
            continue
        tree = ast.parse(text)
        for fn in ast.walk(tree):
            if not isinstance(fn, (ast.FunctionDef, ast.AsyncFunctionDef)):
                continue
            for node in ast.walk(fn):
                if (isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute)
                        and node.func.attr == "modify_nation_relation"):
                    # the INNERMOST function owns the call
                    owner = fn.name
                    for inner in ast.walk(fn):
                        if (inner is not fn and isinstance(inner, (ast.FunctionDef, ast.AsyncFunctionDef))
                                and any(n is node for n in ast.walk(inner))):
                            owner = inner.name
                    found.add((path.name, owner))
    return found


def _w4_booked_kinds():
    """Every literal `kind` handed to the books — `modify_relation_booked` /
    `set_relation_booked` (5th positional), `note_mission_shock` (3rd) and the
    executor's `_booked` alias — read off the syntax tree, with where."""
    import ast
    found = {}
    for path in (_W4_ROOT / "backend").rglob("*.py"):
        if "__pycache__" in path.parts:
            continue
        text = path.read_text(encoding="utf-8")
        if not any(k in text for k in ("modify_relation_booked", "set_relation_booked",
                                       "note_mission_shock", "_booked(")):
            continue
        for node in ast.walk(ast.parse(text)):
            if not isinstance(node, ast.Call):
                continue
            name = getattr(node.func, "id", getattr(node.func, "attr", ""))
            if name in ("modify_relation_booked", "set_relation_booked", "_booked"):
                index = 4
            elif name == "note_mission_shock":
                index = 2
            else:
                continue
            if len(node.args) <= index:
                continue
            kind = node.args[index]
            if isinstance(kind, ast.Constant) and isinstance(kind.value, str):
                found.setdefault(kind.value, []).append(f"{path.name}:{node.lineno}")
    return found


class TestS14EX112:
    """Reproduced: after the mission agent's X37/XI1 hooks, `grep
    modify_nation_relation(` still found writes the books never saw — the auto
    downgrade's half penalty, the liberation's two, the AI's rivalry and
    downgrade, the compensation's sold-out hit, an estate confiscation, the
    formation's blow, the Emperor's road teeth and decrees, a moment letter's
    relation, the Ansbach trap, an AI-AI treaty's +10, the forced alliance's
    reset to zero and the vassal cascades' -20s. Each moved a pair a Reassure
    Ally / Improve Relations / Undermine stands on and read in the Cabinet
    row's ledger line as `drift` — a lie about the court's own cooling."""

    # ── the census: the class, not the instances ───────────────────────────

    def test_no_direct_relation_write_is_left_unaccounted(self):
        """A direct `modify_nation_relation(` call is allowed only where the
        books already hold it: the booked write itself, the mission's own work
        (`earned`), the court's own drift (the derived term), or a window a
        `mission_pair_snapshot` / `note_mission_shock` pair brackets."""
        allowed = {
            ("diplomatic_dialogue.py", "modify_relation_booked"),   # the booked write
            ("diplomacy.py", "_process_mission_effects"),           # the mission's own work: `earned`
            ("diplomacy.py", "_process_relation_decay"),            # the court's own drift: the derived term
            ("diplomacy.py", "declare_war"),                        # bracketed: war_declaration
            ("diplomacy.py", "_enter_offensive_war"),               # inside declare_war's / the vassal cascades' bracket
            ("diplomacy.py", "_process_war_cascade"),               # inside declare_war's / the vassal cascades' bracket
            ("diplomacy.py", "execute_downgrade"),                  # bracketed: downgrade
            ("diplomacy.py", "break_treaty"),                       # bracketed: treaty_break
        }
        unbooked = sorted(_w4_direct_calls() - allowed)
        assert unbooked == [], (
            "relation writes the mission's books never see (route each through "
            "diplomatic_dialogue.modify_relation_booked, or bracket it): " + repr(unbooked))

    def test_the_bracketed_allowances_really_are_bracketed(self):
        """The allowance above is only true while each bracket stands."""
        src = (_W4_ROOT / "backend" / "game_logic" / "diplomacy.py").read_text(encoding="utf-8")
        for fn, kind in (("def declare_war(", '"war_declaration"'),
                         ("def execute_downgrade(", '"downgrade"'),
                         ("def break_treaty(", '"treaty_break"')):
            assert fn in src, fn
            body = src[src.index(fn):]
            body = body[:body.index("\ndef ", 10)]
            assert "mission_pair_snapshot" in body and "note_mission_shock" in body, fn
            assert kind in body, (fn, kind)
        vassal = (_W4_ROOT / "backend" / "game_logic" / "vassal.py").read_text(encoding="utf-8")
        assert vassal.count("note_mission_shock(world, _mission_pair_before") == 2, \
            "both vassal cascades (the rebellion, the bribe) are bracketed"

    def test_no_pair_entry_is_set_outright_unbooked(self):
        """The forced alliance's reset writes `nation_relations[pair] = 0`; a
        direct subscript write is allowed only in the cheat console and the
        booked setter."""
        import ast
        found = set()
        for path in (_W4_ROOT / "backend").rglob("*.py"):
            if "__pycache__" in path.parts:
                continue
            text = path.read_text(encoding="utf-8")
            if "nation_relations[" not in text:
                continue
            tree = ast.parse(text)
            for fn in ast.walk(tree):
                if not isinstance(fn, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    continue
                for node in ast.walk(fn):
                    targets = (node.targets if isinstance(node, ast.Assign)
                               else [node.target] if isinstance(node, ast.AugAssign) else [])
                    for t in targets:
                        if (isinstance(t, ast.Subscript) and isinstance(t.value, ast.Attribute)
                                and t.value.attr == "nation_relations"):
                            found.add((path.name, fn.name))
        assert found == {("diplomatic_dialogue.py", "set_relation_booked"),
                         ("meta_executor.py", "_execute_cheat"),
                         ("world_state.py", "modify_nation_relation")}, found

    def test_every_booked_kind_has_its_own_cause_words(self):
        from backend.game_logic.diplomatic_dialogue import mission_shock_cause
        kinds = _w4_booked_kinds()
        assert len(kinds) >= 44, sorted(kinds)
        # the fall-through ("Spain's <kind>") is the lie this census exists to refuse;
        # a kind that reads right as is must be named here on purpose.
        allowed_default = {"separate_peace", "sponsorship", "guarantee"}
        for kind, where in sorted(kinds.items()):
            cause = mission_shock_cause({"kind": kind, "by": "Spain", "on": "Prussia"})
            assert cause and cause != "events", (kind, where)
            assert "_" not in cause, (kind, cause, where)
            if kind not in allowed_default:
                assert cause != f"Spain's {kind.replace('_', ' ')}", (kind, cause, where)

