    def test_the_auto_downgrade_is_booked(self, _w4_w):
        from backend.game_logic import diplomacy as D
        w = _w4_w
        assert w.get_diplomatic_state("France", "Spain") == "ALLIANCE"
        _w4_set_rel(w, "France", "Spain", -10)           # 50 below the alliance's 40
        w.turns_below_threshold[w._make_diplo_key("France", "Spain")] = 4
        mw, bare = _w4_both(w, lambda x: _w4_stage(x, "REASSURE_ALLY", "Spain"),
                            D.check_auto_downgrade)
        assert mw.get_diplomatic_state("France", "Spain") == "DEFENSIVE_ALLIANCE", "it did downgrade"
        (shock,) = [s for s in _w4_shocks(mw) if s["kind"] == "auto_downgrade"]
        assert shock["delta"] == D.DOWNGRADE_PENALTIES[("ALLIANCE", "DEFENSIVE_ALLIANCE")]["relation_target"] // 2
        assert _w4_cause(shock) == "the bond's automatic downgrade"

    def test_the_ai_rivalry_is_booked_and_folds(self, _w4_w):
        from backend.game_logic import ai_diplomacy as AD
        w = _w4_w
        assert _w4_rel(w, "Russia", "Sweden") > 0
        mw, bare = _w4_both(w, lambda x: _w4_stage(x, "UNDERMINE_ALLIANCE", "Russia", "Sweden"),
                            AD._process_ai_ai_rivalry)
        (shock,) = _w4_shocks(mw)
        assert (shock["kind"], shock["delta"]) == ("ai_rivalry", -3)
        # a standing write: the second turn folds into the same entry
        with _w4_quiet():
            AD._process_ai_ai_rivalry(mw)
        (shock,) = _w4_shocks(mw)
        assert shock["delta"] == -6, shock
        # the rivalry of a pair the mission does not stand on is not booked
        assert _w4_rel(mw, "Prussia", "Russia") == _w4_rel(w, "Prussia", "Russia") - 6

