    def test_the_already_booked_bargain_entries_are_not_doubled(self, _w4_w):
        """`resolve_join_opportunity` and `accept_counter_bargain` hold their
        own hook (kind `bargain_entry`) and sit OUTSIDE declare_war's bracket,
        so one write is one entry."""
        from backend.game_logic import diplomacy as D
        w = _w4_w
        assert w.get_diplomatic_state("Prussia", "Russia") != "WAR"
        _w4_set_state(w, "France", "Prussia", "ALLIANCE")     # the counter's source treaty
        opportunity = {"beneficiary": "Prussia", "named_enemy": "Russia", "promiser": "France",
                       "request_type": "offensive_ally_request", "hard_blocks": [],
                       "origin_episode_id": ""}
        mw, bare = _w4_both(
            w, lambda x: _w4_stage(x, "UNDERMINE_ALLIANCE", "Prussia", "Russia"),
            lambda x: D.resolve_join_opportunity(x, dict(opportunity), "accept"))
        assert mw.get_diplomatic_state("Prussia", "Russia") == "WAR"
        (shock,) = _w4_shocks(mw)
        assert (shock["kind"], shock["delta"]) == ("bargain_entry", -20)
        # accept_counter_bargain: the same, once
        claim = next(r.name for r in w.regions.values()
                     if r.controller == "Russia" and D._has_bargain_strategic_interest(w, "France", r.name))
        counter = {"promiser": "France", "beneficiary": "Prussia", "named_enemy": "Russia",
                   "demanded_region": claim}
        mw, bare = _w4_both(
            w, lambda x: _w4_stage(x, "UNDERMINE_ALLIANCE", "Prussia", "Russia"),
            lambda x: D.accept_counter_bargain(x, dict(counter), join_war=True))
        assert mw.get_diplomatic_state("Prussia", "Russia") == "WAR"
        (shock,) = _w4_shocks(mw)
        assert (shock["kind"], shock["delta"]) == ("bargain_entry", -20)

