class TestS14EX136:
    """Reproduced: the vassal cascades (`check_vassal_rebellion`, and the
    bribe's `_defect_vassal_free_and_hostile`) call `_process_war_cascade`
    outside any bracket — a Switzerland allied to Prussia that rebels from
    France sets Prussia marching and the cascade's -20 on France-Prussia read
    as `drift` under an Improve Relations on Prussia."""

    def test_a_vassal_cascade_is_booked_as_the_rebellion_that_set_it_off(self, _w4_w):
        """Switzerland (France's client) rebels; its allies march and the
        cascade's -20 lands on a pair the mission stands on."""
        from backend.game_logic.vassal import check_vassal_rebellion
        w = _w4_w
        assert w.vassals["Switzerland"]["lord"] == "France"
        _w4_set_state(w, "Switzerland", "Prussia", "ALLIANCE")
        w.vassals["Switzerland"]["loyalty"] = 0
        mw, bare = _w4_both(w, lambda x: _w4_stage(x, "IMPROVE_RELATIONS", "Prussia"),
                            check_vassal_rebellion)
        assert mw.get_diplomatic_state("Switzerland", "France") == "WAR", "the client did rebel"
        rows = [s for s in _w4_shocks(mw) if s["kind"] == "vassal_rebellion"]
        landed = _w4_rel(mw, "France", "Prussia") - _w4_rel(w, "France", "Prussia")
        assert landed == -20, "Prussia, Switzerland's ally, marched on France: the cascade's -20"
        assert sum(s["delta"] for s in rows) == landed, (rows, landed)
        assert _w4_cause(rows[0]) == "Switzerland's rebellion against us"
        assert sum(s["delta"] for s in _w4_shocks(mw)) == landed, "nothing unbooked, nothing doubled"

    def test_the_bribes_cascade_is_booked_as_the_defection(self, _w4_w):
        from backend.game_logic.vassal import _defect_vassal_free_and_hostile
        w = _w4_w
        _w4_set_state(w, "Switzerland", "Prussia", "ALLIANCE")
        mw, bare = _w4_both(
            w, lambda x: _w4_stage(x, "IMPROVE_RELATIONS", "Prussia"),
            lambda x: _defect_vassal_free_and_hostile(x, "Switzerland", "Britain"))
        (shock,) = _w4_shocks(mw)
        assert (shock["kind"], shock["delta"]) == ("vassal_defection", -20)
        assert _w4_cause(shock) == "Switzerland's defection"


class TestS14EX137:
    """Reproduced: a forced alliance's peace resets the pair to ZERO
    (`nation_relations[pair] = 0`, a direct set, not a `modify_nation_relation`
    call, so the first grep missed it) on both ratifiers; a mission on the
    defeated court read the whole swing as `drift`."""

    def test_the_forced_alliances_reset_is_booked(self, _w4_w):
        from backend.game_logic.diplomatic_dialogue import set_relation_booked
