# S14E-X119 — the Ireland road, on every surface that names Munster
# ══════════════════════════════════════════════════════════════════════════

def _w4_hold(world, *names):
    for name in names:
        world.regions[name].controller = "France"
    world.invalidate_active_nations_cache()
    return world


class TestS14EX119:
    """Reproduced (the shipped 1805 board, Free Ireland begun — France holds
    Munster): `congress.state_line` read "(1 held, unsettled: Munster — on the
    road to Ireland)" while `game_end.title_roads` (the Territories tab's text,
    the Moniteur's and the desk's short) read "Munster — no clock runs on it;
    only a treaty that cedes it titles it" / "Munster waits on a treaty", and
    the payload's `held_unsettled` (the ledger's fallback list) read the bare
    "Munster"."""

    def test_the_boot_board_is_byte_identical(self, _w4_w):
        from backend.game_logic import congress, game_end
        w = _w4_w
        assert game_end.title_roads(w, "France") == []
        payload = congress.build_congress_payload(w)
        assert payload["held_unsettled"] == [] and payload["held_roads"] == []
        assert "road to" not in congress.state_line(w)

    def test_a_province_on_no_road_reads_as_it_did(self, _w4_w):
        from backend.game_logic import congress, game_end
        w = _w4_hold(_w4_w, "Tyrol")
        (road,) = game_end.title_roads(w, "France")
        assert road["text"] == ("Tyrol — no clock runs on it; only a treaty that cedes it titles it")
        assert road["short"] == "Tyrol waits on a treaty"
        assert congress.build_congress_payload(w)["held_unsettled"] == ["Tyrol"]

    def test_munster_on_the_ireland_carve_carries_the_clock_s_clause(self, _w4_w):
        from backend.game_logic import congress, game_end
        from backend.game_logic.formations import road_clause_for
        w = _w4_hold(_w4_w, "Munster")
        clause = road_clause_for(w, "Munster")
        assert clause == "on the road to Ireland"
        (road,) = game_end.title_roads(w, "France")
        assert road["text"].endswith(f" — {clause}"), road["text"]
        assert road["short"] == f"Munster waits on a treaty — {clause}"
        assert f"(1 held, unsettled: Munster — {clause})" in congress.state_line(w)
        # the same words on every surface that reads the roads or the payload
        payload = congress.build_congress_payload(w)
        assert payload["held_unsettled"] == [f"Munster — {clause}"]
        assert payload["held_roads"][0]["short"] == road["short"]
        assert payload["held_roads"][0]["text"] == road["text"]
        gate = congress.clock_payload(w)
        assert gate["held_roads"][0]["short"] == road["short"]

    def test_the_quiet_and_peace_roads_carry_it_too(self, _w4_w):
        """Whatever kind the road to title is, the clause rides its tail."""
        from backend.game_logic import game_end
        from backend.game_logic.diplomacy import set_diplomatic_state
        w = _w4_hold(_w4_w, "Munster")
        game_end.record_province_title(w, "Munster", game_end.TITLE_CONQUEST, "Britain", "France")
        (road,) = game_end.title_roads(w, "France")
        assert road["kind"] in ("peace", "quiet"), road
        assert road["text"].endswith(" — on the road to Ireland")
        assert road["short"].endswith(" — on the road to Ireland")
        set_diplomatic_state(w, "France", "Britain", "PEACE", "test")
        (road,) = game_end.title_roads(w, "France")
        assert road["kind"] == "quiet", road
        assert road["text"].endswith(" — on the road to Ireland")
        assert road["short"].endswith(" — on the road to Ireland")

    def test_the_moniteur_names_the_carve_beside_munster(self, _w4_w):
        """Within five provinces of the summons the paper names the nearest
        roads (`gazette._congress_column`, reading each road's `short`)."""
        from backend.game_logic import congress, game_end
        from backend.game_logic.gazette import NEAR_MISS_PROVINCES, _congress_column
        w = _w4_w
        need = congress.titled(w)["needed"]
        moved = 0
        for nation in ("Hanover", "Denmark", "Portugal", "Sardinia", "Naples", "Saxony", "Hesse"):
            for region in sorted(w.get_nation_regions(nation)):
                if congress.titled(w)["count"] >= need - NEAR_MISS_PROVINCES:
                    break
                if region == "Lisbon":
                    continue
                w.regions[region].controller = "France"
                game_end.record_province_title(w, region, game_end.TITLE_TREATY, nation, "France")
                w.invalidate_active_nations_cache()
                moved += 1
        _w4_hold(w, "Munster")
        view = congress.titled(w)
        assert 0 < view["needed"] - view["count"] <= NEAR_MISS_PROVINCES, view["count"]
        lines = _congress_column(w, None)
        assert any("Munster waits on a treaty — on the road to Ireland" in line for line in lines), lines

    def test_a_mixed_hold_clauses_only_the_province_on_the_road(self, _w4_w):
        from backend.game_logic import congress, game_end
        w = _w4_hold(_w4_w, "Munster", "Tyrol")
        roads = {r["region"]: r for r in game_end.title_roads(w, "France")}
        assert roads["Munster"]["short"].endswith(" — on the road to Ireland")
        assert "road to" not in roads["Tyrol"]["short"] and "road to" not in roads["Tyrol"]["text"]
        assert congress.build_congress_payload(w)["held_unsettled"] == [
            "Munster — on the road to Ireland", "Tyrol"]

    def test_a_whole_carve_adds_nothing(self, _w4_w):
        """Both provinces held: a `ready` road feeds the war card and the review
        only — the clock adds nothing, and neither do the roads."""
        from backend.game_logic import congress, game_end
        w = _w4_hold(_w4_w, "Munster", "Ulster")
        for road in game_end.title_roads(w, "France"):
            assert "road to" not in road["text"] and "road to" not in road["short"]
        assert congress.build_congress_payload(w)["held_unsettled"] == ["Munster", "Ulster"]

    def test_the_ledgers_fallback_prints_the_backends_labels_as_they_are(self):
        """The `held_unsettled` fallback needs no client logic: it shows each
        entry as the backend wrote it (the clause rides in the label)."""
        text = (_W4_ROOT / "godot-client" / "project-sovereign" / "scripts"
                / "diplomatic_ledger.gd").read_text(encoding="utf-8")
        assert 'var held = c.get("held_unsettled", [])' in text
        assert "names.append(str(h))" in text
        assert "Ireland" not in text[text.index('var held = c.get("held_unsettled"'):
                                     text.index("func _congress_sitting_block")]

# ========== S14f part 2 - merged from test_s14f_p2_w5.py ==========

_W5_ROOT = Path(__file__).resolve().parents[1]
_W5_SCENARIO = (_W5_ROOT / "godot-client" / "project-sovereign"
                / "assets" / "maps" / "europe_1805.json")
_W5_MINUS = "−"


def _w5_quiet():
    return contextlib.redirect_stdout(io.StringIO())


@pytest.fixture(scope="module")
def _w5_boot():
    from backend.models.world_state import WorldState
    with _w5_quiet():
        return WorldState.from_scenario(str(_W5_SCENARIO))


def _w5_world(boot):
    from backend.models.world_state import WorldState
    return WorldState.from_dict(json.loads(json.dumps(boot.to_dict(), default=str)))


def _w5_set(w, a: str, b: str, state: str) -> None:
    from backend.game_logic.diplomacy import set_diplomatic_state
    with _w5_quiet():
        set_diplomatic_state(w, a, b, state, "test")


def _w5_see(w) -> None:
    w._build_marshal_index()
    with _w5_quiet():
        w.calculate_visibility()


@contextlib.contextmanager
def _w5_client(w):
    """The player's road: /command on a swapped world (three globals, restored)."""
    import backend.main as M
    from backend.commands.parser import CommandParser
    from fastapi.testclient import TestClient
    saved = (M.game_state["world"], M.world, M.parser)
    M.game_state["world"] = w
    M.world = w
    M.parser = CommandParser(use_real_llm=False)
    try:
        yield TestClient(M.app)
    finally:
        M.game_state["world"], M.world, M.parser = saved


def _w5_say(client, text: str) -> dict:
    with _w5_quiet():
        return client.post("/command", json={"command": text}).json()


def _w5_figure(text: str) -> int:
    m = re.search(_W5_MINUS + r"([\d,]+)g", text)
    assert m, text
    return int(m.group(1).replace(",", ""))


def _w5_pay(w, nation: str = "France") -> int:
    return int(w.calculate_turn_upkeep(nation)["campaign_pay"])


def _w5_detour_board(boot):
    """S14E-22's board (the conquest run, DD-B turn 19): France holds Berlin,
    Moravia and Vienna; Bohemia and Dresden are Austrian under the truce;
    Prussia has opened her borders; Soult (literal) stands in Berlin and
    Davout (cautious) at Vienna. The direct road Berlin -> Dresden -> Vienna
    is shut; the lawful one is Brandenburg -> Posen -> Silesia -> Podolia ->
    Moravia -> Vienna (six)."""
    w = _w5_world(boot)
    for name, owner in (("Berlin", "France"), ("Moravia", "France"), ("Vienna", "France"),
                        ("Dresden", "Austria"), ("Bohemia", "Austria")):
        w.regions[name].controller = owner
    _w5_set(w, "France", "Austria", "ARMISTICE")
    _w5_set(w, "France", "Prussia", "OPEN_BORDERS")
    soult = w.get_marshal("Soult")
    assert soult.personality == "literal" and soult.movement_range == 1
    soult.location = "Berlin"
    w.get_marshal("Davout").location = "Vienna"
    _w5_see(w)
    return w


@pytest.fixture
def _w5_detour(_w5_boot):
    return _w5_detour_board(_w5_boot)


_W5_DETOUR = ("The direct road to Vienna via Dresden is closed by the truce with Austria; "
              "the lawful road is 6 provinces, 6 turns, through Prussia and Russia")


