# S14E-X86 - the pursuit ask names the first march's campaign pay
# ══════════════════════════════════════════════════════════════════════════

_W5_SWABIA_PAY = ("Swabia is Bavaria's soil " + "—" + " the corps standing there are fed by "
                  "contract, about " + _W5_MINUS + "288g more a turn.")


def _w5_pursuit_board(boot):
    """DDB-R1's board: Ney (24,000, aggressive) on Rhineland; Kutuzov seen at
    Bohemia, three marches off - the road's first march is Swabia, Bavaria's
    soil (our ally; a French corps there is fed by contract)."""
    w = _w5_world(boot)
    w.get_marshal("Kutuzov").location = "Bohemia"
    w.get_marshal("Mack").location = "Munich"
    _w5_see(w)
    ney = w.get_marshal("Ney")
    assert ney.location == "Rhineland" and ney.strength == 24000
    return w


@pytest.fixture
def _w5_pursuit(_w5_boot):
    return _w5_pursuit_board(_w5_boot)


class TestS14EX86:
    """S14E-X86 (the sweep of S14E-X67): the pursuit ask (DDB-R1, a typed
    attack on a marshal out of reach) names the first march's SOIL but not
    the pay that soil draws.

    Reproduced: on the DDB-R1 board "Ney, attack Kutuzov in Bohemia" asked
    "... the first march takes Ney to Swabia, Bavaria's soil), or cancel?" and
    nothing of EAD-1, while the first step stands a 24,000-man corps on an
    ally's soil at -288g a turn.

    The fix: `movement_executor.campaign_pay_line(world, marshal, first)` - the
    sentence the march card, the plain move and the muster print - rides the
    ask before its question; byte-identical when the pay does not change."""

    _BASE = ("Kutuzov stands at Bohemia, three marches off. Pursue him (2 AP "
             "— a standing order; the first march takes Ney to Swabia, Bavaria's "
             "soil), or cancel?")

    def test_the_ask_names_the_pay(self, _w5_pursuit):
        w = _w5_pursuit
        ney = w.get_marshal("Ney")
        ap = int(w.actions_remaining)
        with _w5_client(w) as client:
            out = _w5_say(client, "Ney, attack Kutuzov in Bohemia")
        assert out.get("clarification_kind") == "pursuit_ask", out.get("message")
        assert out["message"] == (
            "Kutuzov stands at Bohemia, three marches off. " + _W5_SWABIA_PAY
            + " Pursue him (2 AP — a standing order; the first march takes Ney to "
            "Swabia, Bavaria's soil), or cancel?"), out["message"]
        assert ney.location == "Rhineland" and ney.strategic_order is None
        assert int(w.actions_remaining) == ap                  # a free ask

    def test_shown_equals_applied_against_the_upkeep_bill(self, _w5_pursuit):
        w = _w5_pursuit
        ney = w.get_marshal("Ney")
        with _w5_client(w) as client:
            out = _w5_say(client, "Ney, attack Kutuzov in Bohemia")
        quoted = _w5_figure(out["message"])
        before = _w5_pay(w)
        ney.location = "Swabia"                                 # the first march is taken
        assert _w5_pay(w) - before == quoted == 288

    def test_the_sentence_is_the_march_cards_own(self, _w5_pursuit):
        from backend.commands.movement_executor import campaign_pay_line
        from backend.commands.order_quotes import march_quote
        w = _w5_pursuit
        ney = w.get_marshal("Ney")
        assert campaign_pay_line(w, ney, "Swabia") == _W5_SWABIA_PAY
        assert march_quote(w, ney, "Swabia")["pay"] == _W5_SWABIA_PAY

    def test_no_pay_keeps_the_ask_byte_identical(self, _w5_pursuit):
        """A satellite's soil feeds the corps (the bill reads none): the ask
        is exactly the DDB-R1 sentence."""
        w = _w5_pursuit
        w.diplomatic_states[w._make_diplo_key("France", "Bavaria")] = "VASSAL"
        with _w5_client(w) as client:
            out = _w5_say(client, "Ney, attack Kutuzov in Bohemia")
        assert out.get("clarification_kind") == "pursuit_ask", out.get("message")
        assert out["message"] == self._BASE

    def test_own_soil_first_march_keeps_the_ask_byte_identical(self, _w5_pursuit):
        w = _w5_pursuit
        w.get_region("Swabia").controller = "France"
        with _w5_client(w) as client:
            out = _w5_say(client, "Ney, attack Kutuzov in Bohemia")
        assert out["message"].startswith("Kutuzov stands at Bohemia, three marches off. Pursue him")
        assert "fed by contract" not in out["message"]


# ══════════════════════════════════════════════════════════════════════════
# S14E-X87 - typed support, follow and pursue roads ask about a shut road
# ══════════════════════════════════════════════════════════════════════════

class TestS14EX87:
    """S14E-X87 (the sweep of S14E-22): typed `support`, `follow` and `pursue`
    roads use the breadth-first search, so the same silent long or foreign
    detour S14E-22 fixed for `march to` still committed unasked.

    Reproduced on the S14E-22 board (Dresden and Bohemia Austrian under the
    truce): "Soult, support Davout" (Davout at Vienna), "Soult, follow Davout"
    and "Soult, pursue Kutuzov" (Kutuzov seen at Vienna) were each accepted at once -
    1 AP / 2 AP spent, the order standing, the first step walked to Brandenburg
    - and the reply printed the six-province road only afterwards.

    The fix: `strategic.march_detour_reading` takes the order's type and reads
    the finder the issuance itself uses (weighted for MOVE_TO / HOLD, breadth-
    first for the rest); `march_detour_ask` asks for those types in the same
    words with the verb named. The AI, delegation-inferred orders,
    `_strategic_execution` and a standing order's later re-plots are untouched
    (Golden Rule 5)."""

    @pytest.mark.parametrize("line,verb,kind", [
        pytest.param("Soult, support Davout", "support", "SUPPORT", id="support"),
        pytest.param("Soult, follow Davout", "follow", "SUPPORT", id="follow"),
        pytest.param("Soult, pursue Kutuzov", "pursue", "PURSUE", id="pursue"),
    ])
    def test_the_typed_road_asks_before_it_commits(self, _w5_detour, line, verb, kind):
        w = _w5_detour
        w.get_marshal("Kutuzov").location = "Vienna"
        _w5_see(w)
        soult = w.get_marshal("Soult")
        ap = int(w.actions_remaining)
        with _w5_client(w) as client:
            out = _w5_say(client, line)
        assert out.get("state") == "awaiting_clarification", out.get("message")
        assert out.get("clarification_kind") == "march_detour_ask"
        assert out.get("free_action") is True and out["strategic_type"] == kind
        assert out["message"] == f"{_W5_DETOUR} — {verb}, or cancel?"
        assert out["options"][0]["label"].startswith(verb.capitalize() + " (")
        assert out["options"][0]["command"] == line
        assert out["options"][0]["flags"] == {"_march_confirmed": True}
        assert soult.location == "Berlin" and soult.strategic_order is None
        assert int(w.actions_remaining) == ap

    @pytest.mark.parametrize("line,verb,kind", [
        pytest.param("Soult, support Davout", "support", "SUPPORT", id="support"),
        pytest.param("Soult, follow Davout", "follow", "SUPPORT", id="follow"),
        pytest.param("Soult, pursue Kutuzov", "pursue", "PURSUE", id="pursue"),
    ])
    def test_the_verb_issues_the_order_as_today(self, _w5_detour, line, verb, kind):
        w = _w5_detour
        w.get_marshal("Kutuzov").location = "Vienna"
        _w5_see(w)
        soult = w.get_marshal("Soult")
        ap = int(w.actions_remaining)
        price = int(soult.strategic_order_ap(order_type=kind))
        with _w5_client(w) as client:
            ask = _w5_say(client, line)
            assert ask.get("clarification_kind") == "march_detour_ask", ask.get("message")
            out = _w5_say(client, verb)
        assert out.get("success") is True, out.get("message")
        assert out.get("state") != "awaiting_clarification"
        assert soult.strategic_order is not None and soult.strategic_order.command_type == kind
        assert int(w.actions_remaining) == ap - price          # the price, once
        assert soult.location == "Brandenburg"
        if verb == "follow":
            assert soult.strategic_order.standing_follow is True

    def test_cancel_spends_nothing(self, _w5_detour):
        w = _w5_detour
        soult = w.get_marshal("Soult")
        ap = int(w.actions_remaining)
        with _w5_client(w) as client:
            _w5_say(client, "Soult, support Davout")
            out = _w5_say(client, "cancel")
        assert out.get("success") is True and "withdrawn" in out["message"]
        assert soult.location == "Berlin" and soult.strategic_order is None
        assert int(w.actions_remaining) == ap

    def test_the_reading_asks_the_finder_the_issuance_uses(self, _w5_detour):
        """Weighted for a march or a hold, breadth-first for the rest."""
        from backend.commands import strategic as S
        w = _w5_detour
        soult = w.get_marshal("Soult")
        road, refusal, _kind = S.march_road(w, soult, "Vienna", "SUPPORT")
        assert refusal is None
        calls = []
        real_weighted, real_bfs = w.find_weighted_path, w.find_path

        def weighted(*a, **k):
            calls.append("weighted")
            return real_weighted(*a, **k)

        def bfs(*a, **k):
            calls.append("bfs")
            return real_bfs(*a, **k)

        w.find_weighted_path, w.find_path = weighted, bfs
        try:
            for kind, finder in (("SUPPORT", "bfs"), ("PURSUE", "bfs"),
                                 ("MOVE_TO", "weighted"), ("HOLD", "weighted")):
                del calls[:]
                reading = S.march_detour_reading(w, soult, "Vienna", road, kind)
                assert reading and reading["via"] == "Dresden", kind
                assert calls == [finder], (kind, calls)
            del calls[:]
            S.march_detour_reading(w, soult, "Vienna", road)         # the default is the march's
            assert calls == ["weighted"]
        finally:
            del w.find_weighted_path, w.find_path

    def test_the_quote_says_what_the_ask_says(self, _w5_boot):
        """The support and follow cards carry the march card's `detour` rider -
        the card the player reads before sending and the question the typed
        order asks cannot disagree."""
        from backend.commands.order_quotes import follow_quote, support_quote
        w = _w5_detour_board(_w5_boot)
        soult, davout = w.get_marshal("Soult"), w.get_marshal("Davout")
        sq, fq = support_quote(w, soult, davout), follow_quote(w, soult, davout)
        assert sq["ok"] and fq["ok"]
        with _w5_client(w) as client:
            ask = _w5_say(client, "Soult, support Davout")
        assert sq["detour"] == fq["detour"] == _W5_DETOUR + "."
        assert ask["message"] == sq["detour"].rstrip(".") + " — support, or cancel?"
        # ... and an open road quotes no detour
        calm = _w5_world(_w5_boot)
        assert support_quote(calm, calm.get_marshal("Soult"), calm.get_marshal("Ney"))["detour"] == ""

    @pytest.mark.parametrize("command_extra,parsed_extra", [
        pytest.param({"_army_order": True}, {"raw_input": "the army, support Davout"}, id="army_order"),
        pytest.param({"objection_response": "proceed"}, {"raw_input": "Soult, support Davout"},
                     id="objection_answered"),
        pytest.param({"_march_confirmed": True}, {"raw_input": "Soult, support Davout"},
                     id="the_answered_ask"),
        pytest.param({}, {"raw_input": "Soult, support Davout", "delegation_inferred": True},
                     id="delegation_inferred"),
        pytest.param({}, {}, id="no_typed_line"),
    ])
    def test_orders_that_are_not_the_players_typed_line_keep_today(self, _w5_boot,
                                                                   command_extra, parsed_extra):
        from backend.commands.executor import CommandExecutor
        w = _w5_detour_board(_w5_boot)
        command = {"marshal": "Soult", "action": "support", "target": "Davout", **command_extra}
        parsed = {"command": command, "is_strategic": True, "strategic_type": "SUPPORT",
                  **parsed_extra}
        with _w5_quiet():
            out = CommandExecutor().execute(parsed, {"world": w})
        assert out.get("state") != "awaiting_clarification", out.get("message")
        assert w.get_marshal("Soult").strategic_order is not None

    def test_the_ais_side_never_reads_it(self, _w5_detour):
        """Golden Rule 5: the reading is the player's corps only; the AI's
        executor path, a standing order's re-plot and the AI module never
        call it."""
        from backend.commands import strategic as S
        w = _w5_detour
        road, _r, _k = S.march_road(w, w.get_marshal("Soult"), "Vienna", "SUPPORT")
        ai = w.get_marshal("Mack")
        assert ai.nation != w.player_nation
        for kind in ("SUPPORT", "PURSUE"):
            assert S.march_detour_reading(w, ai, "Vienna", road, kind) is None
        ai_src = (_W5_ROOT / "backend" / "ai" / "enemy_ai.py").read_text(encoding="utf-8")
        assert "march_detour" not in ai_src
        text = (_W5_ROOT / "backend" / "commands" / "strategic_executor.py").read_text(encoding="utf-8")
        assert text.count("march_detour_ask(") == 2          # the definition and the road stage

    def test_an_open_road_never_asks(self, _w5_boot):
        """The shipped board: Soult follows Ney across lawful soil - taken as today."""
        w = _w5_world(_w5_boot)
        soult = w.get_marshal("Soult")
        with _w5_client(w) as client:
            out = _w5_say(client, "Soult, follow Ney")
        assert out.get("state") != "awaiting_clarification", out.get("message")
        assert soult.strategic_order is not None


# ══════════════════════════════════════════════════════════════════════════
# S14E-X131 - the answered pursuit ask never asks twice; the ask names the detour
# ══════════════════════════════════════════════════════════════════════════

class TestS14EX131:
    """S14E-X131 (the sweep of S14E-X87): the DDB-R1 pursuit ask (a typed attack
    on a marshal out of reach) walks the same breadth-first road, and its
    answer re-issues the attack as a PURSUE - which the new road-stage ask
    would have asked about a second time.

    Reproduced (by construction): "Soult, attack Kutuzov" with Kutuzov at Vienna asks
    "Pursue him ...", and the "yes" then fell on `march_detour_ask`'s PURSUE arm
    (the upgrade's synthetic line is a typed line to it). The upgrade carries
    `_attack_upgrade` and the ask skips it; the pursuit ask itself now names the
    shut direct road in the detour's words, so the one question the player is
    asked says everything."""

    def test_the_pursuit_ask_names_the_detour(self, _w5_detour):
        w = _w5_detour
        w.get_marshal("Kutuzov").location = "Vienna"
        _w5_see(w)
        soult = w.get_marshal("Soult")
        with _w5_client(w) as client:
            out = _w5_say(client, "Soult, attack Kutuzov")
        assert out.get("clarification_kind") == "pursuit_ask", out.get("message")
        assert _W5_DETOUR + "." in out["message"], out["message"]
        assert out["message"].index(_W5_DETOUR) < out["message"].index("Pursue him")
        assert soult.location == "Berlin" and soult.strategic_order is None

    def test_yes_pursues_and_does_not_ask_twice(self, _w5_detour):
        w = _w5_detour
        w.get_marshal("Kutuzov").location = "Vienna"
        _w5_see(w)
        soult = w.get_marshal("Soult")
        ap = int(w.actions_remaining)
        with _w5_client(w) as client:
            ask = _w5_say(client, "Soult, attack Kutuzov")
            assert ask.get("clarification_kind") == "pursuit_ask"
            out = _w5_say(client, "yes")
        assert out.get("clarification_kind") != "march_detour_ask", out.get("message")
        assert out.get("success") is True, out.get("message")
        assert soult.strategic_order is not None and soult.strategic_order.command_type == "PURSUE"
        assert int(w.actions_remaining) == ap - int(soult.strategic_order_ap(order_type="PURSUE"))
        assert soult.location == "Brandenburg"

    def test_an_open_road_keeps_the_pursuit_ask_as_it_was(self, _w5_pursuit):
        """No shut direct road, no detour sentence (the DDB-R1 board)."""
        w = _w5_pursuit
        w.diplomatic_states[w._make_diplo_key("France", "Bavaria")] = "VASSAL"
        with _w5_client(w) as client:
            out = _w5_say(client, "Ney, attack Kutuzov in Bohemia")
        assert "direct road" not in out["message"]
        assert out["message"] == TestS14EX86._BASE


# ══════════════════════════════════════════════════════════════════════════
# S14E-X88 - the army order's group quote counts the detours
# ══════════════════════════════════════════════════════════════════════════

def _w5_army_board(boot):
    """The detour board with the Staff in force: the Emperor and Ney at
    Silesia (the lawful road's own province - Podolia, Moravia, Vienna lie
    open ahead of them), Davout at Posen, Soult at Berlin and Bernadotte at
    Franconia (their direct roads to Vienna are shut by the truce); Lannes,
    Murat and Massena stand beyond the column."""
    from backend.game_logic import reforms
    w = _w5_detour_board(boot)
    row = next(r for r in reforms.deck(w, w.player_nation) if reforms.is_staff(r))
    row["enacted_turn"] = w.current_turn
    for name in ("Napoleon", "Ney"):
        w.get_marshal(name).location = "Silesia"
    w.get_marshal("Davout").location = "Posen"
    _w5_see(w)
    return w


class TestS14EX88:
    """S14E-X88 (the sweep of S14E-22): `army_quote` (the Staff's one order for
    the Emperor's column - the province panel's army row) carried no per-corps
    detour, so a column of five could march three corps down a six-province
    foreign road and the card said only "5 corps march: ...".

    Reproduced: `army_quote(w, "Vienna")` on the army board returned the corps
    rows `{marshal, shown, turns, objection}` and a note with no word of the
    roads, while `march_quote` for Soult, Ney and the Emperor each carried the
    detour sentence.

    The fix: each corps row carries the march card's `detour` rider and the
    note counts the corps whose road would ask - "3 of 5 corps take a long or
    foreign road - their cards say which"."""

    def test_the_corps_rows_carry_the_detour_rider(self, _w5_boot):
        from backend.commands.order_quotes import army_quote, march_quote
        w = _w5_army_board(_w5_boot)
        a = army_quote(w, "Vienna")
        assert a["ok"], a["refusal"]
        rows = {c["marshal"]: c for c in a["corps"]}
        assert set(rows) == {"Ney", "Davout", "Soult", "Bernadotte", "Napoleon"}
        assert rows["Soult"]["detour"] == _W5_DETOUR + "."
        assert rows["Davout"]["detour"].startswith("The direct road to Vienna via Dresden is closed")
        assert rows["Bernadotte"]["detour"].startswith("The direct road to Vienna via Bohemia is closed")
        for name in ("Ney", "Napoleon"):
            assert rows[name]["detour"] == "", name
        # the single card and the group row cannot disagree
        for name, row in rows.items():
            assert row["detour"] == march_quote(w, w.get_marshal(name), "Vienna")["detour"], name

    def test_the_note_counts_the_corps_whose_road_would_ask(self, _w5_boot):
        from backend.commands.order_quotes import army_quote
        w = _w5_army_board(_w5_boot)
        note = army_quote(w, "Vienna")["note"]
        assert "3 of 5 corps take a long or foreign road — their cards say which" in note, note
        assert note.startswith("5 corps march: ")

    def test_one_corps_is_said_in_the_singular(self, _w5_boot):
        from backend.commands.order_quotes import army_quote
        w = _w5_army_board(_w5_boot)
        for name in ("Davout", "Bernadotte"):               # beyond the column
            w.get_marshal(name).location = "Franche-Comte"
        _w5_see(w)
        note = army_quote(w, "Vienna")["note"]
        assert "1 of 3 corps takes a long or foreign road — his card says which" in note, note

    def test_no_detour_no_clause(self, _w5_boot):
        """The shipped board: nothing is shut, the note is the army row's as it was."""
        from backend.commands.order_quotes import army_quote
        from backend.game_logic import reforms
        w = _w5_world(_w5_boot)
        row = next(r for r in reforms.deck(w, w.player_nation) if reforms.is_staff(r))
        row["enacted_turn"] = w.current_turn
        a = army_quote(w, "Munich")
        assert a["ok"], a["refusal"]
        assert "road" not in a["note"]
        assert all(c["detour"] == "" for c in a["corps"])

    def test_the_group_card_already_carries_each_corps_rider(self, _w5_boot):
        """`group_march_quotes` (Ctrl-click) is made of whole march quotes, so
        its rows already carried the rider - the sweep's negative control."""
        from backend.commands.order_quotes import group_march_quotes
        w = _w5_army_board(_w5_boot)
        got = group_march_quotes(w, ["Soult", "Davout"], "Vienna")
        by = {q["marshal"]: q for q in got["quotes"]}
        assert by["Soult"]["detour"] == _W5_DETOUR + "."
        assert by["Davout"]["detour"].startswith("The direct road to Vienna via Dresden is closed")
        assert group_march_quotes(w, ["Ney"], "Vienna")["quotes"][0]["detour"] == ""


# ══════════════════════════════════════════════════════════════════════════
# S14E-X89 - a retreat onto allied or neutral soil says the pay
# ══════════════════════════════════════════════════════════════════════════

def _w5_retreat_board(boot):
    """Davout (26,000, cautious) on Rhineland with Mack at Lorraine - in
    danger; Swabia (adjacent) is Bavaria's soil, our ally's, where a French
    corps is fed by contract."""
    w = _w5_world(boot)
    w.get_marshal("Mack").location = "Lorraine"
    _w5_see(w)
    davout = w.get_marshal("Davout")
    assert davout.location == "Rhineland" and w.is_in_danger("Davout")
    return w


@pytest.fixture
def _w5_retreat(_w5_boot):
    return _w5_retreat_board(_w5_boot)


class TestS14EX89:
    """S14E-X89 (the sweep of S14E-X67): a retreat (`_execute_retreat_action`)
    and a FORCED retreat onto allied or neutral soil said nothing of the
    campaign pay the corps now draws.

    Reproduced: "Davout, retreat to Swabia" replied "Davout retreats from
    Rhineland to Swabia. ... Will recover over 2 turns." with no word of EAD-1,
    while the next turn's bill grew by the pay of the thinned corps on Bavaria's
    soil; the broken army "flees to Swabia!" the same way.

    The fix: `campaign_pay_note(world, marshal, new_location, old_location)`
    (X67's line, read after the step so the figure is the figure the bill then
    applies) closes the ordered retreat's reply and the forced retreat's
    report. The AI's retreat text is untouched: the note is the player's corps
    only (`campaign_pay_quote`)."""

    def test_the_ordered_retreat_says_it_and_the_bill_agrees(self, _w5_retreat):
        w = _w5_retreat
        davout = w.get_marshal("Davout")
        before = _w5_pay(w)
        with _w5_client(w) as client:
            out = _w5_say(client, "Davout, retreat to Swabia")
        assert davout.location == "Swabia", out.get("message")
        line = next(ln for ln in out["message"].splitlines()
                    if ln.startswith("Swabia is Bavaria's soil"))
        assert line.startswith("Swabia is Bavaria's soil — the corps standing there are fed "
                               "by contract, about " + _W5_MINUS)
        assert _w5_pay(w) - before == _w5_figure(line) > 0       # shown == applied

    def test_a_retreat_to_home_soil_adds_nothing(self, _w5_retreat):
        w = _w5_retreat
        with _w5_client(w) as client:
            out = _w5_say(client, "Davout, retreat")
        assert w.get_marshal("Davout").location != "Rhineland", out.get("message")
        assert "fed by contract" not in out["message"]

    def test_the_forced_retreat_says_it_and_the_bill_agrees(self, _w5_retreat):
        from backend.commands.executor import CommandExecutor
        w = _w5_retreat
        davout, mack = w.get_marshal("Davout"), w.get_marshal("Mack")
        # The rout's destination is the doctrine's (`get_safe_retreat_destination`,
        # not this row's): hold it on Swabia, the sentence is what is read.
        w.get_safe_retreat_destination = lambda *a, **k: "Swabia"
        before = _w5_pay(w)
        with _w5_quiet():
            msg = CommandExecutor()._combat._apply_forced_retreat_or_break(
                davout, mack, w, skip_fate=True)
        assert davout.location == "Swabia" and "broken army flees to Swabia!" in msg, msg
        line = next(ln for ln in msg.splitlines() if ln.startswith("Swabia is Bavaria's soil"))
        assert _w5_pay(w) - before == _w5_figure(line) > 0
        assert msg.index("flees to Swabia!") < msg.index("Swabia is Bavaria's soil")

    def test_the_forced_retreat_home_is_as_it_was(self, _w5_retreat):
        from backend.commands.executor import CommandExecutor
        w = _w5_retreat
        davout, mack = w.get_marshal("Davout"), w.get_marshal("Mack")
        w.get_safe_retreat_destination = lambda *a, **k: "Lorraine"
        with _w5_quiet():
            msg = CommandExecutor()._combat._apply_forced_retreat_or_break(
                davout, mack, w, skip_fate=True)
        assert "flees to Lorraine!" in msg and "fed by contract" not in msg

    def test_the_ais_retreat_text_is_untouched(self, _w5_retreat):
        """The note reads the player's corps only: an AI corps retreating onto
        a neutral court's soil prints exactly what it printed."""
        from backend.commands.movement_executor import campaign_pay_note
        w = _w5_retreat
        mack = w.get_marshal("Mack")
        assert mack.nation != w.player_nation
        assert campaign_pay_note(w, mack, "Swabia", "Lorraine") == ""

    def test_the_pay_rides_the_replies_not_the_state(self, _w5_retreat):
        """No serialized field: the line is derived from the bill's predicate."""
        w = _w5_retreat
        text = json.dumps(w.to_dict(), default=str)
        assert "campaign_pay_note" not in text and "fed by contract" not in text


# ══════════════════════════════════════════════════════════════════════════
# S14E-X132 - the reckless charge's own rout says the pay (XD7's sweep)
# ══════════════════════════════════════════════════════════════════════════

def _w5_charge(boot, seed: int, mack_strength: int, mack_morale=None, murat_morale=None):
    """Murat (22,000, reckless cavalry) auto-charges Mack on Swabia - Bavaria's
    soil, our ally's - and the loser's rout is held on Munich (Bavaria's too):
    `get_safe_retreat_destination` is the doctrine's, not this row's."""
    import random
    w = _w5_world(boot)
    murat, mack = w.get_marshal("Murat"), w.get_marshal("Mack")
    murat.recklessness = 4
    if murat_morale is not None:
        murat.morale = murat_morale
    mack.location, mack.strength = "Swabia", mack_strength
    if mack_morale is not None:
        mack.morale = mack_morale
    w.get_marshal("Kutuzov").location = "Podolia"
    _w5_see(w)
    w.get_safe_retreat_destination = lambda *a, **k: "Munich"
    random.seed(seed)
    with _w5_quiet():
        events = w._process_reckless_cavalry_turn_start()
    return w, murat, mack, str(events[0].get("message") or "") if events else ""


class TestS14EX132:
    """S14E-X132 (the sweep of S14E-X89): the reckless cavalry's AUTO-CHARGE
    (`WorldState._process_reckless_cavalry_turn_start`, the simplified
    forced-retreat arms) routs a corps onto allied soil with the same silence
    - and the charger's own rout is the player's, unasked and free.

    Reproduced: Murat (22,000, morale 40) auto-charging Mack's 24,000 on
    Swabia broke and "Murat's broken army flees to Munich!" - Bavaria's soil -
    said nothing of the pay the corps now draws there.

    The fix: both arms append `campaign_pay_line` (X67's sentence) to the
    rout's sentence, read after the move; the AI's rout is untouched."""

    def test_the_chargers_own_rout_says_it_and_the_bill_agrees(self, _w5_boot):
        found = 0
        for seed in range(1, 7):
            w, murat, _mack, msg = _w5_charge(_w5_boot, seed, 24000, murat_morale=40)
            if "Murat's broken army flees to Munich!" not in msg:
                continue
            found += 1
            pay = re.search(r"Munich is Bavaria's soil .*? a turn\.", msg)
            assert pay, msg
            after = _w5_pay(w)
            murat.location = "Franche-Comte"
            assert after - _w5_pay(w) == _w5_figure(pay.group(0)) > 0, (seed, msg)
        assert found >= 3, f"the charger's rout was reached on only {found}/6 seeds - the pin is vacuous"

    def test_the_ais_rout_is_untouched(self, _w5_boot):
        """Mack (Austria) routed onto Bavaria's soil: exactly the sentence it was."""
        found = 0
        for seed in range(1, 7):
            _w, _murat, _mack, msg = _w5_charge(_w5_boot, seed, 22000, 30)
            if "Mack's broken army flees to Munich!" not in msg:
                continue
            found += 1
            tail = msg.split("Mack's broken army flees to Munich!", 1)[1]
            assert "Munich is Bavaria's soil" not in msg and "fed by contract" not in tail.split("Swabia")[0]
        assert found >= 3, f"the defender's rout was reached on only {found}/6 seeds - the pin is vacuous"

    def test_both_arms_read_the_one_sentence(self):
        src = (_W5_ROOT / "backend" / "models" / "world_state.py").read_text(encoding="utf-8")
        assert src.count("campaign_pay_line as _ac_pay") == 2
        assert "_ac_pay(self, enemy, retreat_to, old_enemy_loc)" in src
        assert "_ac_pay(self, marshal, retreat_to, old_atk_loc)" in src

# ========== S14f part 2 - merged from test_s14f_p2_w6.py ==========

_W6_ROOT = Path(__file__).resolve().parent.parent
_W6_SCENARIO = _W6_ROOT / "godot-client/project-sovereign/assets/maps/europe_1805.json"


@contextlib.contextmanager
def _w6_quiet():
    with contextlib.redirect_stdout(io.StringIO()):
        yield


@pytest.fixture(scope="module")
def _w6_boot():
    from backend.models.world_state import WorldState
    with _w6_quiet():
        return WorldState.from_scenario(str(_W6_SCENARIO))


def _w6_copy(world):
    from backend.models.world_state import WorldState
    with _w6_quiet():
        return WorldState.from_dict(json.loads(json.dumps(world.to_dict(), default=str)))


@pytest.fixture
def _w6_world(_w6_boot):
    return _w6_copy(_w6_boot)


# ══════════════════════════════════════════════════════════════════════════
# S14E-X118 — every battle restarts Europe's armed-peace fuse
# ══════════════════════════════════════════════════════════════════════════

def _w6_mk(name, location, strength, nation, **kw):
    from backend.models.marshal import Marshal
    return Marshal(name=name, location=location, strength=strength,
                   personality=kw.pop("personality", "aggressive"),
                   nation=nation, spawn_location=location, **kw)


def _w6_fixture_world(turn=12):
    """The legacy fixture world, France at WAR with Britain, turn 12, no
    battle fought yet — the French court's quiet count reads 12."""
    from backend.models.world_state import WorldState
    with _w6_quiet():
        w = WorldState()
    w.current_turn = turn
    w.diplomatic_states[w._make_diplo_key("France", "Britain")] = "WAR"
    return w


def _w6_garrison_world(garrison):
    w = _w6_fixture_world()
    w.marshals.clear()
    for name in ("Ney", "Davout", "Soult"):
        w.marshals[name] = _w6_mk(name, "Paris", 30000, "France")
    target = w.get_region("Belgium")
    target.controller = "Britain"
    target.garrison_strength = garrison
    target.garrison_detachment = False
    return w, target


def _w6_assault(garrison):
    from backend.commands.combat_executor import CombatExecutor
    from backend.commands.executor import CommandExecutor
    w, target = _w6_garrison_world(garrison)
    with _w6_quiet():
        res = CombatExecutor(CommandExecutor())._resolve_garrison_combat(
            w.get_marshal("Ney"), target, w, {"world": w})
    assert res["success"], res
    return w, res


def _w6_quiet_turns(world, court="France"):
    from backend.game_logic import coalition as CO
    return CO.hegemon_quiet_turns(world, court)


class TestS14EX118:
    """Only the main attack path stamped the court's last battle
    (`stamp_battle_turn`, S14E-35); a garrison assault, a hold fight, a charge
    never restarted Europe's armed-peace fuse, so a France that fought only
    those read "quiet".

    Reproduced (the fixture world, turn 12, France at war with Britain): a
    garrison assault that falls (3,000 defenders) and one that holds (40,000),
    a Glorious Charge on Wellington — each left `last_battle_turn_by_nation`
    EMPTY and `hegemon_quiet_turns(world, "France")` at 12. A bombardment
    correctly left it there too.

    The fix: `_post_combat_pipeline` stamps BOTH sides' courts (step 6.5) for
    every non-bombardment battle, through the one writer; the main attack
    path's own pair-stamp at the W6-1 block moved INTO the pipeline (the
    reinforcers' stamps, which the pipeline cannot see, stay with W6-1).
    """

    def test_a_garrison_assault_that_falls_restarts_the_count(self):
        w, res = _w6_assault(3000)
        assert w.get_marshal("Ney").location == "Belgium", "the garrison fell and he advanced"
        assert _w6_quiet_turns(w) == 0
        assert w.last_battle_turn_by_nation == {"France": 12, "Britain": 12}

    def test_a_garrison_that_holds_restarts_the_count(self):
        w, res = _w6_assault(40000)
        assert "holds" in res["message"]
        assert _w6_quiet_turns(w) == 0
        assert w.last_battle_turn_by_nation == {"France": 12, "Britain": 12}

    def test_the_garrison_defender_is_the_provinces_owner_not_the_war_partner(self):
        """The court that FELT the assault is the garrison's controller."""
        from backend.commands.combat_executor import CombatExecutor
        from backend.commands.executor import CommandExecutor
        w, target = _w6_garrison_world(3000)
        target.controller = "Britain"
        w.diplomatic_states[w._make_diplo_key("France", "Prussia")] = "PEACE"
        with _w6_quiet():
            CombatExecutor(CommandExecutor())._resolve_garrison_combat(
                w.get_marshal("Ney"), target, w, {"world": w})
        assert "Prussia" not in w.last_battle_turn_by_nation

    def test_a_glorious_charge_restarts_the_count(self):
        from backend.commands.executor import CommandExecutor
        w = _w6_fixture_world()
        ney = w.get_marshal("Ney")
        ney.cavalry, ney.personality, ney.recklessness = True, "aggressive", 3
        ney.location = "Belgium"
        w.get_marshal("Wellington").location = "Waterloo"
        assert _w6_quiet_turns(w) == 12
        with _w6_quiet():
            res = CommandExecutor()._execute_glorious_charge(ney, "Wellington", w, {"world": w})
        assert res["success"], res
        assert "GLORIOUS CHARGE" in res["message"]
        assert _w6_quiet_turns(w) == 0
        assert w.last_battle_turn_by_nation == {"France": 12, "Britain": 12}

    def test_a_bombardment_does_not(self):
        from unittest.mock import patch
        from backend.commands.executor import CommandExecutor
        from backend.models.marshal import Marshal
        w = _w6_fixture_world()
        art = Marshal(name="ArtRanged", location="Belgium", strength=25000,
                      personality="cautious", nation="France", movement_range=1,
                      tactical_skill=7, artillery=True, spawn_location="Belgium")
        w.marshals["ArtRanged"] = art
        with patch("random.uniform", return_value=1.0), _w6_quiet():
            res = CommandExecutor()._execute_attack(art, "Wellington", w, {"world": w})
        assert res.get("action") == "bombardment", res
        assert w.last_battle_turn_by_nation == {}
        assert _w6_quiet_turns(w) == 12

    def test_the_pipeline_skips_a_bombardment_and_stamps_the_rest(self):
        """The pipeline itself, called directly: the ranged bombardment is the
        one flag that does not restart the fuse."""
        from backend.commands.combat_executor import CombatExecutor
        from backend.commands.executor import CommandExecutor
        for flag, stamps in (("is_bombardment", False), ("is_garrison", True),
                             ("is_glorious_charge", True),
                             ("is_auto_bombardment_kill", True), (None, True)):
            w = _w6_fixture_world()
            ney, wel = w.get_marshal("Ney"), w.get_marshal("Wellington")
            ctx = {
                "attacker": ney, "defender": wel, "defender_nation": "Britain",
                "battle_region": "Belgium", "outcome": "attacker_victory",
                "attacker_won": True, "defender_won": False,
                "attacker_casualties": 100, "defender_casualties": 100,
                "pre_battle_attacker_strength": 10000,
                "pre_battle_defender_strength": 10000,
                "battle_result": None, "conquered": False,
            }
            if flag:
                ctx[flag] = True
            with _w6_quiet():
                CombatExecutor(CommandExecutor())._post_combat_pipeline(ctx, w)
            assert bool(w.last_battle_turn_by_nation) is stamps, (flag, w.last_battle_turn_by_nation)
            if stamps:
                assert w.last_battle_turn_by_nation == {"France": 12, "Britain": 12}, flag

    def test_the_main_attack_stamps_each_court_once(self):
        """The pipeline is the ONE stamp site for the pair: the main attack
        path must not stamp them a second time (the W6-1 block keeps only
        the reinforcers, who are not the pair)."""
        from backend.commands.executor import CommandExecutor
        w = _w6_fixture_world()
        w.marshals.clear()
        ney = _w6_mk("Ney", "Belgium", 30000, "France")
        wel = _w6_mk("Wellington", "Waterloo", 30000, "Britain")
        w.marshals["Ney"], w.marshals["Wellington"] = ney, wel
        calls = []
        real = w.stamp_battle_turn

        def spy(nation, turn):
            calls.append((nation, turn))
            return real(nation, turn)

        w.stamp_battle_turn = spy
        with _w6_quiet():
            res = CommandExecutor()._execute_attack(ney, "Wellington", w, {"world": w})
        assert res.get("success"), res
        assert ney.last_battle_turn == 12 and wel.last_battle_turn == 12, "W6-1 marshal stamps stand"
        assert sorted(calls) == [("Britain", 12), ("France", 12)], calls
        assert _w6_quiet_turns(w) == 0

    def test_a_reinforcer_of_the_pairs_own_court_does_not_stamp_it_twice(self):
        """Uxbridge arrives at Waterloo to stand with Wellington (his own
        court's stamp is the pipeline's, not the W6-1 block's second one)."""
        from backend.commands.executor import CommandExecutor
        w = _w6_fixture_world()
        for name in list(w.marshals):
            if name not in ("Ney", "Wellington", "Uxbridge"):
                del w.marshals[name]
        w.get_marshal("Ney").location = "Belgium"
        w.get_marshal("Wellington").location = "Waterloo"
        w.get_marshal("Uxbridge").location = "Netherlands"
        w._build_marshal_index()
        calls = []
        real = w.stamp_battle_turn

        def spy(nation, turn):
            calls.append((nation, turn))
            return real(nation, turn)

        w.stamp_battle_turn = spy
        with _w6_quiet():
            res = CommandExecutor()._execute_attack(w.get_marshal("Ney"), "Wellington", w, {"world": w})
        assert res.get("success"), res
        uxbridge = w.get_marshal("Uxbridge")
        assert uxbridge.location == "Waterloo" and uxbridge.last_battle_turn == 12, "he arrived and fought"
        assert sorted(calls) == [("Britain", 12), ("France", 12)], calls

    def test_a_shipped_board_main_attack_still_stamps_the_pair(self, _w6_world):
        """S14E-35's own board, through the executor: Massena's first step
        fights Archduke John — both courts stamped, once each."""
        from backend.commands.executor import CommandExecutor
        w = _w6_world
        w.current_turn = 19
        massena = w.get_marshal("Massena")
        massena.location = "Bohemia"
        w.calculate_visibility()
        calls = []
        real = w.stamp_battle_turn

        def spy(nation, turn):
            calls.append((nation, turn))
            return real(nation, turn)

        w.stamp_battle_turn = spy
        with _w6_quiet():
            result = CommandExecutor().execute({
                "command": {"raw_input": "Massena, move Milan", "marshal": "Massena",
                            "action": "move", "target": "Milan"},
                "is_strategic": True, "strategic_type": "MOVE_TO",
            }, {"world": w})
        assert result.get("first_step_combat") is True
        assert sorted(calls) == [("Austria", 19), ("France", 19)], calls
        assert w.last_battle_turn_by_nation == {"France": 19, "Austria": 19}

    def test_the_stamp_is_one_pipeline_site_and_one_reinforcer_site(self):
        src = (_W6_ROOT / "backend/commands/combat_executor.py").read_text(encoding="utf-8")
        assert len(re.findall(r"ctx\.world\.stamp_battle_turn\(ctx\.marshal\.nation", src)) == 0, \
            "the main attack path no longer stamps the pair itself"
        assert len(re.findall(r"ctx\.world\.stamp_battle_turn\(_fighter\.nation", src)) == 0
        assert len(re.findall(r"ctx\.world\.stamp_battle_turn\(_court, _w6_turn\)", src)) == 1
        body = src.split("def _post_combat_pipeline")[1].split("def _resolve_garrison_combat")[0]
        assert body.count("self._stamp_battle_clock(world, attacker.nation, defender_nation)") == 1, \
            "the pipeline stamps the pair, once"
        helper = src.split("def _stamp_battle_clock")[1].split("def _post_combat_pipeline")[0]
        assert helper.count("world.stamp_battle_turn(") == 2, "the helper writes both courts"

    def test_the_marshal_field_is_left_to_the_main_path(self):
        """Decision on record: a garrison assault / charge stamps the COURT
        (the store the fuse reads), not the marshal's own `last_battle_turn`
        — that field's only reader is the roster fallback, and the series arm
        swaps the store for exactly that fallback."""
        w, _res = _w6_assault(3000)
        assert w.get_marshal("Ney").last_battle_turn == -1
        assert w.get_marshal("Davout").last_battle_turn == -1


# ══════════════════════════════════════════════════════════════════════════
# S14E-X129 — the auto-charge outside the pipeline never stamped either
# ══════════════════════════════════════════════════════════════════════════

class TestS14EX129:
    """`WorldState._process_reckless_cavalry_turn_start` is the one combat path
    outside `_post_combat_pipeline` (GE-1's comment); it mirrors the pipeline's
    recordings by hand and never mirrored the armed-peace stamp, so a reckless
    cavalry corps' turn-start charge left Europe's fuse unlit.

    Reproduced (the shipped board, turn 12): Murat's auto-charge on Mack at
    Lorraine won, the store stayed empty, France's quiet count read 12.
    """

    def test_a_turn_start_auto_charge_restarts_the_count(self, _w6_world):
        import random
        w = _w6_world
        w.current_turn = 12
        murat, mack = w.get_marshal("Murat"), w.get_marshal("Mack")
        murat.recklessness = 4
        mack.location, mack.strength = "Lorraine", 3000
        for name in ("Soult", "Napoleon"):
            w.get_marshal(name).location = "Paris"
        w._build_marshal_index()
        w.invalidate_active_nations_cache()
        w.calculate_visibility()
        assert w.last_battle_turn_by_nation == {}
        random.seed(1)
        with _w6_quiet():
            out = w._process_reckless_cavalry_turn_start()
        assert any(r.get("type") == "auto_glorious_charge" for r in out), out
        assert w.last_battle_turn_by_nation == {"France": 12, "Austria": 12}
        assert _w6_quiet_turns(w) == 0


# ══════════════════════════════════════════════════════════════════════════
# S14E-X110 — a Reassure Ally mission ends the tick its alliance is gone
# ══════════════════════════════════════════════════════════════════════════

def _w6_set_state(w, a, b, state):
    w.diplomatic_states[w._make_diplo_key(a, b)] = state
    w.invalidate_bloc_members_cache()


def _w6_rel(w, a, b):
    return int(w.nation_relations.get(w._make_diplo_key(a, b), 0) or 0)


def _w6_begin(w, mission_type, target, dp=10):
    """Drive the REAL `start_mission` dialogue arm (the executor writes the dict)."""
    from backend.commands.executor import CommandExecutor
    from backend.game_logic.diplomatic_dialogue import MISSION_DP_COSTS
    w.dialogue_manager.replace({
        "type": "mission", "target_nation": target, "talleyrand_text": "Very well, Sire.",
        "options": [
            {"label": "Begin mission", "description": "Start.", "action": "start_mission",
             "terms": {"mission_type": mission_type, "target_nation": target}},
            {"label": "Dismiss", "description": "Cancel.", "action": "dismiss"},
        ],
        "context": {"dp_cost_per_turn": int(MISSION_DP_COSTS[mission_type])},
        "turn_created": int(w.current_turn), "blocking": False,
    })
    w.diplomatic_points = max(int(w.diplomatic_points), dp)
    with _w6_quiet():
        out = CommandExecutor()._diplomatic.handle_diplomatic_dialogue_response(1, {"world": w})
    assert out.get("success"), out
    return w.active_diplomatic_mission


def _w6_tick(w, dp=10):
    from backend.game_logic import diplomacy as D
    w.diplomatic_points = dp
    with _w6_quiet():
        return D.process_diplomacy_turn(w)


class TestS14EX110:
    """A Reassure Ally mission ran on, billing 1 DP a turn and writing +6 on
    the relation, after its alliance was gone.

    Reproduced (the shipped board, France-Spain ALLIANCE at boot, the real
    `start_mission` arm for Reassure Ally, then the pair at WAR and three
    `process_diplomacy_turn` ticks): the mission stayed LIVE (`completed`
    absent), `turns_active` 0 -> 3 (3 DP billed) and the relation climbed
    40 -> 52 at war; the slide to a defensive alliance (S14E-11's sighting)
    read the same.
    """

    def test_a_mission_begun_in_the_alliance_records_it(self, _w6_world):
        w = _w6_world
        assert w.get_diplomatic_state("France", "Spain") == "ALLIANCE"
        mission = _w6_begin(w, "REASSURE_ALLY", "Spain")
        assert mission["started_state"] == "ALLIANCE"

    def test_a_mission_begun_elsewhere_records_nothing(self, _w6_world):
        w = _w6_world
        _w6_set_state(w, "France", "Spain", "DEFENSIVE_ALLIANCE")
        mission = _w6_begin(w, "REASSURE_ALLY", "Spain")
        assert "started_state" not in mission, mission

    def test_the_slide_to_a_defensive_alliance_ends_the_mission_and_bills_nothing(self, _w6_world):
        w = _w6_world
        _w6_begin(w, "REASSURE_ALLY", "Spain")
        _w6_set_state(w, "France", "Spain", "DEFENSIVE_ALLIANCE")
        events = _w6_tick(w)
        mission = w.active_diplomatic_mission
        assert mission["completed"] is True and mission["end_reason"] == "lapsed", mission
        assert mission["turns_active"] == 0, "the tick that finds the lapse bills no DP"
        (done,) = [e for e in events if e.get("type") == "diplomatic_mission_completed"]
        assert done["reason"] == "lapsed"
        assert done["message"] == "The alliance with Spain has lapsed — Talleyrand is home."
        before = _w6_rel(w, "France", "Spain")
        for _ in range(3):
            _w6_tick(w)
        assert w.active_diplomatic_mission["turns_active"] == 0
        assert int(w.active_diplomatic_mission.get("earned") or 0) == 0
        assert _w6_rel(w, "France", "Spain") <= before, "no more +6 a tick for a lapsed alliance"
        assert w.talleyrand_state == "IDLE"

    def test_war_ends_the_mission_in_its_own_words(self, _w6_world):
        w = _w6_world
        _w6_begin(w, "REASSURE_ALLY", "Spain")
        _w6_set_state(w, "France", "Spain", "WAR")
        events = _w6_tick(w)
        mission = w.active_diplomatic_mission
        assert mission["completed"] is True and mission["end_reason"] == "war", mission
        assert mission["turns_active"] == 0
        (done,) = [e for e in events if e.get("type") == "diplomatic_mission_completed"]
        assert done["reason"] == "war"
        assert done["message"] == "France and Spain are at war — Talleyrand is home."
        for _ in range(3):
            _w6_tick(w)
        assert w.active_diplomatic_mission["turns_active"] == 0

    def test_the_end_is_told_on_the_rail_the_log_and_the_dispatch(self, _w6_world):
        from backend.campaign_log import format_event_oneliner
        from backend.game_logic.dispatch import _build_diplomatic_events_section
        for state, reason, words, phrase in (
                ("DEFENSIVE_ALLIANCE", "lapsed",
                 "The alliance with Spain has lapsed — Talleyrand is home.", "the alliance lapsed"),
                ("WAR", "war",
                 "France and Spain are at war — Talleyrand is home.", "war broke the alliance")):
            w = _w6_copy(_w6_world)
            _w6_begin(w, "REASSURE_ALLY", "Spain")
            _w6_set_state(w, "France", "Spain", state)
            w.pending_dispatch_events = []
            _w6_tick(w)
            rows = [n for n in w.notifications.get_pending() if n.get("type") == "diplomatic_mission"]
            assert len(rows) == 1 and words in rows[0]["message"], rows
            assert rows[0]["details"]["beat"] == "completed"
            ended = [e for e in w.event_log if e.get("type") == "diplomatic_mission_ended"]
            assert ended and ended[-1]["reason"] == reason
            assert phrase in format_event_oneliner(ended[-1])
            with _w6_quiet():
                events = _build_diplomatic_events_section(w, "France")
            (beat,) = [e for e in events if e["type"] == "diplomatic_mission_completed"]
            assert beat["priority"] == "MEDIUM"
            assert words in beat["text"], beat

    def test_the_last_mission_line_reads_the_new_reasons(self, _w6_world):
        from backend.game_logic.ledger import build_cabinet
        for state, phrase in (("DEFENSIVE_ALLIANCE", "the alliance lapsed"),
                              ("WAR", "war broke the alliance")):
            w = _w6_copy(_w6_world)
            _w6_begin(w, "REASSURE_ALLY", "Spain")
            _w6_set_state(w, "France", "Spain", state)
            _w6_tick(w)
            cabinet = build_cabinet(w)
            assert cabinet["live"] is False
            assert cabinet["last"]["reason_phrase"] == phrase, cabinet

    def test_the_desk_is_free_for_the_next_mission(self, _w6_world):
        from backend.game_logic import diplomacy as D
        w = _w6_world
        _w6_begin(w, "REASSURE_ALLY", "Spain")
        assert D.mission_gate(w, "GATHER_INTEL") == (False, "Mission already active")
        _w6_set_state(w, "France", "Spain", "DEFENSIVE_ALLIANCE")
        _w6_tick(w)
        assert D.mission_gate(w, "GATHER_INTEL") == (True, "")

    def test_the_auto_downgrade_that_breaks_the_alliance_ends_it_on_that_tick(self, _w6_world):
        """Step 13 slides the alliance AFTER the head-of-tick read: the
        second read (as the undermine twin's) closes it the same tick."""
        w = _w6_world
        key = w._make_diplo_key("France", "Spain")
        _w6_begin(w, "REASSURE_ALLY", "Spain")
        w.nation_relations[key] = -30
        w.turns_below_threshold[key] = 4
        _w6_tick(w)
        assert w.get_diplomatic_state("France", "Spain") == "DEFENSIVE_ALLIANCE", "the slide landed"
        mission = w.active_diplomatic_mission
        assert mission["completed"] is True and mission["end_reason"] == "lapsed", mission

    def test_an_alliance_that_stands_leaves_the_mission_at_work(self, _w6_world):
        w = _w6_world
        _w6_begin(w, "REASSURE_ALLY", "Spain")
        for _ in range(3):
            _w6_tick(w)
        mission = w.active_diplomatic_mission
        assert not mission.get("completed") and mission["turns_active"] == 3, mission
        assert "end_reason" not in mission

    def test_a_mission_begun_at_a_defensive_alliance_is_untouched(self, _w6_world):
        w = _w6_world
        _w6_set_state(w, "France", "Spain", "DEFENSIVE_ALLIANCE")
        _w6_begin(w, "REASSURE_ALLY", "Spain")
        _w6_set_state(w, "France", "Spain", "WAR")
        _w6_tick(w)
        assert not w.active_diplomatic_mission.get("completed")

    def test_an_old_save_without_the_key_runs_as_it_did(self, _w6_world):
        w = _w6_world
        mission = _w6_begin(w, "REASSURE_ALLY", "Spain")
        mission.pop("started_state")
        _w6_set_state(w, "France", "Spain", "DEFENSIVE_ALLIANCE")
        _w6_tick(w)
        assert not w.active_diplomatic_mission.get("completed")

    def test_other_missions_are_not_of_the_class(self, _w6_world):
        """Improve Relations (S14E-34) and Court Nation read their own rules."""
        w = _w6_world
        mission = _w6_begin(w, "COURT_NATION", "Spain")
        assert "started_state" not in mission
        _w6_set_state(w, "France", "Spain", "DEFENSIVE_ALLIANCE")
        _w6_tick(w)
        assert not w.active_diplomatic_mission.get("completed")

    def test_the_new_end_survives_a_save(self, _w6_world):
        w = _w6_world
        _w6_begin(w, "REASSURE_ALLY", "Spain")
        saved = _w6_copy(w)
        assert saved.active_diplomatic_mission["started_state"] == "ALLIANCE"
        _w6_set_state(saved, "France", "Spain", "WAR")
        _w6_tick(saved)
        again = _w6_copy(saved)
        assert again.active_diplomatic_mission["end_reason"] == "war"
        assert again.active_diplomatic_mission["completed"] is True

    def test_the_save_reference_documents_the_two_values(self):
        text = (_W6_ROOT / "docs/SAVE_FORMAT_REFERENCE.md").read_text(encoding="utf-8")
        row = next(line for line in text.splitlines() if line.startswith("| `active_diplomatic_mission`"))
        assert '"lapsed"' in row and '"war"' in row and "REASSURE_ALLY" in row

