@pytest.fixture
def _w7_client(monkeypatch):
    """The in-process HTTP idiom: `M.world`, `M.game_state["world"]` and the
    parser swapped together. Returns a function that seats a world."""
    import backend.main as M
    from backend.commands.parser import CommandParser
    from fastapi.testclient import TestClient
    for key in ("SOVEREIGN_SCENARIO", "SOVEREIGN_MAP", "SOVEREIGN_SMOKE_START"):
        monkeypatch.delenv(key, raising=False)
    monkeypatch.setenv("LLM_MODE", "mock")
    monkeypatch.setattr(M, "parser", CommandParser(use_real_llm=False))

    def _seat(world):
        monkeypatch.setattr(M, "world", world)
        monkeypatch.setitem(M.game_state, "world", world)
        return TestClient(M.app)
    return _seat


def _w7_quiet(fn, *args, **kwargs):
    with contextlib.redirect_stdout(io.StringIO()):
        return fn(*args, **kwargs)


def _w7_post(client, body: dict) -> dict:
    with contextlib.redirect_stdout(io.StringIO()):
        return client.post("/command", json=body).json()


def _w7_reading(w, court: str = "Britain") -> dict:
    from backend.game_logic import counsel as CS
    return _w7_quiet(CS.read_counsel, w, court)


def _w7_preview(w, court: str = "Britain") -> dict:
    from backend.game_logic.diplomacy import get_diplomatic_preview
    return _w7_quiet(get_diplomatic_preview, w, court)


def _w7_table_rows(preview: dict) -> list:
    return [a for a in preview["actions"] if a.get("action") == "open_settlement"]


_W7_LEVER_FUNDED = (
    "A payment of 875 gold to Britain would carry the table with her alone. "
    "At the table: Open Settlement with Britain alone, then Offer gold to "
    "Britain, 875 or more (the + and - on its line move it by 100).")


# ══════════════════════════════════════════════════════════════════════════
# S14E-X124 — a truce page prices a table road the page has no row for
# ══════════════════════════════════════════════════════════════════════════

class TestS14EX124:
    """Reproduced (before the fix, on the shipped 1805 board, France's war on
    Britain ended in a truce): the counsel's roads line reads "Propose Peace —
    4 of 50 ✗ (2 DP)", "Open Settlement with Britain alone — -8 of 50 ✗" and
    "the whole table — -8 of 50 ✗" while the Britain page carries NO
    `open_settlement` row (the executor refuses it: "We are not at war with
    Britain, Sire."). `read_counsel` appended the table roads for WAR and
    ARMISTICE alike; the table exists only at a WAR."""

    def test_a_truce_reading_carries_no_table_road(self, _w7_truce_world):
        reading = _w7_reading(_w7_truce_world)
        assert reading["state"] == "ARMISTICE" and reading["truce"] is True
        roads = [r["road"] for r in reading["roads"]]
        assert roads == ["send_peace"], roads

    def test_the_roads_line_prices_only_the_roads_the_page_carries(self, _w7_truce_world):
        from backend.game_logic import counsel as CS
        w = _w7_truce_world
        out = _w7_quiet(CS.counsel_for_wizard, w, "Britain", remember=False)
        shown = " | ".join(out["roads_display"])
        assert "Open Settlement" not in shown and "whole table" not in shown, shown
        assert [r["road"] for r in out["roads"]] == ["send_peace"]
        assert not out["best_road"].startswith("table") and out["best_coverage"] == []
        # the page: no table row, so no road to name one
        preview = _w7_preview(w)
        assert _w7_table_rows(preview) == []
        assert [r["road"] for r in preview["counsel_roads"]] == ["send_peace"]
        assert all("Open Settlement" not in s for s in preview["counsel_roads_display"])

    def test_the_executor_refuses_the_table_the_old_roads_line_priced(
            self, _w7_truce_world, _w7_client):
        """The other half of the sighting: what the old line would have sent
        the player to is refused."""
        client = _w7_client(_w7_truce_world)
        response = _w7_post(client, {"command": "propose common peace with Britain",
                                     "action": "propose_common_peace",
                                     "target_nation": "Britain",
                                     "counsel_coverage": ["Britain"]})
        assert response["success"] is False
        assert response["message"] == "We are not at war with Britain, Sire."

    def test_a_truce_names_no_table_lever_whatever_the_sum(self, _w7_truce_world, monkeypatch):
        """The lever sentence is read off the alone road. With a sum the scorer
        would credit forced onto the dry-run, a truce page still names no
        table; the same sum on a WAR page does."""
        from backend.game_logic import counsel as CS
        monkeypatch.setattr(CS, "_gold_to_carry", lambda *a, **k: 875)
        truce = _w7_reading(_w7_truce_world)
        assert "At the table" not in CS._lever_sentence(truce)
        line = _w7_quiet(CS.compose_counsel_line, truce, None)["line"]
        assert "Open Settlement" not in line and "At the table" not in line, line

    def test_the_second_sentence_does_not_read_the_table_either(self, _w7_truce_world):
        """`_second_sentence` named "The table with Britain alone reads …" off
        the table road when the send was the best road; no road, no sentence."""
        from backend.game_logic import counsel as CS
        reading = _w7_reading(_w7_truce_world)
        assert "table" not in CS._second_sentence(reading).lower()

    def test_a_war_page_is_byte_identical(self, _w7_world):
        """The WAR page is unchanged: the same five roads in the same order,
        the same roads line, the same lever, the same two table rows."""
        from backend.game_logic import counsel as CS
        w = _w7_world
        w.nation_gold["France"] = 3000      # funded: S14E-X126 adds nothing
        reading = _w7_reading(w)
        assert reading["state"] == "WAR"
        assert [r["road"] for r in reading["roads"]] == [
            "table_alone", "table_whole", "send_peace", "truce", "battle"]
        out = _w7_quiet(CS.counsel_for_wizard, w, "Britain", remember=False)
        assert out["roads_display"] == [
            "Open Settlement with Britain alone — 15 of 50 ✗",
            "the whole table — 15 of 50 ✗",
            "Propose Peace — 9 of 50 ✗ (3 DP)",
            "Propose Armistice — 22 of 50 ✗ (1 DP)",
            "a battle — 0 of 15 ✗"]
        assert CS._lever_sentence(reading) == _W7_LEVER_FUNDED
        assert len(_w7_table_rows(_w7_preview(w))) == 2     # the whole table + the lever's

    def test_a_peace_court_has_no_roads_at_all(self, _w7_world):
        """The gate is the pair's state: at PEACE (Prussia) nothing is read."""
        reading = _w7_reading(_w7_world, "Prussia")
        assert reading["state"] == "PEACE" and reading["roads"] == []


# ══════════════════════════════════════════════════════════════════════════
# S14E-X125 — the CN-4 echo-note for the Outbid row (and the lever row) is dead
# ══════════════════════════════════════════════════════════════════════════

def _w7_display_only_keys() -> set:
    src = _w7_src("diplomacy_wizard.gd")
    block = src[src.index("const ECHO_IS_DISPLAY_ONLY"):src.index("func echo_note")]
    return set(re.findall(r'^\t"(\w+)": "', block, re.M))


def _w7_wizard_payload(action_id: str, row: dict, nation: str = "Britain") -> dict:
    """What `diplomacy_wizard._structured_payload_for_action` sends for these
    two rows (pinned against the GDScript source below) — the Python mirror
    the tests drive main.gd's key choice with."""
    if action_id == "outbid_bond":
        data = {"action": "propose_common_peace", "target_nation": nation,
                "echo_key": "outbid_bond"}
        if row.get("counsel_coverage"):
            data["counsel_coverage"] = list(row["counsel_coverage"])
        if int(float(row.get("bond_bid", 0) or 0)) > 0:
            data["bond_bid"] = int(float(row["bond_bid"]))
        return data
    data = {"action": "propose_common_peace", "target_nation": nation}
    if row.get("counsel_coverage"):
        data["counsel_coverage"] = list(row["counsel_coverage"])
    gold = int(float(row.get("gold_offer", 0) or 0))
    if gold > 0:
        data["gold_offer"] = gold
        data["echo_key"] = "open_settlement_offer"
    elif bool(row.get("echo_display_only", False)):
        # S14E-X128: the court alone without a staged sum is display copy too
        data["echo_key"] = "open_settlement_alone"
    return data


def _w7_main_key(data: dict) -> str:
    """The key `main.gd::_on_wizard_structured_command_selected` looks the echo
    note up by: `data.get("echo_key", data.get("action", ""))`."""
    return str(data.get("echo_key", data.get("action", "")))


class TestS14EX125:
    """Reproduced (before the fix): `main.gd` read
    `diplomacy_wizard.echo_note(str(data.get("action", "")))`, and for the
    Outbid row (and the lever row S14E-D7 added) `data["action"]` is
    "propose_common_peace" — `ECHO_IS_DISPLAY_ONLY["outbid_bond"]` never fired:
    the typed echo "propose common peace with Britain" was parked on the
    up-arrow with no disclosure although re-sent it opens the WHOLE table
    without the bid or the sum."""

    # ── the wizard stamps the key; main.gd reads it ──────────────────────

    def test_the_wizard_stamps_the_echo_key_on_both_rows(self):
        src = _w7_src("diplomacy_wizard.gd")
        arm = _w7_func(src, "_structured_payload_for_action")
        # the Outbid row
        outbid = arm[arm.index('if action_id == "outbid_bond":'):
                     arm.index('if action_id == "grant_region_to_vassal":')]
        assert '"echo_key": "outbid_bond"' in outbid
        # the lever row: only the row that stages a sum is a display-only echo
        lever = arm[arm.index('if action_id == "open_settlement":'):
                    arm.index('if action_id == "propose_white_peace":')]
        stamped = lever.index('data["echo_key"] = "open_settlement_offer"')
        assert lever.index('if offer_gold > 0:') < stamped < lever.index("return data")
        # the plain whole-table row and the white peace stay un-stamped
        assert "echo_key" not in arm[arm.index('if action_id == "propose_white_peace":'):
                                    arm.index('if action_id == "outbid_bond":')]
        # tests/test_settlement_ui_slice_f_source.py: the helper's body never
        # says the word the emit signal is named for - not in a comment either
        assert "S14E-X125" in arm

    def test_main_reads_the_echo_key_before_the_action(self):
        body = _w7_func(_w7_src("main.gd"), "_on_wizard_structured_command_selected")
        assert 'diplomacy_wizard.echo_note(str(data.get("echo_key", data.get("action", ""))))' in body
        # read first, then the key is dropped from the wire (state clearing
        # AFTER reading); the request model never learns the display key
        read = body.index('data.get("echo_key"')
        erase = body.index('data.erase("echo_key")')
        gate = body.index('if echo_note == "":')
        sent = body.index("api_client.send_structured_command")
        assert read < erase < sent
        assert body.index("_add_to_history(command)") > gate

    def test_the_lever_row_is_registered_as_a_display_only_echo(self):
        keys = _w7_display_only_keys()
        # S14E-X128: + "open_settlement_alone" (the court alone, no sum staged)
        assert keys == {"propose_white_peace", "outbid_bond", "open_settlement_offer",
                        "open_settlement_alone"}, keys
        src = _w7_src("diplomacy_wizard.gd")
        line = next(l for l in src.splitlines() if l.startswith('\t"open_settlement_offer": "'))
        # the disclosure says what the typed line does instead
        assert "whole table" in line and "without" in line

    # ── the key main.gd looks up now finds the note ──────────────────────

    def test_the_outbid_payload_finds_its_note_and_the_old_lookup_missed(self):
        row = {"counsel_coverage": ["Austria"], "bond_bid": 1000}
        data = _w7_wizard_payload("outbid_bond", row, "Austria")
        assert data["action"] == "propose_common_peace"
        assert data["action"] not in _w7_display_only_keys()      # the dead lookup
        assert _w7_main_key(data) == "outbid_bond"
        assert _w7_main_key(data) in _w7_display_only_keys()

    def test_the_lever_payload_finds_its_note(self, _w7_world):
        w = _w7_world
        w.nation_gold["France"] = 3000
        row = next(a for a in _w7_table_rows(_w7_preview(w))
                   if list(a.get("counsel_coverage") or []) == ["Britain"])
        data = _w7_wizard_payload("open_settlement", row)
        assert data["gold_offer"] == int(row["gold_offer"]) and data["gold_offer"] > 0
        assert data["action"] not in _w7_display_only_keys()      # the dead lookup
        assert _w7_main_key(data) == "open_settlement_offer"
        assert _w7_main_key(data) in _w7_display_only_keys()

    def test_the_rows_that_are_not_display_only_keep_their_lookup(self, _w7_world):
        """The whole-table row sends no `echo_key`, so main.gd falls back to
        the action — not in the display-only set, parked on the up-arrow as
        before (its typed form IS its order). S14E-X128 flipped the second
        half of this pin: a lever row the treasury cannot fund (no
        `gold_offer`) is still the court ALONE, which its typed echo is not -
        it carries `echo_display_only` and the key `open_settlement_alone`."""
        w = _w7_world       # 800 gold: the lever row carries no gold_offer
        preview = _w7_preview(w)
        tables = _w7_table_rows(preview)
        assert len(tables) == 2
        for row in tables:
            assert "gold_offer" not in row
            data = _w7_wizard_payload("open_settlement", row)
            if list(row.get("counsel_coverage") or []) == ["Britain"]:
                assert row["echo_display_only"] is True
                assert _w7_main_key(data) == "open_settlement_alone"
                assert _w7_main_key(data) in _w7_display_only_keys()
                continue
            assert "echo_key" not in data
            assert _w7_main_key(data) not in _w7_display_only_keys()

    # ── the census's rule stays true: an echo that cannot be typed is display-only ──

    def test_the_lever_echo_typed_opens_the_whole_table_without_the_sum(
            self, _w7_boot, _w7_client):
        """Why the note is honest: the structured send opens the court alone
        with the sum staged; the echo re-typed from the up-arrow opens the
        whole table and stages nothing."""
        echo = "propose common peace with Britain"

        def _board():
            w = _w7_copy(_w7_boot)
            w.diplomatic_points = 30
            _w7_scores(w)
            w.nation_gold["France"] = 3000
            return w

        w = _board()
        row = next(a for a in _w7_table_rows(_w7_preview(w))
                   if list(a.get("counsel_coverage") or []) == ["Britain"])
        data = _w7_wizard_payload("open_settlement", row)
        structured = _w7_post(_w7_client(w), {"command": echo, **data})
        sd = structured["diplomatic_dialogue"]
        assert sd["covered_enemy_participants"] == ["Britain"]
        staged = [t for t in sd["settlement_terms"] if t.get("type") == "gold_indemnity"]
        assert [int(t["amount"]) for t in staged] == [int(row["gold_offer"])]
        # a fresh board, the echo alone (what the up-arrow re-sends)
        typed = _w7_post(_w7_client(_board()), {"command": echo})
        td = typed["diplomatic_dialogue"]
        assert sorted(td["covered_enemy_participants"]) == ["Austria", "Britain", "Russia"]
        assert [t for t in td["settlement_terms"] if t.get("type") == "gold_indemnity"] == []

    def test_the_census_drives_the_key_main_reads(self):
        """tests/test_cn4_the_chip_honesty_census.py composes the structured
        payload for each case; it must key the display-only decision the way
        main.gd does (`echo_key`, else the action) — with the dead lookup
        retired, the census's set is the three keys the wizard registers."""
        src = (_W7_ROOT / "tests" / "test_cn4_the_chip_honesty_census.py").read_text(encoding="utf-8")
        assert "S14E-X125" in src and "def _echo_key" in src
        assert '"open_settlement_offer"' in src and '"echo_key"' in src


# ══════════════════════════════════════════════════════════════════════════
# S14E-X126 — the lever quotes a sum the chest cannot fund, without the chest
# ══════════════════════════════════════════════════════════════════════════

class TestS14EX126:
    """Reproduced (before the fix, on the shipped opening — France holding 800
    gold, the Britain table alone short of the line at 20 / 20 / 20): the
    counsel says "A payment of 875 gold to Britain would carry the table with
    her alone. At the table: … Offer gold to Britain, 875 or more …" and the
    Cabinet's lever row (`cabinet_rows.lever_table_actions`) carries no
    `gold_offer` and reads "the treasury can fund 800" — the sentence promised
    a payment the chest could not make and never said so."""

    def test_the_short_chest_is_named_in_the_sentence(self, _w7_world):
        from backend.game_logic import counsel as CS
        w = _w7_world
        assert int(w.nation_gold["France"]) == 800
        reading = _w7_reading(w)
        alone = next(r for r in reading["roads"] if r["road"] == "table_alone")
        assert int(alone["gold_to_carry"]) == 875
        lever = CS._lever_sentence(reading)
        assert "the treasury holds 800" in lever, lever
        # the words S14E-8 and S14E-D7 pinned stand
        assert lever.startswith("A payment of 875 gold to Britain would carry the table with her alone. ")
        assert "At the table: Open Settlement with Britain alone, then Offer gold to Britain, 875 or more" in lever
        assert "move it by 100" in lever
        line = _w7_quiet(CS.compose_counsel_line, reading, None)["line"]
        assert "the treasury holds 800" in line

    def test_the_funded_sentence_is_byte_identical(self, _w7_world):
        from backend.game_logic import counsel as CS
        w = _w7_world
        w.nation_gold["France"] = 3000
        assert CS._lever_sentence(_w7_reading(w)) == _W7_LEVER_FUNDED

    def test_the_sentences_chest_is_the_rows_chest(self, _w7_world):
        """Shown == applied: the figure the sentence prints is the one the
        Cabinet's lever row prints (both read `cabinet_rows._lever_funds`),
        and the row stages nothing when the sentence says the chest is short."""
        from backend.game_logic import counsel as CS
        from backend.game_logic.cabinet_rows import _lever_funds
        w = _w7_world
        funds = int(_lever_funds(w, "France"))
        assert funds == 800
        lever = CS._lever_sentence(_w7_reading(w))
        assert f"the treasury holds {funds}" in lever
        row = next(a for a in _w7_table_rows(_w7_preview(w))
                   if list(a.get("counsel_coverage") or []) == ["Britain"])
        assert "gold_offer" not in row
        assert f"the treasury can fund {funds}" in row["effect_text"]

    def test_the_boundary_is_the_sum_itself(self, _w7_world):
        from backend.game_logic import counsel as CS
        w = _w7_world
        gold = int(next(r for r in _w7_reading(w)["roads"]
                        if r["road"] == "table_alone")["gold_to_carry"])
        w.nation_gold["France"] = gold          # exactly the sum: funded
        assert "treasury" not in CS._lever_sentence(_w7_reading(w))
        w.nation_gold["France"] = gold - 1      # a gold short: the chest is named
        assert f"the treasury holds {gold - 1}" in CS._lever_sentence(_w7_reading(w))

    def test_the_chest_is_the_validators_budget_not_the_bare_treasury(self, _w7_world, monkeypatch):
        """`_lever_funds` is the settlement validator's own budget (the treasury
        less what is already owed) — the sentence reads it, not
        `nation_gold`, so a payment the ratifier would bounce is not promised."""
        from backend.game_logic import cabinet_rows
        from backend.game_logic import counsel as CS
        w = _w7_world
        w.nation_gold["France"] = 3000
        monkeypatch.setattr(cabinet_rows, "_lever_funds", lambda world, payer: 410)
        lever = CS._lever_sentence(_w7_reading(w))
        assert "the treasury holds 410" in lever, lever

    def test_a_reading_without_a_chest_is_read_as_funded(self):
        """The sentence is a pure function of the reading: a road that
        carries no `gold_funds` (a hand-made reading) says nothing of one."""
        from backend.game_logic import counsel as CS
        reading = {"court_display": "Britain", "roads": [{
            "road": "table_alone", "available": True, "carries": False,
            "label": "Open Settlement with Britain alone", "gold_to_carry": 975}]}
        assert "treasury" not in CS._lever_sentence(reading)
        reading["roads"][0]["gold_funds"] = 975
        assert "treasury" not in CS._lever_sentence(reading)
        reading["roads"][0]["gold_funds"] = 974
        assert "the treasury holds 974" in CS._lever_sentence(reading)

    def test_the_chest_rides_the_road_as_an_integer(self, _w7_world):
        """Golden Rule 2: the wire carries a whole number."""
        road = next(r for r in _w7_preview(_w7_world)["counsel_roads"]
                    if r["road"] == "table_alone")
        assert road["gold_funds"] == 800 and isinstance(road["gold_funds"], int)

# ========== S14f part 2 - merged from test_s14f_p2_w8.py ==========

_W8_ROOT = Path(__file__).resolve().parents[1]
_W8_SCENARIO = (_W8_ROOT / "godot-client" / "project-sovereign"
                / "assets" / "maps" / "europe_1805.json")
_W8_MINUS = "−"


def _w8_quiet():
    return contextlib.redirect_stdout(io.StringIO())


@pytest.fixture(scope="module")
def _w8_boot():
    from backend.models.world_state import WorldState
    with _w8_quiet():
        return WorldState.from_scenario(str(_W8_SCENARIO))


def _w8_world(boot):
    from backend.models.world_state import WorldState
    return WorldState.from_dict(json.loads(json.dumps(boot.to_dict(), default=str)))


def _w8_set(w, a: str, b: str, state: str) -> None:
    from backend.game_logic.diplomacy import set_diplomatic_state
    with _w8_quiet():
        set_diplomatic_state(w, a, b, state, "test")


def _w8_see(w) -> None:
    w._build_marshal_index()
    with _w8_quiet():
        w.calculate_visibility()


def _w8_figure(text: str) -> int:
    m = re.search(_W8_MINUS + r"([\d,]+)g", text)
    assert m, text
    return int(m.group(1).replace(",", ""))


def _w8_pay(w, nation: str = "France") -> int:
    return int(w.calculate_turn_upkeep(nation)["campaign_pay"])


_W8_PAY = re.compile(r"Swabia is Bavaria's soil — the corps standing there are fed by "
                     r"contract, about " + _W8_MINUS + r"[\d,]+g more a turn\.")


# ══════════════════════════════════════════════════════════════════════════
# S14E-X133 - a post-victory advance onto allied soil says the pay
# ══════════════════════════════════════════════════════════════════════════

def _w8_ulm(boot, mack_strength: int = 6000):
    """The Ulm board (tests/test_neutral_soil_pursuit_capture.py): Mack
    OCCUPIES Bavarian Swabia, Bavaria our ally; Ney (24,000, aggressive) at
    Rhineland strikes him. The victor advances as liberator onto Bavaria's
    soil, where a French corps is fed by contract."""
    w = _w8_world(boot)
    mack = w.get_marshal("Mack")
    mack.strength = mack_strength
    assert mack.location == "Swabia"
    assert w.get_region("Swabia").controller == "Bavaria"
    assert w.get_diplomatic_state("France", "Bavaria") == "ALLIANCE"
    assert w.get_marshal("Ney").location == "Rhineland"
    return w


def _w8_attack(w, marshal: str, target: str, seed: int = 7) -> dict:
    import random
    from backend.commands.executor import CommandExecutor
    w.actions_remaining = 4
    random.seed(seed)
    with _w8_quiet():
        return CommandExecutor().execute({
            "success": True,
            "command": {"type": "specific", "marshal": marshal,
                        "action": "attack", "target": target},
        }, {"world": w})


class TestS14EX133:
    """S14E-X133 (the sweep of S14E-X67): the ADVANCE after a victory is a
    move onto the field, and onto allied soil it puts the corps on campaign
    pay from the next bill - which the battle report never said.

    Reproduced: Ney (24,000) striking Mack on Bavaria's Swabia "advances into
    Swabia." and the report ended there, while the next turn's bill grew by
    the pay of the corps standing on Bavaria's soil; the auto-kill
    bombardment's advance, the glorious charge's and the reckless auto-charge's
    were as silent.

    The fix: each advance captures the province it left before `move_to` and
    appends `movement_executor.campaign_pay_clause` (X67's sentence, read
    after the attrition so the figure is the figure the bill then applies;
    '' for the AI and for home soil) after the march note."""

    def test_the_attack_advance_says_it_and_the_bill_agrees(self, _w8_boot):
        w = _w8_ulm(_w8_boot)
        ney = w.get_marshal("Ney")
        result = _w8_attack(w, "Ney", "Mack")
        assert result.get("success"), result.get("message")
        assert ney.location == "Swabia" and ney.strength > 0
        msg = str(result["message"])
        assert "Ney advances into Swabia." in msg, msg
        # the muster at the head already quotes the whole host's pay; the
        # WINNER's own line is the one the advance owes (after the march note)
        tail = msg.split("Ney advances into Swabia.", 1)[1]
        hit = _W8_PAY.search(tail)
        assert hit, msg
        assert tail.index("lost to march") < hit.start()
        after = _w8_pay(w)
        ney.location = "Rhineland"
        assert after - _w8_pay(w) == _w8_figure(hit.group(0)) > 0       # shown == applied

    def test_an_advance_onto_home_soil_says_nothing(self, _w8_boot):
        """Control: the same victory on a province of the homeland draws no pay."""
        w = _w8_ulm(_w8_boot)
        mack = w.get_marshal("Mack")
        mack.location = "Lorraine"               # France's own soil
        assert w.get_region("Lorraine").controller == "France"
        result = _w8_attack(w, "Ney", "Mack")
        assert result.get("success"), result.get("message")
        assert "fed by contract" not in str(result["message"])

    def test_the_auto_kill_bombardments_advance_says_it(self, _w8_boot):
        """The guns on SUPPORT kill Mack before the battle: the win without a
        battle advances Ney all the same."""
        from backend.models.marshal import StrategicOrder
        w = _w8_ulm(_w8_boot, mack_strength=40)
        gunner = w.get_marshal("Davout")
        gunner.artillery = True
        gunner.location = "Rhineland"
        gunner.strategic_order = StrategicOrder(
            command_type="SUPPORT", target="Ney", target_type="marshal",
            started_turn=int(w.current_turn), original_command="support Ney",
            issued_turn=int(w.current_turn))
        ney = w.get_marshal("Ney")
        result = _w8_attack(w, "Ney", "Mack")
        assert result.get("success"), result.get("message")
        assert ney.location == "Swabia", result.get("message")
        msg = str(result["message"])
        assert "Mack" not in w.marshals, msg                     # killed by the guns, no battle
        tail = msg.split("Ney advances into Swabia.", 1)[1]
        hit = _W8_PAY.search(tail)
        assert hit, msg
        after = _w8_pay(w)
        ney.location = "Rhineland"
        assert after - _w8_pay(w) == _w8_figure(hit.group(0)) > 0

    def test_the_glorious_charges_advance_says_it(self, _w8_boot):
        import random
        from backend.commands.executor import CommandExecutor
        w = _w8_ulm(_w8_boot, mack_strength=3000)
        murat = w.get_marshal("Murat")
        murat.location = "Rhineland"
        w.actions_remaining = 4
        random.seed(7)
        with _w8_quiet():
            result = CommandExecutor()._combat._execute_glorious_charge(
                murat, "Mack", w, {"world": w})
        assert result.get("success"), result.get("message")
        assert murat.location == "Swabia", result.get("message")
        msg = str(result["message"])
        tail = msg.split("Murat advances into Swabia.", 1)[1]
        hit = _W8_PAY.search(tail)
        assert hit, msg
        after = _w8_pay(w)
        murat.location = "Rhineland"
        assert after - _w8_pay(w) == _w8_figure(hit.group(0)) > 0

    def test_the_reckless_auto_charges_advance_says_it(self, _w8_boot):
        found = 0
        for seed in range(1, 9):
            w, murat, msg = _w8_auto_charge(_w8_boot, seed)
            if "Murat advances into Swabia." not in msg:
                continue
            found += 1
            hit = _W8_PAY.search(msg.split("Murat advances into Swabia.", 1)[1])
            assert hit, (seed, msg)
            after = _w8_pay(w)
            murat.location = "Rhineland"
            assert after - _w8_pay(w) == _w8_figure(hit.group(0)) > 0, (seed, msg)
        assert found >= 3, f"the auto-charge's advance was reached on only {found}/8 seeds - the pin is vacuous"

    def test_the_ais_advance_is_untouched(self, _w8_boot):
        """Rule 5: the clause reads the player's corps only - an Austrian corps
        walking onto a neutral court's soil prints what it printed."""
        from backend.commands.movement_executor import campaign_pay_clause
        w = _w8_world(_w8_boot)
        mack = w.get_marshal("Mack")
        assert mack.nation != w.player_nation
        assert campaign_pay_clause(w, mack, "Munich", "Swabia") == ""
        assert campaign_pay_clause(w, w.get_marshal("Ney"), "Lorraine", "Rhineland") == ""

    def test_all_four_advances_read_the_one_clause(self):
        ce = (_W8_ROOT / "backend" / "commands" / "combat_executor.py").read_text(encoding="utf-8")
        ws = (_W8_ROOT / "backend" / "models" / "world_state.py").read_text(encoding="utf-8")
        assert ce.count("campaign_pay_clause(") == 4          # three advances + XU2's approach step
        assert ws.count("_ac_clause(self, marshal, auto_charge_battle_region, _advance_from)") == 1


def _w8_auto_charge(boot, seed: int):
    """Murat (22,000, reckless cavalry) auto-charges a broken Mack (3,000) on
    Swabia from Rhineland and wins: the advance onto Bavaria's soil."""
    import random
    w = _w8_world(boot)
    murat, mack = w.get_marshal("Murat"), w.get_marshal("Mack")
    murat.location = "Rhineland"
    murat.recklessness = 4
    mack.strength = 3000
    w.get_marshal("Kutuzov").location = "Podolia"
    _w8_see(w)
    random.seed(seed)
    with _w8_quiet():
        events = w._process_reckless_cavalry_turn_start()
    return w, murat, str(events[0].get("message") or "") if events else ""


# ══════════════════════════════════════════════════════════════════════════
# S14E-X134 - the Staff's typed army order counts the column's long roads
# ══════════════════════════════════════════════════════════════════════════

@contextlib.contextmanager
def _w8_client(w):
    """The player's road: /command on a swapped world (three globals, restored)."""
    import backend.main as M
    from backend.commands.parser import CommandParser
    from fastapi.testclient import TestClient
    saved = (M.game_state["world"], M.world, M.parser)
    M.game_state["world"] = w
    M.world = w
    M.parser = CommandParser(use_real_llm=False)
    try:
        yield TestClient(M.app)
    finally:
        M.game_state["world"], M.world, M.parser = saved


def _w8_say(client, text: str) -> dict:
    with _w8_quiet():
        return client.post("/command", json={"command": text}).json()


def _w8_army_board(boot):
    """S14E-X88's board (the conquest run, DD-B turn 19): France holds Berlin,
    Moravia and Vienna; Bohemia and Dresden are Austrian under the truce;
    Prussia has opened her borders; the Staff is in force; the Emperor and Ney
    stand at Silesia, Davout at Posen, Soult (literal) at Berlin and
    Bernadotte at Franconia - the direct roads of Soult, Davout and
    Bernadotte to Vienna are shut by the truce."""
    from backend.game_logic import reforms
    w = _w8_world(boot)
    for name, owner in (("Berlin", "France"), ("Moravia", "France"), ("Vienna", "France"),
                        ("Dresden", "Austria"), ("Bohemia", "Austria")):
        w.regions[name].controller = owner
    _w8_set(w, "France", "Austria", "ARMISTICE")
    _w8_set(w, "France", "Prussia", "OPEN_BORDERS")
    w.get_marshal("Soult").location = "Berlin"
    w.get_marshal("Davout").location = "Vienna"
    row = next(r for r in reforms.deck(w, w.player_nation) if reforms.is_staff(r))
    row["enacted_turn"] = w.current_turn
    for name in ("Napoleon", "Ney"):
        w.get_marshal(name).location = "Silesia"
    w.get_marshal("Davout").location = "Posen"
    _w8_see(w)
    return w


_W8_COUNT = "3 of 5 corps take a long or foreign road — their cards say which"


class TestS14EX134:
    """S14E-X134 (the sweep of S14E-22): the Staff's typed army order
    (`group_orders._army_order`) commits the whole column down its roads with
    no ask (S14E-22's ask skips it by scope), and its head line said only
    "5 corps within 2 provinces of the Emperor".

    Reproduced: "the army, march to Vienna" on the army board marched Soult
    through Brandenburg, Posen, Silesia, Podolia and Moravia (six provinces
    through two foreign courts) and Davout and Bernadotte round their shut
    roads, while the head line carried no word of it - the province panel's
    army row counted "3 of 5 corps take a long or foreign road".

    The fix: `group_orders._head_line` prints the SAME count
    (`order_quotes.detour_count_clause`, which `army_quote`'s note now prints
    too), read through the cards' own readers (`order_quotes.column_detours`);
    byte-identical when no corps detours."""

    def test_the_head_line_carries_the_count_the_quote_carries(self, _w8_boot):
        from backend.commands.order_quotes import army_quote
        w = _w8_army_board(_w8_boot)
        assert _W8_COUNT in army_quote(w, "Vienna")["note"]
        with _w8_client(w) as client:
            out = _w8_say(client, "the army, march to Vienna")
        head = str(out["message"]).splitlines()[0]
        assert out["group"]["army"] is True, out["message"]
        assert head.startswith("The Grand Quartier Général carries the Emperor's order")
        assert "5 corps within 2 provinces of the Emperor, 'march to Vienna'. " + _W8_COUNT + "." in head, head

    def test_no_corps_detours_no_clause(self, _w8_boot):
        """The shipped board: nothing is shut - the head is the head it was."""
        from backend.game_logic import reforms
        w = _w8_world(_w8_boot)
        row = next(r for r in reforms.deck(w, w.player_nation) if reforms.is_staff(r))
        row["enacted_turn"] = w.current_turn
        with _w8_client(w) as client:
            out = _w8_say(client, "the army, march to Munich")
        head = str(out["message"]).splitlines()[0]
        assert out["group"]["army"] is True, out["message"]
        assert "long or foreign road" not in head
        assert head.endswith("'march to Munich'.") or "Beyond the Emperor's reach" in head, head

    def test_one_corps_is_said_in_the_singular(self, _w8_boot):
        w = _w8_army_board(_w8_boot)
        for name in ("Davout", "Bernadotte"):               # beyond the column
            w.get_marshal(name).location = "Franche-Comte"
        _w8_see(w)
        with _w8_client(w) as client:
            out = _w8_say(client, "the army, march to Vienna")
        head = str(out["message"]).splitlines()[0]
        assert "1 of 3 corps takes a long or foreign road — his card says which." in head, head

    def test_the_two_surfaces_print_one_sentence(self):
        from backend.commands.order_quotes import detour_count_clause
        assert detour_count_clause(0, 5) == ""
        assert detour_count_clause(1, 3) == "1 of 3 corps takes a long or foreign road — his card says which"
        assert detour_count_clause(3, 5) == _W8_COUNT
        src = (_W8_ROOT / "backend" / "commands" / "order_quotes.py").read_text(encoding="utf-8")
        assert "notes.append(detour_count_clause(detoured, len(corps)))" in src

    def test_a_support_and_a_pursuit_read_the_cards_own_readers(self, _w8_boot):
        """`column_detours` is the head's reader for every typed tier: a MOVE_TO
        counts `march_quote`'s rider, a SUPPORT `support_quote`'s."""
        from backend.commands.order_quotes import column_detours, march_quote, support_quote
        w = _w8_army_board(_w8_boot)
        names = ["Ney", "Davout", "Soult", "Bernadotte", "Napoleon"]
        assert column_detours(w, names, "MOVE_TO", "Vienna") == 3 == sum(
            1 for n in names if march_quote(w, w.get_marshal(n), "Vienna")["detour"])
        ally = w.get_marshal("Napoleon")
        want = sum(1 for n in ("Ney", "Davout", "Soult", "Bernadotte")
                   if support_quote(w, w.get_marshal(n), ally)["detour"])
        assert column_detours(w, ["Ney", "Davout", "Soult", "Bernadotte"], "SUPPORT", "Napoleon") == want
        assert column_detours(w, names, "MOVE_TO", "") == 0

    def test_a_pursuit_counts_the_breadth_first_road_the_ask_reads(self, _w8_boot):
        from backend.commands import strategic as road_law
        from backend.commands.order_quotes import column_detours
        w = _w8_army_board(_w8_boot)
        w.get_marshal("Kutuzov").location = "Vienna"
        names = ["Ney", "Davout", "Soult", "Bernadotte", "Napoleon"]
        want = 0
        for n in names:
            m = w.get_marshal(n)
            road, refusal, _kind = road_law.march_road(w, m, "Vienna", "PURSUE")
            if refusal is None and road and road_law.march_detour_reading(w, m, "Vienna", road, "PURSUE"):
                want += 1
        assert want > 0, "the board has no pursuit detour - the pin is vacuous"
        assert column_detours(w, names, "PURSUE", "Kutuzov") == want


# ══════════════════════════════════════════════════════════════════════════
# S14E-X135 - the province panel prints each corps's detour under the army row
# ══════════════════════════════════════════════════════════════════════════

def _w8_gd(name: str) -> str:
    return (_W8_ROOT / "godot-client" / "project-sovereign" / "scripts" / name).read_text(encoding="utf-8")


class TestS14EX135:
    """S14E-X135 (the sweep of S14E-X88): the army quote's per-corps `detour`
    rows were data-only - the panel printed the count in the row's `note`
    ("3 of 5 corps take a long or foreign road - their cards say which") and
    the cards are the march chips of the corps' own provinces, which the
    column's panel does not show.

    Reproduced: `region_panel.gd` read `q.get("detour")` for a march chip
    (`_quote_notes`) and nothing of `army.corps[].detour` - the army row
    printed the count and no corps.

    The fix: `_army_detour_rows(army)` renders one line per corps that has a
    detour ("Soult - The direct road to Vienna via Dresden is closed ...") in
    the panel's note colour under the army row. The payload side is pinned
    here (the rows ride `GET /march_quotes`'s `army` quote); the .gd is
    pinned by its source text."""

    def test_the_payload_carries_the_rows_the_panel_prints(self, _w8_boot):
        from backend.commands.order_quotes import march_quotes_for_region
        w = _w8_army_board(_w8_boot)
        army = march_quotes_for_region(w, "Vienna")["army"]
        assert army["ok"], army["refusal"]
        said = {c["shown"]: c["detour"] for c in army["corps"] if c["detour"]}
        assert set(said) == {"Soult", "Davout", "Bernadotte"}, said
        assert said["Soult"].startswith("The direct road to Vienna via Dresden is closed by the truce")
        assert _W8_COUNT in army["note"]

    def test_the_panel_renders_each_corps_detour_in_the_note_colour(self):
        src = _w8_gd("region_panel.gd")
        assert "func _army_detour_rows(army: Dictionary) -> String:" in src
        body = src.split("func _army_detour_rows(army: Dictionary) -> String:", 1)[1]
        body = body.split("\nfunc ", 1)[0]
        assert 'army.get("corps", [])' in body
        assert 'var detour := str(c.get("detour", ""))' in body
        assert 'if detour == "":' in body and "continue" in body
        assert 'str(c.get("shown", "")) + " — " + detour' in body
        assert "Utils.COLOR_INFO" in body
        assert 'out += "    [color=#"' in body                     # a line of its own, indented
        # ... under the army row, after the chip row is printed
        assert ('out += _quote_rows([army])\n\t\tout += _army_detour_rows(army)') in src

    def test_the_gd_is_tabbed(self):
        src = _w8_gd("region_panel.gd")
        body = src.split("func _army_detour_rows(army: Dictionary) -> String:", 1)[1].split("\nfunc ", 1)[0]
        for ln in body.splitlines():
            assert not ln.startswith("  "), repr(ln)               # GDScript uses TABS

    def test_the_march_chips_own_detour_note_is_untouched(self):
        """The negative control: `_quote_notes` still carries the march card's
        `detour` and `pay` riders, in their order."""
        src = _w8_gd("region_panel.gd")
        notes = src.split("func _quote_notes(q: Dictionary) -> String:", 1)[1].split("\nfunc ", 1)[0]
        assert notes.index('q.get("detour", "")') < notes.index('q.get("pay", "")')


