class TestS14EX150:
    """S14E-X150: a bare `Ney, attack` with the nearest enemy out of reach and
    the pursuit unaffordable (`_attack_nearest_target`'s fallback step) marches
    a step toward him at once.

    Reproduced: Mack at Munich, one action in hand, "Ney, attack" replied "Ney
    advances from Rhineland to Swabia, moving toward Mack at Munich! (Now 1
    region away) (432 lost to march)" and the next turn's bill grew by the pay
    of the corps on Bavaria's Swabia.

    The fix: the message closes with `campaign_pay_clause` (X67's sentence,
    read after the attrition, from the province left)."""

    def test_the_approach_step_says_it_and_the_bill_agrees(self, _w8_boot):
        import random
        from backend.commands.executor import CommandExecutor
        w = _w8_world(_w8_boot)
        w.get_marshal("Mack").location = "Munich"
        _w8_see(w)
        w.actions_remaining = 1                      # the pursuit (2 AP) is unaffordable
        random.seed(7)
        ney = w.get_marshal("Ney")
        with _w8_quiet():
            result = CommandExecutor().execute({
                "success": True,
                "command": {"type": "specific", "marshal": "Ney", "action": "attack", "target": None},
            }, {"world": w})
        assert result.get("success"), result.get("message")
        assert ney.location == "Swabia", result.get("message")
        msg = str(result["message"])
        assert msg.startswith("Ney advances from Rhineland to Swabia, moving toward Mack at Munich!"), msg
        hit = _W8_PAY.search(msg)
        assert hit and msg.index("lost to march") < hit.start(), msg
        after = _w8_pay(w)
        ney.location = "Rhineland"
        assert after - _w8_pay(w) == _w8_figure(hit.group(0)) > 0


class TestS14EX151:
    """S14E-X151: the general attack (`_execute_general_attack`) with nobody in
    reach walks the closest corps a step toward the enemy.

    Reproduced: with the army at Rhineland and Mack at Bohemia, the reply
    "No marshals in attack range! Ney advances toward Mack: Rhineland ->
    Swabia ..." ended at the clock, while the bill then grew by the pay of the
    corps on Bavaria's soil.

    The fix: the reply closes with `campaign_pay_note`."""

    def test_the_general_attacks_step_says_it_and_the_bill_agrees(self, _w8_boot):
        import random
        from backend.commands.executor import CommandExecutor
        w = _w8_world(_w8_boot)
        w.get_marshal("Mack").location = "Bohemia"
        for m in w.get_player_marshals():
            m.location = "Rhineland"
        w.get_marshal("ArchdukeJohn").location = "Vienna"
        w.get_marshal("Kutuzov").location = "Podolia"
        _w8_see(w)
        random.seed(7)
        with _w8_quiet():
            result = CommandExecutor()._combat._execute_general_attack(
                {"action": "attack"}, {"world": w})
        assert result.get("success"), result.get("message")
        mover = w.get_marshal(result["marshal"])
        assert result["to"] == "Swabia" and mover.location == "Swabia", result
        msg = str(result["message"])
        hit = _W8_PAY.search(msg)
        assert hit, msg
        assert msg.index("more move") < hit.start()
        assert msg.rstrip().endswith("a turn."), msg                    # a line of its own, last
        after = _w8_pay(w)
        mover.location = "Rhineland"
        assert after - _w8_pay(w) == _w8_figure(hit.group(0)) > 0

    def test_a_step_over_home_soil_is_as_it_was(self, _w8_boot):
        import random
        from backend.commands.executor import CommandExecutor
        w = _w8_world(_w8_boot)
        w.get_marshal("Mack").location = "Swabia"
        for m in w.get_player_marshals():
            m.location = "Nivernais"                 # two off: the step is Lorraine or Franche-Comte, home soil
        w.get_marshal("Kutuzov").location = "Podolia"
        _w8_see(w)
        random.seed(7)
        with _w8_quiet():
            result = CommandExecutor()._combat._execute_general_attack(
                {"action": "attack"}, {"world": w})
        assert result.get("success") and result.get("to") in ("Lorraine", "Franche-Comte"), result
        assert "fed by contract" not in str(result.get("message")), result.get("message")


class TestS14EX152:
    """S14E-X152: the reckless cavalry's FREE ride toward a foe out of charge
    reach (`_process_reckless_cavalry_turn_start`, the "rides out seeking
    battle" event) is the player's corps moved without an order.

    Reproduced: Murat (22,000, recklessness 4) at Rhineland with Mack at
    Bohemia rode "Rhineland → Swabia (toward Mack)" and the event said only
    "[FREE ACTION - 2 regions to target]" while the bill grew by the pay of the
    corps on Bavaria's soil.

    The fix: the event's message carries the campaign pay line after the
    ride, before the free-action clock; the AI's ride is untouched."""

    def _ride(self, boot, seed: int = 3):
        import random
        w = _w8_world(boot)
        murat = w.get_marshal("Murat")
        murat.location, murat.recklessness = "Rhineland", 4
        w.get_marshal("Mack").location = "Bohemia"
        w.get_marshal("Kutuzov").location = "Podolia"
        _w8_see(w)
        random.seed(seed)
        with _w8_quiet():
            events = w._process_reckless_cavalry_turn_start()
        return w, murat, [e for e in events if e.get("type") == "reckless_move"]

    def test_the_ride_says_it_and_the_bill_agrees(self, _w8_boot):
        w, murat, rides = self._ride(_w8_boot)
        assert len(rides) == 1 and murat.location == "Swabia", rides
        msg = str(rides[0]["message"])
        hit = _W8_PAY.search(msg)
        assert hit, msg
        assert msg.index("Auto-moved: Rhineland → Swabia (toward Mack)") < hit.start() < msg.index("[FREE ACTION")
        after = _w8_pay(w)
        murat.location = "Rhineland"
        assert after - _w8_pay(w) == _w8_figure(hit.group(0)) > 0

    def test_a_ride_over_home_soil_is_as_it_was(self, _w8_boot):
        import random
        w = _w8_world(_w8_boot)
        murat = w.get_marshal("Murat")
        murat.location, murat.recklessness = "Ile-de-France", 4
        w.get_marshal("Mack").location = "Swabia"          # three off: the ride is over home soil
        w.get_marshal("Kutuzov").location = "Podolia"
        _w8_see(w)
        random.seed(3)
        with _w8_quiet():
            events = w._process_reckless_cavalry_turn_start()
        rides = [e for e in events if e.get("type") == "reckless_move"]
        assert len(rides) == 1 and w.get_region(rides[0]["to"]).controller == "France", events
        for e in events:
            assert "fed by contract" not in str(e.get("message")), e


class TestS14EX153:
    """S14E-X153 (XD7's sweep of the retreats): the won BREAKOUT
    (`apply_successful_breakout` - the last-stand ask's winning roll and the
    standing order's breakout) is a fighting withdrawal onto a neighbour
    province, and XD7 swept the ordered and the forced retreat but not this one.

    Reproduced: Davout (26,000) at Rhineland with Mack at Lorraine, the safe
    retreat held on Bavaria's Swabia, got out and "Davout falls back on
    Swabia, his corps disordered but in the field. (130 lost to the march)"
    with no word of the pay the corps now draws there.

    The fix: the sentence closes with `campaign_pay_note` read after the step
    ('' for the AI and for home soil)."""

    def _board(self, boot, destination: str):
        w = _w8_world(boot)
        w.get_marshal("Mack").location = "Lorraine"
        _w8_see(w)
        w.get_safe_retreat_destination = lambda *a, **k: destination
        return w

    def test_the_breakout_says_it_and_the_bill_agrees(self, _w8_boot):
        from backend.commands.executor import CommandExecutor
        w = self._board(_w8_boot, "Swabia")
        davout, mack = w.get_marshal("Davout"), w.get_marshal("Mack")
        before = _w8_pay(w)
        with _w8_quiet():
            msg = CommandExecutor()._combat.apply_successful_breakout(davout, mack, w)
        assert davout.location == "Swabia", msg
        assert msg.startswith("Davout falls back on Swabia, his corps disordered but in the field."), msg
        line = next(ln for ln in msg.splitlines() if ln.startswith("Swabia is Bavaria's soil"))
        assert _w8_pay(w) - before == _w8_figure(line) > 0              # shown == applied

    def test_a_breakout_home_is_as_it_was(self, _w8_boot):
        from backend.commands.executor import CommandExecutor
        w = self._board(_w8_boot, "Lorraine")
        davout, mack = w.get_marshal("Davout"), w.get_marshal("Mack")
        with _w8_quiet():
            msg = CommandExecutor()._combat.apply_successful_breakout(davout, mack, w)
        assert "falls back on Lorraine" in msg and "fed by contract" not in msg, msg

# ========== S14f part 2 - merged from test_s14f_p2_w9.py ==========

# ══════════════════════════════════════════════════════════════════════════
# S14f part 2, third wave — the two siblings the D7 / XM wave filed
# ══════════════════════════════════════════════════════════════════════════
# S14E-X127 (the bond's price line quotes "1,000 gold to her pays it" with no
# chest, and the Outbid row stays open on a chest that cannot pay it - the
# S14E-X126 class: a sum quoted against a treasury that cannot fund it) and
# S14E-X128 (a table row that opens ONE court of several is a display-only
# echo - the S14E-X125 / CN-4 class: typed, the line opens the whole table).

_W9_ROOT = Path(__file__).resolve().parents[1]
_W9_SCENARIO = (_W9_ROOT / "godot-client" / "project-sovereign" / "assets" / "maps"
                / "europe_1805.json")
_W9_SCRIPTS = _W9_ROOT / "godot-client" / "project-sovereign" / "scripts"
_W9_BOARDS = _W9_ROOT / "tests" / "fixtures" / "pc_boards"

# The shipped board, a Britain-to-Austria bond (the league's paymaster), and
# the figures it prices: 1,000 gold bids it (`bond.bid_gold`), the shipped
# chest holds 800.
_W9_PRICE = ("Britain's bond costs her 40 at the table (9 in a bilateral peace); "
             "1,000 gold to her pays it")
_W9_COMPENSATION = " — or Franconia, Bavaria's (+35), most of it."
_W9_SHORT = " (the treasury holds 800)"


def _w9_src(name: str) -> str:
    return (_W9_SCRIPTS / name).read_text(encoding="utf-8")


def _w9_func(src: str, name: str) -> str:
    body = src[src.index("func " + name):]
    nxt = body.find("\nfunc ", 10)
    return body if nxt < 0 else body[:nxt]


def _w9_quiet(fn, *args, **kwargs):
    with contextlib.redirect_stdout(io.StringIO()):
        return fn(*args, **kwargs)


@pytest.fixture(scope="module")
def _w9_boot():
    from backend.models.world_state import WorldState
    with contextlib.redirect_stdout(io.StringIO()):
        return WorldState.from_scenario(str(_W9_SCENARIO))


def _w9_copy(boot):
    from backend.models.world_state import WorldState
    return WorldState.from_dict(json.loads(json.dumps(boot.to_dict(), default=str)))


def _w9_scores(w, view: int = 20) -> None:
    """The Third Coalition board at `view` / `view` / `view` (France's chair)."""
    for other in ("Britain", "Austria", "Russia"):
        key = w._make_diplo_key("France", other)
        w.war_scores[key] = view if key.split("|")[0] == "France" else -view


@pytest.fixture
def _w9_world(_w9_boot):
    """The shipped 1805 board at 20 / 20 / 20, France holding the SHIPPED 800
    gold, DP to spend."""
    w = _w9_copy(_w9_boot)
    w.diplomatic_points = 30
    _w9_scores(w)
    return w


@pytest.fixture
def _w9_bonded(_w9_world):
    """The league's bond, minted through the game's own mint: Britain pays
    Austria not to sign alone against France."""
    from backend.game_logic import bond as B
    w = _w9_world
    w.nation_gold["Britain"] = 5000
    minted = _w9_quiet(B.mint_bond, w, payer="Britain", member="Austria", enemy="France")
    assert minted["success"], minted
    return w


@pytest.fixture
def _w9_client(monkeypatch):
    """The in-process HTTP idiom: `M.world`, `M.game_state["world"]` and the
    parser swapped together. Returns a function that seats a world."""
    import backend.main as M
    from backend.commands.parser import CommandParser
    from fastapi.testclient import TestClient
    for key in ("SOVEREIGN_SCENARIO", "SOVEREIGN_MAP", "SOVEREIGN_SMOKE_START"):
        monkeypatch.delenv(key, raising=False)
    monkeypatch.setenv("LLM_MODE", "mock")
    monkeypatch.setattr(M, "parser", CommandParser(use_real_llm=False))

    def _seat(world):
        monkeypatch.setattr(M, "world", world)
        monkeypatch.setitem(M.game_state, "world", world)
        return TestClient(M.app)
    return _seat


def _w9_post(client, body: dict) -> dict:
    with contextlib.redirect_stdout(io.StringIO()):
        return client.post("/command", json=body).json()


def _w9_preview(w, court: str = "Britain") -> dict:
    from backend.game_logic.diplomacy import get_diplomatic_preview
    return _w9_quiet(get_diplomatic_preview, w, court)


def _w9_outbid(w, court: str = "Austria") -> dict:
    """The Cabinet's Outbid row on the court's page (the player's list)."""
    from backend.game_logic import diplomacy as D
    w.diplomatic_points = max(int(w.diplomatic_points), 10)
    rows = _w9_quiet(D.get_available_diplomatic_actions, w, court)
    return next(a for a in rows if a["action"] == "outbid_bond")


def _w9_table_rows(preview: dict) -> list:
    return [a for a in preview["actions"] if a.get("action") == "open_settlement"]


def _w9_lever_row(preview: dict, court: str = "Britain") -> dict:
    return next(a for a in _w9_table_rows(preview)
                if list(a.get("counsel_coverage") or []) == [court])


# ══════════════════════════════════════════════════════════════════════════
# S14E-X127 — the bond's price line quotes a sum the chest cannot fund
# ══════════════════════════════════════════════════════════════════════════

class TestS14EX127:
    """Reproduced (before the fix, on the shipped 1805 board with Britain's
    bond on Austria and France holding the shipped 800 gold):
    `bond.price_line` reads "Britain's bond costs her 40 at the table (9 in a
    bilateral peace); 1,000 gold to her pays it — or Franconia, Bavaria's
    (+35), most of it." with no word of the chest, and the Cabinet's "Outbid
    Britain's Bond" row (`cabinet_rows.bond_actions`) is `available: True`
    with `choices: []` - an open control that stages nothing, and no reason
    beside it. The counsel's two roads (`counsel._table_road`,
    `counsel._bilateral_road`), the Congress's lever (`congress.price`) and
    the war panel's table lines (`war_status._peace_table`) carry the same
    bare sum."""

    # ── the price line ───────────────────────────────────────────────────

    def test_the_short_chest_is_named_after_the_sum(self, _w9_bonded):
        from backend.game_logic import bond as B
        w = _w9_bonded
        assert int(w.nation_gold["France"]) == 800
        assert B.bid_gold(w, B.bond_on(w, "Austria", "France")) == 1000
        assert B.price_line(w, "Austria", "France") == _W9_PRICE + _W9_SHORT + "."

    def test_the_compensation_clause_follows_the_chest(self, _w9_bonded):
        from backend.game_logic import bond as B
        w = _w9_bonded
        line = B.price_line(w, "Austria", "France", war_instance=w.war_instances["war_1"])
        assert line == _W9_PRICE + _W9_SHORT + _W9_COMPENSATION

    def test_the_funded_line_is_byte_identical(self, _w9_bonded):
        from backend.game_logic import bond as B
        w = _w9_bonded
        w.nation_gold["France"] = 3000
        assert B.price_line(w, "Austria", "France") == _W9_PRICE + "."
        line = B.price_line(w, "Austria", "France", war_instance=w.war_instances["war_1"])
        assert line == _W9_PRICE + _W9_COMPENSATION

    def test_the_boundary_is_the_bid_itself(self, _w9_bonded, monkeypatch):
        from backend.game_logic import bond as B
        from backend.game_logic import cabinet_rows
        w = _w9_bonded
        monkeypatch.setattr(cabinet_rows, "_lever_funds", lambda world, payer: 1000)
        assert "treasury" not in B.price_line(w, "Austria", "France")
        monkeypatch.setattr(cabinet_rows, "_lever_funds", lambda world, payer: 999)
        assert B.price_line(w, "Austria", "France").startswith(_W9_PRICE + " (the treasury holds 999)")

    def test_the_chest_is_the_levers_chest_not_the_bare_treasury(self, _w9_bonded, monkeypatch):
        """Shown == applied: the figure is `cabinet_rows._lever_funds` (the
        settlement validator's budget - the treasury less what is owed), the
        very chest S14E-X126 quotes beside the counsel's lever, so a bid the
        ratifier would bounce is not promised."""
        from backend.game_logic import bond as B
        from backend.game_logic import cabinet_rows
        w = _w9_bonded
        w.nation_gold["France"] = 3000
        monkeypatch.setattr(cabinet_rows, "_lever_funds", lambda world, payer: 410)
        assert B.price_line(w, "Austria", "France").startswith(_W9_PRICE + " (the treasury holds 410)")

    def test_a_large_chest_is_grouped_like_the_sum(self, _w9_bonded, monkeypatch):
        """The bid is printed "1,000"; the chest beside it reads the same way
        (a 12,500-gold bid, a 12,100 chest)."""
        from backend.game_logic import bond as B
        w = _w9_bonded
        monkeypatch.setattr(B, "bid_gold", lambda world, record: 12500)
        from backend.game_logic import cabinet_rows
        monkeypatch.setattr(cabinet_rows, "_lever_funds", lambda world, payer: 12100)
        line = B.price_line(w, "Austria", "France")
        assert "12,500 gold to her pays it (the treasury holds 12,100)" in line, line

    def test_no_bond_no_line_still(self, _w9_world):
        from backend.game_logic import bond as B
        assert B.price_line(_w9_world, "Austria", "France") == ""

    # ── the Outbid row ───────────────────────────────────────────────────

    def test_the_short_row_is_shut_with_its_reason(self, _w9_bonded):
        w = _w9_bonded
        row = _w9_outbid(w)
        assert row["available"] is False, row
        assert row["disabled_reason_display"] == row["disabled_reason"] == (
            "The treasury holds 800 gold — the bid is 1,000, 200 short.")
        assert row["choices"] == []
        assert row["bid_short_by"] == 200 and isinstance(row["bid_short_by"], int)
        # the sentence on the button names the chest as well
        assert (_W9_PRICE + _W9_SHORT) in row["effect_text"], row["effect_text"]
        # the rest of the row keeps its shape
        assert row["display_name"] == "Outbid Britain's Bond — Austria alone at the table"
        assert row["counsel_coverage"] == ["Austria"] and row["war_id"] == "war_1"

    def test_the_funded_row_is_unchanged(self, _w9_bonded):
        w = _w9_bonded
        w.nation_gold["France"] = 3000
        row = _w9_outbid(w)
        assert row["available"] is True and row["disabled_reason_display"] == ""
        assert row["choices"] == [{"label": "Open the table with 1,000 gold to Austria (+40)",
                                   "payload": {"bond_bid": 1000}}]
        assert "bid_short_by" not in row
        assert row["effect_text"] == _W9_PRICE + _W9_COMPENSATION

    def test_the_row_and_the_line_read_one_chest(self, _w9_bonded, monkeypatch):
        """The row's offer (its choice) and the sentence's note are both the
        lever's chest: a chest of exactly the bid funds it, a gold short
        does not, and the shortfall is the difference."""
        from backend.game_logic import cabinet_rows
        w = _w9_bonded
        monkeypatch.setattr(cabinet_rows, "_lever_funds", lambda world, payer: 1000)
        row = _w9_outbid(w)
        assert row["available"] and len(row["choices"]) == 1 and "treasury" not in row["effect_text"]
        monkeypatch.setattr(cabinet_rows, "_lever_funds", lambda world, payer: 999)
        row = _w9_outbid(w)
        assert not row["available"] and row["choices"] == []
        assert row["bid_short_by"] == 1
        assert "the treasury holds 999" in row["effect_text"]
        assert "holds 999 gold — the bid is 1,000, 1 short" in row["disabled_reason_display"]

    def test_the_tables_own_reason_comes_first(self):
        """Where the table itself is shut the row says why (the executor's
        words), not the chest - and the pointer to it stays unnamed."""
        from types import SimpleNamespace as NS
        from backend.game_logic import cabinet_rows
        from backend.game_logic import bond as B
        record = {"payer": "Britain", "recipient": "Austria", "aim": "France"}
        w = NS(player_nation="France", diplomatic_points=10, nation_gold={"France": 800},
               war_instances={}, is_at_war=lambda a, b: True)
        import unittest.mock as mock
        with mock.patch.object(B, "shared_enemies", return_value=[]), \
                mock.patch.object(B, "bond_on", return_value=record), \
                mock.patch.object(B, "bid_gold", return_value=1000), \
                mock.patch.object(B, "table_price", return_value=40), \
                mock.patch.object(B, "price_line", return_value="the line."), \
                mock.patch.object(cabinet_rows, "_lever_funds", return_value=800):
            shut = {"action": "open_settlement", "available": False,
                    "disabled_reason_display": "The table is not open.", "war_id": "war_1"}
            row = cabinet_rows.bond_actions(w, "France", "Austria", [shut])[0]
            assert row["available"] is False
            assert row["disabled_reason_display"] == "The table is not open."
            assert "bid_short_by" not in row
            opened = dict(shut, available=True, disabled_reason_display="")
            row = cabinet_rows.bond_actions(w, "France", "Austria", [opened])[0]
            assert row["available"] is False and row["bid_short_by"] == 200

    def test_the_wire_carries_whole_numbers(self, _w9_bonded):
        row = _w9_outbid(_w9_bonded)
        assert json.loads(json.dumps(row))["bid_short_by"] == 200
        assert all(isinstance(row[k], int) for k in ("bid_short_by", "dp_cost"))

    # ── every surface says the same ──────────────────────────────────────

    def test_the_counsels_two_roads_say_it_and_still_name_the_row(self, _w9_bonded):
        """`_table_road` (the alone road) and `_bilateral_road` (the Propose
        Peace road) end "(F1 → Austria → Outbid Britain's Bond)." as S14E-X33
        / XI5 pinned - the row exists, shut for want of gold, and its path
        stays where the player will find it (and its reason)."""
        from backend.game_logic import counsel as K
        w = _w9_bonded
        with contextlib.redirect_stdout(io.StringIO()):
            table = K._table_road(w, "France", "Austria", alone=True)
            bilateral = K._bilateral_road(w, "France", "Austria", "peace", "send_peace")
        for road in (table, bilateral):
            line = road["bond_line"]
            assert (_W9_PRICE + _W9_SHORT) in line, line
            assert line.endswith("(F1 → Austria → Outbid Britain's Bond)."), line
            assert line in road["trade"]

    def test_the_path_is_named_only_for_a_row_the_chest_alone_shuts(self, _w9_bonded, monkeypatch):
        from backend.game_logic import cabinet_rows
        from backend.game_logic import counsel as K
        w = _w9_bonded
        base = {"action": "outbid_bond", "display_name": "Outbid Britain's Bond — Austria alone at the table"}
        monkeypatch.setattr(cabinet_rows, "bond_actions", lambda *a, **k: [
            dict(base, available=False, disabled_reason_display="The table is not open.")])
        assert K._outbid_path(w, "France", "Austria", "war_1") == ""
        monkeypatch.setattr(cabinet_rows, "bond_actions", lambda *a, **k: [
            dict(base, available=False, bid_short_by=200)])
        assert K._outbid_path(w, "France", "Austria", "war_1") == "(F1 → Austria → Outbid Britain's Bond)"
        monkeypatch.setattr(cabinet_rows, "bond_actions", lambda *a, **k: [dict(base, available=True)])
        assert K._outbid_path(w, "France", "Austria", "war_1") == "(F1 → Austria → Outbid Britain's Bond)"

    def test_the_congress_lever_says_it(self, _w9_bonded):
        from backend.game_logic import congress
        from tests.test_congress_of_paris import _sit
        w = _w9_bonded
        _w9_quiet(_sit, w)
        key = w._make_diplo_key("Austria", "France")
        w.war_scores[key] = -45 if key.split("|")[0] == "Austria" else 45
        row = _w9_quiet(congress.answer, w, "Austria")
        text = _w9_quiet(congress.price, w, "Austria", row)["text"]
        assert ("sign a peace with Austria — " + _W9_PRICE + _W9_SHORT
                + " (F1 → Austria → Outbid Britain's Bond)") in text, text

    def test_the_war_panels_table_line_says_it(self, _w9_bonded):
        from backend.game_logic.war_status import build_active_wars
        w = _w9_bonded
        out = _w9_quiet(build_active_wars, w)
        lines = [line for war in out["wars"] for line in (war.get("peace_table") or {}).get("lines", [])
                 if "is bound not to sign alone" in line]
        assert lines == ["Austria is bound not to sign alone: " + _W9_PRICE + _W9_SHORT + "."], lines

    def test_the_four_surfaces_quote_one_sentence(self, _w9_bonded):
        """The class pin: whatever the surface, the sum and the chest beside
        it are the same words (the price line is the one home)."""
        from backend.game_logic import bond as B
        from backend.game_logic import counsel as K
        w = _w9_bonded
        home = B.price_line(w, "Austria", "France").rstrip(".")
        assert home.endswith("pays it" + _W9_SHORT)
        with contextlib.redirect_stdout(io.StringIO()):
            roads = (K._table_road(w, "France", "Austria", alone=True)["bond_line"],
                     K._bilateral_road(w, "France", "Austria", "peace", "send_peace")["bond_line"])
        assert all(home.split(";")[1] in r for r in roads)
        assert home.split(";")[1] in _w9_outbid(w)["effect_text"]

    def test_the_callers_still_take_the_old_arguments(self):
        """Source pin: the four callers pass the court and the player, the
        chest rides inside `price_line` (nothing was added to their calls)."""
        for rel, needle in (("congress.py", "_bond.price_line(world, court, _player(world))"),
                            ("counsel.py", "_bond_price(world, court, player)"),
                            ("war_status.py", "_bond_price(world, c[\"nation\"], france)")):
            src = (_W9_ROOT / "backend" / "game_logic" / rel).read_text(encoding="utf-8")
            assert needle in src, rel


# ══════════════════════════════════════════════════════════════════════════
# S14E-X128 — a table row that opens one court of several is display copy
# ══════════════════════════════════════════════════════════════════════════

def _w9_display_only_keys() -> set:
    src = _w9_src("diplomacy_wizard.gd")
    block = src[src.index("const ECHO_IS_DISPLAY_ONLY"):src.index("func echo_note")]
    return set(re.findall(r'^\t"(\w+)": "', block, re.M))


def _w9_wizard_payload(row: dict, nation: str = "Britain") -> dict:
    """What `diplomacy_wizard._structured_payload_for_action("open_settlement")`
    sends for this Cabinet row (pinned against the GDScript source below): the
    Python mirror the tests drive main.gd's key choice with."""
    data = {"action": "propose_common_peace", "target_nation": nation}
    if row.get("war_id"):
        data["war_id"] = str(row["war_id"])
    if row.get("counsel_coverage"):
        data["counsel_coverage"] = list(row["counsel_coverage"])
    gold = int(float(row.get("gold_offer", 0) or 0))
    if gold > 0:
        data["gold_offer"] = gold
        data["echo_key"] = "open_settlement_offer"
    elif bool(row.get("echo_display_only", False)):
        data["echo_key"] = "open_settlement_alone"
    return data


def _w9_main_key(data: dict) -> str:
    """The key `main.gd::_on_wizard_structured_command_selected` looks the echo
    note up by: `data.get("echo_key", data.get("action", ""))`."""
    return str(data.get("echo_key", data.get("action", "")))


def _w9_covered(response: dict) -> list:
    return sorted(response["diplomatic_dialogue"]["covered_enemy_participants"])


class TestS14EX128:
    """Reproduced (before the fix, on the shipped 1805 board at 20 / 20 / 20,
    France holding the shipped 800 gold - the Britain page's lever row, shut
    to the sum): the Cabinet's "Open Settlement with Britain alone" row
    carries `counsel_coverage: ["Britain"]` and no `gold_offer`; the wizard
    stamps no `echo_key`, so `main.gd` parked the echo "propose common peace
    with Britain" on the up-arrow with no disclosure - and re-sent, it opens
    the WHOLE table (Britain, Austria and Russia) where the row opened
    Britain alone. The same for an `open_settlement` row the counsel stamps
    through `diplomacy.counsel_first` (a best road that is a table road
    with a declared draft)."""

    # ── the backend flags the row ────────────────────────────────────────

    def test_the_unfunded_lever_row_is_flagged_display_only(self, _w9_world):
        preview = _w9_preview(_w9_world)
        row = _w9_lever_row(preview)
        assert "gold_offer" not in row, "800 gold cannot fund the sum: the row stages none"
        assert row["echo_display_only"] is True

    def test_the_funded_lever_row_is_flagged_too(self, _w9_world):
        w = _w9_world
        w.nation_gold["France"] = 3000
        row = _w9_lever_row(_w9_preview(w))
        assert row["gold_offer"] > 0 and row["echo_display_only"] is True

    def test_the_whole_table_row_keeps_a_typeable_echo(self, _w9_world):
        """The whole-table row IS what its echo types: no flag."""
        preview = _w9_preview(_w9_world)
        whole = next(a for a in _w9_table_rows(preview) if "counsel_coverage" not in a)
        assert "whole table" in whole["display_name"] and "echo_display_only" not in whole
        assert "echo_display_only" not in next(
            a for a in preview["actions"] if a["action"] == "propose_white_peace")

    def test_a_counsel_stamped_alone_row_is_flagged(self, _w9_world):
        """`counsel_first` stamps the best table road's coverage on the
        `open_settlement` row; `name_the_courts_a_peace_row_addresses` reads
        the war's whole table and flags the row that narrows it."""
        from backend.game_logic import diplomacy as D
        w = _w9_world
        row = {"action": "open_settlement", "display_name": "Open Settlement", "available": True}
        rows = D.counsel_first([dict(row)], "", "", rec_action="open_settlement",
                               rec_coverage=["Britain"])
        out = D.name_the_courts_a_peace_row_addresses(w, "Britain", rows)
        assert out[0]["counsel_coverage"] == ["Britain"] and out[0]["addresses"] == ["Britain"]
        assert out[0]["echo_display_only"] is True

    def test_a_counsel_stamped_whole_table_is_not(self, _w9_world):
        from backend.game_logic import diplomacy as D
        w = _w9_world
        row = {"action": "open_settlement", "display_name": "Open Settlement", "available": True}
        whole = ["Britain", "Austria", "Russia"]
        rows = D.counsel_first([dict(row)], "", "", rec_action="open_settlement", rec_coverage=whole)
        out = D.name_the_courts_a_peace_row_addresses(w, "Britain", rows)
        assert out[0]["counsel_coverage"] == whole and "echo_display_only" not in out[0]
        # no coverage stamped at all: the row opens the whole table, as typed
        out = D.name_the_courts_a_peace_row_addresses(w, "Britain", [dict(row)])
        assert "echo_display_only" not in out[0]

    def test_where_the_court_is_the_whole_table_it_is_not(self, _w9_world):
        """A war with one enemy left: the court alone IS the whole table, and
        the typed echo opens exactly that."""
        from backend.game_logic import diplomacy as D
        w = _w9_world
        for other in ("Britain", "Russia"):
            w.diplomatic_states[w._make_diplo_key("France", other)] = "PEACE"
        w.invalidate_bloc_members_cache()
        row = {"action": "open_settlement", "display_name": "Open Settlement", "available": True}
        rows = D.counsel_first([dict(row)], "", "", rec_action="open_settlement",
                               rec_coverage=["Austria"])
        out = D.name_the_courts_a_peace_row_addresses(w, "Austria", rows)
        assert out[0]["counsel_coverage"] == ["Austria"] and "echo_display_only" not in out[0]

    def test_only_the_wizards_page_gains_the_flag(self, _w9_world):
        """Golden Rule 5: the preview (the player's Cabinet) is where the row is
        flagged; the list every other reader takes keeps its rows."""
        from backend.game_logic import diplomacy as D
        w = _w9_world
        rows = _w9_quiet(D.get_available_diplomatic_actions, w, "Britain")
        assert all("echo_display_only" not in r for r in rows)

    # ── the typed echo really does something else ────────────────────────

    def test_the_lever_echo_typed_opens_the_whole_table(self, _w9_boot, _w9_client):
        """Why the note is honest: the structured send opens the court alone;
        the same line typed (the up-arrow re-sends it) opens the whole table."""
        echo = "propose common peace with Britain"

        def _board():
            w = _w9_copy(_w9_boot)
            w.diplomatic_points = 30
            _w9_scores(w)
            return w

        w = _board()
        row = _w9_lever_row(_w9_preview(w))
        body = {"command": echo, **_w9_wizard_payload(row)}
        body.pop("echo_key", None)
        structured = _w9_post(_w9_client(w), body)
        assert _w9_covered(structured) == ["Britain"]
        typed = _w9_post(_w9_client(_board()), {"command": echo})
        assert _w9_covered(typed) == ["Austria", "Britain", "Russia"]

    # ── the wizard maps the flag to a registered key ─────────────────────

    def test_the_wizard_stamps_the_alone_key_after_the_offer_branch(self):
        src = _w9_src("diplomacy_wizard.gd")
        arm = _w9_func(src, "_structured_payload_for_action")
        lever = arm[arm.index('if action_id == "open_settlement":'):
                    arm.index('if action_id == "propose_white_peace":')]
        offer = lever.index('data["echo_key"] = "open_settlement_offer"')
        flag = lever.index('elif bool(action_payload.get("echo_display_only", false)):')
        alone = lever.index('data["echo_key"] = "open_settlement_alone"')
        assert lever.index("if offer_gold > 0:") < offer < flag < alone < lever.index("return data")
        # tests/test_settlement_ui_slice_f_source.py: the helper's body never
        # says the word the emit signal is named for - not in a comment either
        addition = lever[lever.index("# S14E-X128"):]
        assert re.search(r"\bcommand\b", addition) is None
        # the whole-table row (no gold, no flag) is still un-stamped
        assert "echo_key" not in lever[:lever.index("# S14E-D7")]

    def test_the_alone_key_is_registered_with_its_disclosure(self):
        keys = _w9_display_only_keys()
        assert keys == {"propose_white_peace", "outbid_bond", "open_settlement_offer",
                        "open_settlement_alone"}, keys
        src = _w9_src("diplomacy_wizard.gd")
        line = next(l for l in src.splitlines() if l.startswith('\t"open_settlement_alone": "'))
        assert "whole table" in line and "alone" in line

    def test_main_still_reads_the_key_first(self):
        body = _w9_func(_w9_src("main.gd"), "_on_wizard_structured_command_selected")
        assert 'diplomacy_wizard.echo_note(str(data.get("echo_key", data.get("action", ""))))' in body

    def test_the_unfunded_lever_payload_finds_its_note(self, _w9_world):
        """The mirror, row to key: the flagged row's payload carries the alone
        key main.gd looks up; the old lookup (the action) found nothing."""
        row = _w9_lever_row(_w9_preview(_w9_world))
        data = _w9_wizard_payload(row)
        assert data["action"] not in _w9_display_only_keys()      # the dead lookup
        assert _w9_main_key(data) == "open_settlement_alone"
        assert _w9_main_key(data) in _w9_display_only_keys()

    def test_the_funded_lever_keeps_the_sum_note(self, _w9_world):
        w = _w9_world
        w.nation_gold["France"] = 3000
        data = _w9_wizard_payload(_w9_lever_row(_w9_preview(w)))
        assert _w9_main_key(data) == "open_settlement_offer"

    def test_the_whole_table_row_keeps_its_lookup(self, _w9_world):
        whole = next(a for a in _w9_table_rows(_w9_preview(_w9_world)) if "counsel_coverage" not in a)
        data = _w9_wizard_payload(whole)
        assert "echo_key" not in data
        assert _w9_main_key(data) not in _w9_display_only_keys()

    # ── the census's rule: an echo that cannot be typed is display-only ──

    def test_the_census_drives_the_new_key(self):
        src = (_W9_ROOT / "tests" / "test_cn4_the_chip_honesty_census.py").read_text(encoding="utf-8")
        assert "S14E-X128" in src and '"open_settlement_alone"' in src
        assert "echo_display_only" in src

