# ══════════════════════════════════════════════════════════════════════════
# S14E-35 — Europe's quiet-turns clock, kept on the world
# ══════════════════════════════════════════════════════════════════════════

@pytest.fixture
def _r35_world(_rk_boot):
    return _rk_copy(_rk_boot)


def _r35_fight(world):
    """A REAL battle on the shipped board: Massena (aggressive, 42,000) at
    Bohemia marches for Milan and fights Archduke John at Tyrol on his first
    step — the executor's own pipeline stamps the battle."""
    from backend.commands.executor import CommandExecutor
    massena = world.get_marshal("Massena")
    massena.location = "Bohemia"
    world.calculate_visibility()
    with _rk_quiet():
        result = CommandExecutor().execute({
            "command": {"raw_input": "Massena, move Milan", "marshal": "Massena",
                        "action": "move", "target": "Milan"},
            "is_strategic": True, "strategic_type": "MOVE_TO",
        }, {"world": world})
    assert result.get("first_step_combat") is True
    return massena


def _r35_the_last_stamp_is_a_lone_corps(world, turn=13):
    """Turn 19, the French roster's old stamps at turn 4, and the latest
    battle (turn 13) stamped on ONE corps — the sea #13 board."""
    world.current_turn = 19
    for m in world.marshals.values():
        if m.nation == "France":
            m.last_battle_turn = 4
    lone = world.get_marshal("Massena")
    lone.last_battle_turn = turn
    return lone


class TestS14E35:
    """Reproduced (the shipped 1805 board, turn 19): the French roster's latest
    stamp is Massena's, from a battle on turn 13 — `hegemon_quiet_turns` = 6;
    Massena stands down / is destroyed and the count reads 19 − 4 = 15, the
    league's consult/declare turns jumping with it. After the fix the battle
    is stamped on the WORLD (`last_battle_turn_by_nation`) and the count
    reads the max of the store and the roster."""

    def test_a_real_battle_stamps_the_world(self, _r35_world):
        w = _r35_world
        w.current_turn = 19
        assert w.last_battle_turn_by_nation == {}
        massena = _r35_fight(w)
        assert massena.last_battle_turn == 19
        assert w.last_battle_turn_by_nation == {"France": 19, "Austria": 19}

    def test_a_stand_down_leaves_the_count_unchanged(self, _r35_world):
        from backend.game_logic import coalition as CO
        w = _r35_world
        w.current_turn = 19
        massena = _r35_fight(w)
        assert CO.hegemon_quiet_turns(w, "France") == 0
        w.current_turn = 21
        before = CO.hegemon_quiet_turns(w, "France")
        assert before == 2
        assert w.stand_down_marshal(massena) is True
        assert w.get_marshal("Massena") is None
        assert CO.hegemon_quiet_turns(w, "France") == before

    def test_a_destroyed_lone_corps_leaves_the_count_unchanged(self, _r35_world):
        from backend.game_logic import coalition as CO
        w = _r35_world
        w.current_turn = 19
        _r35_fight(w)
        w.current_turn = 21
        before = CO.hegemon_quiet_turns(w, "France")
        assert before == 2
        assert w.destroy_marshal("Massena", cause="battle", log=False)
        assert w.get_marshal("Massena") is None
        assert CO.hegemon_quiet_turns(w, "France") == before

    def test_the_sea_13_board_a_standing_down_does_not_jump_the_clock(self, _r35_world):
        """The sighting: 19 − 13 = 6, then the corps came home and the next
        stamp (turn 4) read 20 − 16; the count must run 6 → 7."""
        from backend.game_logic import coalition as CO
        w = _r35_world
        lone = _r35_the_last_stamp_is_a_lone_corps(w)
        w.stamp_battle_turn("France", int(lone.last_battle_turn))
        assert CO.hegemon_quiet_turns(w, "France") == 6
        assert w.stand_down_marshal(lone) is True
        w.current_turn = 20
        assert CO.hegemon_quiet_turns(w, "France") == 7

    def test_a_marshal_at_zero_strength_does_not_erase_the_history(self, _r35_world):
        from backend.game_logic import coalition as CO
        w = _r35_world
        lone = _r35_the_last_stamp_is_a_lone_corps(w)
        w.stamp_battle_turn("France", 13)
        lone.strength = 0
        assert CO.hegemon_quiet_turns(w, "France") == 6

    def test_the_helper_keeps_the_latest_and_ignores_the_blank(self, _r35_world):
        w = _r35_world
        w.stamp_battle_turn("France", 9)
        w.stamp_battle_turn("France", 4)
        w.stamp_battle_turn("", 12)
        w.stamp_battle_turn("France", -1)
        assert w.last_battle_turn_by_nation == {"France": 9}
        w.stamp_battle_turn("France", 11)
        assert w.last_battle_turn_by_nation == {"France": 11}

    def test_the_store_round_trips_and_an_old_save_reads_as_today(self, _r35_world):
        from backend.game_logic import coalition as CO
        from backend.models.world_state import WorldState
        w = _r35_world
        w.current_turn = 19
        w.stamp_battle_turn("France", 13)
        data = json.loads(json.dumps(w.to_dict(), default=str))
        assert data["last_battle_turn_by_nation"] == {"France": 13}
        loaded = WorldState.from_dict(data)
        assert loaded.last_battle_turn_by_nation == {"France": 13}
        assert all(isinstance(v, int) for v in loaded.last_battle_turn_by_nation.values())
        data.pop("last_battle_turn_by_nation")
        old = WorldState.from_dict(data)
        assert old.last_battle_turn_by_nation == {}
        for m in old.marshals.values():
            if m.nation == "France":
                m.last_battle_turn = 4
        old.current_turn = 19
        assert CO.hegemon_quiet_turns(old, "France") == 15     # the roster alone, as today

    def test_a_world_that_never_fought_counts_from_the_boot(self, _r35_world):
        from backend.game_logic import coalition as CO
        w = _r35_world
        w.current_turn = 7
        assert CO.hegemon_quiet_turns(w, "France") == 7
        assert CO.hegemon_quiet_turns(w, "France", ahead=2) == 9

    def test_the_seam_is_one_function_and_the_old_reading_is_the_roster(self, _r35_world):
        """The orchestrator's arm swaps `last_battle_turn_of` for the roster
        reading — the old behaviour, byte for byte."""
        from backend.game_logic import coalition as CO
        w = _r35_world
        lone = _r35_the_last_stamp_is_a_lone_corps(w)
        w.stamp_battle_turn("France", 13)
        w.stand_down_marshal(lone)
        assert CO.last_battle_turn_of(w, "France") == 13
        assert CO.roster_last_battle_turn(w, "France") == 4
        orig = CO.last_battle_turn_of
        try:
            CO.last_battle_turn_of = CO.roster_last_battle_turn
            assert CO.hegemon_quiet_turns(w, "France") == 15
        finally:
            CO.last_battle_turn_of = orig
        assert CO.hegemon_quiet_turns(w, "France") == 6

    def test_the_forecast_cache_sees_the_stamp(self, _r35_world):
        """`_league_signature` keys the forecast on the roster's stamps; a
        store write with no marshal change must key differently too."""
        from backend.game_logic import coalition as CO
        w = _r35_world
        before = CO._league_signature(w, "France")
        w.stamp_battle_turn("France", 5)
        assert CO._league_signature(w, "France") != before

    def test_the_stamp_sites_write_through_the_one_helper(self):
        src = (_RK_ROOT / "backend/commands/combat_executor.py").read_text(encoding="utf-8")
        assert src.count(".stamp_battle_turn(") >= 3
        assert len(re.findall(r"\.last_battle_turn = _w6_turn", src)) == 3


# ══════════════════════════════════════════════════════════════════════════
# S14E-X22 — an ally's capture of a court's last province ends our war too
# ══════════════════════════════════════════════════════════════════════════

_RX22_LINE = "Hanover has no province left — the war is over, Sire."


@pytest.fixture
def _rx22_world(_rk_boot):
    return _rk_copy(_rk_boot)


def _rx22_rump(world, keep=("Osnabruck",), taker="Prussia"):
    """Hanover keeps ``keep``; ``taker`` holds the rest of its 1805 homeland."""
    for name in world.nation_starting_regions["Hanover"]:
        world.regions[name].controller = "Hanover" if name in keep else taker
    world.invalidate_active_nations_cache()
    return world


def _rx22_at(world, a, b, state):
    from backend.game_logic.diplomacy import set_diplomatic_state
    set_diplomatic_state(world, a, b, state, "test")


@contextlib.contextmanager
def _rx22_client(world):
    import backend.main as main_module
    from backend.commands.parser import CommandParser
    from fastapi.testclient import TestClient
    originals = (main_module.game_state["world"], main_module.world, main_module.parser)
    main_module.game_state["world"] = world
    main_module.world = world
    main_module.parser = CommandParser(use_real_llm=False)
    try:
        yield TestClient(main_module.app)
    finally:
        (main_module.game_state["world"], main_module.world,
         main_module.parser) = originals


class TestS14EX22:
    """Reproduced (the shipped 1805 board, Hanover a rump of Osnabruck, France
    at WAR with Hanover): Prussia's `capture_region("Osnabruck", "Prussia")`
    tore the war down to PEACE and left `_elimination_receipts` empty — the
    player had the rail icon and next morning's dispatch only. After the fix
    the war's end is read BEFORE the PEACE teardown and the player's reply
    carries "Hanover has no province left — the war is over, Sire." """

    def test_an_allys_capture_of_the_last_province_says_the_war_is_over(self, _rx22_world):
        w = _rx22_rump(_rx22_world)
        _rx22_at(w, "France", "Hanover", "WAR")
        _rx22_at(w, "France", "Prussia", "ALLIANCE")
        assert w.capture_region("Osnabruck", "Prussia") is True
        assert w.get_diplomatic_state("France", "Hanover") == "PEACE"      # the teardown ran
        assert w._elimination_receipts == [_RX22_LINE]

    def test_the_line_rides_the_reply_once(self, _rx22_world):
        w = _rx22_rump(_rx22_world)
        _rx22_at(w, "France", "Hanover", "WAR")
        _rx22_at(w, "France", "Prussia", "ALLIANCE")
        w.capture_region("Osnabruck", "Prussia")
        with _rx22_client(w) as client:
            first = client.post("/command", json={"command": "status"}).json()
            again = client.post("/command", json={"command": "status"}).json()
        assert _RX22_LINE in first["message"]
        assert "has no province left" not in again["message"]

    def test_a_third_courts_capture_ends_our_war_with_the_dying_court_too(self, _rx22_world):
        w = _rx22_rump(_rx22_world, taker="Russia")
        _rx22_at(w, "France", "Hanover", "WAR")
        w.capture_region("Osnabruck", "Russia")
        assert w._elimination_receipts == [_RX22_LINE]

    def test_the_players_own_capture_still_says_it(self, _rx22_world):
        w = _rx22_rump(_rx22_world)
        _rx22_at(w, "France", "Hanover", "WAR")
        w.capture_region("Osnabruck", "France")
        assert w._elimination_receipts == [_RX22_LINE]

    def test_a_court_the_player_was_not_at_war_with_is_silent(self, _rx22_world):
        """An ally's capture from a court the player was at PEACE with ends no
        war of his — nothing to say."""
        w = _rx22_rump(_rx22_world)
        _rx22_at(w, "France", "Hanover", "PEACE")
        w.capture_region("Osnabruck", "Prussia")
        assert not getattr(w, "_elimination_receipts", None)

    def test_a_capture_that_leaves_a_province_is_silent(self, _rx22_world):
        w = _rx22_rump(_rx22_world, keep=("Osnabruck", "Oldenburg"))
        _rx22_at(w, "France", "Hanover", "WAR")
        w.capture_region("Osnabruck", "Prussia")
        assert not getattr(w, "_elimination_receipts", None)

    def test_an_armistice_is_not_a_war_that_ends(self, _rx22_world):
        w = _rx22_rump(_rx22_world)
        _rx22_at(w, "France", "Hanover", "ARMISTICE")
        w.capture_region("Osnabruck", "Prussia")
        assert not getattr(w, "_elimination_receipts", None)


# ══════════════════════════════════════════════════════════════════════════
# S14E-X38 — a third power's treaty break names its cost to France
# ══════════════════════════════════════════════════════════════════════════

_RX38_CLAUSE = "relations with every court, France's included, fall 10"


@pytest.fixture
def _rx38_world(_rk_boot):
    return _rk_copy(_rk_boot)


def _rx38_treaty(world, a, b, state="ALLIANCE", kind="alliance"):
    key = world._make_diplo_key(a, b)
    world.diplomatic_states[key] = state
    world.active_treaties = {key: {"type": kind, "nations": [a, b]}}
    world.nation_relations[key] = 50
    world.nation_dp = {a: 5, b: 5}
    return key


def _rx38_break(world, key, breaker):
    from backend.game_logic.diplomacy import break_treaty
    with _rk_quiet():
        return break_treaty(key, breaker, world)


def _rx38_rail(world):
    return [n["message"] for n in world.notifications.get_pending()
            if "broken" in n["message"]]


def _rx38_beat(world):
    return [e for e in world.pending_dispatch_events if e["type"] == "diplomatic_treaty_broken"]


class TestS14EX38:
    """Reproduced (the shipped 1805 board, Austria breaks the Austro-Prussian
    alliance — France a bystander): `break_treaty` took 10 off Austria's
    relation with France (-80 -> -90) and the rail read "Austria has broken
    the Full Alliance with Prussia without seeking release." — no cost named.
    The AI-to-AI downgrade (`ai_ai_downgrade`) writes ONLY the pair's
    `relation_target` — it never reaches `execute_downgrade`'s `relation_all`
    (that verb is the player's alone) — so it costs France nothing and the
    row's downgrade half has no cost to name (pinned below). S14E-D13 /
    S14E-X120 (S14f p3) then routed the AI downgrade through
    `execute_downgrade`: that last pin is flipped, the clause now names the
    cost the downgrade takes."""

    def test_the_rail_beat_names_the_cost_the_break_applied(self, _rx38_world):
        w = _rx38_world
        key = _rx38_treaty(w, "Austria", "Prussia")
        fk = w._make_diplo_key("Austria", "France")
        before = int(w.nation_relations[fk])
        result = _rx38_break(w, key, "Austria")
        assert result["success"] is True
        assert int(w.nation_relations[fk]) == before - 10             # applied
        assert _rx38_rail(w) == [
            f"Austria has broken the Full Alliance with Prussia without seeking release — "
            f"{_RX38_CLAUSE}."]                                         # shown

    def test_the_dispatch_beat_and_the_campaign_log_read_the_same_line(self, _rx38_world):
        from backend.campaign_log import format_event_oneliner
        from backend.game_logic.dispatch import _format_dispatch_event_text
        w = _rx38_world
        key = _rx38_treaty(w, "Austria", "Prussia")
        _rx38_break(w, key, "Austria")
        beat = _rx38_beat(w)[-1]
        text = _format_dispatch_event_text("diplomatic_treaty_broken", beat["template_vars"])
        assert text.endswith(f"— {_RX38_CLAUSE}.")
        logged = [e for e in w.event_log if e.get("type") == "diplomatic_treaty_broken"][-1]
        assert logged["relation_cost"] == 10
        assert format_event_oneliner(logged, w).endswith(f"— {_RX38_CLAUSE}.")

    def test_the_figure_is_the_one_break_treaty_applies(self, _rx38_world):
        from backend.game_logic import diplomacy as D
        w = _rx38_world
        key = _rx38_treaty(w, "Austria", "Prussia")
        assert D.treaty_break_cost_to_player(w, "Austria", "Prussia") == D.TREATY_BREAK_RELATION_ALL
        result = _rx38_break(w, key, "Austria")
        hits = [c["delta"] for c in result["relation_changes"] if "France" in c["nations"]]
        assert hits == [-D.TREATY_BREAK_RELATION_ALL]

    def test_a_break_france_is_party_to_names_no_cost(self, _rx38_world):
        """France the injured party (her own relation takes the -30/-40 of the
        pair) or the breaker (her own act, priced in her dialogue)."""
        w = _rx38_world
        key = _rx38_treaty(w, "Austria", "France")
        _rx38_break(w, key, "Austria")
        assert _rx38_rail(w) and "fall 10" not in _rx38_rail(w)[0]
        w2 = _rk_copy(_rx38_world)
        key2 = _rx38_treaty(w2, "France", "Prussia")
        w2.diplomatic_points = 3
        _rx38_break(w2, key2, "France")
        assert _rx38_rail(w2) and "fall 10" not in _rx38_rail(w2)[0]
        assert all(e["template_vars"]["relation_cost"] == 0 for e in _rx38_beat(w2))

    def test_a_cascade_break_is_untouched(self):
        from backend.game_logic.commitments_routing import format_commitments_notice
        text = format_commitments_notice("diplomatic_treaty_broken", {
            "breaker": "Prussia", "injured_party": "Austria", "treaty_type_display": "Full Alliance",
            "end_reason_family": "obsolescence_or_external", "relation_cost": 10})
        assert text == "Prussia was forced to break the Full Alliance with Austria (cascade)."

    def test_a_pre_fix_event_without_the_figure_renders_as_before(self):
        from backend.game_logic.commitments_routing import format_commitments_notice
        text = format_commitments_notice("diplomatic_treaty_broken", {
            "breaker": "Austria", "injured_party": "Prussia", "treaty_type_display": "Full Alliance",
            "reason_phrase": "without seeking release"})
        assert text == "Austria has broken the Full Alliance with Prussia without seeking release."

    def test_the_clause_follows_the_declaration_idiom(self):
        from backend.game_logic.commitments_routing import format_commitments_notice
        from backend.game_logic.diplomacy import declaration_cost_clause
        text = format_commitments_notice("diplomatic_treaty_broken", {
            "breaker": "Austria", "injured_party": "Prussia", "treaty_type_display": "Full Alliance",
            "reason_phrase": "without seeking release", "relation_cost": 10, "player": "France"})
        assert text.endswith(" — " + declaration_cost_clause(10, "France") + ".")
        assert not any(w in text for w in ("!", "crush", "strike"))     # the Voice Bible's never-says

    def test_an_ai_downgrade_names_its_cost_to_france_because_it_takes_it(self, _rx38_world):
        """S14E-D13 / S14E-X120: FLIPPED. The pin said an AI downgrade "costs
        France nothing and says so by saying nothing" because `ai_ai_downgrade`
        wrote the pair's relation only. It now walks `execute_downgrade` (the
        seam `_ai_ai_downgrade`), which takes `relation_all` off the actor's
        relation with every court - France's included - so the line names that
        cost (X38's clause) and the figure is the one applied. The lower two
        steps cost France nothing and name nothing (`TestS14EX120`)."""
        src = (_RK_ROOT / "backend/game_logic/ai_diplomacy.py").read_text(encoding="utf-8")
        start = src.index("result = _ai_ai_downgrade(")
        block = src[start:start + 2400]
        assert "declaration_cost_clause" in block
        assert 'rel_hit = penalty.get("relation_target", -10)' not in block


# ══════════════════════════════════════════════════════════════════════════
# S14E-X63 — the Congress clock says the Ireland carve settles Munster
# ══════════════════════════════════════════════════════════════════════════

@pytest.fixture
def _rx63_world(_rk_boot):
    return _rk_copy(_rk_boot)


def _rx63_hold(world, *names):
    for name in names:
        world.regions[name].controller = "France"
    world.invalidate_active_nations_cache()
    return world


class TestS14EX63:
    """Reproduced (the shipped 1805 board, Free Ireland begun — France on
    Munster, Ulster still to take, the war with Britain running):
    `congress.state_line` read "… 35 of 45 titled (1 held, unsettled: Munster)
    — summon from the Cabinet (F1)" with no hint that the Ireland carve is
    what settles Munster. It now reads "(1 held, unsettled: Munster — on the
    road to Ireland)". No exact-string pin flipped: the pins on that tail
    (test_congress_of_paris.py::test_the_held_unsettled_provinces_are_named,
    test_sr1c_the_gate_line_teaches_the_road.py) name Tyrol, Bohemia and
    Vienna, which lie on no begun road."""

    def test_the_boot_line_is_byte_identical(self, _rx63_world):
        """Nothing held on a road: the line is the gate line, as before."""
        from backend.game_logic import congress
        line = congress.state_line(_rx63_world)
        assert line.startswith("THE CONGRESS OF PARIS — 35 of 45 titled · ")
        assert "unsettled" not in line and "road to" not in line

    def test_a_held_province_on_a_begun_carve_names_its_road(self, _rx63_world):
        from backend.game_logic import congress
        w = _rx63_hold(_rx63_world, "Munster")
        line = congress.state_line(w)
        assert "(1 held, unsettled: Munster — on the road to Ireland)" in line
        payload = congress.clock_payload(w)
        assert "(1 held, unsettled: Munster — on the road to Ireland)" in payload["line"]

    def test_the_clause_is_the_road_notes_own_province_set(self, _rx63_world):
        from backend.game_logic.formations import road_clause_for, road_notes
        w = _rx63_hold(_rx63_world, "Munster")
        notes = road_notes(w)
        for province in ("Munster", "Ulster"):
            assert province in notes["by_province"]
            assert road_clause_for(w, province, notes) == "on the road to Ireland"
        assert road_clause_for(w, "Tyrol", notes) == ""

    def test_a_held_province_on_no_road_is_unchanged(self, _rx63_world):
        from backend.game_logic import congress
        w = _rx63_hold(_rx63_world, "Tyrol")
        line = congress.state_line(w)
        assert "(1 held, unsettled: Tyrol)" in line
        assert "road to" not in line

    def test_a_mixed_list_clauses_only_the_province_on_the_road(self, _rx63_world):
        from backend.game_logic import congress
        w = _rx63_hold(_rx63_world, "Munster", "Tyrol")
        held = congress.titled(w)["held"]
        assert set(held) == {"Munster", "Tyrol"}
        line = congress.state_line(w)
        assert "Munster — on the road to Ireland" in line
        assert "Tyrol — on the road" not in line

    def test_a_road_whose_war_has_ended_still_points_at_the_carve(self, _rx63_world):
        from backend.game_logic import congress
        from backend.game_logic.diplomacy import set_diplomatic_state
        w = _rx63_hold(_rx63_world, "Munster")
        set_diplomatic_state(w, "France", "Britain", "PEACE", "test")
        assert "Munster — on the road to Ireland" in congress.state_line(w)

    def test_a_whole_held_carve_adds_nothing(self, _rx63_world):
        """Both provinces held and the war running: a `ready` road feeds only
        the war card and the review — the clock adds nothing to the names."""
        from backend.game_logic import congress
        w = _rx63_hold(_rx63_world, "Munster", "Ulster")
        line = congress.state_line(w)
        assert "Munster" in line and "road to" not in line


# ══════════════════════════════════════════════════════════════════════════
# S14E-D9 / X62 — a Class T dream's one line on the war card and the review
# ══════════════════════════════════════════════════════════════════════════

_RD9_CLAUSE = "and closes the climb to Italy, Naples and Rome not yet held"
_RD9_REVIEW = "This peace ends the war and closes the climb to Italy — Naples and Rome not yet held."


@pytest.fixture
def _rd9_world(_rk_boot):
    return _rk_copy(_rk_boot)


def _rd9_empty():
    return {"roads": [], "by_province": {}, "by_court": {}, "completing": []}


def _rd9_summary(world) -> dict:
    with _rk_quiet():
        return world.get_filtered_game_state_summary()


def _rd9_austria_holds_the_dream(world):
    """Italy (a French satellite, 2 of 5) lacks Naples and Rome; Austria, at
    war with France, holds both."""
    for name in ("Naples", "Rome"):
        world.regions[name].controller = "Austria"
    world.invalidate_active_nations_cache()
    return world


class TestS14ED9:
    """Reproduced (the shipped 1805 board, Austria holding Naples and Rome,
    France at war with Austria, Italy 2 of 5 in France's bloc): the war card
    read "" for Austria and the peace review listed no road — a peace that
    ends the war with the court holding the dream's missing provinces closed
    the climb unannounced. Built as the ruling recommended: NO pointers on
    the panels (the Italy watcher at 2 of 5 would stamp the boot's panels);
    ONE line on the war card and the peace review, only when the watched
    nation is in the player's bloc or the player is its ex-lord."""

    def test_the_boot_board_stamps_nothing_anywhere(self, _rd9_world):
        from backend.game_logic import naval
        from backend.game_logic.formations import (
            get_formation_watch, road_note_for, road_notes, road_peace_lines,
        )
        from backend.game_logic.war_status import _held_line
        w = _rd9_world
        # Italy stands at 2 of 5 and Holland at 0 of 1 in France's bloc — but
        # no court at war holds a province either dream still lacks
        assert get_formation_watch(w, "KingdomOfItaly")["progress"] == "2 of 5 provinces held"
        assert road_notes(w) == _rd9_empty()
        assert road_note_for(w, "Rome") == "" and road_note_for(w, "Flanders") == ""
        for court in ("Austria", "Britain", "Russia"):
            assert road_peace_lines(w, [court], [{"type": "peace"}]) == []
        assert _held_line(w, "France", ["Austria", "Britain", "Russia"]) == ""
        assert not any("road_note" in row for row in _rd9_summary(w)["map_data"].values())
        assert not any("Italy" in n for n in
                       naval.build_admiralty_report(w).get("expedition_notes", []))

    def test_the_war_card_says_a_peace_closes_the_climb(self, _rd9_world):
        from backend.game_logic.formations import road_notes, road_war_card_clause
        from backend.game_logic.war_status import _held_line
        w = _rd9_austria_holds_the_dream(_rd9_world)
        notes = road_notes(w)
        [row] = notes["by_court"]["Austria"]
        assert row["cls"] == "T" and row["tag"] == "KingdomOfItaly"
        assert row["display_name"] == "Italy" and row["state"] == "open"
        assert row["missing"] == ["Naples", "Rome"] and row["held"] == ["Milan", "Piedmont"]
        assert road_war_card_clause(w, ["Austria", "Britain"], notes) == {"Austria": _RD9_CLAUSE}
        assert _held_line(w, "France", ["Austria"]) == (
            "A peace signed now closes the climb to Italy, Naples and Rome not yet held.")

    def test_no_panel_the_landing_or_the_admiralty_is_stamped(self, _rd9_world):
        """The pointer is on the war card and the review alone: the Class C
        sinks (`roads`, `by_province`, `completing`) stay empty, so the
        region payload, the capture/landing replies and the Admiralty add
        nothing."""
        from backend.game_logic import naval
        from backend.game_logic.formations import road_note_for, road_notes
        w = _rd9_austria_holds_the_dream(_rd9_world)
        notes = road_notes(w)
        assert notes["roads"] == [] and notes["by_province"] == {} and notes["completing"] == []
        assert road_note_for(w, "Rome") == "" and road_note_for(w, "Naples") == ""
        assert not any("road_note" in row for row in _rd9_summary(w)["map_data"].values())
        assert not any("Italy" in n for n in
                       naval.build_admiralty_report(w).get("expedition_notes", []))

    def test_the_peace_review_carries_the_line(self, _rd9_world):
        from backend.game_logic.formations import road_peace_lines
        w = _rd9_austria_holds_the_dream(_rd9_world)
        assert road_peace_lines(w, ["Austria"], [{"type": "peace"}]) == [_RD9_REVIEW]
        assert road_peace_lines(w, ["Britain"], [{"type": "peace"}]) == []   # holds none of it

    def test_the_bilateral_preview_and_the_letter_carry_it_too(self, _rd9_world):
        from backend.game_logic.diplomatic_dialogue import attach_status_quo_forecast
        w = _rd9_austria_holds_the_dream(_rd9_world)
        out = attach_status_quo_forecast(w, {"annotated_terms": [{"type": "peace"}]},
                                         "France", "Austria", {"clauses": []})
        assert out["status_quo_forecast"]["road_closing"] == [_RD9_REVIEW]

    def test_a_package_that_hands_the_province_to_the_dream_moves_it_on(self, _rd9_world):
        from backend.game_logic.formations import road_peace_lines
        w = _rd9_austria_holds_the_dream(_rd9_world)
        rome_to_italy = {"type": "territory_cede", "region": "Rome",
                         "from": "Austria", "to": "KingdomOfItaly"}
        assert road_peace_lines(w, ["Austria"], [{"type": "peace"}, rome_to_italy]) == [
            "This peace ends the war and closes the climb to Italy — Naples not yet held."]
        both = [{"type": "territory_cede", "regions": ["Naples", "Rome"],
                 "from": "Austria", "to": "KingdomOfItaly"}]
        assert road_peace_lines(w, ["Austria"], [{"type": "peace"}] + both) == []
        # ceded to France instead: the dream is no nearer
        to_france = [{"type": "territory_cede", "regions": ["Naples", "Rome"],
                      "from": "Austria", "to": "France"}]
        assert road_peace_lines(w, ["Austria"], [{"type": "peace"}] + to_france) == [_RD9_REVIEW]

    def test_a_dream_outside_the_players_bloc_adds_nothing(self, _rd9_world):
        from backend.game_logic.formations import road_notes
        w = _rd9_austria_holds_the_dream(_rd9_world)
        w.vassals.pop("KingdomOfItaly", None)
        w.invalidate_bloc_members_cache()
        assert "KingdomOfItaly" not in w.get_bloc_members("France")
        assert road_notes(w) == _rd9_empty()

    def test_the_ex_lord_of_a_carved_client_sees_its_dream(self, _rd9_world):
        """France carved the Duchy of Warsaw and released it: not in her bloc,
        but she is its ex-lord (the creation record's sponsor). Poland needs
        Lithuania and Volhynia — Russia, at war with France, holds both."""
        from backend.game_logic.formations import (
            create_client_nation, road_notes, road_peace_lines,
        )
        w = _rd9_world
        with _rk_quiet():
            create_client_nation(w, "DuchyOfWarsaw", "France", ceded_from="Prussia")
        w.vassals.pop("DuchyOfWarsaw", None)
        w.invalidate_bloc_members_cache()
        w.invalidate_active_nations_cache()
        assert "DuchyOfWarsaw" not in w.get_bloc_members("France")
        [row] = road_notes(w)["by_court"]["Russia"]
        assert row["cls"] == "T" and row["display_name"] == "Poland"
        assert row["missing"] == ["Lithuania", "Volhynia"]
        assert road_peace_lines(w, ["Russia"], [{"type": "peace"}]) == [
            "This peace ends the war and closes the climb to Poland — Lithuania and Volhynia not yet held."]

    def test_a_court_not_at_war_closes_nothing(self, _rd9_world):
        from backend.game_logic.diplomacy import set_diplomatic_state
        from backend.game_logic.formations import road_notes
        w = _rd9_austria_holds_the_dream(_rd9_world)
        with _rk_quiet():
            set_diplomatic_state(w, "France", "Austria", "PEACE", "test")
        assert road_notes(w) == _rd9_empty()
        with _rk_quiet():
            set_diplomatic_state(w, "France", "Austria", "ARMISTICE", "test")
        assert "Austria" in road_notes(w)["by_court"]       # a truce is the war, as the page reads it

    def test_a_formed_dream_adds_nothing(self, _rd9_world):
        from backend.game_logic.formations import road_notes
        w = _rd9_austria_holds_the_dream(_rd9_world)
        w.nation_formations["KingdomOfItaly"] = {"id": "risorgimento", "turn": 5, "formed": True}
        assert road_notes(w) == _rd9_empty()

    def test_a_class_c_road_is_unchanged_beside_it(self, _rd9_world):
        """Munster held (the Ireland carve) and Austria on Italy's soil: the
        Ireland rows, panels and war card are exactly as before; the dream's
        line joins the Austria card only."""
        from backend.game_logic.formations import road_notes
        from backend.game_logic.war_status import _held_line
        w = _rd9_austria_holds_the_dream(_rd9_world)
        w.regions["Munster"].controller = "France"
        notes = road_notes(w)
        [road] = notes["roads"]
        assert road["tag"] == "Ireland" and notes["completing"] == ["Ulster"]
        assert [r["tag"] for r in notes["by_court"]["Britain"]] == ["Ireland"]
        assert [r["tag"] for r in notes["by_court"]["Austria"]] == ["KingdomOfItaly"]
        assert "closes the Ireland carve, Ulster not yet held" in _held_line(w, "France", ["Britain"])
        assert "climb" not in _held_line(w, "France", ["Britain"])


class TestS14EX62:
    """The defect half of D9: Class T dream roads had no pointer at any point
    of action. The ruling's build (above) is the fix; this pins the row's own
    sentence — the dream's progress stays on the Formables page, byte for
    byte, and the builder reads the page's own watcher."""

    def test_the_formables_page_is_untouched_and_the_pointer_reads_its_watcher(self, _rd9_world):
        from backend.game_logic.formations import build_formables_payload, road_notes
        w = _rd9_austria_holds_the_dream(_rd9_world)
        page = {r["tag"]: r for r in build_formables_payload(w)["formables"]}
        assert page["KingdomOfItaly"]["cls"] == "T"
        assert page["KingdomOfItaly"]["progress"] == "2 of 5 provinces held"
        [row] = road_notes(w)["by_court"]["Austria"]
        assert row["display_name"] == page["KingdomOfItaly"]["display_name"]

    def test_the_dream_arm_costs_the_hot_path_nothing_it_can_feel(self, _rd9_world):
        import time
        from backend.game_logic.formations import road_notes
        w = _rd9_world
        road_notes(w)
        start = time.perf_counter()
        for _ in range(200):
            road_notes(w)
        assert (time.perf_counter() - start) / 200 < 0.002      # ~60 us measured; 2 ms is the tripwire


# ========== S14f part 2 - merged from test_s14f_p2_w18.py ==========

_W18_ROOT = Path(__file__).resolve().parents[1]
_W18_SCENARIO = (_W18_ROOT / "godot-client" / "project-sovereign" / "assets" / "maps"
                 / "europe_1805.json")
_W18_BACKEND = _W18_ROOT / "backend"
_W18_FREE = " free of its obligations"


def _w18_quiet(fn, *args, **kwargs):
    with contextlib.redirect_stdout(io.StringIO()):
        return fn(*args, **kwargs)


def _w18_owe(w, per_turn: int = 100, turns: int = 3, payer: str = "France",
             to: str = "Austria") -> int:
    """A ratified recurring settlement payment the payer still owes: the lever
    chest (`bond.bid_funds`) is the treasury less `per_turn * turns`."""
    w.recurring_settlement_payments.append({
        "payment_id": f"recurring_gold:{payer}:{to}:0:{len(w.recurring_settlement_payments)}",
        "from": payer, "to": to,
        "amount_per_turn": int(per_turn), "turns_remaining": int(turns),
        "total_turns": int(turns), "war_id": "", "war_label": "the settlement",
        "ratified_turn": 0,
    })
    return int(per_turn) * int(turns)


@pytest.fixture(scope="module")
def _w18_boot():
    from backend.models.world_state import WorldState
    with contextlib.redirect_stdout(io.StringIO()):
        return WorldState.from_scenario(str(_W18_SCENARIO))


def _w18_world(boot, raw: int, owed: int = 0, dp: int = 5):
    """The shipped 1805 board: France holds `raw` gold and `dp` DP, `owed` of
    the gold promised to a recurring settlement payment (100 a turn)."""
    from backend.models.world_state import WorldState
    w = WorldState.from_dict(json.loads(json.dumps(boot.to_dict(), default=str)))
    w.nation_gold["France"] = raw
    w.diplomatic_points = dp
    if owed:
        assert owed % 100 == 0
        _w18_owe(w, 100, owed // 100)
    return w


@contextlib.contextmanager
def _w18_client(w):
    """The player's road: /command on a swapped world (three globals, restored)."""
    import backend.main as M
    from backend.commands.parser import CommandParser
    from fastapi.testclient import TestClient
    saved = (M.game_state["world"], M.world, M.parser)
    M.game_state["world"] = w
    M.world = w
    M.parser = CommandParser(use_real_llm=False)
    try:
        yield TestClient(M.app)
    finally:
        M.game_state["world"], M.world, M.parser = saved


def _w18_say(client, text: str) -> dict:
    with contextlib.redirect_stdout(io.StringIO()):
        return client.post("/command", json={"command": text}).json()


def _w18_after(message: str) -> int:
    m = re.search(r"would hold ([\d,]+) after", message)
    assert m, message
    return int(m.group(1).replace(",", ""))


def _w18_is_quote(reply: dict) -> bool:
    return (reply.get("state") == "awaiting_clarification"
            and bool(reply.get("instrument_confirm")))


def _w18_book(w) -> tuple:
    """Everything a quote must leave alone: the coffers, the points, the courts'
    chests, the cooldowns, the vassal rows, the auction bids."""
    return (json.dumps(dict(w.nation_gold), sort_keys=True),
            int(w.diplomatic_points),
            json.dumps(w.vassals, sort_keys=True, default=str),
            json.dumps(getattr(w, "vassal_investment_cooldowns", {}), sort_keys=True),
            json.dumps(getattr(w, "vassal_release_cooldowns", {}), sort_keys=True),
            json.dumps(w.allegiance_auctions, sort_keys=True, default=str),
            json.dumps(getattr(w, "reparations_cooldown", {}), sort_keys=True, default=str),
            json.dumps(getattr(w, "betrayal_history", {}), sort_keys=True, default=str))


def _w18_src(*parts: str) -> str:
    return _W18_BACKEND.joinpath(*parts).read_text(encoding="utf-8")


def _w18_function_names_reading(src: str, needle: str) -> set:
    """The top-level `def` names whose BODY mentions `needle`."""
    names, current, bodies = [], None, {}
    for line in src.splitlines():
        m = re.match(r"(?:async )?def (\w+)\(", line)
        if m:
            current = m.group(1)
            bodies[current] = []
        elif current is not None:
            bodies[current].append(line)
    for name, lines in bodies.items():
        if needle in "\n".join(lines):
            names.append(name)
    return set(names)


# ══════════════════════════════════════════════════════════════════════════
# S14E-X185 - the allegiance bid quotes and refuses on the raw coffers
# ══════════════════════════════════════════════════════════════════════════

def _w18_open_auction(w, nation: str = "Denmark", turns: int = 3) -> None:
    w.allegiance_auctions[nation] = {"opened_turn": int(w.current_turn),
                                     "resolves_turn": int(w.current_turn) + turns}


class TestS14EX185:
    """Reproduced (before the fix, on the shipped 1805 board with Denmark's
    allegiance in play, France holding 1,000 gold and 300 of it owed to a
    recurring settlement payment - a 700 chest): `allegiance_bid_refusal(w,
    "France", "Denmark", 1000)` was "" (the raw coffers hold 1,000),
    `allegiance_bid_quote` read "The treasury holds 1,000 gold and would hold
    0 after" and `place_allegiance_bid` laid the 1,000 - the lever text, the
    sweetener, the buy-off and the Make Amends row all call the same purse
    700. The Cabinet's bid row offered the 1,000 sum too."""

    def test_the_refusal_names_the_chest_the_quote_prints(self, _w18_boot):
        from backend.game_logic import ai_diplomacy as AD
        w = _w18_world(_w18_boot, raw=1000, owed=300)
        _w18_open_auction(w)
        assert AD.allegiance_bid_refusal(w, "France", "Denmark", 1000) == (
            "The chest holds 700 gold free of its obligations, Sire — "
            "not the 1000 the bid names.")

    def test_the_boundary_is_the_chest_itself(self, _w18_boot):
        from backend.game_logic import ai_diplomacy as AD
        w = _w18_world(_w18_boot, raw=1000, owed=300)
        _w18_open_auction(w)
        assert AD.allegiance_bid_refusal(w, "France", "Denmark", 700) == ""
        assert AD.allegiance_bid_refusal(w, "France", "Denmark", 701) == (
            "The chest holds 700 gold free of its obligations, Sire — "
            "not the 701 the bid names.")

    def test_place_cannot_lay_what_the_gate_refuses(self, _w18_boot):
        from backend.game_logic import ai_diplomacy as AD
        w = _w18_world(_w18_boot, raw=1000, owed=300)
        _w18_open_auction(w)
        before = _w18_book(w)
        result = _w18_quiet(AD.place_allegiance_bid, w, "France", "Denmark", 1000)
        assert result["success"] is False
        assert result["message"] == AD.allegiance_bid_refusal(w, "France", "Denmark", 1000)
        assert _w18_book(w) == before

    def test_the_quote_reads_the_chest_and_the_bid_leaves_it(self, _w18_boot):
        """Shown == applied: the quote's "would hold N after" is the chest
        (`bond.bid_funds`) once the bid has been laid."""
        from backend.game_logic import bond as B
        w = _w18_world(_w18_boot, raw=5000, owed=300)
        _w18_open_auction(w)
        with _w18_client(w) as client:
            quote = _w18_say(client, "Talleyrand, bid for Denmark, 200 gold")
            assert _w18_is_quote(quote), quote.get("message")
            text = quote["message"]
            assert ("the treasury holds 4,700 gold free of its obligations and "
                    "would hold 4,500 after") in text, text
            promised = _w18_after(text)
            done = _w18_say(client, quote["options"][0]["command"])
        assert done["success"] is True, done["message"]
        assert B.bid_funds(w, "France") == promised == 4500
        assert int(w.nation_gold["France"]) == 4800
        assert w.allegiance_auctions["Denmark"]["bids"] == {"France": 200}

    def test_the_typed_bid_a_chest_cannot_fund_is_refused_free(self, _w18_boot):
        w = _w18_world(_w18_boot, raw=1000, owed=300)       # chest 700 < 800 <= 1000 raw
        _w18_open_auction(w)
        before = _w18_book(w)
        with _w18_client(w) as client:
            reply = _w18_say(client, "bid for Denmark, 800 gold")
        assert reply["success"] is False and not reply.get("options"), reply["message"]
        assert ("The chest holds 700 gold free of its obligations, Sire — "
                "not the 800 the bid names.") in reply["message"], reply["message"]
        assert _w18_book(w) == before

    def test_the_cabinet_row_offers_only_the_sums_the_chest_pays(self, _w18_boot):
        from backend.game_logic.diplomacy import _bid_actions
        w = _w18_world(_w18_boot, raw=1000, owed=300)
        _w18_open_auction(w)
        (row,) = _bid_actions(w, "France", "Denmark")
        assert [c["payload"]["amount"] for c in row["choices"]] == [100, 250, 500]
        assert row["available"] is True
        w = _w18_world(_w18_boot, raw=1000, owed=1000)       # an empty chest
        _w18_open_auction(w)
        (row,) = _bid_actions(w, "France", "Denmark")
        assert row["choices"] == [] and row["available"] is False
        assert row["disabled_reason"] == (
            "The chest holds 0 gold free of its obligations, Sire — not the 100 the bid names.")

    def test_nothing_owed_is_byte_identical(self, _w18_boot):
        from backend.game_logic import ai_diplomacy as AD
        w = _w18_world(_w18_boot, raw=50)
        _w18_open_auction(w)
        assert AD.allegiance_bid_refusal(w, "France", "Denmark", 100) == (
            "The chest holds 50 gold, Sire — not the 100 the bid names.")
        w = _w18_world(_w18_boot, raw=2500)
        _w18_open_auction(w)
        assert AD.allegiance_bid_refusal(w, "France", "Denmark", 1000) == ""
        text = AD.allegiance_bid_quote(w, "France", "Denmark", 200)
        assert ("the treasury holds 2,500 gold and would hold 2,300 after, and the "
                "court keeps the gold whoever wins. Lay it? (yes / no)") in text
        assert "obligations" not in text

    def test_an_ai_suitor_reads_the_raw_coffers(self, _w18_boot):
        """Golden Rule 5: an AI court's bid (the shared road) is gated as ever
        - its recurring bill does not shrink its purse."""
        from backend.game_logic import ai_diplomacy as AD
        w = _w18_world(_w18_boot, raw=1000)
        _w18_open_auction(w)
        w.nation_gold["Sweden"] = 1000
        _w18_owe(w, 100, 3, payer="Sweden", to="Austria")
        assert AD.allegiance_bid_refusal(w, "Sweden", "Denmark", 1000) == ""
        bid = _w18_quiet(AD.place_allegiance_bid, w, "Sweden", "Denmark", 1000)
        assert bid["success"] is True, bid["message"]
        assert int(w.nation_gold["Sweden"]) == 0

    def test_only_the_players_bid_functions_read_the_chest(self):
        """The AI's producers do not reach `chest_of` (Rule 5)."""
        for rel in (("game_logic", "war_council.py"), ("ai", "enemy_ai.py")):
            assert "chest_of" not in _w18_src(*rel), rel
        assert _w18_function_names_reading(
            _w18_src("game_logic", "ai_diplomacy.py"), "chest_of(") == {
                "allegiance_bid_refusal", "allegiance_bid_quote"}


# ══════════════════════════════════════════════════════════════════════════
# S14E-X186 - Make Amends reads the raw coffers (both variants and the row)
# ══════════════════════════════════════════════════════════════════════════

def _w18_amends_world(boot, raw: int, owed: int = 0, dp: int = 4):
    """A strike AND a grievance flag on Prussia's record against us."""
    from backend.game_logic.diplomacy import _betrayal_key
    w = _w18_world(boot, raw=raw, owed=owed, dp=dp)
    w.betrayal_history[_betrayal_key("France", "Prussia")] = {
        "strikes": [{"severity": "medium", "turn": 0, "episode_id": "ep_s",
                     "decays_on_turn": 10}],
        "grievance_flags": [{"turn": 0, "episode_id": "ep_g",
                             "grievance_type": "defensive_call_refused"}],
        "categories": ["treaty_breach", "grievance"], "last_turn": 0}
    return w


class TestS14EX186:
    """Reproduced (before the fix, on the shipped board with a strike and a
    grievance on Prussia's record, France holding 400 gold and 300 of it owed -
    a 100 chest): "make amends with Prussia" quoted "The treasury holds 400
    gold and would hold 200 after" and spent the 200; the Cabinet's Make
    Amends row was open on the raw 400; the grievance variant (400g) was open
    on a 1,000 purse with 700 owed (a 300 chest). The sweetener, the buy-off,
    the lever and the bid all call that purse 100 / 300."""

    _SHORT_STANDARD = ("Insufficient treasury, Sire. Reparations to Prussia require 200 gold, "
                       "but we have only 100 gold free of its obligations.")

    def test_the_standard_variant_refuses_on_the_chest(self, _w18_boot):
        w = _w18_amends_world(_w18_boot, raw=400, owed=300)
        before = _w18_book(w)
        with _w18_client(w) as client:
            reply = _w18_say(client, "make amends with Prussia")
        assert reply["success"] is False and not reply.get("options"), reply["message"]
        assert reply["message"] == self._SHORT_STANDARD
        assert _w18_book(w) == before

    def test_the_grievance_variant_refuses_on_the_chest(self, _w18_boot):
        w = _w18_amends_world(_w18_boot, raw=1000, owed=700)       # a 300 chest < 400
        before = _w18_book(w)
        with _w18_client(w) as client:
            reply = _w18_say(client, "make amends with Prussia for the abandoned alliance")
        assert reply["success"] is False and not reply.get("options"), reply["message"]
        assert reply["message"] == (
            "Insufficient treasury, Sire. Reparations to Prussia require 400 gold, "
            "but we have only 300 gold free of its obligations.")
        assert _w18_book(w) == before

    def test_the_standard_quote_reads_the_chest_and_the_confirm_leaves_it(self, _w18_boot):
        from backend.game_logic import bond as B
        w = _w18_amends_world(_w18_boot, raw=1000, owed=300)
        with _w18_client(w) as client:
            quote = _w18_say(client, "make amends with Prussia")
            assert _w18_is_quote(quote), quote.get("message")
            text = quote["message"]
            assert ("The treasury holds 700 gold free of its obligations and would hold "
                    "500 after.") in text, text
            promised = _w18_after(text)
            done = _w18_say(client, quote["options"][0]["command"])
        assert done["success"] is True, done["message"]
        assert B.bid_funds(w, "France") == promised == 500
        assert int(w.nation_gold["France"]) == 800

    def test_the_grievance_quote_reads_the_chest_and_the_confirm_leaves_it(self, _w18_boot):
        from backend.game_logic import bond as B
        w = _w18_amends_world(_w18_boot, raw=1000, owed=300)
        with _w18_client(w) as client:
            quote = _w18_say(client, "make amends with Prussia for the abandoned alliance")
            assert _w18_is_quote(quote), quote.get("message")
            text = quote["message"]
            assert ("The treasury holds 700 gold free of its obligations and would hold "
                    "300 after.") in text, text
            promised = _w18_after(text)
            done = _w18_say(client, quote["options"][0]["command"])
        assert done["success"] is True, done["message"]
        assert B.bid_funds(w, "France") == promised == 300
        assert int(w.nation_gold["France"]) == 600

    def test_the_cabinet_row_is_the_executors_own_gate(self, _w18_boot):
        """The row's reason is the sentence the click prints; funded, both open."""
        from backend.game_logic.cabinet_rows import AMENDS_GRIEVANCE, AMENDS_STANDARD, amends_actions
        w = _w18_amends_world(_w18_boot, raw=400, owed=300)
        rows = {r["action"]: r for r in amends_actions(w, "France", "Prussia")}
        assert rows[AMENDS_STANDARD]["available"] is False
        assert rows[AMENDS_STANDARD]["disabled_reason"] == self._SHORT_STANDARD
        assert rows[AMENDS_STANDARD]["disabled_reason_display"] == self._SHORT_STANDARD
        assert rows[AMENDS_GRIEVANCE]["available"] is False
        with _w18_client(w) as client:
            clicked = _w18_say(client, "make amends with Prussia")
        assert clicked["message"] == rows[AMENDS_STANDARD]["disabled_reason"]
        w = _w18_amends_world(_w18_boot, raw=1000, owed=300)       # chest 700
        rows = {r["action"]: r for r in amends_actions(w, "France", "Prussia")}
        assert rows[AMENDS_STANDARD]["available"] is True
        assert rows[AMENDS_GRIEVANCE]["available"] is True

    def test_the_grievance_row_is_shut_where_only_the_standard_is_funded(self, _w18_boot):
        from backend.game_logic.cabinet_rows import AMENDS_GRIEVANCE, AMENDS_STANDARD, amends_actions
        w = _w18_amends_world(_w18_boot, raw=1000, owed=700)       # chest 300: 200 yes, 400 no
        rows = {r["action"]: r for r in amends_actions(w, "France", "Prussia")}
        assert rows[AMENDS_STANDARD]["available"] is True
        assert rows[AMENDS_GRIEVANCE]["available"] is False
        assert rows[AMENDS_GRIEVANCE]["disabled_reason"].endswith(
            "but we have only 300 gold free of its obligations.")

    def test_nothing_owed_is_byte_identical(self, _w18_boot):
        from backend.game_logic.cabinet_rows import AMENDS_STANDARD, amends_actions
        w = _w18_amends_world(_w18_boot, raw=150)
        row = next(r for r in amends_actions(w, "France", "Prussia")
                   if r["action"] == AMENDS_STANDARD)
        assert row["disabled_reason"] == (
            "Insufficient treasury, Sire. Reparations to Prussia require 200 gold, "
            "but we have only 150.")
        w = _w18_amends_world(_w18_boot, raw=1000)
        with _w18_client(w) as client:
            text = _w18_say(client, "make amends with Prussia")["message"]
        assert "The treasury holds 1,000 gold and would hold 800 after." in text
        assert "obligations" not in text

    def test_the_gate_is_the_one_helper(self):
        """Both variants and the row read `cabinet_rows.amends_gold_refusal`,
        and no `insufficient_gold` sentence is composed beside it."""
        rows_src = _w18_src("game_logic", "cabinet_rows.py")
        exe_src = _w18_src("commands", "diplomatic_executor.py")
        assert rows_src.count('AMENDS_REFUSAL_DISPLAY["insufficient_gold"]') == 1
        assert 'AMENDS_REFUSAL_DISPLAY["insufficient_gold"]' not in exe_src
        assert exe_src.count("amends_gold_refusal(") == 2


