# S14E-X187 - the vassal investment's gate and quote read the raw coffers
# ══════════════════════════════════════════════════════════════════════════

def _w18_invest_world(boot, raw: int, owed: int = 0, dp: int = 5):
    """The shipped board, Holland's loyalty 70 (the boot's 100 buys nothing)."""
    w = _w18_world(boot, raw=raw, owed=owed, dp=dp)
    w.vassals["Holland"]["loyalty"] = 70
    w.vassal_investment_cooldowns = {}
    return w


class TestS14EX187:
    """Reproduced (before the fix, on the shipped board, Holland at loyalty 70,
    France holding 300 gold and 200 of it owed - a 100 chest): "invest in
    Holland" quoted "The treasury holds 300 gold and would hold 100 after" and
    charged the 200; `get_available_diplomatic_actions` left the Invest chip
    open. The sweetener, the buy-off, the bid and Make Amends all call that
    purse 100."""

    def test_the_quote_reads_the_chest_and_the_confirm_leaves_it(self, _w18_boot):
        from backend.game_logic import bond as B
        w = _w18_invest_world(_w18_boot, raw=1000, owed=300)
        with _w18_client(w) as client:
            quote = _w18_say(client, "invest in Holland")
            assert _w18_is_quote(quote), quote.get("message")
            text = quote["message"]
            assert ("The treasury holds 700 gold free of its obligations and would hold "
                    "500 after. Invest? (yes / no)") in text, text
            promised = _w18_after(text)
            done = _w18_say(client, quote["options"][0]["command"])
        assert done["success"] is True, done["message"]
        assert B.bid_funds(w, "France") == promised == 500
        assert int(w.nation_gold["France"]) == 800
        assert w.vassals["Holland"]["loyalty"] == 80

    def test_a_chest_below_the_price_is_refused_before_the_quote(self, _w18_boot):
        w = _w18_invest_world(_w18_boot, raw=300, owed=200)       # chest 100 < 200 <= 300 raw
        before = _w18_book(w)
        with _w18_client(w) as client:
            reply = _w18_say(client, "invest in Holland")
            confirmed = _w18_say(client, "invest in Holland confirmed")
        for r in (reply, confirmed):
            assert r["success"] is False and not r.get("options"), r["message"]
            assert r["message"] == ("Insufficient gold (100/200 required) — the treasury "
                                    "holds 100 gold free of its obligations."), r["message"]
        assert _w18_book(w) == before

    def test_the_domain_function_refuses_and_charges_nothing(self, _w18_boot):
        from backend.game_logic.vassal import invest_in_vassal
        w = _w18_invest_world(_w18_boot, raw=300, owed=200)
        before = _w18_book(w)
        for quote_only in (False, True):
            result = _w18_quiet(invest_in_vassal, w, "Holland", quote_only=quote_only)
            assert result["success"] is False
            assert result["message"].endswith("holds 100 gold free of its obligations.")
        assert _w18_book(w) == before

    def test_the_quote_plan_carries_the_chest_and_the_treasury(self, _w18_boot):
        from backend.game_logic.vassal import invest_in_vassal
        w = _w18_invest_world(_w18_boot, raw=1000, owed=300)
        quote = _w18_quiet(invest_in_vassal, w, "Holland", quote_only=True)
        assert quote["success"] is True
        assert (quote["quote"]["chest"], quote["quote"]["treasury"]) == (700, 1000)

    def test_the_chip_is_the_verbs_own_gate(self, _w18_boot):
        from backend.game_logic.diplomacy import get_available_diplomatic_actions
        w = _w18_invest_world(_w18_boot, raw=300, owed=200)
        row = next(a for a in get_available_diplomatic_actions(w, "Holland")
                   if a["action"] == "invest_vassal")
        assert row["available"] is False
        assert row["disabled_reason"] == "Insufficient Gold"
        assert row["disabled_reason_display"] == "Needs 200 gold; 100 held" + _W18_FREE
        w = _w18_invest_world(_w18_boot, raw=1000, owed=300)       # chest 700
        row = next(a for a in get_available_diplomatic_actions(w, "Holland")
                   if a["action"] == "invest_vassal")
        assert row["available"] is True

    def test_nothing_owed_is_byte_identical(self, _w18_boot):
        from backend.game_logic.diplomacy import get_available_diplomatic_actions
        w = _w18_invest_world(_w18_boot, raw=150)
        with _w18_client(w) as client:
            reply = _w18_say(client, "invest in Holland")
        assert reply["message"] == "Insufficient gold (150/200 required)."
        row = next(a for a in get_available_diplomatic_actions(w, "Holland")
                   if a["action"] == "invest_vassal")
        assert row["disabled_reason"] == "Insufficient Gold"
        assert row["disabled_reason_display"] == "Needs 200 gold; 150 held"
        w = _w18_invest_world(_w18_boot, raw=2500)
        with _w18_client(w) as client:
            text = _w18_say(client, "invest in Holland")["message"]
        assert "The treasury holds 2,500 gold and would hold 2,300 after." in text
        assert "obligations" not in text

    def test_an_ai_lord_invests_on_its_raw_coffers(self, _w18_boot):
        """Golden Rule 5: the AI lord's investment is the same verb, gated as
        ever - a recurring bill does not shrink its purse."""
        from backend.game_logic.vassal import invest_in_vassal
        w = _w18_invest_world(_w18_boot, raw=1000)
        w.vassals["Holland"]["lord"] = "Britain"
        w.nation_gold["Britain"] = 250
        w.nation_dp["Britain"] = 3
        _w18_owe(w, 100, 2, payer="Britain", to="Austria")        # a 50 "chest"
        result = _w18_quiet(invest_in_vassal, w, "Holland", actor="Britain")
        assert result["success"] is True, result["message"]
        assert int(w.nation_gold["Britain"]) == 50


