# S14E-X191 - the sweetener's Cabinet row: ONE read of the chest
# ══════════════════════════════════════════════════════════════════════════

def _w18_sitting(boot, raw: int, owed: int = 0, dp: int = 4):
    """The shipped board with the Congress sitting (the staging the Congress's
    own tests use)."""
    from tests.test_congress_of_paris import _sit
    w = _w18_world(boot, raw=raw, owed=owed, dp=dp)
    _w18_quiet(_sit, w)
    w.nation_gold["France"] = raw
    w.diplomatic_points = dp
    return w


class TestS14EX191:
    """The row kept a raw `amount <= gold` filter beside `sweetener_refusal`
    (which has gated on the chest since X157) and a raw fallback sentence
    ("The treasury holds N g - not enough for a sweetener.") that the refusal
    now always pre-empts. Reproduced by reading `cabinet_rows.py`: both stood;
    the refusal's words and the fallback's could say two figures. One chest
    read now; the funded rows are unchanged."""

    def test_the_source_has_no_raw_filter_and_no_raw_fallback(self):
        src = _w18_src("game_logic", "cabinet_rows.py")
        body = src[src.index("def recognition_actions("):src.index("def bond_actions(")]
        assert "amount <= gold" not in body
        assert "not enough for a sweetener" not in body
        assert 'get("nation_gold"' not in body and "nation_gold" not in body

    def test_a_funded_board_is_unchanged(self, _w18_boot):
        from backend.game_logic import congress
        from backend.game_logic.cabinet_rows import recognition_actions
        w = _w18_sitting(_w18_boot, raw=5000)
        (row,) = recognition_actions(w, "France", "Prussia")
        assert [c["payload"]["amount"] for c in row["choices"]] == [500, 1000, 2000]
        assert [c["label"] for c in row["choices"]] == [
            "Offer 500 gold", "Offer 1,000 gold", "Offer 2,000 gold"]
        assert row["available"] is True and row["disabled_reason"] == ""
        assert row["display_name"] == "Offer Gold for Recognition"
        assert row["dp_cost"] == int(congress.SWEETENER_DP_COST)
        assert row["effect_text"] == (
            f"+{int(congress.SWEETENER_PER_1000)} at the table per 1,000 gold, up to "
            f"+{int(congress.SWEETENER_CAP)} — the Congress sits")

    def test_the_chest_trims_the_sums_not_the_raw_coffers(self, _w18_boot):
        from backend.game_logic.cabinet_rows import recognition_actions
        w = _w18_sitting(_w18_boot, raw=1000, owed=300)           # chest 700
        (row,) = recognition_actions(w, "France", "Prussia")
        assert [c["payload"]["amount"] for c in row["choices"]] == [500]
        assert row["available"] is True

    def test_a_short_board_says_the_refusals_words(self, _w18_boot):
        from backend.game_logic import congress
        from backend.game_logic.cabinet_rows import recognition_actions
        w = _w18_sitting(_w18_boot, raw=1000, owed=700)           # chest 300
        (row,) = recognition_actions(w, "France", "Prussia")
        assert row["choices"] == [] and row["available"] is False
        assert row["disabled_reason"] == (
            "The treasury holds 300 gold free of its obligations — "
            "the sweetener is 500, 200 short.")
        assert row["disabled_reason"] == congress.sweetener_refusal(w, "Prussia", 500)
        assert row["disabled_reason_display"] == row["disabled_reason"]
        w = _w18_sitting(_w18_boot, raw=300)                       # nothing owed
        (row,) = recognition_actions(w, "France", "Prussia")
        assert row["disabled_reason"] == "The treasury holds 300g — the sweetener asks 500g."

    def test_the_points_are_the_refusals_own_words(self, _w18_boot):
        """Funded but with no point to carry the envoy: the row is shut in the
        executor's sentence (the refusal checks the points before the gold -
        the row's own, later "Insufficient DP" line could never be reached)."""
        from backend.game_logic import congress
        from backend.game_logic.cabinet_rows import recognition_actions
        w = _w18_sitting(_w18_boot, raw=5000, dp=0)
        (row,) = recognition_actions(w, "France", "Prussia")
        assert row["available"] is False and row["choices"] == []
        assert row["disabled_reason"] == congress.sweetener_refusal(w, "Prussia", 500)
        assert "1 diplomatic point, and 0 remain" in row["disabled_reason"]
        assert "Insufficient DP" not in _w18_src("game_logic", "cabinet_rows.py").split(
            "def recognition_actions(")[1].split("def bond_actions(")[0]

    def test_a_sum_the_table_clips_is_offered_while_the_chest_pays_the_charge(self, _w18_boot):
        """The raw `amount <= gold` filter hid a clipped sum the chest pays in
        full: 500 already laid, 1,500 held - the table counts 1,500 of a
        2,000 offer, the quote says so (`Only 1,500g of the 2,000g offered
        counts`) and the charge is the 1,500 the refusal measured."""
        from backend.game_logic import congress
        from backend.game_logic.cabinet_rows import recognition_actions
        w = _w18_sitting(_w18_boot, raw=1500)
        w.congress.setdefault("sweeteners", {})["Prussia"] = 500
        assert congress.sweetener_charge(w, "Prussia", 2000) == 1500
        (row,) = recognition_actions(w, "France", "Prussia")
        assert [c["payload"]["amount"] for c in row["choices"]] == [500, 1000, 2000]
        assert "Only 1,500g of the 2,000g offered counts" in congress.sweetener_quote(
            w, "Prussia", 2000)


# ══════════════════════════════════════════════════════════════════════════
# S14E-X160 - release_vassal: a one-click irreversible act, quoted first
# ══════════════════════════════════════════════════════════════════════════

def _w18_release_world(boot, dp: int = 4, **kw):
    """The shipped board: France holds Holland (loyalty 100 at boot), `dp` DP."""
    w = _w18_world(boot, raw=kw.get("raw", 1000), owed=kw.get("owed", 0), dp=dp)
    return w


class TestS14EX160:
    """Reproduced (before the fix, on the shipped 1805 board): the Cabinet's
    "Release Vassal" chip sends "release Holland" and `_execute_release_vassal`
    called `release_vassal` at once - 1 DP, the tribute lost, the marshals
    handed back, the contingent recalled, the pair at peace, the yoke barred
    for five turns, the lord's alarm eased - on one click with no quote and no
    way back. The invest, bid, amends and buy-off verbs all quote first."""

    def test_the_bare_order_quotes_and_changes_nothing(self, _w18_boot):
        w = _w18_release_world(_w18_boot)
        before = _w18_book(w)
        with _w18_client(w) as client:
            quote = _w18_say(client, "release Holland")
        assert _w18_is_quote(quote), quote.get("message")
        assert "Holland" in w.vassals and _w18_book(w) == before
        assert [o["label"] for o in quote["options"]] == ["Release", "Not now"]
        assert quote["options"][0]["command"] == "release Holland confirmed"
        text = quote["message"]
        assert text.startswith("Release Holland from vassalage: 1 diplomatic point (4 held, 3 after).")
        assert text.endswith("Release? (yes / no)")

    def test_the_confirm_releases_exactly_as_it_always_did(self, _w18_boot):
        w = _w18_release_world(_w18_boot)
        with _w18_client(w) as client:
            quote = _w18_say(client, "release Holland")
            done = _w18_say(client, quote["options"][0]["command"])
        assert done["success"] is True, done["message"]
        assert "Holland" not in w.vassals
        assert int(w.diplomatic_points) == 3
        assert done["message"].startswith(
            "Holland is released from vassalage and stands a free court again.")
        assert w.vassal_release_cooldowns["Holland"] == 5

    def test_not_now_spends_nothing(self, _w18_boot):
        w = _w18_release_world(_w18_boot)
        with _w18_client(w) as client:
            quote = _w18_say(client, "release Holland")
            before = _w18_book(w)
            _w18_say(client, quote["options"][1]["command"])
        assert _w18_book(w) == before and "Holland" in w.vassals

    def test_every_refusal_comes_before_the_quote(self, _w18_boot):
        w = _w18_release_world(_w18_boot, dp=0)
        before = _w18_book(w)
        with _w18_client(w) as client:
            poor = _w18_say(client, "release Holland")
            gone = _w18_say(client, "release Austria")
        assert poor["success"] is False and not poor.get("options")
        assert poor["message"] == ("Insufficient Diplomatic Points. Releasing a vassal "
                                   "costs 1 DP.")
        assert gone["success"] is False and not gone.get("options")
        assert gone["message"] == "Austria is not a vassal."
        assert _w18_book(w) == before

    def test_the_plan_is_pure(self, _w18_boot):
        from backend.game_logic.vassal import release_plan
        w = _w18_release_world(_w18_boot)
        before = json.dumps(w.to_dict(), sort_keys=True, default=str)
        plan = release_plan(w, "Holland")
        assert plan["court"] == "Holland" and plan["lord"] == "France"
        assert json.dumps(w.to_dict(), sort_keys=True, default=str) == before
        assert release_plan(w, "Austria") is None

    def test_shown_is_applied_on_a_full_board(self, _w18_boot):
        """Tribute, an assimilated marshal, the Continental System, the alarm:
        each figure the quote prints is the one the release report prints."""
        from backend.game_logic.vassal import _release_tribute_snapshot
        w = _w18_release_world(_w18_boot)
        w.marshals["Murat"].original_nation = "Holland"            # an assimilated corps
        w.continental_system_members = ["Holland"]
        w.threat_by_target["France"] = 30
        tribute = _release_tribute_snapshot(w, "Holland", w.vassals["Holland"])
        assert tribute > 0
        with _w18_client(w) as client:
            quote = _w18_say(client, "release Holland")
            text = quote["message"]
            assert f"Their tribute of {tribute:,} gold a turn ends." in text
            assert "Their marshals return to their own colours: Murat." in text
            assert "They are no longer bound to the Continental System." in text
            assert "They will no longer answer France's call to arms." in text
            assert "Europe's alarm at France eases (30 → 22)." in text
            assert "They cannot be brought back under the yoke for 5 turns." in text
            done = _w18_say(client, quote["options"][0]["command"])
        report = done["message"]
        assert done["success"] is True, report
        for clause in (f"Their tribute of {tribute} gold a turn ends.",
                       "Their marshals return to their own colours: Murat.",
                       "They are no longer bound to the Continental System.",
                       "They will no longer answer France's call to arms.",
                       "Europe's alarm at France eases (30 → 22).",
                       "They cannot be brought back under the yoke for 5 turns."):
            assert clause in report, (clause, report)
        assert w.marshals["Murat"].nation == "Holland"

    def test_the_alarm_clause_is_silent_where_nothing_eases(self, _w18_boot):
        w = _w18_release_world(_w18_boot)
        w.threat_by_target["France"] = 0
        with _w18_client(w) as client:
            quote = _w18_say(client, "release Holland")
            done = _w18_say(client, quote["options"][0]["command"])
        assert "alarm" not in quote["message"] and "alarm" not in done["message"]

    def test_the_plan_matches_the_release_on_every_shipped_vassal(self, _w18_boot):
        """Drift pin: `release_plan` against `release_vassal`'s own snapshot -
        the tribute, the marshals, the alarm - for each vassal on the board."""
        from backend.game_logic.vassal import release_plan, release_vassal
        for court in ("Holland", "KingdomOfItaly", "Switzerland"):
            w = _w18_release_world(_w18_boot)
            w.threat_by_target["France"] = 41
            plan = release_plan(w, court)
            result = _w18_quiet(release_vassal, w, court)
            assert result["success"] is True
            msg = result["message"]
            if plan["lost_tribute"] > 0:
                assert f"Their tribute of {plan['lost_tribute']} gold a turn ends." in msg
            assert f"({plan['threat_before']} → {plan['threat_after']})." in msg
            assert (plan["threat_before"], plan["threat_after"]) == (41, 33)
            assert w.threat_by_target["France"] == plan["threat_after"]

    def test_a_recalled_contingent_is_quoted_and_is_not_a_handed_back_marshal(self, _w18_boot):
        """The contingent's commander flies France's flag with `original_nation`
        set to the satellite; the release stands him down (he leaves the board)
        BEFORE the hand-back loop - so the quote lists him as recalled, not as a
        marshal returning to his own colours."""
        from backend.game_logic import contingent as C
        from backend.game_logic.vassal import release_plan
        w = _w18_release_world(_w18_boot)
        _w18_quiet(C.process_vassal_contingents, w)
        record = w.vassal_contingents["Holland"]
        commander = record["marshal"]
        men = int(w.marshals[commander].strength)
        plan = release_plan(w, "Holland")
        assert plan["contingent"] == {"marshal": commander, "men": men}
        assert commander not in plan["marshals"]
        with _w18_client(w) as client:
            quote = _w18_say(client, "release Holland")
            text = quote["message"]
            assert (f"Their contingent under {commander} ({men:,} men) is recalled "
                    f"and leaves our lines.") in text
            assert "return to their own colours" not in text
            done = _w18_say(client, quote["options"][0]["command"])
        assert done["success"] is True
        assert commander not in w.marshals and "Holland" not in w.vassal_contingents
        assert "return to their own colours" not in done["message"]

    def test_a_captured_commander_is_handed_back_not_recalled(self, _w18_boot):
        """`stand_down_marshal` refuses a captured man: he stays on the board
        and the hand-back loop returns him - the plan reads the same guard."""
        from backend.game_logic import contingent as C
        from backend.game_logic.vassal import release_plan, release_vassal
        w = _w18_release_world(_w18_boot)
        _w18_quiet(C.process_vassal_contingents, w)
        commander = w.vassal_contingents["Holland"]["marshal"]
        w.marshals[commander].captured_by = "Austria"
        plan = release_plan(w, "Holland")
        assert plan["contingent"] is None and plan["marshals"] == [commander]
        result = _w18_quiet(release_vassal, w, "Holland")
        assert f"Their marshals return to their own colours: {commander}." in result["message"]

    def test_the_programmatic_release_is_untouched(self, _w18_boot):
        """The AI's / the settlement's releases call `release_vassal` directly:
        no quote, no DP, the same report as ever."""
        from backend.game_logic.vassal import release_vassal
        w = _w18_release_world(_w18_boot)
        dp = int(w.diplomatic_points)
        result = _w18_quiet(release_vassal, w, "Holland")
        assert result["success"] is True and int(w.diplomatic_points) == dp
        assert "Holland" not in w.vassals
        assert result["message"].startswith(
            "Holland is released from vassalage and stands a free court again.")

    def test_an_acting_nation_marker_skips_the_quote(self, _w18_boot):
        """The executor keeps the invest verb's rule: an order carrying
        `_acting_nation` never sees the player's quote (Golden Rule 5)."""
        from backend.commands.executor import CommandExecutor
        w = _w18_release_world(_w18_boot)
        executor = CommandExecutor()
        result = _w18_quiet(executor._vassal._execute_release_vassal,
                            {"target": "Holland", "_acting_nation": "France"},
                            {"world": w})
        assert result["success"] is True and "Holland" not in w.vassals
        assert not result.get("instrument_confirm")

    def test_the_treaty_fuzzers_release_walks_the_confirmed_order(self, _w18_boot):
        """Sweep find: `tools/treaty_fuzzer.py` `verb_release_vassal` drives the
        executor with a bare order, which now quotes and releases nothing - the
        fuzzer sends the confirmed order so the release path stays exercised."""
        src = (_W18_ROOT / "tools" / "treaty_fuzzer.py").read_text(encoding="utf-8")
        body = src.split("def verb_release_vassal(")[1].split("\n    def ")[0]
        assert '"confirmed": True' in body and 'f"release {court} confirmed"' in body
        from backend.commands.executor import CommandExecutor
        from backend.commands.reforms_executor import _confirmed
        assert _confirmed({"action": "release_vassal", "target": "Holland", "confirmed": True})
        w = _w18_release_world(_w18_boot)
        executor = CommandExecutor()
        result = _w18_quiet(executor._vassal._execute_release_vassal,
                            {"target": "Holland", "confirmed": True}, {"world": w})
        assert result["success"] is True and "Holland" not in w.vassals

    def test_the_confirmed_word_on_the_target_is_stripped(self, _w18_boot):
        """The typed `release Holland confirmed` (the quote's own option) names
        the court, not a court called 'holland confirmed'."""
        w = _w18_release_world(_w18_boot)
        with _w18_client(w) as client:
            done = _w18_say(client, "release Holland confirmed")
        assert done["success"] is True, done["message"]
        assert "Holland" not in w.vassals

    def test_a_formed_court_is_quoted_by_its_display_name(self, _w18_boot):
        """R4-5: the confirmed line is the court's key; the words carry its
        display name and its article."""
        w = _w18_release_world(_w18_boot)
        with _w18_client(w) as client:
            quote = _w18_say(client, "release the kingdom of italy")
            assert _w18_is_quote(quote), quote.get("message")
            assert quote["message"].startswith(
                "Release the Kingdom of Italy from vassalage: 1 diplomatic point")
            assert "KingdomOfItaly" not in quote["message"]
            done = _w18_say(client, quote["options"][0]["command"])
        assert done["success"] is True, done["message"]
        assert "KingdomOfItaly" not in w.vassals


# ========== S14f part 2 - the re-play's P2 (the orchestrator's pin) ==========

class TestS14EX197:
    """S14E-X197 (the re-play's P2): D10's camp wash painted every province
    OUTSIDE the camp opaque black. `_refresh_camp_fill` resized a
    `PackedColorArray` and set only the camp provinces; a resized array is
    opaque black by default and the fill shader paints every province its
    slot's colour (the reach layer never met this because it sets every
    slot). Reproduced on the instrument (frames 0157 ... 0163 of
    `docs/audits/dd_b/replay_2026_10_25/`). The fix clears every slot first,
    in a Utils-free colour the D10 source pin allows."""

    def test_the_camp_fill_clears_every_slot_before_the_camp_is_set(self):
        src = (Path(__file__).resolve().parents[1] / "godot-client" / "project-sovereign" / "scenes"
               / "map_renderer_base.gd").read_text(encoding="utf-8")
        fill = src[src.index("func _refresh_camp_fill("):src.index("func _create_reach_fill_layer(")]
        resize = fill.index("washes.resize(OWNER_FILL_MAX_PROVINCES)")
        clear = fill.index("washes.fill(Color.TRANSPARENT)")
        loop = fill.index("for i in range(_owner_fill_province_order.size()):")
        assert resize < clear < loop, "the clear must follow the resize and precede the camp provinces"
        assert "S14E-X197" in fill


