_W19_ROOT = Path(__file__).resolve().parents[1]
_W19_SCENARIO = (_W19_ROOT / "godot-client" / "project-sovereign" / "assets"
                 / "maps" / "europe_1805.json")
_W19_SCRIPTS = _W19_ROOT / "godot-client" / "project-sovereign" / "scripts"


def _w19_quiet():
    return contextlib.redirect_stdout(io.StringIO())


def _w19_src(name: str) -> str:
    return (_W19_SCRIPTS / name).read_text(encoding="utf-8")


def _w19_func(src: str, header: str) -> str:
    """One GDScript function's text: from its header to the next top-level func."""
    start = src.index(header)
    rest = src[start + len(header):]
    ends = [i for i in (rest.find("\nfunc "), rest.find("\nstatic func ")) if i >= 0]
    return src[start: start + len(header) + (min(ends) if ends else len(rest))]


@pytest.fixture(scope="module")
def _w19_boot():
    from backend.models.world_state import WorldState
    with _w19_quiet():
        return WorldState.from_scenario(str(_W19_SCENARIO))


@pytest.fixture
def _w19_world(_w19_boot):
    """The shipped 1805 board (a copy), France with a chest that carries the
    instruments and DP to spend."""
    from backend.models.world_state import WorldState
    w = WorldState.from_dict(json.loads(json.dumps(_w19_boot.to_dict(), default=str)))
    w.nation_gold["France"] = 2500
    w.diplomatic_points = 5
    return w


@contextlib.contextmanager
def _w19_client(w):
    """The player's road: /command on a swapped world (three globals, restored)."""
    import backend.main as M
    from backend.commands.parser import CommandParser
    from fastapi.testclient import TestClient
    saved = (M.game_state["world"], M.world, M.parser)
    M.game_state["world"] = w
    M.world = w
    M.parser = CommandParser(use_real_llm=False)
    try:
        yield TestClient(M.app)
    finally:
        M.game_state["world"], M.world, M.parser = saved


def _w19_say(client, text: str) -> dict:
    with _w19_quiet():
        return client.post("/command", json={"command": text}).json()


def _w19_fight(w, **points):
    """Give nations battle contribution in the war (the material the ally
    reactions read): `_w19_fight(w, France=200, Bavaria=200)`."""
    from backend.game_logic.war_contribution import open_episode
    for nation, pts in points.items():
        episode = open_episode(w, "war_1", nation, joined_turn=0, war_sequence=1)
        episode["battle"] = pts
        episode["total"] = pts


