# S14E-X198 — the separate-peace sentence, once
# ══════════════════════════════════════════════════════════════════════════

_W19_BAVARIA_ENDS = "Bavaria's war with Austria ends in this instrument"
_W19_BAVARIA_LEFT_OUT = (
    "Bavaria's war with Austria ends in this instrument; she takes nothing by it "
    "and is left out: -18 relation and a grievance; Make Amends (400g + 2 DP) clears it.")


def _w19_printed(dialogue: dict) -> list:
    """Every line the confirm popup prints under Political Consequences: the
    dialogue's `warnings`, then the snapshot's tier warnings, fallout and
    commitment conflicts (`proposal_confirm_popup.gd`'s four loops)."""
    snap = dialogue.get("war_context_snapshot") or {}
    lines = []
    for w in dialogue.get("warnings") or []:
        lines.append(str(w.get("text", w)) if isinstance(w, dict) else str(w))
    for w in snap.get("tier_mismatch_warnings") or []:
        lines.append(str(w.get("display", w.get("text", w))) if isinstance(w, dict) else str(w))
    for w in snap.get("fallout_warnings") or []:
        lines.append(str(w.get("display", w)) if isinstance(w, dict) else str(w))
    for c in snap.get("commitment_conflicts") or []:
        lines.append(str(c.get("display", c)) if isinstance(c, dict) else str(c))
    return lines


def _w19_open_peace(w, court: str) -> dict:
    from backend.game_logic.diplomatic_dialogue import generate_dialogue
    with _w19_quiet():
        return generate_dialogue(
            "proposal_confirm", {"target_nation": court, "proposal_type": "peace"}, w)


class TestS14EX198:
    """The peace preview's Political Consequences printed the separate-peace
    price sentence TWICE, back to back: once as Talleyrand's note ("Mark one
    thing, Sire: Spain's war with Britain ends in this instrument; …", the
    dialogue's `warnings`, severity medium) and once as the snapshot's
    `carried_in` conflict row (the same `separate_peace_words`, severity
    WARNING) — frames 0213 (Britain, Spain), 0027 (Austria, Bavaria), 0168 and
    0267 of the replay.

    Reproduced on the shipped 1805 board: `generate_dialogue("proposal_confirm",
    {Austria, peace})` carried "Mark one thing, Sire: Bavaria's war with Austria
    ends in this instrument; she takes nothing by it." in `warnings` AND
    "Bavaria's war with Austria ends in this instrument; she takes nothing by
    it." in `commitment_conflicts[0].display` (two lines printed); the Britain
    draft the same for Spain.

    The fix: the snapshot's rows are the ONE line (they carry the severity and
    the draft's own clauses); the note stays on the dialogue as
    `separate_peace_note` for the counsel and rides `warnings` only where the
    rows do not already print the sentence
    (`diplomatic_dialogue.separate_peace_said_by_the_rows`). Both popups also
    skip a consequence line already printed.
    """

    def test_a_the_boot_austria_peace_says_bavarias_war_once(self, _w19_world):
        dialogue = _w19_open_peace(_w19_world, "Austria")
        lines = _w19_printed(dialogue)
        assert [ln for ln in lines if _W19_BAVARIA_ENDS in ln] == [
            "Bavaria's war with Austria ends in this instrument; she takes nothing by it."], lines
        assert len(lines) == len(set(lines)), lines

    def test_b_the_priced_shut_out_sentence_is_printed_once_and_is_the_row(self, _w19_world):
        w = _w19_world
        _w19_fight(w, France=200, Bavaria=200)
        dialogue = _w19_open_peace(w, "Austria")
        lines = _w19_printed(dialogue)
        assert [ln for ln in lines if "-18 relation and a grievance" in ln] == [
            _W19_BAVARIA_LEFT_OUT], lines
        row = next(c for c in dialogue["war_context_snapshot"]["commitment_conflicts"]
                   if c["conflict_type"] == "carried_in")
        assert row["severity"] == "WARNING" and row["display"] == _W19_BAVARIA_LEFT_OUT
        assert row["detail"]["relation_change"] == -18 and row["detail"]["grievance"] is True
        assert len(lines) == len(set(lines)), lines

    def test_c_the_note_stays_on_the_dialogue_for_the_counsel(self, _w19_world):
        w = _w19_world
        _w19_fight(w, France=200, Bavaria=200)
        dialogue = _w19_open_peace(w, "Austria")
        assert dialogue["separate_peace_note"] == f"Mark one thing, Sire: {_W19_BAVARIA_LEFT_OUT}"
        # ...but it no longer rides the printed warnings beside the row
        assert not any("Mark one thing" in str(x.get("text", "")) for x in dialogue["warnings"]
                       if isinstance(x, dict))

    def test_d_the_spain_britain_draft_the_replays_frame_0213(self, _w19_world):
        """France at war with Britain, Spain allied and at war with her: the
        sighting's board (frame 0213)."""
        dialogue = _w19_open_peace(_w19_world, "Britain")
        lines = _w19_printed(dialogue)
        spain = [ln for ln in lines if "Spain's war with Britain ends in this instrument" in ln]
        assert len(spain) == 1, lines
        assert not spain[0].startswith("Mark one thing"), spain

    def test_e_an_ally_left_fighting_is_said_once(self):
        """The paradox row (an ally the proposer does not lead is LEFT
        FIGHTING, priced): the note used to repeat it beside the row."""
        from backend.game_logic.diplomacy import set_diplomatic_state
        from backend.game_logic.diplomatic_dialogue import _enrich_proposal_summary
        from backend.models.world_state import WorldState
        world = WorldState()
        set_diplomatic_state(world, "France", "Britain", "WAR", "test")
        set_diplomatic_state(world, "France", "Prussia", "ALLIANCE", "test")
        set_diplomatic_state(world, "Prussia", "Britain", "WAR", "test")
        with _w19_quiet():
            dialogue = _enrich_proposal_summary(
                {"options": [{"label": "Send", "action": "execute_proposal", "terms": {}}]},
                "Britain", "peace", world)
        lines = _w19_printed(dialogue)
        prussia = [ln for ln in lines if "Prussia stays at war with Britain after this separate peace" in ln]
        assert len(prussia) == 1, lines
        assert "relation with her" in prussia[0]
        assert "Prussia" in dialogue["separate_peace_note"]

    def test_f_a_draft_that_names_the_ally_reads_the_same_in_note_and_row(self, _w19_world):
        """The note read no terms (the row did): a draft ceding Tyrol to
        Bavaria printed "she takes nothing by it" in the note beside the row's
        "named for Tyrol". One reading now, from the draft's own clauses."""
        from backend.game_logic.diplomatic_dialogue import _enrich_proposal_summary
        w = _w19_world
        # S14E-X211 (S14f p3): the words price the COMPILED clauses alone — a
        # dict written into `clauses` is never applied by the ratifier and is
        # no longer read; the cession rides the demands dialect (to Bavaria).
        terms = {"type": "peace", "proposal_type": "peace", "sweeteners": [],
                 "demands": [{"type": "territory_cede", "regions": ["Tyrol"],
                              "from_nation": "Austria", "to_nation": "Bavaria"}],
                 "clauses": []}
        with _w19_quiet():
            dialogue = _enrich_proposal_summary(
                {"options": [{"label": "Send", "action": "execute_proposal", "terms": terms}]},
                "Austria", "peace", w)
        lines = _w19_printed(dialogue)
        bavaria = [ln for ln in lines if _W19_BAVARIA_ENDS in ln]
        assert len(bavaria) == 1 and "named for Tyrol" in bavaria[0], lines
        assert "named for Tyrol" in dialogue["separate_peace_note"]

    def test_g_the_rows_say_it_only_when_every_ally_row_is_the_words(self, _w19_world):
        from backend.game_logic.diplomacy import separate_peace_words
        from backend.game_logic.diplomatic_dialogue import separate_peace_said_by_the_rows
        w = _w19_world
        words = separate_peace_words(w, "France", "Austria")
        sentence = words["per_ally"]["Bavaria"]
        said = {"war_context_snapshot": {"commitment_conflicts": [
            {"conflict_type": "carried_in", "affected_entity": "Bavaria", "display": sentence}]}}
        other = {"war_context_snapshot": {"commitment_conflicts": [
            {"conflict_type": "paradox", "affected_entity": "Bavaria",
             "display": "Bavaria stays at war with Austria after this separate peace - "
                        "France joined at an ally's call."}]}}
        none = {"war_context_snapshot": {"commitment_conflicts": []}}
        assert separate_peace_said_by_the_rows(w, said, "France", "Austria") is True
        assert separate_peace_said_by_the_rows(w, other, "France", "Austria") is False
        assert separate_peace_said_by_the_rows(w, none, "France", "Austria") is False
        assert separate_peace_said_by_the_rows(w, {}, "France", "Austria") is False

    def test_h_the_other_readers_one_source(self, _w19_world):
        """The wizard row's chip, the counsel's note and the rows all read
        `separate_peace_words` — the same sentence, unchanged by the fold."""
        from backend.game_logic import diplomacy as D
        from backend.game_logic.diplomatic_dialogue import separate_peace_note_text
        w = _w19_world
        words = D.separate_peace_words(w, "France", "Austria")
        assert D.separate_peace_note(w, "France", "Austria") == words["chip"] == words["display"]
        assert separate_peace_note_text(w, "France", "Austria") == f"Mark one thing, Sire: {words['display']}"

    @pytest.mark.parametrize("script,marker", [("proposal_confirm_popup.gd", "*[/color]"),
                                               ("incoming_proposal_popup.gd", "-[/color]")])
    def test_i_the_popups_print_each_consequence_once(self, script, marker):
        src = _w19_src(script)
        loop = re.search(r"for item in consequence_items:\n(.*?)\n\n", src, re.S).group(1)
        assert "printed_texts" in src
        assert 'if printed_texts.has(str(item.get("text", ""))):' in loop
        assert 'printed_texts[str(item.get("text", ""))] = true' in loop
        assert "continue" in loop and "break" not in loop
        # the guard precedes the print, and the print is the one line per item
        assert loop.index("continue") < loop.index("bbcode +=")
        assert loop.count("bbcode +=") == 1 and marker in loop


# ══════════════════════════════════════════════════════════════════════════
# S14E-X199 — the rail's chip after the mission ended
# ══════════════════════════════════════════════════════════════════════════

def _w19_chip_words(notif: dict) -> str:
    """The chip's words, as `notification_bar.gd::_mission_words` builds them
    (a mirror; the source pins below hold the `rail_words` early return)."""
    from backend.display_names import display_nation
    details = notif.get("details") or {}
    if str(details.get("rail_words") or ""):
        return str(details["rail_words"])
    court = display_nation(str(details.get("target_nation") or "")) if details.get("target_nation") else ""
    kind = ""
    title = str(notif.get("title") or "")
    if title.startswith("Talleyrand: "):
        kind = title[len("Talleyrand: "):].split(" - ")[0].strip()
    words = "Talleyrand"
    if court:
        words += " at " + court
    if kind:
        words += " — " + kind
    return words


def _w19_set_state(w, a, b, state):
    w.diplomatic_states[w._make_diplo_key(a, b)] = state
    w.invalidate_bloc_members_cache()


def _w19_set_rel(w, a, b, value):
    w.nation_relations[w._make_diplo_key(a, b)] = int(value)


def _w19_begin(w, mission_type, target, dp=10):
    """Drive the REAL `start_mission` dialogue arm (the executor writes the dict)."""
    from backend.commands.executor import CommandExecutor
    from backend.game_logic.diplomatic_dialogue import MISSION_DP_COSTS
    w.dialogue_manager.replace({
        "type": "mission", "target_nation": target, "talleyrand_text": "Very well, Sire.",
        "options": [
            {"label": "Begin mission", "description": "Start.", "action": "start_mission",
             "terms": {"mission_type": mission_type, "target_nation": target}},
            {"label": "Dismiss", "description": "Cancel.", "action": "dismiss"},
        ],
        "context": {"dp_cost_per_turn": int(MISSION_DP_COSTS[mission_type])},
        "turn_created": int(w.current_turn), "blocking": False,
    })
    w.diplomatic_points = max(int(w.diplomatic_points), dp)
    with _w19_quiet():
        out = CommandExecutor()._diplomatic.handle_diplomatic_dialogue_response(1, {"world": w})
    assert out.get("success"), out
    return w.active_diplomatic_mission


def _w19_tick(w, dp=10):
    from backend.game_logic import diplomacy as D
    w.diplomatic_points = dp
    with _w19_quiet():
        return D.process_diplomacy_turn(w)


def _w19_truce(w, relation=-60):
    """France and Austria under a truce (the replay's mission scene)."""
    _w19_set_state(w, "France", "Austria", "ARMISTICE")
    _w19_set_rel(w, "France", "Austria", relation)
    w.armistice_turns[w._make_diplo_key("France", "Austria")] = 1


def _w19_mission_rows(w) -> list:
    return [n for n in w.notifications.get_pending() if n.get("type") == "diplomatic_mission"]


_W19_ENDED = {"completed", "recalled", "collapsed", "eliminated"}


class TestS14EX199:
    """The Imperial Box rail still showed "Talleyrand at Austria — Improving
    Relations" for the whole turn after the mission ended with "Austria and
    France are at peace — Talleyrand is home." (frames 0187-0199), beside the
    top bar's "Talleyrand: Idle".

    Reproduced on the shipped board (France-Austria under a truce at -60, the
    real `start_mission` arm for Improve Relations, the pair at PEACE, one
    `process_diplomacy_turn`): the rail held ONE row — beat "completed" — whose
    only text for the chip was its title "Talleyrand: Improving Relations -
    Austria", so `_mission_words` built "Talleyrand at Austria — Improving
    Relations": word for word the standing mission's chip. (The row is the
    mission's ending notice and, like the ordinary completion's, stands until
    the player acknowledges it — `test_iq4_cabinet_visible`'s "the ended row
    survives the next advance"; the defect was that it SPOKE as a standing
    mission.)

    The fix: an ended beat's row carries `details.rail_words` ("Talleyrand
    home from Austria — mission done" / "recalled from" / "collapsed" /
    "ended"), the chip and its tooltip print them, a standing mission's chip is
    untouched. One builder (`diplomatic_dialogue.mission_rail_words`) for every
    ending — the peace (S14E-34), the lapsed/war alliance (S14E-X110), the
    ceiling, the duration, the recall, the collapse, the elimination.
    """

    def test_a_the_peace_tick_leaves_one_row_that_reads_as_ended(self, _w19_world):
        w = _w19_world
        _w19_truce(w)
        _w19_begin(w, "IMPROVE_RELATIONS", "Austria")
        running = _w19_chip_words(_w19_mission_rows(w)[0])
        assert running == "Talleyrand at Austria — Improving Relations"
        _w19_set_state(w, "France", "Austria", "PEACE")
        _w19_tick(w)
        (row,) = _w19_mission_rows(w)
        assert row["details"]["beat"] == "completed"
        assert "Austria and France are at peace — Talleyrand is home" in row["message"]
        assert row["details"]["rail_words"] == "Talleyrand home from Austria — mission done"
        assert "action_command" not in row["details"], "an ended mission offers no Recall"
        chip = _w19_chip_words(row)
        assert chip == "Talleyrand home from Austria — mission done"
        assert "Talleyrand at Austria" not in chip and "Improving Relations" not in chip

    def test_b_before_the_fix_the_ended_chip_was_the_standing_one(self, _w19_world):
        """The reproduction, kept: with no `rail_words` the chip builder reads
        the title, and the ended row's title is the running row's."""
        w = _w19_world
        _w19_truce(w)
        _w19_begin(w, "IMPROVE_RELATIONS", "Austria")
        running = dict(_w19_mission_rows(w)[0])
        _w19_set_state(w, "France", "Austria", "PEACE")
        _w19_tick(w)
        (row,) = _w19_mission_rows(w)
        assert row["title"] == running["title"] == "Talleyrand: Improving Relations - Austria"
        old = dict(row, details={k: v for k, v in row["details"].items() if k != "rail_words"})
        assert _w19_chip_words(old) == "Talleyrand at Austria — Improving Relations"

    def test_c_the_ended_row_is_not_revived_by_the_next_ticks(self, _w19_world):
        w = _w19_world
        _w19_truce(w)
        _w19_begin(w, "IMPROVE_RELATIONS", "Austria")
        _w19_set_state(w, "France", "Austria", "PEACE")
        _w19_tick(w)
        (row,) = _w19_mission_rows(w)
        for _ in range(2):
            _w19_tick(w)
        (again,) = _w19_mission_rows(w)
        assert again["id"] == row["id"] and again["details"]["beat"] in _W19_ENDED
        assert again["details"]["rail_words"] == row["details"]["rail_words"]
        assert not any(n["details"].get("beat") in ("begun", "running") for n in _w19_mission_rows(w))

    def test_d_the_lapsed_and_war_endings_read_as_ended(self, _w19_world):
        """S14E-X110's Reassure Ally endings (the alliance lapsed / war broke
        it) go through the same `record_mission_end`."""
        from backend.models.world_state import WorldState
        for state, reason in (("DEFENSIVE_ALLIANCE", "lapsed"), ("WAR", "war")):
            w = WorldState.from_dict(json.loads(json.dumps(_w19_world.to_dict(), default=str)))
            assert w.get_diplomatic_state("France", "Spain") == "ALLIANCE"
            _w19_begin(w, "REASSURE_ALLY", "Spain")
            running = _w19_chip_words(_w19_mission_rows(w)[0])
            assert running.startswith("Talleyrand at Spain")
            _w19_set_state(w, "France", "Spain", state)
            _w19_tick(w)
            (row,) = _w19_mission_rows(w)
            assert w.active_diplomatic_mission["end_reason"] == reason
            assert row["details"]["beat"] == "completed"
            assert _w19_chip_words(row) == "Talleyrand home from Spain — mission done", reason
            assert "action_command" not in row["details"]

    def test_e_a_recall_reads_as_ended_too(self, _w19_world):
        from backend.game_logic.diplomatic_dialogue import record_mission_end
        w = _w19_world
        mission = _w19_begin(w, "IMPROVE_RELATIONS", "Prussia")
        with _w19_quiet():
            record_mission_end(w, dict(mission), "recalled")
        (row,) = _w19_mission_rows(w)
        assert row["details"]["beat"] == "recalled"
        assert _w19_chip_words(row) == "Talleyrand recalled from Prussia"

    def test_f_the_words_by_beat(self):
        from backend.game_logic.diplomatic_dialogue import mission_rail_words
        assert mission_rail_words("completed", "Austria") == "Talleyrand home from Austria — mission done"
        assert mission_rail_words("recalled", "PapalStates") == "Talleyrand recalled from Papal States"
        assert mission_rail_words("collapsed", "Prussia") == "Talleyrand's mission to Prussia collapsed"
        assert mission_rail_words("eliminated", "Hanover") == "Talleyrand's mission to Hanover ended"
        for standing in ("begun", "running", "paused_transit", "paused_starved", "blowback"):
            assert mission_rail_words(standing, "Austria") == "", standing

    def test_g_a_standing_mission_keeps_its_chip_and_its_recall(self, _w19_world):
        w = _w19_world
        _w19_begin(w, "IMPROVE_RELATIONS", "Prussia")
        (row,) = _w19_mission_rows(w)
        assert "rail_words" not in row["details"]
        assert row["details"].get("action_command"), "the live mission still carries its Recall"
        assert _w19_chip_words(row) == "Talleyrand at Prussia — Improving Relations"
        _w19_tick(w)
        (running,) = _w19_mission_rows(w)
        assert "rail_words" not in running["details"]

    def test_h_the_client_prints_the_ending_words_and_the_tooltip(self):
        src = _w19_src("notification_bar.gd")
        words = _w19_func(src, "func _mission_words(notif: Dictionary) -> String:")
        assert 'str(details.get("rail_words", ""))' in words
        assert words.index('"rail_words"') < words.index('words += " at "'), (
            "the ending's words come before the standing mission's composition")
        row = _w19_func(src, "func _create_mission_row(notif: Dictionary) -> HBoxContainer:")
        assert "btn.text = _mission_words(notif)" in row
        assert 'btn.tooltip_text = str(details.get("rail_words", ""))' in row
        assert row.index("btn.text = _mission_words(notif)") < row.index("btn.tooltip_text")


