# S14E-X200 — the quotes' own two buttons
# ══════════════════════════════════════════════════════════════════════════

def _w19_popup_buttons(options: list) -> list:
    """The buttons `clarification_popup.gd::show_clarification` draws for a
    backend `options` list (a mirror: the rule the source pins below hold)."""
    labels = [str(o.get("label", "Option")) for o in options]
    carries_cancel = any(str(o.get("command", "")) == "cancel" or str(o.get("value", "")) == "cancel"
                         for o in options if isinstance(o, dict))
    return labels if carries_cancel else labels + ["Cancel Order"]


def _w19_is_quote(reply: dict) -> bool:
    return (reply.get("state") == "awaiting_clarification"
            and reply.get("type") == "clarification" and bool(reply.get("options")))


def _w19_amends_board(w):
    from backend.game_logic.diplomacy import _betrayal_key
    w.betrayal_history[_betrayal_key("France", "Prussia")] = {
        "strikes": [{"severity": "medium", "turn": 0, "episode_id": "ep_s", "decays_on_turn": 10}],
        "grievance_flags": [{"turn": 0, "episode_id": "ep_g", "grievance_type": "defensive_call_refused"}],
        "categories": ["treaty_breach", "grievance"], "last_turn": 0}
    w.nation_gold["France"], w.diplomatic_points = 1000, 4
    return w


_W19_QUOTES = (
    ("buy off Sweden", ["Buy it off", "Not now"]),
    ("sponsor Prussia against Hanover, 200 gold", ["Sponsor it", "Not now"]),
    ("guarantee Denmark", None),
    ("Talleyrand, bid for Denmark, 200 gold", None),
    ("make amends with Prussia", ["Make amends", "Not now"]),
)


class TestS14EX200:
    """The Buy Off quote (S14E-26's `_quote_instrument` on the clarification
    channel) drew a THIRD button, "Cancel Order", beside "Buy it off" and "Not
    now", with no order pending (frame 0111): `clarification_popup.gd` ALWAYS
    appended its own cancel to the backend's options.

    Reproduced on the shipped board (France 2,500g, 5 DP): `/command` "buy off
    Sweden" answered `options` = [Buy it off, Not now(command "cancel")], and
    the popup drew those two plus "Cancel Order" — the backend was right (every
    quote pins exactly two options), the third button was the client's.

    The fix, at the ONE place: the popup adds its own "Cancel Order" only when
    none of the backend's options is itself a cancel (`command` or `value`
    "cancel") — the instrument and Law quotes' "Not now", the Admiralty's
    "Stand down" and the pursuit ask's "Cancel" read as their own cancel; an
    ask that carries none (the march ask's "March (1 AP)") keeps the popup's.
    """

    @pytest.mark.parametrize("line,labels", _W19_QUOTES)
    def test_a_each_quote_is_two_buttons_and_the_second_is_its_cancel(self, _w19_boot, line, labels):
        from backend.models.world_state import WorldState
        w = WorldState.from_dict(json.loads(json.dumps(_w19_boot.to_dict(), default=str)))
        w.nation_gold["France"], w.diplomatic_points = 2500, 5
        if line.startswith("make amends"):
            _w19_amends_board(w)
        if "bid for Denmark" in line:
            w.allegiance_auctions["Denmark"] = {"opened_turn": int(w.current_turn),
                                                "resolves_turn": int(w.current_turn) + 3}
        with _w19_client(w) as client:
            reply = _w19_say(client, line)
        assert _w19_is_quote(reply), (line, reply.get("message"))
        options = reply["options"]
        assert len(options) == 2, [o["label"] for o in options]
        if labels:
            assert [o["label"] for o in options] == labels
        assert options[1]["command"] == "cancel" and "Cancel Order" not in [o["label"] for o in options]
        # what the player sees: the quote's own two buttons, nothing added
        buttons = _w19_popup_buttons(options)
        assert buttons == [o["label"] for o in options] and "Cancel Order" not in buttons

    def test_b_an_ask_with_no_cancel_keeps_the_popups_own(self):
        march = [{"label": "March (1 AP)", "command": "Soult, march to Vienna"}]
        assert _w19_popup_buttons(march) == ["March (1 AP)", "Cancel Order"]
        pursuit = [{"label": "Pursue Mack", "value": "specify", "target": "Mack", "command": "x"},
                   {"label": "Cancel", "value": "cancel"}]
        assert _w19_popup_buttons(pursuit) == ["Pursue Mack", "Cancel"]
        assert _w19_popup_buttons([]) == ["Cancel Order"]

    def test_c_the_popup_adds_its_cancel_only_when_the_options_carry_none(self):
        src = _w19_src("clarification_popup.gd")
        show = _w19_func(src, "func show_clarification(data: Dictionary):")
        assert "if not _options_carry_cancel(options):" in show
        guarded = show[show.index("if not _options_carry_cancel(options):"):]
        assert guarded.index('_create_button("Cancel Order", {})') > 0
        assert guarded.index('_create_button("Cancel Order", {})') < guarded.index("show()")
        # the fallback (no options) still reaches the popup's own cancel
        assert 'var options = data.get("options", [])' in show
        helper = _w19_func(src, "func _options_carry_cancel(options: Array) -> bool:")
        assert 'str(option.get("command", "")) == "cancel"' in helper
        assert 'str(option.get("value", "")) == "cancel"' in helper
        assert "return true" in helper and helper.rstrip().endswith("return false")

    def test_d_every_backend_refusal_option_is_a_cancel_the_popup_reads(self):
        """The class: each quote/ask that offers its own refusal ("Not now",
        "Stand down") words it with `command` "cancel" — the key the popup
        reads — so none of them draws the stray button."""
        for rel in ("backend/commands/diplomatic_executor.py", "backend/commands/reforms_executor.py",
                    "backend/commands/naval_executor.py"):
            src = (_W19_ROOT / rel).read_text(encoding="utf-8")
            refusals = re.findall(r'\{"label": "(Not now|Stand down)",\s*"([a-z]+)": "([a-z]+)"', src)
            assert refusals, rel
            for label, key, value in refusals:
                assert (key, value) == ("command", "cancel"), (rel, label, key, value)
        strategic = (_W19_ROOT / "backend/commands/strategic_executor.py").read_text(encoding="utf-8")
        assert 'options.append({"label": "Cancel", "value": "cancel"})' in strategic


