def _w20_printed(dialogue: dict) -> list:
    """Every line the confirm popup prints under Political Consequences: the
    dialogue's `warnings`, then the snapshot's tier warnings, fallout and
    commitment conflicts (`proposal_confirm_popup.gd`'s four loops), each text
    once (the popup's own `printed_texts` guard)."""
    snap = dialogue.get("war_context_snapshot") or {}
    lines = []
    for w in dialogue.get("warnings") or []:
        lines.append(str(w.get("text", w)) if isinstance(w, dict) else str(w))
    for w in snap.get("tier_mismatch_warnings") or []:
        lines.append(str(w.get("display", w.get("text", w))) if isinstance(w, dict) else str(w))
    for w in snap.get("fallout_warnings") or []:
        lines.append(str(w.get("display", w)) if isinstance(w, dict) else str(w))
    for c in snap.get("commitment_conflicts") or []:
        lines.append(str(c.get("display", c)) if isinstance(c, dict) else str(c))
    return lines


