# S14E-X205 — the cross-bloc friction, once
# ══════════════════════════════════════════════════════════════════════════

_W20_BLOC_WORDS = ("cross-bloc", "sits outside your bloc", "resisting your")


class TestS14EX205:
    """The hegemony warning ("Britain's court sees the ... consolidating across
    Europe and will resist a cross-bloc agreement." - the dialogue's `warnings`)
    and the snapshot's `bloc_opposition` INFO row ("Britain sits outside your
    bloc. Peace normalizes relations with a nation resisting your European
    influence.") stated the same cross-bloc friction in one consequence list,
    in two voices: both gates are the same pair of facts (the hegemon bloc at
    30%+ of Europe, the proposer inside it, the court outside).

    Reproduced on the shipped board: `generate_dialogue("proposal_confirm",
    {Austria, peace})` carried the hegemony warning in `warnings` AND the
    `bloc_opposition` row in `commitment_conflicts` - two printed lines about
    one fact; on the fixture world (Berlin Alignment) the same pair at band 3.

    The fix (`diplomatic_dialogue.fold_hegemony_warning_into_bloc_row`, at the
    confirm's builder): the warning is the sentence with the band's strength,
    the bloc's name and, for the hegemon, the lever; the row carries the share
    (`detail.bloc_share`, a whole percent). The row inherits the warning's
    sentence and its strength (critical / high -> a WARNING row, the rest INFO)
    and the warning leaves `warnings`. The incoming letter builds no hegemony
    warning and keeps the row's own words.
    """

    def test_a_the_shipped_boards_peace_says_the_friction_once(self, _w20_world):
        dialogue = _w20_open_peace(_w20_world, "Austria")
        lines = _w20_printed(dialogue)
        bloc = [ln for ln in lines if any(word in ln for word in _W20_BLOC_WORDS)]
        assert len(bloc) == 1, lines
        assert "will resist a cross-bloc agreement" in bloc[0]
        assert "sits outside your bloc" not in " ".join(lines)
        assert not [w for w in dialogue.get("warnings") or []
                    if isinstance(w, dict) and w.get("category") == "hegemony"]

    def test_b_the_row_keeps_the_figure_and_the_sentence_keeps_the_lever(self, _w20_world):
        from backend.game_logic.diplomacy import build_proposal_commitment_warnings
        w = _w20_world
        dialogue = _w20_open_peace(w, "Austria")
        row = next(c for c in dialogue["war_context_snapshot"]["commitment_conflicts"]
                   if c["conflict_type"] == "bloc_opposition")
        share = row["detail"]["bloc_share"]
        assert isinstance(share, int) and 30 <= share <= 100, "the share rides the row"
        with _w20_quiet():
            heg = next(x for x in build_proposal_commitment_warnings(
                w, proposer_nation="France", target_nation="Austria", proposal_type="peace")
                if x["category"] == "hegemony")
        assert row["display"] == heg["text"], "the row IS the warning's sentence"
        assert len(row["display"]) > 100, "the lever (the counter-play hint) is in it"

    def test_c_the_fixture_worlds_band_three_reads_as_a_red_row(self):
        dialogue = _w20_enrich(_w20_left_ally_fixture())
        lines = _w20_printed(dialogue)
        bloc = [ln for ln in lines if any(word in ln for word in _W20_BLOC_WORDS)]
        assert bloc == ["Britain treats Berlin Alignment as a continental emergency; "
                        "cross-bloc agreements have grown nearly unreachable."], lines
        row = next(c for c in dialogue["war_context_snapshot"]["commitment_conflicts"]
                   if c["conflict_type"] == "bloc_opposition")
        assert row["severity"] == "WARNING"
        assert "warnings" not in dialogue or not dialogue["warnings"]

    @pytest.mark.parametrize("severity,expected", [
        ("critical", "WARNING"), ("high", "WARNING"), ("medium", "INFO"), ("low", "INFO")])
    def test_d_the_warnings_strength_is_the_rows(self, severity, expected):
        from backend.game_logic.diplomatic_dialogue import fold_hegemony_warning_into_bloc_row
        dialogue = {"war_context_snapshot": {"commitment_conflicts": [
            {"conflict_type": "paradox", "affected_entity": "Spain", "display": "x", "severity": "WARNING"},
            {"conflict_type": "bloc_opposition", "affected_entity": "Austria",
             "display": "Austria sits outside your bloc.", "severity": "INFO",
             "detail": {"bloc_share": 45}}]}}
        other = {"severity": "medium", "category": "betrayal", "text": "Austria remembers."}
        heg = {"severity": severity, "category": "hegemony", "text": "Austria hardens."}
        left = fold_hegemony_warning_into_bloc_row(dialogue, [other, heg])
        assert left == [other], "the other warnings stay, in order"
        row = dialogue["war_context_snapshot"]["commitment_conflicts"][1]
        assert (row["display"], row["severity"]) == ("Austria hardens.", expected)
        assert row["detail"] == {"bloc_share": 45}
        assert dialogue["war_context_snapshot"]["commitment_conflicts"][0]["display"] == "x"

    def test_e_without_a_bloc_row_the_warning_stays(self):
        """A proposal that is not a peace (no snapshot), or a pair with no
        bloc_opposition row: the hegemony warning prints as it did."""
        from backend.game_logic.diplomatic_dialogue import fold_hegemony_warning_into_bloc_row
        heg = {"severity": "high", "category": "hegemony", "text": "Austria hardens."}
        assert fold_hegemony_warning_into_bloc_row({}, [heg]) == [heg]
        no_row = {"war_context_snapshot": {"commitment_conflicts": [
            {"conflict_type": "paradox", "affected_entity": "Spain", "display": "x"}]}}
        assert fold_hegemony_warning_into_bloc_row(no_row, [heg]) == [heg]
        assert fold_hegemony_warning_into_bloc_row({"war_context_snapshot": {}}, [heg]) == [heg]
        assert fold_hegemony_warning_into_bloc_row({}, []) == []
        assert fold_hegemony_warning_into_bloc_row({}, None) is None

    def test_f_a_non_peace_proposal_keeps_its_hegemony_warning(self, _w20_world):
        from backend.game_logic.diplomatic_dialogue import generate_dialogue
        with _w20_quiet():
            dialogue = generate_dialogue(
                "proposal_confirm", {"target_nation": "Austria", "proposal_type": "open_borders"},
                _w20_world)
        cats = [w.get("category") for w in dialogue.get("warnings") or [] if isinstance(w, dict)]
        assert "hegemony" in cats

    def test_g_the_incoming_letter_keeps_the_rows_own_words(self, _w20_world):
        from backend.game_logic.mailbox_payloads import build_pending_envoy_popup_from_terms
        with _w20_quiet():
            payload = build_pending_envoy_popup_from_terms(
                _w20_world, nation="Austria",
                terms={"type": "peace", "proposer_nation": "Austria",
                       "target_nation": "France", "sweeteners": [], "demands": []})
        row = next(c for c in payload["commitment_conflicts"]
                   if c["conflict_type"] == "bloc_opposition")
        assert row["display"].startswith("Austria sits outside your bloc.")
        assert row["severity"] == "INFO"

    def test_h_the_base_builders_are_untouched(self):
        """Both producers still say what they said (their own tests read them);
        only the confirm's assembly folds them."""
        from backend.game_logic.diplomacy import (
            build_proposal_commitment_warnings, get_peace_commitment_conflicts)
        w = _w20_left_ally_fixture()
        with _w20_quiet():
            warns = build_proposal_commitment_warnings(
                w, proposer_nation="France", target_nation="Britain", proposal_type="peace")
            rows = get_peace_commitment_conflicts(w, "France", "Britain", [])
        assert [x["category"] for x in warns] == ["hegemony"]
        row = next(c for c in rows if c["conflict_type"] == "bloc_opposition")
        assert row["severity"] == "INFO" and row["display"].startswith("Britain sits outside your bloc.")


