# S14E-X206 — the truce keeps the drawn battle too
# ══════════════════════════════════════════════════════════════════════════

class TestS14EX206:
    """The truce rows' `keeps.battles` (and the "The ledger stands: ... (N
    battles, M decisives kept)" line the armistice popup, the incoming letter,
    the wizard row, the counsel, the dispatch and the war HUD's armistice card
    all read) counted `battle_records` only - the winner-only list - so a
    stalemate fought before the truce was uncounted there while the war title
    and the preview's Battles line (S14E-X201) counted it.

    Reproduced on the shipped board: one drawn battle between France and
    Austria (`record_drawn_battle`), then `truce_words` -> `keeps.battles` 0
    and the line "(0 battles, 0 decisives kept)"; the armistice card on the HUD
    `battles_fought` 0.

    The fix: `diplomacy.truce_words` adds the pair ledger's `drawn` list (the
    same read `war_title._record_parts` makes), and says it in the line with
    the war title's own phrase (`war_title.drawn_suffix`). The settlement
    ratifier's battle read (`settlement_ratify._capture_pair_pre_cleanup_war_data`)
    counts casualties, not battles, and needs no change.
    """

    def _truce(self, w, drawn=1):
        for _ in range(drawn):
            w.record_drawn_battle("France", "Austria", 7673, 6020)
        from backend.game_logic.diplomacy import truce_words
        with _w20_quiet():
            return truce_words(w, "France", "Austria")

    def test_a_the_truce_keeps_the_stalemate(self, _w20_world):
        words = self._truce(_w20_world)
        assert words["keeps"]["battles"] == 1
        assert "(1 battle, a stalemate, 0 decisives kept)" in words["keeps_line"]

    def test_b_a_board_without_a_draw_reads_as_before(self, _w20_world):
        from backend.game_logic.diplomacy import truce_words
        with _w20_quiet():
            words = truce_words(_w20_world, "France", "Austria")
        assert words["keeps"]["battles"] == 0
        assert "(0 battles, 0 decisives kept)" in words["keeps_line"]

    def test_c_a_won_battle_and_a_draw_are_both_kept(self, _w20_world):
        w = _w20_world
        key = w._make_diplo_key("France", "Austria")
        w.battle_records[key] = [{
            "turn": int(w.current_turn), "winner": "France", "attacker": "France",
            "defender": "Austria", "attacker_casualties": 900, "defender_casualties": 4000,
            "location": "Swabia", "battle_name": ""}]
        words = self._truce(w)
        assert words["keeps"]["battles"] == 2
        assert "(2 battles, 1 drawn, 0 decisives kept)" in words["keeps_line"]
        w.battle_records.clear()
        w.record_drawn_battle("France", "Austria", 3000, 3000)
        from backend.game_logic.diplomacy import truce_words
        with _w20_quiet():
            assert "(2 battles, all drawn, 0 decisives kept)" in truce_words(
                w, "France", "Austria")["keeps_line"]

    def test_d_the_preview_the_running_truce_and_the_hud_card_agree(self, _w20_world):
        """Shown == kept: the armistice preview's mechanics, the running truce's
        words and the war HUD's armistice card quote one count, after the truce
        has been signed (the ledger survives it, PC-R2)."""
        from backend.game_logic.diplomacy import build_war_context_snapshot, truce_words
        from backend.game_logic.war_status import build_active_wars
        w = _w20_world
        w.record_drawn_battle("France", "Austria", 7673, 6020)
        with _w20_quiet():
            proposed = build_war_context_snapshot(w, "France", "Austria", "armistice")
        assert proposed["armistice_mechanics"]["keeps"]["battles"] == 1
        _w20_state(w, "France", "Austria", "ARMISTICE")
        with _w20_quiet():
            running = truce_words(w, "France", "Austria")
            wars = build_active_wars(w)["wars"]
        assert running["keeps"]["battles"] == 1
        card = next(r for r in wars if r.get("status") == "armistice" and r.get("opponent") == "Austria")
        assert card["battles_fought"] == 1 and isinstance(card["battles_fought"], int)
        assert "(1 battle, a stalemate," in card["armistice_keeps_line"]

    def test_e_the_one_phrase_the_title_and_the_truce_share(self):
        from backend.game_logic.war_title import drawn_suffix
        assert drawn_suffix(1, 1) == " (a stalemate)"
        assert drawn_suffix(2, 2) == " (all drawn)"
        assert drawn_suffix(3, 2) == " (2 drawn)"
        assert drawn_suffix(3, 0) == ""

    def test_f_the_war_title_reads_as_it_did(self, _w20_world):
        """The lift left the title's words untouched (X201's pins hold)."""
        from backend.game_logic.war_title import war_title_for_pair
        w = _w20_world
        w.record_drawn_battle("France", "Austria", 7673, 6020)
        assert war_title_for_pair(w, "France", "Austria")["line"] == (
            "The War with the Third Coalition: 1 battle fought (a stalemate); "
            "no ground taken yet on either side.")

    def test_g_a_pair_at_peace_keeps_nothing(self, _w20_world):
        from backend.game_logic.diplomacy import truce_words
        w = _w20_world
        w.record_drawn_battle("France", "Prussia", 5000, 5000)   # not at war: nothing stamped
        with _w20_quiet():
            assert truce_words(w, "France", "Prussia")["keeps"]["battles"] == 0


# ══════════════════════════════════════════════════════════════════════════
# S14E-X207 — "2 resources still in use at exit"
# ══════════════════════════════════════════════════════════════════════════

_W20_RELEASED = {
    # file -> (static var, the release line it must have)
    "utils.gd": ("_garamond_faces", "\t_garamond_faces.clear()"),
    "portrait_locket.gd": ("_shader", "\t_shader = null"),
    "war_table_piece.gd": ("_texture_cache", "\t_texture_cache.clear()"),
}


class TestS14EX207:
    """The replay's engine log ended with its last plain `ERROR:` line, "2
    resources still in use at exit" (X202 fixed the other twenty): the game's
    STATIC caches hold Resources - `utils.gd::_garamond_faces` (the theme's own
    path-loaded fonts, captured once so the plain body face can be switched
    back), `portrait_locket.gd::_shader`, `war_table_piece.gd::_texture_cache`
    (path-loaded textures) - and a static variable lives on the script, which
    Godot 4.4 frees AFTER its resource cache's own teardown check.

    The fix: each static class gets a `release_static_caches()` that empties its
    cache, and `AudioManager._exit_tree` calls the three. AudioManager is the one
    node that lives from the first scene to the last (a child of the root, made
    on first use, never freed by a scene change), so its exit IS the game's exit
    on every road - the window's close, `get_tree().quit()` from the menu and
    the pause menu, the instrument's quit - and it is NEVER an exit of a scene:
    clearing `_garamond_faces` on a scene change would make the next
    `apply_body_font` capture the PLAIN faces as the July ones.

    Source pins only (no Godot here): the headless parse harness the orchestrator
    runs prints the same line on exit if it still stands - the harness must
    confirm.
    """

    @pytest.mark.parametrize("name", sorted(_W20_RELEASED))
    def test_a_each_static_cache_is_released(self, name):
        var, line = _W20_RELEASED[name]
        src = _w20_src(name)
        body = _w20_block(src, "static func release_static_caches() -> void:")
        assert body == [line], body
        assert re.search(rf"^static var {var}\b", src, re.M), f"{var} still declared in {name}"

    def test_b_the_exit_hook_is_the_persistent_nodes_exit_tree(self):
        src = _w20_src("audio_manager.gd")
        body = _w20_func(src, "func _exit_tree() -> void:")
        for call in ("\tUtils.release_static_caches()",
                     "\tPortraitLocket.release_static_caches()",
                     "\tWarTablePiece.release_static_caches()"):
            assert call in body.split("\n"), call
        code = "\n".join(ln for ln in body.split("\n") if not ln.strip().startswith("#"))
        assert "get_tree" not in code and "queue_free" not in code, "teardown touches no tree"
        # the node is a child of the ROOT, made on first use - a scene change keeps it
        inst = _w20_func(src, "static func _inst() -> AudioManager:")
        assert "root.add_child(_instance)" in inst

    def test_c_it_is_the_games_exit_never_a_scenes(self):
        """The release is called from AudioManager only: not from a scene's
        `_exit_tree` / `_notification`, which a scene change would run."""
        callers = []
        for folder in (_W20_SCRIPTS, _W20_SCENES):
            for path in folder.glob("*.gd"):
                text = path.read_text(encoding="utf-8")
                for match in re.finditer(r"\.release_static_caches\(\)", text):
                    callers.append(path.name)
        assert sorted(callers) == ["audio_manager.gd"] * 3, callers
        for name in ("main.gd", "main_menu.gd", "pause_menu.gd", "top_bar.gd"):
            assert "release_static_caches" not in _w20_src(name), name

    def test_d_every_resource_holding_static_is_in_the_release(self):
        """The class: a `static var` that is a cache or holds a Resource type
        must have a release line, or be a known non-Resource cache. A new one
        fails here, so its author decides."""
        non_resource = {
            "_flag_path_cache", "_flag_aspect_cache",      # path strings, aspect floats
            "_portrait_paths", "_bitmap_load_error_latch",  # path strings, a latch
            "_text_size_bases",                             # [type, item, size] numbers
        }
        released = {var for var, _ in _W20_RELEASED.values()}
        resource_types = r"(Shader|Texture2D|Texture|Font|FontFile|FontVariation|Theme|Resource|" \
                         r"PackedScene|AudioStream|StyleBox|Material|Image|Mesh)"
        found = set()
        for folder in (_W20_SCRIPTS, _W20_SCENES):
            for path in sorted(folder.glob("*.gd")):
                for line in path.read_text(encoding="utf-8").splitlines():
                    m = re.match(r"^static var (\w+)\s*(?::\s*([\w\[\], ]*?))?\s*(?:=|$)", line)
                    if not m:
                        continue
                    name, typ = m.group(1), m.group(2) or ""
                    if (re.fullmatch(resource_types, typ.strip())
                            or "cache" in name or "faces" in name or "shader" in name):
                        found.add(name)
        assert found - non_resource == released, found

    def test_e_new_functions_are_tab_indented(self):
        for name in sorted(_W20_RELEASED) + ["audio_manager.gd"]:
            src = _w20_src(name)
            header = ("func _exit_tree() -> void:" if name == "audio_manager.gd"
                      else "static func release_static_caches() -> void:")
            code = _w20_block(src, header)
            assert code and all(ln.startswith("\t") and not ln.startswith(" ") for ln in code), (name, code)

    def test_f_the_font_capture_is_still_guarded_on_empty(self):
        """The release is safe at exit only because nothing after it re-reads
        the faces: the one reader recaptures when empty, and runs on a body-font
        setting change, never at teardown."""
        body = _w20_func(_w20_src("utils.gd"), "static func apply_body_font() -> void:")
        assert "if _garamond_faces.is_empty():" in body


