def _w21_left_ally_fixture():
    """France at war with Britain, Prussia allied to France and at war with
    Britain on her own account (France does not lead her war): LEFT FIGHTING."""
    from backend.models.world_state import WorldState
    w = WorldState()
    _w21_state(w, "France", "Britain", "WAR")
    _w21_state(w, "France", "Prussia", "ALLIANCE")
    _w21_state(w, "Prussia", "Britain", "WAR")
    return w


def _w21_draft(demands=(), sweeteners=(), clauses=()):
    return {"type": "peace", "proposal_type": "peace",
            "sweeteners": [dict(s) for s in sweeteners],
            "demands": [dict(d) for d in demands],
            "clauses": list(clauses)}


def _w21_paradox(snapshot, ally="Prussia"):
    (row,) = [c for c in snapshot["commitment_conflicts"]
              if c["conflict_type"] == "paradox" and c["affected_entity"] == ally]
    return row


def _w21_snapshot(w, terms, court="Britain", **kw):
    from backend.game_logic.diplomacy import build_war_context_snapshot
    with _w21_quiet():
        return build_war_context_snapshot(w, "France", court, "peace", terms=terms, **kw)


def _w21_ratify_drop(w, proposal, ally="Prussia", start=60, court="Britain"):
    """Sign the proposal through the REAL ratifier and return the ally's
    relation change (what the signing applied)."""
    key = w._make_diplo_key("France", ally)
    w.nation_relations[key] = start
    w.nation_gold[court] = 5000
    with _w21_quiet():
        result = w._ratify_treaty(proposal)
    assert isinstance(result, dict) and result.get("type") == "diplomatic_treaty_signed", result
    assert w.get_diplomatic_state("France", court) == "PEACE"
    return w.nation_relations[key] - start


